// PHP ordered hash map
use crate::value::{Value, PStr};
use std::rc::Rc;

#[derive(Clone, Debug)]
pub enum Key {
    Int(i64),
    Str(PStr),
}

impl PartialEq for Key {
    fn eq(&self, other: &Key) -> bool {
        match (self, other) {
            (Key::Int(a), Key::Int(b)) => a == b,
            (Key::Str(a), Key::Str(b)) => Rc::ptr_eq(a, b) || a.as_slice() == b.as_slice(),
            _ => false,
        }
    }
}
impl Eq for Key {}

impl Key {
    pub fn to_value(&self) -> Value {
        match self {
            Key::Int(i) => Value::Int(*i),
            Key::Str(s) => Value::Str(s.clone()),
        }
    }
    pub fn as_bytes(&self) -> Vec<u8> {
        match self {
            Key::Int(i) => i.to_string().into_bytes(),
            Key::Str(s) => s.to_vec(),
        }
    }
    pub fn from_str_bytes(b: &[u8]) -> Key {
        if let Some(i) = str_to_int_key(b) {
            Key::Int(i)
        } else {
            Key::Str(Rc::new(b.to_vec()))
        }
    }
    pub fn from_pstr(s: &PStr) -> Key {
        if let Some(i) = str_to_int_key(s) {
            Key::Int(i)
        } else {
            Key::Str(s.clone())
        }
    }
}

/// canonical decimal integer string -> int key
pub fn str_to_int_key(b: &[u8]) -> Option<i64> {
    let n = b.len();
    if n == 0 || n > 20 {
        return None;
    }
    let (neg, digits) = if b[0] == b'-' { (true, &b[1..]) } else { (false, b) };
    if digits.is_empty() {
        return None;
    }
    if digits[0] == b'0' && (digits.len() > 1 || neg) {
        return None;
    }
    let mut v: i64 = 0;
    for &c in digits {
        if !(b'0'..=b'9').contains(&c) {
            return None;
        }
        let d = (c - b'0') as i64;
        if neg {
            v = v.checked_mul(10)?.checked_sub(d)?;
        } else {
            v = v.checked_mul(10)?.checked_add(d)?;
        }
    }
    Some(v)
}

#[inline]
fn hash_int(i: i64) -> u32 {
    let x = (i as u64).wrapping_mul(0x9E3779B97F4A7C15);
    (x >> 32) as u32
}

#[inline]
pub fn hash_bytes(b: &[u8]) -> u32 {
    // FNV-1a style 64-bit then fold
    let mut h: u64 = 0xcbf29ce484222325;
    let mut chunks = b.chunks_exact(8);
    for c in &mut chunks {
        let w = u64::from_le_bytes([c[0], c[1], c[2], c[3], c[4], c[5], c[6], c[7]]);
        h = (h ^ w).wrapping_mul(0x100000001b3).rotate_left(29);
    }
    for &c in chunks.remainder() {
        h = (h ^ c as u64).wrapping_mul(0x100000001b3);
    }
    h = h.wrapping_mul(0x9E3779B97F4A7C15);
    (h >> 32) as u32
}

#[inline]
fn hash_key(k: &Key) -> u32 {
    match k {
        Key::Int(i) => hash_int(*i),
        Key::Str(s) => hash_bytes(s),
    }
}

const EMPTY: u32 = u32::MAX;

#[derive(Clone)]
pub struct Bucket {
    pub key: Key,
    pub val: Value, // Value::Undef => deleted
    next: u32,
}

#[derive(Clone)]
pub struct PArray {
    entries: Vec<Bucket>,
    table: Vec<u32>, // empty => packed mode
    count: usize,
    pub next_free: i64,
    pub iter_pos: usize, // internal pointer (entry index)
    deleted: usize,
}

impl Default for PArray {
    fn default() -> Self {
        PArray::new()
    }
}

impl PArray {
    pub fn new() -> PArray {
        PArray { entries: Vec::new(), table: Vec::new(), count: 0, next_free: 0, iter_pos: 0, deleted: 0 }
    }
    pub fn with_capacity(n: usize) -> PArray {
        PArray { entries: Vec::with_capacity(n), table: Vec::new(), count: 0, next_free: 0, iter_pos: 0, deleted: 0 }
    }
    pub fn from_values(v: Vec<Value>) -> PArray {
        let n = v.len();
        let entries: Vec<Bucket> = v
            .into_iter()
            .enumerate()
            .map(|(i, val)| Bucket { key: Key::Int(i as i64), val, next: EMPTY })
            .collect();
        PArray { entries, table: Vec::new(), count: n, next_free: n as i64, iter_pos: 0, deleted: 0 }
    }
    #[inline]
    pub fn len(&self) -> usize {
        self.count
    }
    #[inline]
    pub fn is_empty(&self) -> bool {
        self.count == 0
    }
    #[inline]
    fn is_packed(&self) -> bool {
        self.table.is_empty()
    }

    pub fn is_list(&self) -> bool {
        if self.is_packed() {
            return true;
        }
        let mut i = 0i64;
        for b in self.entries.iter() {
            if let Value::Undef = b.val {
                continue;
            }
            match b.key {
                Key::Int(k) if k == i => {}
                _ => return false,
            }
            i += 1;
        }
        true
    }

    fn build_table(&mut self, min: usize) {
        let mut size = 8usize;
        while size < min * 2 {
            size <<= 1;
        }
        // compact if many deleted
        if self.deleted > 0 {
            self.compact();
        }
        self.table = vec![EMPTY; size];
        let mask = (size - 1) as u32;
        for (i, b) in self.entries.iter_mut().enumerate() {
            let h = hash_key(&b.key) & mask;
            b.next = self.table[h as usize];
            self.table[h as usize] = i as u32;
        }
    }

    fn compact(&mut self) {
        // remove deleted entries, adjust iter_pos
        let mut new_pos = None;
        let mut j = 0usize;
        let old_iter = self.iter_pos;
        let mut out: Vec<Bucket> = Vec::with_capacity(self.count);
        for (i, b) in std::mem::take(&mut self.entries).into_iter().enumerate() {
            if i == old_iter && new_pos.is_none() {
                new_pos = Some(j);
            }
            if let Value::Undef = b.val {
                continue;
            }
            out.push(b);
            j += 1;
        }
        self.entries = out;
        self.iter_pos = new_pos.unwrap_or(j);
        self.deleted = 0;
    }

    fn to_hash(&mut self) {
        if self.is_packed() {
            let n = self.entries.len().max(4);
            self.build_table(n);
        }
    }

    #[inline]
    fn find_index(&self, k: &Key) -> Option<usize> {
        if self.is_packed() {
            if let Key::Int(i) = k {
                let i = *i;
                if i >= 0 && (i as usize) < self.entries.len() {
                    let idx = i as usize;
                    if !matches!(self.entries[idx].val, Value::Undef) {
                        return Some(idx);
                    }
                }
            }
            return None;
        }
        let mask = (self.table.len() - 1) as u32;
        let mut i = self.table[(hash_key(k) & mask) as usize];
        while i != EMPTY {
            let b = &self.entries[i as usize];
            if b.key == *k {
                return Some(i as usize);
            }
            i = b.next;
        }
        None
    }

    #[inline]
    pub fn get(&self, k: &Key) -> Option<&Value> {
        self.find_index(k).map(|i| &self.entries[i].val)
    }
    #[inline]
    pub fn get_mut(&mut self, k: &Key) -> Option<&mut Value> {
        match self.find_index(k) {
            Some(i) => Some(&mut self.entries[i].val),
            None => None,
        }
    }
    pub fn get_int(&self, i: i64) -> Option<&Value> {
        self.get(&Key::Int(i))
    }
    pub fn get_str(&self, s: &[u8]) -> Option<&Value> {
        self.get(&Key::from_str_bytes(s))
    }
    pub fn contains_key(&self, k: &Key) -> bool {
        self.find_index(k).is_some()
    }

    fn insert_new(&mut self, k: Key, v: Value) -> usize {
        if let Key::Int(i) = k {
            if i >= self.next_free {
                self.next_free = if i == i64::MAX { i } else { i + 1 };
            }
        }
        if self.is_packed() {
            if let Key::Int(i) = k {
                if i >= 0 && i as usize == self.entries.len() && self.deleted == 0 {
                    self.entries.push(Bucket { key: k, val: v, next: EMPTY });
                    self.count += 1;
                    return self.entries.len() - 1;
                }
            }
            self.to_hash();
        }
        if self.entries.len() + 1 > self.table.len() {
            let need = self.count + 1;
            self.build_table(need);
        }
        let mask = (self.table.len() - 1) as u32;
        let h = (hash_key(&k) & mask) as usize;
        let idx = self.entries.len();
        self.entries.push(Bucket { key: k, val: v, next: self.table[h] });
        self.table[h] = idx as u32;
        self.count += 1;
        idx
    }

    /// set value (insert or overwrite)
    pub fn set(&mut self, k: Key, v: Value) {
        if let Some(i) = self.find_index(&k) {
            self.entries[i].val = v;
        } else {
            self.insert_new(k, v);
        }
    }
    pub fn set_int(&mut self, i: i64, v: Value) {
        self.set(Key::Int(i), v)
    }
    pub fn set_str(&mut self, s: &[u8], v: Value) {
        self.set(Key::from_str_bytes(s), v)
    }
    /// returns mutable ref to entry, inserting Null if absent
    pub fn entry_mut(&mut self, k: Key) -> &mut Value {
        let i = match self.find_index(&k) {
            Some(i) => i,
            None => self.insert_new(k, Value::Null),
        };
        &mut self.entries[i].val
    }
    /// like entry_mut but tells whether it was inserted
    pub fn entry_mut_ins(&mut self, k: Key) -> (&mut Value, bool) {
        match self.find_index(&k) {
            Some(i) => (&mut self.entries[i].val, false),
            None => {
                let i = self.insert_new(k, Value::Null);
                (&mut self.entries[i].val, true)
            }
        }
    }
    /// append; returns false if next index overflowed
    pub fn push(&mut self, v: Value) -> bool {
        let k = self.next_free;
        if k == i64::MAX && self.contains_key(&Key::Int(k)) {
            return false;
        }
        if self.count > 0 || k > 0 {
            if self.contains_key(&Key::Int(k)) {
                return false;
            }
        }
        self.insert_new(Key::Int(k), v);
        if k == i64::MAX {
            // mark as full
        }
        true
    }
    pub fn push_mut(&mut self) -> Option<&mut Value> {
        let k = self.next_free;
        if self.contains_key(&Key::Int(k)) {
            return None;
        }
        let i = self.insert_new(Key::Int(k), Value::Null);
        Some(&mut self.entries[i].val)
    }

    pub fn remove(&mut self, k: &Key) -> Option<Value> {
        let idx = self.find_index(k)?;
        if self.is_packed() {
            if idx == self.entries.len() - 1 {
                let b = self.entries.pop().unwrap();
                self.count -= 1;
                return Some(b.val);
            }
            self.to_hash();
        }
        // unlink
        let mask = (self.table.len() - 1) as u32;
        let h = (hash_key(k) & mask) as usize;
        let mut cur = self.table[h];
        let mut prev = EMPTY;
        while cur != EMPTY {
            if cur as usize == idx {
                let nx = self.entries[idx].next;
                if prev == EMPTY {
                    self.table[h] = nx;
                } else {
                    self.entries[prev as usize].next = nx;
                }
                break;
            }
            prev = cur;
            cur = self.entries[cur as usize].next;
        }
        let v = std::mem::replace(&mut self.entries[idx].val, Value::Undef);
        self.count -= 1;
        self.deleted += 1;
        // trailing deleted entries can be trimmed
        if idx == self.entries.len() - 1 {
            // keep simple
        }
        Some(v)
    }

    pub fn clear(&mut self) {
        self.entries.clear();
        self.table.clear();
        self.count = 0;
        self.next_free = 0;
        self.iter_pos = 0;
        self.deleted = 0;
    }

    pub fn iter(&self) -> ArrIter<'_> {
        ArrIter { arr: self, pos: 0 }
    }
    pub fn iter_mut(&mut self) -> impl Iterator<Item = (&Key, &mut Value)> {
        self.entries.iter_mut().filter(|b| !matches!(b.val, Value::Undef)).map(|b| (&b.key, &mut b.val))
    }
    pub fn keys(&self) -> impl Iterator<Item = &Key> {
        self.iter().map(|(k, _)| k)
    }
    pub fn values(&self) -> impl Iterator<Item = &Value> {
        self.iter().map(|(_, v)| v)
    }

    // position based iteration (for foreach & internal pointer)
    pub fn raw_len(&self) -> usize {
        self.entries.len()
    }
    /// first valid position >= pos
    pub fn next_valid(&self, mut pos: usize) -> Option<usize> {
        while pos < self.entries.len() {
            if !matches!(self.entries[pos].val, Value::Undef) {
                return Some(pos);
            }
            pos += 1;
        }
        None
    }
    pub fn prev_valid(&self, pos: usize) -> Option<usize> {
        let mut p = pos;
        while p > 0 {
            p -= 1;
            if !matches!(self.entries[p].val, Value::Undef) {
                return Some(p);
            }
        }
        None
    }
    pub fn entry_at(&self, pos: usize) -> Option<(&Key, &Value)> {
        let b = self.entries.get(pos)?;
        if matches!(b.val, Value::Undef) {
            None
        } else {
            Some((&b.key, &b.val))
        }
    }
    pub fn entry_at_mut(&mut self, pos: usize) -> Option<(&Key, &mut Value)> {
        let b = self.entries.get_mut(pos)?;
        if matches!(b.val, Value::Undef) {
            None
        } else {
            Some((&b.key, &mut b.val))
        }
    }
    pub fn first(&self) -> Option<(&Key, &Value)> {
        self.next_valid(0).and_then(|p| self.entry_at(p))
    }
    pub fn last(&self) -> Option<(&Key, &Value)> {
        self.prev_valid(self.entries.len()).and_then(|p| self.entry_at(p))
    }
    pub fn pop(&mut self) -> Option<(Key, Value)> {
        let p = self.prev_valid(self.entries.len())?;
        let k = self.entries[p].key.clone();
        let v = self.remove(&k)?;
        // reset next_free like PHP: array_pop resets next index
        self.next_free = 0;
        let mut nf: i64 = 0;
        for k in self.keys() {
            if let Key::Int(i) = k {
                if *i >= nf {
                    nf = i.wrapping_add(1);
                }
            }
        }
        self.next_free = nf;
        self.iter_pos = 0;
        Some((k, v))
    }
    pub fn position_of(&self, k: &Key) -> Option<usize> {
        self.find_index(k)
    }
    /// recompute next_free from keys
    pub fn recompute_next_free(&mut self) {
        let mut nf: i64 = 0;
        for k in self.keys() {
            if let Key::Int(i) = k {
                if *i >= nf {
                    nf = i.wrapping_add(1);
                }
            }
        }
        self.next_free = nf;
    }
    pub fn into_pairs(self) -> Vec<(Key, Value)> {
        self.entries.into_iter().filter(|b| !matches!(b.val, Value::Undef)).map(|b| (b.key, b.val)).collect()
    }
    pub fn from_pairs(pairs: Vec<(Key, Value)>) -> PArray {
        let mut a = PArray::with_capacity(pairs.len());
        for (k, v) in pairs {
            a.set(k, v);
        }
        a
    }
}

pub struct ArrIter<'a> {
    arr: &'a PArray,
    pos: usize,
}
impl<'a> Iterator for ArrIter<'a> {
    type Item = (&'a Key, &'a Value);
