    fn next(&mut self) -> Option<Self::Item> {
        while self.pos < self.arr.entries.len() {
            let b = &self.arr.entries[self.pos];
            self.pos += 1;
            if !matches!(b.val, Value::Undef) {
                return Some((&b.key, &b.val));
            }
        }
        None
    }
}
