pub fn float_to_int(f: f64) -> i64 {
    if !f.is_finite() {
        return 0;
    }
    if f >= -9.2233720368547758e18 && f < 9.2233720368547758e18 {
        return f as i64;
    }
    // modular arithmetic
    let two64 = 18446744073709551616.0f64;
    let mut dmod = f % two64;
    if dmod < 0.0 {
        // we're going to make this number positive; call ourselves recursively
        // if the result is -zend_long_min
        dmod += two64;
    }
    if dmod >= 9.2233720368547758e18 {
        dmod -= two64;
    }
    dmod as i64
}

pub fn float_fits_int(f: f64) -> bool {
    f.is_finite() && f >= -9.2233720368547758e18 && f < 9.2233720368547758e18
}

