#[inline]
pub fn is_ws(c: u8) -> bool {
    c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' || c == 0x0b || c == 0x0c
}

/// Parse a numeric prefix of a string PHP-style.
/// Returns (number, consumed_all) or None if no numeric prefix.
/// consumed_all = true if the entire string (with optional surrounding whitespace) is numeric.
pub fn parse_numeric_prefix(s: &[u8]) -> Option<(Num, bool)> {
    let n = s.len();
    let mut i = 0;
    while i < n && is_ws(s[i]) {
        i += 1;
    }
    let start = i;
    if i < n && (s[i] == b'+' || s[i] == b'-') {
        i += 1;
    }
    let int_start = i;
    while i < n && s[i].is_ascii_digit() {
        i += 1;
    }
    let int_digits = i - int_start;
    let mut is_float = false;
    let mut frac_digits = 0;
    if i < n && s[i] == b'.' {
        let save = i;
        i += 1;
        let fs = i;
        while i < n && s[i].is_ascii_digit() {
            i += 1;
        }
        frac_digits = i - fs;
        if int_digits == 0 && frac_digits == 0 {
            i = save;
        } else {
            is_float = true;
        }
    }
    if int_digits == 0 && frac_digits == 0 {
        return None;
    }
    // exponent
    if i < n && (s[i] == b'e' || s[i] == b'E') {
        let mut j = i + 1;
        if j < n && (s[j] == b'+' || s[j] == b'-') {
            j += 1;
        }
        if j < n && s[j].is_ascii_digit() {
            while j < n && s[j].is_ascii_digit() {
                j += 1;
            }
            i = j;
            is_float = true;
        }
    }
    let end = i;
    let mut k = i;
    while k < n && is_ws(s[k]) {
        k += 1;
    }
    let whole = k == n;
    let text = unsafe { std::str::from_utf8_unchecked(&s[start..end]) };
    if !is_float {
        // try integer
        match text.parse::<i64>() {
            Ok(v) => return Some((Num::Int(v), whole)),
            Err(_) => {
                let f: f64 = text.parse().unwrap_or(0.0);
                return Some((Num::Float(f), whole));
            }
        }
    }
    let f: f64 = text.parse().unwrap_or(0.0);
    Some((Num::Float(f), whole))
}

