            if f.is_nan() {
                0
            } else if f >= 9.2233720368547758e18 {
                i64::MAX
            } else if f <= -9.2233720368547758e18 {
                i64::MIN
            } else {
                f as i64
            }
        }
        None => 0,
    }
}

