        d.pop();
    }
    (d, e)
}

fn split_exp(s: &str) -> (Vec<u8>, i32) {
    let (m, e) = s.split_once('e').unwrap();
    let exp: i32 = e.parse().unwrap();
    let digits: Vec<u8> = m.bytes().filter(|c| *c != b'.').collect();
    (digits, exp + 1)
}

/// format with given digits/decpt, PHP php_gcvt style
fn gcvt_layout(neg: bool, digits: &[u8], decpt: i32, prec: i32, exp_char: u8) -> String {
    let mut out = String::new();
    if neg {
        out.push('-');
    }
    if decpt < -3 || decpt > prec {
        // exponential
        out.push(digits[0] as char);
        out.push('.');
        if digits.len() > 1 {
            for &c in &digits[1..] {
                out.push(c as char);
            }
        } else {
            out.push('0');
        }
        out.push(exp_char as char);
        let e = decpt - 1;
        if e < 0 {
            out.push('-');
        } else {
            out.push('+');
        }
        out.push_str(&e.abs().to_string());
    } else if decpt <= 0 {
        out.push_str("0.");
        for _ in 0..(-decpt) {
            out.push('0');
        }
        for &c in digits {
            out.push(c as char);
        }
    } else {
        let dp = decpt as usize;
        for (i, &c) in digits.iter().enumerate() {
            if i == dp {
                out.push('.');
            }
            out.push(c as char);
        }
        for _ in digits.len()..dp {
            out.push('0');
        }
    }
    out
}

/// echo / string conversion of floats (precision=14)
pub fn fmt_float(f: f64) -> String {
    fmt_float_prec(f, 14)
}

pub fn fmt_float_prec(f: f64, prec: i32) -> String {
    if f.is_nan() {
        return "NAN".into();
    }
    if f.is_infinite() {
        return if f > 0.0 { "INF".into() } else { "-INF".into() };
    }
    if f == 0.0 {
        return if f.is_sign_negative() { "-0".into() } else { "0".into() };
    }
    if prec == -1 {
        return fmt_float_repr(f);
    }
    let p = if prec == 0 { 1 } else { prec };
    let (d, e) = prec_digits(f, p as usize);
    gcvt_layout(f < 0.0, &d, e, p, b'E')
}

/// var_dump / var_export / json style (serialize_precision=-1)
pub fn fmt_float_repr(f: f64) -> String {
    if f.is_nan() {
        return "NAN".into();
    }
    if f.is_infinite() {
        return if f > 0.0 { "INF".into() } else { "-INF".into() };
    }
    if f == 0.0 {
        return if f.is_sign_negative() { "-0".into() } else { "0".into() };
    }
    let (d, e) = shortest_digits(f);
    gcvt_layout(f < 0.0, &d, e, 17, b'E')
}

pub fn fmt_float_repr_e(f: f64, exp_char: u8) -> String {
    if f == 0.0 || !f.is_finite() {
        return fmt_float_repr(f);
    }
    let (d, e) = shortest_digits(f);
    gcvt_layout(f < 0.0, &d, e, 17, exp_char)
}

// key conversion helpers
impl Value {
    /// Convert to array key for simple cases (no diagnostics)
    pub fn to_key_simple(&self) -> Option<Key> {
        match self {
            Value::Int(i) => Some(Key::Int(*i)),
            Value::Str(s) => Some(Key::from_pstr(s)),
            Value::Bool(b) => Some(Key::Int(*b as i64)),
            Value::Float(f) => Some(Key::Int(float_to_int(*f))),
            Value::Null | Value::Undef => Some(Key::Str(Rc::new(Vec::new()))),
            Value::Ref(r) => r.borrow().to_key_simple(),
            _ => None,
        }
    }
}
