use std::rc::Rc;

#[derive(Clone, Debug, PartialEq)]
pub enum TPart {
    Lit(Vec<u8>),
    Expr(Vec<Token>),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum NameKind {
    Qualified,      // A\B
    FullyQualified, // \A\B
    Relative,       // namespace\A
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Op {
    Semi, Comma, LParen, RParen, LBracket, RBracket, LBrace, RBrace,
    Arrow, NullsafeArrow, DoubleArrow, DoubleColon, Ellipsis, Question, Colon,
    Coalesce, CoalesceAssign,
    Assign, PlusAssign, MinusAssign, MulAssign, DivAssign, ConcatAssign, ModAssign, PowAssign,
    AndAssign, OrAssign, XorAssign, ShlAssign, ShrAssign,
    Eq, NotEq, Identical, NotIdentical, Lt, Gt, Le, Ge, Spaceship,
    Plus, Minus, Mul, Div, Mod, Pow, Dot, Amp, Pipe, Caret, Tilde, Not, BoolAnd, BoolOr, Shl, Shr,
    Inc, Dec, At, Dollar, PipeGt, Backslash, AttrOpen,
}

#[derive(Clone, Debug, PartialEq)]
pub enum T {
    InlineHtml(Vec<u8>),
    OpenTagEcho,
    CloseTag,
    Var(Rc<str>),
    Ident(Rc<str>),
    Name(Rc<str>, NameKind),
    Int(i64),
    Float(f64),
    Str(Vec<u8>),
    Template(Vec<TPart>),
    ShellCmd(Vec<TPart>),
    Cast(&'static str),
    Op(Op),
    Eof,
}

#[derive(Clone, Debug, PartialEq)]
pub struct Token {
    pub t: T,
    pub line: u32,
    pub doc: Option<Rc<str>>,
}

pub struct LexError {
    pub msg: String,
    pub line: u32,
}

pub struct Lexer<'a> {
    src: &'a [u8],
    pos: usize,
    pub line: u32,
    pending_doc: Option<Rc<str>>,
}

#[inline]
fn is_ident_start(c: u8) -> bool {
    c.is_ascii_alphabetic() || c == b'_' || c >= 0x80
}
#[inline]
fn is_ident_char(c: u8) -> bool {
    c.is_ascii_alphanumeric() || c == b'_' || c >= 0x80
}

fn to_rc_str(b: &[u8]) -> Rc<str> {
    Rc::from(String::from_utf8_lossy(b).as_ref())
}

pub fn tokenize(src: &[u8]) -> Result<Vec<Token>, LexError> {
    let mut lx = Lexer { src, pos: 0, line: 1, pending_doc: None };
    let mut out = Vec::new();
    lx.lex_html(&mut out)?;
    out.push(Token { t: T::Eof, line: lx.line, doc: None });
    Ok(out)
}

/// tokenize code that starts directly in PHP mode (eval / -r)
pub fn tokenize_php(src: &[u8]) -> Result<Vec<Token>, LexError> {
    let mut lx = Lexer { src, pos: 0, line: 1, pending_doc: None };
    let mut out = Vec::new();
    let closed = lx.lex_php(&mut out, false)?;
    if closed {
        lx.lex_html(&mut out)?;
    }
    out.push(Token { t: T::Eof, line: lx.line, doc: None });
    Ok(out)
}

impl<'a> Lexer<'a> {
    #[inline]
    fn peek(&self, off: usize) -> u8 {
        *self.src.get(self.pos + off).unwrap_or(&0)
    }
    #[inline]
    fn at_end(&self) -> bool {
        self.pos >= self.src.len()
    }
    fn starts_with(&self, s: &[u8]) -> bool {
        self.src[self.pos..].starts_with(s)
    }
    fn starts_with_ci(&self, s: &[u8]) -> bool {
        let rest = &self.src[self.pos..];
        rest.len() >= s.len() && rest[..s.len()].eq_ignore_ascii_case(s)
    }
    fn err<T>(&self, msg: &str) -> Result<T, LexError> {
        Err(LexError { msg: msg.to_string(), line: self.line })
    }
    fn push(&mut self, out: &mut Vec<Token>, t: T, line: u32) {
        out.push(Token { t, line, doc: None });
    }

    fn lex_html(&mut self, out: &mut Vec<Token>) -> Result<(), LexError> {
        loop {
            if self.at_end() {
                return Ok(());
            }
            let start = self.pos;
            let start_line = self.line;
            // find open tag
            let mut found = None;
            let mut i = self.pos;
            while i + 1 < self.src.len() {
                if self.src[i] == b'<' && self.src[i + 1] == b'?' {
                    found = Some(i);
                    break;
                }
                i += 1;
            }
            match found {
                None => {
                    let text = self.src[start..].to_vec();
                    self.line += text.iter().filter(|&&c| c == b'\n').count() as u32;
                    self.pos = self.src.len();
                    if !text.is_empty() {
                        self.push(out, T::InlineHtml(text), start_line);
                    }
                    return Ok(());
                }
                Some(p) => {
                    let text = self.src[start..p].to_vec();
                    self.line += text.iter().filter(|&&c| c == b'\n').count() as u32;
                    if !text.is_empty() {
                        self.push(out, T::InlineHtml(text), start_line);
                    }
                    self.pos = p + 2;
                    if self.starts_with_ci(b"php") {
                        let c = self.peek(3);
                        if c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' || c == 0 {
                            self.pos += 3;
                            if c == b'\n' {
                                self.line += 1;
                                self.pos += 1;
                            } else if c == b'\r' {
                                self.pos += 1;
                                if self.peek(0) == b'\n' {
                                    self.pos += 1;
                                }
                                self.line += 1;
                            } else if c != 0 {
                                self.pos += 1;
                            }
                        }
                    } else if self.peek(0) == b'=' {
                        self.pos += 1;
                        let l = self.line;
                        self.push(out, T::OpenTagEcho, l);
                    }
                    let closed = self.lex_php(out, false)?;
                    if !closed {
                        return Ok(());
                    }
                }
            }
        }
    }

    fn skip_ws_comments(&mut self) -> Result<bool, LexError> {
        // returns true if hit close tag inside a line comment (we stop before ?>)
        loop {
            let c = self.peek(0);
            match c {
                b'\n' => {
                    self.line += 1;
                    self.pos += 1;
                }
                b' ' | b'\t' | b'\r' | 0x0b | 0x0c => self.pos += 1,
                b'#' if self.peek(1) != b'[' => self.skip_line_comment(),
                b'/' if self.peek(1) == b'/' => self.skip_line_comment(),
                b'/' if self.peek(1) == b'*' => {
                    let is_doc = self.peek(2) == b'*' && self.peek(3) != b'/';
                    let start = self.pos;
                    self.pos += 2;
                    loop {
                        if self.at_end() {
                            break;
                        }
                        if self.peek(0) == b'*' && self.peek(1) == b'/' {
                            self.pos += 2;
                            break;
                        }
                        if self.peek(0) == b'\n' {
                            self.line += 1;
                        }
                        self.pos += 1;
                    }
                    if is_doc {
                        self.pending_doc = Some(to_rc_str(&self.src[start..self.pos]));
                    }
                }
                _ => return Ok(false),
            }
        }
    }

    fn skip_line_comment(&mut self) {
        while !self.at_end() {
            let c = self.peek(0);
            if c == b'\n' {
                return;
            }
            if c == b'?' && self.peek(1) == b'>' {
                return;
            }
            self.pos += 1;
        }
    }

    /// Lex PHP code. If `brace_mode`, stop at unmatched '}' (consumed). Returns true if stopped at ?>.
    fn lex_php(&mut self, out: &mut Vec<Token>, brace_mode: bool) -> Result<bool, LexError> {
        let mut depth: i32 = 0;
        loop {
            self.skip_ws_comments()?;
            if self.at_end() {
                if brace_mode {
                    return self.err("syntax error, unexpected end of file");
                }
                return Ok(false);
            }
            let line = self.line;
            let c = self.peek(0);
            // close tag
            if c == b'?' && self.peek(1) == b'>' {
                if brace_mode {
                    return self.err("syntax error, unexpected token \"?>\"");
                }
                self.pos += 2;
                if self.peek(0) == b'\n' {
                    self.pos += 1;
                    self.line += 1;
                } else if self.peek(0) == b'\r' && self.peek(1) == b'\n' {
                    self.pos += 2;
                    self.line += 1;
                }
                self.push(out, T::CloseTag, line);
                return Ok(true);
            }
            let doc = self.pending_doc.take();
            let start_len = out.len();
            match c {
                b'$' => {
                    if is_ident_start(self.peek(1)) {
                        self.pos += 1;
                        let s = self.pos;
                        while is_ident_char(self.peek(0)) {
                            self.pos += 1;
                        }
                        let name = to_rc_str(&self.src[s..self.pos]);
                        self.push(out, T::Var(name), line);
                    } else {
                        self.pos += 1;
                        self.push(out, T::Op(Op::Dollar), line);
                    }
                }
                b'\'' => {
                    self.pos += 1;
                    let s = self.lex_single_quoted()?;
                    self.push(out, T::Str(s), line);
                }
                b'"' => {
                    self.pos += 1;
                    let parts = self.lex_double_quoted(b'"')?;
                    out.push(Token { t: parts_to_tok(parts, false), line, doc: None });
                }
                b'`' => {
                    self.pos += 1;
                    let parts = self.lex_double_quoted(b'`')?;
                    out.push(Token { t: T::ShellCmd(parts), line, doc: None });
                }
                b'0'..=b'9' => {
                    let t = self.lex_number()?;
                    self.push(out, t, line);
                }
                b'.' if self.peek(1).is_ascii_digit() => {
                    let t = self.lex_number()?;
                    self.push(out, t, line);
                }
                b'<' if self.starts_with(b"<<<") => {
                    let t = self.lex_heredoc()?;
                    self.push(out, t, line);
                }
                b'\\' => {
                    // fully qualified name
                    if is_ident_start(self.peek(1)) {
                        self.pos += 1;
                        let name = self.lex_qualified_rest();
                        self.push(out, T::Name(name, NameKind::FullyQualified), line);
                    } else {
                        self.pos += 1;
                        self.push(out, T::Op(Op::Backslash), line);
                    }
                }
                b'(' => {
                    if let Some(cast) = self.try_cast() {
                        self.push(out, T::Cast(cast), line);
                    } else {
                        self.pos += 1;
                        self.push(out, T::Op(Op::LParen), line);
                    }
                }
                b'{' => {
                    self.pos += 1;
                    depth += 1;
                    self.push(out, T::Op(Op::LBrace), line);
                }
                b'}' => {
                    self.pos += 1;
                    if brace_mode && depth == 0 {
                        return Ok(false);
                    }
                    depth -= 1;
                    self.push(out, T::Op(Op::RBrace), line);
                }
                b'#' if self.peek(1) == b'[' => {
                    self.pos += 2;
                    self.push(out, T::Op(Op::AttrOpen), line);
                }
                _ if is_ident_start(c) => {
                    let s = self.pos;
                    while is_ident_char(self.peek(0)) {
                        self.pos += 1;
                    }
                    // qualified?
                    if self.peek(0) == b'\\' && is_ident_start(self.peek(1)) {
                        let first = &self.src[s..self.pos];
                        if first.eq_ignore_ascii_case(b"namespace") {
                            self.pos += 1;
                            let rest = self.lex_qualified_rest();
                            self.push(out, T::Name(rest, NameKind::Relative), line);
                        } else {
                            self.pos = s;
                            let name = self.lex_qualified_rest();
                            self.push(out, T::Name(name, NameKind::Qualified), line);
                        }
                    } else {
                        let word = &self.src[s..self.pos];
                        // __halt_compiler
                        if word.eq_ignore_ascii_case(b"__halt_compiler") {
                            // stop lexing entirely
                            self.pos = self.src.len();
                            out.push(Token { t: T::Op(Op::Semi), line, doc: None });
                            return Ok(false);
                        }
                        let name = to_rc_str(word);
                        self.push(out, T::Ident(name), line);
                    }
                }
                _ => {
                    let op = self.lex_op()?;
                    self.push(out, T::Op(op), line);
                }
            }
            if let Some(d) = doc {
                if out.len() > start_len {
                    out[start_len].doc = Some(d);
                }
            }
        }
    }

    fn lex_qualified_rest(&mut self) -> Rc<str> {
        let s = self.pos;
        loop {
            while is_ident_char(self.peek(0)) {
                self.pos += 1;
            }
            if self.peek(0) == b'\\' && is_ident_start(self.peek(1)) {
                self.pos += 1;
                continue;
            }
            break;
        }
        to_rc_str(&self.src[s..self.pos])
    }

    fn try_cast(&mut self) -> Option<&'static str> {
        let mut i = self.pos + 1;
        while i < self.src.len() && (self.src[i] == b' ' || self.src[i] == b'\t') {
            i += 1;
        }
        let s = i;
        while i < self.src.len() && self.src[i].is_ascii_alphabetic() {
            i += 1;
        }
        let word = self.src[s..i].to_ascii_lowercase();
        while i < self.src.len() && (self.src[i] == b' ' || self.src[i] == b'\t') {
            i += 1;
        }
        if i >= self.src.len() || self.src[i] != b')' {
            return None;
        }
        let r = match &word[..] {
            b"int" | b"integer" => "int",
            b"bool" | b"boolean" => "bool",
            b"float" | b"double" | b"real" => "float",
            b"string" | b"binary" => "string",
            b"array" => "array",
            b"object" => "object",
            b"unset" => "unset",
            b"void" => "void",
            _ => return None,
        };
        self.pos = i + 1;
        Some(r)
    }

    fn lex_op(&mut self) -> Result<Op, LexError> {
        let c0 = self.peek(0);
        let c1 = self.peek(1);
        let c2 = self.peek(2);
        let (op, n) = match (c0, c1, c2) {
            (b'=', b'=', b'=') => (Op::Identical, 3),
            (b'!', b'=', b'=') => (Op::NotIdentical, 3),
            (b'<', b'=', b'>') => (Op::Spaceship, 3),
            (b'*', b'*', b'=') => (Op::PowAssign, 3),
            (b'.', b'.', b'.') => (Op::Ellipsis, 3),
            (b'?', b'?', b'=') => (Op::CoalesceAssign, 3),
            (b'?', b'-', b'>') => (Op::NullsafeArrow, 3),
            (b'<', b'<', b'=') => (Op::ShlAssign, 3),
            (b'>', b'>', b'=') => (Op::ShrAssign, 3),
            (b'=', b'=', _) => (Op::Eq, 2),
            (b'!', b'=', _) => (Op::NotEq, 2),
            (b'<', b'>', _) => (Op::NotEq, 2),
            (b'<', b'=', _) => (Op::Le, 2),
            (b'>', b'=', _) => (Op::Ge, 2),
            (b'<', b'<', _) => (Op::Shl, 2),
            (b'>', b'>', _) => (Op::Shr, 2),
            (b'-', b'>', _) => (Op::Arrow, 2),
            (b'=', b'>', _) => (Op::DoubleArrow, 2),
            (b':', b':', _) => (Op::DoubleColon, 2),
            (b'?', b'?', _) => (Op::Coalesce, 2),
            (b'+', b'=', _) => (Op::PlusAssign, 2),
            (b'-', b'=', _) => (Op::MinusAssign, 2),
            (b'*', b'=', _) => (Op::MulAssign, 2),
            (b'/', b'=', _) => (Op::DivAssign, 2),
            (b'.', b'=', _) => (Op::ConcatAssign, 2),
            (b'%', b'=', _) => (Op::ModAssign, 2),
            (b'&', b'=', _) => (Op::AndAssign, 2),
            (b'|', b'=', _) => (Op::OrAssign, 2),
            (b'^', b'=', _) => (Op::XorAssign, 2),
            (b'*', b'*', _) => (Op::Pow, 2),
            (b'+', b'+', _) => (Op::Inc, 2),
            (b'-', b'-', _) => (Op::Dec, 2),
            (b'&', b'&', _) => (Op::BoolAnd, 2),
            (b'|', b'|', _) => (Op::BoolOr, 2),
            (b'|', b'>', _) => (Op::PipeGt, 2),
            (b';', _, _) => (Op::Semi, 1),
            (b',', _, _) => (Op::Comma, 1),
            (b'(', _, _) => (Op::LParen, 1),
            (b')', _, _) => (Op::RParen, 1),
            (b'[', _, _) => (Op::LBracket, 1),
            (b']', _, _) => (Op::RBracket, 1),
            (b'?', _, _) => (Op::Question, 1),
            (b':', _, _) => (Op::Colon, 1),
            (b'=', _, _) => (Op::Assign, 1),
            (b'<', _, _) => (Op::Lt, 1),
            (b'>', _, _) => (Op::Gt, 1),
            (b'+', _, _) => (Op::Plus, 1),
            (b'-', _, _) => (Op::Minus, 1),
            (b'*', _, _) => (Op::Mul, 1),
            (b'/', _, _) => (Op::Div, 1),
            (b'%', _, _) => (Op::Mod, 1),
            (b'.', _, _) => (Op::Dot, 1),
            (b'&', _, _) => (Op::Amp, 1),
            (b'|', _, _) => (Op::Pipe, 1),
            (b'^', _, _) => (Op::Caret, 1),
            (b'~', _, _) => (Op::Tilde, 1),
            (b'!', _, _) => (Op::Not, 1),
            (b'@', _, _) => (Op::At, 1),
            _ => {
                let ch = c0 as char;
                return self.err(&format!("syntax error, unexpected character 0x{:02X}", c0).replace("{}", &ch.to_string()));
            }
        };
        self.pos += n;
        Ok(op)
    }

    fn lex_number(&mut self) -> Result<T, LexError> {
        let s = self.pos;
        let c0 = self.peek(0);
        let c1 = self.peek(1);
        if c0 == b'0' && (c1 == b'x' || c1 == b'X') && self.peek(2).is_ascii_hexdigit() {
            self.pos += 2;
            return Ok(self.lex_radix(16));
        }
        if c0 == b'0' && (c1 == b'b' || c1 == b'B') && (self.peek(2) == b'0' || self.peek(2) == b'1') {
            self.pos += 2;
            return Ok(self.lex_radix(2));
        }
        if c0 == b'0' && (c1 == b'o' || c1 == b'O') && (b'0'..=b'7').contains(&self.peek(2)) {
            self.pos += 2;
            return Ok(self.lex_radix(8));
        }
        // decimal / float / legacy octal
        let mut is_float = false;
        while self.peek(0).is_ascii_digit() || (self.peek(0) == b'_' && self.peek(1).is_ascii_digit()) {
            self.pos += 1;
        }
        if self.peek(0) == b'.' && self.peek(1).is_ascii_digit() {
            is_float = true;
            self.pos += 1;
            while self.peek(0).is_ascii_digit() || (self.peek(0) == b'_' && self.peek(1).is_ascii_digit()) {
                self.pos += 1;
            }
        } else if self.peek(0) == b'.' && !(self.peek(1) == b'.' ) && !is_ident_start(self.peek(1)) {
            // "1." is a float
            is_float = true;
            self.pos += 1;
        }
        if self.peek(0) == b'e' || self.peek(0) == b'E' {
            let save = self.pos;
            self.pos += 1;
            if self.peek(0) == b'+' || self.peek(0) == b'-' {
                self.pos += 1;
            }
            if self.peek(0).is_ascii_digit() {
                is_float = true;
                while self.peek(0).is_ascii_digit() || (self.peek(0) == b'_' && self.peek(1).is_ascii_digit()) {
                    self.pos += 1;
                }
            } else {
                self.pos = save;
            }
        }
        let text: String = self.src[s..self.pos].iter().filter(|&&c| c != b'_').map(|&c| c as char).collect();
        if is_float {
            return Ok(T::Float(text.parse().unwrap_or(0.0)));
        }
        if text.len() > 1 && text.starts_with('0') {
            // legacy octal
            let digits = &text[1..];
            if digits.bytes().any(|c| c == b'8' || c == b'9') {
                return self.err("Invalid numeric literal");
            }
            let mut v: i64 = 0;
            let mut fv: f64 = 0.0;
            let mut overflow = false;
            for c in digits.bytes() {
                let d = (c - b'0') as i64;
                fv = fv * 8.0 + d as f64;
                if !overflow {
                    match v.checked_mul(8).and_then(|x| x.checked_add(d)) {
                        Some(x) => v = x,
                        None => overflow = true,
                    }
                }
            }
            return Ok(if overflow { T::Float(fv) } else { T::Int(v) });
        }
        match text.parse::<i64>() {
            Ok(v) => Ok(T::Int(v)),
            Err(_) => Ok(T::Float(text.parse().unwrap_or(0.0))),
        }
    }

    fn lex_radix(&mut self, radix: u32) -> T {
        let mut v: i64 = 0;
        let mut fv: f64 = 0.0;
        let mut overflow = false;
        loop {
            let c = self.peek(0);
            if c == b'_' && (self.peek(1) as char).is_digit(radix) {
                self.pos += 1;
                continue;
            }
            let d = match (c as char).to_digit(radix) {
                Some(d) => d as i64,
                None => break,
            };
            self.pos += 1;
            fv = fv * radix as f64 + d as f64;
            if !overflow {
                match v.checked_mul(radix as i64).and_then(|x| x.checked_add(d)) {
                    Some(x) => v = x,
                    None => overflow = true,
                }
            }
        }
        if overflow {
            T::Float(fv)
        } else {
            T::Int(v)
        }
    }

    fn lex_single_quoted(&mut self) -> Result<Vec<u8>, LexError> {
        let mut out = Vec::new();
        loop {
            if self.at_end() {
                return self.err("syntax error, unexpected end of file");
            }
            let c = self.peek(0);
            if c == b'\'' {
                self.pos += 1;
                return Ok(out);
            }
            if c == b'\\' && (self.peek(1) == b'\'' || self.peek(1) == b'\\') {
                out.push(self.peek(1));
                self.pos += 2;
                continue;
            }
            if c == b'\n' {
                self.line += 1;
            }
            out.push(c);
            self.pos += 1;
        }
    }

    /// parse escape at pos (after backslash consumed?) - here pos at backslash
    fn lex_escape(&mut self, out: &mut Vec<u8>, quote: u8) {
        // self.peek(0) == '\\'
        let c = self.peek(1);
        match c {
            b'n' => { out.push(b'\n'); self.pos += 2; }
            b't' => { out.push(b'\t'); self.pos += 2; }
            b'r' => { out.push(b'\r'); self.pos += 2; }
            b'v' => { out.push(0x0b); self.pos += 2; }
            b'e' => { out.push(0x1b); self.pos += 2; }
            b'f' => { out.push(0x0c); self.pos += 2; }
            b'\\' => { out.push(b'\\'); self.pos += 2; }
            b'$' => { out.push(b'$'); self.pos += 2; }
            b'0'..=b'7' => {
                let mut v: u32 = 0;
                let mut n = 0;
                self.pos += 1;
                while n < 3 && (b'0'..=b'7').contains(&self.peek(0)) {
                    v = v * 8 + (self.peek(0) - b'0') as u32;
                    self.pos += 1;
                    n += 1;
                }
                out.push((v & 0xff) as u8);
            }
            b'x' if self.peek(2).is_ascii_hexdigit() => {
                self.pos += 2;
                let mut v: u32 = 0;
                let mut n = 0;
                while n < 2 && self.peek(0).is_ascii_hexdigit() {
                    v = v * 16 + (self.peek(0) as char).to_digit(16).unwrap();
                    self.pos += 1;
                    n += 1;
                }
                out.push(v as u8);
            }
            b'u' if self.peek(2) == b'{' => {
                let save = self.pos;
                self.pos += 3;
                let mut v: u32 = 0;
                let mut n = 0;
                while self.peek(0).is_ascii_hexdigit() {
                    v = v.wrapping_mul(16).wrapping_add((self.peek(0) as char).to_digit(16).unwrap());
                    self.pos += 1;
                    n += 1;
                }
                if self.peek(0) == b'}' && n > 0 {
                    self.pos += 1;
                    encode_utf8(v, out);
                } else {
                    self.pos = save;
                    out.push(b'\\');
                    self.pos += 1;
                }
            }
            _ => {
                if c == quote && quote != 0 {
                    out.push(c);
                    self.pos += 2;
                } else {
                    out.push(b'\\');
                    self.pos += 1;
                }
            }
        }
    }

    /// lex double quoted content until `quote` (consumed). quote==0 => until end of src (heredoc body)
    fn lex_double_quoted(&mut self, quote: u8) -> Result<Vec<TPart>, LexError> {
        let mut parts: Vec<TPart> = Vec::new();
        let mut lit: Vec<u8> = Vec::new();
        loop {
            if self.at_end() {
                if quote == 0 {
                    break;
                }
                return self.err("syntax error, unexpected end of file");
            }
            let c = self.peek(0);
            if c == quote && quote != 0 {
                self.pos += 1;
                break;
            }
            match c {
                b'\\' => {
                    self.lex_escape(&mut lit, quote);
                }
                b'$' if is_ident_start(self.peek(1)) => {
                    if !lit.is_empty() {
                        parts.push(TPart::Lit(std::mem::take(&mut lit)));
                    }
                    let toks = self.lex_simple_interp()?;
                    parts.push(TPart::Expr(toks));
                }
                b'$' if self.peek(1) == b'{' => {
                    if !lit.is_empty() {
                        parts.push(TPart::Lit(std::mem::take(&mut lit)));
                    }
                    let line = self.line;
                    self.pos += 2;
                    // ${name} or ${expr}
                    let s = self.pos;
                    let mut i = s;
                    while i < self.src.len() && is_ident_char(self.src[i]) {
                        i += 1;
                    }
                    let mut toks = Vec::new();
                    if i > s && is_ident_start(self.src[s]) && i < self.src.len() && (self.src[i] == b'}' || self.src[i] == b'[') {
                        let name = to_rc_str(&self.src[s..i]);
                        if self.src[i] == b'}' {
                            self.pos = i + 1;
                            toks.push(Token { t: T::Var(name), line, doc: None });
                        } else {
                            // ${name[expr]}
                            self.pos = i;
                            toks.push(Token { t: T::Var(name), line, doc: None });
                            self.lex_php(&mut toks, true)?;
                        }
                    } else {
                        toks.push(Token { t: T::Op(Op::Dollar), line, doc: None });
                        toks.push(Token { t: T::Op(Op::LBrace), line, doc: None });
                        self.lex_php(&mut toks, true)?;
                        toks.push(Token { t: T::Op(Op::RBrace), line, doc: None });
                    }
                    // mark as dollar-brace (deprecated) using a leading marker
                    toks.insert(0, Token { t: T::Op(Op::DoubleArrow), line, doc: Some(Rc::from("${")) });
                    parts.push(TPart::Expr(toks));
                }
                b'{' if self.peek(1) == b'$' => {
                    if !lit.is_empty() {
                        parts.push(TPart::Lit(std::mem::take(&mut lit)));
                    }
                    self.pos += 1;
                    let mut toks = Vec::new();
                    self.lex_php(&mut toks, true)?;
                    parts.push(TPart::Expr(toks));
                }
                b'\n' => {
                    self.line += 1;
                    lit.push(c);
                    self.pos += 1;
                }
                _ => {
                    lit.push(c);
                    self.pos += 1;
                }
            }
        }
        if !lit.is_empty() {
            parts.push(TPart::Lit(lit));
        }
        Ok(parts)
    }

    fn lex_simple_interp(&mut self) -> Result<Vec<Token>, LexError> {
        let line = self.line;
        self.pos += 1;
        let s = self.pos;
        while is_ident_char(self.peek(0)) {
            self.pos += 1;
        }
        let name = to_rc_str(&self.src[s..self.pos]);
        let mut toks = vec![Token { t: T::Var(name), line, doc: None }];
        let mk = |t: T| Token { t, line, doc: None };
        if self.peek(0) == b'[' {
            // simple index
            let save = self.pos;
            self.pos += 1;
            let c = self.peek(0);
            let mut ok = true;
            let mut idx_tok = None;
            if c == b'$' && is_ident_start(self.peek(1)) {
                self.pos += 1;
                let s2 = self.pos;
                while is_ident_char(self.peek(0)) {
                    self.pos += 1;
                }
                idx_tok = Some(T::Var(to_rc_str(&self.src[s2..self.pos])));
            } else if c.is_ascii_digit() || (c == b'-' && self.peek(1).is_ascii_digit()) {
                let s2 = self.pos;
                if c == b'-' {
                    self.pos += 1;
                }
                while self.peek(0).is_ascii_alphanumeric() || self.peek(0) == b'_' {
                    self.pos += 1;
                }
                let txt = &self.src[s2..self.pos];
                // decimal integer without leading zeros -> int, else string
                let txt_s = String::from_utf8_lossy(txt).to_string();
                let is_dec = {
                    let d = txt_s.strip_prefix('-').unwrap_or(&txt_s);
                    !d.is_empty() && d.bytes().all(|b| b.is_ascii_digit()) && (d == "0" || !d.starts_with('0'))
                };
                if is_dec && !(txt_s == "-0") {
                    match txt_s.parse::<i64>() {
                        Ok(v) => idx_tok = Some(T::Int(v)),
                        Err(_) => idx_tok = Some(T::Str(txt.to_vec())),
                    }
                } else {
                    idx_tok = Some(T::Str(txt.to_vec()));
                }
            } else if is_ident_start(c) {
                let s2 = self.pos;
                while is_ident_char(self.peek(0)) {
                    self.pos += 1;
                }
                idx_tok = Some(T::Str(self.src[s2..self.pos].to_vec()));
            } else {
                ok = false;
            }
            if ok && self.peek(0) == b']' {
                self.pos += 1;
                toks.push(mk(T::Op(Op::LBracket)));
                toks.push(mk(idx_tok.unwrap()));
                toks.push(mk(T::Op(Op::RBracket)));
            } else {
                self.pos = save;
                if ok {
                    // malformed: PHP gives parse error; we treat literally
                    return self.err("syntax error, unexpected token \"\", expecting \"]\"");
                }
            }
        } else if self.peek(0) == b'-' && self.peek(1) == b'>' && is_ident_start(self.peek(2)) {
            self.pos += 2;
            let s2 = self.pos;
            while is_ident_char(self.peek(0)) {
                self.pos += 1;
            }
            toks.push(mk(T::Op(Op::Arrow)));
            toks.push(mk(T::Ident(to_rc_str(&self.src[s2..self.pos]))));
        } else if self.peek(0) == b'?' && self.peek(1) == b'-' && self.peek(2) == b'>' && is_ident_start(self.peek(3)) {
            self.pos += 3;
            let s2 = self.pos;
            while is_ident_char(self.peek(0)) {
                self.pos += 1;
            }
            toks.push(mk(T::Op(Op::NullsafeArrow)));
            toks.push(mk(T::Ident(to_rc_str(&self.src[s2..self.pos]))));
        }
        Ok(toks)
    }

    fn lex_heredoc(&mut self) -> Result<T, LexError> {
        // at <<<
        self.pos += 3;
        while self.peek(0) == b' ' || self.peek(0) == b'\t' {
            self.pos += 1;
        }
        let mut nowdoc = false;
        let mut quoted = 0u8;
        if self.peek(0) == b'\'' {
            nowdoc = true;
            quoted = b'\'';
            self.pos += 1;
        } else if self.peek(0) == b'"' {
            quoted = b'"';
            self.pos += 1;
        }
        let s = self.pos;
        while is_ident_char(self.peek(0)) {
            self.pos += 1;
        }
        let label = self.src[s..self.pos].to_vec();
        if quoted != 0 {
            if self.peek(0) != quoted {
                return self.err("syntax error");
            }
            self.pos += 1;
        }
        // newline
        if self.peek(0) == b'\r' {
            self.pos += 1;
        }
        if self.peek(0) != b'\n' {
            return self.err("syntax error");
        }
        self.pos += 1;
        self.line += 1;
        let body_start = self.pos;
        let body_line = self.line;
        // find closing label
        let mut line_start = self.pos;
        let (body_end, indent, close_end);
        loop {
            if line_start > self.src.len() {
                return self.err("syntax error, unexpected end of file");
            }
            // check this line
            let mut i = line_start;
            while i < self.src.len() && (self.src[i] == b' ' || self.src[i] == b'\t') {
                i += 1;
            }
            if self.src[i..].starts_with(&label) {
                let after = i + label.len();
                if after >= self.src.len() || !is_ident_char(self.src[after]) {
                    indent = i - line_start;
                    body_end = line_start;
                    close_end = after;
                    break;
                }
            }
            // next line
            match self.src[line_start..].iter().position(|&c| c == b'\n') {
                Some(p) => line_start = line_start + p + 1,
                None => return self.err("syntax error, unexpected end of file"),
            }
        }
        // body text excluding final newline
        let mut raw_end = body_end;
        if raw_end > body_start {
            raw_end -= 1; // remove \n
            if raw_end > body_start && self.src[raw_end - 1] == b'\r' {
                raw_end -= 1;
            }
        }
        let raw = if body_end > body_start { &self.src[body_start..raw_end] } else { &self.src[body_start..body_start] };
        // de-indent
        let mut text = Vec::with_capacity(raw.len());
        if indent > 0 {
            for (li, l) in raw.split(|&c| c == b'\n').enumerate() {
                if li > 0 {
                    text.push(b'\n');
                }
                let mut k = 0;
                while k < indent && k < l.len() && (l[k] == b' ' || l[k] == b'\t') {
                    k += 1;
                }
                text.extend_from_slice(&l[k..]);
            }
        } else {
            text.extend_from_slice(raw);
        }
        let nl = self.src[body_start..close_end].iter().filter(|&&c| c == b'\n').count() as u32;
        self.pos = close_end;
        let result = if nowdoc {
            T::Str(text)
        } else {
            let mut sub = Lexer { src: &text, pos: 0, line: body_line, pending_doc: None };
            let parts = sub.lex_double_quoted(0)?;
            parts_to_tok(parts, true)
        };
        self.line = body_line + nl - 1;
        let _ = body_line;
        Ok(result)
    }
}

fn parts_to_tok(parts: Vec<TPart>, _heredoc: bool) -> T {
    if parts.is_empty() {
        return T::Str(Vec::new());
    }
    if parts.len() == 1 {
        if let TPart::Lit(_) = &parts[0] {
            if let TPart::Lit(l) = parts.into_iter().next().unwrap() {
                return T::Str(l);
            }
            unreachable!()
        }
    }
    T::Template(parts)
}

pub fn encode_utf8(v: u32, out: &mut Vec<u8>) {
    if v < 0x80 {
        out.push(v as u8);
    } else if v < 0x800 {
        out.push(0xC0 | (v >> 6) as u8);
        out.push(0x80 | (v & 0x3F) as u8);
    } else if v < 0x10000 {
        out.push(0xE0 | (v >> 12) as u8);
        out.push(0x80 | ((v >> 6) & 0x3F) as u8);
        out.push(0x80 | (v & 0x3F) as u8);
    } else {
        out.push(0xF0 | (v >> 18) as u8);
        out.push(0x80 | ((v >> 12) & 0x3F) as u8);
        out.push(0x80 | ((v >> 6) & 0x3F) as u8);
        out.push(0x80 | (v & 0x3F) as u8);
    }
}
