pub fn tok_desc(t: &T) -> String {
    match t {
        T::Eof => "end of file".into(),
        T::Var(n) => format!("variable \"${}\"", n),
        T::Ident(n) => {
            let l = n.to_ascii_lowercase();
            if is_keyword(&l) {
                format!("token \"{}\"", n)
            } else {
                format!("identifier \"{}\"", n)
            }
        }
        T::Name(n, k) => match k {
            NameKind::FullyQualified => format!("fully qualified name \"\\{}\"", n),
            NameKind::Qualified => format!("qualified name \"{}\"", n),
            NameKind::Relative => format!("namespace-relative name \"namespace\\{}\"", n),
        },
        T::Int(i) => format!("integer \"{}\"", i),
        T::Float(f) => format!("floating-point number \"{}\"", f),
        T::Str(s) => format!("double-quoted string \"{}\"", String::from_utf8_lossy(s)),
        T::Template(_) => "token \"\"\"".into(),
        T::InlineHtml(_) => "inline html".into(),
        T::CloseTag => "token \"?>\"".into(),
        T::OpenTagEcho => "token \"<?=\"".into(),
        T::Cast(c) => format!("token \"({})\"", c),
        T::ShellCmd(_) => "token \"`\"".into(),
        T::Op(o) => format!("token \"{}\"", op_str(*o)),
    }
}

fn is_keyword(l: &str) -> bool {
    matches!(
        l,
        "abstract" | "and" | "array" | "as" | "break" | "callable" | "case" | "catch" | "class" | "clone" | "const" | "continue" | "declare" | "default" | "do" | "echo" | "else" | "elseif" | "empty" | "enddeclare" | "endfor" | "endforeach" | "endif" | "endswitch" | "endwhile" | "eval" | "exit" | "die" | "extends" | "final" | "finally" | "fn" | "for" | "foreach" | "function" | "global" | "goto" | "if" | "implements" | "include" | "include_once" | "instanceof" | "insteadof" | "interface" | "isset" | "list" | "match" | "namespace" | "new" | "or" | "print" | "private" | "protected" | "public" | "readonly" | "require" | "require_once" | "return" | "static" | "switch" | "throw" | "trait" | "try" | "unset" | "use" | "var" | "while" | "xor" | "yield"
    )
}

pub fn op_str(o: Op) -> &'static str {
    use Op::*;
    match o {
        Semi => ";", Comma => ",", LParen => "(", RParen => ")", LBracket => "[", RBracket => "]", LBrace => "{", RBrace => "}",
        Arrow => "->", NullsafeArrow => "?->", DoubleArrow => "=>", DoubleColon => "::", Ellipsis => "...", Question => "?", Colon => ":",
        Coalesce => "??", CoalesceAssign => "??=", Assign => "=", PlusAssign => "+=", MinusAssign => "-=", MulAssign => "*=", DivAssign => "/=",
        ConcatAssign => ".=", ModAssign => "%=", PowAssign => "**=", AndAssign => "&=", OrAssign => "|=", XorAssign => "^=", ShlAssign => "<<=", ShrAssign => ">>=",
        Eq => "==", NotEq => "!=", Identical => "===", NotIdentical => "!==", Lt => "<", Gt => ">", Le => "<=", Ge => ">=", Spaceship => "<=>",
        Plus => "+", Minus => "-", Mul => "*", Div => "/", Mod => "%", Pow => "**", Dot => ".", Amp => "&", Pipe => "|", Caret => "^", Tilde => "~",
        Not => "!", BoolAnd => "&&", BoolOr => "||", Shl => "<<", Shr => ">>", Inc => "++", Dec => "--", At => "@", Dollar => "$", PipeGt => "|>",
        Backslash => "\\", AttrOpen => "#[",
    }
}

impl Parser {
    pub fn new(toks: Vec<Token>, file: Rc<str>) -> Parser {
        Parser {
            toks,
            pos: 0,
            namespace: String::new(),
            use_class: HashMap::new(),
            use_func: HashMap::new(),
            use_const: HashMap::new(),
            scopes: vec![Scope::new(false)],
            class_ctx: vec![None],
            func_ctx: vec![String::new()],
            method_ctx: vec![String::new()],
            file,
            warnings: Vec::new(),
            anon_count: 0,
            strict_types: false,
            no_in_template: false,
        }
    }

    // ---------- token helpers ----------
    #[inline]
    fn peek(&self) -> &T {
        &self.toks[self.pos].t
    }
    #[inline]
    fn peek_at(&self, n: usize) -> &T {
        let i = (self.pos + n).min(self.toks.len() - 1);
        &self.toks[i].t
    }
    #[inline]
    fn line(&self) -> u32 {
        self.toks[self.pos].line
    }
    fn prev_line(&self) -> u32 {
        if self.pos > 0 {
            self.toks[self.pos - 1].line
        } else {
            1
        }
    }
    #[inline]
    fn advance(&mut self) -> Token {
        let t = self.toks[self.pos].clone();
        if self.pos < self.toks.len() - 1 {
            self.pos += 1;
        }
        t
    }
    #[inline]
    fn is_op(&self, o: Op) -> bool {
        matches!(self.peek(), T::Op(x) if *x == o)
    }
    fn is_kw(&self, k: &str) -> bool {
        kw(self.peek(), k)
    }
    fn accept_op(&mut self, o: Op) -> bool {
        if self.is_op(o) {
            self.advance();
            true
        } else {
            false
        }
    }
    fn accept_kw(&mut self, k: &str) -> bool {
        if self.is_kw(k) {
            self.advance();
            true
        } else {
            false
        }
    }
    fn unexpected<X>(&self) -> PResult<X> {
        Err(ParseError { msg: format!("syntax error, unexpected {}", tok_desc(self.peek())), line: self.line() })
    }
    fn unexpected_expecting<X>(&self, what: &str) -> PResult<X> {
        Err(ParseError { msg: format!("syntax error, unexpected {}, expecting {}", tok_desc(self.peek()), what), line: self.line() })
    }
    fn expect_op(&mut self, o: Op) -> PResult<()> {
        if self.accept_op(o) {
            Ok(())
        } else {
            self.unexpected_expecting(&format!("\"{}\"", op_str(o)))
        }
    }
    fn expect_semi(&mut self) -> PResult<()> {
        if self.accept_op(Op::Semi) {
            return Ok(());
        }
        if matches!(self.peek(), T::CloseTag) {
            self.advance();
            return Ok(());
        }
        if matches!(self.peek(), T::Eof) {
            return self.unexpected_expecting("\";\"");
        }
        self.unexpected_expecting("\";\" or \",\"")
    }
    fn expect_ident(&mut self) -> PResult<Name> {
        match self.peek().clone() {
            T::Ident(n) => {
                self.advance();
                Ok(n)
            }
            _ => self.unexpected_expecting("identifier"),
        }
    }
    fn err<X>(&self, msg: &str) -> PResult<X> {
        Err(ParseError { msg: msg.to_string(), line: self.line() })
    }

    // ---------- scopes ----------
    fn scope(&mut self) -> &mut Scope {
        self.scopes.last_mut().unwrap()
    }
    fn var_ref(&mut self, name: &Name) -> VarRef {
        let slot = self.scope().slot(name);
        VarRef { name: name.clone(), slot }
    }

    // ---------- name resolution ----------
    fn ns_prefix(&self, name: &str) -> String {
        if self.namespace.is_empty() {
            name.to_string()
        } else {
            format!("{}\\{}", self.namespace, name)
        }
    }
    pub fn resolve_class(&self, name: &str, kind: Option<NameKind>) -> String {
        match kind {
            Some(NameKind::FullyQualified) => name.to_string(),
            Some(NameKind::Relative) => self.ns_prefix(name),
            Some(NameKind::Qualified) => {
                let (first, rest) = name.split_once('\\').unwrap();
                if let Some(t) = self.use_class.get(&first.to_ascii_lowercase()) {
                    format!("{}\\{}", t, rest)
                } else {
                    self.ns_prefix(name)
                }
            }
            None => {
                let l = name.to_ascii_lowercase();
                if l == "self" || l == "parent" || l == "static" {
                    return name.to_string();
                }
                if let Some(t) = self.use_class.get(&l) {
                    t.clone()
                } else {
                    self.ns_prefix(name)
                }
            }
        }
    }
    fn resolve_func(&self, name: &str, kind: Option<NameKind>) -> (Name, Option<Name>) {
        match kind {
            None => {
                if let Some(t) = self.use_func.get(&name.to_ascii_lowercase()) {
                    return (Rc::from(t.as_str()), None);
                }
                if self.namespace.is_empty() {
                    (Rc::from(name), None)
                } else {
                    (Rc::from(self.ns_prefix(name).as_str()), Some(Rc::from(name)))
                }
            }
            _ => (Rc::from(self.resolve_class(name, kind).as_str()), None),
        }
    }
    fn resolve_const(&self, name: &str, kind: Option<NameKind>) -> (Name, Option<Name>) {
        match kind {
            None => {
                if let Some(t) = self.use_const.get(name) {
                    return (Rc::from(t.as_str()), None);
                }
                if self.namespace.is_empty() {
                    (Rc::from(name), None)
                } else {
                    (Rc::from(self.ns_prefix(name).as_str()), Some(Rc::from(name)))
                }
            }
            _ => (Rc::from(self.resolve_class(name, kind).as_str()), None),
        }
    }

    fn mk(&self, kind: ExprKind, line: u32) -> Expr {
        Expr { kind, line }
    }

    // ---------- program ----------
    pub fn parse_program(&mut self) -> PResult<Program> {
        let mut stmts = Vec::new();
        while !matches!(self.peek(), T::Eof) {
            if self.is_kw("namespace") && !matches!(self.peek_at(1), T::Op(Op::Backslash)) {
                self.parse_namespace(&mut stmts)?;
                continue;
            }
            let s = self.parse_statement(true)?;
            stmts.push(s);
        }
        let sc = self.scopes.pop().unwrap();
        Ok(Program {
            stmts,
            num_slots: sc.names.len() as u32,
            slot_names: Rc::new(sc.names),
            file: self.file.clone(),
            warnings: std::mem::take(&mut self.warnings),
        })
    }

    fn parse_namespace(&mut self, stmts: &mut Vec<Stmt>) -> PResult<()> {
        self.advance(); // namespace
        let name = match self.peek().clone() {
            T::Ident(n) => {
                self.advance();
                n.to_string()
            }
            T::Name(n, NameKind::Qualified) => {
                self.advance();
                n.to_string()
            }
            _ => String::new(),
        };
        self.namespace = name;
        self.use_class.clear();
        self.use_func.clear();
        self.use_const.clear();
        if self.accept_op(Op::LBrace) {
            while !self.is_op(Op::RBrace) {
                if matches!(self.peek(), T::Eof) {
                    return self.unexpected();
                }
                let s = self.parse_statement(true)?;
                stmts.push(s);
            }
            self.advance();
            self.namespace = String::new();
        } else {
            self.expect_semi()?;
        }
        Ok(())
    }

    fn parse_block_or_statement(&mut self) -> PResult<Vec<Stmt>> {
        if self.is_op(Op::LBrace) {
            self.advance();
            let b = self.parse_stmts_until_brace()?;
            Ok(b)
        } else {
            let s = self.parse_statement(false)?;
            Ok(vec![s])
        }
    }

    fn parse_stmts_until_brace(&mut self) -> PResult<Vec<Stmt>> {
        let mut v = Vec::new();
        while !self.is_op(Op::RBrace) {
            if matches!(self.peek(), T::Eof) {
                return self.unexpected();
            }
            v.push(self.parse_statement(true)?);
        }
        self.advance();
        Ok(v)
    }

    fn parse_stmts_until_kw(&mut self, kws: &[&str]) -> PResult<Vec<Stmt>> {
        let mut v = Vec::new();
        loop {
            if kws.iter().any(|k| self.is_kw(k)) {
                break;
            }
            if matches!(self.peek(), T::Eof) {
                return self.unexpected();
            }
            v.push(self.parse_statement(true)?);
        }
        Ok(v)
    }

    fn skip_attributes(&mut self) -> PResult<Vec<Attribute>> {
        let mut attrs = Vec::new();
        while self.is_op(Op::AttrOpen) {
            self.advance();
            loop {
                if self.is_op(Op::RBracket) {
                    self.advance();
                    break;
                }
                let name = self.parse_class_name_raw()?;
                let args = if self.is_op(Op::LParen) { self.parse_args()?.0 } else { Vec::new() };
                attrs.push(Attribute { name: Rc::from(name.as_str()), args });
                if !self.accept_op(Op::Comma) {
                    self.expect_op(Op::RBracket)?;
                    break;
                }
            }
        }
        Ok(attrs)
    }

    fn parse_class_name_raw(&mut self) -> PResult<String> {
        match self.peek().clone() {
            T::Ident(n) => {
                self.advance();
                Ok(self.resolve_class(&n, None))
            }
            T::Name(n, k) => {
                self.advance();
                Ok(self.resolve_class(&n, Some(k)))
            }
            _ => self.unexpected(),
        }
    }

    pub fn parse_statement(&mut self, top: bool) -> PResult<Stmt> {
        let line = self.line();
        let t = self.peek().clone();
        let kind = match &t {
            T::InlineHtml(h) => {
                let h = h.clone();
                self.advance();
                StmtKind::InlineHtml(Rc::new(h))
            }
            T::OpenTagEcho => {
                self.advance();
                let mut exprs = vec![self.parse_expr()?];
                while self.accept_op(Op::Comma) {
                    exprs.push(self.parse_expr()?);
                }
                self.expect_semi()?;
                StmtKind::Echo(exprs)
            }
            T::CloseTag => {
                self.advance();
                StmtKind::Nop
            }
            T::Op(Op::Semi) => {
                self.advance();
                StmtKind::Nop
            }
            T::Op(Op::LBrace) => {
                self.advance();
                StmtKind::Block(self.parse_stmts_until_brace()?)
            }
            T::Op(Op::AttrOpen) => {
                let attrs = self.skip_attributes()?;
                // followed by function/class/etc
                let mut s = self.parse_statement(top)?;
                match &mut s.kind {
                    StmtKind::FuncDecl(_) | StmtKind::ClassDecl(_) => {}
                    _ => {}
                }
                let _ = attrs;
                return Ok(s);
            }
            T::Ident(id) => {
                let l = id.to_ascii_lowercase();
                match l.as_str() {
                    "echo" => {
                        self.advance();
                        let mut exprs = vec![self.parse_expr()?];
                        while self.accept_op(Op::Comma) {
                            exprs.push(self.parse_expr()?);
                        }
                        self.expect_semi()?;
                        StmtKind::Echo(exprs)
                    }
                    "if" => self.parse_if()?,
                    "while" => {
                        self.advance();
                        self.expect_op(Op::LParen)?;
                        let c = self.parse_expr()?;
                        self.expect_op(Op::RParen)?;
                        let body = if self.accept_op(Op::Colon) {
                            let b = self.parse_stmts_until_kw(&["endwhile"])?;
                            self.advance();
                            self.expect_semi()?;
                            b
                        } else {
                            self.parse_block_or_statement()?
                        };
                        StmtKind::While(c, body)
                    }
                    "do" => {
                        self.advance();
                        let body = self.parse_block_or_statement()?;
                        if !self.accept_kw("while") {
                            return self.unexpected_expecting("\"while\"");
                        }
                        self.expect_op(Op::LParen)?;
                        let c = self.parse_expr()?;
                        self.expect_op(Op::RParen)?;
                        self.expect_semi()?;
                        StmtKind::DoWhile(body, c)
                    }
                    "for" => {
                        self.advance();
                        self.expect_op(Op::LParen)?;
                        let init = self.parse_expr_list(Op::Semi)?;
                        self.expect_op(Op::Semi)?;
                        let cond = self.parse_expr_list(Op::Semi)?;
                        self.expect_op(Op::Semi)?;
                        let step = self.parse_expr_list(Op::RParen)?;
                        self.expect_op(Op::RParen)?;
                        let body = if self.accept_op(Op::Colon) {
                            let b = self.parse_stmts_until_kw(&["endfor"])?;
                            self.advance();
                            self.expect_semi()?;
                            b
                        } else {
                            self.parse_block_or_statement()?
                        };
                        StmtKind::For(init, cond, step, body)
                    }
                    "foreach" => self.parse_foreach()?,
                    "switch" => self.parse_switch()?,
                    "break" | "continue" => {
                        self.advance();
                        let mut n = 1;
                        if let T::Int(i) = self.peek() {
                            n = *i as u32;
                            self.advance();
                        }
                        self.expect_semi()?;
                        if l == "break" {
                            StmtKind::Break(n)
                        } else {
                            StmtKind::Continue(n)
                        }
                    }
                    "return" => {
                        self.advance();
                        if self.is_op(Op::Semi) || matches!(self.peek(), T::CloseTag | T::Eof) {
                            self.expect_semi()?;
                            StmtKind::Return(None)
                        } else {
                            let e = self.parse_expr()?;
                            self.expect_semi()?;
                            StmtKind::Return(Some(e))
                        }
                    }
                    "global" => {
                        self.advance();
                        let mut vars = Vec::new();
                        loop {
                            let e = self.parse_simple_variable()?;
                            vars.push(e);
                            if !self.accept_op(Op::Comma) {
                                break;
                            }
                        }
                        self.expect_semi()?;
                        StmtKind::Global(vars)
                    }
                    "static" if matches!(self.peek_at(1), T::Var(_)) => {
                        self.advance();
                        let mut vars = Vec::new();
                        loop {
                            let l2 = self.line();
                            let name = match self.advance().t {
                                T::Var(n) => n,
                                _ => return self.unexpected(),
                            };
                            let vr = self.var_ref(&name);
                            let init = if self.accept_op(Op::Assign) { Some(self.parse_expr()?) } else { None };
                            vars.push((vr, init, l2));
                            if !self.accept_op(Op::Comma) {
                                break;
                            }
                        }
                        self.expect_semi()?;
                        StmtKind::Static(vars)
                    }
                    "unset" if matches!(self.peek_at(1), T::Op(Op::LParen)) => {
                        self.advance();
                        self.advance();
                        let mut vars = Vec::new();
                        while !self.is_op(Op::RParen) {
                            vars.push(self.parse_expr()?);
                            if !self.accept_op(Op::Comma) {
                                break;
                            }
                        }
                        self.expect_op(Op::RParen)?;
                        self.expect_semi()?;
                        StmtKind::Unset(vars)
                    }
                    "function" if matches!(self.peek_at(1), T::Ident(_)) || (matches!(self.peek_at(1), T::Op(Op::Amp)) && matches!(self.peek_at(2), T::Ident(_))) => {
                        self.advance();
                        let by_ref = self.accept_op(Op::Amp);
                        let name = self.expect_ident()?;
                        let fq = self.ns_prefix(&name);
                        let f = self.parse_function_rest(Rc::from(fq.as_str()), by_ref, false, false, line, None)?;
                        StmtKind::FuncDecl(f)
                    }
                    "abstract" | "final" | "class" | "interface" | "trait" | "readonly"
                        if self.looks_like_class_decl() =>
                    {
                        let c = self.parse_class_decl()?;
                        StmtKind::ClassDecl(c)
                    }
                    "enum" if matches!(self.peek_at(1), T::Ident(_)) && !matches!(self.peek_at(2), T::Op(Op::LParen) | T::Op(Op::DoubleColon)) => {
                        let c = self.parse_class_decl()?;
                        StmtKind::ClassDecl(c)
                    }
                    "try" => self.parse_try()?,
                    "namespace" if !matches!(self.peek_at(1), T::Op(Op::Backslash)) && !matches!(self.peek_at(1), T::Name(_, NameKind::Relative)) => {
                        let mut v = Vec::new();
                        self.parse_namespace(&mut v)?;
                        StmtKind::Block(v)
                    }
                    "use" => {
                        self.parse_use()?;
                        StmtKind::Nop
                    }
                    "const" => {
                        self.advance();
                        let mut items = Vec::new();
                        loop {
                            let n = self.expect_ident()?;
                            self.expect_op(Op::Assign)?;
                            let e = self.parse_expr()?;
                            items.push((Rc::from(self.ns_prefix(&n).as_str()), e));
                            if !self.accept_op(Op::Comma) {
                                break;
                            }
                        }
                        self.expect_semi()?;
                        StmtKind::Const(items)
                    }
                    "declare" => {
                        self.advance();
                        self.expect_op(Op::LParen)?;
                        let mut items = Vec::new();
                        loop {
                            let n = self.expect_ident()?;
                            self.expect_op(Op::Assign)?;
                            let e = self.parse_expr()?;
                            if n.eq_ignore_ascii_case("strict_types") {
                                if let ExprKind::Lit(Value::Int(1)) = e.kind {
                                    self.strict_types = true;
                                }
                            }
                            items.push((n, e));
                            if !self.accept_op(Op::Comma) {
                                break;
                            }
                        }
                        self.expect_op(Op::RParen)?;
                        if self.accept_op(Op::Colon) {
                            let b = self.parse_stmts_until_kw(&["enddeclare"])?;
                            self.advance();
                            self.expect_semi()?;
                            StmtKind::Declare(items, Some(b))
                        } else if self.is_op(Op::LBrace) {
                            self.advance();
                            let b = self.parse_stmts_until_brace()?;
                            StmtKind::Declare(items, Some(b))
                        } else {
                            self.expect_semi()?;
                            StmtKind::Declare(items, None)
                        }
                    }
                    "goto" => {
                        self.advance();
                        let n = self.expect_ident()?;
                        self.expect_semi()?;
                        StmtKind::Goto(n)
                    }
                    _ => {
                        // label?
                        if matches!(self.peek_at(1), T::Op(Op::Colon)) && !is_keyword(&l) && top {
                            let n = id.clone();
                            self.advance();
                            self.advance();
                            StmtKind::Label(n)
                        } else {
                            let e = self.parse_expr()?;
                            self.expect_semi()?;
                            StmtKind::Expr(e)
                        }
                    }
                }
            }
            _ => {
                let e = self.parse_expr()?;
                self.expect_semi()?;
                StmtKind::Expr(e)
            }
        };
        Ok(Stmt { kind, line })
    }

    fn looks_like_class_decl(&self) -> bool {
        let mut i = 0;
        loop {
            match self.peek_at(i) {
                T::Ident(s) => {
                    let l = s.to_ascii_lowercase();
                    match l.as_str() {
                        "abstract" | "final" | "readonly" => i += 1,
                        "class" | "interface" | "trait" => return matches!(self.peek_at(i + 1), T::Ident(_)),
                        _ => return false,
                    }
                }
                _ => return false,
            }
        }
    }

    fn parse_use(&mut self) -> PResult<()> {
        self.advance(); // use
        let mut kind = 0; // 0 class, 1 function, 2 const
        if self.is_kw("function") {
            kind = 1;
            self.advance();
        } else if self.is_kw("const") {
            kind = 2;
            self.advance();
        }
        loop {
            let name = match self.advance().t {
                T::Ident(n) => n.to_string(),
                T::Name(n, NameKind::Qualified) => n.to_string(),
                T::Name(n, NameKind::FullyQualified) => n.to_string(),
                _ => return self.unexpected(),
            };
            if self.is_op(Op::Backslash) || self.is_op(Op::LBrace) {
                // group use
                self.accept_op(Op::Backslash);
                self.expect_op(Op::LBrace)?;
                loop {
                    if self.is_op(Op::RBrace) {
                        break;
                    }
                    let mut k = kind;
                    if self.is_kw("function") {
                        k = 1;
                        self.advance();
                    } else if self.is_kw("const") {
                        k = 2;
                        self.advance();
                    }
                    let sub = match self.advance().t {
                        T::Ident(n) => n.to_string(),
                        T::Name(n, NameKind::Qualified) => n.to_string(),
                        _ => return self.unexpected(),
                    };
                    let full = format!("{}\\{}", name, sub);
                    let alias = if self.accept_kw("as") { self.expect_ident()?.to_string() } else { sub.rsplit('\\').next().unwrap().to_string() };
                    self.add_use(k, full, alias);
                    if !self.accept_op(Op::Comma) {
                        break;
                    }
                }
                self.expect_op(Op::RBrace)?;
            } else {
                let alias = if self.accept_kw("as") { self.expect_ident()?.to_string() } else { name.rsplit('\\').next().unwrap().to_string() };
                self.add_use(kind, name, alias);
            }
            if !self.accept_op(Op::Comma) {
                break;
            }
        }
        self.expect_semi()?;
        Ok(())
    }

    fn add_use(&mut self, kind: i32, full: String, alias: String) {
        match kind {
            0 => {
                self.use_class.insert(alias.to_ascii_lowercase(), full);
            }
            1 => {
                self.use_func.insert(alias.to_ascii_lowercase(), full);
            }
            _ => {
                self.use_const.insert(alias, full);
            }
        }
    }

    fn parse_if(&mut self) -> PResult<StmtKind> {
        self.advance(); // if
        self.expect_op(Op::LParen)?;
        let cond = self.parse_expr()?;
        self.expect_op(Op::RParen)?;
        let mut branches = Vec::new();
        let mut els = None;
        if self.accept_op(Op::Colon) {
            // alt syntax
            let body = self.parse_stmts_until_kw(&["elseif", "else", "endif"])?;
            branches.push((cond, body));
            loop {
                if self.accept_kw("elseif") {
                    self.expect_op(Op::LParen)?;
                    let c = self.parse_expr()?;
                    self.expect_op(Op::RParen)?;
                    self.expect_op(Op::Colon)?;
                    let b = self.parse_stmts_until_kw(&["elseif", "else", "endif"])?;
                    branches.push((c, b));
                } else if self.accept_kw("else") {
                    if self.is_kw("if") {
                        // else if in alt syntax
                        self.advance();
                        self.expect_op(Op::LParen)?;
                        let c = self.parse_expr()?;
                        self.expect_op(Op::RParen)?;
                        self.expect_op(Op::Colon)?;
                        let b = self.parse_stmts_until_kw(&["elseif", "else", "endif"])?;
                        branches.push((c, b));
                        continue;
                    }
                    self.expect_op(Op::Colon)?;
                    let b = self.parse_stmts_until_kw(&["endif"])?;
                    els = Some(b);
                } else {
                    break;
                }
            }
            if !self.accept_kw("endif") {
                return self.unexpected_expecting("\"endif\"");
            }
            self.expect_semi()?;
            return Ok(StmtKind::If(branches, els));
        }
        let body = self.parse_block_or_statement()?;
        branches.push((cond, body));
        loop {
            if self.is_kw("elseif") {
                self.advance();
                self.expect_op(Op::LParen)?;
                let c = self.parse_expr()?;
                self.expect_op(Op::RParen)?;
                let b = self.parse_block_or_statement()?;
                branches.push((c, b));
            } else if self.is_kw("else") {
                self.advance();
                if self.is_kw("if") {
                    let line = self.line();
                    let s = self.parse_if()?;
                    els = Some(vec![Stmt { kind: s, line }]);
                    break;
                }
                els = Some(self.parse_block_or_statement()?);
                break;
            } else {
                break;
            }
        }
        Ok(StmtKind::If(branches, els))
    }

    fn parse_foreach(&mut self) -> PResult<StmtKind> {
        self.advance();
        self.expect_op(Op::LParen)?;
        let subject = self.parse_expr()?;
        if !self.accept_kw("as") {
            return self.unexpected_expecting("\"as\"");
        }
        let mut by_ref = self.accept_op(Op::Amp);
        let first = self.parse_foreach_target()?;
        let (key, value) = if self.accept_op(Op::DoubleArrow) {
            by_ref = self.accept_op(Op::Amp);
            let v = self.parse_foreach_target()?;
            (Some(first), v)
        } else {
            (None, first)
        };
        self.expect_op(Op::RParen)?;
        let body = if self.accept_op(Op::Colon) {
            let b = self.parse_stmts_until_kw(&["endforeach"])?;
            self.advance();
            self.expect_semi()?;
            b
        } else {
            self.parse_block_or_statement()?
        };
        Ok(StmtKind::Foreach { subject, key, value, by_ref, body })
    }

    fn parse_foreach_target(&mut self) -> PResult<Expr> {
        let e = self.parse_expr_bp(P_ASSIGN + 1)?;
        Ok(self.to_list_if_array(e))
    }

    fn to_list_if_array(&self, e: Expr) -> Expr {
        match e.kind {
            ExprKind::Array(items) => {
                let line = e.line;
                let mut out = Vec::new();
                for it in items {
                    if let ExprKind::Lit(Value::Undef) = it.value.kind {
                        out.push(None);
                        continue;
                    }
                    let target = self.to_list_if_array(it.value);
                    out.push(Some(ListItem { key: it.key, target, by_ref: it.by_ref }));
                }
                Expr { kind: ExprKind::List(out, true), line }
            }
            k => Expr { kind: k, line: e.line },
        }
    }

    fn parse_switch(&mut self) -> PResult<StmtKind> {
        self.advance();
        self.expect_op(Op::LParen)?;
        let subj = self.parse_expr()?;
        self.expect_op(Op::RParen)?;
        let alt = if self.accept_op(Op::Colon) {
            true
        } else {
            self.expect_op(Op::LBrace)?;
            false
        };
        let mut cases = Vec::new();
        loop {
            if alt && self.is_kw("endswitch") {
                self.advance();
                self.expect_semi()?;
                break;
            }
            if !alt && self.accept_op(Op::RBrace) {
                break;
            }
            let cond = if self.accept_kw("case") {
                Some(self.parse_expr()?)
            } else if self.accept_kw("default") {
                None
            } else if self.accept_op(Op::Semi) {
                continue;
            } else {
                return self.unexpected();
            };
            if !self.accept_op(Op::Colon) && !self.accept_op(Op::Semi) {
                return self.unexpected_expecting("\":\"");
            }
            let mut body = Vec::new();
            loop {
                if self.is_kw("case") || self.is_kw("default") || self.is_op(Op::RBrace) || self.is_kw("endswitch") {
                    break;
                }
                if matches!(self.peek(), T::Eof) {
                    return self.unexpected();
                }
                body.push(self.parse_statement(true)?);
            }
            cases.push(Case { cond, body });
        }
        Ok(StmtKind::Switch(subj, cases))
    }

    fn parse_try(&mut self) -> PResult<StmtKind> {
        self.advance();
        self.expect_op(Op::LBrace)?;
        let body = self.parse_stmts_until_brace()?;
        let mut catches = Vec::new();
        let mut finally = None;
        loop {
            if self.accept_kw("catch") {
                self.expect_op(Op::LParen)?;
                let mut types = Vec::new();
                loop {
                    let n = self.parse_class_name_raw()?;
                    types.push(Rc::from(n.as_str()));
                    if !self.accept_op(Op::Pipe) {
                        break;
                    }
                }
                let var = if let T::Var(n) = self.peek().clone() {
                    self.advance();
                    Some(self.var_ref(&n))
                } else {
                    None
                };
                self.expect_op(Op::RParen)?;
                self.expect_op(Op::LBrace)?;
                let b = self.parse_stmts_until_brace()?;
                catches.push(Catch { types, var, body: b });
            } else if self.accept_kw("finally") {
                self.expect_op(Op::LBrace)?;
                finally = Some(self.parse_stmts_until_brace()?);
                break;
            } else {
                break;
            }
        }
        if catches.is_empty() && finally.is_none() {
            return self.err("Cannot use try without catch or finally");
        }
        Ok(StmtKind::Try(body, catches, finally))
    }

    // ---------- types ----------
    fn parse_type(&mut self) -> PResult<TypeHint> {
        if self.accept_op(Op::Question) {
            let t = self.parse_single_type()?;
            return Ok(TypeHint::Nullable(Box::new(t)));
        }
        let first = self.parse_type_atom()?;
        if self.is_op(Op::Pipe) {
            let mut v = vec![first];
            while self.accept_op(Op::Pipe) {
                v.push(self.parse_type_atom()?);
            }
            return Ok(TypeHint::Union(v));
        }
        if self.is_op(Op::Amp) && !matches!(self.peek_at(1), T::Var(_)) && !matches!(self.peek_at(1), T::Op(Op::Ellipsis)) {
            let mut v = vec![first];
            while self.is_op(Op::Amp) && !matches!(self.peek_at(1), T::Var(_)) && !matches!(self.peek_at(1), T::Op(Op::Ellipsis)) {
                self.advance();
                v.push(self.parse_single_type()?);
            }
            return Ok(TypeHint::Intersection(v));
        }
        Ok(first)
    }
    fn parse_type_atom(&mut self) -> PResult<TypeHint> {
        if self.accept_op(Op::LParen) {
            let mut v = vec![self.parse_single_type()?];
            while self.accept_op(Op::Amp) {
                v.push(self.parse_single_type()?);
            }
            self.expect_op(Op::RParen)?;
            return Ok(TypeHint::Intersection(v));
        }
        self.parse_single_type()
    }
    fn parse_single_type(&mut self) -> PResult<TypeHint> {
        match self.peek().clone() {
            T::Ident(n) => {
                self.advance();
                let l = n.to_ascii_lowercase();
                if RESERVED_TYPES.contains(&l.as_str()) {
                    if l == "self" || l == "parent" {
                        return Ok(TypeHint::Simple(Rc::from(l.as_str())));
                    }
                    return Ok(TypeHint::Simple(Rc::from(l.as_str())));
                }
                Ok(TypeHint::Simple(Rc::from(self.resolve_class(&n, None).as_str())))
            }
            T::Name(n, k) => {
                self.advance();
                Ok(TypeHint::Simple(Rc::from(self.resolve_class(&n, Some(k)).as_str())))
            }
            _ => self.unexpected(),
        }
    }

    fn at_type_start(&self) -> bool {
        match self.peek() {
            T::Ident(_) | T::Name(_, _) => true,
            T::Op(Op::Question) | T::Op(Op::LParen) => true,
            _ => false,
        }
    }

    // ---------- functions ----------
    fn parse_params(&mut self) -> PResult<Vec<Param>> {
        self.expect_op(Op::LParen)?;
        let mut params = Vec::new();
        while !self.is_op(Op::RParen) {
            let attrs = self.skip_attributes()?;
            let mut promote: Option<(Visibility, bool, Option<Visibility>)> = None;
            loop {
                let t = self.peek().clone();
                if let T::Ident(n) = &t {
                    let l = n.to_ascii_lowercase();
                    let vis = match l.as_str() {
                        "public" => Some(Visibility::Public),
                        "protected" => Some(Visibility::Protected),
                        "private" => Some(Visibility::Private),
                        _ => None,
                    };
                    if let Some(v) = vis {
                        self.advance();
                        if self.is_op(Op::LParen) && kw(self.peek_at(1), "set") {
                            self.advance();
                            self.advance();
                            self.expect_op(Op::RParen)?;
                            let p = promote.get_or_insert((Visibility::Public, false, None));
                            p.2 = Some(v);
                        } else {
                            let p = promote.get_or_insert((v, false, None));
                            p.0 = v;
                        }
                        continue;
                    }
                    if l == "readonly" {
                        self.advance();
                        let p = promote.get_or_insert((Visibility::Public, false, None));
                        p.1 = true;
                        continue;
                    }
                    if l == "final" {
                        self.advance();
                        promote.get_or_insert((Visibility::Public, false, None));
                        continue;
                    }
                }
                break;
            }
            let ty = if !matches!(self.peek(), T::Var(_)) && !self.is_op(Op::Amp) && !self.is_op(Op::Ellipsis) {
                Some(self.parse_type()?)
            } else {
                None
            };
            let by_ref = self.accept_op(Op::Amp);
            let variadic = self.accept_op(Op::Ellipsis);
            let name = match self.advance().t {
                T::Var(n) => n,
                _ => {
                    self.pos -= 1;
                    return self.unexpected_expecting("variable");
                }
            };
            let slot = self.var_ref(&name).slot;
            let default = if self.accept_op(Op::Assign) { Some(self.parse_expr()?) } else { None };
            // property hooks on promoted params
            if promote.is_some() && self.is_op(Op::LBrace) {
                self.skip_balanced_braces()?;
            }
            params.push(Param { name, slot, default, ty, by_ref, variadic, promote, attrs });
            if !self.accept_op(Op::Comma) {
                break;
            }
        }
        self.expect_op(Op::RParen)?;
        Ok(params)
    }

    fn skip_balanced_braces(&mut self) -> PResult<()> {
        let mut depth = 0;
        loop {
            match self.peek() {
                T::Op(Op::LBrace) => depth += 1,
                T::Op(Op::RBrace) => {
                    depth -= 1;
                    if depth == 0 {
                        self.advance();
                        return Ok(());
                    }
                }
                T::Eof => return self.unexpected(),
                _ => {}
            }
            self.advance();
        }
    }

    fn closure_name(&self, line: u32) -> String {
        let m = self.method_ctx.last().cloned().unwrap_or_default();
        let f = self.func_ctx.last().cloned().unwrap_or_default();
        if !m.is_empty() {
            format!("{{closure:{}():{}}}", m, line)
        } else if !f.is_empty() {
            if f.starts_with("{closure") {
                format!("{{closure:{}:{}}}", f, line)
            } else {
                format!("{{closure:{}():{}}}", f, line)
            }
        } else {
            format!("{{closure:{}:{}}}", self.file, line)
        }
    }

    /// parse params + body after name. pushes new scope.
    fn parse_function_rest(
        &mut self,
        name: Name,
        by_ref: bool,
        is_closure: bool,
        is_method: bool,
        line: u32,
        doc: Option<Rc<str>>,
    ) -> PResult<Rc<FuncDecl>> {
        self.scopes.push(Scope::new(false));
        let disp_name: String = name.to_string();
        self.func_ctx.push(disp_name.clone());
        if is_method {
            let cls = self.class_ctx.last().cloned().flatten().map(|c| c.name.to_string()).unwrap_or_default();
            self.method_ctx.push(format!("{}::{}", cls, name));
        } else if is_closure {
            let cur = self.method_ctx.last().cloned().unwrap_or_default();
            if cur.is_empty() {
                self.method_ctx.push(String::new());
            } else {
                self.method_ctx.push(String::new());
            }
        } else {
            self.method_ctx.push(String::new());
        }
        let params = self.parse_params()?;
        let mut uses = Vec::new();
        if is_closure && self.accept_kw("use") {
            self.expect_op(Op::LParen)?;
            while !self.is_op(Op::RParen) {
                let r = self.accept_op(Op::Amp);
                let n = match self.advance().t {
                    T::Var(n) => n,
                    _ => return self.unexpected(),
                };
                uses.push((n, r));
                if !self.accept_op(Op::Comma) {
                    break;
                }
            }
            self.expect_op(Op::RParen)?;
        }
        let mut use_refs = Vec::new();
        for (n, r) in &uses {
            let inner = self.var_ref(n);
            use_refs.push((n.clone(), inner, *r));
        }
        let ret = if self.accept_op(Op::Colon) { Some(self.parse_type()?) } else { None };
        let body = if self.is_op(Op::LBrace) {
            self.advance();
            Some(self.parse_stmts_until_brace()?)
        } else {
            self.expect_semi()?;
            None
        };
        let end_line = self.prev_line();
        self.func_ctx.pop();
        self.method_ctx.pop();
        let sc = self.scopes.pop().unwrap();
        let f = Rc::new(FuncDecl {
            name,
            params,
            body,
            by_ref,
            ret,
            is_generator: sc.is_generator,
            num_slots: sc.names.len() as u32,
            slot_names: Rc::new(sc.names),
            this_used: sc.this_used,
            is_static: false,
            line,
            end_line,
            doc,
            statics: RefCell::new(Vec::new()),
            is_arrow: false,
            is_closure,
            uses_dynamic: sc.uses_dynamic,
            file: self.file.clone(),
            attrs: Vec::new(),
            id: Cell::new(0),
        });
        // register uses in outer scope (store in a side channel)
        if is_closure {
            let mut outer_uses = Vec::new();
            for (n, inner, r) in use_refs {
                let outer = self.var_ref(&n);
                outer_uses.push((outer, inner, r));
            }
            self.pending_uses = Some(outer_uses);
        }
        Ok(f)
    }
}

// hack: pending closure uses passed between functions
impl Parser {
    #[allow(non_upper_case_globals)]
    fn take_uses(&mut self) -> Vec<(VarRef, VarRef, bool)> {
        self.pending_uses.take().unwrap_or_default()
    }
}
