// ---------- classes ----------
impl Parser {
    fn parse_class_decl(&mut self) -> PResult<Rc<ClassDecl>> {
        let line = self.line();
        let doc = self.toks[self.pos].doc.clone();
        let mut is_abstract = false;
        let mut is_final = false;
        let mut is_readonly = false;
        loop {
            if self.accept_kw("abstract") {
                is_abstract = true;
            } else if self.accept_kw("final") {
                is_final = true;
            } else if self.accept_kw("readonly") {
                is_readonly = true;
            } else {
                break;
            }
        }
        let kind = if self.accept_kw("class") {
            ClassKind::Class
        } else if self.accept_kw("interface") {
            ClassKind::Interface
        } else if self.accept_kw("trait") {
            ClassKind::Trait
        } else if self.accept_kw("enum") {
            ClassKind::Enum
        } else {
            return self.unexpected();
        };
        let name = self.expect_ident()?;
        let fq: Name = Rc::from(self.ns_prefix(&name).as_str());
        self.parse_class_body(fq, kind, is_abstract, is_final, is_readonly, line, doc, false)
    }

    fn parse_class_body(
        &mut self,
        fq: Name,
        kind: ClassKind,
        is_abstract: bool,
        is_final: bool,
        is_readonly: bool,
        line: u32,
        doc: Option<Rc<str>>,
        is_anon: bool,
    ) -> PResult<Rc<ClassDecl>> {
        let mut enum_type = None;
        if kind == ClassKind::Enum && self.accept_op(Op::Colon) {
            enum_type = Some(self.parse_type()?);
        }
        let mut parent = None;
        let mut interfaces = Vec::new();
        if self.accept_kw("extends") {
            if kind == ClassKind::Interface {
                loop {
                    let n = self.parse_class_name_raw()?;
                    interfaces.push(Rc::from(n.as_str()));
                    if !self.accept_op(Op::Comma) {
                        break;
                    }
                }
            } else {
                let n = self.parse_class_name_raw()?;
                parent = Some(Rc::from(n.as_str()));
            }
        }
        if self.accept_kw("implements") {
            loop {
                let n = self.parse_class_name_raw()?;
                interfaces.push(Rc::from(n.as_str()));
                if !self.accept_op(Op::Comma) {
                    break;
                }
            }
        }
        self.expect_op(Op::LBrace)?;
        self.class_ctx.push(Some(ClassCtx { name: fq.clone(), is_trait: kind == ClassKind::Trait, parent: parent.clone() }));
        let mut consts = Vec::new();
        let mut props = Vec::new();
        let mut methods = Vec::new();
        let mut traits = Vec::new();
        let mut trait_rules = Vec::new();
        let mut cases = Vec::new();
        let mut member_order = Vec::new();
        while !self.accept_op(Op::RBrace) {
            if matches!(self.peek(), T::Eof) {
                return self.unexpected();
            }
            let attrs = self.skip_attributes()?;
            let mline = self.line();
            let mdoc = self.toks[self.pos].doc.clone();
            if self.is_kw("use") {
                self.advance();
                loop {
                    let n = self.parse_class_name_raw()?;
                    traits.push(Rc::from(n.as_str()));
                    if !self.accept_op(Op::Comma) {
                        break;
                    }
                }
                if self.accept_op(Op::LBrace) {
                    while !self.accept_op(Op::RBrace) {
                        // [Trait::]method insteadof A, B;  |  [Trait::]method as [vis] [alias];
                        let first = match self.advance().t {
                            T::Ident(n) => (n.to_string(), None),
                            T::Name(n, k) => (n.to_string(), Some(k)),
                            _ => return self.unexpected(),
                        };
                        let (tname, mname) = if self.accept_op(Op::DoubleColon) {
                            let m = self.expect_ident()?;
                            (Some(Rc::from(self.resolve_class(&first.0, first.1).as_str())), m)
                        } else {
                            (None, Rc::from(first.0.as_str()))
                        };
                        if self.accept_kw("insteadof") {
                            let mut list = Vec::new();
                            loop {
                                let n = self.parse_class_name_raw()?;
                                list.push(Rc::from(n.as_str()));
                                if !self.accept_op(Op::Comma) {
                                    break;
                                }
                            }
                            trait_rules.push(TraitRule::Insteadof { trait_name: tname, method: mname, instead_of: list });
                        } else if self.accept_kw("as") {
                            let mut vis = None;
                            if self.accept_kw("public") {
                                vis = Some(Visibility::Public);
                            } else if self.accept_kw("protected") {
                                vis = Some(Visibility::Protected);
                            } else if self.accept_kw("private") {
                                vis = Some(Visibility::Private);
                            }
                            let alias = if let T::Ident(n) = self.peek().clone() {
                                self.advance();
                                Some(n)
                            } else {
                                None
                            };
                            trait_rules.push(TraitRule::Alias { trait_name: tname, method: mname, alias, vis });
                        } else {
                            return self.unexpected();
                        }
                        self.expect_semi()?;
                    }
                } else {
                    self.expect_semi()?;
                }
                continue;
            }
            if self.is_kw("case") && kind == ClassKind::Enum {
                self.advance();
                let n = self.expect_ident()?;
                let v = if self.accept_op(Op::Assign) { Some(self.parse_expr()?) } else { None };
                self.expect_semi()?;
                member_order.push((3u8, cases.len()));
                cases.push(EnumCase { name: n, value: v });
                continue;
            }
            // modifiers
            let mut vis = None;
            let mut set_vis = None;
            let mut is_static = false;
            let mut m_abstract = false;
            let mut m_final = false;
            let mut readonly = false;
            loop {
                let t = self.peek().clone();
                if let T::Ident(n) = &t {
                    let l = n.to_ascii_lowercase();
                    let v = match l.as_str() {
                        "public" => Some(Visibility::Public),
                        "protected" => Some(Visibility::Protected),
                        "private" => Some(Visibility::Private),
                        _ => None,
                    };
                    if let Some(v) = v {
                        self.advance();
                        if self.is_op(Op::LParen) && kw(self.peek_at(1), "set") && matches!(self.peek_at(2), T::Op(Op::RParen)) {
                            self.advance();
                            self.advance();
                            self.advance();
                            set_vis = Some(v);
                        } else {
                            vis = Some(v);
                        }
                        continue;
                    }
                    match l.as_str() {
                        "static" => {
                            self.advance();
                            is_static = true;
                            continue;
                        }
                        "abstract" => {
                            self.advance();
                            m_abstract = true;
                            continue;
                        }
                        "final" => {
                            self.advance();
                            m_final = true;
                            continue;
                        }
                        "readonly" => {
                            self.advance();
                            readonly = true;
                            continue;
                        }
                        "var" => {
                            self.advance();
                            vis = Some(Visibility::Public);
                            continue;
                        }
                        _ => {}
                    }
                }
                break;
            }
            if self.is_kw("const") {
                self.advance();
                // optional type
                let mut ty = None;
                if matches!(self.peek_at(1), T::Ident(_)) || matches!(self.peek(), T::Op(Op::Question)) || (matches!(self.peek_at(1), T::Op(Op::Pipe))) {
                    if !matches!(self.peek_at(1), T::Op(Op::Assign)) {
                        ty = Some(self.parse_type()?);
                    }
                }
                loop {
                    let n = self.expect_ident()?;
                    self.expect_op(Op::Assign)?;
                    let e = self.parse_expr()?;
                    member_order.push((0u8, consts.len()));
                    consts.push(ConstDecl { name: n, value: e, vis: vis.unwrap_or(Visibility::Public), is_final: m_final, ty: ty.clone(), doc: mdoc.clone() });
                    if !self.accept_op(Op::Comma) {
                        break;
                    }
                }
                self.expect_semi()?;
                continue;
            }
            if self.is_kw("function") {
                self.advance();
                let by_ref = self.accept_op(Op::Amp);
                let n = match self.advance().t {
                    T::Ident(n) => n,
                    _ => return self.unexpected(),
                };
                let mut f = self.parse_function_rest(n, by_ref, false, true, mline, mdoc)?;
                if is_static {
                    if let Some(fm) = Rc::get_mut(&mut f) {
                        fm.is_static = true;
                    }
                }
                if let Some(fm) = Rc::get_mut(&mut f) {
                    fm.attrs = attrs;
                }
                let is_abs = m_abstract || (kind == ClassKind::Interface);
                member_order.push((2u8, methods.len()));
                methods.push(MethodDecl { func: f, vis: vis.unwrap_or(Visibility::Public), is_static, is_abstract: is_abs, is_final: m_final });
                continue;
            }
            // property
            let ty = if !matches!(self.peek(), T::Var(_)) { Some(self.parse_type()?) } else { None };
            loop {
                let pline = self.line();
                let n = match self.advance().t {
                    T::Var(n) => n,
                    _ => {
                        self.pos -= 1;
                        return self.unexpected_expecting("variable");
                    }
                };
                let default = if self.accept_op(Op::Assign) { Some(self.parse_expr()?) } else { None };
                let mut hooks = Vec::new();
                if self.is_op(Op::LBrace) {
                    hooks = self.parse_prop_hooks(&n, ty.clone())?;
                }
                member_order.push((1u8, props.len()));
                props.push(PropDecl {
                    name: n,
                    default,
                    ty: ty.clone(),
                    vis: vis.unwrap_or(Visibility::Public),
                    set_vis,
                    is_static,
                    readonly: readonly || is_readonly,
                    doc: mdoc.clone(),
                    hooks,
                    is_abstract: m_abstract,
                    is_final: m_final,
                    attrs: Vec::new(),
                    line: pline,
                });
                if !self.accept_op(Op::Comma) {
                    break;
                }
            }
            if !props.last().map(|p| !p.hooks.is_empty()).unwrap_or(false) || self.is_op(Op::Semi) {
                self.expect_semi()?;
            }
            let _ = attrs;
        }
        let end_line = self.prev_line();
        self.class_ctx.pop();
        Ok(Rc::new(ClassDecl {
            name: fq,
            kind,
            parent,
            interfaces,
            is_abstract,
            is_final,
            is_readonly,
            consts,
            props,
            methods,
            traits,
            trait_rules,
            cases,
            enum_type,
            line,
            end_line,
            doc,
            attrs: Vec::new(),
            is_anon,
            file: self.file.clone(),
            declared: Cell::new(false),
            member_order,
        }))
    }

    fn parse_prop_hooks(&mut self, prop: &Name, ty: Option<TypeHint>) -> PResult<Vec<PropHook>> {
        self.expect_op(Op::LBrace)?;
        let mut hooks = Vec::new();
        while !self.accept_op(Op::RBrace) {
            let _ = self.skip_attributes()?;
            while self.accept_kw("final") {}
            let by_ref = self.accept_op(Op::Amp);
            let hline = self.line();
            let kind = self.expect_ident()?;
            let lk: Name = Rc::from(kind.to_ascii_lowercase().as_str());
            self.scopes.push(Scope::new(false));
            let cls = self.class_ctx.last().cloned().flatten().map(|c| c.name.to_string()).unwrap_or_default();
            self.func_ctx.push(format!("${}::{}", prop, lk));
            self.method_ctx.push(format!("{}::${}::{}", cls, prop, lk));
            let mut params = Vec::new();
            if &*lk == "set" {
                if self.is_op(Op::LParen) {
                    params = self.parse_params()?;
                } else {
                    let slot = self.var_ref(&Rc::from("value")).slot;
                    params.push(Param { name: Rc::from("value"), slot, default: None, ty: ty.clone(), by_ref: false, variadic: false, promote: None, attrs: Vec::new() });
                }
            }
            let body;
            let mut is_short = false;
            if self.accept_op(Op::DoubleArrow) {
                let e = self.parse_expr()?;
                self.expect_semi()?;
                let l = e.line;
                body = Some(vec![Stmt { kind: StmtKind::Return(Some(e)), line: l }]);
                is_short = true;
            } else if self.is_op(Op::LBrace) {
                self.advance();
                body = Some(self.parse_stmts_until_brace()?);
            } else {
                self.expect_semi()?;
                body = None;
            }
            self.func_ctx.pop();
            self.method_ctx.pop();
            let sc = self.scopes.pop().unwrap();
            let f = Rc::new(FuncDecl {
                name: Rc::from(format!("${}::{}", prop, lk).as_str()),
                params,
                body,
                by_ref,
                ret: None,
                is_generator: sc.is_generator,
                num_slots: sc.names.len() as u32,
                slot_names: Rc::new(sc.names),
                this_used: true,
                is_static: false,
                line: hline,
                end_line: self.prev_line(),
                doc: None,
                statics: RefCell::new(Vec::new()),
                is_arrow: is_short,
                is_closure: false,
                uses_dynamic: false,
                file: self.file.clone(),
                attrs: Vec::new(),
                id: Cell::new(0),
            });
            hooks.push(PropHook { kind: lk, func: f, by_ref });
        }
        Ok(hooks)
    }
}

// ---------- expressions ----------
fn binop_info(t: &T) -> Option<(u8, bool, BinOp)> {
    // (prec, right_assoc, op)
    let r = match t {
        T::Op(o) => match o {
            Op::BoolOr => (P_BOOLOR, false, BinOp::Or),
            Op::BoolAnd => (P_BOOLAND, false, BinOp::And),
            Op::Pipe => (P_BITOR, false, BinOp::BitOr),
            Op::Caret => (P_BITXOR, false, BinOp::BitXor),
            Op::Amp => (P_BITAND, false, BinOp::BitAnd),
            Op::Eq => (P_EQUALITY, false, BinOp::Eq),
            Op::NotEq => (P_EQUALITY, false, BinOp::NotEq),
            Op::Identical => (P_EQUALITY, false, BinOp::Identical),
            Op::NotIdentical => (P_EQUALITY, false, BinOp::NotIdentical),
            Op::Spaceship => (P_EQUALITY, false, BinOp::Spaceship),
            Op::Lt => (P_COMPARE, false, BinOp::Lt),
            Op::Gt => (P_COMPARE, false, BinOp::Gt),
            Op::Le => (P_COMPARE, false, BinOp::Le),
            Op::Ge => (P_COMPARE, false, BinOp::Ge),
            Op::Dot => (P_CONCAT, false, BinOp::Concat),
            Op::Shl => (P_SHIFT, false, BinOp::Shl),
            Op::Shr => (P_SHIFT, false, BinOp::Shr),
            Op::Plus => (P_ADD, false, BinOp::Add),
            Op::Minus => (P_ADD, false, BinOp::Sub),
            Op::Mul => (P_MUL, false, BinOp::Mul),
            Op::Div => (P_MUL, false, BinOp::Div),
            Op::Mod => (P_MUL, false, BinOp::Mod),
            Op::Pow => (P_POW, true, BinOp::Pow),
            _ => return None,
        },
        T::Ident(s) => {
            if s.eq_ignore_ascii_case("or") {
                (P_OR, false, BinOp::Or)
            } else if s.eq_ignore_ascii_case("and") {
                (P_AND, false, BinOp::And)
            } else if s.eq_ignore_ascii_case("xor") {
                (P_XOR, false, BinOp::Xor)
            } else {
                return None;
            }
        }
        _ => return None,
    };
    Some(r)
}

fn assign_op(t: &T) -> Option<Option<BinOp>> {
    match t {
        T::Op(o) => match o {
            Op::Assign => Some(None),
            Op::PlusAssign => Some(Some(BinOp::Add)),
            Op::MinusAssign => Some(Some(BinOp::Sub)),
            Op::MulAssign => Some(Some(BinOp::Mul)),
            Op::DivAssign => Some(Some(BinOp::Div)),
            Op::ConcatAssign => Some(Some(BinOp::Concat)),
            Op::ModAssign => Some(Some(BinOp::Mod)),
            Op::PowAssign => Some(Some(BinOp::Pow)),
            Op::AndAssign => Some(Some(BinOp::BitAnd)),
            Op::OrAssign => Some(Some(BinOp::BitOr)),
            Op::XorAssign => Some(Some(BinOp::BitXor)),
            Op::ShlAssign => Some(Some(BinOp::Shl)),
            Op::ShrAssign => Some(Some(BinOp::Shr)),
            _ => None,
        },
        _ => None,
    }
}

fn is_lvalue(e: &Expr) -> bool {
    match &e.kind {
        ExprKind::Var(_) | ExprKind::VarVar(_) | ExprKind::Index(..) | ExprKind::StaticProp(..) | ExprKind::List(..) | ExprKind::This => true,
        ExprKind::Prop(_, _, nullsafe) => !*nullsafe,
        ExprKind::Array(_) => true,
        _ => false,
    }
}

impl Parser {
    pub fn parse_expr(&mut self) -> PResult<Expr> {
        self.parse_expr_bp(P_LOWEST)
    }

    fn parse_expr_list(&mut self, end: Op) -> PResult<Vec<Expr>> {
        let mut v = Vec::new();
        if self.is_op(end) {
            return Ok(v);
        }
        loop {
            v.push(self.parse_expr()?);
            if !self.accept_op(Op::Comma) {
                break;
            }
        }
        Ok(v)
    }

    fn parse_expr_bp(&mut self, min: u8) -> PResult<Expr> {
        let mut left = self.parse_unary()?;
        loop {
            let t = self.peek().clone();
            let line = self.line();
            if let Some(aop) = assign_op(&t) {
                if is_lvalue(&left) {
                    self.advance();
                    let target = if matches!(left.kind, ExprKind::Array(_)) { self.to_list_if_array(left) } else { left };
                    match aop {
                        None => {
                            if self.is_op(Op::Amp) {
                                self.advance();
                                let rhs = self.parse_expr_bp(P_ASSIGN)?;
                                left = self.mk(ExprKind::AssignRef(Box::new(target), Box::new(rhs)), line);
                            } else {
                                let rhs = self.parse_expr_bp(P_ASSIGN)?;
                                left = self.mk(ExprKind::Assign(Box::new(target), Box::new(rhs)), line);
                            }
                        }
                        Some(op) => {
                            let rhs = self.parse_expr_bp(P_ASSIGN)?;
                            left = self.mk(ExprKind::AssignOp(op, Box::new(target), Box::new(rhs)), line);
                        }
                    }
                    continue;
                }
            }
            if let T::Op(Op::CoalesceAssign) = t {
                if is_lvalue(&left) {
                    self.advance();
                    let rhs = self.parse_expr_bp(P_ASSIGN)?;
                    left = self.mk(ExprKind::CoalesceAssign(Box::new(left), Box::new(rhs)), line);
                    continue;
                }
            }
            match &t {
                T::Op(Op::Question) => {
                    if P_TERNARY < min {
                        break;
                    }
                    self.advance();
                    if self.accept_op(Op::Colon) {
                        let rhs = self.parse_expr_bp(P_TERNARY + 1)?;
                        left = self.mk(ExprKind::Ternary(Box::new(left), None, Box::new(rhs)), line);
                    } else {
                        let mid = self.parse_expr_bp(P_LOWEST)?;
                        self.expect_op(Op::Colon)?;
                        let rhs = self.parse_expr_bp(P_TERNARY + 1)?;
                        left = self.mk(ExprKind::Ternary(Box::new(left), Some(Box::new(mid)), Box::new(rhs)), line);
                    }
                    continue;
                }
                T::Op(Op::Coalesce) => {
                    if P_COALESCE < min {
                        break;
                    }
                    self.advance();
                    let rhs = self.parse_expr_bp(P_COALESCE)?;
                    left = self.mk(ExprKind::Coalesce(Box::new(left), Box::new(rhs)), line);
                    continue;
                }
                T::Op(Op::PipeGt) => {
                    if P_PIPE < min {
                        break;
                    }
                    self.advance();
                    let rhs = self.parse_expr_bp(P_PIPE + 1)?;
                    left = self.mk(ExprKind::Pipe(Box::new(left), Box::new(rhs)), line);
                    continue;
                }
                T::Ident(s) if s.eq_ignore_ascii_case("instanceof") => {
                    if P_INSTANCEOF < min {
                        break;
                    }
                    self.advance();
                    let cref = self.parse_class_ref_for_instanceof()?;
                    left = self.mk(ExprKind::InstanceOf(Box::new(left), cref), line);
                    continue;
                }
                _ => {}
            }
            if let Some((prec, right, op)) = binop_info(&t) {
                if prec < min {
                    break;
                }
                self.advance();
                let rhs = self.parse_expr_bp(if right { prec } else { prec + 1 })?;
                left = self.mk(ExprKind::Bin(op, Box::new(left), Box::new(rhs)), line);
                continue;
            }
            break;
        }
        Ok(left)
    }

    fn parse_class_ref_for_instanceof(&mut self) -> PResult<ClassRef> {
        match self.peek().clone() {
            T::Ident(n) => {
                self.advance();
                Ok(self.class_ref_from_name(&n, None))
            }
            T::Name(n, k) => {
                self.advance();
                Ok(self.class_ref_from_name(&n, Some(k)))
            }
            _ => {
                let e = self.parse_unary()?;
                Ok(ClassRef::Dynamic(Box::new(e)))
            }
        }
    }

    fn class_ref_from_name(&self, n: &str, k: Option<NameKind>) -> ClassRef {
        if k.is_none() {
            let l = n.to_ascii_lowercase();
            match l.as_str() {
                "self" => return ClassRef::SelfRef,
                "parent" => return ClassRef::Parent,
                "static" => return ClassRef::Static,
                _ => {}
            }
        }
        ClassRef::Named(Rc::from(self.resolve_class(n, k).as_str()))
    }

    fn parse_unary(&mut self) -> PResult<Expr> {
        let line = self.line();
        let t = self.peek().clone();
        match &t {
            T::Op(Op::Not) => {
                self.advance();
                let e = self.parse_expr_bp(P_NOT)?;
                Ok(self.mk(ExprKind::Unary(UnOp::Not, Box::new(e)), line))
            }
            T::Op(Op::Minus) => {
                self.advance();
                let e = self.parse_expr_bp(P_UNARY)?;
                // fold negative literals
                if let ExprKind::Lit(Value::Int(i)) = &e.kind {
                    if !matches!(self.toks[self.pos - 1].t, T::Op(Op::RParen)) {
                        return Ok(self.mk(ExprKind::Lit(Value::Int(i.wrapping_neg())), line));
                    }
                }
                if let ExprKind::Lit(Value::Float(f)) = &e.kind {
                    return Ok(self.mk(ExprKind::Lit(Value::Float(-f)), line));
                }
                Ok(self.mk(ExprKind::Unary(UnOp::Neg, Box::new(e)), line))
            }
            T::Op(Op::Plus) => {
                self.advance();
                let e = self.parse_expr_bp(P_UNARY)?;
                Ok(self.mk(ExprKind::Unary(UnOp::Plus, Box::new(e)), line))
            }
            T::Op(Op::Tilde) => {
                self.advance();
                let e = self.parse_expr_bp(P_UNARY)?;
                Ok(self.mk(ExprKind::Unary(UnOp::BitNot, Box::new(e)), line))
            }
            T::Op(Op::At) => {
                self.advance();
                let e = self.parse_expr_bp(P_UNARY)?;
                Ok(self.mk(ExprKind::Silence(Box::new(e)), line))
            }
            T::Cast(c) => {
                self.advance();
                let k = match *c {
                    "int" => CastKind::Int,
                    "float" => CastKind::Float,
                    "string" => CastKind::String,
                    "bool" => CastKind::Bool,
                    "array" => CastKind::Array,
                    "object" => CastKind::Object,
                    "void" => CastKind::Unset,
                    _ => CastKind::Unset,
                };
                let e = self.parse_expr_bp(P_UNARY)?;
                Ok(self.mk(ExprKind::Cast(k, Box::new(e)), line))
            }
            T::Op(Op::Inc) | T::Op(Op::Dec) => {
                let inc = matches!(t, T::Op(Op::Inc));
                self.advance();
                let e = self.parse_expr_bp(P_UNARY)?;
                Ok(self.mk(ExprKind::IncDec(true, inc, Box::new(e)), line))
            }
            T::Op(Op::Amp) => self.unexpected(),
            T::Ident(id) => {
                let l = id.to_ascii_lowercase();
                match l.as_str() {
                    "new" => {
                        let e = self.parse_new()?;
                        self.parse_postfix(e)
                    }
                    "clone" => {
                        self.advance();
                        if self.is_op(Op::LParen) {
                            // clone(...) function-like syntax (PHP 8.5)
                            let save = self.pos;
                            let (args, _) = self.parse_args()?;
                            if args.len() == 2 || (args.len() == 1 && args[0].name.is_none() && !args[0].unpack) {
                                let mut it = args.into_iter();
                                let a = it.next().unwrap();
                                let e = if let Some(b) = it.next() {
                                    self.mk(ExprKind::CloneWith(Box::new(a.value), Box::new(b.value)), line)
                                } else {
                                    self.mk(ExprKind::Clone(Box::new(a.value)), line)
                                };
                                return self.parse_postfix(e);
                            }
                            self.pos = save;
                        }
                        let e = self.parse_expr_bp(P_POW + 1)?;
                        Ok(self.mk(ExprKind::Clone(Box::new(e)), line))
                    }
                    "print" => {
                        self.advance();
                        let e = self.parse_expr_bp(P_AND + 1)?;
                        Ok(self.mk(ExprKind::Print(Box::new(e)), line))
                    }
                    "yield" => {
                        self.advance();
                        self.scope().is_generator = true;
                        if self.is_kw("from") {
                            self.advance();
                            let e = self.parse_expr_bp(P_AND + 1)?;
                            return Ok(self.mk(ExprKind::YieldFrom(Box::new(e)), line));
                        }
                        if matches!(self.peek(), T::Op(Op::Semi) | T::Op(Op::RParen) | T::Op(Op::Comma) | T::Op(Op::RBracket) | T::CloseTag) {
                            return Ok(self.mk(ExprKind::Yield(None, None), line));
                        }
                        let v = self.parse_expr_bp(P_AND + 1)?;
                        if self.accept_op(Op::DoubleArrow) {
                            let v2 = self.parse_expr_bp(P_AND + 1)?;
                            return Ok(self.mk(ExprKind::Yield(Some(Box::new(v)), Some(Box::new(v2))), line));
                        }
                        Ok(self.mk(ExprKind::Yield(None, Some(Box::new(v))), line))
                    }
                    "throw" => {
                        self.advance();
                        let e = self.parse_expr_bp(P_LOWEST)?;
                        Ok(self.mk(ExprKind::Throw(Box::new(e)), line))
                    }
                    "include" | "include_once" | "require" | "require_once" => {
                        self.advance();
                        let k = match l.as_str() {
                            "include" => IncludeKind::Include,
                            "include_once" => IncludeKind::IncludeOnce,
                            "require" => IncludeKind::Require,
                            _ => IncludeKind::RequireOnce,
                        };
                        let e = self.parse_expr_bp(P_LOWEST)?;
                        self.scope().uses_dynamic = true;
                        Ok(self.mk(ExprKind::Include(k, Box::new(e)), line))
                    }
                    _ => {
                        let e = self.parse_primary()?;
                        self.parse_postfix(e)
                    }
                }
            }
            _ => {
                let e = self.parse_primary()?;
                self.parse_postfix(e)
            }
        }
    }

    fn parse_new(&mut self) -> PResult<Expr> {
        let line = self.line();
        self.advance(); // new
        if self.is_kw("class") {
            // anonymous class
            self.advance();
            let args = if self.is_op(Op::LParen) { self.parse_args()?.0 } else { Vec::new() };
            let name = format!("class@anonymous\0{}:{}${:x}", self.file, line, self.anon_count);
            self.anon_count += 1;
            let decl = self.parse_class_body(Rc::from(name.as_str()), ClassKind::Class, false, false, false, line, None, true)?;
            return Ok(self.mk(ExprKind::NewAnon(decl, args), line));
        }
        let cref = match self.peek().clone() {
            T::Ident(n) if !n.eq_ignore_ascii_case("static") || true => {
                self.advance();
                self.class_ref_from_name(&n, None)
            }
            T::Name(n, k) => {
                self.advance();
                self.class_ref_from_name(&n, Some(k))
            }
            T::Op(Op::LParen) => {
                self.advance();
                let e = self.parse_expr()?;
                self.expect_op(Op::RParen)?;
                ClassRef::Dynamic(Box::new(e))
            }
            T::Var(_) | T::Op(Op::Dollar) => {
                let e = self.parse_new_variable()?;
                ClassRef::Dynamic(Box::new(e))
            }
            _ => return self.unexpected(),
        };
        let args = if self.is_op(Op::LParen) { self.parse_args()?.0 } else { Vec::new() };
        Ok(self.mk(ExprKind::New(cref, args), line))
    }

    fn parse_new_variable(&mut self) -> PResult<Expr> {
        let mut e = self.parse_simple_variable()?;
        loop {
            let line = self.line();
            if self.is_op(Op::LBracket) {
                self.advance();
                let idx = if self.is_op(Op::RBracket) { None } else { Some(Box::new(self.parse_expr()?)) };
                self.expect_op(Op::RBracket)?;
                e = self.mk(ExprKind::Index(Box::new(e), idx), line);
            } else if self.is_op(Op::Arrow) || self.is_op(Op::NullsafeArrow) {
                let ns = self.is_op(Op::NullsafeArrow);
                self.advance();
                let m = self.parse_member_name()?;
                e = self.mk(ExprKind::Prop(Box::new(e), m, ns), line);
            } else if self.is_op(Op::DoubleColon) && matches!(self.peek_at(1), T::Var(_)) {
                self.advance();
                let n = match self.advance().t {
                    T::Var(n) => n,
                    _ => unreachable!(),
                };
                e = self.mk(ExprKind::StaticProp(ClassRef::Dynamic(Box::new(e)), MemberName::Ident(n)), line);
            } else {
                break;
            }
        }
        Ok(e)
    }

    fn parse_simple_variable(&mut self) -> PResult<Expr> {
        let line = self.line();
        match self.peek().clone() {
            T::Var(n) => {
                self.advance();
                if &*n == "this" {
                    self.scope().this_used = true;
                    return Ok(self.mk(ExprKind::This, line));
                }
                let v = self.var_ref(&n);
                Ok(self.mk(ExprKind::Var(v), line))
            }
            T::Op(Op::Dollar) => {
                self.advance();
                self.scope().uses_dynamic = true;
                if self.accept_op(Op::LBrace) {
                    let e = self.parse_expr()?;
                    self.expect_op(Op::RBrace)?;
                    Ok(self.mk(ExprKind::VarVar(Box::new(e)), line))
                } else {
                    let e = self.parse_simple_variable()?;
                    Ok(self.mk(ExprKind::VarVar(Box::new(e)), line))
                }
            }
            _ => self.unexpected_expecting("variable"),
        }
    }

    fn parse_member_name(&mut self) -> PResult<MemberName> {
        match self.peek().clone() {
            T::Ident(n) => {
                self.advance();
                Ok(MemberName::Ident(n))
            }
            T::Var(_) | T::Op(Op::Dollar) => {
                let e = self.parse_simple_variable()?;
                Ok(MemberName::Dynamic(Box::new(e)))
            }
            T::Op(Op::LBrace) => {
                self.advance();
                let e = self.parse_expr()?;
                self.expect_op(Op::RBrace)?;
                Ok(MemberName::Dynamic(Box::new(e)))
            }
            _ => self.unexpected(),
        }
    }

    /// returns (args, is_first_class_callable)
    fn parse_args(&mut self) -> PResult<(Vec<Arg>, bool)> {
        self.expect_op(Op::LParen)?;
        let mut args = Vec::new();
        if self.is_op(Op::Ellipsis) && matches!(self.peek_at(1), T::Op(Op::RParen)) {
            self.advance();
            self.advance();
            return Ok((args, true));
        }
        while !self.is_op(Op::RParen) {
            if self.accept_op(Op::Ellipsis) {
                let e = self.parse_expr()?;
                args.push(Arg { value: e, unpack: true, name: None });
            } else if matches!(self.peek(), T::Ident(_)) && matches!(self.peek_at(1), T::Op(Op::Colon)) && !matches!(self.peek_at(2), T::Op(Op::Colon)) {
                let n = match self.advance().t {
                    T::Ident(n) => n,
                    _ => unreachable!(),
                };
                self.advance();
                let e = self.parse_expr()?;
                args.push(Arg { value: e, unpack: false, name: Some(n) });
            } else {
                let e = self.parse_expr()?;
                args.push(Arg { value: e, unpack: false, name: None });
            }
            if !self.accept_op(Op::Comma) {
                break;
            }
        }
        self.expect_op(Op::RParen)?;
        Ok((args, false))
    }

    fn parse_array_items(&mut self, end: Op) -> PResult<Vec<ArrayItem>> {
        let mut items = Vec::new();
        loop {
            if self.is_op(end) {
                break;
            }
            if self.is_op(Op::Comma) {
                // empty slot (for list)
                let line = self.line();
                self.advance();
                items.push(ArrayItem { key: None, value: self.mk(ExprKind::Lit(Value::Undef), line), by_ref: false, unpack: false });
                continue;
            }
            if self.accept_op(Op::Ellipsis) {
                let e = self.parse_expr()?;
                items.push(ArrayItem { key: None, value: e, by_ref: false, unpack: true });
            } else if self.accept_op(Op::Amp) {
                let e = self.parse_expr()?;
                items.push(ArrayItem { key: None, value: e, by_ref: true, unpack: false });
            } else {
                let e = self.parse_expr()?;
                if self.accept_op(Op::DoubleArrow) {
                    let r = self.accept_op(Op::Amp);
                    let v = self.parse_expr()?;
                    items.push(ArrayItem { key: Some(e), value: v, by_ref: r, unpack: false });
                } else {
                    items.push(ArrayItem { key: None, value: e, by_ref: false, unpack: false });
                }
            }
            if !self.accept_op(Op::Comma) {
                break;
            }
        }
        self.expect_op(end)?;
        Ok(items)
    }

    fn magic(&self, l: &str, line: u32) -> Option<ExprKind> {
        let cls = self.class_ctx.last().cloned().flatten();
        Some(match l {
            "__line__" => ExprKind::Lit(Value::Int(line as i64)),
            "__file__" => ExprKind::Lit(Value::str(&self.file)),
            "__dir__" => {
                let f = &*self.file;
                let d = match f.rfind('/') {
                    Some(0) => "/".to_string(),
                    Some(p) => f[..p].to_string(),
                    None => ".".to_string(),
                };
                ExprKind::Lit(Value::str(&d))
            }
            "__namespace__" => ExprKind::Lit(Value::str(&self.namespace)),
            "__class__" => match &cls {
                Some(c) if c.is_trait => ExprKind::Magic(MagicConst::Class),
                Some(c) => {
                    if c.name.starts_with("class@anonymous") {
                        ExprKind::Magic(MagicConst::Class)
                    } else {
                        ExprKind::Lit(Value::str(&c.name))
                    }
                }
                None => ExprKind::Lit(Value::str("")),
            },
            "__trait__" => match &cls {
                Some(c) if c.is_trait => ExprKind::Lit(Value::str(&c.name)),
                _ => ExprKind::Lit(Value::str("")),
            },
            "__function__" => {
                let f = self.func_ctx.last().cloned().unwrap_or_default();
                ExprKind::Lit(Value::str(&f))
            }
            "__method__" => {
                let m = self.method_ctx.last().cloned().unwrap_or_default();
                if m.is_empty() {
                    let f = self.func_ctx.last().cloned().unwrap_or_default();
                    ExprKind::Lit(Value::str(&f))
                } else {
                    ExprKind::Lit(Value::str(&m))
                }
            }
            "__property__" => ExprKind::Magic(MagicConst::Property),
            _ => return None,
        })
    }

    fn parse_primary(&mut self) -> PResult<Expr> {
        let line = self.line();
        let t = self.peek().clone();
        match t {
            T::Var(_) | T::Op(Op::Dollar) => self.parse_simple_variable(),
            T::Int(i) => {
                self.advance();
                Ok(self.mk(ExprKind::Lit(Value::Int(i)), line))
            }
            T::Float(f) => {
                self.advance();
                Ok(self.mk(ExprKind::Lit(Value::Float(f)), line))
            }
            T::Str(s) => {
                self.advance();
                Ok(self.mk(ExprKind::Lit(Value::vec(s)), line))
            }
            T::Template(parts) => {
                self.advance();
                let p = self.parse_template(parts)?;
                Ok(self.mk(ExprKind::Interp(p), line))
            }
            T::ShellCmd(parts) => {
                self.advance();
                let p = self.parse_template(parts)?;
                Ok(self.mk(ExprKind::ShellExec(p), line))
            }
            T::Op(Op::LParen) => {
                self.advance();
                let e = self.parse_expr()?;
                self.expect_op(Op::RParen)?;
                // mark parenthesized by wrapping? keep as is
                Ok(e)
            }
            T::Op(Op::LBracket) => {
                self.advance();
                let items = self.parse_array_items(Op::RBracket)?;
                Ok(self.mk(ExprKind::Array(items), line))
            }
            T::Op(Op::AttrOpen) => {
                let _ = self.skip_attributes()?;
                self.parse_primary()
            }
            T::Name(n, k) => {
                self.advance();
                self.parse_name_expr(&n, Some(k), line)
            }
            T::Ident(id) => {
                let l = id.to_ascii_lowercase();
                match l.as_str() {
                    "true" | "false" | "null" if !matches!(self.peek_at(1), T::Op(Op::DoubleColon) | T::Op(Op::LParen)) => {
                        self.advance();
                        let v = match l.as_str() {
                            "true" => Value::Bool(true),
                            "false" => Value::Bool(false),
                            _ => Value::Null,
                        };
                        return Ok(self.mk(ExprKind::Lit(v), line));
                    }
                    "array" if matches!(self.peek_at(1), T::Op(Op::LParen)) => {
                        self.advance();
                        self.advance();
                        let items = self.parse_array_items(Op::RParen)?;
                        return Ok(self.mk(ExprKind::Array(items), line));
                    }
                    "list" if matches!(self.peek_at(1), T::Op(Op::LParen)) => {
                        self.advance();
                        self.advance();
                        let items = self.parse_array_items(Op::RParen)?;
                        let mut out = Vec::new();
                        for it in items {
                            if let ExprKind::Lit(Value::Undef) = it.value.kind {
                                out.push(None);
                                continue;
                            }
                            let target = self.to_list_if_array(it.value);
                            out.push(Some(ListItem { key: it.key, target, by_ref: it.by_ref }));
                        }
                        return Ok(self.mk(ExprKind::List(out, false), line));
                    }
                    "isset" => {
                        self.advance();
                        self.expect_op(Op::LParen)?;
                        let mut v = Vec::new();
                        while !self.is_op(Op::RParen) {
                            v.push(self.parse_expr()?);
                            if !self.accept_op(Op::Comma) {
                                break;
                            }
                        }
                        self.expect_op(Op::RParen)?;
                        return Ok(self.mk(ExprKind::Isset(v), line));
                    }
                    "empty" => {
                        self.advance();
                        self.expect_op(Op::LParen)?;
                        let e = self.parse_expr()?;
                        self.expect_op(Op::RParen)?;
                        return Ok(self.mk(ExprKind::Empty(Box::new(e)), line));
                    }
                    "exit" | "die" => {
                        self.advance();
                        let mut arg = None;
                        if self.accept_op(Op::LParen) {
                            if !self.is_op(Op::RParen) {
                                arg = Some(Box::new(self.parse_expr()?));
                            }
                            self.expect_op(Op::RParen)?;
                        }
                        return Ok(self.mk(ExprKind::Exit(arg), line));
                    }
                    "eval" if matches!(self.peek_at(1), T::Op(Op::LParen)) => {
                        self.advance();
                        self.advance();
                        let e = self.parse_expr()?;
                        self.expect_op(Op::RParen)?;
                        self.scope().uses_dynamic = true;
                        return Ok(self.mk(ExprKind::Eval(Box::new(e)), line));
                    }
                    "function" | "fn" => {
                        return self.parse_closure(false);
                    }
                    "static" if kw(self.peek_at(1), "function") || kw(self.peek_at(1), "fn") => {
                        self.advance();
                        return self.parse_closure(true);
                    }
                    "match" if matches!(self.peek_at(1), T::Op(Op::LParen)) => {
                        return self.parse_match();
                    }
                    "new" => return self.parse_new(),
                    _ => {}
                }
                if l.starts_with("__") && l.ends_with("__") {
                    if let Some(k) = self.magic(&l, line) {
                        self.advance();
                        return Ok(self.mk(k, line));
                    }
                }
                self.advance();
                self.parse_name_expr(&id, None, line)
            }
            _ => self.unexpected(),
        }
    }

    fn parse_name_expr(&mut self, n: &str, k: Option<NameKind>, line: u32) -> PResult<Expr> {
        if self.is_op(Op::LParen) {
            let (fname, fb) = self.resolve_func(n, k);
            let lname = fname.to_ascii_lowercase();
            if lname == "compact" || lname == "extract" || lname == "get_defined_vars" || lname == "func_get_args" || lname == "func_get_arg" || lname == "func_num_args" {
                self.scope().uses_dynamic = true;
            }
            let (args, fcc) = self.parse_args()?;
            let fnm = Rc::new(FuncName { name: fname, fallback: fb, cache: RefCell::new(None) });
            let call = self.mk(ExprKind::Call(fnm, args), line);
            if fcc {
                return Ok(self.mk(ExprKind::CallableRef(Box::new(call)), line));
            }
            return Ok(call);
        }
        if self.is_op(Op::DoubleColon) {
            let cref = self.class_ref_from_name(n, k);
            return self.parse_static_member(cref, line);
        }
        // constant
        let (cname, fb) = self.resolve_const(n, k);
        Ok(self.mk(ExprKind::Const(FuncName { name: cname, fallback: fb, cache: RefCell::new(None) }), line))
    }

    fn parse_static_member(&mut self, cref: ClassRef, line: u32) -> PResult<Expr> {
        self.expect_op(Op::DoubleColon)?;
        match self.peek().clone() {
            T::Var(n) => {
                self.advance();
                let e = self.mk(ExprKind::StaticProp(cref, MemberName::Ident(n.clone())), line);
                if self.is_op(Op::LParen) {
                    // A::$name() - variable static method call
                    let ExprKind::StaticProp(cref, _) = e.kind else { unreachable!() };
                    let v = self.var_ref(&n);
                    let name_expr = self.mk(ExprKind::Var(v), line);
                    let (args, fcc) = self.parse_args()?;
                    let call = self.mk(ExprKind::StaticCall(cref, MemberName::Dynamic(Box::new(name_expr)), args), line);
                    if fcc {
                        return Ok(self.mk(ExprKind::CallableRef(Box::new(call)), line));
                    }
                    return Ok(call);
                }
                Ok(e)
            }
            T::Ident(m) => {
                self.advance();
                if self.is_op(Op::LParen) {
                    let (args, fcc) = self.parse_args()?;
                    let call = self.mk(ExprKind::StaticCall(cref, MemberName::Ident(m), args), line);
                    if fcc {
                        return Ok(self.mk(ExprKind::CallableRef(Box::new(call)), line));
                    }
                    return Ok(call);
                }
                Ok(self.mk(ExprKind::ClassConst(cref, MemberName::Ident(m)), line))
            }
            T::Op(Op::LBrace) => {
                self.advance();
                let e = self.parse_expr()?;
                self.expect_op(Op::RBrace)?;
                if self.is_op(Op::LParen) {
                    let (args, fcc) = self.parse_args()?;
                    let call = self.mk(ExprKind::StaticCall(cref, MemberName::Dynamic(Box::new(e)), args), line);
                    if fcc {
                        return Ok(self.mk(ExprKind::CallableRef(Box::new(call)), line));
                    }
                    return Ok(call);
                }
                Ok(self.mk(ExprKind::ClassConst(cref, MemberName::Dynamic(Box::new(e))), line))
            }
            T::Op(Op::Dollar) => {
                let e = self.parse_simple_variable()?;
                Ok(self.mk(ExprKind::StaticProp(cref, MemberName::Dynamic(Box::new(e))), line))
            }
            _ => self.unexpected(),
        }
    }

    fn parse_postfix(&mut self, mut e: Expr) -> PResult<Expr> {
        loop {
            let line = self.line();
            match self.peek() {
                T::Op(Op::LBracket) => {
                    self.advance();
                    let idx = if self.is_op(Op::RBracket) { None } else { Some(Box::new(self.parse_expr()?)) };
                    self.expect_op(Op::RBracket)?;
                    e = self.mk(ExprKind::Index(Box::new(e), idx), line);
                }
                T::Op(Op::LBrace) if false => {}
                T::Op(Op::Arrow) | T::Op(Op::NullsafeArrow) => {
                    let ns = self.is_op(Op::NullsafeArrow);
                    self.advance();
                    let m = self.parse_member_name()?;
                    if self.is_op(Op::LParen) {
                        let (args, fcc) = self.parse_args()?;
                        let call = self.mk(ExprKind::MethodCall(Box::new(e), m, args, ns), line);
                        e = if fcc { self.mk(ExprKind::CallableRef(Box::new(call)), line) } else { call };
                    } else {
                        e = self.mk(ExprKind::Prop(Box::new(e), m, ns), line);
                    }
                }
                T::Op(Op::DoubleColon) => {
                    let cref = ClassRef::Dynamic(Box::new(e));
                    e = self.parse_static_member(cref, line)?;
                }
                T::Op(Op::LParen) => {
                    let (args, fcc) = self.parse_args()?;
                    let call = self.mk(ExprKind::CallExpr(Box::new(e), args), line);
                    e = if fcc { self.mk(ExprKind::CallableRef(Box::new(call)), line) } else { call };
                }
                T::Op(Op::Inc) => {
                    self.advance();
                    e = self.mk(ExprKind::IncDec(false, true, Box::new(e)), line);
                }
                T::Op(Op::Dec) => {
                    self.advance();
                    e = self.mk(ExprKind::IncDec(false, false, Box::new(e)), line);
                }
                _ => break,
            }
        }
        Ok(e)
    }

    fn parse_closure(&mut self, is_static: bool) -> PResult<Expr> {
        let line = self.line();
        let doc = self.toks[self.pos].doc.clone();
        let is_fn = self.is_kw("fn");
        self.advance();
        let by_ref = self.accept_op(Op::Amp);
        let cname = self.closure_name(line);
        if is_fn {
            self.scopes.push(Scope::new(true));
            self.func_ctx.push(cname.clone());
            self.method_ctx.push(String::new());
            let params = self.parse_params()?;
            let ret = if self.accept_op(Op::Colon) { Some(self.parse_type()?) } else { None };
            self.expect_op(Op::DoubleArrow)?;
            let body_e = self.parse_expr_bp(P_LOWEST)?;
            let bl = body_e.line;
            self.func_ctx.pop();
            self.method_ctx.pop();
            let sc = self.scopes.pop().unwrap();
            // captures
            let mut caps = Vec::new();
            let pnames: Vec<Name> = params.iter().map(|p| p.name.clone()).collect();
            for (i, n) in sc.names.iter().enumerate() {
                if pnames.contains(n) {
                    continue;
                }
                let outer = self.scope().slot(n);
                caps.push((outer, i as u32));
            }
            if sc.this_used {
                self.scope().this_used = true;
            }
            let f = Rc::new(FuncDecl {
                name: Rc::from(cname.as_str()),
                params,
                body: Some(vec![Stmt { kind: StmtKind::Return(Some(body_e)), line: bl }]),
                by_ref,
                ret,
                is_generator: sc.is_generator,
                num_slots: sc.names.len() as u32,
                slot_names: Rc::new(sc.names),
                this_used: sc.this_used,
                is_static,
                line,
                end_line: self.prev_line(),
                doc,
                statics: RefCell::new(Vec::new()),
                is_arrow: true,
                is_closure: true,
                uses_dynamic: sc.uses_dynamic,
                file: self.file.clone(),
                attrs: Vec::new(),
                id: Cell::new(0),
            });
            return Ok(self.mk(ExprKind::ArrowFn(f, caps, is_static), line));
        }
        let mut f = self.parse_function_rest(Rc::from(cname.as_str()), by_ref, true, false, line, doc)?;
        if let Some(fm) = Rc::get_mut(&mut f) {
            fm.is_static = is_static;
        }
        if f.this_used {
            self.scope().this_used = true;
        }
        let uses = self.take_uses();
        Ok(self.mk(ExprKind::Closure(f, uses, is_static), line))
    }

    fn parse_match(&mut self) -> PResult<Expr> {
        let line = self.line();
        self.advance();
        self.expect_op(Op::LParen)?;
        let subj = self.parse_expr()?;
        self.expect_op(Op::RParen)?;
        self.expect_op(Op::LBrace)?;
        let mut arms = Vec::new();
        while !self.accept_op(Op::RBrace) {
            let conds = if self.is_kw("default") && matches!(self.peek_at(1), T::Op(Op::DoubleArrow) | T::Op(Op::Comma)) {
                self.advance();
                self.accept_op(Op::Comma);
                None
            } else {
                let mut v = Vec::new();
                loop {
                    v.push(self.parse_expr()?);
                    if !self.accept_op(Op::Comma) {
                        break;
                    }
                    if self.is_op(Op::DoubleArrow) {
                        break;
                    }
                }
                Some(v)
            };
            self.expect_op(Op::DoubleArrow)?;
            let body = self.parse_expr()?;
            arms.push(MatchArm { conds, body });
            if !self.accept_op(Op::Comma) {
                self.expect_op(Op::RBrace)?;
                break;
            }
        }
        Ok(self.mk(ExprKind::Match(Box::new(subj), arms), line))
    }

    fn parse_template(&mut self, parts: Vec<TPart>) -> PResult<Vec<InterpPart>> {
        let mut out = Vec::new();
        for p in parts {
            match p {
                TPart::Lit(l) => out.push(InterpPart::Lit(Rc::new(l))),
                TPart::Expr(mut toks) => {
                    if let Some(first) = toks.first() {
                        if first.doc.as_deref() == Some("${") && matches!(first.t, T::Op(Op::DoubleArrow)) {
                            let l = first.line;
                            toks.remove(0);
                            self.warnings.push(("Deprecated: Using ${var} in strings is deprecated, use {$var} instead".to_string(), l));
                        }
                    }
                    let eof_line = toks.last().map(|t| t.line).unwrap_or(0);
                    toks.push(Token { t: T::Eof, line: eof_line, doc: None });
                    let saved_toks = std::mem::replace(&mut self.toks, toks);
                    let saved_pos = self.pos;
                    self.pos = 0;
                    let r = self.parse_expr();
                    let at_end = matches!(self.peek(), T::Eof);
                    let errline = self.line();
                    let unexpected = if !at_end { Some(tok_desc(self.peek())) } else { None };
                    self.toks = saved_toks;
                    self.pos = saved_pos;
                    let e = r?;
                    if let Some(u) = unexpected {
                        return Err(ParseError { msg: format!("syntax error, unexpected {}", u), line: errline });
                    }
                    out.push(InterpPart::Expr(e));
                }
            }
        }
        Ok(out)
    }
}
EOF
echo ok"}

actions.command:
cd /workspace/src && cat >> parser.rs <<'EOF'

// ---------- classes ----------
impl Parser {
    fn parse_class_decl(&mut self) -> PResult<Rc<ClassDecl>> {
        let line = self.line();
        let doc = self.toks[self.pos].doc.clone();
        let mut is_abstract = false;
        let mut is_final = false;
        let mut is_readonly = false;
        loop {
            if self.accept_kw("abstract") {
                is_abstract = true;
            } else if self.accept_kw("final") {
                is_final = true;
            } else if self.accept_kw("readonly") {
                is_readonly = true;
            } else {
                break;
            }
        }
        let kind = if self.accept_kw("class") {
            ClassKind::Class
        } else if self.accept_kw("interface") {
            ClassKind::Interface
        } else if self.accept_kw("trait") {
            ClassKind::Trait
        } else if self.accept_kw("enum") {
            ClassKind::Enum
        } else {
            return self.unexpected();
        };
        let name = self.expect_ident()?;
        let fq: Name = Rc::from(self.ns_prefix(&name).as_str());
        self.parse_class_body(fq, kind, is_abstract, is_final, is_readonly, line, doc, false)
    }

    fn parse_class_body(
        &mut self,
        fq: Name,
        kind: ClassKind,
        is_abstract: bool,
        is_final: bool,
        is_readonly: bool,
        line: u32,
        doc: Option<Rc<str>>,
        is_anon: bool,
    ) -> PResult<Rc<ClassDecl>> {
        let mut enum_type = None;
        if kind == ClassKind::Enum && self.accept_op(Op::Colon) {
            enum_type = Some(self.parse_type()?);
        }
        let mut parent = None;
        let mut interfaces = Vec::new();
        if self.accept_kw("extends") {
            if kind == ClassKind::Interface {
                loop {
                    let n = self.parse_class_name_raw()?;
                    interfaces.push(Rc::from(n.as_str()));
                    if !self.accept_op(Op::Comma) {
                        break;
                    }
                }
            } else {
                let n = self.parse_class_name_raw()?;
                parent = Some(Rc::from(n.as_str()));
            }
        }
        if self.accept_kw("implements") {
            loop {
                let n = self.parse_class_name_raw()?;
                interfaces.push(Rc::from(n.as_str()));
                if !self.accept_op(Op::Comma) {
                    break;
                }
            }
        }
        self.expect_op(Op::LBrace)?;
        self.class_ctx.push(Some(ClassCtx { name: fq.clone(), is_trait: kind == ClassKind::Trait, parent: parent.clone() }));
        let mut consts = Vec::new();
        let mut props = Vec::new();
        let mut methods = Vec::new();
        let mut traits = Vec::new();
        let mut trait_rules = Vec::new();
        let mut cases = Vec::new();
        let mut member_order = Vec::new();
        while !self.accept_op(Op::RBrace) {
            if matches!(self.peek(), T::Eof) {
                return self.unexpected();
            }
            let attrs = self.skip_attributes()?;
            let mline = self.line();
            let mdoc = self.toks[self.pos].doc.clone();
            if self.is_kw("use") {
                self.advance();
                loop {
                    let n = self.parse_class_name_raw()?;
                    traits.push(Rc::from(n.as_str()));
                    if !self.accept_op(Op::Comma) {
                        break;
                    }
                }
                if self.accept_op(Op::LBrace) {
                    while !self.accept_op(Op::RBrace) {
                        // [Trait::]method insteadof A, B;  |  [Trait::]method as [vis] [alias];
                        let first = match self.advance().t {
                            T::Ident(n) => (n.to_string(), None),
                            T::Name(n, k) => (n.to_string(), Some(k)),
                            _ => return self.unexpected(),
                        };
                        let (tname, mname) = if self.accept_op(Op::DoubleColon) {
                            let m = self.expect_ident()?;
                            (Some(Rc::from(self.resolve_class(&first.0, first.1).as_str())), m)
                        } else {
                            (None, Rc::from(first.0.as_str()))
                        };
                        if self.accept_kw("insteadof") {
                            let mut list = Vec::new();
                            loop {
                                let n = self.parse_class_name_raw()?;
                                list.push(Rc::from(n.as_str()));
                                if !self.accept_op(Op::Comma) {
                                    break;
                                }
                            }
                            trait_rules.push(TraitRule::Insteadof { trait_name: tname, method: mname, instead_of: list });
                        } else if self.accept_kw("as") {
                            let mut vis = None;
                            if self.accept_kw("public") {
                                vis = Some(Visibility::Public);
                            } else if self.accept_kw("protected") {
                                vis = Some(Visibility::Protected);
                            } else if self.accept_kw("private") {
                                vis = Some(Visibility::Private);
                            }
                            let alias = if let T::Ident(n) = self.peek().clone() {
                                self.advance();
                                Some(n)
                            } else {
                                None
                            };
                            trait_rules.push(TraitRule::Alias { trait_name: tname, method: mname, alias, vis });
                        } else {
                            return self.unexpected();
                        }
                        self.expect_semi()?;
                    }
                } else {
                    self.expect_semi()?;
                }
                continue;
            }
            if self.is_kw("case") && kind == ClassKind::Enum {
                self.advance();
                let n = self.expect_ident()?;
                let v = if self.accept_op(Op::Assign) { Some(self.parse_expr()?) } else { None };
                self.expect_semi()?;
                member_order.push((3u8, cases.len()));
                cases.push(EnumCase { name: n, value: v });
                continue;
            }
            // modifiers
            let mut vis = None;
            let mut set_vis = None;
            let mut is_static = false;
            let mut m_abstract = false;
            let mut m_final = false;
            let mut readonly = false;
            loop {
                let t = self.peek().clone();
                if let T::Ident(n) = &t {
                    let l = n.to_ascii_lowercase();
                    let v = match l.as_str() {
                        "public" => Some(Visibility::Public),
                        "protected" => Some(Visibility::Protected),
                        "private" => Some(Visibility::Private),
                        _ => None,
                    };
                    if let Some(v) = v {
                        self.advance();
                        if self.is_op(Op::LParen) && kw(self.peek_at(1), "set") && matches!(self.peek_at(2), T::Op(Op::RParen)) {
                            self.advance();
                            self.advance();
                            self.advance();
                            set_vis = Some(v);
                        } else {
                            vis = Some(v);
                        }
                        continue;
                    }
                    match l.as_str() {
                        "static" => {
                            self.advance();
                            is_static = true;
                            continue;
                        }
                        "abstract" => {
                            self.advance();
                            m_abstract = true;
                            continue;
                        }
                        "final" => {
                            self.advance();
                            m_final = true;
                            continue;
                        }
                        "readonly" => {
                            self.advance();
                            readonly = true;
                            continue;
                        }
                        "var" => {
                            self.advance();
                            vis = Some(Visibility::Public);
                            continue;
                        }
                        _ => {}
                    }
                }
                break;
            }
            if self.is_kw("const") {
                self.advance();
                // optional type
                let mut ty = None;
                if matches!(self.peek_at(1), T::Ident(_)) || matches!(self.peek(), T::Op(Op::Question)) || (matches!(self.peek_at(1), T::Op(Op::Pipe))) {
                    if !matches!(self.peek_at(1), T::Op(Op::Assign)) {
                        ty = Some(self.parse_type()?);
                    }
                }
                loop {
                    let n = self.expect_ident()?;
                    self.expect_op(Op::Assign)?;
                    let e = self.parse_expr()?;
                    member_order.push((0u8, consts.len()));
                    consts.push(ConstDecl { name: n, value: e, vis: vis.unwrap_or(Visibility::Public), is_final: m_final, ty: ty.clone(), doc: mdoc.clone() });
                    if !self.accept_op(Op::Comma) {
                        break;
                    }
                }
                self.expect_semi()?;
                continue;
            }
            if self.is_kw("function") {
                self.advance();
                let by_ref = self.accept_op(Op::Amp);
                let n = match self.advance().t {
                    T::Ident(n) => n,
                    _ => return self.unexpected(),
                };
                let mut f = self.parse_function_rest(n, by_ref, false, true, mline, mdoc)?;
                if is_static {
                    if let Some(fm) = Rc::get_mut(&mut f) {
                        fm.is_static = true;
                    }
                }
                if let Some(fm) = Rc::get_mut(&mut f) {
                    fm.attrs = attrs;
                }
                let is_abs = m_abstract || (kind == ClassKind::Interface);
                member_order.push((2u8, methods.len()));
                methods.push(MethodDecl { func: f, vis: vis.unwrap_or(Visibility::Public), is_static, is_abstract: is_abs, is_final: m_final });
                continue;
            }
            // property
            let ty = if !matches!(self.peek(), T::Var(_)) { Some(self.parse_type()?) } else { None };
            loop {
                let pline = self.line();
                let n = match self.advance().t {
                    T::Var(n) => n,
                    _ => {
                        self.pos -= 1;
                        return self.unexpected_expecting("variable");
                    }
                };
                let default = if self.accept_op(Op::Assign) { Some(self.parse_expr()?) } else { None };
                let mut hooks = Vec::new();
                if self.is_op(Op::LBrace) {
                    hooks = self.parse_prop_hooks(&n, ty.clone())?;
                }
                member_order.push((1u8, props.len()));
                props.push(PropDecl {
                    name: n,
                    default,
                    ty: ty.clone(),
                    vis: vis.unwrap_or(Visibility::Public),
                    set_vis,
                    is_static,
                    readonly: readonly || is_readonly,
                    doc: mdoc.clone(),
                    hooks,
                    is_abstract: m_abstract,
                    is_final: m_final,
                    attrs: Vec::new(),
                    line: pline,
                });
                if !self.accept_op(Op::Comma) {
                    break;
                }
            }
            if !props.last().map(|p| !p.hooks.is_empty()).unwrap_or(false) || self.is_op(Op::Semi) {
                self.expect_semi()?;
            }
            let _ = attrs;
        }
        let end_line = self.prev_line();
        self.class_ctx.pop();
        Ok(Rc::new(ClassDecl {
            name: fq,
            kind,
            parent,
            interfaces,
            is_abstract,
            is_final,
            is_readonly,
            consts,
            props,
            methods,
            traits,
            trait_rules,
            cases,
            enum_type,
            line,
            end_line,
            doc,
            attrs: Vec::new(),
            is_anon,
            file: self.file.clone(),
            declared: Cell::new(false),
            member_order,
        }))
    }

    fn parse_prop_hooks(&mut self, prop: &Name, ty: Option<TypeHint>) -> PResult<Vec<PropHook>> {
        self.expect_op(Op::LBrace)?;
        let mut hooks = Vec::new();
        while !self.accept_op(Op::RBrace) {
            let _ = self.skip_attributes()?;
            while self.accept_kw("final") {}
            let by_ref = self.accept_op(Op::Amp);
            let hline = self.line();
            let kind = self.expect_ident()?;
            let lk: Name = Rc::from(kind.to_ascii_lowercase().as_str());
            self.scopes.push(Scope::new(false));
            let cls = self.class_ctx.last().cloned().flatten().map(|c| c.name.to_string()).unwrap_or_default();
            self.func_ctx.push(format!("${}::{}", prop, lk));
            self.method_ctx.push(format!("{}::${}::{}", cls, prop, lk));
            let mut params = Vec::new();
            if &*lk == "set" {
                if self.is_op(Op::LParen) {
                    params = self.parse_params()?;
                } else {
                    let slot = self.var_ref(&Rc::from("value")).slot;
                    params.push(Param { name: Rc::from("value"), slot, default: None, ty: ty.clone(), by_ref: false, variadic: false, promote: None, attrs: Vec::new() });
                }
            }
            let body;
            let mut is_short = false;
            if self.accept_op(Op::DoubleArrow) {
                let e = self.parse_expr()?;
                self.expect_semi()?;
                let l = e.line;
                body = Some(vec![Stmt { kind: StmtKind::Return(Some(e)), line: l }]);
                is_short = true;
            } else if self.is_op(Op::LBrace) {
                self.advance();
                body = Some(self.parse_stmts_until_brace()?);
            } else {
                self.expect_semi()?;
                body = None;
            }
            self.func_ctx.pop();
            self.method_ctx.pop();
            let sc = self.scopes.pop().unwrap();
            let f = Rc::new(FuncDecl {
                name: Rc::from(format!("${}::{}", prop, lk).as_str()),
                params,
                body,
                by_ref,
                ret: None,
                is_generator: sc.is_generator,
                num_slots: sc.names.len() as u32,
                slot_names: Rc::new(sc.names),
                this_used: true,
                is_static: false,
                line: hline,
                end_line: self.prev_line(),
                doc: None,
                statics: RefCell::new(Vec::new()),
                is_arrow: is_short,
                is_closure: false,
                uses_dynamic: false,
                file: self.file.clone(),
                attrs: Vec::new(),
                id: Cell::new(0),
            });
            hooks.push(PropHook { kind: lk, func: f, by_ref });
        }
        Ok(hooks)
    }
}

// ---------- expressions ----------
fn binop_info(t: &T) -> Option<(u8, bool, BinOp)> {
    // (prec, right_assoc, op)
    let r = match t {
        T::Op(o) => match o {
            Op::BoolOr => (P_BOOLOR, false, BinOp::Or),
            Op::BoolAnd => (P_BOOLAND, false, BinOp::And),
            Op::Pipe => (P_BITOR, false, BinOp::BitOr),
            Op::Caret => (P_BITXOR, false, BinOp::BitXor),
            Op::Amp => (P_BITAND, false, BinOp::BitAnd),
            Op::Eq => (P_EQUALITY, false, BinOp::Eq),
            Op::NotEq => (P_EQUALITY, false, BinOp::NotEq),
            Op::Identical => (P_EQUALITY, false, BinOp::Identical),
            Op::NotIdentical => (P_EQUALITY, false, BinOp::NotIdentical),
            Op::Spaceship => (P_EQUALITY, false, BinOp::Spaceship),
            Op::Lt => (P_COMPARE, false, BinOp::Lt),
            Op::Gt => (P_COMPARE, false, BinOp::Gt),
            Op::Le => (P_COMPARE, false, BinOp::Le),
            Op::Ge => (P_COMPARE, false, BinOp::Ge),
            Op::Dot => (P_CONCAT, false, BinOp::Concat),
            Op::Shl => (P_SHIFT, false, BinOp::Shl),
            Op::Shr => (P_SHIFT, false, BinOp::Shr),
            Op::Plus => (P_ADD, false, BinOp::Add),
            Op::Minus => (P_ADD, false, BinOp::Sub),
            Op::Mul => (P_MUL, false, BinOp::Mul),
            Op::Div => (P_MUL, false, BinOp::Div),
            Op::Mod => (P_MUL, false, BinOp::Mod),
            Op::Pow => (P_POW, true, BinOp::Pow),
            _ => return None,
        },
        T::Ident(s) => {
            if s.eq_ignore_ascii_case("or") {
                (P_OR, false, BinOp::Or)
            } else if s.eq_ignore_ascii_case("and") {
                (P_AND, false, BinOp::And)
            } else if s.eq_ignore_ascii_case("xor") {
                (P_XOR, false, BinOp::Xor)
            } else {
                return None;
            }
        }
        _ => return None,
    };
    Some(r)
}

fn assign_op(t: &T) -> Option<Option<BinOp>> {
    match t {
        T::Op(o) => match o {
            Op::Assign => Some(None),
            Op::PlusAssign => Some(Some(BinOp::Add)),
            Op::MinusAssign => Some(Some(BinOp::Sub)),
            Op::MulAssign => Some(Some(BinOp::Mul)),
            Op::DivAssign => Some(Some(BinOp::Div)),
            Op::ConcatAssign => Some(Some(BinOp::Concat)),
            Op::ModAssign => Some(Some(BinOp::Mod)),
            Op::PowAssign => Some(Some(BinOp::Pow)),
            Op::AndAssign => Some(Some(BinOp::BitAnd)),
            Op::OrAssign => Some(Some(BinOp::BitOr)),
            Op::XorAssign => Some(Some(BinOp::BitXor)),
            Op::ShlAssign => Some(Some(BinOp::Shl)),
            Op::ShrAssign => Some(Some(BinOp::Shr)),
            _ => None,
        },
        _ => None,
    }
}

fn is_lvalue(e: &Expr) -> bool {
    match &e.kind {
        ExprKind::Var(_) | ExprKind::VarVar(_) | ExprKind::Index(..) | ExprKind::StaticProp(..) | ExprKind::List(..) | ExprKind::This => true,
        ExprKind::Prop(_, _, nullsafe) => !*nullsafe,
        ExprKind::Array(_) => true,
        _ => false,
    }
}

impl Parser {
    pub fn parse_expr(&mut self) -> PResult<Expr> {
        self.parse_expr_bp(P_LOWEST)
    }

    fn parse_expr_list(&mut self, end: Op) -> PResult<Vec<Expr>> {
        let mut v = Vec::new();
        if self.is_op(end) {
            return Ok(v);
        }
        loop {
            v.push(self.parse_expr()?);
            if !self.accept_op(Op::Comma) {
                break;
            }
        }
        Ok(v)
    }

    fn parse_expr_bp(&mut self, min: u8) -> PResult<Expr> {
        let mut left = self.parse_unary()?;
        loop {
            let t = self.peek().clone();
            let line = self.line();
            if let Some(aop) = assign_op(&t) {
                if is_lvalue(&left) {
                    self.advance();
                    let target = if matches!(left.kind, ExprKind::Array(_)) { self.to_list_if_array(left) } else { left };
                    match aop {
                        None => {
                            if self.is_op(Op::Amp) {
                                self.advance();
                                let rhs = self.parse_expr_bp(P_ASSIGN)?;
                                left = self.mk(ExprKind::AssignRef(Box::new(target), Box::new(rhs)), line);
                            } else {
                                let rhs = self.parse_expr_bp(P_ASSIGN)?;
                                left = self.mk(ExprKind::Assign(Box::new(target), Box::new(rhs)), line);
                            }
                        }
                        Some(op) => {
                            let rhs = self.parse_expr_bp(P_ASSIGN)?;
                            left = self.mk(ExprKind::AssignOp(op, Box::new(target), Box::new(rhs)), line);
                        }
                    }
                    continue;
                }
            }
            if let T::Op(Op::CoalesceAssign) = t {
                if is_lvalue(&left) {
                    self.advance();
                    let rhs = self.parse_expr_bp(P_ASSIGN)?;
                    left = self.mk(ExprKind::CoalesceAssign(Box::new(left), Box::new(rhs)), line);
                    continue;
                }
            }
            match &t {
                T::Op(Op::Question) => {
                    if P_TERNARY < min {
                        break;
                    }
                    self.advance();
                    if self.accept_op(Op::Colon) {
                        let rhs = self.parse_expr_bp(P_TERNARY + 1)?;
                        left = self.mk(ExprKind::Ternary(Box::new(left), None, Box::new(rhs)), line);
                    } else {
                        let mid = self.parse_expr_bp(P_LOWEST)?;
                        self.expect_op(Op::Colon)?;
                        let rhs = self.parse_expr_bp(P_TERNARY + 1)?;
                        left = self.mk(ExprKind::Ternary(Box::new(left), Some(Box::new(mid)), Box::new(rhs)), line);
                    }
                    continue;
                }
                T::Op(Op::Coalesce) => {
                    if P_COALESCE < min {
                        break;
                    }
                    self.advance();
                    let rhs = self.parse_expr_bp(P_COALESCE)?;
                    left = self.mk(ExprKind::Coalesce(Box::new(left), Box::new(rhs)), line);
                    continue;
                }
                T::Op(Op::PipeGt) => {
                    if P_PIPE < min {
                        break;
                    }
                    self.advance();
                    let rhs = self.parse_expr_bp(P_PIPE + 1)?;
                    left = self.mk(ExprKind::Pipe(Box::new(left), Box::new(rhs)), line);
                    continue;
                }
                T::Ident(s) if s.eq_ignore_ascii_case("instanceof") => {
                    if P_INSTANCEOF < min {
                        break;
                    }
                    self.advance();
                    let cref = self.parse_class_ref_for_instanceof()?;
                    left = self.mk(ExprKind::InstanceOf(Box::new(left), cref), line);
                    continue;
                }
                _ => {}
            }
            if let Some((prec, right, op)) = binop_info(&t) {
                if prec < min {
                    break;
                }
                self.advance();
                let rhs = self.parse_expr_bp(if right { prec } else { prec + 1 })?;
                left = self.mk(ExprKind::Bin(op, Box::new(left), Box::new(rhs)), line);
                continue;
            }
            break;
        }
        Ok(left)
    }

    fn parse_class_ref_for_instanceof(&mut self) -> PResult<ClassRef> {
        match self.peek().clone() {
            T::Ident(n) => {
                self.advance();
                Ok(self.class_ref_from_name(&n, None))
            }
            T::Name(n, k) => {
                self.advance();
                Ok(self.class_ref_from_name(&n, Some(k)))
            }
            _ => {
                let e = self.parse_unary()?;
                Ok(ClassRef::Dynamic(Box::new(e)))
            }
        }
    }

    fn class_ref_from_name(&self, n: &str, k: Option<NameKind>) -> ClassRef {
        if k.is_none() {
            let l = n.to_ascii_lowercase();
            match l.as_str() {
                "self" => return ClassRef::SelfRef,
                "parent" => return ClassRef::Parent,
                "static" => return ClassRef::Static,
                _ => {}
            }
        }
        ClassRef::Named(Rc::from(self.resolve_class(n, k).as_str()))
    }

    fn parse_unary(&mut self) -> PResult<Expr> {
        let line = self.line();
        let t = self.peek().clone();
        match &t {
            T::Op(Op::Not) => {
                self.advance();
                let e = self.parse_expr_bp(P_NOT)?;
                Ok(self.mk(ExprKind::Unary(UnOp::Not, Box::new(e)), line))
            }
            T::Op(Op::Minus) => {
                self.advance();
                let e = self.parse_expr_bp(P_UNARY)?;
                // fold negative literals
                if let ExprKind::Lit(Value::Int(i)) = &e.kind {
                    if !matches!(self.toks[self.pos - 1].t, T::Op(Op::RParen)) {
                        return Ok(self.mk(ExprKind::Lit(Value::Int(i.wrapping_neg())), line));
                    }
                }
                if let ExprKind::Lit(Value::Float(f)) = &e.kind {
                    return Ok(self.mk(ExprKind::Lit(Value::Float(-f)), line));
                }
                Ok(self.mk(ExprKind::Unary(UnOp::Neg, Box::new(e)), line))
            }
            T::Op(Op::Plus) => {
                self.advance();
                let e = self.parse_expr_bp(P_UNARY)?;
                Ok(self.mk(ExprKind::Unary(UnOp::Plus, Box::new(e)), line))
            }
            T::Op(Op::Tilde) => {
                self.advance();
                let e = self.parse_expr_bp(P_UNARY)?;
                Ok(self.mk(ExprKind::Unary(UnOp::BitNot, Box::new(e)), line))
            }
            T::Op(Op::At) => {
                self.advance();
                let e = self.parse_expr_bp(P_UNARY)?;
                Ok(self.mk(ExprKind::Silence(Box::new(e)), line))
            }
            T::Cast(c) => {
                self.advance();
                let k = match *c {
                    "int" => CastKind::Int,
                    "float" => CastKind::Float,
                    "string" => CastKind::String,
                    "bool" => CastKind::Bool,
                    "array" => CastKind::Array,
                    "object" => CastKind::Object,
                    "void" => CastKind::Unset,
                    _ => CastKind::Unset,
                };
                let e = self.parse_expr_bp(P_UNARY)?;
                Ok(self.mk(ExprKind::Cast(k, Box::new(e)), line))
            }
            T::Op(Op::Inc) | T::Op(Op::Dec) => {
                let inc = matches!(t, T::Op(Op::Inc));
                self.advance();
                let e = self.parse_expr_bp(P_UNARY)?;
                Ok(self.mk(ExprKind::IncDec(true, inc, Box::new(e)), line))
            }
            T::Op(Op::Amp) => self.unexpected(),
            T::Ident(id) => {
                let l = id.to_ascii_lowercase();
                match l.as_str() {
                    "new" => {
                        let e = self.parse_new()?;
                        self.parse_postfix(e)
                    }
                    "clone" => {
                        self.advance();
                        if self.is_op(Op::LParen) {
                            // clone(...) function-like syntax (PHP 8.5)
                            let save = self.pos;
                            let (args, _) = self.parse_args()?;
                            if args.len() == 2 || (args.len() == 1 && args[0].name.is_none() && !args[0].unpack) {
                                let mut it = args.into_iter();
                                let a = it.next().unwrap();
                                let e = if let Some(b) = it.next() {
                                    self.mk(ExprKind::CloneWith(Box::new(a.value), Box::new(b.value)), line)
                                } else {
                                    self.mk(ExprKind::Clone(Box::new(a.value)), line)
                                };
                                return self.parse_postfix(e);
                            }
                            self.pos = save;
                        }
                        let e = self.parse_expr_bp(P_POW + 1)?;
                        Ok(self.mk(ExprKind::Clone(Box::new(e)), line))
                    }
                    "print" => {
                        self.advance();
                        let e = self.parse_expr_bp(P_AND + 1)?;
                        Ok(self.mk(ExprKind::Print(Box::new(e)), line))
                    }
                    "yield" => {
                        self.advance();
                        self.scope().is_generator = true;
                        if self.is_kw("from") {
                            self.advance();
                            let e = self.parse_expr_bp(P_AND + 1)?;
                            return Ok(self.mk(ExprKind::YieldFrom(Box::new(e)), line));
                        }
                        if matches!(self.peek(), T::Op(Op::Semi) | T::Op(Op::RParen) | T::Op(Op::Comma) | T::Op(Op::RBracket) | T::CloseTag) {
                            return Ok(self.mk(ExprKind::Yield(None, None), line));
                        }
                        let v = self.parse_expr_bp(P_AND + 1)?;
                        if self.accept_op(Op::DoubleArrow) {
                            let v2 = self.parse_expr_bp(P_AND + 1)?;
                            return Ok(self.mk(ExprKind::Yield(Some(Box::new(v)), Some(Box::new(v2))), line));
                        }
                        Ok(self.mk(ExprKind::Yield(None, Some(Box::new(v))), line))
                    }
                    "throw" => {
                        self.advance();
                        let e = self.parse_expr_bp(P_LOWEST)?;
                        Ok(self.mk(ExprKind::Throw(Box::new(e)), line))
                    }
                    "include" | "include_once" | "require" | "require_once" => {
                        self.advance();
                        let k = match l.as_str() {
                            "include" => IncludeKind::Include,
                            "include_once" => IncludeKind::IncludeOnce,
                            "require" => IncludeKind::Require,
                            _ => IncludeKind::RequireOnce,
                        };
                        let e = self.parse_expr_bp(P_LOWEST)?;
                        self.scope().uses_dynamic = true;
                        Ok(self.mk(ExprKind::Include(k, Box::new(e)), line))
                    }
                    _ => {
                        let e = self.parse_primary()?;
                        self.parse_postfix(e)
                    }
                }
            }
            _ => {
                let e = self.parse_primary()?;
                self.parse_postfix(e)
            }
        }
    }

    fn parse_new(&mut self) -> PResult<Expr> {
        let line = self.line();
        self.advance(); // new
        if self.is_kw("class") {
            // anonymous class
            self.advance();
            let args = if self.is_op(Op::LParen) { self.parse_args()?.0 } else { Vec::new() };
            let name = format!("class@anonymous\0{}:{}${:x}", self.file, line, self.anon_count);
            self.anon_count += 1;
            let decl = self.parse_class_body(Rc::from(name.as_str()), ClassKind::Class, false, false, false, line, None, true)?;
            return Ok(self.mk(ExprKind::NewAnon(decl, args), line));
        }
        let cref = match self.peek().clone() {
            T::Ident(n) if !n.eq_ignore_ascii_case("static") || true => {
                self.advance();
                self.class_ref_from_name(&n, None)
            }
            T::Name(n, k) => {
                self.advance();
                self.class_ref_from_name(&n, Some(k))
            }
            T::Op(Op::LParen) => {
                self.advance();
                let e = self.parse_expr()?;
                self.expect_op(Op::RParen)?;
                ClassRef::Dynamic(Box::new(e))
            }
            T::Var(_) | T::Op(Op::Dollar) => {
                let e = self.parse_new_variable()?;
                ClassRef::Dynamic(Box::new(e))
            }
            _ => return self.unexpected(),
        };
        let args = if self.is_op(Op::LParen) { self.parse_args()?.0 } else { Vec::new() };
        Ok(self.mk(ExprKind::New(cref, args), line))
    }

    fn parse_new_variable(&mut self) -> PResult<Expr> {
        let mut e = self.parse_simple_variable()?;
        loop {
            let line = self.line();
            if self.is_op(Op::LBracket) {
                self.advance();
                let idx = if self.is_op(Op::RBracket) { None } else { Some(Box::new(self.parse_expr()?)) };
                self.expect_op(Op::RBracket)?;
                e = self.mk(ExprKind::Index(Box::new(e), idx), line);
            } else if self.is_op(Op::Arrow) || self.is_op(Op::NullsafeArrow) {
                let ns = self.is_op(Op::NullsafeArrow);
                self.advance();
                let m = self.parse_member_name()?;
                e = self.mk(ExprKind::Prop(Box::new(e), m, ns), line);
            } else if self.is_op(Op::DoubleColon) && matches!(self.peek_at(1), T::Var(_)) {
                self.advance();
                let n = match self.advance().t {
                    T::Var(n) => n,
                    _ => unreachable!(),
                };
                e = self.mk(ExprKind::StaticProp(ClassRef::Dynamic(Box::new(e)), MemberName::Ident(n)), line);
            } else {
                break;
            }
        }
        Ok(e)
    }

    fn parse_simple_variable(&mut self) -> PResult<Expr> {
        let line = self.line();
        match self.peek().clone() {
            T::Var(n) => {
                self.advance();
                if &*n == "this" {
                    self.scope().this_used = true;
                    return Ok(self.mk(ExprKind::This, line));
                }
                let v = self.var_ref(&n);
                Ok(self.mk(ExprKind::Var(v), line))
            }
            T::Op(Op::Dollar) => {
                self.advance();
                self.scope().uses_dynamic = true;
                if self.accept_op(Op::LBrace) {
                    let e = self.parse_expr()?;
                    self.expect_op(Op::RBrace)?;
                    Ok(self.mk(ExprKind::VarVar(Box::new(e)), line))
                } else {
                    let e = self.parse_simple_variable()?;
                    Ok(self.mk(ExprKind::VarVar(Box::new(e)), line))
                }
            }
            _ => self.unexpected_expecting("variable"),
        }
    }

    fn parse_member_name(&mut self) -> PResult<MemberName> {
        match self.peek().clone() {
            T::Ident(n) => {
                self.advance();
                Ok(MemberName::Ident(n))
            }
            T::Var(_) | T::Op(Op::Dollar) => {
                let e = self.parse_simple_variable()?;
                Ok(MemberName::Dynamic(Box::new(e)))
            }
            T::Op(Op::LBrace) => {
                self.advance();
                let e = self.parse_expr()?;
                self.expect_op(Op::RBrace)?;
                Ok(MemberName::Dynamic(Box::new(e)))
            }
            _ => self.unexpected(),
        }
    }

    /// returns (args, is_first_class_callable)
    fn parse_args(&mut self) -> PResult<(Vec<Arg>, bool)> {
        self.expect_op(Op::LParen)?;
        let mut args = Vec::new();
        if self.is_op(Op::Ellipsis) && matches!(self.peek_at(1), T::Op(Op::RParen)) {
            self.advance();
            self.advance();
            return Ok((args, true));
        }
        while !self.is_op(Op::RParen) {
            if self.accept_op(Op::Ellipsis) {
                let e = self.parse_expr()?;
                args.push(Arg { value: e, unpack: true, name: None });
            } else if matches!(self.peek(), T::Ident(_)) && matches!(self.peek_at(1), T::Op(Op::Colon)) && !matches!(self.peek_at(2), T::Op(Op::Colon)) {
                let n = match self.advance().t {
                    T::Ident(n) => n,
                    _ => unreachable!(),
                };
                self.advance();
                let e = self.parse_expr()?;
                args.push(Arg { value: e, unpack: false, name: Some(n) });
            } else {
                let e = self.parse_expr()?;
                args.push(Arg { value: e, unpack: false, name: None });
            }
            if !self.accept_op(Op::Comma) {
                break;
            }
        }
        self.expect_op(Op::RParen)?;
        Ok((args, false))
    }

    fn parse_array_items(&mut self, end: Op) -> PResult<Vec<ArrayItem>> {
        let mut items = Vec::new();
        loop {
            if self.is_op(end) {
                break;
            }
            if self.is_op(Op::Comma) {
                // empty slot (for list)
                let line = self.line();
                self.advance();
                items.push(ArrayItem { key: None, value: self.mk(ExprKind::Lit(Value::Undef), line), by_ref: false, unpack: false });
                continue;
            }
            if self.accept_op(Op::Ellipsis) {
                let e = self.parse_expr()?;
                items.push(ArrayItem { key: None, value: e, by_ref: false, unpack: true });
            } else if self.accept_op(Op::Amp) {
                let e = self.parse_expr()?;
                items.push(ArrayItem { key: None, value: e, by_ref: true, unpack: false });
            } else {
                let e = self.parse_expr()?;
                if self.accept_op(Op::DoubleArrow) {
                    let r = self.accept_op(Op::Amp);
                    let v = self.parse_expr()?;
                    items.push(ArrayItem { key: Some(e), value: v, by_ref: r, unpack: false });
                } else {
                    items.push(ArrayItem { key: None, value: e, by_ref: false, unpack: false });
                }
            }
            if !self.accept_op(Op::Comma) {
                break;
            }
        }
        self.expect_op(end)?;
        Ok(items)
    }

    fn magic(&self, l: &str, line: u32) -> Option<ExprKind> {
        let cls = self.class_ctx.last().cloned().flatten();
        Some(match l {
            "__line__" => ExprKind::Lit(Value::Int(line as i64)),
            "__file__" => ExprKind::Lit(Value::str(&self.file)),
            "__dir__" => {
                let f = &*self.file;
                let d = match f.rfind('/') {
                    Some(0) => "/".to_string(),
                    Some(p) => f[..p].to_string(),
                    None => ".".to_string(),
                };
                ExprKind::Lit(Value::str(&d))
            }
            "__namespace__" => ExprKind::Lit(Value::str(&self.namespace)),
            "__class__" => match &cls {
                Some(c) if c.is_trait => ExprKind::Magic(MagicConst::Class),
                Some(c) => {
                    if c.name.starts_with("class@anonymous") {
                        ExprKind::Magic(MagicConst::Class)
                    } else {
                        ExprKind::Lit(Value::str(&c.name))
                    }
                }
                None => ExprKind::Lit(Value::str("")),
            },
            "__trait__" => match &cls {
                Some(c) if c.is_trait => ExprKind::Lit(Value::str(&c.name)),
                _ => ExprKind::Lit(Value::str("")),
            },
            "__function__" => {
                let f = self.func_ctx.last().cloned().unwrap_or_default();
                ExprKind::Lit(Value::str(&f))
            }
            "__method__" => {
                let m = self.method_ctx.last().cloned().unwrap_or_default();
                if m.is_empty() {
                    let f = self.func_ctx.last().cloned().unwrap_or_default();
                    ExprKind::Lit(Value::str(&f))
                } else {
                    ExprKind::Lit(Value::str(&m))
                }
            }
            "__property__" => ExprKind::Magic(MagicConst::Property),
            _ => return None,
        })
    }

    fn parse_primary(&mut self) -> PResult<Expr> {
        let line = self.line();
        let t = self.peek().clone();
        match t {
            T::Var(_) | T::Op(Op::Dollar) => self.parse_simple_variable(),
            T::Int(i) => {
                self.advance();
                Ok(self.mk(ExprKind::Lit(Value::Int(i)), line))
            }
            T::Float(f) => {
                self.advance();
                Ok(self.mk(ExprKind::Lit(Value::Float(f)), line))
            }
            T::Str(s) => {
                self.advance();
                Ok(self.mk(ExprKind::Lit(Value::vec(s)), line))
            }
            T::Template(parts) => {
                self.advance();
                let p = self.parse_template(parts)?;
                Ok(self.mk(ExprKind::Interp(p), line))
            }
            T::ShellCmd(parts) => {
                self.advance();
                let p = self.parse_template(parts)?;
                Ok(self.mk(ExprKind::ShellExec(p), line))
            }
            T::Op(Op::LParen) => {
                self.advance();
                let e = self.parse_expr()?;
                self.expect_op(Op::RParen)?;
                // mark parenthesized by wrapping? keep as is
                Ok(e)
            }
            T::Op(Op::LBracket) => {
                self.advance();
                let items = self.parse_array_items(Op::RBracket)?;
                Ok(self.mk(ExprKind::Array(items), line))
            }
            T::Op(Op::AttrOpen) => {
                let _ = self.skip_attributes()?;
                self.parse_primary()
            }
            T::Name(n, k) => {
                self.advance();
                self.parse_name_expr(&n, Some(k), line)
            }
            T::Ident(id) => {
                let l = id.to_ascii_lowercase();
                match l.as_str() {
                    "true" | "false" | "null" if !matches!(self.peek_at(1), T::Op(Op::DoubleColon) | T::Op(Op::LParen)) => {
                        self.advance();
                        let v = match l.as_str() {
                            "true" => Value::Bool(true),
                            "false" => Value::Bool(false),
                            _ => Value::Null,
                        };
                        return Ok(self.mk(ExprKind::Lit(v), line));
                    }
                    "array" if matches!(self.peek_at(1), T::Op(Op::LParen)) => {
                        self.advance();
                        self.advance();
                        let items = self.parse_array_items(Op::RParen)?;
                        return Ok(self.mk(ExprKind::Array(items), line));
                    }
                    "list" if matches!(self.peek_at(1), T::Op(Op::LParen)) => {
                        self.advance();
                        self.advance();
                        let items = self.parse_array_items(Op::RParen)?;
                        let mut out = Vec::new();
                        for it in items {
                            if let ExprKind::Lit(Value::Undef) = it.value.kind {
                                out.push(None);
                                continue;
                            }
                            let target = self.to_list_if_array(it.value);
                            out.push(Some(ListItem { key: it.key, target, by_ref: it.by_ref }));
                        }
                        return Ok(self.mk(ExprKind::List(out, false), line));
                    }
                    "isset" => {
                        self.advance();
                        self.expect_op(Op::LParen)?;
                        let mut v = Vec::new();
                        while !self.is_op(Op::RParen) {
                            v.push(self.parse_expr()?);
                            if !self.accept_op(Op::Comma) {
                                break;
                            }
                        }
                        self.expect_op(Op::RParen)?;
                        return Ok(self.mk(ExprKind::Isset(v), line));
                    }
                    "empty" => {
                        self.advance();
                        self.expect_op(Op::LParen)?;
                        let e = self.parse_expr()?;
                        self.expect_op(Op::RParen)?;
                        return Ok(self.mk(ExprKind::Empty(Box::new(e)), line));
                    }
                    "exit" | "die" => {
                        self.advance();
                        let mut arg = None;
                        if self.accept_op(Op::LParen) {
                            if !self.is_op(Op::RParen) {
                                arg = Some(Box::new(self.parse_expr()?));
                            }
                            self.expect_op(Op::RParen)?;
                        }
                        return Ok(self.mk(ExprKind::Exit(arg), line));
                    }
                    "eval" if matches!(self.peek_at(1), T::Op(Op::LParen)) => {
                        self.advance();
                        self.advance();
                        let e = self.parse_expr()?;
                        self.expect_op(Op::RParen)?;
                        self.scope().uses_dynamic = true;
                        return Ok(self.mk(ExprKind::Eval(Box::new(e)), line));
                    }
                    "function" | "fn" => {
                        return self.parse_closure(false);
                    }
                    "static" if kw(self.peek_at(1), "function") || kw(self.peek_at(1), "fn") => {
                        self.advance();
                        return self.parse_closure(true);
                    }
                    "match" if matches!(self.peek_at(1), T::Op(Op::LParen)) => {
                        return self.parse_match();
                    }
                    "new" => return self.parse_new(),
                    _ => {}
                }
                if l.starts_with("__") && l.ends_with("__") {
                    if let Some(k) = self.magic(&l, line) {
                        self.advance();
                        return Ok(self.mk(k, line));
                    }
                }
                self.advance();
                self.parse_name_expr(&id, None, line)
            }
            _ => self.unexpected(),
        }
    }

    fn parse_name_expr(&mut self, n: &str, k: Option<NameKind>, line: u32) -> PResult<Expr> {
        if self.is_op(Op::LParen) {
            let (fname, fb) = self.resolve_func(n, k);
            let lname = fname.to_ascii_lowercase();
            if lname == "compact" || lname == "extract" || lname == "get_defined_vars" || lname == "func_get_args" || lname == "func_get_arg" || lname == "func_num_args" {
                self.scope().uses_dynamic = true;
            }
            let (args, fcc) = self.parse_args()?;
            let fnm = Rc::new(FuncName { name: fname, fallback: fb, cache: RefCell::new(None) });
            let call = self.mk(ExprKind::Call(fnm, args), line);
            if fcc {
                return Ok(self.mk(ExprKind::CallableRef(Box::new(call)), line));
            }
            return Ok(call);
        }
        if self.is_op(Op::DoubleColon) {
            let cref = self.class_ref_from_name(n, k);
            return self.parse_static_member(cref, line);
        }
        // constant
        let (cname, fb) = self.resolve_const(n, k);
        Ok(self.mk(ExprKind::Const(FuncName { name: cname, fallback: fb, cache: RefCell::new(None) }), line))
    }

    fn parse_static_member(&mut self, cref: ClassRef, line: u32) -> PResult<Expr> {
        self.expect_op(Op::DoubleColon)?;
        match self.peek().clone() {
            T::Var(n) => {
                self.advance();
                let e = self.mk(ExprKind::StaticProp(cref, MemberName::Ident(n.clone())), line);
                if self.is_op(Op::LParen) {
                    // A::$name() - variable static method call
                    let ExprKind::StaticProp(cref, _) = e.kind else { unreachable!() };
                    let v = self.var_ref(&n);
                    let name_expr = self.mk(ExprKind::Var(v), line);
                    let (args, fcc) = self.parse_args()?;
                    let call = self.mk(ExprKind::StaticCall(cref, MemberName::Dynamic(Box::new(name_expr)), args), line);
                    if fcc {
                        return Ok(self.mk(ExprKind::CallableRef(Box::new(call)), line));
                    }
                    return Ok(call);
                }
                Ok(e)
            }
            T::Ident(m) => {
                self.advance();
                if self.is_op(Op::LParen) {
                    let (args, fcc) = self.parse_args()?;
                    let call = self.mk(ExprKind::StaticCall(cref, MemberName::Ident(m), args), line);
                    if fcc {
                        return Ok(self.mk(ExprKind::CallableRef(Box::new(call)), line));
                    }
                    return Ok(call);
                }
                Ok(self.mk(ExprKind::ClassConst(cref, MemberName::Ident(m)), line))
            }
            T::Op(Op::LBrace) => {
                self.advance();
                let e = self.parse_expr()?;
                self.expect_op(Op::RBrace)?;
                if self.is_op(Op::LParen) {
                    let (args, fcc) = self.parse_args()?;
                    let call = self.mk(ExprKind::StaticCall(cref, MemberName::Dynamic(Box::new(e)), args), line);
                    if fcc {
                        return Ok(self.mk(ExprKind::CallableRef(Box::new(call)), line));
                    }
                    return Ok(call);
                }
                Ok(self.mk(ExprKind::ClassConst(cref, MemberName::Dynamic(Box::new(e))), line))
            }
            T::Op(Op::Dollar) => {
                let e = self.parse_simple_variable()?;
                Ok(self.mk(ExprKind::StaticProp(cref, MemberName::Dynamic(Box::new(e))), line))
            }
            _ => self.unexpected(),
        }
    }

    fn parse_postfix(&mut self, mut e: Expr) -> PResult<Expr> {
        loop {
            let line = self.line();
            match self.peek() {
                T::Op(Op::LBracket) => {
                    self.advance();
                    let idx = if self.is_op(Op::RBracket) { None } else { Some(Box::new(self.parse_expr()?)) };
                    self.expect_op(Op::RBracket)?;
                    e = self.mk(ExprKind::Index(Box::new(e), idx), line);
                }
                T::Op(Op::LBrace) if false => {}
                T::Op(Op::Arrow) | T::Op(Op::NullsafeArrow) => {
                    let ns = self.is_op(Op::NullsafeArrow);
                    self.advance();
                    let m = self.parse_member_name()?;
                    if self.is_op(Op::LParen) {
                        let (args, fcc) = self.parse_args()?;
                        let call = self.mk(ExprKind::MethodCall(Box::new(e), m, args, ns), line);
                        e = if fcc { self.mk(ExprKind::CallableRef(Box::new(call)), line) } else { call };
                    } else {
                        e = self.mk(ExprKind::Prop(Box::new(e), m, ns), line);
                    }
                }
                T::Op(Op::DoubleColon) => {
                    let cref = ClassRef::Dynamic(Box::new(e));
                    e = self.parse_static_member(cref, line)?;
                }
                T::Op(Op::LParen) => {
                    let (args, fcc) = self.parse_args()?;
                    let call = self.mk(ExprKind::CallExpr(Box::new(e), args), line);
                    e = if fcc { self.mk(ExprKind::CallableRef(Box::new(call)), line) } else { call };
                }
                T::Op(Op::Inc) => {
                    self.advance();
                    e = self.mk(ExprKind::IncDec(false, true, Box::new(e)), line);
                }
                T::Op(Op::Dec) => {
                    self.advance();
                    e = self.mk(ExprKind::IncDec(false, false, Box::new(e)), line);
                }
                _ => break,
            }
        }
        Ok(e)
    }

    fn parse_closure(&mut self, is_static: bool) -> PResult<Expr> {
        let line = self.line();
        let doc = self.toks[self.pos].doc.clone();
        let is_fn = self.is_kw("fn");
        self.advance();
        let by_ref = self.accept_op(Op::Amp);
        let cname = self.closure_name(line);
        if is_fn {
            self.scopes.push(Scope::new(true));
            self.func_ctx.push(cname.clone());
            self.method_ctx.push(String::new());
            let params = self.parse_params()?;
            let ret = if self.accept_op(Op::Colon) { Some(self.parse_type()?) } else { None };
            self.expect_op(Op::DoubleArrow)?;
            let body_e = self.parse_expr_bp(P_LOWEST)?;
            let bl = body_e.line;
            self.func_ctx.pop();
            self.method_ctx.pop();
            let sc = self.scopes.pop().unwrap();
            // captures
            let mut caps = Vec::new();
            let pnames: Vec<Name> = params.iter().map(|p| p.name.clone()).collect();
            for (i, n) in sc.names.iter().enumerate() {
                if pnames.contains(n) {
                    continue;
                }
                let outer = self.scope().slot(n);
                caps.push((outer, i as u32));
            }
            if sc.this_used {
                self.scope().this_used = true;
            }
            let f = Rc::new(FuncDecl {
                name: Rc::from(cname.as_str()),
                params,
                body: Some(vec![Stmt { kind: StmtKind::Return(Some(body_e)), line: bl }]),
                by_ref,
                ret,
                is_generator: sc.is_generator,
                num_slots: sc.names.len() as u32,
                slot_names: Rc::new(sc.names),
                this_used: sc.this_used,
                is_static,
                line,
                end_line: self.prev_line(),
                doc,
                statics: RefCell::new(Vec::new()),
                is_arrow: true,
                is_closure: true,
                uses_dynamic: sc.uses_dynamic,
                file: self.file.clone(),
                attrs: Vec::new(),
                id: Cell::new(0),
            });
            return Ok(self.mk(ExprKind::ArrowFn(f, caps, is_static), line));
        }
        let mut f = self.parse_function_rest(Rc::from(cname.as_str()), by_ref, true, false, line, doc)?;
        if let Some(fm) = Rc::get_mut(&mut f) {
            fm.is_static = is_static;
        }
        if f.this_used {
            self.scope().this_used = true;
        }
        let uses = self.take_uses();
        Ok(self.mk(ExprKind::Closure(f, uses, is_static), line))
    }

    fn parse_match(&mut self) -> PResult<Expr> {
        let line = self.line();
        self.advance();
        self.expect_op(Op::LParen)?;
        let subj = self.parse_expr()?;
        self.expect_op(Op::RParen)?;
        self.expect_op(Op::LBrace)?;
        let mut arms = Vec::new();
        while !self.accept_op(Op::RBrace) {
            let conds = if self.is_kw("default") && matches!(self.peek_at(1), T::Op(Op::DoubleArrow) | T::Op(Op::Comma)) {
                self.advance();
                self.accept_op(Op::Comma);
                None
            } else {
                let mut v = Vec::new();
                loop {
                    v.push(self.parse_expr()?);
                    if !self.accept_op(Op::Comma) {
                        break;
                    }
                    if self.is_op(Op::DoubleArrow) {
                        break;
                    }
                }
                Some(v)
            };
            self.expect_op(Op::DoubleArrow)?;
            let body = self.parse_expr()?;
            arms.push(MatchArm { conds, body });
            if !self.accept_op(Op::Comma) {
                self.expect_op(Op::RBrace)?;
                break;
            }
        }
        Ok(self.mk(ExprKind::Match(Box::new(subj), arms), line))
    }

    fn parse_template(&mut self, parts: Vec<TPart>) -> PResult<Vec<InterpPart>> {
        let mut out = Vec::new();
        for p in parts {
            match p {
                TPart::Lit(l) => out.push(InterpPart::Lit(Rc::new(l))),
                TPart::Expr(mut toks) => {
                    if let Some(first) = toks.first() {
                        if first.doc.as_deref() == Some("${") && matches!(first.t, T::Op(Op::DoubleArrow)) {
                            let l = first.line;
                            toks.remove(0);
                            self.warnings.push(("Deprecated: Using ${var} in strings is deprecated, use {$var} instead".to_string(), l));
                        }
                    }
                    let eof_line = toks.last().map(|t| t.line).unwrap_or(0);
                    toks.push(Token { t: T::Eof, line: eof_line, doc: None });
                    let saved_toks = std::mem::replace(&mut self.toks, toks);
                    let saved_pos = self.pos;
                    self.pos = 0;
                    let r = self.parse_expr();
                    let at_end = matches!(self.peek(), T::Eof);
                    let errline = self.line();
                    let unexpected = if !at_end { Some(tok_desc(self.peek())) } else { None };
                    self.toks = saved_toks;
                    self.pos = saved_pos;
                    let e = r?;
                    if let Some(u) = unexpected {
                        return Err(ParseError { msg: format!("syntax error, unexpected {}", u), line: errline });
                    }
                    out.push(InterpPart::Expr(e));
                }
            }
        }
        Ok(out)
    }
}
