pub const OBJ_NO_DTOR: u8 = 2;
pub const OBJ_CLONING: u8 = 4;
pub const OBJ_LAZY: u8 = 8;

thread_local! {
    pub static FREE_IDS: RefCell<Vec<u32>> = const { RefCell::new(Vec::new()) };
    pub static NEXT_ID: Cell<u32> = const { Cell::new(1) };
    pub static PENDING_DTORS: RefCell<Vec<Obj>> = const { RefCell::new(Vec::new()) };
    pub static PENDING_COUNT: Cell<usize> = const { Cell::new(0) };
    pub static LIVE_OBJECTS: RefCell<Vec<Weak<Object>>> = const { RefCell::new(Vec::new()) };
