    pub static GEN_DTOR_HOOK: Cell<Option<fn(&Object) -> bool>> = const { Cell::new(None) };
}

pub fn alloc_obj_id() -> u32 {
    let reuse = FREE_IDS.with(|f| f.borrow_mut().pop());
    match reuse {
        Some(id) => id,
        None => NEXT_ID.with(|n| {
            let id = n.get();
            n.set(id + 1);
            id
        }),
    }
}

