            class,
            slots: RefCell::new(slots),
            dynamic: RefCell::new(None),
            internal: RefCell::new(Internal::None),
            flags: Cell::new(0),
            guards: RefCell::new(Vec::new()),
            readonly_init: RefCell::new(vec![false; n]),
        });
