                class: self.class.clone(),
                slots: RefCell::new(std::mem::take(&mut *self.slots.borrow_mut())),
                dynamic: RefCell::new(self.dynamic.borrow_mut().take()),
                internal: RefCell::new(std::mem::replace(&mut *self.internal.borrow_mut(), Internal::None)),
                flags: Cell::new(flags | OBJ_DESTRUCTED),
                guards: RefCell::new(Vec::new()),
                readonly_init: RefCell::new(std::mem::take(&mut *self.readonly_init.borrow_mut())),
            });
