                    }
                }
            });
            PENDING_DTORS.with(|p| p.borrow_mut().push(o));
            PENDING_COUNT.with(|c| c.set(c.get() + 1));
            return;
        }
        // release id
        let id = self.id;
        LIVE_OBJECTS.with(|l| {
            if let Ok(mut l) = l.try_borrow_mut() {
                let idx = id as usize;
                if idx < l.len() {
                    l[idx] = Weak::new();
                }
            }
        });
        FREE_IDS.with(|f| {
            if let Ok(mut f) = f.try_borrow_mut() {
                f.push(id)
            }
        });
    }
