// Stackful coroutines (x86_64 SysV) used for generators and fibers.
use std::arch::naked_asm;
use std::cell::RefCell;
use std::ffi::c_void;

extern "C" {
    fn mmap(addr: *mut c_void, len: usize, prot: i32, flags: i32, fd: i32, off: i64) -> *mut c_void;
    fn munmap(addr: *mut c_void, len: usize) -> i32;
    fn mprotect(addr: *mut c_void, len: usize, prot: i32) -> i32;
}

const STACK_SIZE: usize = 8 * 1024 * 1024;
const GUARD: usize = 16 * 1024;

#[unsafe(naked)]
unsafe extern "C" fn ctx_switch(_save_sp: *mut *mut u8, _new_sp: *mut u8) {
    naked_asm!(
        "push rbp",
        "push rbx",
        "push r12",
        "push r13",
        "push r14",
        "push r15",
        "sub rsp, 8",
        "stmxcsr [rsp]",
        "fnstcw [rsp+4]",
        "mov [rdi], rsp",
        "mov rsp, rsi",
        "ldmxcsr [rsp]",
        "fldcw [rsp+4]",
        "add rsp, 8",
        "pop r15",
        "pop r14",
        "pop r13",
        "pop r12",
        "pop rbx",
        "pop rbp",
        "ret",
    )
}

#[unsafe(naked)]
unsafe extern "C" fn trampoline() {
    naked_asm!(
        "mov rdi, r12",
        "call {entry}",
        "ud2",
        entry = sym coro_entry,
    )
}

pub struct Coro {
    base: *mut u8,
    size: usize,
    sp: *mut u8,
    caller_sp: *mut u8,
    func: Option<Box<dyn FnOnce()>>,
    pub finished: bool,
    pub panicked: bool,
    pub running: bool,
}

thread_local! {
    static STACK_POOL: RefCell<Vec<*mut u8>> = const { RefCell::new(Vec::new()) };
}

fn alloc_stack() -> *mut u8 {
    if let Some(s) = STACK_POOL.with(|p| p.borrow_mut().pop()) {
        return s;
    }
    unsafe {
        let p = mmap(std::ptr::null_mut(), STACK_SIZE, 3, 0x02 | 0x20 | 0x4000, -1, 0);
        if p as isize == -1 {
            panic!("cannot allocate coroutine stack");
        }
        mprotect(p, GUARD, 0);
        p as *mut u8
    }
}

fn free_stack(p: *mut u8) {
    let pooled = STACK_POOL.with(|pool| {
        let mut pool = pool.borrow_mut();
        if pool.len() < 64 {
            pool.push(p);
            true
        } else {
            false
        }
    });
    if !pooled {
        unsafe {
            munmap(p as *mut c_void, STACK_SIZE);
        }
    }
}

