            E_WARNING | E_USER_WARNING => "Warning",
            E_PARSE => "Parse error",
            E_NOTICE | E_USER_NOTICE => "Notice",
            E_STRICT => "Strict Standards",
            E_DEPRECATED | E_USER_DEPRECATED => "Deprecated",
            _ => "Unknown error",
        }
    }

