    pub fn fatal(&mut self, msg: &str) -> Flow {
        let s = format!("\nFatal error: {} in {} on line {}\n", msg, self.cur_file, self.cur_line);
        self.last_error = Some((E_ERROR, msg.to_string(), self.cur_file.clone(), self.cur_line));
        self.echo(s.as_bytes());
        self.exit_code = 255;
        Flow::Fatal
    }

    pub fn fatal_at(&mut self, msg: &str, file: &str, line: u32) -> Flow {
        let s = format!("\nFatal error: {} in {} on line {}\n", msg, file, line);
        self.last_error = Some((E_ERROR, msg.to_string(), Rc::from(file), line));
        self.echo(s.as_bytes());
        self.exit_code = 255;
        Flow::Fatal
    }

    /// create a throwable of a builtin class and return Flow::Throw
    pub fn throw_err(&mut self, class: &str, msg: &str) -> Flow {
        match self.create_exception(class, msg, 0) {
            Ok(o) => Flow::Throw(o),
            Err(e) => e,
        }
    }
    pub fn type_error(&mut self, msg: &str) -> Flow {
        self.throw_err("TypeError", msg)
    }
    pub fn value_error(&mut self, msg: &str) -> Flow {
        self.throw_err("ValueError", msg)
    }
    pub fn error(&mut self, msg: &str) -> Flow {
        self.throw_err("Error", msg)
    }

    pub fn create_exception(&mut self, class: &str, msg: &str, code: i64) -> R<Obj> {
        let cls = self.lookup_class(class.as_bytes())?;
        let obj = self.instantiate_raw(&cls)?;
        self.init_exception(&obj, Some(Value::str(msg)), Some(Value::Int(code)), None);
        Ok(obj)
    }

    pub fn global_frame(&mut self) -> &mut Frame {
        unsafe { &mut *self.globals }
    }

    pub fn get_constant(&self, name: &[u8]) -> Option<Value> {
        if let Some(v) = self.constants.get(name) {
            return Some(v.clone());
        }
        // namespaced: case-insensitive namespace part
        if let Some(p) = name.iter().rposition(|&c| c == b'\\') {
            let mut k = name[..p].to_ascii_lowercase();
            k.extend_from_slice(&name[p..]);
            if let Some(v) = self.constants.get(&k) {
                return Some(v.clone());
            }
        }
        None
    }

    pub fn ini_get(&self, k: &str) -> Option<String> {
        self.ini.get(k).cloned()
    }

    /// run pending destructors
    #[inline]
    pub fn run_pending(&mut self) -> R<()> {
        if PENDING_COUNT.with(|c| c.get()) == 0 {
            return Ok(());
        }
        self.run_pending_slow()
    }

    pub fn run_pending_slow(&mut self) -> R<()> {
        loop {
            let o = PENDING_DTORS.with(|p| p.borrow_mut().pop());
            let o = match o {
                Some(o) => o,
                None => break,
            };
            PENDING_COUNT.with(|c| c.set(c.get().saturating_sub(1)));
            if gen::is_generator_obj(&o) {
                gen::destroy_generator(self, &o)?;
                continue;
            }
            if let Some(d) = o.class.magic.destruct.clone() {
                let line = self.cur_line;
                let r = self.call_method_obj(&o, &d, Vec::new());
                self.cur_line = line;
                match r {
                    Ok(_) => {}
                    Err(e) => return Err(e),
                }
            }
        }
        Ok(())
    }

    pub fn file_line(&self) -> (Rc<str>, u32) {
        (self.cur_file.clone(), self.cur_line)
    }
}

pub fn key_to_value(k: &Key) -> Value {
    k.to_value()
}

pub fn new_arr() -> PArray {
    PArray::new()
}
