pub const E_WARNING: i64 = 2;
pub const E_PARSE: i64 = 4;
pub const E_NOTICE: i64 = 8;
pub const E_CORE_ERROR: i64 = 16;
pub const E_COMPILE_ERROR: i64 = 64;
pub const E_USER_ERROR: i64 = 256;
pub const E_USER_WARNING: i64 = 512;
pub const E_USER_NOTICE: i64 = 1024;
pub const E_STRICT: i64 = 2048;
pub const E_RECOVERABLE_ERROR: i64 = 4096;
pub const E_DEPRECATED: i64 = 8192;
pub const E_USER_DEPRECATED: i64 = 16384;
pub const E_ALL: i64 = 32767;

pub enum Flow {
    Break(u32),
    Continue(u32),
    Return(Value),
    Throw(Obj),
    Exit(i32),
    Fatal,
    GenDestroy,
    Goto(Name),
}

pub type R<T> = Result<T, Flow>;

#[derive(Clone)]
pub enum Callable {
    User(Rc<FuncDecl>),
    Builtin(&'static crate::builtins::BuiltinDef),
}

impl std::fmt::Debug for Callable {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Callable")
    }
}

pub struct Frame {
    pub slots: Vec<Value>,
    pub names: Rc<Vec<Name>>,
    pub func: Option<Rc<FuncDecl>>,
    pub this: Option<Obj>,
    pub class: Option<Rc<Class>>,
    pub static_class: Option<Rc<Class>>,
    pub extra_args: Vec<Value>,
    pub num_args: usize,
    pub remap: Option<Rc<Vec<u32>>>,
    pub strict: bool,
    pub closure: Option<Obj>,
    pub file: Rc<str>,
    pub is_global: bool,
    pub method_name: Option<Name>,
}

impl Frame {
    pub fn new(num_slots: usize, names: Rc<Vec<Name>>, file: Rc<str>) -> Frame {
        Frame {
            slots: vec![Value::Undef; num_slots],
            names,
            func: None,
            this: None,
            class: None,
            static_class: None,
            extra_args: Vec::new(),
            num_args: 0,
            remap: None,
            strict: false,
            closure: None,
            file,
            is_global: false,
            method_name: None,
        }
    }
    #[inline]
    pub fn idx(&self, v: &VarRef) -> usize {
        match &self.remap {
            None => v.slot as usize,
            Some(m) => m[v.slot as usize] as usize,
        }
    }
    pub fn find_slot(&self, name: &[u8]) -> Option<usize> {
        self.names.iter().position(|n| n.as_bytes() == name)
    }
    /// find or create a slot for a dynamic name
    pub fn slot_for(&mut self, name: &[u8]) -> usize {
        if let Some(i) = self.find_slot(name) {
            return i;
        }
        let n: Name = Rc::from(String::from_utf8_lossy(name).as_ref());
        Rc::make_mut(&mut self.names).push(n);
        self.slots.push(Value::Undef);
        self.slots.len() - 1
    }
    /// ensure slots vector covers names
    pub fn sync(&mut self) {
        while self.slots.len() < self.names.len() {
            self.slots.push(Value::Undef);
        }
    }
}

