thread_local! {
    pub static INTERP: std::cell::Cell<*mut Interp> = const { std::cell::Cell::new(std::ptr::null_mut()) };
}

pub fn lc(s: &str) -> Vec<u8> {
    s.as_bytes().to_ascii_lowercase()
}

impl Interp {
    pub fn new() -> Box<Interp> {
        let mut it = Box::new(Interp {
            out: Vec::with_capacity(1 << 16),
            ob: Vec::new(),
            functions: HashMap::new(),
            classes: HashMap::new(),
            class_decls: HashMap::new(),
            constants: HashMap::new(),
            globals: std::ptr::null_mut(),
            call_stack: Vec::new(),
            cur_line: 0,
            cur_file: Rc::from(""),
            main_file: Rc::from(""),
            included: HashSet::new(),
            error_reporting: E_ALL,
            silence: 0,
            shutdown_funcs: Vec::new(),
            ini: HashMap::new(),
            mt: crate::builtins::rand::Mt::new(),
            statics: HashMap::new(),
            autoloaders: Vec::new(),
            error_handlers: Vec::new(),
            exception_handlers: Vec::new(),
            last_error: None,
            in_error_handler: false,
            gen_stack: Vec::new(),
            argv: Vec::new(),
            json_last_error: 0,
            preg_last_error: 0,
            class_id_counter: 0,
            func_id_counter: 0,
            regex_cache: HashMap::new(),
            autoload_in_progress: HashSet::new(),
            precision: 14,
            serialize_precision: -1,
            depth: 0,
            timezone: "UTC".to_string(),
            start_time: std::time::Instant::now(),
            exit_code: 0,
            fibers: Vec::new(),
            strict_files: HashSet::new(),
            stdin_buf: None,
            resources: HashMap::new(),
            next_resource: 4,
            compiled_files: HashMap::new(),
            srand_seeded: false,
            lcg_state: None,
            shutdown_started: false,
            var_dump_depth: 0,
            uncaught_in_progress: false,
            output_started: false,
            internal_class_names: HashSet::new(),
            prelude_done: false,
        });
        let p: *mut Interp = &mut *it;
        INTERP.with(|i| i.set(p));
        crate::builtins::register_all(&mut it);
        it
    }

    // ---------------- output ----------------
    #[inline]
    pub fn echo(&mut self, s: &[u8]) {
        if let Some(b) = self.ob.last_mut() {
            b.buf.extend_from_slice(s);
            return;
        }
        self.out.extend_from_slice(s);
        if self.out.len() > (1 << 16) {
            self.flush();
        }
    }
    pub fn echo_str(&mut self, s: &str) {
        self.echo(s.as_bytes());
    }
    pub fn flush(&mut self) {
        if !self.out.is_empty() {
            let stdout = std::io::stdout();
            let mut lock = stdout.lock();
            let _ = lock.write_all(&self.out);
            let _ = lock.flush();
            self.out.clear();
        }
    }

    // ---------------- errors ----------------
    pub fn error_type_name(level: i64) -> &'static str {
        match level {
            E_ERROR | E_CORE_ERROR | E_COMPILE_ERROR | E_USER_ERROR => "Fatal error",
            E_RECOVERABLE_ERROR => "Recoverable fatal error",
            E_WARNING | E_USER_WARNING => "Warning",
            E_PARSE => "Parse error",
            E_NOTICE | E_USER_NOTICE => "Notice",
            E_STRICT => "Strict Standards",
            E_DEPRECATED | E_USER_DEPRECATED => "Deprecated",
            _ => "Unknown error",
        }
    }

    pub fn raise(&mut self, level: i64, msg: &str) -> R<()> {
        let file = self.cur_file.clone();
        let line = self.cur_line;
        self.raise_at(level, msg, file, line)
    }

    pub fn raise_at(&mut self, level: i64, msg: &str, file: Rc<str>, line: u32) -> R<()> {
        self.last_error = Some((level, msg.to_string(), file.clone(), line));
        // user error handler
        if !self.in_error_handler {
            if let Some((h, mask)) = self.error_handlers.last().cloned() {
                if !h.is_null() && (mask & level) != 0 {
                    // handler is called even when silenced (error_reporting() returns reduced value)
                    self.in_error_handler = true;
                    let args = vec![Value::Int(level), Value::str(msg), Value::str(&file), Value::Int(line as i64)];
                    let r = self.call_value(&h, args);
                    self.in_error_handler = false;
                    match r {
                        Ok(v) => {
                            if !matches!(v, Value::Bool(false)) {
                                return Ok(());
                            }
                        }
                        Err(e) => return Err(e),
                    }
                }
            }
        }
        if self.silence > 0 && level & (E_ERROR | E_CORE_ERROR | E_COMPILE_ERROR | E_USER_ERROR | E_PARSE | E_RECOVERABLE_ERROR) == 0 {
            return Ok(());
        }
        if self.error_reporting & level == 0 {
            return Ok(());
        }
        if self.ini.get("display_errors").map(|s| s == "0" || s.eq_ignore_ascii_case("off") || s.is_empty()).unwrap_or(false) {
            return Ok(());
        }
        let s = format!("\n{}: {} in {} on line {}\n", Self::error_type_name(level), msg, file, line);
        self.echo(s.as_bytes());
        Ok(())
    }

    pub fn warn(&mut self, msg: &str) -> R<()> {
        self.raise(E_WARNING, msg)
    }
    pub fn notice(&mut self, msg: &str) -> R<()> {
        self.raise(E_NOTICE, msg)
    }
    pub fn deprecated(&mut self, msg: &str) -> R<()> {
        self.raise(E_DEPRECATED, msg)
    }

    /// print fatal error and return Flow::Fatal
    pub fn fatal(&mut self, msg: &str) -> Flow {
        let s = format!("\nFatal error: {} in {} on line {}\n", msg, self.cur_file, self.cur_line);
        self.last_error = Some((E_ERROR, msg.to_string(), self.cur_file.clone(), self.cur_line));
        self.echo(s.as_bytes());
        self.exit_code = 255;
        Flow::Fatal
    }

    pub fn fatal_at(&mut self, msg: &str, file: &str, line: u32) -> Flow {
        let s = format!("\nFatal error: {} in {} on line {}\n", msg, file, line);
        self.last_error = Some((E_ERROR, msg.to_string(), Rc::from(file), line));
        self.echo(s.as_bytes());
        self.exit_code = 255;
        Flow::Fatal
    }

    /// create a throwable of a builtin class and return Flow::Throw
    pub fn throw_err(&mut self, class: &str, msg: &str) -> Flow {
        match self.create_exception(class, msg, 0) {
            Ok(o) => Flow::Throw(o),
            Err(e) => e,
        }
    }
    pub fn type_error(&mut self, msg: &str) -> Flow {
        self.throw_err("TypeError", msg)
    }
    pub fn value_error(&mut self, msg: &str) -> Flow {
        self.throw_err("ValueError", msg)
    }
    pub fn error(&mut self, msg: &str) -> Flow {
        self.throw_err("Error", msg)
    }

    pub fn create_exception(&mut self, class: &str, msg: &str, code: i64) -> R<Obj> {
        let cls = self.lookup_class(class.as_bytes())?;
        let obj = self.instantiate_raw(&cls)?;
        self.init_exception(&obj, Some(Value::str(msg)), Some(Value::Int(code)), None);
        Ok(obj)
    }

    pub fn global_frame(&mut self) -> &mut Frame {
        unsafe { &mut *self.globals }
    }

    pub fn get_constant(&self, name: &[u8]) -> Option<Value> {
        if let Some(v) = self.constants.get(name) {
            return Some(v.clone());
        }
        // namespaced: case-insensitive namespace part
        if let Some(p) = name.iter().rposition(|&c| c == b'\\') {
            let mut k = name[..p].to_ascii_lowercase();
            k.extend_from_slice(&name[p..]);
            if let Some(v) = self.constants.get(&k) {
                return Some(v.clone());
            }
        }
        None
    }

    pub fn ini_get(&self, k: &str) -> Option<String> {
        self.ini.get(k).cloned()
    }

    /// run pending destructors
    #[inline]
    pub fn run_pending(&mut self) -> R<()> {
        if PENDING_COUNT.with(|c| c.get()) == 0 {
            return Ok(());
        }
        self.run_pending_slow()
    }

    pub fn run_pending_slow(&mut self) -> R<()> {
        loop {
            let o = PENDING_DTORS.with(|p| p.borrow_mut().pop());
            let o = match o {
                Some(o) => o,
                None => break,
            };
            PENDING_COUNT.with(|c| c.set(c.get().saturating_sub(1)));
            if gen::is_generator_obj(&o) {
                gen::destroy_generator(self, &o)?;
                continue;
            }
            if let Some(d) = o.class.magic.destruct.clone() {
                let line = self.cur_line;
                let r = self.call_method_obj(&o, &d, Vec::new());
                self.cur_line = line;
                match r {
                    Ok(_) => {}
                    Err(e) => return Err(e),
                }
            }
        }
        Ok(())
    }

    pub fn file_line(&self) -> (Rc<str>, u32) {
        (self.cur_file.clone(), self.cur_line)
    }
}

pub fn key_to_value(k: &Key) -> Value {
    k.to_value()
}

pub fn new_arr() -> PArray {
    PArray::new()
}
