use super::*;
use crate::array::PArray;
use crate::ast::BinOp;

pub fn binop_str(op: BinOp) -> &'static str {
    match op {
        BinOp::Add => "+",
        BinOp::Sub => "-",
        BinOp::Mul => "*",
        BinOp::Div => "/",
        BinOp::Mod => "%",
        BinOp::Pow => "**",
        BinOp::Concat => ".",
        BinOp::BitAnd => "&",
        BinOp::BitOr => "|",
        BinOp::BitXor => "^",
        BinOp::Shl => "<<",
        BinOp::Shr => ">>",
        _ => "?",
    }
}

pub fn type_for_op(v: &Value) -> String {
    match v {
        Value::Object(o) => o.class.name.to_string(),
        Value::Ref(r) => type_for_op(&r.borrow()),
        _ => v.type_name().to_string(),
    }
}

impl Interp {
    /// convert operand to number for arithmetic. Returns None if unsupported type.
    pub fn op_num(&mut self, v: &Value) -> R<Option<Num>> {
        Ok(Some(match v {
            Value::Int(i) => Num::Int(*i),
            Value::Float(f) => Num::Float(*f),
            Value::Null | Value::Undef => Num::Int(0),
            Value::Bool(b) => Num::Int(*b as i64),
            Value::Str(s) => match parse_numeric_prefix(s) {
                Some((n, true)) => n,
                Some((n, false)) => {
                    self.warn("A non-numeric value encountered")?;
                    n
                }
                None => return Ok(None),
            },
            Value::Ref(r) => {
                let v = r.borrow().clone();
                return self.op_num(&v);
            }
            _ => return Ok(None),
        }))
    }

    fn unsupported(&mut self, op: BinOp, a: &Value, b: &Value) -> Flow {
        let msg = format!("Unsupported operand types: {} {} {}", type_for_op(a), binop_str(op), type_for_op(b));
        self.type_error(&msg)
    }

    pub fn arith(&mut self, op: BinOp, a: &Value, b: &Value) -> R<Value> {
        // fast paths
        match (a, b) {
            (Value::Int(x), Value::Int(y)) => {
                let (x, y) = (*x, *y);
                match op {
                    BinOp::Add => {
                        return Ok(match x.checked_add(y) {
                            Some(r) => Value::Int(r),
                            None => Value::Float(x as f64 + y as f64),
                        })
                    }
                    BinOp::Sub => {
                        return Ok(match x.checked_sub(y) {
                            Some(r) => Value::Int(r),
                            None => Value::Float(x as f64 - y as f64),
                        })
                    }
                    BinOp::Mul => {
                        return Ok(match x.checked_mul(y) {
                            Some(r) => Value::Int(r),
                            None => Value::Float(x as f64 * y as f64),
                        })
                    }
                    _ => {}
                }
            }
            (Value::Float(x), Value::Float(y)) => match op {
                BinOp::Add => return Ok(Value::Float(x + y)),
                BinOp::Sub => return Ok(Value::Float(x - y)),
                BinOp::Mul => return Ok(Value::Float(x * y)),
                _ => {}
            },
            _ => {}
        }
        match op {
            BinOp::Concat => {
                let mut s = self.to_str(a)?.to_vec();
                let t = self.to_str(b)?;
                s.extend_from_slice(&t);
                return Ok(Value::vec(s));
            }
            BinOp::BitAnd | BinOp::BitOr | BinOp::BitXor => return self.bitwise(op, a, b),
            BinOp::Shl | BinOp::Shr => {
                let x = self.int_operand(op, a, b, true)?;
                let y = self.int_operand(op, a, b, false)?;
                if y < 0 {
                    return Err(self.throw_err("ArithmeticError", "Bit shift by negative number"));
                }
                return Ok(Value::Int(if op == BinOp::Shl {
                    if y >= 64 {
                        0
                    } else {
                        x.wrapping_shl(y as u32)
                    }
                } else if y >= 64 {
                    if x < 0 {
                        -1
                    } else {
                        0
                    }
                } else {
                    x >> y
                }));
            }
            BinOp::Mod => {
                let x = self.int_operand(op, a, b, true)?;
                let y = self.int_operand(op, a, b, false)?;
                if y == 0 {
                    return Err(self.throw_err("DivisionByZeroError", "Modulo by zero"));
                }
                if y == -1 {
                    return Ok(Value::Int(0));
                }
                return Ok(Value::Int(x % y));
            }
            _ => {}
        }
        let a = a.deref();
        let b = b.deref();
        if let (Value::Array(x), Value::Array(y)) = (&a, &b) {
            if op == BinOp::Add {
                let mut r = (**x).clone();
                for (k, v) in y.iter() {
                    if !r.contains_key(k) {
                        r.set(k.clone(), v.clone());
                    }
                }
                return Ok(Value::Array(Rc::new(r)));
            }
            return Err(self.unsupported(op, &a, &b));
        }
        if matches!(a, Value::Array(_) | Value::Object(_)) || matches!(b, Value::Array(_) | Value::Object(_)) {
            return Err(self.unsupported(op, &a, &b));
        }
        let na = match self.op_num(&a)? {
            Some(n) => n,
            None => return Err(self.unsupported(op, &a, &b)),
        };
        let nb = match self.op_num(&b)? {
            Some(n) => n,
            None => return Err(self.unsupported(op, &a, &b)),
        };
        self.arith_num(op, na, nb)
    }

    pub fn arith_num(&mut self, op: BinOp, na: Num, nb: Num) -> R<Value> {
        Ok(match op {
            BinOp::Add => match (na, nb) {
                (Num::Int(x), Num::Int(y)) => match x.checked_add(y) {
                    Some(r) => Value::Int(r),
                    None => Value::Float(x as f64 + y as f64),
                },
                _ => Value::Float(na.as_f64() + nb.as_f64()),
            },
            BinOp::Sub => match (na, nb) {
                (Num::Int(x), Num::Int(y)) => match x.checked_sub(y) {
                    Some(r) => Value::Int(r),
                    None => Value::Float(x as f64 - y as f64),
                },
                _ => Value::Float(na.as_f64() - nb.as_f64()),
            },
            BinOp::Mul => match (na, nb) {
                (Num::Int(x), Num::Int(y)) => match x.checked_mul(y) {
                    Some(r) => Value::Int(r),
                    None => Value::Float(x as f64 * y as f64),
                },
                _ => Value::Float(na.as_f64() * nb.as_f64()),
            },
            BinOp::Div => {
                let zero = match nb {
                    Num::Int(0) => true,
                    Num::Float(f) => f == 0.0,
                    _ => false,
                };
                if zero {
                    return Err(self.throw_err("DivisionByZeroError", "Division by zero"));
                }
                match (na, nb) {
                    (Num::Int(x), Num::Int(y)) => {
                        if y == -1 && x == i64::MIN {
                            Value::Float(x as f64 / y as f64)
                        } else if x % y == 0 {
                            Value::Int(x / y)
                        } else {
                            Value::Float(x as f64 / y as f64)
                        }
                    }
                    _ => Value::Float(na.as_f64() / nb.as_f64()),
                }
            }
            BinOp::Pow => match (na, nb) {
                (Num::Int(x), Num::Int(y)) if y >= 0 => {
                    let mut result: i64 = 1;
                    let mut base = x;
                    let mut e = y;
                    let mut overflow = false;
                    while e > 0 {
                        if e & 1 == 1 {
                            match result.checked_mul(base) {
                                Some(r) => result = r,
                                None => {
                                    overflow = true;
                                    break;
                                }
                            }
                        }
                        e >>= 1;
                        if e > 0 {
                            match base.checked_mul(base) {
                                Some(b) => base = b,
                                None => {
                                    overflow = true;
                                    break;
                                }
                            }
                        }
                    }
                    if overflow {
                        Value::Float((x as f64).powf(y as f64))
                    } else {
                        Value::Int(result)
                    }
                }
                _ => Value::Float(na.as_f64().powf(nb.as_f64())),
            },
            _ => Value::Null,
        })
    }

    /// integer operand for %, <<, >> and bitwise ops
    fn int_operand(&mut self, op: BinOp, a: &Value, b: &Value, left: bool) -> R<i64> {
        let v = if left { a.deref() } else { b.deref() };
        match &v {
            Value::Int(i) => Ok(*i),
            Value::Float(f) => self.float_to_int_op(*f),
            Value::Null | Value::Undef => Ok(0),
            Value::Bool(x) => Ok(*x as i64),
            Value::Str(_) => match self.op_num(&v)? {
                Some(Num::Int(i)) => Ok(i),
                Some(Num::Float(f)) => self.float_to_int_op(f),
                None => Err(self.unsupported(op, &a.deref(), &b.deref())),
            },
            _ => Err(self.unsupported(op, &a.deref(), &b.deref())),
        }
    }

    pub fn float_to_int_op(&mut self, f: f64) -> R<i64> {
        if !f.is_finite() || !float_fits_int(f) {
            let s = fmt_float_repr(f);
            self.warn(&format!("The float {} is not representable as an int, cast occurred", s))?;
            return Ok(float_to_int(f));
        }
        if f.fract() != 0.0 {
            let s = fmt_float_repr(f);
            self.deprecated(&format!("Implicit conversion from float {} to int loses precision", s))?;
        }
        Ok(f as i64)
    }

    fn bitwise(&mut self, op: BinOp, a: &Value, b: &Value) -> R<Value> {
        let a = a.deref();
        let b = b.deref();
        if let (Value::Str(x), Value::Str(y)) = (&a, &b) {
            let r: Vec<u8> = match op {
                BinOp::BitAnd => x.iter().zip(y.iter()).map(|(p, q)| p & q).collect(),
                BinOp::BitXor => x.iter().zip(y.iter()).map(|(p, q)| p ^ q).collect(),
                _ => {
                    let (long, short) = if x.len() >= y.len() { (x, y) } else { (y, x) };
                    let mut r = long.to_vec();
                    for (i, c) in short.iter().enumerate() {
                        r[i] |= c;
                    }
                    r
                }
            };
            return Ok(Value::vec(r));
        }
        let x = self.int_operand(op, &a, &b, true)?;
        let y = self.int_operand(op, &a, &b, false)?;
        Ok(Value::Int(match op {
            BinOp::BitAnd => x & y,
            BinOp::BitOr => x | y,
            _ => x ^ y,
        }))
    }

    pub fn bitnot(&mut self, v: &Value) -> R<Value> {
        match v.deref() {
            Value::Int(i) => Ok(Value::Int(!i)),
            Value::Float(f) => {
                let i = self.float_to_int_op(f)?;
                Ok(Value::Int(!i))
            }
            Value::Str(s) => Ok(Value::vec(s.iter().map(|c| !c).collect())),
            other => {
                let msg = format!("Cannot perform bitwise not on {}", type_for_op(&other));
                Err(self.type_error(&msg))
            }
        }
    }

    pub fn negate(&mut self, v: &Value) -> R<Value> {
        match v.deref() {
            Value::Int(i) => Ok(match i.checked_neg() {
                Some(r) => Value::Int(r),
                None => Value::Float(-(i as f64)),
            }),
            Value::Float(f) => Ok(Value::Float(-f)),
            other => self.arith(BinOp::Mul, &other, &Value::Int(-1)),
        }
    }

    pub fn unary_plus(&mut self, v: &Value) -> R<Value> {
        match v.deref() {
            Value::Int(i) => Ok(Value::Int(i)),
            Value::Float(f) => Ok(Value::Float(f)),
            other => self.arith(BinOp::Mul, &other, &Value::Int(1)),
        }
    }

    // ---------------- conversions ----------------
    pub fn to_str(&mut self, v: &Value) -> R<PStr> {
        match v {
            Value::Str(s) => Ok(s.clone()),
            Value::Int(i) => Ok(Rc::new(i.to_string().into_bytes())),
            Value::Float(f) => {
                if f.is_nan() {
                    self.warn("unexpected NAN value was coerced to string")?;
                }
                Ok(Rc::new(fmt_float_prec(*f, self.precision).into_bytes()))
            }
            Value::Null | Value::Undef => Ok(Rc::new(Vec::new())),
            Value::Bool(b) => Ok(Rc::new(if *b { b"1".to_vec() } else { Vec::new() })),
            Value::Array(_) => {
                self.warn("Array to string conversion")?;
                Ok(Rc::new(b"Array".to_vec()))
            }
            Value::Object(o) => {
                let o = o.clone();
                self.obj_to_string(&o)
            }
            Value::Ref(r) => {
                let v = r.borrow().clone();
                self.to_str(&v)
            }
        }
    }

    pub fn obj_to_string(&mut self, o: &Obj) -> R<PStr> {
        if let Some(m) = o.class.magic.tostring.clone() {
            let r = self.call_method_obj(o, &m, Vec::new())?;
            match r {
                Value::Str(s) => return Ok(s),
                _ => {
                    let msg = format!("{}::__toString(): Return value must be of type string, {} returned", o.class.name, r.type_name());
                    return Err(self.type_error(&msg));
                }
            }
        }
        let msg = format!("Object of class {} could not be converted to string", o.class.name);
        Err(self.error(&msg))
    }

    pub fn to_string_lossy(&mut self, v: &Value) -> R<String> {
        let s = self.to_str(v)?;
        Ok(String::from_utf8_lossy(&s).into_owned())
    }

    /// (int) cast semantics
    pub fn to_int_cast(&mut self, v: &Value) -> R<i64> {
        match v {
            Value::Float(f) => {
                if !float_fits_int(*f) {
                    let s = fmt_float_repr(*f);
                    self.warn(&format!("The float {} is not representable as an int, cast occurred", s))?;
                }
                Ok(float_to_int(*f))
            }
            Value::Object(o) => {
                let msg = format!("Object of class {} could not be converted to int", o.class.name);
                self.warn(&msg)?;
                Ok(1)
            }
            Value::Ref(r) => {
                let v = r.borrow().clone();
                self.to_int_cast(&v)
            }
            _ => Ok(v.to_int()),
        }
    }

    pub fn to_float_cast(&mut self, v: &Value) -> R<f64> {
        match v {
            Value::Object(o) => {
                let msg = format!("Object of class {} could not be converted to float", o.class.name);
                self.warn(&msg)?;
                Ok(1.0)
            }
            Value::Ref(r) => {
                let v = r.borrow().clone();
                self.to_float_cast(&v)
            }
            _ => Ok(v.to_float()),
        }
    }

    // ---------------- comparisons ----------------
    pub fn strict_eq(&self, a: &Value, b: &Value) -> bool {
        strict_equals(a, b)
    }

    pub fn loose_eq(&mut self, a: &Value, b: &Value) -> R<bool> {
        match (a, b) {
            (Value::Int(x), Value::Int(y)) => return Ok(x == y),
            (Value::Str(x), Value::Str(y)) => {
                if Rc::ptr_eq(x, y) {
                    return Ok(true);
                }
                return Ok(match (str_numeric(x), str_numeric(y)) {
                    (Some(p), Some(q)) => num_cmp(p, q) == 0,
                    _ => x.as_slice() == y.as_slice(),
                });
            }
            (Value::Object(x), Value::Object(y)) => {
                if Rc::ptr_eq(x, y) {
                    return Ok(true);
                }
                if !Rc::ptr_eq(&x.class, &y.class) && x.class.lname != y.class.lname {
                    return Ok(false);
                }
                return Ok(self.compare(a, b)? == 0);
            }
            (Value::Array(x), Value::Array(y)) => {
                if x.len() != y.len() {
                    return Ok(false);
                }
                let (x, y) = (x.clone(), y.clone());
                for (k, v) in x.iter() {
                    match y.get(k) {
                        Some(w) => {
                            if !self.loose_eq(&v.deref(), &w.deref())? {
                                return Ok(false);
                            }
                        }
                        None => return Ok(false),
                    }
                }
                return Ok(true);
            }
            (Value::Ref(r), _) => {
                let v = r.borrow().clone();
                return self.loose_eq(&v, b);
            }
            (_, Value::Ref(r)) => {
                let v = r.borrow().clone();
                return self.loose_eq(a, &v);
            }
            _ => {}
        }
        Ok(self.compare(a, b)? == 0)
    }

    /// zend_compare semantics: returns -1, 0, 1
    pub fn compare(&mut self, a: &Value, b: &Value) -> R<i32> {
        use Value::*;
        Ok(match (a, b) {
            (Ref(r), _) => {
                let v = r.borrow().clone();
                return self.compare(&v, b);
            }
            (_, Ref(r)) => {
                let v = r.borrow().clone();
                return self.compare(a, &v);
            }
            (Int(x), Int(y)) => cmp_i(*x, *y),
            (Int(x), Float(y)) => cmp_f(*x as f64, *y),
            (Float(x), Int(y)) => cmp_f(*x, *y as f64),
            (Float(x), Float(y)) => cmp_f(*x, *y),
            (Array(x), Array(y)) => {
                let (x, y) = (x.clone(), y.clone());
                return self.compare_arrays(&x, &y);
            }
            (Null | Undef, Null | Undef) => 0,
            (Null | Undef, Bool(y)) => cmp_i(0, *y as i64),
            (Bool(x), Null | Undef) => cmp_i(*x as i64, 0),
            (Bool(x), Bool(y)) => cmp_i(*x as i64, *y as i64),
            (Str(x), Str(y)) => {
                if Rc::ptr_eq(x, y) {
                    return Ok(0);
                }
                match (str_numeric(x), str_numeric(y)) {
                    (Some(p), Some(q)) => num_cmp(p, q),
                    _ => byte_cmp(x, y),
                }
            }
            (Null | Undef, Str(y)) => byte_cmp(b"", y),
            (Str(x), Null | Undef) => byte_cmp(x, b""),
            (Null | Undef, Object(_)) => -1,
            (Object(_), Null | Undef) => 1,
            (Null | Undef, _) => cmp_i(0, b.to_bool() as i64),
            (_, Null | Undef) => cmp_i(a.to_bool() as i64, 0),
            (Bool(x), _) => cmp_i(*x as i64, b.to_bool() as i64),
            (_, Bool(y)) => cmp_i(a.to_bool() as i64, *y as i64),
            (Int(_) | Float(_), Str(s)) => {
                let n = if let Int(i) = a { Num::Int(*i) } else { Num::Float(a.to_float()) };
                match str_numeric(s) {
                    Some(q) => num_cmp(n, q),
                    None => {
