                let n = if let Int(i) = b { Num::Int(*i) } else { Num::Float(b.to_float()) };
                match str_numeric(s) {
                    Some(q) => num_cmp(q, n),
                    None => {
                        let ns = self.to_str(b)?;
                        byte_cmp(s, &ns)
                    }
                }
            }
            (Array(_), _) => 1,
            (_, Array(_)) => -1,
            (Object(x), Object(y)) => {
                if Rc::ptr_eq(x, y) {
                    return Ok(0);
                }
                if x.class.lname != y.class.lname {
                    return Ok(1);
                }
                // compare properties
                let px = self.object_prop_array(x);
                let py = self.object_prop_array(y);
                return self.compare_arrays(&px, &py);
            }
            (Object(o), Str(s)) => {
                if o.class.magic.tostring.is_some() {
                    let o = o.clone();
                    let t = self.obj_to_string(&o)?;
                    byte_cmp(&t, s)
                } else {
                    1
                }
            }
            (Str(s), Object(o)) => {
                if o.class.magic.tostring.is_some() {
                    let o = o.clone();
                    let t = self.obj_to_string(&o)?;
                    byte_cmp(s, &t)
                } else {
                    -1
                }
            }
            (Object(o), _) => {
                let msg = format!("Object of class {} could not be converted to {}", o.class.name, if matches!(b, Float(_)) { "float" } else { "int" });
                self.notice(&msg)?;
                match b {
                    Float(f) => cmp_f(1.0, *f),
                    _ => cmp_i(1, b.to_int()),
                }
            }
            (_, Object(o)) => {
                let msg = format!("Object of class {} could not be converted to {}", o.class.name, if matches!(a, Float(_)) { "float" } else { "int" });
                self.notice(&msg)?;
                match a {
                    Float(f) => cmp_f(*f, 1.0),
                    _ => cmp_i(a.to_int(), 1),
                }
            }
        })
    }

    pub fn compare_arrays(&mut self, x: &PArray, y: &PArray) -> R<i32> {
        if x.len() != y.len() {
            return Ok(cmp_i(x.len() as i64, y.len() as i64));
        }
        for (k, v) in x.iter() {
            match y.get(k) {
                Some(w) => {
                    let (v, w) = (v.deref(), w.deref());
                    let c = self.compare(&v, &w)?;
                    if c != 0 {
                        return Ok(c);
                    }
                }
                None => return Ok(1),
            }
        }
        Ok(0)
    }

    pub fn is_smaller(&mut self, a: &Value, b: &Value) -> R<bool> {
        if let (Value::Int(x), Value::Int(y)) = (a, b) {
            return Ok(x < y);
        }
        if let (Value::Float(x), Value::Float(y)) = (a, b) {
            return Ok(x < y);
        }
        Ok(self.compare(a, b)? < 0)
    }
    pub fn is_smaller_or_equal(&mut self, a: &Value, b: &Value) -> R<bool> {
        if let (Value::Int(x), Value::Int(y)) = (a, b) {
            return Ok(x <= y);
        }
        if let (Value::Float(x), Value::Float(y)) = (a, b) {
            return Ok(x <= y);
        }
        Ok(self.compare(a, b)? <= 0)
    }
}

#[inline]
pub fn cmp_i(a: i64, b: i64) -> i32 {
    if a < b {
        -1
    } else if a > b {
        1
    } else {
        0
    }
}
#[inline]
pub fn cmp_f(a: f64, b: f64) -> i32 {
    if a < b {
        -1
    } else if a > b {
        1
    } else if a == b {
        0
    } else {
        1 // NAN: uncomparable
    }
}
pub fn num_cmp(a: Num, b: Num) -> i32 {
    match (a, b) {
        (Num::Int(x), Num::Int(y)) => cmp_i(x, y),
        _ => cmp_f(a.as_f64(), b.as_f64()),
    }
}
pub fn byte_cmp(a: &[u8], b: &[u8]) -> i32 {
    match a.cmp(b) {
        std::cmp::Ordering::Less => -1,
        std::cmp::Ordering::Equal => 0,
        std::cmp::Ordering::Greater => 1,
    }
}

pub fn strict_equals(a: &Value, b: &Value) -> bool {
    use Value::*;
    match (a, b) {
        (Ref(r), _) => strict_equals(&r.borrow(), b),
        (_, Ref(r)) => strict_equals(a, &r.borrow()),
        (Null | Undef, Null | Undef) => true,
        (Bool(x), Bool(y)) => x == y,
        (Int(x), Int(y)) => x == y,
        (Float(x), Float(y)) => x == y,
        (Str(x), Str(y)) => Rc::ptr_eq(x, y) || x.as_slice() == y.as_slice(),
        (Array(x), Array(y)) => {
            if Rc::ptr_eq(x, y) {
                return true;
            }
            if x.len() != y.len() {
                return false;
            }
            let mut ix = x.iter();
            let mut iy = y.iter();
            loop {
                match (ix.next(), iy.next()) {
                    (None, None) => return true,
                    (Some((k1, v1)), Some((k2, v2))) => {
                        if k1 != k2 || !strict_equals(v1, v2) {
                            return false;
                        }
                    }
                    _ => return false,
                }
            }
        }
        (Object(x), Object(y)) => Rc::ptr_eq(x, y),
        _ => false,
    }
}
