use std::rc::Rc;

pub type BuiltinFn = fn(&mut Interp, &mut Args) -> R<Value>;

pub struct ParamSpec {
    pub name: &'static str,
    pub by_ref: bool,
    pub optional: bool,
    pub variadic: bool,
}

pub struct BuiltinDef {
    pub name: &'static str,
    pub f: BuiltinFn,
    pub params: Vec<ParamSpec>,
    pub min: usize,
    pub variadic: bool,
}

impl BuiltinDef {
    pub fn by_ref(&self, i: usize) -> bool {
        if i < self.params.len() {
            self.params[i].by_ref
        } else if self.variadic {
            self.params.last().map(|p| p.by_ref).unwrap_or(false)
        } else {
            false
        }
    }
    pub fn param_name(&self, i: usize) -> &'static str {
        if i < self.params.len() {
            self.params[i].name
        } else {
            self.params.last().map(|p| p.name).unwrap_or("")
        }
    }
}

pub struct Args {
    pub v: Vec<Value>,
    pub def: &'static BuiltinDef,
}

pub fn parse_spec(spec: &'static str) -> (Vec<ParamSpec>, usize, bool) {
    let mut params = Vec::new();
    let mut min = 0;
    let mut variadic = false;
    if spec.is_empty() {
        return (params, 0, false);
    }
    for p in spec.split(',') {
        let mut p = p.trim();
        let mut by_ref = false;
        let mut optional = false;
        let mut var = false;
        if let Some(r) = p.strip_prefix('&') {
            by_ref = true;
            p = r;
        }
        if let Some(r) = p.strip_prefix("...") {
            var = true;
            variadic = true;
            p = r;
        }
        if let Some(r) = p.strip_suffix('?') {
            optional = true;
            p = r;
        }
        if !optional && !var {
            min = params.len() + 1;
        }
        params.push(ParamSpec { name: p, by_ref, optional, variadic: var });
    }
    (params, min, variadic)
}

pub fn reg(it: &mut Interp, name: &'static str, spec: &'static str, f: BuiltinFn) {
    let (params, min, variadic) = parse_spec(spec);
    let def: &'static BuiltinDef = Box::leak(Box::new(BuiltinDef { name, f, params, min, variadic }));
    it.functions.insert(name.as_bytes().to_ascii_lowercase(), Callable::Builtin(def));
}

