use super::*;
use crate::array::{Key, PArray};
use crate::ast::*;

impl Interp {
    #[inline]
    pub fn read_var(&mut self, f: &Frame, v: &VarRef, line: u32) -> R<Value> {
        let i = f.idx(v);
        match f.slots.get(i) {
            Some(Value::Ref(r)) => {
                let b = r.borrow();
                if let Value::Undef = *b {
                    drop(b);
                    self.cur_line = line;
                    self.warn(&format!("Undefined variable ${}", v.name))?;
                    return Ok(Value::Null);
                }
                Ok(b.clone())
            }
            Some(Value::Undef) | None => {
                self.cur_line = line;
                self.warn(&format!("Undefined variable ${}", v.name))?;
                Ok(Value::Null)
            }
            Some(v) => Ok(v.clone()),
        }
    }

    pub fn eval(&mut self, f: &mut Frame, e: &Expr) -> R<Value> {
        match &e.kind {
            ExprKind::Lit(v) => Ok(v.clone()),
            ExprKind::Var(v) => self.read_var(f, v, e.line),
            ExprKind::This => match &f.this {
                Some(o) => Ok(Value::Object(o.clone())),
                None => {
                    self.cur_line = e.line;
                    Err(self.error("Using $this when not in object context"))
                }
            },
            ExprKind::Super(n) => self.read_super(f, n),
            ExprKind::VarVar(ne) => {
                let nv = self.eval(f, ne)?;
                let name = self.to_str(&nv)?;
                if name.as_slice() == b"this" {
                    if let Some(o) = &f.this {
                        return Ok(Value::Object(o.clone()));
                    }
                }
                match f.find_slot(&name) {
                    Some(i) if !matches!(f.slots.get(i), Some(Value::Undef) | None) => Ok(f.slots[i].deref()),
                    _ => {
                        self.cur_line = e.line;
                        self.warn(&format!("Undefined variable ${}", String::from_utf8_lossy(&name)))?;
                        Ok(Value::Null)
                    }
                }
            }
            ExprKind::Interp(parts) => {
                let mut out: Vec<u8> = Vec::new();
                for p in parts {
                    match p {
                        InterpPart::Lit(l) => out.extend_from_slice(l),
                        InterpPart::Expr(x) => {
                            let v = self.eval(f, x)?;
                            match &v {
                                Value::Str(s) => out.extend_from_slice(s),
                                Value::Int(i) => out.extend_from_slice(i.to_string().as_bytes()),
                                _ => {
                                    self.cur_line = x.line;
                                    let s = self.to_str(&v)?;
                                    out.extend_from_slice(&s);
                                }
                            }
                        }
                    }
                }
                Ok(Value::vec(out))
            }
            ExprKind::Array(items) => self.eval_array_lit(f, items),
            ExprKind::List(..) => {
                self.cur_line = e.line;
                Err(self.fatal("Cannot use list() outside assignment context"))
            }
            ExprKind::Index(..) | ExprKind::Prop(..) | ExprKind::MethodCall(..) => Ok(self.eval_chain(f, e)?.unwrap_or(Value::Null)),
            ExprKind::StaticProp(cref, name) => {
                self.cur_line = e.line;
                let r = self.static_prop_ref(f, cref, name)?;
                let v = r.borrow().clone();
                Ok(v)
            }
            ExprKind::ClassConst(cref, name) => {
                self.cur_line = e.line;
                self.eval_class_const(f, cref, name)
            }
            ExprKind::Const(fname) => {
                self.cur_line = e.line;
                self.eval_const(fname)
            }
            ExprKind::Call(fname, args) => {
                self.cur_line = e.line;
                self.eval_call(f, fname, args, e.line)
            }
            ExprKind::CallExpr(callee, args) => {
                let cv = self.eval(f, callee)?;
                self.cur_line = e.line;
                self.call_value_with_args(f, &cv, args, e.line)
            }
            ExprKind::StaticCall(cref, name, args) => {
                self.cur_line = e.line;
                self.eval_static_call(f, cref, name, args, e.line)
            }
            ExprKind::CallableRef(inner) => {
                self.cur_line = e.line;
                self.eval_callable_ref(f, inner)
            }
            ExprKind::New(cref, args) => {
                self.cur_line = e.line;
                let cls = self.resolve_class_ref(f, cref, true)?;
                self.cur_line = e.line;
                self.new_object(f, &cls, args, e.line)
            }
            ExprKind::NewAnon(decl, args) => {
                self.cur_line = e.line;
                let cls = match self.classes.get(&lc(&decl.name)).cloned() {
                    Some(c) => c,
                    None => {
                        self.declare_class(decl)?;
                        self.classes.get(&lc(&decl.name)).cloned().unwrap()
                    }
                };
                self.new_object(f, &cls, args, e.line)
            }
            ExprKind::Clone(x) => {
                let v = self.eval(f, x)?;
                self.cur_line = e.line;
                match v {
                    Value::Object(o) => Ok(Value::Object(self.clone_object(&o)?)),
                    other => {
                        let msg = format!("clone(): Argument #1 ($object) must be of type object, {} given", other.type_name());
                        Err(self.type_error(&msg))
                    }
                }
            }
            ExprKind::CloneWith(x, props) => {
                let v = self.eval(f, x)?;
                let pv = self.eval(f, props)?;
                self.cur_line = e.line;
                match v {
                    Value::Object(o) => {
                        let c = self.clone_object(&o)?;
                        if let Value::Array(a) = pv {
                            let scope = f.class.clone();
                            for (k, v) in a.iter() {
                                let name = k.as_bytes();
                                self.write_prop_scoped(&c, &name, v.deref(), scope.as_ref(), true)?;
                            }
                        }
                        Ok(Value::Object(c))
                    }
                    other => {
                        let msg = format!("clone(): Argument #1 ($object) must be of type object, {} given", other.type_name());
                        Err(self.type_error(&msg))
                    }
                }
            }
            ExprKind::Unary(op, x) => {
                let v = self.eval(f, x)?;
                self.cur_line = e.line;
                match op {
                    UnOp::Not => Ok(Value::Bool(!v.to_bool())),
                    UnOp::Neg => self.negate(&v),
                    UnOp::Plus => self.unary_plus(&v),
                    UnOp::BitNot => self.bitnot(&v),
                }
            }
            ExprKind::Bin(op, a, b) => {
                match op {
                    BinOp::And => {
                        let x = self.eval(f, a)?;
                        if !x.to_bool() {
                            return Ok(Value::Bool(false));
                        }
                        let y = self.eval(f, b)?;
                        return Ok(Value::Bool(y.to_bool()));
                    }
                    BinOp::Or => {
                        let x = self.eval(f, a)?;
                        if x.to_bool() {
                            return Ok(Value::Bool(true));
                        }
                        let y = self.eval(f, b)?;
                        return Ok(Value::Bool(y.to_bool()));
                    }
                    _ => {}
                }
                let x = self.eval(f, a)?;
                let y = self.eval(f, b)?;
                self.cur_line = e.line;
                self.binop(*op, &x, &y)
            }
            ExprKind::Assign(t, v) => {
                if let ExprKind::Var(vr) = &t.kind {
                    let val = self.eval(f, v)?;
                    let i = f.idx(vr);
                    if i >= f.slots.len() {
                        f.sync();
                    }
                    match &mut f.slots[i] {
                        Value::Ref(r) => {
                            let old = std::mem::replace(&mut *r.borrow_mut(), val.clone());
                            drop(old);
                        }
                        slot => {
                            let old = std::mem::replace(slot, val.clone());
                            drop(old);
                        }
                    }
                    return Ok(val);
                }
                if let ExprKind::List(items, _) = &t.kind {
                    let val = self.eval(f, v)?;
                    self.cur_line = e.line;
                    self.assign_list(f, items, &val)?;
                    return Ok(val);
                }
                self.assign_expr(f, t, v, e.line)
            }
            ExprKind::AssignRef(t, s) => {
                self.cur_line = e.line;
                self.assign_ref_expr(f, t, s)
            }
            ExprKind::AssignOp(op, t, v) => {
                self.cur_line = e.line;
                self.assign_op_expr(f, *op, t, v, e.line)
            }
            ExprKind::CoalesceAssign(t, v) => {
                self.cur_line = e.line;
                if let Some(cur) = self.eval_quiet(f, t)? {
                    if !cur.is_null() {
                        return Ok(cur);
                    }
                }
                self.assign_expr(f, t, v, e.line)
            }
            ExprKind::IncDec(pre, inc, t) => {
                self.cur_line = e.line;
                self.incdec_expr(f, *pre, *inc, t)
            }
            ExprKind::Ternary(c, a, b) => {
                let cv = self.eval(f, c)?;
                match a {
                    Some(a) => {
                        if cv.to_bool() {
                            self.eval(f, a)
                        } else {
                            self.eval(f, b)
                        }
                    }
                    None => {
                        if cv.to_bool() {
                            Ok(cv)
                        } else {
                            self.eval(f, b)
                        }
                    }
                }
            }
            ExprKind::Coalesce(a, b) => {
                if let Some(v) = self.eval_quiet(f, a)? {
                    if !v.is_null() {
                        return Ok(v);
                    }
                }
                self.eval(f, b)
            }
            ExprKind::Isset(list) => {
                for x in list {
                    if !self.eval_isset(f, x)? {
                        return Ok(Value::Bool(false));
                    }
                }
                Ok(Value::Bool(true))
            }
            ExprKind::Empty(x) => {
                let v = self.eval_quiet_empty(f, x)?;
                Ok(Value::Bool(match v {
                    None => true,
                    Some(v) => !v.to_bool(),
                }))
            }
            ExprKind::InstanceOf(x, cref) => {
                let v = self.eval(f, x)?;
                self.cur_line = e.line;
                let o = match v {
                    Value::Object(o) => o,
                    _ => {
                        // still evaluate dynamic class expr
                        if let ClassRef::Dynamic(d) = cref {
                            self.eval(f, d)?;
                        }
                        return Ok(Value::Bool(false));
                    }
                };
                match cref {
                    ClassRef::Named(n) => Ok(Value::Bool(o.class.instance_of_name(&String::from_utf8_lossy(&lc(n))))),
                    ClassRef::Dynamic(d) => {
                        let dv = self.eval(f, d)?;
                        match dv {
                            Value::Object(c) => Ok(Value::Bool(o.class.instance_of_name(&c.class.lname))),
                            Value::Str(s) => {
                                let mut l = s.to_ascii_lowercase();
                                if l.first() == Some(&b'\\') {
                                    l.remove(0);
                                }
                                Ok(Value::Bool(o.class.instance_of_name(&String::from_utf8_lossy(&l))))
                            }
                            _ => Err(self.error("Class name must be a valid object or a string")),
                        }
                    }
                    _ => {
                        let c = self.resolve_class_ref(f, cref, false)?;
                        Ok(Value::Bool(o.class.instance_of_name(&c.lname)))
                    }
                }
            }
            ExprKind::Cast(k, x) => {
                let v = self.eval(f, x)?;
                self.cur_line = e.line;
                self.cast(*k, v)
            }
            ExprKind::Silence(x) => {
                self.silence += 1;
                let r = self.eval(f, x);
                self.silence -= 1;
                r
            }
            ExprKind::Closure(decl, uses, is_static) => {
                self.cur_line = e.line;
                self.make_closure(f, decl, uses, *is_static)
            }
            ExprKind::ArrowFn(decl, caps, is_static) => self.make_arrow_fn(f, decl, caps, *is_static),
            ExprKind::Match(subj, arms) => {
                let v = self.eval(f, subj)?;
                for arm in arms {
                    match &arm.conds {
                        None => {}
                        Some(conds) => {
                            for c in conds {
                                let cv = self.eval(f, c)?;
                                if strict_equals(&v, &cv) {
                                    return self.eval(f, &arm.body);
                                }
                            }
                        }
                    }
                }
                for arm in arms {
                    if arm.conds.is_none() {
                        return self.eval(f, &arm.body);
                    }
                }
                self.cur_line = e.line;
                let desc = match &v {
                    Value::Str(s) => {
                        let mut d = Vec::new();
                        crate::builtins::output::export_str(&mut d, s);
                        format!("Unhandled match case {}", String::from_utf8_lossy(&d))
                    }
                    Value::Int(i) => format!("Unhandled match case {}", i),
                    Value::Float(x) => format!("Unhandled match case {}", fmt_float_repr(*x)),
                    Value::Bool(b) => format!("Unhandled match case {}", if *b { "true" } else { "false" }),
                    Value::Null => "Unhandled match case NULL".to_string(),
                    _ => format!("Unhandled match case of type {}", type_name_for_match(&v)),
                };
                Err(self.throw_err("UnhandledMatchError", &desc))
            }
            ExprKind::Throw(x) => {
                let v = self.eval(f, x)?;
                self.cur_line = e.line;
                match v {
                    Value::Object(o) if o.class.instance_of_name("throwable") => Err(Flow::Throw(o)),
                    _ => Err(self.error("Can only throw objects")),
                }
            }
            ExprKind::Yield(k, v) => {
                let key = match k {
                    Some(k) => Some(self.eval(f, k)?),
                    None => None,
                };
                let val = match v {
                    Some(v) => {
                        if f.func.as_ref().map(|d| d.by_ref).unwrap_or(false) {
                            match self.make_ref(f, v) {
                                Ok(r) => Value::Ref(r),
                                Err(_) => self.eval(f, v)?,
                            }
                        } else {
                            self.eval(f, v)?
                        }
                    }
                    None => Value::Null,
                };
                self.cur_line = e.line;
                self.do_yield(key, val)
            }
            ExprKind::YieldFrom(x) => {
                let v = self.eval(f, x)?;
                self.cur_line = e.line;
                self.do_yield_from(v)
            }
            ExprKind::Print(x) => {
                let v = self.eval(f, x)?;
                let s = self.to_str(&v)?;
                self.echo(&s);
                Ok(Value::Int(1))
            }
            ExprKind::Exit(x) => {
                let code = match x {
                    Some(x) => {
                        let v = self.eval(f, x)?;
                        match v {
                            Value::Int(i) => i as i32,
                            Value::Str(s) => {
                                self.echo(&s);
                                0
                            }
                            Value::Bool(_) | Value::Float(_) | Value::Null => {
                                let s = self.to_str(&v)?;
                                self.echo(&s);
                                0
                            }
                            other => {
                                let msg = format!("exit(): Argument #1 ($status) must be of type string|int, {} given", other.type_name());
                                return Err(self.type_error(&msg));
                            }
                        }
                    }
                    None => 0,
                };
                Err(Flow::Exit(code))
            }
            ExprKind::Include(kind, x) => {
                let v = self.eval(f, x)?;
                self.cur_line = e.line;
                let p = self.to_str(&v)?;
                self.include_file(f, *kind, &String::from_utf8_lossy(&p))
            }
            ExprKind::Eval(x) => {
                let v = self.eval(f, x)?;
                self.cur_line = e.line;
                let code = self.to_str(&v)?;
                self.eval_code(f, &code)
            }
            ExprKind::Magic(m) => match m {
                MagicConst::Class => {
                    let c = f.class.clone();
                    Ok(match c {
                        Some(c) => Value::str(&c.name),
                        None => Value::str(""),
                    })
                }
                _ => Ok(Value::str("")),
            },
            ExprKind::ShellExec(parts) => {
                let mut cmd: Vec<u8> = Vec::new();
                for p in parts {
                    match p {
                        InterpPart::Lit(l) => cmd.extend_from_slice(l),
                        InterpPart::Expr(x) => {
                            let v = self.eval(f, x)?;
                            let s = self.to_str(&v)?;
                            cmd.extend_from_slice(&s);
                        }
                    }
                }
                self.flush();
                let out = std::process::Command::new("/bin/sh").arg("-c").arg(String::from_utf8_lossy(&cmd).as_ref()).output();
                match out {
                    Ok(o) => {
                        if o.stdout.is_empty() {
                            Ok(Value::Null)
                        } else {
                            Ok(Value::vec(o.stdout))
                        }
                    }
                    Err(_) => Ok(Value::Null),
                }
            }
            ExprKind::Pipe(lhs, rhs) => {
                let v = self.eval(f, lhs)?;
                let callee = self.eval(f, rhs)?;
                self.cur_line = e.line;
                self.call_value(&callee, vec![v])
            }
        }
    }

    pub fn binop(&mut self, op: BinOp, x: &Value, y: &Value) -> R<Value> {
        Ok(match op {
            BinOp::Eq => Value::Bool(self.loose_eq(x, y)?),
            BinOp::NotEq => Value::Bool(!self.loose_eq(x, y)?),
            BinOp::Identical => Value::Bool(strict_equals(x, y)),
            BinOp::NotIdentical => Value::Bool(!strict_equals(x, y)),
            BinOp::Lt => Value::Bool(self.is_smaller(x, y)?),
            BinOp::Gt => Value::Bool(self.is_smaller(y, x)?),
            BinOp::Le => Value::Bool(self.is_smaller_or_equal(x, y)?),
            BinOp::Ge => Value::Bool(self.is_smaller_or_equal(y, x)?),
            BinOp::Spaceship => Value::Int(self.compare(x, y)? as i64),
            BinOp::Xor => Value::Bool(x.to_bool() ^ y.to_bool()),
            BinOp::And => Value::Bool(x.to_bool() && y.to_bool()),
            BinOp::Or => Value::Bool(x.to_bool() || y.to_bool()),
            BinOp::Concat => {
                let mut s = match x {
                    Value::Str(s) => s.to_vec(),
                    _ => self.to_str(x)?.to_vec(),
                };
                match y {
                    Value::Str(t) => s.extend_from_slice(t),
                    _ => {
                        let t = self.to_str(y)?;
                        s.extend_from_slice(&t);
                    }
                }
                Value::vec(s)
            }
            _ => return self.arith(op, x, y),
        })
    }

    pub fn cast(&mut self, k: CastKind, v: Value) -> R<Value> {
        Ok(match k {
            CastKind::Int => Value::Int(self.to_int_cast(&v)?),
            CastKind::Float => Value::Float(self.to_float_cast(&v)?),
            CastKind::String => Value::Str(self.to_str(&v)?),
            CastKind::Bool => Value::Bool(v.to_bool()),
            CastKind::Array => match v {
                Value::Array(_) => v,
                Value::Null | Value::Undef => Value::empty_array(),
                Value::Object(o) => Value::Array(Rc::new(self.object_to_array(&o)?)),
                other => Value::Array(Rc::new(PArray::from_values(vec![other]))),
            },
            CastKind::Object => match v {
                Value::Object(_) => v,
                Value::Array(a) => {
                    let o = self.new_stdclass();
                    {
                        let mut d = o.dynamic.borrow_mut();
                        let mut pa = PArray::new();
                        for (k, val) in a.iter() {
                            let key = match k {
                                Key::Int(i) => Key::Str(Rc::new(i.to_string().into_bytes())),
                                k => k.clone(),
                            };
                            pa.set(key, val.deref());
                        }
                        *d = Some(pa);
                    }
                    Value::Object(o)
                }
                Value::Null | Value::Undef => Value::Object(self.new_stdclass()),
                other => {
                    let o = self.new_stdclass();
                    let mut pa = PArray::new();
                    pa.set(Key::Str(Rc::new(b"scalar".to_vec())), other);
                    *o.dynamic.borrow_mut() = Some(pa);
                    Value::Object(o)
                }
            },
            CastKind::Unset => Value::Null,
        })
    }

    pub fn eval_array_lit(&mut self, f: &mut Frame, items: &[ArrayItem]) -> R<Value> {
        let mut arr = PArray::with_capacity(items.len());
        for it in items {
            if it.unpack {
                let v = self.eval(f, &it.value)?;
                match v {
                    Value::Array(a) => {
                        for (k, v) in a.iter() {
                            match k {
                                Key::Int(_) => {
                                    if !arr.push(v.deref()) {
                                        return Err(self.error("Cannot add element to the array as the next element is already occupied"));
                                    }
                                }
                                Key::Str(_) => arr.set(k.clone(), v.deref()),
                            }
                        }
                    }
                    Value::Object(o) => {
                        let mut pairs = Vec::new();
                        self.iterate_object(&o, &mut |_, k, v| {
                            pairs.push((k, v));
                            Ok(true)
                        })?;
                        for (k, v) in pairs {
                            match k {
                                Value::Str(s) => arr.set(Key::Str(s), v),
                                _ => {
                                    arr.push(v);
                                }
                            }
                        }
                    }
                    other => {
                        let _ = other;
                        return Err(self.error("Only arrays and Traversables can be unpacked"));
                    }
                }
                continue;
            }
            if let ExprKind::Lit(Value::Undef) = it.value.kind {
                return Err(self.fatal("Cannot use empty array elements in arrays"));
            }
            let key = match &it.key {
                Some(k) => Some(self.eval(f, k)?),
                None => None,
            };
            let val = if it.by_ref {
                Value::Ref(self.make_ref(f, &it.value)?)
            } else {
                self.eval(f, &it.value)?
            };
            match key {
                Some(k) => {
                    let key = self.to_key(&k)?;
                    arr.set(key, val);
                }
                None => {
                    if !arr.push(val) {
                        return Err(self.error("Cannot add element to the array as the next element is already occupied"));
                    }
                }
            }
        }
        Ok(Value::arr(arr))
    }

    /// convert a value to an array key (with PHP diagnostics)
    pub fn to_key(&mut self, k: &Value) -> R<Key> {
        match k {
            Value::Int(i) => Ok(Key::Int(*i)),
            Value::Str(s) => Ok(Key::from_pstr(s)),
            Value::Bool(b) => Ok(Key::Int(*b as i64)),
            Value::Float(f) => {
                let i = float_to_int(*f);
                if !f.is_finite() || !float_fits_int(*f) || (i as f64) != *f {
                    let s = fmt_float_repr(*f);
                    if !f.is_finite() || !float_fits_int(*f) {
                        self.warn(&format!("The float {} is not representable as an int, cast occurred", s))?;
                    } else {
                        self.deprecated(&format!("Implicit conversion from float {} to int loses precision", s))?;
                    }
                }
                Ok(Key::Int(i))
            }
            Value::Null | Value::Undef => {
                self.deprecated("Using null as an array offset is deprecated, use an empty string instead")?;
                Ok(Key::Str(Rc::new(Vec::new())))
            }
            Value::Ref(r) => {
                let v = r.borrow().clone();
                self.to_key(&v)
            }
            other => {
                let msg = format!("Cannot access offset of type {} on array", ops::type_for_op(other));
                Err(self.type_error(&msg))
            }
        }
    }

    pub fn read_super(&mut self, f: &mut Frame, n: &Name) -> R<Value> {
        if &**n == "GLOBALS" {
            let g = self.global_frame();
            let mut arr = PArray::new();
            for (i, name) in g.names.clone().iter().enumerate() {
                if let Some(v) = g.slots.get(i) {
                    if !v.is_undef() {
                        if let Value::Ref(r) = v {
                            if r.borrow().is_undef() {
                                continue;
                            }
                        }
                        arr.set(Key::from_str_bytes(name.as_bytes()), v.deref());
                    }
                }
            }
            let _ = f;
            return Ok(Value::arr(arr));
        }
        let g = self.global_frame();
        match g.find_slot(n.as_bytes()) {
            Some(i) => Ok(g.slots[i].deref()),
            None => Ok(Value::empty_array()),
        }
    }

    /// evaluate an expression that can be part of a nullsafe chain. None = short-circuited
    pub fn eval_chain(&mut self, f: &mut Frame, e: &Expr) -> R<Option<Value>> {
        match &e.kind {
            ExprKind::Index(base, idx) => {
                let b = match self.eval_chain(f, base)? {
                    Some(b) => b,
                    None => return Ok(None),
                };
                let idx = match idx {
                    Some(i) => self.eval(f, i)?,
                    None => {
                        self.cur_line = e.line;
                        return Err(self.error("Cannot use [] for reading"));
                    }
                };
                self.cur_line = e.line;
                Ok(Some(self.read_index(&b, &idx, false)?))
            }
            ExprKind::Prop(base, name, nullsafe) => {
                let b = match self.eval_chain(f, base)? {
                    Some(b) => b,
                    None => return Ok(None),
                };
                if *nullsafe && b.is_null() {
                    return Ok(None);
                }
                let n = self.member_name(f, name)?;
                self.cur_line = e.line;
                match b {
                    Value::Object(o) => {
                        let scope = f.class.clone();
                        Ok(Some(self.read_prop(&o, &n, scope.as_ref(), false)?))
                    }
                    other => {
                        self.warn(&format!("Attempt to read property \"{}\" on {}", String::from_utf8_lossy(&n), other.type_name()))?;
                        Ok(Some(Value::Null))
                    }
                }
            }
            ExprKind::MethodCall(base, name, args, nullsafe) => {
                let b = match self.eval_chain(f, base)? {
                    Some(b) => b,
                    None => return Ok(None),
                };
                if *nullsafe && b.is_null() {
                    return Ok(None);
                }
                self.cur_line = e.line;
                Ok(Some(self.eval_method_call(f, b, name, args, e.line)?))
            }
            _ => Ok(Some(self.eval(f, e)?)),
        }
    }

    pub fn member_name(&mut self, f: &mut Frame, m: &MemberName) -> R<PStr> {
        match m {
            MemberName::Ident(n) => Ok(Rc::new(n.as_bytes().to_vec())),
            MemberName::Dynamic(e) => {
                let v = self.eval(f, e)?;
                self.to_str(&v)
            }
        }
    }

    /// read $base[$idx]
    pub fn read_index(&mut self, b: &Value, idx: &Value, quiet: bool) -> R<Value> {
        match b {
            Value::Array(a) => {
                let k = match idx {
                    Value::Int(i) => Key::Int(*i),
                    Value::Str(s) => Key::from_pstr(s),
                    _ => self.to_key(idx)?,
                };
                match a.get(&k) {
                    Some(v) => Ok(v.deref()),
                    None => {
                        if !quiet {
                            match &k {
                                Key::Int(i) => self.warn(&format!("Undefined array key {}", i))?,
                                Key::Str(s) => self.warn(&format!("Undefined array key \"{}\"", String::from_utf8_lossy(s)))?,
                            }
                        }
                        Ok(Value::Null)
                    }
                }
            }
            Value::Str(s) => {
                let i = match idx {
                    Value::Int(i) => *i,
                    Value::Str(is) => match str_numeric(is) {
                        Some(Num::Int(i)) => i,
                        _ => {
                            if quiet {
                                return Ok(Value::Null);
                            }
                            let msg = if parse_numeric_prefix(is).is_some() && !quiet {
                                "Cannot access offset of type string on string".to_string()
                            } else {
                                "Cannot access offset of type string on string".to_string()
                            };
                            return Err(self.type_error(&msg));
                        }
                    },
                    Value::Float(fl) => {
                        if !quiet {
                            self.warn("String offset cast occurred")?;
                        }
                        float_to_int(*fl)
                    }
                    Value::Bool(bv) => {
                        if !quiet {
                            self.warn("String offset cast occurred")?;
                        }
                        *bv as i64
                    }
                    Value::Null => {
                        if !quiet {
                            self.warn("String offset cast occurred")?;
                        }
                        0
                    }
                    other => {
                        let msg = format!("Cannot access offset of type {} on string", ops::type_for_op(other));
                        return Err(self.type_error(&msg));
                    }
                };
                let len = s.len() as i64;
                let p = if i < 0 { len + i } else { i };
                if p < 0 || p >= len {
                    if !quiet {
                        self.warn(&format!("Uninitialized string offset {}", i))?;
                    }
                    return Ok(if quiet { Value::Null } else { Value::str("") });
                }
                Ok(Value::bytes(&s[p as usize..p as usize + 1]))
            }
            Value::Object(o) => {
                let o = o.clone();
                self.array_access_get(&o, idx)
            }
            Value::Ref(r) => {
                let v = r.borrow().clone();
                self.read_index(&v, idx, quiet)
            }
            Value::Null | Value::Undef => {
                if !quiet {
                    self.warn("Trying to access array offset on null")?;
                }
                Ok(Value::Null)
            }
            other => {
                if !quiet {
                    self.warn(&format!("Trying to access array offset on {}", other.type_name()))?;
                }
                Ok(Value::Null)
            }
        }
    }

    pub fn array_access_get(&mut self, o: &Obj, idx: &Value) -> R<Value> {
        if let Some(m) = o.class.find_method("offsetget").cloned() {
            if o.class.instance_of_name("arrayaccess") {
                return self.call_method_obj(o, &m, vec![idx.clone()]);
            }
        }
        let msg = format!("Cannot use object of type {} as array", o.class.name);
        Err(self.error(&msg))
    }

    /// quiet evaluation for isset/??: None if not set
    pub fn eval_quiet(&mut self, f: &mut Frame, e: &Expr) -> R<Option<Value>> {
        match &e.kind {
            ExprKind::Var(v) => {
                let i = f.idx(v);
                match f.slots.get(i) {
                    Some(Value::Undef) | None => Ok(None),
                    Some(Value::Ref(r)) => {
                        let b = r.borrow();
                        if b.is_undef() {
                            Ok(None)
                        } else {
                            Ok(Some(b.clone()))
                        }
                    }
                    Some(v) => Ok(Some(v.clone())),
                }
            }
            ExprKind::VarVar(ne) => {
                let nv = self.eval(f, ne)?;
                let name = self.to_str(&nv)?;
                match f.find_slot(&name) {
                    Some(i) if !f.slots[i].is_undef() => Ok(Some(f.slots[i].deref())),
                    _ => Ok(None),
                }
            }
            ExprKind::This => Ok(f.this.clone().map(Value::Object)),
            ExprKind::Index(base, idx) => {
                let b = match self.eval_quiet(f, base)? {
                    Some(b) => b,
                    None => return Ok(None),
                };
                let idx = match idx {
                    Some(i) => self.eval(f, i)?,
                    None => return Err(self.error("Cannot use [] for reading")),
                };
                self.cur_line = e.line;
                match &b {
                    Value::Object(o) => {
                        let o = o.clone();
                        if !o.class.instance_of_name("arrayaccess") {
                            let msg = format!("Cannot use object of type {} as array", o.class.name);
                            return Err(self.error(&msg));
                        }
                        let m = o.class.find_method("offsetexists").cloned();
