                            Value::Int(i) => *i,
                            Value::Str(is) => match str_numeric(is) {
                                Some(Num::Int(i)) => i,
                                _ => return Ok(None),
                            },
                            Value::Float(fl) => *fl as i64,
                            Value::Bool(b) => *b as i64,
                            _ => return Ok(None),
                        };
                        let len = s.len() as i64;
                        let p = if i < 0 { len + i } else { i };
                        if p < 0 || p >= len {
                            return Ok(None);
                        }
                        Ok(Some(Value::bytes(&s[p as usize..p as usize + 1])))
                    }
                    _ => Ok(None),
                }
            }
            ExprKind::Prop(base, name, _) => {
                let b = match self.eval_quiet(f, base)? {
                    Some(b) => b,
                    None => return Ok(None),
                };
