                }
            }
            ExprKind::ClassConst(..) | ExprKind::Const(..) => Ok(Some(self.eval(f, e)?)),
            ExprKind::MethodCall(_, _, _, _) => Ok(self.eval_chain(f, e)?),
            _ => Ok(Some(self.eval(f, e)?)),
        }
    }

    fn eval_quiet_empty(&mut self, f: &mut Frame, e: &Expr) -> R<Option<Value>> {
        self.eval_quiet(f, e)
    }

    pub fn eval_isset(&mut self, f: &mut Frame, e: &Expr) -> R<bool> {
        match &e.kind {
            ExprKind::Index(base, idx) => {
                // isset on ArrayAccess only calls offsetExists
                let b = match self.eval_quiet(f, base)? {
                    Some(b) => b,
                    None => return Ok(false),
                };
                if let Value::Object(o) = &b {
                    let idxv = match idx {
                        Some(i) => self.eval(f, i)?,
                        None => return Err(self.error("Cannot use [] for reading")),
                    };
                    if !o.class.instance_of_name("arrayaccess") {
                        let msg = format!("Cannot use object of type {} as array", o.class.name);
                        return Err(self.error(&msg));
                    }
                    let o = o.clone();
                    if let Some(m) = o.class.find_method("offsetexists").cloned() {
                        let r = self.call_method_obj(&o, &m, vec![idxv])?;
                        return Ok(r.to_bool());
                    }
                    return Ok(false);
                }
                let _ = b;
                Ok(match self.eval_quiet(f, e)? {
                    Some(v) => !v.is_null(),
                    None => false,
                })
            }
            ExprKind::Prop(base, name, _) => {
                let b = match self.eval_quiet(f, base)? {
                    Some(b) => b,
                    None => return Ok(false),
                };
                let n = self.member_name(f, name)?;
                match b {
                    Value::Object(o) => {
                        let scope = f.class.clone();
                        self.prop_isset_value(&o, &n, scope.as_ref())
                    }
                    _ => Ok(false),
                }
            }
            _ => Ok(match self.eval_quiet(f, e)? {
                Some(v) => !v.is_null(),
                None => false,
            }),
        }
    }

    pub fn eval_const(&mut self, fname: &FuncName) -> R<Value> {
        if let Some(v) = self.get_constant(fname.name.as_bytes()) {
            return Ok(v);
        }
        if let Some(fb) = &fname.fallback {
            if let Some(v) = self.get_constant(fb.as_bytes()) {
                return Ok(v);
            }
            // case-insensitive true/false/null in namespace
        }
        let n = fname.fallback.as_ref().unwrap_or(&fname.name).clone();
        let ln = n.to_ascii_lowercase();
        match ln.as_str() {
            "true" => return Ok(Value::Bool(true)),
            "false" => return Ok(Value::Bool(false)),
            "null" => return Ok(Value::Null),
            _ => {}
        }
        let msg = format!("Undefined constant \"{}\"", fname.name);
        Err(self.error(&msg))
    }

    pub fn new_stdclass(&mut self) -> Obj {
        let cls = self.classes.get(&b"stdclass"[..]).cloned().unwrap();
        Object::new(cls, Vec::new())
    }
}

fn type_name_for_match(v: &Value) -> String {
    match v {
        Value::Object(o) => o.class.name.to_string(),
        _ => v.type_name().to_string(),
    }
}
