impl Interp {
    /// phase 1: collect base and steps (evaluating keys in order)
    pub fn lv_collect(&mut self, f: &mut Frame, e: &Expr, steps: &mut Vec<Step>) -> R<LvBase> {
        match &e.kind {
            ExprKind::Var(v) => {
                let i = f.idx(v);
                if i >= f.slots.len() {
                    f.sync();
                }
                Ok(LvBase::Slot(i))
            }
            ExprKind::VarVar(ne) => {
                let nv = self.eval(f, ne)?;
                let name = self.to_str(&nv)?;
                if name.as_slice() == b"this" {
                    if let Some(o) = &f.this {
                        return Ok(LvBase::Val(Value::Object(o.clone())));
                    }
                }
                Ok(LvBase::Slot(f.slot_for(&name)))
            }
            ExprKind::Super(n) => {
                if &**n == "GLOBALS" {
                    return Ok(LvBase::Val(self.read_super(f, n)?));
                }
                let g = self.global_frame();
                Ok(LvBase::GlobalSlot(g.slot_for(n.as_bytes())))
            }
            ExprKind::This => match &f.this {
                Some(o) => Ok(LvBase::Val(Value::Object(o.clone()))),
                None => Err(self.error("Using $this when not in object context")),
            },
            ExprKind::StaticProp(cref, name) => {
                let r = self.static_prop_ref(f, cref, name)?;
                Ok(LvBase::Ref(r))
            }
            ExprKind::Index(b, k) => {
                // $GLOBALS['name']
                if let ExprKind::Super(n) = &b.kind {
                    if &**n == "GLOBALS" {
                        if let Some(k) = k {
                            let kv = self.eval(f, k)?;
                            let name = self.to_str(&kv)?;
                            if f.is_global {
                                return Ok(LvBase::Slot(f.slot_for(&name)));
                            }
                            let g = self.global_frame();
                            return Ok(LvBase::GlobalSlot(g.slot_for(&name)));
                        }
                    }
                }
                let base = self.lv_collect(f, b, steps)?;
                let kv = match k {
                    Some(k) => Some(self.eval(f, k)?),
                    None => None,
                };
                steps.push(Step::Dim(kv));
                Ok(base)
            }
            ExprKind::Prop(b, name, ns) => {
                if *ns {
                    return Err(self.fatal("Can't use nullsafe operator in write context"));
                }
                let base = self.lv_collect(f, b, steps)?;
                let n = self.member_name(f, name)?;
                steps.push(Step::Prop(n));
                Ok(base)
            }
            _ => {
                let v = self.eval(f, e)?;
                Ok(LvBase::Val(v))
            }
        }
    }

    /// raw pointer to base storage (not dereferenced)
    fn base_raw(&mut self, f: &mut Frame, base: &LvBase, temps: &mut Vec<Box<Value>>) -> *mut Value {
        match base {
            LvBase::Slot(i) => {
                if *i >= f.slots.len() {
                    f.sync();
                    while f.slots.len() <= *i {
                        f.slots.push(Value::Undef);
                    }
                }
                &mut f.slots[*i] as *mut Value
            }
            LvBase::GlobalSlot(i) => {
                let g = self.global_frame();
                while g.slots.len() <= *i {
                    g.slots.push(Value::Undef);
                }
                &mut g.slots[*i] as *mut Value
            }
            LvBase::Ref(r) => r.as_ptr(),
            LvBase::Val(v) => {
                temps.push(Box::new(v.clone()));
                &mut **temps.last_mut().unwrap() as *mut Value
            }
        }
    }

    #[inline]
    fn deref_ptr(p: *mut Value) -> *mut Value {
        unsafe {
            if let Value::Ref(r) = &*p {
                r.as_ptr()
            } else {
                p
            }
        }
    }

    /// walk one intermediate step in write mode; returns deref'd pointer
    fn lv_step(&mut self, p: *mut Value, step: &Step, scope: Option<&Rc<Class>>, temps: &mut Vec<Box<Value>>, rw: bool) -> R<*mut Value> {
        let cur = unsafe { &mut *p };
        match step {
            Step::Dim(k) => {
                match cur {
                    Value::Undef | Value::Null => *cur = Value::empty_array(),
                    Value::Bool(false) => {
                        self.deprecated("Automatic conversion of false to array is deprecated")?;
                        let cur = unsafe { &mut *p };
                        *cur = Value::empty_array();
                    }
                    _ => {}
                }
                let cur = unsafe { &mut *p };
                match cur {
                    Value::Array(a) => {
                        let key = match k {
                            Some(k) => Some(match k {
                                Value::Int(i) => Key::Int(*i),
                                Value::Str(s) => Key::from_pstr(s),
                                _ => self.to_key(k)?,
                            }),
                            None => None,
                        };
                        let cur = unsafe { &mut *p };
                        let a = match cur {
                            Value::Array(a) => a,
                            _ => unreachable!(),
                        };
                        let arr = Rc::make_mut(a);
                        let slot: *mut Value = match key {
                            None => match arr.push_mut() {
                                Some(s) => s as *mut Value,
                                None => return Err(self.error("Cannot add element to the array as the next element is already occupied")),
                            },
                            Some(key) => {
                                let (s, inserted) = arr.entry_mut_ins(key.clone());
                                let sp = s as *mut Value;
                                if inserted && rw {
                                    match &key {
                                        Key::Int(i) => self.warn(&format!("Undefined array key {}", i))?,
                                        Key::Str(s) => self.warn(&format!("Undefined array key \"{}\"", String::from_utf8_lossy(s)))?,
                                    }
                                }
                                sp
                            }
                        };
                        Ok(Self::deref_ptr(slot))
                    }
                    Value::Object(o) => {
                        let o = o.clone();
                        let kv = k.clone().unwrap_or(Value::Null);
                        let v = self.array_access_get(&o, &kv)?;
                        temps.push(Box::new(v));
                        Ok(&mut **temps.last_mut().unwrap() as *mut Value)
                    }
                    Value::Str(_) => {
                        if k.is_none() {
                            return Err(self.error("[] operator not supported for strings"));
                        }
                        Err(self.error("Cannot use string offset as an array"))
                    }
                    _ => Err(self.error("Cannot use a scalar value as an array")),
                }
            }
            Step::Prop(name) => match cur {
                Value::Object(o) => {
                    let o = o.clone();
                    self.prop_ptr_for_write(&o, name, scope, temps)
                }
                Value::Undef | Value::Null => {
                    let msg = format!("Attempt to modify property \"{}\" on null", String::from_utf8_lossy(name));
                    Err(self.error(&msg))
                }
                other => {
                    let msg = format!("Attempt to modify property \"{}\" on {}", String::from_utf8_lossy(name), other.type_name());
                    Err(self.error(&msg))
                }
            },
        }
    }

    /// walk base + all steps except the last; returns (container ptr deref'd)
    fn lv_walk(&mut self, f: &mut Frame, base: &LvBase, steps: &[Step], temps: &mut Vec<Box<Value>>, rw: bool) -> R<*mut Value> {
        let raw = self.base_raw(f, base, temps);
        let mut p = Self::deref_ptr(raw);
        let scope = f.class.clone();
        for s in steps {
            p = self.lv_step(p, s, scope.as_ref(), temps, rw)?;
        }
        Ok(p)
    }

    /// assign precomputed value into container via last step
    fn lv_assign_final(&mut self, p: *mut Value, step: &Step, val: Value, scope: Option<&Rc<Class>>) -> R<Value> {
        let cur = unsafe { &mut *p };
        match step {
            Step::Dim(k) => {
                match cur {
                    Value::Undef | Value::Null => *cur = Value::empty_array(),
                    Value::Bool(false) => {
                        self.deprecated("Automatic conversion of false to array is deprecated")?;
                        let cur = unsafe { &mut *p };
                        *cur = Value::empty_array();
                    }
                    _ => {}
                }
                let cur = unsafe { &mut *p };
                match cur {
                    Value::Array(_) => {
                        let key = match k {
                            Some(k) => Some(match k {
                                Value::Int(i) => Key::Int(*i),
                                Value::Str(s) => Key::from_pstr(s),
                                _ => self.to_key(k)?,
                            }),
                            None => None,
                        };
                        let cur = unsafe { &mut *p };
                        let a = match cur {
                            Value::Array(a) => a,
                            _ => unreachable!(),
                        };
                        let arr = Rc::make_mut(a);
                        match key {
                            None => {
                                if !arr.push(val.clone()) {
                                    return Err(self.error("Cannot add element to the array as the next element is already occupied"));
                                }
                            }
                            Some(key) => {
                                let slot = arr.entry_mut(key);
                                if let Value::Ref(r) = slot {
                                    let old = std::mem::replace(&mut *r.borrow_mut(), val.clone());
                                    drop(old);
                                } else {
                                    let old = std::mem::replace(slot, val.clone());
                                    drop(old);
                                }
                            }
                        }
                        Ok(val)
                    }
                    Value::Object(o) => {
                        let o = o.clone();
                        let kv = k.clone().unwrap_or(Value::Null);
                        self.array_access_set(&o, kv, val.clone())?;
                        Ok(val)
                    }
                    Value::Str(_) => {
                        let k = match k {
                            Some(k) => k.clone(),
                            None => return Err(self.error("[] operator not supported for strings")),
                        };
                        self.string_offset_assign(p, &k, &val)
                    }
                    _ => Err(self.error("Cannot use a scalar value as an array")),
                }
            }
            Step::Prop(name) => match cur {
                Value::Object(o) => {
                    let o = o.clone();
                    self.write_prop_scoped(&o, name, val.clone(), scope, false)?;
                    Ok(val)
                }
                Value::Undef | Value::Null => {
                    let msg = format!("Attempt to assign property \"{}\" on null", String::from_utf8_lossy(name));
                    Err(self.error(&msg))
                }
                other => {
                    let msg = format!("Attempt to assign property \"{}\" on {}", String::from_utf8_lossy(name), other.type_name());
                    Err(self.error(&msg))
                }
            },
        }
    }

    fn string_offset_assign(&mut self, p: *mut Value, k: &Value, val: &Value) -> R<Value> {
        let off = match k {
            Value::Int(i) => *i,
            Value::Str(s) => match str_numeric(s) {
                Some(Num::Int(i)) => i,
                _ => {
                    let msg = "Cannot access offset of type string on string".to_string();
                    return Err(self.type_error(&msg));
                }
            },
            Value::Float(f) => {
                self.warn("String offset cast occurred")?;
                *f as i64
            }
            Value::Bool(b) => {
                self.warn("String offset cast occurred")?;
                *b as i64
            }
            Value::Null => {
                self.warn("String offset cast occurred")?;
                0
            }
            other => {
                let msg = format!("Cannot access offset of type {} on string", ops::type_for_op(other));
                return Err(self.type_error(&msg));
            }
        };
        let vs = self.to_str(val)?;
        if vs.is_empty() {
            return Err(self.error("Cannot assign an empty string to a string offset"));
        }
        if vs.len() > 1 {
            self.warn("Only the first byte will be assigned to the string offset")?;
        }
        let cur = unsafe { &mut *p };
        if let Value::Str(s) = cur {
            let len = s.len() as i64;
            let pos = if off < 0 { len + off } else { off };
            if pos < 0 {
                self.warn(&format!("Illegal string offset {}", off))?;
                return Ok(Value::Null);
            }
            let cur = unsafe { &mut *p };
            if let Value::Str(s) = cur {
                let m = Rc::make_mut(s);
                let pos = pos as usize;
                while m.len() <= pos {
                    m.push(b' ');
                }
                m[pos] = vs[0];
            }
        }
        Ok(Value::bytes(&vs[..1]))
    }

    pub fn array_access_set(&mut self, o: &Obj, k: Value, v: Value) -> R<()> {
        if o.class.instance_of_name("arrayaccess") {
            if let Some(m) = o.class.find_method("offsetset").cloned() {
                self.call_method_obj(o, &m, vec![k, v])?;
                return Ok(());
            }
        }
        let msg = format!("Cannot use object of type {} as array", o.class.name);
        Err(self.error(&msg))
    }

    /// assign value to an arbitrary target expression
    pub fn assign_value(&mut self, f: &mut Frame, target: &Expr, val: Value) -> R<Value> {
        match &target.kind {
            ExprKind::Var(v) => {
                let i = f.idx(v);
                if i >= f.slots.len() {
                    f.sync();
                }
                match &mut f.slots[i] {
                    Value::Ref(r) => {
                        let old = std::mem::replace(&mut *r.borrow_mut(), val.clone());
                        drop(old);
                    }
                    slot => {
                        let old = std::mem::replace(slot, val.clone());
                        drop(old);
                    }
                }
                Ok(val)
            }
            ExprKind::List(items, _) => {
                self.assign_list(f, items, &val)?;
                Ok(val)
            }
            ExprKind::Array(items) => {
                // convert on the fly
                let _ = items;
                Err(self.fatal("Cannot assign to array literal"))
            }
            _ => {
                let mut steps = Vec::new();
                let base = self.lv_collect(f, target, &mut steps)?;
                self.lv_assign_steps(f, &base, &steps, val)
            }
        }
    }

    fn lv_assign_steps(&mut self, f: &mut Frame, base: &LvBase, steps: &[Step], val: Value) -> R<Value> {
        let mut temps: Vec<Box<Value>> = Vec::new();
        if steps.is_empty() {
            if let LvBase::Val(_) = base {
                return Err(self.fatal("Can't use temporary expression in write context"));
            }
            let raw = self.base_raw(f, base, &mut temps);
            let p = Self::deref_ptr(raw);
            let old = unsafe { std::mem::replace(&mut *p, val.clone()) };
            drop(old);
            return Ok(val);
        }
        let (last, init) = steps.split_last().unwrap();
        let p = self.lv_walk(f, base, init, &mut temps, false)?;
        let scope = f.class.clone();
        let r = self.lv_assign_final(p, last, val, scope.as_ref());
        drop(temps);
        r
    }

    pub fn assign_expr(&mut self, f: &mut Frame, target: &Expr, rhs: &Expr, line: u32) -> R<Value> {
        match &target.kind {
            ExprKind::Var(_) => {
                let v = self.eval(f, rhs)?;
                self.assign_value(f, target, v)
            }
            ExprKind::List(items, _) => {
                let v = self.eval(f, rhs)?;
                self.cur_line = line;
                self.assign_list(f, items, &v)?;
                Ok(v)
            }
            _ => {
                let mut steps = Vec::new();
                let base = self.lv_collect(f, target, &mut steps)?;
                let v = self.eval(f, rhs)?;
                self.cur_line = line;
                self.lv_assign_steps(f, &base, &steps, v)
            }
        }
    }

    pub fn assign_list(&mut self, f: &mut Frame, items: &[Option<ListItem>], val: &Value) -> R<()> {
        let mut idx: i64 = 0;
        for item in items {
            let item = match item {
                Some(i) => i,
                None => {
                    idx += 1;
                    continue;
                }
            };
            let key = match &item.key {
                Some(k) => self.eval(f, k)?,
                None => {
                    let k = Value::Int(idx);
                    idx += 1;
                    k
                }
            };
            let elem = match val {
                Value::Array(a) => {
                    let k = self.to_key(&key)?;
                    match a.get(&k) {
                        Some(v) => v.deref(),
                        None => {
                            match &k {
                                Key::Int(i) => self.warn(&format!("Undefined array key {}", i))?,
                                Key::Str(s) => self.warn(&format!("Undefined array key \"{}\"", String::from_utf8_lossy(s)))?,
                            }
                            Value::Null
                        }
                    }
                }
                Value::Object(o) => {
                    let o = o.clone();
                    self.array_access_get(&o, &key)?
                }
                _ => Value::Null,
            };
            match &item.target.kind {
                ExprKind::List(sub, _) => self.assign_list(f, sub, &elem)?,
                _ => {
                    self.assign_value(f, &item.target, elem)?;
                }
            }
        }
        Ok(())
    }

    /// get (or create) a reference to the storage designated by e
    pub fn make_ref(&mut self, f: &mut Frame, e: &Expr) -> R<PRef> {
        match &e.kind {
            ExprKind::Var(v) => {
                let i = f.idx(v);
                if i >= f.slots.len() {
                    f.sync();
                }
                let slot = &mut f.slots[i];
                return Ok(wrap_ref(slot));
            }
            ExprKind::Call(..) | ExprKind::MethodCall(..) | ExprKind::StaticCall(..) | ExprKind::CallExpr(..) | ExprKind::New(..) | ExprKind::Lit(_) | ExprKind::Bin(..) | ExprKind::Array(..) | ExprKind::Interp(..) | ExprKind::Ternary(..) | ExprKind::Closure(..) | ExprKind::ArrowFn(..) | ExprKind::Const(..) | ExprKind::ClassConst(..) | ExprKind::Cast(..) | ExprKind::Unary(..) | ExprKind::Assign(..) | ExprKind::Match(..) | ExprKind::Coalesce(..) => {
                let v = self.eval(f, e)?;
                return Ok(Rc::new(RefCell::new(v)));
            }
            _ => {}
        }
        let mut steps = Vec::new();
        let base = self.lv_collect(f, e, &mut steps)?;
        let mut temps: Vec<Box<Value>> = Vec::new();
        if steps.is_empty() {
            let raw = self.base_raw(f, &base, &mut temps);
            if let LvBase::Ref(r) = &base {
                return Ok(r.clone());
            }
            let r = unsafe { wrap_ref(&mut *raw) };
            return Ok(r);
        }
        let (last, init) = steps.split_last().unwrap();
        let p = self.lv_walk(f, &base, init, &mut temps, false)?;
        let scope = f.class.clone();
        let raw = self.lv_raw_final(p, last, scope.as_ref(), &mut temps)?;
        let r = unsafe { wrap_ref(&mut *raw) };
        Ok(r)
    }

    /// pointer to final storage (not dereferenced) creating as needed
    fn lv_raw_final(&mut self, p: *mut Value, step: &Step, scope: Option<&Rc<Class>>, temps: &mut Vec<Box<Value>>) -> R<*mut Value> {
        let cur = unsafe { &mut *p };
        match step {
            Step::Dim(k) => {
                if matches!(cur, Value::Undef | Value::Null) {
                    *cur = Value::empty_array();
                }
                let cur = unsafe { &mut *p };
                match cur {
                    Value::Array(a) => {
                        let key = match k {
                            Some(k) => Some(self.to_key(k)?),
                            None => None,
                        };
                        let cur = unsafe { &mut *p };
                        let a = match cur {
                            Value::Array(a) => a,
                            _ => unreachable!(),
                        };
                        let _ = &a;
                        let arr = Rc::make_mut(a);
                        Ok(match key {
                            None => match arr.push_mut() {
                                Some(s) => s as *mut Value,
                                None => return Err(self.error("Cannot add element to the array as the next element is already occupied")),
                            },
                            Some(key) => arr.entry_mut(key) as *mut Value,
                        })
                    }
                    Value::Object(o) => {
                        let o = o.clone();
                        let kv = k.clone().unwrap_or(Value::Null);
                        let v = self.array_access_get(&o, &kv)?;
                        let msg = format!("Indirect modification of overloaded element of {} has no effect", o.class.name);
                        if !matches!(v, Value::Object(_)) {
                            self.notice(&msg)?;
                        }
                        temps.push(Box::new(v));
                        Ok(&mut **temps.last_mut().unwrap() as *mut Value)
                    }
                    Value::Str(_) => Err(self.error("Cannot create references to/from string offsets")),
                    _ => Err(self.error("Cannot use a scalar value as an array")),
                }
            }
            Step::Prop(name) => match cur {
                Value::Object(o) => {
                    let o = o.clone();
                    self.prop_raw_ptr(&o, name, scope, temps)
                }
                Value::Undef | Value::Null => {
                    let msg = format!("Attempt to modify property \"{}\" on null", String::from_utf8_lossy(name));
                    Err(self.error(&msg))
                }
                other => {
                    let msg = format!("Attempt to modify property \"{}\" on {}", String::from_utf8_lossy(name), other.type_name());
                    Err(self.error(&msg))
                }
            },
        }
    }

    pub fn assign_ref_expr(&mut self, f: &mut Frame, target: &Expr, src: &Expr) -> R<Value> {
        let r = match &src.kind {
            ExprKind::Call(..) | ExprKind::MethodCall(..) | ExprKind::StaticCall(..) | ExprKind::CallExpr(..) => {
                let v = self.eval(f, src)?;
                if let Value::Ref(r) = v {
                    r
                } else {
                    Rc::new(RefCell::new(v))
                }
            }
            _ => self.make_ref(f, src)?,
        };
        self.bind_ref(f, target, r.clone())?;
        let v = r.borrow().clone();
        Ok(v)
    }

    /// bind target storage to an existing reference
    pub fn bind_ref(&mut self, f: &mut Frame, target: &Expr, r: PRef) -> R<()> {
        if let ExprKind::Var(v) = &target.kind {
            let i = f.idx(v);
            if i >= f.slots.len() {
                f.sync();
            }
            let old = std::mem::replace(&mut f.slots[i], Value::Ref(r));
            drop(old);
            return Ok(());
        }
        let mut steps = Vec::new();
        let base = self.lv_collect(f, target, &mut steps)?;
        let mut temps: Vec<Box<Value>> = Vec::new();
        if steps.is_empty() {
            let raw = self.base_raw(f, &base, &mut temps);
            let old = unsafe { std::mem::replace(&mut *raw, Value::Ref(r)) };
            drop(old);
            return Ok(());
        }
        let (last, init) = steps.split_last().unwrap();
        let p = self.lv_walk(f, &base, init, &mut temps, false)?;
        let scope = f.class.clone();
        let raw = self.lv_raw_final(p, last, scope.as_ref(), &mut temps)?;
        let old = unsafe { std::mem::replace(&mut *raw, Value::Ref(r)) };
        drop(old);
        Ok(())
    }

    pub fn assign_op_expr(&mut self, f: &mut Frame, op: BinOp, target: &Expr, rhs: &Expr, line: u32) -> R<Value> {
        // fast path: simple variable
        if let ExprKind::Var(v) = &target.kind {
            let rv = self.eval(f, rhs)?;
            self.cur_line = line;
            let i = f.idx(v);
            if i >= f.slots.len() {
                f.sync();
            }
            let p = Self::deref_ptr(&mut f.slots[i] as *mut Value);
            let cur = unsafe { &mut *p };
            if cur.is_undef() {
                self.warn(&format!("Undefined variable ${}", v.name))?;
                let cur = unsafe { &mut *p };
                *cur = Value::Null;
            }
            return self.apply_op_at(p, op, rv, || None);
        }
        let mut steps = Vec::new();
        let base = self.lv_collect(f, target, &mut steps)?;
        let rv = self.eval(f, rhs)?;
        self.cur_line = line;
        let mut temps: Vec<Box<Value>> = Vec::new();
        if steps.is_empty() {
            let raw = self.base_raw(f, &base, &mut temps);
            let p = Self::deref_ptr(raw);
            return self.apply_op_at(p, op, rv, || None);
        }
        let (last, init) = steps.split_last().unwrap();
        let p = self.lv_walk(f, &base, init, &mut temps, true)?;
        let scope = f.class.clone();
        let cur = unsafe { &mut *p };
        match last {
            Step::Dim(k) => {
                if matches!(cur, Value::Undef | Value::Null) {
                    *cur = Value::empty_array();
                }
                let cur = unsafe { &mut *p };
                match cur {
                    Value::Array(_) => {
                        let key = match k {
                            Some(k) => Some(self.to_key(k)?),
                            None => None,
                        };
                        let cur = unsafe { &mut *p };
                        let a = match cur {
                            Value::Array(a) => a,
                            _ => unreachable!(),
                        };
                        let arr = Rc::make_mut(a);
                        let (slot, inserted) = match key.clone() {
                            None => match arr.push_mut() {
                                Some(s) => (s as *mut Value, false),
                                None => return Err(self.error("Cannot add element to the array as the next element is already occupied")),
                            },
                            Some(key) => {
                                let (s, ins) = arr.entry_mut_ins(key);
                                (s as *mut Value, ins)
                            }
                        };
                        if inserted {
                            match key.as_ref().unwrap() {
                                Key::Int(i) => self.warn(&format!("Undefined array key {}", i))?,
                                Key::Str(s) => self.warn(&format!("Undefined array key \"{}\"", String::from_utf8_lossy(s)))?,
                            }
                        }
                        let sp = Self::deref_ptr(slot);
                        self.apply_op_at(sp, op, rv, || None)
                    }
                    Value::Object(o) => {
                        let o = o.clone();
                        let kv = k.clone().unwrap_or(Value::Null);
                        let old = self.array_access_get(&o, &kv)?;
                        let nv = self.binop(op, &old, &rv)?;
                        self.array_access_set(&o, kv, nv.clone())?;
                        Ok(nv)
                    }
                    Value::Str(_) => Err(self.error("Cannot use assign-op operators with string offsets")),
                    _ => Err(self.error("Cannot use a scalar value as an array")),
                }
            }
            Step::Prop(name) => match cur {
                Value::Object(o) => {
                    let o = o.clone();
                    drop(temps);
                    let old = self.read_prop(&o, name, scope.as_ref(), false)?;
                    let nv = self.binop(op, &old, &rv)?;
                    self.write_prop_scoped(&o, name, nv.clone(), scope.as_ref(), false)?;
                    Ok(nv)
                }
                Value::Undef | Value::Null => {
                    let msg = format!("Attempt to assign property \"{}\" on null", String::from_utf8_lossy(name));
                    Err(self.error(&msg))
                }
                other => {
                    let msg = format!("Attempt to assign property \"{}\" on {}", String::from_utf8_lossy(name), other.type_name());
                    Err(self.error(&msg))
                }
            },
        }
    }

    /// apply compound op to storage at p (deref'd)
    fn apply_op_at(&mut self, p: *mut Value, op: BinOp, rv: Value, _f: impl Fn() -> Option<()>) -> R<Value> {
        let cur = unsafe { &mut *p };
        // in-place concat
        if op == BinOp::Concat {
            if let Value::Str(s) = cur {
                match &rv {
                    Value::Str(t) => {
                        Rc::make_mut(s).extend_from_slice(t);
                        return Ok(Value::Str(s.clone()));
                    }
                    Value::Int(i) => {
                        Rc::make_mut(s).extend_from_slice(i.to_string().as_bytes());
                        return Ok(Value::Str(s.clone()));
                    }
                    _ => {}
                }
            }
        }
        if let (Value::Int(a), Value::Int(b)) = (&*cur, &rv) {
            match op {
                BinOp::Add => {
                    if let Some(r) = a.checked_add(*b) {
                        *cur = Value::Int(r);
                        return Ok(Value::Int(r));
                    }
                }
                BinOp::Sub => {
                    if let Some(r) = a.checked_sub(*b) {
                        *cur = Value::Int(r);
                        return Ok(Value::Int(r));
                    }
                }
                _ => {}
            }
        }
        let old = cur.clone();
        let involves_obj = matches!(old, Value::Object(_)) || matches!(rv, Value::Object(_));
        let nv = self.binop(op, &old, &rv)?;
        if involves_obj {
            // pointer may be stale only in pathological cases; still write
        }
        let cur = unsafe { &mut *p };
        let prev = std::mem::replace(cur, nv.clone());
        drop(prev);
        drop(old);
        Ok(nv)
    }

    pub fn incdec_value(&mut self, v: &Value, inc: bool) -> R<Value> {
        Ok(match v {
            Value::Int(i) => {
                if inc {
                    match i.checked_add(1) {
                        Some(r) => Value::Int(r),
                        None => Value::Float(*i as f64 + 1.0),
                    }
                } else {
                    match i.checked_sub(1) {
                        Some(r) => Value::Int(r),
                        None => Value::Float(*i as f64 - 1.0),
                    }
                }
            }
            Value::Float(x) => Value::Float(if inc { x + 1.0 } else { x - 1.0 }),
            Value::Null | Value::Undef => {
                if inc {
                    Value::Int(1)
                } else {
                    self.warn("Decrement on type null has no effect, this will change in the next major version of PHP")?;
                    Value::Null
                }
            }
            Value::Bool(b) => {
                self.warn(&format!("{} on type bool has no effect, this will change in the next major version of PHP", if inc { "Increment" } else { "Decrement" }))?;
                Value::Bool(*b)
            }
            Value::Str(s) => {
                if s.is_empty() {
                    if inc {
                        self.deprecated("Increment on non-numeric string is deprecated, use str_increment() instead")?;
                        return Ok(Value::str("1"));
                    } else {
                        self.deprecated("Decrement on empty string is deprecated as non-numeric")?;
                        return Ok(Value::Int(-1));
                    }
                }
                match str_numeric(s) {
                    Some(Num::Int(i)) => return self.incdec_value(&Value::Int(i), inc),
                    Some(Num::Float(x)) => Value::Float(if inc { x + 1.0 } else { x - 1.0 }),
                    None => {
                        if inc {
                            self.deprecated("Increment on non-numeric string is deprecated, use str_increment() instead")?;
                            Value::vec(str_increment(s))
                        } else {
                            self.deprecated("Decrement on non-numeric string has no effect and is deprecated")?;
                            Value::Str(s.clone())
                        }
                    }
                }
            }
            Value::Array(_) => {
                return Err(self.type_error(&format!("Cannot {} array", if inc { "increment" } else { "decrement" })));
            }
            Value::Object(o) => {
                return Err(self.type_error(&format!("Cannot {} {}", if inc { "increment" } else { "decrement" }, o.class.name)));
            }
            Value::Ref(r) => {
                let v = r.borrow().clone();
                return self.incdec_value(&v, inc);
            }
        })
    }

    pub fn incdec_expr(&mut self, f: &mut Frame, pre: bool, inc: bool, target: &Expr) -> R<Value> {
        if let ExprKind::Var(v) = &target.kind {
            let i = f.idx(v);
            if i >= f.slots.len() {
                f.sync();
            }
            let p = Self::deref_ptr(&mut f.slots[i] as *mut Value);
            let cur = unsafe { &mut *p };
            if let Value::Int(n) = cur {
                let old = *n;
                if inc {
                    if let Some(r) = old.checked_add(1) {
                        *n = r;
                        return Ok(Value::Int(if pre { r } else { old }));
                    }
                } else if let Some(r) = old.checked_sub(1) {
                    *n = r;
                    return Ok(Value::Int(if pre { r } else { old }));
                }
            }
            if cur.is_undef() {
                self.warn(&format!("Undefined variable ${}", v.name))?;
                let cur = unsafe { &mut *p };
                *cur = Value::Null;
            }
            let cur = unsafe { &mut *p };
            let old = cur.clone();
            let nv = self.incdec_value(&old, inc)?;
            let cur = unsafe { &mut *p };
            *cur = nv.clone();
            return Ok(if pre { nv } else { old });
        }
        let mut steps = Vec::new();
        let base = self.lv_collect(f, target, &mut steps)?;
        let mut temps: Vec<Box<Value>> = Vec::new();
        if steps.is_empty() {
            let raw = self.base_raw(f, &base, &mut temps);
            let p = Self::deref_ptr(raw);
            let old = unsafe { (*p).clone() };
            let nv = self.incdec_value(&old, inc)?;
            unsafe {
                *p = nv.clone();
            }
            return Ok(if pre { nv } else { old });
        }
        let (last, init) = steps.split_last().unwrap();
        let p = self.lv_walk(f, &base, init, &mut temps, true)?;
        let scope = f.class.clone();
        let cur = unsafe { &mut *p };
        match last {
            Step::Prop(name) => match cur {
                Value::Object(o) => {
                    let o = o.clone();
                    let old = self.read_prop(&o, name, scope.as_ref(), false)?;
                    let nv = self.incdec_value(&old, inc)?;
                    self.write_prop_scoped(&o, name, nv.clone(), scope.as_ref(), false)?;
                    Ok(if pre { nv } else { old })
                }
                Value::Undef | Value::Null => {
                    let msg = format!("Attempt to increment/decrement property \"{}\" on null", String::from_utf8_lossy(name));
                    Err(self.error(&msg))
                }
                other => {
                    let msg = format!("Attempt to increment/decrement property \"{}\" on {}", String::from_utf8_lossy(name), other.type_name());
                    Err(self.error(&msg))
                }
            },
            Step::Dim(k) => {
                if let Value::Object(o) = cur {
                    let o = o.clone();
                    let kv = k.clone().unwrap_or(Value::Null);
                    let old = self.array_access_get(&o, &kv)?;
                    let nv = self.incdec_value(&old, inc)?;
                    self.array_access_set(&o, kv, nv.clone())?;
                    return Ok(if pre { nv } else { old });
                }
                if let Value::Str(_) = cur {
                    return Err(self.error("Cannot increment/decrement string offsets"));
                }
                let step = Step::Dim(k.clone());
                let sp = self.lv_step(p, &step, scope.as_ref(), &mut temps, true)?;
                let old = unsafe { (*sp).clone() };
                let old = if old.is_undef() { Value::Null } else { old };
                let nv = self.incdec_value(&old, inc)?;
                unsafe {
                    *sp = nv.clone();
                }
                Ok(if pre { nv } else { old })
            }
        }
    }

    pub fn unset_expr(&mut self, f: &mut Frame, e: &Expr) -> R<()> {
        match &e.kind {
            ExprKind::Var(v) => {
                let i = f.idx(v);
                if i < f.slots.len() {
                    let old = std::mem::replace(&mut f.slots[i], Value::Undef);
                    drop(old);
                }
                Ok(())
            }
            ExprKind::VarVar(ne) => {
                let nv = self.eval(f, ne)?;
                let name = self.to_str(&nv)?;
                if let Some(i) = f.find_slot(&name) {
                    let old = std::mem::replace(&mut f.slots[i], Value::Undef);
                    drop(old);
                }
                Ok(())
            }
            ExprKind::This => Err(self.fatal("Cannot unset $this")),
            ExprKind::Index(b, k) => {
                if let ExprKind::Super(n) = &b.kind {
                    if &**n == "GLOBALS" {
                        if let Some(k) = k {
                            let kv = self.eval(f, k)?;
                            let name = self.to_str(&kv)?;
                            let g = self.global_frame();
                            if let Some(i) = g.find_slot(&name) {
                                let old = std::mem::replace(&mut g.slots[i], Value::Undef);
                                drop(old);
                            }
                            return Ok(());
                        }
                    }
                }
                let mut steps = Vec::new();
                let base = self.lv_collect(f, b, &mut steps)?;
                let kv = match k {
                    Some(k) => self.eval(f, k)?,
                    None => return Err(self.fatal("Cannot use [] for unsetting")),
                };
                // walk without creating
                let mut temps: Vec<Box<Value>> = Vec::new();
                let raw = self.base_raw(f, &base, &mut temps);
                let mut p = Self::deref_ptr(raw);
                let scope = f.class.clone();
                for s in &steps {
                    let cur = unsafe { &mut *p };
                    match (s, cur) {
                        (Step::Dim(Some(k)), Value::Array(a)) => {
                            let key = self.to_key(k)?;
                            if !a.contains_key(&key) {
                                return Ok(());
                            }
                            let cur = unsafe { &mut *p };
                            if let Value::Array(a) = cur {
                                let arr = Rc::make_mut(a);
                                p = Self::deref_ptr(arr.get_mut(&key).unwrap() as *mut Value);
                            }
                        }
                        (Step::Dim(k), Value::Object(o)) => {
                            let o = o.clone();
                            let v = self.array_access_get(&o, &k.clone().unwrap_or(Value::Null))?;
                            temps.push(Box::new(v));
                            p = &mut **temps.last_mut().unwrap() as *mut Value;
                        }
                        (Step::Prop(n), Value::Object(o)) => {
                            let o = o.clone();
                            p = self.prop_ptr_for_write(&o, n, scope.as_ref(), &mut temps)?;
                        }
                        _ => return Ok(()),
                    }
                }
                let cur = unsafe { &mut *p };
                match cur {
                    Value::Array(a) => {
                        let key = self.to_key(&kv)?;
                        let cur = unsafe { &mut *p };
                        if let Value::Array(a2) = cur {
                            let _ = &a;
                            if a2.contains_key(&key) {
                                let arr = Rc::make_mut(a2);
                                let old = arr.remove(&key);
                                drop(old);
                            }
                        }
                    }
                    Value::Object(o) => {
                        let o = o.clone();
                        if o.class.instance_of_name("arrayaccess") {
                            if let Some(m) = o.class.find_method("offsetunset").cloned() {
                                self.call_method_obj(&o, &m, vec![kv])?;
                            }
                        } else {
                            let msg = format!("Cannot use object of type {} as array", o.class.name);
                            return Err(self.error(&msg));
                        }
                    }
                    Value::Str(_) => return Err(self.error("Cannot unset string offsets")),
                    _ => {}
                }
                Ok(())
            }
            ExprKind::Prop(b, name, _) => {
                let bv = self.eval(f, b)?;
                let n = self.member_name(f, name)?;
                if let Value::Object(o) = bv {
                    let scope = f.class.clone();
                    self.unset_prop(&o, &n, scope.as_ref())?;
                }
                Ok(())
            }
            ExprKind::StaticProp(..) => Err(self.error("Attempt to unset static property")),
            _ => Ok(()),
        }
    }
}

pub fn wrap_ref(slot: &mut Value) -> PRef {
    if let Value::Ref(r) = slot {
        return r.clone();
    }
    let old = std::mem::replace(slot, Value::Undef);
    let r = Rc::new(RefCell::new(if old.is_undef() { Value::Null } else { old }));
    *slot = Value::Ref(r.clone());
    r
}

pub fn str_increment(s: &[u8]) -> Vec<u8> {
    let mut v = s.to_vec();
    let mut i = v.len();
    loop {
        if i == 0 {
            // overflow: prepend
            let first = s[0];
            let pre = if first.is_ascii_digit() {
                b'1'
            } else if first.is_ascii_uppercase() {
                b'A'
            } else {
                b'a'
            };
            v.insert(0, pre);
            return v;
        }
        i -= 1;
        let c = v[i];
        match c {
            b'z' => {
                v[i] = b'a';
            }
            b'Z' => {
                v[i] = b'A';
            }
            b'9' => {
                v[i] = b'0';
            }
            b'a'..=b'y' | b'A'..=b'Y' | b'0'..=b'8' => {
                v[i] = c + 1;
                return v;
            }
            _ => return v,
        }
    }
}

pub fn new_parray() -> PArray {
    PArray::new()
}
