use super::*;
use crate::array::{Key, PArray};
use crate::ast::*;

macro_rules! loop_body {
    ($self:ident, $f:ident, $body:expr) => {
        match $self.exec_block($f, $body) {
            Ok(()) => {}
            Err(Flow::Break(n)) => {
                if n > 1 {
                    return Err(Flow::Break(n - 1));
                }
                break;
            }
            Err(Flow::Continue(n)) => {
                if n > 1 {
                    return Err(Flow::Continue(n - 1));
                }
            }
            Err(e) => return Err(e),
        }
    };
}

impl Interp {
    pub fn exec_block(&mut self, f: &mut Frame, stmts: &[Stmt]) -> R<()> {
        for s in stmts {
            self.exec(f, s)?;
        }
        Ok(())
    }

    pub fn exec(&mut self, f: &mut Frame, s: &Stmt) -> R<()> {
        self.cur_line = s.line;
        match &s.kind {
            StmtKind::Expr(e) => {
                let v = self.eval(f, e)?;
                drop(v);
            }
            StmtKind::Echo(es) => {
                for e in es {
                    let v = self.eval(f, e)?;
                    match &v {
                        Value::Str(s) => self.echo(s),
                        Value::Int(i) => {
                            let s = i.to_string();
                            self.echo(s.as_bytes());
                        }
                        _ => {
                            self.cur_line = e.line;
                            let s = self.to_str(&v)?;
                            self.echo(&s);
                        }
                    }
                }
            }
            StmtKind::InlineHtml(h) => self.echo(h),
            StmtKind::If(branches, els) => {
                let mut done = false;
                for (c, body) in branches {
                    let cv = self.eval(f, c)?;
                    if cv.to_bool() {
                        self.exec_block(f, body)?;
                        done = true;
                        break;
                    }
                }
                if !done {
                    if let Some(b) = els {
                        self.exec_block(f, b)?;
                    }
                }
            }
            StmtKind::While(c, body) => loop {
                let cv = self.eval(f, c)?;
                if !cv.to_bool() {
                    break;
                }
                loop_body!(self, f, body);
            },
            StmtKind::DoWhile(body, c) => loop {
                loop_body!(self, f, body);
                let cv = self.eval(f, c)?;
                if !cv.to_bool() {
                    break;
                }
            },
            StmtKind::For(init, cond, step, body) => {
                for e in init {
                    self.eval(f, e)?;
                }
                loop {
                    let mut ok = true;
                    for (i, c) in cond.iter().enumerate() {
                        let v = self.eval(f, c)?;
                        if i == cond.len() - 1 {
                            ok = v.to_bool();
                        }
                    }
                    if !ok {
                        break;
                    }
                    loop_body!(self, f, body);
                    for e in step {
                        self.eval(f, e)?;
                    }
                }
            }
            StmtKind::Foreach { subject, key, value, by_ref, body } => {
                self.exec_foreach(f, subject, key.as_ref(), value, *by_ref, body)?;
            }
            StmtKind::Switch(subj, cases) => {
                let v = self.eval(f, subj)?;
                let mut start = None;
                for (i, c) in cases.iter().enumerate() {
                    if let Some(ce) = &c.cond {
                        let cv = self.eval(f, ce)?;
                        if self.loose_eq(&v, &cv)? {
                            start = Some(i);
                            break;
                        }
                    }
                }
                if start.is_none() {
                    start = cases.iter().position(|c| c.cond.is_none());
                }
                if let Some(st) = start {
                    for c in &cases[st..] {
                        match self.exec_block(f, &c.body) {
                            Ok(()) => {}
                            Err(Flow::Break(n)) | Err(Flow::Continue(n)) if n <= 1 => return self.after_stmt(),
                            Err(Flow::Break(n)) => return Err(Flow::Break(n - 1)),
                            Err(Flow::Continue(n)) => return Err(Flow::Continue(n - 1)),
                            Err(e) => return Err(e),
                        }
                    }
                }
            }
            StmtKind::Break(n) => return Err(Flow::Break(*n)),
            StmtKind::Continue(n) => return Err(Flow::Continue(*n)),
            StmtKind::Return(e) => {
                let v = match e {
                    Some(e) => {
                        if f.func.as_ref().map(|d| d.by_ref).unwrap_or(false) {
                            match &e.kind {
                                ExprKind::Var(_) | ExprKind::Index(..) | ExprKind::Prop(..) | ExprKind::StaticProp(..) => Value::Ref(self.make_ref(f, e)?),
                                _ => self.eval(f, e)?,
                            }
                        } else {
                            self.eval(f, e)?
                        }
                    }
                    None => Value::Null,
                };
                return Err(Flow::Return(v));
            }
            StmtKind::Global(vars) => {
                for v in vars {
                    let name = match &v.kind {
                        ExprKind::Var(vr) => Rc::new(vr.name.as_bytes().to_vec()),
                        ExprKind::VarVar(e) => {
                            let nv = self.eval(f, e)?;
                            self.to_str(&nv)?
                        }
                        _ => continue,
                    };
                    if f.is_global {
                        continue;
                    }
                    let g = self.global_frame();
                    let gi = g.slot_for(&name);
                    let r = lval::wrap_ref(&mut g.slots[gi]);
                    let li = match &v.kind {
                        ExprKind::Var(vr) => f.idx(vr),
                        _ => f.slot_for(&name),
                    };
                    if li >= f.slots.len() {
                        f.sync();
                    }
                    f.slots[li] = Value::Ref(r);
                }
            }
            StmtKind::Static(vars) => {
                for (vr, init, _line) in vars {
                    let key = vr as *const VarRef as usize;
                    let existing = match &f.closure {
                        Some(c) => crate::builtins::classes::closure_static(c, key),
                        None => self.statics.get(&key).cloned(),
                    };
                    let r = match existing {
                        Some(r) => r,
                        None => {
                            let v = match init {
                                Some(e) => self.eval(f, e)?,
                                None => Value::Null,
                            };
                            let r = Rc::new(RefCell::new(v));
                            match &f.closure {
                                Some(c) => crate::builtins::classes::closure_static_set(c, key, r.clone()),
                                None => {
                                    self.statics.insert(key, r.clone());
                                }
                            }
                            r
                        }
                    };
                    let i = f.idx(vr);
                    if i >= f.slots.len() {
                        f.sync();
                    }
                    f.slots[i] = Value::Ref(r);
                }
            }
            StmtKind::Unset(es) => {
                for e in es {
                    self.unset_expr(f, e)?;
                }
            }
            StmtKind::FuncDecl(d) => {
                self.declare_function(d)?;
            }
            StmtKind::ClassDecl(d) => {
                if !d.declared.get() {
                    self.declare_class(d)?;
                }
            }
            StmtKind::Try(body, catches, finally) => {
                return self.exec_try(f, body, catches, finally.as_deref());
            }
            StmtKind::Block(b) => self.exec_block(f, b)?,
            StmtKind::Const(items) => {
                for (n, e) in items {
                    let v = self.eval(f, e)?;
                    let key = n.as_bytes().to_vec();
                    if self.constants.contains_key(&key) {
                        self.warn(&format!("Constant {} already defined", n))?;
                    } else {
                        self.constants.insert(key, v);
                    }
                }
            }
            StmtKind::Nop => {}
            StmtKind::Label(_) => {}
            StmtKind::Goto(l) => return Err(Flow::Goto(l.clone())),
            StmtKind::Declare(_, body) => {
                if let Some(b) = body {
                    self.exec_block(f, b)?;
                }
            }
        }
        self.after_stmt()
    }

    #[inline]
    fn after_stmt(&mut self) -> R<()> {
        self.run_pending()
    }

    fn exec_try(&mut self, f: &mut Frame, body: &[Stmt], catches: &[Catch], finally: Option<&[Stmt]>) -> R<()> {
        let r = self.exec_block(f, body);
        let r = match r {
            Err(Flow::Throw(ex)) => {
                let mut handled = None;
                for c in catches {
                    if c.types.iter().any(|t| {
                        let l = String::from_utf8_lossy(&lc(t)).to_string();
                        ex.class.instance_of_name(&l)
                    }) {
                        handled = Some(c);
                        break;
                    }
                }
                match handled {
                    Some(c) => {
                        if let Some(v) = &c.var {
                            let i = f.idx(v);
                            if i >= f.slots.len() {
                                f.sync();
                            }
                            match &mut f.slots[i] {
                                Value::Ref(r) => *r.borrow_mut() = Value::Object(ex),
                                slot => *slot = Value::Object(ex),
                            }
                        } else {
                            drop(ex);
                        }
                        self.exec_block(f, &c.body)
                    }
                    None => Err(Flow::Throw(ex)),
                }
            }
            other => other,
        };
        if let Some(fin) = finally {
            match r {
                Err(Flow::Exit(_)) | Err(Flow::Fatal) => return r,
                _ => {}
            }
            let fr = self.exec_block(f, fin);
            fr?;
        }
        r
    }

    pub fn exec_foreach(&mut self, f: &mut Frame, subject: &Expr, key: Option<&Expr>, value: &Expr, by_ref: bool, body: &[Stmt]) -> R<()> {
        if by_ref {
            return self.exec_foreach_ref(f, subject, key, value, body);
        }
        let v = self.eval(f, subject)?;
        match v {
            Value::Array(a) => {
                if a.is_empty() {
                    return Ok(());
                }
                // fast path for simple var targets
                for (k, val) in a.iter() {
                    let val = val.deref();
                    self.foreach_assign(f, value, val)?;
                    if let Some(ke) = key {
                        self.foreach_assign(f, ke, k.to_value())?;
                    }
                    loop_body!(self, f, body);
                }
                Ok(())
            }
            Value::Object(o) => self.foreach_object(f, &o, key, value, false, body),
            other => {
                self.cur_line = subject.line;
                self.warn(&format!("foreach() argument must be of type array|object, {} given", other.type_name()))?;
                Ok(())
            }
        }
    }

    #[inline]
    fn foreach_assign(&mut self, f: &mut Frame, target: &Expr, v: Value) -> R<()> {
        if let ExprKind::Var(vr) = &target.kind {
            let i = f.idx(vr);
            if i >= f.slots.len() {
                f.sync();
            }
            match &mut f.slots[i] {
                Value::Ref(r) => {
                    let old = std::mem::replace(&mut *r.borrow_mut(), v);
                    drop(old);
                }
                slot => {
                    let old = std::mem::replace(slot, v);
                    drop(old);
                }
            }
            return Ok(());
        }
        self.assign_value(f, target, v)?;
        Ok(())
    }

    fn exec_foreach_ref(&mut self, f: &mut Frame, subject: &Expr, key: Option<&Expr>, value: &Expr, body: &[Stmt]) -> R<()> {
        // object case
        let probe = self.eval_quiet(f, subject)?;
        if let Some(Value::Object(o)) = probe {
            return self.foreach_object(f, &o, key, value, true, body);
        }
        let mut pos = 0usize;
        loop {
            // resolve array storage each iteration
            let r = self.make_ref(f, subject)?;
            let (k, elem_ref) = {
                let mut b = r.borrow_mut();
                match &mut *b {
                    Value::Null | Value::Undef => {
                        if pos == 0 {
                            drop(b);
                            self.warn("foreach() argument must be of type array|object, null given")?;
                        }
                        return Ok(());
                    }
                    Value::Array(a) => {
                        let arr = Rc::make_mut(a);
                        match arr.next_valid(pos) {
                            None => return Ok(()),
                            Some(p) => {
                                pos = p + 1;
                                let (k, slot) = arr.entry_at_mut(p).unwrap();
                                let k = k.clone();
                                let er = lval::wrap_ref(slot);
                                (k, er)
                            }
                        }
                    }
                    other => {
                        let tn = other.type_name();
                        drop(b);
                        self.warn(&format!("foreach() argument must be of type array|object, {} given", tn))?;
                        return Ok(());
                    }
                }
            };
            drop(r);
            self.bind_ref(f, value, elem_ref)?;
            if let Some(ke) = key {
                self.foreach_assign(f, ke, k.to_value())?;
            }
            loop_body!(self, f, body);
        }
        Ok(())
    }

    pub fn foreach_object(&mut self, f: &mut Frame, o: &Obj, key: Option<&Expr>, value: &Expr, by_ref: bool, body: &[Stmt]) -> R<()> {
        if gen::is_generator_obj(o) {
            gen::gen_rewind(self, o)?;
            loop {
                if !gen::gen_valid(self, o)? {
                    break;
                }
                let v = gen::gen_current(self, o)?;
                if by_ref {
                    if let Value::Ref(r) = v {
                        self.bind_ref(f, value, r)?;
                    } else {
                        self.foreach_assign(f, value, v)?;
                    }
                } else {
                    self.foreach_assign(f, value, v.deref())?;
                }
                if let Some(ke) = key {
                    let k = gen::gen_key(self, o)?;
                    self.foreach_assign(f, ke, k)?;
                }
                loop_body!(self, f, body);
                gen::gen_next(self, o)?;
            }
            return Ok(());
        }
        if o.class.instance_of_name("iterator") {
            self.call_method_name(o, "rewind", vec![])?;
            loop {
                let valid = self.call_method_name(o, "valid", vec![])?;
                if !valid.to_bool() {
                    break;
                }
                let v = self.call_method_name(o, "current", vec![])?;
                self.foreach_assign(f, value, v)?;
                if let Some(ke) = key {
                    let k = self.call_method_name(o, "key", vec![])?;
                    self.foreach_assign(f, ke, k)?;
                }
                loop_body!(self, f, body);
                self.call_method_name(o, "next", vec![])?;
            }
            return Ok(());
        }
        if o.class.instance_of_name("iteratoraggregate") {
            let it = self.call_method_name(o, "getIterator", vec![])?;
            match it {
                Value::Object(io) if io.class.instance_of_name("traversable") => {
                    return self.foreach_object(f, &io, key, value, by_ref, body);
                }
                _ => {
                    let msg = format!("{}::getIterator(): Return value must be of type Traversable, {} returned", o.class.name, it.type_name());
                    return Err(self.type_error(&msg));
                }
            }
        }
        // plain object: iterate visible properties
        let scope = f.class.clone();
        let props = self.visible_props(o, scope.as_ref());
        for (name, _) in props {
            // re-read current value (may have changed)
            let cur = match self.prop_get_direct(o, &name, scope.as_ref()) {
                Some(v) => v,
                None => continue,
            };
            if by_ref {
                let mut temps = Vec::new();
                let raw = self.prop_raw_ptr(o, &name, scope.as_ref(), &mut temps)?;
                let r = unsafe { lval::wrap_ref(&mut *raw) };
                self.bind_ref(f, value, r)?;
            } else {
                self.foreach_assign(f, value, cur.deref())?;
            }
            if let Some(ke) = key {
                self.foreach_assign(f, ke, Key::from_str_bytes(&name).to_value())?;
            }
            loop_body!(self, f, body);
        }
        Ok(())
    }

    /// generic iteration helper for builtins: callback(key, value) -> continue?
    pub fn iterate_object(&mut self, o: &Obj, cb: &mut dyn FnMut(&mut Interp, Value, Value) -> R<bool>) -> R<()> {
        if gen::is_generator_obj(o) {
            gen::gen_rewind(self, o)?;
            while gen::gen_valid(self, o)? {
                let v = gen::gen_current(self, o)?.deref();
                let k = gen::gen_key(self, o)?;
                if !cb(self, k, v)? {
                    break;
                }
                gen::gen_next(self, o)?;
            }
            return Ok(());
        }
        if o.class.instance_of_name("iterator") {
            self.call_method_name(o, "rewind", vec![])?;
            loop {
                let valid = self.call_method_name(o, "valid", vec![])?;
                if !valid.to_bool() {
                    break;
                }
                let v = self.call_method_name(o, "current", vec![])?;
                let k = self.call_method_name(o, "key", vec![])?;
                if !cb(self, k, v)? {
                    break;
                }
                self.call_method_name(o, "next", vec![])?;
            }
            return Ok(());
        }
        if o.class.instance_of_name("iteratoraggregate") {
            let it = self.call_method_name(o, "getIterator", vec![])?;
            if let Value::Object(io) = it {
                return self.iterate_object(&io, cb);
            }
            return Err(self.error("getIterator() must return a Traversable"));
        }
        let props = self.visible_props(o, None);
        for (name, v) in props {
            if !cb(self, Key::from_str_bytes(&name).to_value(), v.deref())? {
                break;
            }
        }
        Ok(())
    }

    pub fn declare_function(&mut self, d: &Rc<FuncDecl>) -> R<()> {
        let l = lc(&d.name);
        if let Some(existing) = self.functions.get(&l) {
            if let Callable::User(u) = existing {
                if Rc::ptr_eq(u, d) {
                    return Ok(());
                }
                let msg = format!("Cannot redeclare function {}() (previously declared in {}:{})", d.name, u.file, u.line);
                return Err(self.fatal(&msg));
            }
            let msg = format!("Cannot redeclare function {}()", d.name);
            return Err(self.fatal(&msg));
        }
        self.functions.insert(l, Callable::User(d.clone()));
        Ok(())
    }

    /// hoist declarations in a statement list
    pub fn hoist(&mut self, stmts: &[Stmt]) -> R<()> {
        for s in stmts {
            match &s.kind {
                StmtKind::FuncDecl(d) => {
                    self.declare_function(d)?;
                }
                StmtKind::Block(b) => self.hoist_funcs_only(b)?,
                _ => {}
            }
        }
        // classes: multiple passes
        let mut pending: Vec<&Rc<ClassDecl>> = Vec::new();
        collect_classes(stmts, &mut pending);
        loop {
            let mut progress = false;
            let mut rest = Vec::new();
            for d in pending {
                if d.declared.get() {
                    continue;
                }
                if self.class_deps_ready(d) {
                    let saved = self.cur_line;
                    self.cur_line = d.line;
                    match self.declare_class(d) {
                        Ok(()) => progress = true,
                        Err(e) => {
                            // defer errors to runtime
                            match e {
                                Flow::Fatal => return Err(Flow::Fatal),
                                _ => {}
                            }
                        }
                    }
                    self.cur_line = saved;
                } else {
                    rest.push(d);
                }
            }
            pending = rest;
            if !progress || pending.is_empty() {
                break;
            }
        }
        Ok(())
    }

    fn hoist_funcs_only(&mut self, stmts: &[Stmt]) -> R<()> {
        for s in stmts {
            if let StmtKind::FuncDecl(d) = &s.kind {
                self.declare_function(d)?;
            }
            if let StmtKind::Block(b) = &s.kind {
                self.hoist_funcs_only(b)?;
            }
        }
        Ok(())
    }

    fn class_deps_ready(&self, d: &ClassDecl) -> bool {
        let ok = |n: &Name| self.classes.contains_key(&lc(n));
        if let Some(p) = &d.parent {
            if !ok(p) {
                return false;
            }
        }
        d.interfaces.iter().all(ok) && d.traits.iter().all(ok)
    }

    pub fn include_file(&mut self, f: &mut Frame, kind: IncludeKind, path: &str) -> R<Value> {
        let resolved = self.resolve_include_path(path);
        let once = matches!(kind, IncludeKind::IncludeOnce | IncludeKind::RequireOnce);
        let fname = match kind {
            IncludeKind::Include => "include",
            IncludeKind::IncludeOnce => "include_once",
            IncludeKind::Require => "require",
            IncludeKind::RequireOnce => "require_once",
        };
        let real = match &resolved {
            Some(p) => std::fs::canonicalize(p).map(|x| x.to_string_lossy().to_string()).unwrap_or(p.clone()),
            None => {
                if matches!(kind, IncludeKind::Require | IncludeKind::RequireOnce) {
                    self.warn(&format!("{}({}): Failed to open stream: No such file or directory", fname, path))?;
                    let msg = format!("Uncaught Error: Failed opening required '{}' (include_path='.:/usr/share/php')", path);
                    let _ = msg;
                    return Err(self.fatal(&format!("Failed opening required '{}' (include_path='.:')", path)));
                }
                self.warn(&format!("{}({}): Failed to open stream: No such file or directory", fname, path))?;
                self.warn(&format!("{}(): Failed opening '{}' for inclusion (include_path='.:')", fname, path))?;
                return Ok(Value::Bool(false));
            }
        };
        if once && self.included.contains(&real) {
            return Ok(Value::Bool(true));
        }
        self.included.insert(real.clone());
        let src = match std::fs::read(&real) {
            Ok(s) => s,
            Err(_) => {
                self.warn(&format!("{}({}): Failed to open stream: No such file or directory", fname, path))?;
                return Ok(Value::Bool(false));
            }
        };
        let prog = match crate::compile_source(&src, &real, false) {
            Ok(p) => Rc::new(p),
            Err((msg, line)) => {
                let s = format!("\nParse error: {} in {} on line {}\n", msg, real, line);
                self.echo(s.as_bytes());
                self.exit_code = 255;
                return Err(Flow::Fatal);
            }
        };
        self.compiled_files.insert(real.clone(), prog.clone());
        self.run_program_in_frame(f, &prog)
    }

    fn resolve_include_path(&self, path: &str) -> Option<String> {
        let p = std::path::Path::new(path);
        if p.is_absolute() {
            return if p.exists() { Some(path.to_string()) } else { None };
        }
        if path.starts_with("./") || path.starts_with("../") {
            if p.exists() {
                return Some(path.to_string());
            }
        }
        // relative to current script dir
        let dir = match self.cur_file.rfind('/') {
            Some(i) => &self.cur_file[..i],
            None => ".",
        };
        let cand = format!("{}/{}", dir, path);
        if std::path::Path::new(&cand).exists() {
            return Some(cand);
        }
        if p.exists() {
            return Some(path.to_string());
        }
        None
    }

    /// run a compiled program (included file / eval) within an existing frame
    pub fn run_program_in_frame(&mut self, f: &mut Frame, prog: &Rc<Program>) -> R<Value> {
        // build remap
        let mut map = Vec::with_capacity(prog.slot_names.len());
        for n in prog.slot_names.iter() {
            let i = f.slot_for(n.as_bytes());
            map.push(i as u32);
        }
        f.sync();
        let saved_remap = std::mem::replace(&mut f.remap, Some(Rc::new(compose_remap(&None, map))));
        let saved_file = std::mem::replace(&mut self.cur_file, prog.file.clone());
        let saved_line = self.cur_line;
        for (w, l) in &prog.warnings {
            let (lvl, msg) = split_level(w);
            self.cur_line = *l;
            self.raise(lvl, msg)?;
        }
        let r = self.hoist(&prog.stmts).and_then(|_| self.exec_block(f, &prog.stmts));
        f.remap = saved_remap;
        self.cur_file = saved_file;
        self.cur_line = saved_line;
        match r {
            Ok(()) => Ok(Value::Int(1)),
            Err(Flow::Return(v)) => Ok(v),
            Err(e) => Err(e),
        }
    }

    pub fn eval_code(&mut self, f: &mut Frame, code: &[u8]) -> R<Value> {
        let name = format!("{}({}) : eval()'d code", self.cur_file, self.cur_line);
        let prog = match crate::compile_source(code, &name, true) {
            Ok(p) => Rc::new(p),
            Err((msg, line)) => {
                let ex = self.create_exception("ParseError", &msg, 0)?;
                self.set_exception_location(&ex, &name, line);
                return Err(Flow::Throw(ex));
            }
        };
        let mut map = Vec::with_capacity(prog.slot_names.len());
        for n in prog.slot_names.iter() {
            let i = f.slot_for(n.as_bytes());
            map.push(i as u32);
        }
        f.sync();
        let saved_remap = std::mem::replace(&mut f.remap, Some(Rc::new(map)));
        let saved_file = std::mem::replace(&mut self.cur_file, prog.file.clone());
        let saved_line = self.cur_line;
        self.compiled_files.insert(format!("eval{}", self.compiled_files.len()), prog.clone());
        let r = self.hoist(&prog.stmts).and_then(|_| self.exec_block(f, &prog.stmts));
        f.remap = saved_remap;
        self.cur_file = saved_file;
        self.cur_line = saved_line;
        match r {
            Ok(()) => Ok(Value::Null),
            Err(Flow::Return(v)) => Ok(v),
            Err(e) => Err(e),
        }
    }
}

fn compose_remap(_outer: &Option<Rc<Vec<u32>>>, map: Vec<u32>) -> Vec<u32> {
    map
}

pub fn split_level(w: &str) -> (i64, &str) {
    if let Some(m) = w.strip_prefix("Deprecated: ") {
        (E_DEPRECATED, m)
    } else if let Some(m) = w.strip_prefix("Warning: ") {
        (E_WARNING, m)
    } else if let Some(m) = w.strip_prefix("Notice: ") {
        (E_NOTICE, m)
    } else {
        (E_WARNING, w)
    }
}

fn collect_classes<'a>(stmts: &'a [Stmt], out: &mut Vec<&'a Rc<ClassDecl>>) {
    for s in stmts {
        match &s.kind {
            StmtKind::ClassDecl(d) => out.push(d),
            StmtKind::Block(b) => collect_classes(b, out),
            _ => {}
        }
    }
}

pub fn arr_from_pairs(pairs: Vec<(Key, Value)>) -> PArray {
    PArray::from_pairs(pairs)
}
