use super::*;
use crate::array::{Key, PArray};
use crate::ast::*;
use crate::builtins::{Args, BuiltinDef};

pub struct CallCtx {
    pub this: Option<Obj>,
    pub class: Option<Rc<Class>>,
    pub static_class: Option<Rc<Class>>,
    pub closure: Option<Obj>,
    pub disp_class: Option<Name>,
    pub call_type: &'static str,
    pub bound_vars: Option<Vec<(u32, Value)>>,
}

impl CallCtx {
    pub fn plain() -> CallCtx {
        CallCtx { this: None, class: None, static_class: None, closure: None, disp_class: None, call_type: "", bound_vars: None }
    }
}

pub fn type_to_string(t: &TypeHint) -> String {
    match t {
        TypeHint::Simple(n) => {
            if &**n == "iterable" {
                "Traversable|array".to_string()
            } else {
                n.to_string()
            }
        }
        TypeHint::Nullable(inner) => {
            let s = type_to_string(inner);
            if s.contains('|') {
                format!("{}|null", s)
            } else {
                format!("?{}", s)
            }
        }
        TypeHint::Union(ts) => {
            // canonical order: classes first, then builtins in fixed order
            let order = ["static", "callable", "object", "array", "string", "int", "float", "bool", "false", "true", "void", "never", "null"];
            let mut classes = Vec::new();
            let mut builtins: Vec<String> = Vec::new();
            for t in ts {
                match t {
                    TypeHint::Simple(n) if order.contains(&&**n) || &**n == "mixed" || &**n == "iterable" => {
                        if &**n == "iterable" {
                            classes.push("Traversable".to_string());
                            builtins.push("array".to_string());
                        } else {
                            builtins.push(n.to_string());
                        }
                    }
                    TypeHint::Intersection(_) => classes.push(format!("({})", type_to_string(t))),
                    _ => classes.push(type_to_string(t)),
                }
            }
            let mut out = classes;
            for o in order.iter() {
                if builtins.iter().any(|b| b == o) {
                    if *o == "bool" || !(builtins.iter().any(|b| b == "bool") && (*o == "false" || *o == "true")) {
                        out.push(o.to_string());
                    }
                }
            }
            out.join("|")
        }
        TypeHint::Intersection(ts) => ts.iter().map(type_to_string).collect::<Vec<_>>().join("&"),
    }
}

impl Interp {
    pub fn resolve_func(&mut self, fname: &FuncName) -> R<Callable> {
        if let Some(c) = &*fname.cache.borrow() {
            return Ok(c.clone());
        }
        let l = lc(&fname.name);
        let found = match self.functions.get(&l) {
            Some(c) => Some(c.clone()),
            None => match &fname.fallback {
                Some(fb) => self.functions.get(&lc(fb)).cloned(),
                None => None,
            },
        };
        match found {
            Some(c) => {
                *fname.cache.borrow_mut() = Some(c.clone());
                Ok(c)
            }
            None => {
                let n = fname.name.trim_start_matches('\\');
                let msg = format!("Call to undefined function {}()", n);
                Err(self.error(&msg))
            }
        }
    }

    /// evaluate call arguments
    pub fn eval_args(&mut self, f: &mut Frame, args: &[Arg], by_ref: &dyn Fn(usize, Option<&str>) -> bool) -> R<(Vec<Value>, Vec<(Name, Value)>)> {
        let mut out = Vec::with_capacity(args.len());
        let mut named: Vec<(Name, Value)> = Vec::new();
        for a in args {
            if a.unpack {
                let v = self.eval(f, &a.value)?;
                match v {
                    Value::Array(arr) => {
                        for (k, v) in arr.iter() {
                            match k {
                                Key::Int(_) => {
                                    if !named.is_empty() {
                                        return Err(self.error("Cannot use positional argument after named argument during unpacking"));
                                    }
                                    if by_ref(out.len(), None) {
                                        if let Value::Ref(r) = v {
                                            out.push(Value::Ref(r.clone()));
                                            continue;
                                        }
                                    }
                                    out.push(v.deref())
                                }
                                Key::Str(s) => named.push((Rc::from(String::from_utf8_lossy(s).as_ref()), v.deref())),
                            }
                        }
                    }
                    Value::Object(o) => {
                        let mut items = Vec::new();
                        self.iterate_object(&o, &mut |_, k, v| {
                            items.push((k, v));
                            Ok(true)
                        })?;
                        for (k, v) in items {
                            match k {
                                Value::Str(s) => named.push((Rc::from(String::from_utf8_lossy(&s).as_ref()), v)),
                                _ => out.push(v),
                            }
                        }
                    }
                    Value::Null => {
                        return Err(self.type_error("Only arrays and Traversables can be unpacked, null given"));
                    }
                    other => {
                        let msg = format!("Only arrays and Traversables can be unpacked, {} given", other.type_name());
                        return Err(self.type_error(&msg));
                    }
                }
                continue;
            }
            if let Some(n) = &a.name {
                let v = if by_ref(usize::MAX, Some(n)) { Value::Ref(self.make_ref(f, &a.value)?) } else { self.eval(f, &a.value)? };
                named.push((n.clone(), v));
                continue;
            }
            if !named.is_empty() {
                return Err(self.fatal("Cannot use positional argument after named argument"));
            }
            let i = out.len();
            if by_ref(i, None) {
                let r = self.make_ref_arg(f, &a.value)?;
                out.push(r);
            } else {
                out.push(self.eval(f, &a.value)?);
            }
        }
        Ok((out, named))
    }

    fn make_ref_arg(&mut self, f: &mut Frame, e: &Expr) -> R<Value> {
        match &e.kind {
            ExprKind::Var(_) | ExprKind::VarVar(_) | ExprKind::Index(..) | ExprKind::Prop(..) | ExprKind::StaticProp(..) | ExprKind::Super(_) => Ok(Value::Ref(self.make_ref(f, e)?)),
            ExprKind::Call(..) | ExprKind::MethodCall(..) | ExprKind::StaticCall(..) | ExprKind::CallExpr(..) => {
                let v = self.eval(f, e)?;
                if let Value::Ref(_) = v {
                    return Ok(v);
                }
                self.notice("Only variables should be passed by reference")?;
                Ok(Value::Ref(Rc::new(RefCell::new(v))))
            }
            _ => {
                let v = self.eval(f, e)?;
                Ok(Value::Ref(Rc::new(RefCell::new(v))))
            }
        }
    }

    pub fn eval_call(&mut self, f: &mut Frame, fname: &FuncName, args: &[Arg], line: u32) -> R<Value> {
        let c = self.resolve_func(fname)?;
        match c {
            Callable::User(decl) => {
                let d2 = decl.clone();
                let (av, named) = self.eval_args(f, args, &|i, n| param_by_ref(&d2, i, n))?;
                self.cur_line = line;
                self.call_user(&decl, av, named, CallCtx::plain(), line)
            }
            Callable::Builtin(def) => {
                if let Some(r) = self.frame_builtin(f, def, args, line)? {
                    return Ok(r);
                }
                let (av, named) = self.eval_args(f, args, &|i, n| builtin_by_ref(def, i, n))?;
                self.cur_line = line;
                self.call_builtin(def, av, named, line)
            }
        }
    }

    pub fn call_builtin(&mut self, def: &'static BuiltinDef, mut av: Vec<Value>, named: Vec<(Name, Value)>, line: u32) -> R<Value> {
        if !named.is_empty() {
            for (n, v) in named {
                match def.params.iter().position(|p| p.name == &*n && !p.variadic) {
                    Some(i) => {
                        while av.len() <= i {
                            av.push(Value::Undef);
                        }
                        if !av[i].is_undef() {
                            let msg = format!("Named parameter ${} overwrites previous argument", n);
                            return Err(self.error(&msg));
                        }
                        av[i] = v;
                    }
                    None => {
                        if def.variadic {
                            av.push(v);
                        } else {
                            let msg = format!("Unknown named parameter ${}", n);
                            return Err(self.error(&msg));
                        }
                    }
                }
            }
            for i in 0..def.min.min(av.len()) {
                if av[i].is_undef() {
                    let msg = format!("{}(): Argument #{} (${}) not passed", def.name, i + 1, def.params[i].name);
                    return Err(self.throw_err("ArgumentCountError", &msg));
                }
            }
        }
        let n = av.len();
        if n < def.min || (!def.variadic && n > def.params.len()) {
            let max = def.params.len();
            let msg = if def.variadic {
                format!("{}() expects at least {} argument{}, {} given", def.name, def.min, if def.min == 1 { "" } else { "s" }, n)
            } else if def.min == max {
                format!("{}() expects exactly {} argument{}, {} given", def.name, def.min, if def.min == 1 { "" } else { "s" }, n)
            } else if n < def.min {
                format!("{}() expects at least {} argument{}, {} given", def.name, def.min, if def.min == 1 { "" } else { "s" }, n)
            } else {
                format!("{}() expects at most {} argument{}, {} given", def.name, max, if max == 1 { "" } else { "s" }, n)
            };
            return Err(self.throw_err("ArgumentCountError", &msg));
        }
        let mut args = Args { v: av, def };
        self.call_stack.push(CallInfo {
            func: Rc::from(def.name),
            class: None,
            call_type: "",
            file: self.cur_file.clone(),
            line,
            frame: std::ptr::null(),
            bargs: &args.v as *const Vec<Value>,
            internal: false,
            obj: None,
        });
        let r = (def.f)(self, &mut args);
        self.call_stack.pop();
        self.cur_line = line;
        r
    }

    /// user function invocation
    pub fn call_user(&mut self, decl: &Rc<FuncDecl>, args: Vec<Value>, named: Vec<(Name, Value)>, ctx: CallCtx, line: u32) -> R<Value> {
        let mut nf = Frame::new(decl.num_slots as usize, decl.slot_names.clone(), decl.file.clone());
        nf.func = Some(decl.clone());
        nf.this = ctx.this;
        nf.class = ctx.class;
        nf.static_class = ctx.static_class;
        nf.closure = ctx.closure;
        nf.strict = self.strict_files.contains(&*decl.file);
        if let Some(bv) = ctx.bound_vars {
            for (slot, v) in bv {
                nf.slots[slot as usize] = v;
            }
        }
        let disp = match &ctx.disp_class {
            Some(c) => format!("{}::{}", c, decl.name),
            None => decl.name.to_string(),
        };
        let caller_file = self.cur_file.clone();
        let caller_strict = self.strict_files.contains(&*caller_file);
        self.depth += 1;
        if self.depth > 50000 {
            self.depth -= 1;
            let msg = "Maximum function nesting level reached".to_string();
            return Err(self.error(&msg));
        }
        // push call info before binding (for errors)
        self.call_stack.push(CallInfo {
            func: decl.name.clone(),
            class: ctx.disp_class.clone(),
            call_type: ctx.call_type,
            file: caller_file.clone(),
            line,
            frame: &nf as *const Frame,
            bargs: std::ptr::null(),
            internal: false,
            obj: nf.this.clone(),
        });
        let saved_file = std::mem::replace(&mut self.cur_file, decl.file.clone());
        let r = self.bind_params(decl, &mut nf, args, named, &disp, &caller_file, line, caller_strict);
        let r = match r {
            Err(e) => Err(e),
            Ok(()) => {
                if decl.is_generator {
                    // frame moves into generator
                    self.call_stack.pop();
                    let fp = Box::new(nf);
                    let g = gen::create_generator(self, decl, fp, ctx.disp_class.clone(), ctx.call_type);
                    self.cur_file = saved_file;
                    self.cur_line = line;
                    self.depth -= 1;
                    return Ok(g);
                }
                let body = decl.body.as_ref().unwrap();
                let r = self.exec_block(&mut nf, body);
                match r {
                    Ok(()) => Ok(Value::Null),
                    Err(Flow::Return(v)) => Ok(v),
                    Err(e) => Err(e),
                }
            }
        };
        let r = match r {
            Ok(v) => {
                if let Some(rt) = &decl.ret {
                    self.check_return(decl, &nf, rt, v, &disp)
                } else {
                    Ok(v)
                }
            }
            e => e,
        };
        self.call_stack.pop();
        self.cur_file = saved_file;
        self.cur_line = line;
        self.depth -= 1;
        drop(nf);
        let r = match r {
            Ok(v) => {
                self.run_pending()?;
                if decl.by_ref {
                    Ok(v)
                } else {
                    Ok(v.into_deref())
                }
            }
            e => e,
        };
        r
    }

    fn check_return(&mut self, decl: &Rc<FuncDecl>, nf: &Frame, rt: &TypeHint, v: Value, disp: &str) -> R<Value> {
        if let TypeHint::Simple(n) = rt {
            match &**n {
                "void" => return Ok(Value::Null),
                "mixed" => return Ok(v),
                "never" => {
                    let msg = format!("{}(): never-returning function must not implicitly return", disp);
                    return Err(self.type_error(&msg));
                }
                _ => {}
            }
        }
        if decl.is_generator {
            return Ok(v);
        }
        let vd = v.deref();
        let strict = nf.strict;
        match self.coerce_type(&vd, rt, strict, nf.class.as_ref(), nf.static_class.as_ref())? {
            Some(c) => {
                if let Value::Ref(_) = v {
                    if decl.by_ref {
                        return Ok(v);
                    }
                }
                Ok(c)
            }
            None => {
                let msg = format!("{}(): Return value must be of type {}, {} returned", disp, type_to_string(rt), type_name_given(&vd));
                Err(self.type_error(&msg))
            }
        }
    }

    pub fn bind_params(
        &mut self,
        decl: &Rc<FuncDecl>,
        nf: &mut Frame,
        mut args: Vec<Value>,
        named: Vec<(Name, Value)>,
        disp: &str,
        caller_file: &Rc<str>,
        line: u32,
        strict: bool,
    ) -> R<()> {
        let np = decl.params.len();
        let has_variadic = decl.params.last().map(|p| p.variadic).unwrap_or(false);
        let mut variadic_named: Vec<(Name, Value)> = Vec::new();
        let passed = args.len();
        if !named.is_empty() {
            for (n, v) in named {
                match decl.params.iter().position(|p| p.name == n && !p.variadic) {
                    Some(i) => {
                        while args.len() <= i {
                            args.push(Value::Undef);
                        }
                        if !args[i].is_undef() {
                            let msg = format!("Named parameter ${} overwrites previous argument", n);
                            return Err(self.error(&msg));
                        }
                        args[i] = v;
                    }
                    None => {
                        if has_variadic {
                            variadic_named.push((n, v));
                        } else {
                            let msg = format!("Unknown named parameter ${}", n);
                            return Err(self.error(&msg));
                        }
                    }
                }
            }
        }
        nf.num_args = args.len();
        let saved_line = self.cur_line;
        let mut args_iter = args.into_iter();
        for (i, p) in decl.params.iter().enumerate() {
            if p.variadic {
                let mut arr = PArray::new();
                for v in args_iter.by_ref() {
                    let v = if p.by_ref {
                        match v {
                            Value::Ref(_) => v,
                            other => Value::Ref(Rc::new(RefCell::new(other))),
                        }
                    } else {
                        let v = v.into_deref();
                        match &p.ty {
                            Some(t) => {
                                self.cur_line = decl.line;
                                match self.coerce_type(&v, t, strict, nf.class.as_ref(), nf.static_class.as_ref())? {
                                    Some(c) => c,
                                    None => {
                                        let msg = format!(
                                            "{}(): Argument #{} must be of type {}, {} given, called in {} on line {}",
                                            disp,
                                            arr.len() + i + 1,
                                            type_to_string(t),
                                            type_name_given(&v),
                                            caller_file,
                                            line
                                        );
                                        self.cur_line = line;
                                        return Err(self.type_error(&msg));
                                    }
                                }
                            }
                            None => v,
                        }
                    };
                    arr.push(v);
                }
                for (n, v) in variadic_named.drain(..) {
                    arr.set(Key::Str(Rc::new(n.as_bytes().to_vec())), v.into_deref());
                }
                nf.slots[p.slot as usize] = Value::arr(arr);
                break;
            }
            let a = args_iter.next();
            match a {
                Some(v) if !v.is_undef() => {
                    if p.by_ref {
                        nf.slots[p.slot as usize] = match v {
                            Value::Ref(_) => v,
                            other => Value::Ref(Rc::new(RefCell::new(other))),
                        };
                        if let Some(t) = &p.ty {
                            if let Value::Ref(r) = &nf.slots[p.slot as usize] {
                                let inner = r.borrow().clone();
                                self.cur_line = decl.line;
                                match self.coerce_type(&inner, t, strict, nf.class.as_ref(), nf.static_class.as_ref())? {
                                    Some(c) => *r.borrow_mut() = c,
                                    None => {
                                        let msg = format!(
                                            "{}(): Argument #{} (${}) must be of type {}, {} given, called in {} on line {}",
                                            disp,
                                            i + 1,
                                            p.name,
                                            type_to_string(t),
                                            type_name_given(&inner),
                                            caller_file,
                                            line
                                        );
                                        self.cur_line = line;
                                        return Err(self.type_error(&msg));
                                    }
                                }
                            }
                        }
                    } else {
                        let v = v.into_deref();
                        let v = match &p.ty {
                            Some(t) => {
                                self.cur_line = decl.line;
                                match self.coerce_type(&v, t, strict, nf.class.as_ref(), nf.static_class.as_ref())? {
                                    Some(c) => c,
                                    None => {
                                        // null default makes type implicitly nullable
                                        let implicit_null = v.is_null() && matches!(&p.default, Some(Expr { kind: ExprKind::Lit(Value::Null), .. }));
                                        if implicit_null {
                                            Value::Null
                                        } else {
                                            let msg = format!(
                                                "{}(): Argument #{} (${}) must be of type {}, {} given, called in {} on line {}",
                                                disp,
                                                i + 1,
                                                p.name,
                                                type_to_string(t),
                                                type_name_given(&v),
                                                caller_file,
                                                line
                                            );
                                            self.cur_line = line;
                                            return Err(self.type_error(&msg));
                                        }
                                    }
                                }
                            }
                            None => v,
                        };
                        nf.slots[p.slot as usize] = v;
                    }
                }
                _ => {
                    match &p.default {
                        Some(d) => {
                            self.cur_line = decl.line;
                            let v = self.eval(nf, d)?;
                            nf.slots[p.slot as usize] = if p.by_ref { Value::Ref(Rc::new(RefCell::new(v))) } else { v };
                        }
                        None => {
                            self.cur_line = line;
                            if a.is_some() || i < passed {
                                let msg = format!("{}(): Argument #{} (${}) not passed", disp, i + 1, p.name);
                                return Err(self.throw_err("ArgumentCountError", &msg));
                            }
                            let required = decl.params.iter().filter(|p| p.default.is_none() && !p.variadic).count();
                            let has_opt = decl.params.iter().any(|p| p.default.is_some() || p.variadic);
                            let msg = format!(
                                "Too few arguments to function {}(), {} passed in {} on line {} and {} {} expected",
                                disp,
                                passed,
                                caller_file,
                                line,
                                if has_opt { "at least" } else { "exactly" },
                                required
                            );
                            return Err(self.throw_err("ArgumentCountError", &msg));
                        }
                    }
                }
            }
        }
        // extra args
        let extra: Vec<Value> = args_iter.map(|v| v.into_deref()).collect();
        if !extra.is_empty() {
            nf.extra_args = extra;
        }
        let _ = np;
        // constructor promotion
        if decl.params.iter().any(|p| p.promote.is_some()) {
            if let Some(this) = nf.this.clone() {
                for p in &decl.params {
                    if p.promote.is_some() {
                        let v = nf.slots[p.slot as usize].deref();
                        let cls = nf.class.clone();
                        self.init_promoted(&this, &p.name, v, cls.as_ref())?;
                    }
                }
            }
        }
        self.cur_line = saved_line;
        Ok(())
    }

    /// returns Some(coerced) if value acceptable for type
    pub fn coerce_type(&mut self, v: &Value, t: &TypeHint, strict: bool, self_cls: Option<&Rc<Class>>, static_cls: Option<&Rc<Class>>) -> R<Option<Value>> {
        if self.type_matches(v, t, self_cls, static_cls) {
            return Ok(Some(v.clone()));
        }
        // collect scalar types allowed
        let mut set = Vec::new();
        collect_scalar_types(t, &mut set);
        if set.is_empty() {
            return Ok(None);
        }
        let has = |n: &str| set.iter().any(|x| x == n);
        if strict {
            if let Value::Int(i) = v {
                if has("float") {
                    return Ok(Some(Value::Float(*i as f64)));
                }
            }
            return Ok(None);
        }
        match v {
            Value::Int(i) => {
                if has("float") {
                    return Ok(Some(Value::Float(*i as f64)));
                }
                if has("string") {
                    return Ok(Some(Value::string(i.to_string())));
                }
                if has("bool") {
                    return Ok(Some(Value::Bool(*i != 0)));
                }
            }
            Value::Float(f) => {
                if has("int") && f.is_finite() && f.fract() == 0.0 && float_fits_int(*f) {
                    return Ok(Some(Value::Int(*f as i64)));
                }
                if has("string") {
                    return Ok(Some(Value::string(fmt_float_prec(*f, self.precision))));
                }
                if has("int") && f.is_finite() && float_fits_int(*f) {
                    let msg = format!("Implicit conversion from float {} to int loses precision", fmt_float_repr(*f));
                    self.deprecated(&msg)?;
                    return Ok(Some(Value::Int(*f as i64)));
                }
                if has("bool") {
                    return Ok(Some(Value::Bool(*f != 0.0)));
                }
            }
            Value::Str(s) => {
                if has("int") || has("float") {
                    if let Some(n) = str_numeric(s) {
                        match n {
                            Num::Int(i) => {
                                if has("int") {
                                    return Ok(Some(Value::Int(i)));
                                }
                                return Ok(Some(Value::Float(i as f64)));
                            }
                            Num::Float(f) => {
                                if has("float") {
                                    return Ok(Some(Value::Float(f)));
                                }
                                if f.fract() == 0.0 && float_fits_int(f) {
                                    return Ok(Some(Value::Int(f as i64)));
                                }
                                if float_fits_int(f) {
                                    let msg = format!("Implicit conversion from float-string \"{}\" to int loses precision", String::from_utf8_lossy(s));
                                    self.deprecated(&msg)?;
                                    return Ok(Some(Value::Int(f as i64)));
                                }
                            }
                        }
                    }
                }
                if has("bool") {
                    return Ok(Some(Value::Bool(v.to_bool())));
                }
            }
            Value::Bool(b) => {
                if has("int") {
                    return Ok(Some(Value::Int(*b as i64)));
                }
                if has("float") {
                    return Ok(Some(Value::Float(*b as i64 as f64)));
                }
                if has("string") {
                    return Ok(Some(Value::str(if *b { "1" } else { "" })));
                }
            }
            Value::Object(o) => {
                if has("string") && o.class.magic.tostring.is_some() {
                    let o = o.clone();
                    let s = self.obj_to_string(&o)?;
                    return Ok(Some(Value::Str(s)));
                }
            }
            _ => {}
        }
        Ok(None)
    }

    pub fn type_matches(&mut self, v: &Value, t: &TypeHint, self_cls: Option<&Rc<Class>>, static_cls: Option<&Rc<Class>>) -> bool {
        match t {
            TypeHint::Simple(n) => match &**n {
                "mixed" => true,
                "int" => matches!(v, Value::Int(_)),
                "float" => matches!(v, Value::Float(_)),
                "string" => matches!(v, Value::Str(_)),
                "bool" => matches!(v, Value::Bool(_)),
                "false" => matches!(v, Value::Bool(false)),
                "true" => matches!(v, Value::Bool(true)),
                "null" | "void" => v.is_null(),
                "array" => matches!(v, Value::Array(_)),
                "object" => matches!(v, Value::Object(_)),
                "iterable" => match v {
                    Value::Array(_) => true,
                    Value::Object(o) => o.class.instance_of_name("traversable"),
                    _ => false,
                },
                "callable" => self.is_callable(v),
                "never" => false,
                "self" => match (v, self_cls) {
                    (Value::Object(o), Some(c)) => o.class.instance_of_name(&c.lname),
                    _ => false,
                },
                "static" => match (v, static_cls.or(self_cls)) {
                    (Value::Object(o), Some(c)) => o.class.instance_of_name(&c.lname),
                    _ => false,
                },
                "parent" => match (v, self_cls.and_then(|c| c.parent.clone())) {
                    (Value::Object(o), Some(c)) => o.class.instance_of_name(&c.lname),
                    _ => false,
                },
                cname => match v {
                    Value::Object(o) => {
                        let l = cname.to_ascii_lowercase();
                        o.class.instance_of_name(&l)
                    }
                    _ => false,
                },
            },
            TypeHint::Nullable(inner) => v.is_null() || self.type_matches(v, inner, self_cls, static_cls),
            TypeHint::Union(ts) => ts.iter().any(|t| self.type_matches(v, t, self_cls, static_cls)),
            TypeHint::Intersection(ts) => ts.iter().all(|t| self.type_matches(v, t, self_cls, static_cls)),
        }
    }

    // ---------------- method calls ----------------
    pub fn eval_method_call(&mut self, f: &mut Frame, b: Value, name: &MemberName, args: &[Arg], line: u32) -> R<Value> {
        let n = self.member_name(f, name)?;
        let o = match b {
            Value::Object(o) => o,
            other => {
                let msg = format!("Call to a member function {}() on {}", String::from_utf8_lossy(&n), other.type_name_ex_for_call());
                return Err(self.error(&msg));
            }
        };
        let ln = n.to_ascii_lowercase();
        let lns = String::from_utf8_lossy(&ln).to_string();
        // Closure special methods
        let m = o.class.find_method(&lns).cloned();
        let m = match m {
            Some(m) => {
                // visibility
                if m.vis != Visibility::Public && !self.can_access_method(&m, f.class.as_ref()) {
                    if let Some(call) = o.class.magic.call.clone() {
                        let (av, _) = self.eval_args(f, args, &|_, _| false)?;
                        let arr = Value::arr(PArray::from_values(av));
                        self.cur_line = line;
                        return self.call_method_obj_line(&o, &call, vec![Value::Str(n.clone()), arr], line);
                    }
                    let msg = format!(
                        "Call to {} method {}::{}() from {}",
                        vis_name(m.vis),
                        o.class.name,
                        m.name,
                        scope_desc(f.class.as_ref())
                    );
                    return Err(self.error(&msg));
                }
                m
            }
            None => {
                if crate::builtins::classes::is_closure(&o) && (lns == "call" || lns == "bindto" || lns == "__invoke") {
                    // handled by builtin methods on Closure class
                    let m = o.class.find_method(&lns).cloned();
                    if let Some(m) = m {
                        m
                    } else {
                        return Err(self.error("Closure method missing"));
                    }
                } else if let Some(call) = o.class.magic.call.clone() {
                    let (av, _) = self.eval_args(f, args, &|_, _| false)?;
                    let arr = Value::arr(PArray::from_values(av));
                    self.cur_line = line;
                    return self.call_method_obj_line(&o, &call, vec![Value::Str(n.clone()), arr], line);
                } else {
                    let msg = format!("Call to undefined method {}::{}()", o.class.name, String::from_utf8_lossy(&n));
                    return Err(self.error(&msg));
                }
            }
        };
        if m.is_static {
            let cls = o.class.clone();
            return self.invoke_method(f, &m, None, &cls, args, line);
        }
        let cls = o.class.clone();
        self.invoke_method(f, &m, Some(o), &cls, args, line)
    }

    pub fn can_access_method(&self, m: &Method, scope: Option<&Rc<Class>>) -> bool {
        match m.vis {
            Visibility::Public => true,
            Visibility::Private => match scope {
                Some(s) => {
                    let mc = m.class.upgrade();
                    match mc {
                        Some(mc) => Rc::ptr_eq(&mc, s) || mc.lname == s.lname,
                        None => false,
                    }
                }
                None => false,
            },
            Visibility::Protected => match scope {
                Some(s) => {
                    let mc = match m.class.upgrade() {
                        Some(c) => c,
                        None => return false,
                    };
                    let root = m.proto.clone().unwrap_or(mc.lname.clone());
                    s.is_subclass_of(&mc) || mc.is_subclass_of(s) || s.instance_of_name(&root) || {
                        // scope shares a common ancestor declaring the method
                        false
                    }
                }
                None => false,
            },
        }
    }

    /// invoke a method with argument expressions
    pub fn invoke_method(&mut self, f: &mut Frame, m: &Rc<Method>, this: Option<Obj>, static_cls: &Rc<Class>, args: &[Arg], line: u32) -> R<Value> {
        match &m.imp {
            MethodImpl::User(decl) => {
                let d2 = decl.clone();
                let (av, named) = self.eval_args(f, args, &|i, n| param_by_ref(&d2, i, n))?;
                self.cur_line = line;
                let scope = m.scope_class();
                let ctx = CallCtx {
                    this: if m.is_static { None } else { this },
                    class: Some(scope.clone()),
                    static_class: Some(static_cls.clone()),
                    closure: None,
                    disp_class: Some(m.decl_class_name.clone()),
                    call_type: if m.is_static { "::" } else { "->" },
                    bound_vars: None,
                };
                self.call_user(decl, av, named, ctx, line)
            }
            MethodImpl::Builtin(bf) => {
                let bp = m.builtin_params;
                let (mut av, named) = self.eval_args(f, args, &|i, _| bp.map(|p| p.get(i).map(|s| s.starts_with('&')).unwrap_or(false)).unwrap_or(false))?;
                if !named.is_empty() {
                    if let Some(params) = m.builtin_params {
                        for (n, v) in named {
                            if let Some(i) = params.iter().position(|p| p.trim_start_matches('&') == &*n) {
                                while av.len() <= i {
                                    av.push(Value::Undef);
                                }
                                av[i] = v;
                            } else {
                                let msg = format!("Unknown named parameter ${}", n);
                                return Err(self.error(&msg));
                            }
                        }
                    } else {
                        for (_, v) in named {
                            av.push(v);
                        }
                    }
                }
                self.cur_line = line;
                self.call_builtin_method(m, *bf, this.as_ref(), av, static_cls, line)
            }
        }
    }

    pub fn call_builtin_method(&mut self, m: &Rc<Method>, bf: BuiltinMethod, this: Option<&Obj>, mut av: Vec<Value>, cls: &Rc<Class>, line: u32) -> R<Value> {
        self.call_stack.push(CallInfo {
            func: m.name.clone(),
            class: Some(m.decl_class_name.clone()),
            call_type: if this.is_some() { "->" } else { "::" },
            file: self.cur_file.clone(),
            line,
            frame: std::ptr::null(),
            bargs: &av as *const Vec<Value>,
            internal: false,
            obj: this.cloned(),
        });
        let r = bf(self, this, &mut av, cls);
        self.call_stack.pop();
        self.cur_line = line;
        r
    }

    /// call a method with already evaluated args
    pub fn call_method_obj(&mut self, o: &Obj, m: &Rc<Method>, args: Vec<Value>) -> R<Value> {
        let line = self.cur_line;
        self.call_method_obj_line(o, m, args, line)
    }

    pub fn call_method_obj_line(&mut self, o: &Obj, m: &Rc<Method>, args: Vec<Value>, line: u32) -> R<Value> {
        match &m.imp {
            MethodImpl::User(decl) => {
                let scope = m.scope_class();
                let ctx = CallCtx {
                    this: if m.is_static { None } else { Some(o.clone()) },
                    class: Some(scope),
                    static_class: Some(o.class.clone()),
                    closure: None,
                    disp_class: Some(m.decl_class_name.clone()),
                    call_type: if m.is_static { "::" } else { "->" },
                    bound_vars: None,
                };
                self.call_user(decl, args, Vec::new(), ctx, line)
            }
            MethodImpl::Builtin(bf) => {
                let cls = o.class.clone();
                self.call_builtin_method(m, *bf, Some(o), args, &cls, line)
            }
        }
    }

    pub fn call_static_method(&mut self, cls: &Rc<Class>, m: &Rc<Method>, args: Vec<Value>, this: Option<Obj>) -> R<Value> {
        let line = self.cur_line;
        match &m.imp {
            MethodImpl::User(decl) => {
                let scope = m.scope_class();
                let ctx = CallCtx {
                    this: if m.is_static { None } else { this },
                    class: Some(scope),
                    static_class: Some(cls.clone()),
                    closure: None,
                    disp_class: Some(m.decl_class_name.clone()),
                    call_type: if m.is_static { "::" } else { "->" },
                    bound_vars: None,
                };
                self.call_user(decl, args, Vec::new(), ctx, line)
            }
            MethodImpl::Builtin(bf) => self.call_builtin_method(m, *bf, this.as_ref(), args, cls, line),
        }
    }

    pub fn call_method_name(&mut self, o: &Obj, name: &str, args: Vec<Value>) -> R<Value> {
        let l = name.to_ascii_lowercase();
        match o.class.find_method(&l).cloned() {
            Some(m) => self.call_method_obj(o, &m, args),
            None => {
                if let Some(call) = o.class.magic.call.clone() {
                    let arr = Value::arr(PArray::from_values(args));
                    return self.call_method_obj(o, &call, vec![Value::str(name), arr]);
                }
                let msg = format!("Call to undefined method {}::{}()", o.class.name, name);
                Err(self.error(&msg))
            }
        }
    }

    pub fn eval_static_call(&mut self, f: &mut Frame, cref: &ClassRef, name: &MemberName, args: &[Arg], line: u32) -> R<Value> {
        let n = self.member_name(f, name)?;
        let cls = self.resolve_class_ref(f, cref, true)?;
        let lns = String::from_utf8_lossy(&n.to_ascii_lowercase()).to_string();
        let forwarding = matches!(cref, ClassRef::SelfRef | ClassRef::Parent | ClassRef::Static);
        let m = match cls.find_method(&lns).cloned() {
            Some(m) => m,
            None => {
                // __callStatic or __call (when in object context)
                if let Some(this) = f.this.clone() {
                    if this.class.is_subclass_of(&cls) {
                        if let Some(call) = cls.magic.call.clone() {
                            let (av, _) = self.eval_args(f, args, &|_, _| false)?;
                            let arr = Value::arr(PArray::from_values(av));
                            return self.call_method_obj_line(&this, &call, vec![Value::Str(n.clone()), arr], line);
                        }
                    }
                }
                if let Some(cs) = cls.magic.callstatic.clone() {
                    let (av, _) = self.eval_args(f, args, &|_, _| false)?;
                    let arr = Value::arr(PArray::from_values(av));
                    self.cur_line = line;
                    return self.call_static_method(&cls, &cs, vec![Value::Str(n.clone()), arr], None);
                }
                let msg = format!("Call to undefined method {}::{}()", cls.name, String::from_utf8_lossy(&n));
                return Err(self.error(&msg));
            }
        };
        if m.vis != Visibility::Public && !self.can_access_method(&m, f.class.as_ref()) {
            if let Some(cs) = cls.magic.callstatic.clone() {
                let (av, _) = self.eval_args(f, args, &|_, _| false)?;
                let arr = Value::arr(PArray::from_values(av));
                return self.call_static_method(&cls, &cs, vec![Value::Str(n.clone()), arr], None);
            }
            let msg = format!("Call to {} method {}::{}() from {}", vis_name(m.vis), cls.name, m.name, scope_desc(f.class.as_ref()));
            return Err(self.error(&msg));
        }
        if m.is_abstract {
            let msg = format!("Cannot call abstract method {}::{}()", m.decl_class_name, m.name);
            return Err(self.error(&msg));
        }
        let static_cls = if forwarding { f.static_class.clone().unwrap_or(cls.clone()) } else { cls.clone() };
        if m.is_static {
            return self.invoke_method(f, &m, None, &static_cls, args, line);
        }
        // non-static method called statically: allowed if $this is compatible
        if let Some(this) = f.this.clone() {
            if this.class.is_subclass_of(&cls) {
                let sc = this.class.clone();
                return self.invoke_method(f, &m, Some(this), &sc, args, line);
            }
        }
        let msg = format!("Non-static method {}::{}() cannot be called statically", m.decl_class_name, m.name);
        Err(self.error(&msg))
    }

    // ---------------- callable values ----------------
    pub fn call_value(&mut self, cv: &Value, args: Vec<Value>) -> R<Value> {
        self.call_value_named(cv, args, Vec::new())
    }

    pub fn call_value_named(&mut self, cv: &Value, args: Vec<Value>, named: Vec<(Name, Value)>) -> R<Value> {
        let line = self.cur_line;
        match cv {
            Value::Object(o) => {
                if crate::builtins::classes::is_closure(o) {
                    return crate::builtins::classes::call_closure(self, o, args, named, line);
                }
                if let Some(inv) = o.class.magic.invoke.clone() {
                    return self.call_method_obj(o, &inv, args);
                }
                Err(self.error("Object of type ".to_string().as_str()).into_err_obj_not_callable(o, self))
            }
            Value::Str(s) => {
                let st = String::from_utf8_lossy(s).to_string();
                if let Some(p) = st.find("::") {
                    let cn = &st[..p];
                    let mn = &st[p + 2..];
                    let cls = self.lookup_class(cn.as_bytes())?;
                    return self.call_class_method_by_name(&cls, mn, args, None, named);
                }
                let name = st.trim_start_matches('\\');
                match self.functions.get(&lc(name)).cloned() {
                    Some(Callable::User(d)) => self.call_user(&d, args, named, CallCtx::plain(), line),
                    Some(Callable::Builtin(def)) => {
                        let mut av = args;
                        for (i, a) in av.iter_mut().enumerate() {
                            if def.by_ref(i) {
                                if !matches!(a, Value::Ref(_)) {
                                    let v = std::mem::take(a);
                                    *a = Value::Ref(Rc::new(RefCell::new(v)));
                                }
                            }
                        }
                        self.call_builtin(def, av, named, line)
                    }
                    None => {
                        let msg = format!("Call to undefined function {}()", name);
                        Err(self.error(&msg))
                    }
                }
            }
            Value::Array(a) if a.len() == 2 => {
                let t = a.get_int(0).cloned().unwrap_or(Value::Null).deref();
                let m = a.get_int(1).cloned().unwrap_or(Value::Null).deref();
                let mn = match &m {
                    Value::Str(s) => String::from_utf8_lossy(s).to_string(),
                    _ => return Err(self.error("Array callback must have exactly two elements")),
                };
                match t {
                    Value::Object(o) => {
                        let mut mname = mn.as_str();
                        let mut cls = o.class.clone();
                        if let Some(rest) = mname.strip_prefix("parent::") {
                            mname = rest;
                            cls = cls.parent.clone().unwrap_or(cls);
                        }
                        let l = mname.to_ascii_lowercase();
                        match cls.find_method(&l).cloned() {
                            Some(m) => {
                                if m.is_static {
                                    let sc = o.class.clone();
                                    self.call_static_method(&sc, &m, args, None)
                                } else {
                                    match &m.imp {
                                        MethodImpl::User(decl) => {
                                            let ctx = CallCtx {
                                                this: Some(o.clone()),
                                                class: Some(m.scope_class()),
                                                static_class: Some(o.class.clone()),
                                                closure: None,
                                                disp_class: Some(m.decl_class_name.clone()),
                                                call_type: "->",
                                                bound_vars: None,
                                            };
                                            self.call_user(decl, args, named, ctx, line)
                                        }
                                        _ => self.call_method_obj(&o, &m, args),
                                    }
                                }
                            }
                            None => {
                                if let Some(call) = o.class.magic.call.clone() {
                                    let arr = Value::arr(PArray::from_values(args));
                                    return self.call_method_obj(&o, &call, vec![Value::str(mname), arr]);
                                }
                                let msg = format!("Call to undefined method {}::{}()", o.class.name, mname);
                                Err(self.error(&msg))
                            }
                        }
                    }
                    Value::Str(cn) => {
                        let cls = self.lookup_class(&cn)?;
                        let mut mname = mn.as_str();
                        let mut c2 = cls.clone();
                        if let Some(rest) = mname.strip_prefix("parent::") {
                            mname = rest;
                            c2 = cls.parent.clone().unwrap_or(cls.clone());
                        }
                        let this = self.current_this_compatible(&c2);
                        self.call_class_method_by_name(&c2, mname, args, this, named)
                    }
                    _ => Err(self.error("Array callback must have exactly two elements")),
                }
            }
            _ => {
                let msg = "Value not callable".to_string();
                Err(self.error(&msg))
            }
        }
    }

    fn current_this_compatible(&self, cls: &Rc<Class>) -> Option<Obj> {
        for ci in self.call_stack.iter().rev() {
            if !ci.frame.is_null() {
                let fr = unsafe { &*ci.frame };
                if let Some(t) = &fr.this {
                    if t.class.is_subclass_of(cls) {
                        return Some(t.clone());
                    }
                }
                return None;
            }
        }
        None
    }

    pub fn call_class_method_by_name(&mut self, cls: &Rc<Class>, mn: &str, args: Vec<Value>, this: Option<Obj>, named: Vec<(Name, Value)>) -> R<Value> {
        let l = mn.to_ascii_lowercase();
        match cls.find_method(&l).cloned() {
            Some(m) => {
                if !m.is_static && this.is_none() {
                    let msg = format!("Non-static method {}::{}() cannot be called statically", m.decl_class_name, m.name);
                    return Err(self.error(&msg));
                }
                if let MethodImpl::User(decl) = &m.imp {
                    let line = self.cur_line;
                    let ctx = CallCtx {
                        this: if m.is_static { None } else { this },
                        class: Some(m.scope_class()),
                        static_class: Some(cls.clone()),
                        closure: None,
                        disp_class: Some(m.decl_class_name.clone()),
                        call_type: if m.is_static { "::" } else { "->" },
                        bound_vars: None,
                    };
                    return self.call_user(decl, args, named, ctx, line);
                }
                self.call_static_method(cls, &m, args, this)
            }
            None => {
                if let Some(cs) = cls.magic.callstatic.clone() {
                    let arr = Value::arr(PArray::from_values(args));
                    return self.call_static_method(cls, &cs, vec![Value::str(mn), arr], None);
                }
                let msg = format!("Call to undefined method {}::{}()", cls.name, mn);
                Err(self.error(&msg))
            }
        }
    }

    /// $f(...) where $f is a value
    pub fn call_value_with_args(&mut self, f: &mut Frame, cv: &Value, args: &[Arg], line: u32) -> R<Value> {
        // determine by-ref params if possible
        match cv {
            Value::Object(o) if crate::builtins::classes::is_closure(o) => {
                let decl = crate::builtins::classes::closure_decl(o);
                let (av, named) = match &decl {
                    Some(d) => {
                        let d2 = d.clone();
                        self.eval_args(f, args, &|i, n| param_by_ref(&d2, i, n))?
                    }
                    None => {
                        let bdef = crate::builtins::classes::closure_builtin(o);
                        match bdef {
                            Some(def) => self.eval_args(f, args, &|i, n| builtin_by_ref(def, i, n))?,
                            None => self.eval_args(f, args, &|_, _| false)?,
                        }
                    }
                };
                self.cur_line = line;
                crate::builtins::classes::call_closure(self, o, av, named, line)
            }
            Value::Str(s) => {
                let st = String::from_utf8_lossy(s).to_string();
                if !st.contains("::") {
                    let name = st.trim_start_matches('\\');
                    match self.functions.get(&lc(name)).cloned() {
                        Some(Callable::User(d)) => {
                            let d2 = d.clone();
                            let (av, named) = self.eval_args(f, args, &|i, n| param_by_ref(&d2, i, n))?;
                            self.cur_line = line;
                            return self.call_user(&d, av, named, CallCtx::plain(), line);
                        }
                        Some(Callable::Builtin(def)) => {
                            if let Some(r) = self.frame_builtin(f, def, args, line)? {
                                return Ok(r);
                            }
                            let (av, named) = self.eval_args(f, args, &|i, n| builtin_by_ref(def, i, n))?;
                            self.cur_line = line;
                            return self.call_builtin(def, av, named, line);
                        }
                        None => {
                            let msg = format!("Call to undefined function {}()", name);
                            return Err(self.error(&msg));
                        }
                    }
                }
                let (av, named) = self.eval_args(f, args, &|_, _| false)?;
                self.cur_line = line;
                self.call_value_named(cv, av, named)
            }
            Value::Object(o) => {
                if let Some(inv) = o.class.magic.invoke.clone() {
                    let cls = o.class.clone();
                    return self.invoke_method(f, &inv, Some(o.clone()), &cls, args, line);
                }
                Err(self.error("Object of type ".to_string().as_str()).into_err_obj_not_callable(o, self))
            }
            Value::Array(_) => {
                let (av, named) = self.eval_args(f, args, &|_, _| false)?;
                self.cur_line = line;
                if !self.is_callable(cv) {
                    let a = cv.as_array().unwrap();
                    if a.len() == 2 {
                        if let (Some(t), Some(Value::Str(m))) = (a.get_int(0).map(|v| v.deref()), a.get_int(1).map(|v| v.deref())) {
                            let cn = match &t {
                                Value::Object(o) => o.class.name.to_string(),
                                Value::Str(s) => String::from_utf8_lossy(s).to_string(),
                                _ => String::new(),
                            };
                            if !cn.is_empty() {
                                if let Ok(c) = self.lookup_class(cn.as_bytes()) {
                                    let msg = format!("Call to undefined method {}::{}()", c.name, String::from_utf8_lossy(&m));
                                    return Err(self.error(&msg));
                                }
                            }
                        }
                    }
                    return Err(self.error("Array callback must have exactly two elements"));
                }
                self.call_value_named(cv, av, named)
            }
            _ => {
                let msg = "Value not callable".to_string();
                Err(self.error(&msg))
            }
        }
    }

    pub fn is_callable(&mut self, v: &Value) -> bool {
        match v {
            Value::Str(s) => {
                let st = String::from_utf8_lossy(s).to_string();
                if let Some(p) = st.find("::") {
                    let cn = &st[..p];
                    let mn = st[p + 2..].to_ascii_lowercase();
                    match self.find_class_autoload(cn.as_bytes()) {
                        Some(c) => c.find_method(&mn).is_some() || c.magic.callstatic.is_some(),
                        None => false,
                    }
                } else {
                    self.functions.contains_key(&lc(st.trim_start_matches('\\')))
                }
            }
            Value::Array(a) => {
                if a.len() != 2 {
                    return false;
                }
                let t = a.get_int(0).map(|v| v.deref());
                let m = a.get_int(1).map(|v| v.deref());
                match (t, m) {
                    (Some(Value::Object(o)), Some(Value::Str(m))) => {
                        let l = String::from_utf8_lossy(&m.to_ascii_lowercase()).to_string();
                        let l = l.strip_prefix("parent::").unwrap_or(&l).to_string();
                        o.class.find_method(&l).is_some() || o.class.magic.call.is_some()
                    }
                    (Some(Value::Str(c)), Some(Value::Str(m))) => match self.find_class_autoload(&c) {
                        Some(cls) => {
                            let l = String::from_utf8_lossy(&m.to_ascii_lowercase()).to_string();
                            let l = l.strip_prefix("parent::").unwrap_or(&l).to_string();
                            cls.find_method(&l).is_some() || cls.magic.callstatic.is_some()
                        }
                        None => false,
                    },
                    _ => false,
                }
            }
            Value::Object(o) => crate::builtins::classes::is_closure(o) || o.class.magic.invoke.is_some(),
            Value::Ref(r) => {
                let v = r.borrow().clone();
                self.is_callable(&v)
            }
            _ => false,
        }
    }

    pub fn callable_error(&mut self, v: &Value) -> String {
        match v {
            Value::Str(s) => {
                let st = String::from_utf8_lossy(s).to_string();
                if let Some(p) = st.find("::") {
                    let cn = &st[..p];
                    match self.find_class_autoload(cn.as_bytes()) {
                        Some(c) => format!("class {} does not have a method \"{}\"", c.name, &st[p + 2..]),
                        None => format!("class \"{}\" not found", cn),
                    }
                } else {
                    format!("function \"{}\" not found or invalid function name", st)
                }
            }
            Value::Array(a) => {
                if a.len() != 2 {
                    return "array callback must have exactly two members".to_string();
                }
                let t = a.get_int(0).map(|v| v.deref());
                let m = a.get_int(1).map(|v| v.deref());
                match (t, m) {
                    (Some(Value::Object(o)), Some(Value::Str(m))) => format!("class {} does not have a method \"{}\"", o.class.name, String::from_utf8_lossy(&m)),
                    (Some(Value::Str(c)), Some(Value::Str(m))) => match self.find_class_autoload(&c) {
                        Some(cls) => format!("class {} does not have a method \"{}\"", cls.name, String::from_utf8_lossy(&m)),
                        None => format!("class \"{}\" not found", String::from_utf8_lossy(&c)),
                    },
                    _ => "first array member is not a valid class name or object".to_string(),
                }
            }
            _ => "no array or string given".to_string(),
        }
    }

    /// builtins needing access to the caller frame
    pub fn frame_builtin(&mut self, f: &mut Frame, def: &'static BuiltinDef, args: &[Arg], line: u32) -> R<Option<Value>> {
        match def.name {
            "compact" => {
                let (av, _) = self.eval_args(f, args, &|_, _| false)?;
                self.cur_line = line;
                let mut out = PArray::new();
                fn add(it: &mut Interp, f: &Frame, v: &Value, out: &mut PArray) -> R<()> {
                    match v {
                        Value::Array(a) => {
                            for (_, x) in a.iter() {
                                add(it, f, &x.deref(), out)?;
                            }
                        }
                        _ => {
                            let name = it.to_str(v)?;
                            if name.as_slice() == b"this" {
                                if let Some(t) = &f.this {
                                    out.set(Key::Str(name.clone()), Value::Object(t.clone()));
                                }
                                return Ok(());
                            }
                            match f.find_slot(&name) {
                                Some(i) if !f.slots[i].is_undef() && !matches!(&f.slots[i], Value::Ref(r) if r.borrow().is_undef()) => {
                                    out.set(Key::from_pstr(&name), f.slots[i].deref());
                                }
                                _ => {
                                    it.warn(&format!("compact(): Undefined variable ${}", String::from_utf8_lossy(&name)))?;
                                }
                            }
                        }
                    }
                    Ok(())
                }
                for v in &av {
                    add(self, f, v, &mut out)?;
                }
                Ok(Some(Value::arr(out)))
            }
            "extract" => {
                let (av, _) = self.eval_args(f, args, &|i, _| i == 0)?;
                self.cur_line = line;
                let arr = match av.first().map(|v| v.deref()) {
                    Some(Value::Array(a)) => a,
                    Some(other) => {
                        let msg = format!("extract(): Argument #1 ($array) must be of type array, {} given", other.type_name());
                        return Err(self.type_error(&msg));
                    }
                    None => return Err(self.throw_err("ArgumentCountError", "extract() expects at least 1 argument, 0 given")),
                };
                let flags = av.get(1).map(|v| v.to_int()).unwrap_or(0);
                let prefix = match av.get(2) {
                    Some(v) => self.to_str(v)?.to_vec(),
                    None => Vec::new(),
                };
                let refs = flags & 256 != 0;
                let mode = flags & 0xff;
                let mut count = 0;
                for (k, v) in arr.iter() {
                    let name = match k {
                        Key::Str(s) => s.to_vec(),
                        Key::Int(i) => {
                            if mode == 2 || mode == 3 {
                                i.to_string().into_bytes()
                            } else {
                                continue;
                            }
                        }
                    };
                    let exists = f.find_slot(&name).map(|i| !f.slots[i].is_undef()).unwrap_or(false);
                    let final_name = match mode {
                        0 => name.clone(),
                        1 => {
                            if exists {
                                continue;
                            }
                            name.clone()
                        }
                        2 => {
                            if exists {
                                let mut p = prefix.clone();
                                p.push(b'_');
                                p.extend_from_slice(&name);
                                p
                            } else {
                                name.clone()
                            }
                        }
                        3 => {
                            let mut p = prefix.clone();
                            p.push(b'_');
                            p.extend_from_slice(&name);
                            p
                        }
                        6 => {
                            if !exists {
                                continue;
                            }
                            name.clone()
                        }
                        _ => name.clone(),
                    };
                    if !is_valid_var_name(&final_name) || final_name == b"this" {
                        continue;
                    }
                    let i = f.slot_for(&final_name);
                    if refs {
                        if let Some(Value::Ref(src)) = av.first() {
                            let mut b = src.borrow_mut();
                            if let Value::Array(a) = &mut *b {
                                let arr = Rc::make_mut(a);
                                if let Some(slot) = arr.get_mut(k) {
                                    let r = lval::wrap_ref(slot);
                                    drop(b);
                                    f.slots[i] = Value::Ref(r);
                                    count += 1;
                                    continue;
                                }
                            }
                        }
                    }
                    match &mut f.slots[i] {
                        Value::Ref(r) => *r.borrow_mut() = v.deref(),
                        s => *s = v.deref(),
                    }
                    count += 1;
                }
                Ok(Some(Value::Int(count)))
            }
            "get_defined_vars" => {
                let mut out = PArray::new();
                for (i, n) in f.names.iter().enumerate() {
                    if let Some(v) = f.slots.get(i) {
                        if v.is_undef() {
                            continue;
                        }
                        if let Value::Ref(r) = v {
                            if r.borrow().is_undef() {
                                continue;
                            }
                        }
                        out.set(Key::from_str_bytes(n.as_bytes()), v.deref());
                    }
                }
                Ok(Some(Value::arr(out)))
            }
            "func_get_args" => {
                let mut out = PArray::new();
                if let Some(d) = &f.func {
                    let np = d.params.iter().filter(|p| !p.variadic).count();
                    for (i, p) in d.params.iter().enumerate() {
                        if p.variadic {
                            if let Value::Array(a) = &f.slots[p.slot as usize] {
                                for (_, v) in a.iter() {
                                    out.push(v.deref());
                                }
                            }
                            break;
                        }
                        if i < f.num_args {
                            out.push(f.slots[p.slot as usize].deref());
                        }
                    }
                    let _ = np;
                    for v in &f.extra_args {
                        out.push(v.clone());
                    }
                } else {
                    return Err(self.error("func_get_args() cannot be called from the global scope"));
                }
                Ok(Some(Value::arr(out)))
            }
            "func_num_args" => {
                if f.func.is_none() {
                    return Err(self.error("func_num_args() must be called from a function context"));
                }
                Ok(Some(Value::Int(f.num_args.max(f.extra_args.len() + f.func.as_ref().map(|d| d.params.len()).unwrap_or(0).min(f.num_args)) as i64)))
            }
            "func_get_arg" => {
                let (av, _) = self.eval_args(f, args, &|_, _| false)?;
                let n = av.first().map(|v| v.to_int()).unwrap_or(0);
                if let Some(d) = &f.func {
                    let np = d.params.len();
                    if (n as usize) < np.min(f.num_args) {
                        return Ok(Some(f.slots[d.params[n as usize].slot as usize].deref()));
                    }
                    let ei = n as usize - np;
                    if let Some(v) = f.extra_args.get(ei) {
                        return Ok(Some(v.clone()));
                    }
                }
                Err(self.value_error("func_get_arg(): Argument #1 ($position) must be less than the number of the arguments passed to the currently executed function"))
            }
            "get_called_class" => Ok(Some(match &f.static_class {
                Some(c) => Value::str(&c.name),
                None => Value::Bool(false),
            })),
            "get_class" if args.is_empty() => Ok(Some(match &f.class {
                Some(c) => Value::str(&c.name),
                None => {
                    return Err(self.error("get_class() without arguments must be called from within a class"));
                }
            })),
            "get_parent_class" if args.is_empty() => Ok(Some(match f.class.as_ref().and_then(|c| c.parent.clone()) {
                Some(p) => Value::str(&p.name),
                None => Value::Bool(false),
            })),
            "get_object_vars" => {
                let (av, _) = self.eval_args(f, args, &|_, _| false)?;
                match av.first() {
                    Some(Value::Object(o)) => {
                        let scope = f.class.clone();
                        let props = self.visible_props(o, scope.as_ref());
                        let mut out = PArray::new();
                        for (k, v) in props {
                            out.set(Key::from_str_bytes(&k), v.deref());
                        }
                        Ok(Some(Value::arr(out)))
                    }
                    Some(other) => {
                        let msg = format!("get_object_vars(): Argument #1 ($object) must be of type object, {} given", other.type_name());
                        Err(self.type_error(&msg))
                    }
                    None => Err(self.throw_err("ArgumentCountError", "get_object_vars() expects exactly 1 argument, 0 given")),
                }
            }
            "array_map" | "usort" | "uasort" | "uksort" | "array_filter" | "array_walk" | "call_user_func" | "call_user_func_array" | "array_reduce" | "is_callable" | "method_exists" | "property_exists" | "get_class_methods" => {
                // need scope for callable resolution of private methods: record scope
                Ok(None)
            }
            _ => Ok(None),
        }
    }
}

pub fn param_by_ref(d: &FuncDecl, i: usize, name: Option<&str>) -> bool {
    if let Some(n) = name {
        return d.params.iter().any(|p| &*p.name == n && p.by_ref);
    }
    if i < d.params.len() {
        d.params[i].by_ref
    } else {
        d.params.last().map(|p| p.variadic && p.by_ref).unwrap_or(false)
    }
}

pub fn builtin_by_ref(def: &BuiltinDef, i: usize, name: Option<&str>) -> bool {
    if let Some(n) = name {
        return def.params.iter().any(|p| p.name == n && p.by_ref);
    }
    def.by_ref(i)
}

pub fn type_name_given(v: &Value) -> String {
    match v {
        Value::Object(o) => o.class.name.to_string(),
        _ => v.type_name().to_string(),
    }
}

pub fn vis_name(v: Visibility) -> &'static str {
    match v {
        Visibility::Public => "public",
        Visibility::Protected => "protected",
        Visibility::Private => "private",
    }
}

pub fn scope_desc(c: Option<&Rc<Class>>) -> String {
    match c {
        Some(c) => format!("scope {}", c.name),
        None => "global scope".to_string(),
    }
}

fn collect_scalar_types(t: &TypeHint, out: &mut Vec<String>) {
    match t {
        TypeHint::Simple(n) => match &**n {
            "int" | "float" | "string" | "bool" => out.push(n.to_string()),
            "mixed" => {}
            _ => {}
        },
        TypeHint::Nullable(i) => collect_scalar_types(i, out),
        TypeHint::Union(ts) => {
            for t in ts {
                collect_scalar_types(t, out);
            }
        }
        TypeHint::Intersection(_) => {}
    }
}

pub fn is_valid_var_name(n: &[u8]) -> bool {
    if n.is_empty() {
        return false;
    }
    let c = n[0];
    if !(c.is_ascii_alphabetic() || c == b'_' || c >= 0x80) {
        return false;
    }
    n.iter().all(|&c| c.is_ascii_alphanumeric() || c == b'_' || c >= 0x80)
}

trait NotCallable {
    fn into_err_obj_not_callable(self, o: &Obj, it: &mut Interp) -> Flow;
}
impl NotCallable for Flow {
    fn into_err_obj_not_callable(self, o: &Obj, it: &mut Interp) -> Flow {
        drop(self);
        let msg = format!("Object of type {} is not callable", o.class.name);
        it.error(&msg)
    }
}

impl Value {
    pub fn type_name_ex_for_call(&self) -> String {
        match self {
            Value::Object(o) => o.class.name.to_string(),
            _ => self.type_name().to_string(),
        }
    }
}
