cd /workspace/src/interp && cat > props.rs <<'EOF'
use super::*;
use crate::array::{Key, PArray};
use crate::ast::*;
use calls::type_to_string;

pub enum PLook {
    Declared(Rc<PropInfo>),
    Dynamic,
    Wrong(Rc<PropInfo>),
}

const G_GET: u8 = 1;
const G_SET: u8 = 2;
const G_ISSET: u8 = 4;
const G_UNSET: u8 = 8;
const G_HOOK: u8 = 16;

fn same_class(a: &Class, name: &str) -> bool {
    a.name.eq_ignore_ascii_case(name)
}

impl Interp {
    pub fn lookup_prop(&self, cls: &Rc<Class>, name: &str, scope: Option<&Rc<Class>>) -> PLook {
        match cls.prop_infos.get(name) {
            Some(info) => {
                if info.vis == Visibility::Public && !info.changed {
                    return PLook::Declared(info.clone());
                }
                if let Some(s) = scope {
                    if same_class(s, &info.decl_class) {
                        return PLook::Declared(info.clone());
                    }
                    if info.changed || info.vis == Visibility::Private {
                        // scope's own private property shadowed
                        if !Rc::ptr_eq(s, cls) && cls.is_subclass_of(s) {
                            if let Some(p) = s.prop_infos.get(name) {
                                if p.vis == Visibility::Private && same_class(s, &p.decl_class) {
                                    return PLook::Declared(p.clone());
                                }
                            }
                        }
                    }
                    if info.vis == Visibility::Public {
                        return PLook::Declared(info.clone());
                    }
                }
                if info.vis == Visibility::Private {
                    if !same_class(cls, &info.decl_class) {
                        return PLook::Dynamic;
                    }
                    return PLook::Wrong(info.clone());
                }
                // protected
                if let Some(s) = scope {
                    if s.instance_of_name(&info.decl_class.to_ascii_lowercase()) || cls.is_subclass_of(s) || s.is_subclass_of(cls) {
                        return PLook::Declared(info.clone());
                    }
                    // common root
                    if let Some(dc) = self.classes.get(&lc(&info.decl_class)) {
                        if s.is_subclass_of(dc) || dc.is_subclass_of(s) {
                            return PLook::Declared(info.clone());
                        }
                    }
                }
                PLook::Wrong(info.clone())
            }
            None => {
                if let Some(s) = scope {
                    if !Rc::ptr_eq(s, cls) && cls.is_subclass_of(s) {
                        if let Some(p) = s.prop_infos.get(name) {
                            if p.vis == Visibility::Private && same_class(s, &p.decl_class) {
                                return PLook::Declared(p.clone());
                            }
                        }
                    }
                }
                PLook::Dynamic
            }
        }
    }

    fn has_guard(o: &Obj, name: &[u8], kind: u8) -> bool {
        o.guards.borrow().iter().any(|(n, k)| n.as_bytes() == name && (k & kind) != 0)
    }
    fn push_guard(o: &Obj, name: &[u8], kind: u8) {
        o.guards.borrow_mut().push((Rc::from(String::from_utf8_lossy(name).as_ref()), kind));
    }
    fn pop_guard(o: &Obj, name: &[u8], kind: u8) {
        let mut g = o.guards.borrow_mut();
        if let Some(p) = g.iter().rposition(|(n, k)| n.as_bytes() == name && *k == kind) {
            g.remove(p);
        }
    }

    fn call_magic_guarded(&mut self, o: &Obj, m: &Rc<Method>, name: &[u8], kind: u8, args: Vec<Value>) -> R<Value> {
        Self::push_guard(o, name, kind);
        let r = self.call_method_obj(o, m, args);
        Self::pop_guard(o, name, kind);
        r
    }

    fn prop_access_error(&mut self, o: &Obj, info: &PropInfo, name: &str) -> Flow {
        let msg = format!(
            "Cannot access {} property {}::${}",
            calls::vis_name(info.vis),
            o.class.name,
            name
        );
        self.error(&msg)
    }

    pub fn read_prop(&mut self, o: &Obj, name: &[u8], scope: Option<&Rc<Class>>, quiet: bool) -> R<Value> {
        let ns = String::from_utf8_lossy(name);
        let look = self.lookup_prop(&o.class, &ns, scope);
        match look {
            PLook::Declared(info) => {
                if let Some(h) = &info.hooks {
                    if let Some(g) = &h.get {
                        if !Self::has_guard(o, name, G_HOOK) {
                            let g = g.clone();
                            return self.call_hook(o, &g, name, vec![]);
                        }
                    } else if info.is_virtual && !Self::has_guard(o, name, G_HOOK) {
                        let msg = format!("Property {}::${} is write-only", o.class.name, ns);
                        return Err(self.error(&msg));
                    }
                }
                let v = o.slots.borrow()[info.slot].clone();
                if !v.is_undef() {
                    return Ok(v.into_deref());
                }
                if info.ty.is_some() {
                    if let Some(g) = o.class.magic.get.clone() {
                        if !Self::has_guard(o, name, G_GET) && o.flags.get() & OBJ_LAZY != 0 {
                            return self.call_magic_guarded(o, &g, name, G_GET, vec![Value::bytes(name)]);
                        }
                    }
                    if quiet {
                        return Ok(Value::Null);
                    }
                    let msg = format!("Typed property {}::${} must not be accessed before initialization", info.decl_class, ns);
                    return Err(self.error(&msg));
                }
                if let Some(g) = o.class.magic.get.clone() {
                    if !Self::has_guard(o, name, G_GET) {
                        return self.call_magic_guarded(o, &g, name, G_GET, vec![Value::bytes(name)]);
                    }
                }
                if !quiet {
                    self.warn(&format!("Undefined property: {}::${}", o.class.name, ns))?;
                }
                Ok(Value::Null)
            }
            PLook::Dynamic => {
                {
                    let d = o.dynamic.borrow();
                    if let Some(d) = &*d {
                        if let Some(v) = d.get(&Key::from_str_bytes(name)) {
                            return Ok(v.deref());
                        }
                    }
                }
                if let Some(g) = o.class.magic.get.clone() {
                    if !Self::has_guard(o, name, G_GET) {
                        return self.call_magic_guarded(o, &g, name, G_GET, vec![Value::bytes(name)]);
                    }
                }
                if !quiet {
                    self.warn(&format!("Undefined property: {}::${}", o.class.name, ns))?;
                }
                Ok(Value::Null)
            }
            PLook::Wrong(info) => {
                if let Some(g) = o.class.magic.get.clone() {
                    if !Self::has_guard(o, name, G_GET) {
                        return self.call_magic_guarded(o, &g, name, G_GET, vec![Value::bytes(name)]);
                    }
                }
                if quiet {
                    return Ok(Value::Null);
                }
                Err(self.prop_access_error(o, &info, &ns))
            }
        }
    }

    fn call_hook(&mut self, o: &Obj, f: &Rc<FuncDecl>, name: &[u8], args: Vec<Value>) -> R<Value> {
        Self::push_guard(o, name, G_HOOK);
        let cls = o.class.clone();
        let ctx = calls::CallCtx {
            this: Some(o.clone()),
            class: Some(cls.clone()),
            static_class: Some(cls.clone()),
            closure: None,
            disp_class: Some(cls.name.clone()),
            call_type: "->",
            bound_vars: None,
        };
        let line = self.cur_line;
        let r = self.call_user(f, args, Vec::new(), ctx, line);
        Self::pop_guard(o, name, G_HOOK);
        r
    }

    pub fn write_prop(&mut self, o: &Obj, name: &[u8], v: Value, scope: Option<&Rc<Class>>) -> R<()> {
        self.write_prop_scoped(o, name, v, scope, false)
    }

    fn check_prop_type(&mut self, o: &Obj, info: &PropInfo, v: Value) -> R<Value> {
        match &info.ty {
            None => Ok(v),
            Some(t) => {
                let strict = self.strict_files.contains(&*self.cur_file);
                let cls = self.classes.get(&lc(&info.decl_class)).cloned();
                match self.coerce_type(&v, t, strict, cls.as_ref(), Some(&o.class))? {
                    Some(c) => Ok(c),
                    None => {
                        let msg = format!("Cannot assign {} to property {}::${} of type {}", calls::type_name_given(&v), info.decl_class, info.name, type_to_string(t));
                        Err(self.type_error(&msg))
                    }
                }
            }
        }
    }

    pub fn write_prop_scoped(&mut self, o: &Obj, name: &[u8], v: Value, scope: Option<&Rc<Class>>, force: bool) -> R<()> {
        let ns = String::from_utf8_lossy(name).to_string();
        let look = self.lookup_prop(&o.class, &ns, scope);
        match look {
            PLook::Declared(info) => {
                if let Some(h) = &info.hooks {
                    if let Some(sh) = &h.set {
                        if !Self::has_guard(o, name, G_HOOK) {
                            let sh = sh.clone();
                            self.call_hook(o, &sh, name, vec![v])?;
                            return Ok(());
                        }
                    } else if info.is_virtual && !Self::has_guard(o, name, G_HOOK) {
                        let msg = format!("Property {}::${} is read-only", o.class.name, ns);
                        return Err(self.error(&msg));
                    }
                }
                let cur_undef = o.slots.borrow()[info.slot].is_undef();
                if info.readonly && !force {
                    let in_scope = scope.map(|s| same_class(s, &info.decl_class)).unwrap_or(false);
                    let cloning = o.flags.get() & OBJ_CLONING != 0;
                    if !cur_undef && !cloning {
                        let msg = format!("Cannot modify readonly property {}::${}", o.class.name, ns);
                        return Err(self.error(&msg));
                    }
                    if !in_scope {
                        let msg = format!("Cannot modify protected(set) readonly property {}::${} from {}", o.class.name, ns, calls::scope_desc(scope));
                        return Err(self.error(&msg));
                    }
                }
                if let Some(sv) = info.set_vis {
                    if !force && sv != Visibility::Public {
                        let ok = match scope {
                            Some(s) => {
                                if sv == Visibility::Private {
                                    same_class(s, &info.decl_class)
                                } else {
                                    s.instance_of_name(&info.decl_class.to_ascii_lowercase()) || o.class.is_subclass_of(s)
                                }
                            }
                            None => false,
                        };
                        if !ok {
                            let msg = format!("Cannot modify {}(set) property {}::${} from {}", calls::vis_name(sv), o.class.name, ns, calls::scope_desc(scope));
                            return Err(self.error(&msg));
                        }
                    }
                }
                if cur_undef && info.ty.is_none() {
                    // unset untyped property: __set
                    if let Some(s) = o.class.magic.set.clone() {
                        if !Self::has_guard(o, name, G_SET) {
                            self.call_magic_guarded(o, &s, name, G_SET, vec![Value::bytes(name), v])?;
                            return Ok(());
                        }
                    }
                }
                let v = self.check_prop_type(o, &info, v)?;
                let old = {
                    let mut slots = o.slots.borrow_mut();
                    match &mut slots[info.slot] {
                        Value::Ref(r) => {
                            let o2 = std::mem::replace(&mut *r.borrow_mut(), v);
                            o2
                        }
                        s => std::mem::replace(s, v),
                    }
                };
                drop(old);
                Ok(())
            }
            PLook::Dynamic => {
                let exists = o.dynamic.borrow().as_ref().map(|d| d.contains_key(&Key::from_str_bytes(name))).unwrap_or(false);
                if !exists {
                    if let Some(s) = o.class.magic.set.clone() {
                        if !Self::has_guard(o, name, G_SET) {
                            self.call_magic_guarded(o, &s, name, G_SET, vec![Value::bytes(name), v])?;
                            return Ok(());
                        }
                    }
                    if o.class.is_readonly {
                        let msg = format!("Cannot create dynamic property {}::${}", o.class.name, ns);
                        return Err(self.error(&msg));
                    }
                    if !o.class.allow_dynamic {
                        let msg = format!("Creation of dynamic property {}::${} is deprecated", o.class.name, ns);
                        self.deprecated(&msg)?;
                    }
                }
                let old = {
                    let mut d = o.dynamic.borrow_mut();
                    let d = d.get_or_insert_with(PArray::new);
                    let slot = d.entry_mut(Key::from_str_bytes(name));
                    match slot {
                        Value::Ref(r) => std::mem::replace(&mut *r.borrow_mut(), v),
                        s => std::mem::replace(s, v),
                    }
                };
                drop(old);
                Ok(())
            }
            PLook::Wrong(info) => {
                if let Some(s) = o.class.magic.set.clone() {
                    if !Self::has_guard(o, name, G_SET) {
                        self.call_magic_guarded(o, &s, name, G_SET, vec![Value::bytes(name), v])?;
                        return Ok(());
                    }
                }
                if info.readonly {
                    let msg = format!("Cannot modify protected(set) readonly property {}::${} from {}", o.class.name, ns, calls::scope_desc(scope));
                    return Err(self.error(&msg));
                }
                Err(self.prop_access_error(o, &info, &ns))
            }
        }
    }

    pub fn init_promoted(&mut self, o: &Obj, name: &Name, v: Value, scope: Option<&Rc<Class>>) -> R<()> {
        let look = self.lookup_prop(&o.class, name, scope);
        if let PLook::Declared(info) = look {
            let v = self.check_prop_type(o, &info, v)?;
            o.slots.borrow_mut()[info.slot] = v;
            return Ok(());
        }
        self.write_prop_scoped(o, name.as_bytes(), v, scope, true)
    }

    /// pointer to deref'd storage for nested writes
    pub fn prop_ptr_for_write(&mut self, o: &Obj, name: &[u8], scope: Option<&Rc<Class>>, temps: &mut Vec<Box<Value>>) -> R<*mut Value> {
        let raw = self.prop_raw_ptr(o, name, scope, temps)?;
        unsafe {
            if let Value::Ref(r) = &*raw {
                return Ok(r.as_ptr());
            }
        }
        Ok(raw)
    }

    pub fn prop_raw_ptr(&mut self, o: &Obj, name: &[u8], scope: Option<&Rc<Class>>, temps: &mut Vec<Box<Value>>) -> R<*mut Value> {
        let ns = String::from_utf8_lossy(name).to_string();
        let look = self.lookup_prop(&o.class, &ns, scope);
        match look {
            PLook::Declared(info) => {
                if info.hooks.is_some() && !Self::has_guard(o, name, G_HOOK) {
                    let v = self.read_prop(o, name, scope, false)?;
                    temps.push(Box::new(v));
                    return Ok(&mut **temps.last_mut().unwrap() as *mut Value);
                }
                if info.readonly {
                    let cur_undef = o.slots.borrow()[info.slot].is_undef();
                    if !cur_undef || !scope.map(|s| same_class(s, &info.decl_class)).unwrap_or(false) {
                        if !(o.flags.get() & OBJ_CLONING != 0) {
                            let msg = format!("Cannot indirectly modify readonly property {}::${}", o.class.name, ns);
                            return Err(self.error(&msg));
                        }
                    }
                }
                let undef = o.slots.borrow()[info.slot].is_undef();
                if undef {
                    if info.ty.is_none() {
                        if let Some(g) = o.class.magic.get.clone() {
                            if !Self::has_guard(o, name, G_GET) {
                                let v = self.call_magic_guarded(o, &g, name, G_GET, vec![Value::bytes(name)])?;
                                if !matches!(v, Value::Object(_)) {
                                    self.notice(&format!("Indirect modification of overloaded property {}::${} has no effect", o.class.name, ns))?;
                                }
                                temps.push(Box::new(v));
                                return Ok(&mut **temps.last_mut().unwrap() as *mut Value);
                            }
                        }
                    }
                    o.slots.borrow_mut()[info.slot] = Value::Null;
                }
                let p = o.slots.as_ptr();
                unsafe { Ok(&mut (*p)[info.slot] as *mut Value) }
            }
            PLook::Dynamic => {
                let exists = o.dynamic.borrow().as_ref().map(|d| d.contains_key(&Key::from_str_bytes(name))).unwrap_or(false);
                if !exists {
                    if let Some(g) = o.class.magic.get.clone() {
                        if !Self::has_guard(o, name, G_GET) {
                            let v = self.call_magic_guarded(o, &g, name, G_GET, vec![Value::bytes(name)])?;
                            if !matches!(v, Value::Object(_)) {
                                self.notice(&format!("Indirect modification of overloaded property {}::${} has no effect", o.class.name, ns))?;
                            }
                            temps.push(Box::new(v));
                            return Ok(&mut **temps.last_mut().unwrap() as *mut Value);
                        }
                    }
                    if !o.class.allow_dynamic {
                        let msg = format!("Creation of dynamic property {}::${} is deprecated", o.class.name, ns);
                        self.deprecated(&msg)?;
                    }
                }
                let p = o.dynamic.as_ptr();
                unsafe {
                    let d = (*p).get_or_insert_with(PArray::new);
                    Ok(d.entry_mut(Key::from_str_bytes(name)) as *mut Value)
                }
            }
            PLook::Wrong(info) => {
                if let Some(g) = o.class.magic.get.clone() {
                    if !Self::has_guard(o, name, G_GET) {
                        let v = self.call_magic_guarded(o, &g, name, G_GET, vec![Value::bytes(name)])?;
                        temps.push(Box::new(v));
                        return Ok(&mut **temps.last_mut().unwrap() as *mut Value);
                    }
                }
                Err(self.prop_access_error(o, &info, &ns))
            }
        }
    }

    pub fn unset_prop(&mut self, o: &Obj, name: &[u8], scope: Option<&Rc<Class>>) -> R<()> {
        let ns = String::from_utf8_lossy(name).to_string();
        match self.lookup_prop(&o.class, &ns, scope) {
            PLook::Declared(info) => {
                if info.readonly {
                    let msg = format!("Cannot unset readonly property {}::${}", o.class.name, ns);
                    return Err(self.error(&msg));
                }
                let old = std::mem::replace(&mut o.slots.borrow_mut()[info.slot], Value::Undef);
                drop(old);
                Ok(())
            }
            PLook::Dynamic => {
                let removed = {
                    let mut d = o.dynamic.borrow_mut();
                    match &mut *d {
                        Some(d) => d.remove(&Key::from_str_bytes(name)),
                        None => None,
                    }
                };
                if removed.is_none() {
                    if let Some(u) = o.class.magic.unset.clone() {
                        if !Self::has_guard(o, name, G_UNSET) {
                            self.call_magic_guarded(o, &u, name, G_UNSET, vec![Value::bytes(name)])?;
                        }
                    }
                }
                drop(removed);
                Ok(())
            }
            PLook::Wrong(info) => {
                if let Some(u) = o.class.magic.unset.clone() {
                    if !Self::has_guard(o, name, G_UNSET) {
                        self.call_magic_guarded(o, &u, name, G_UNSET, vec![Value::bytes(name)])?;
                        return Ok(());
                    }
                }
                Err(self.prop_access_error(o, &info, &ns))
            }
        }
    }

    /// property exists (for ?? / isset chains), calling __isset when needed
    pub fn prop_isset(&mut self, o: &Obj, name: &[u8], scope: Option<&Rc<Class>>) -> R<bool> {
        let ns = String::from_utf8_lossy(name).to_string();
        match self.lookup_prop(&o.class, &ns, scope) {
            PLook::Declared(info) => {
                if let Some(h) = &info.hooks {
                    if h.get.is_some() && !Self::has_guard(o, name, G_HOOK) {
                        return Ok(true);
                    }
                }
                let undef = o.slots.borrow()[info.slot].is_undef();
                if !undef {
                    return Ok(true);
                }
                if info.ty.is_some() {
                    return Ok(false);
                }
                self.magic_isset(o, name)
            }
            PLook::Dynamic => {
                let exists = o.dynamic.borrow().as_ref().map(|d| d.contains_key(&Key::from_str_bytes(name))).unwrap_or(false);
                if exists {
                    return Ok(true);
                }
                self.magic_isset(o, name)
            }
            PLook::Wrong(_) => self.magic_isset(o, name),
        }
    }

    fn magic_isset(&mut self, o: &Obj, name: &[u8]) -> R<bool> {
        if let Some(m) = o.class.magic.isset.clone() {
            if !Self::has_guard(o, name, G_ISSET) {
                let r = self.call_magic_guarded(o, &m, name, G_ISSET, vec![Value::bytes(name)])?;
                return Ok(r.to_bool());
            }
        }
        Ok(false)
    }

    /// isset($o->name)
    pub fn prop_isset_value(&mut self, o: &Obj, name: &[u8], scope: Option<&Rc<Class>>) -> R<bool> {
        let ns = String::from_utf8_lossy(name).to_string();
        match self.lookup_prop(&o.class, &ns, scope) {
            PLook::Declared(info) => {
                if let Some(h) = &info.hooks {
                    if h.get.is_some() && !Self::has_guard(o, name, G_HOOK) {
                        let v = self.read_prop(o, name, scope, true)?;
                        return Ok(!v.is_null());
                    }
                }
                let v = o.slots.borrow()[info.slot].clone();
                if !v.is_undef() {
                    return Ok(!v.is_null());
                }
                if info.ty.is_some() {
                    return Ok(false);
                }
                self.magic_isset(o, name)
            }
            PLook::Dynamic => {
                let v = o.dynamic.borrow().as_ref().and_then(|d| d.get(&Key::from_str_bytes(name)).cloned());
                match v {
                    Some(v) => Ok(!v.is_null()),
                    None => self.magic_isset(o, name),
                }
            }
            PLook::Wrong(_) => self.magic_isset(o, name),
        }
    }

    pub fn prop_get_direct(&mut self, o: &Obj, name: &[u8], scope: Option<&Rc<Class>>) -> Option<Value> {
        let ns = String::from_utf8_lossy(name).to_string();
        match self.lookup_prop(&o.class, &ns, scope) {
            PLook::Declared(info) => {
                let v = o.slots.borrow()[info.slot].clone();
                if v.is_undef() {
                    None
                } else {
                    Some(v)
                }
            }
            PLook::Dynamic => o.dynamic.borrow().as_ref().and_then(|d| d.get(&Key::from_str_bytes(name)).cloned()),
            PLook::Wrong(_) => None,
        }
    }

    /// properties visible from scope, in order (name, value)
    pub fn visible_props(&self, o: &Obj, scope: Option<&Rc<Class>>) -> Vec<(Vec<u8>, Value)> {
        let mut out = Vec::new();
        let slots = o.slots.borrow();
        let mut seen: Vec<&str> = Vec::new();
        for info in o.class.slots.iter() {
            let v = &slots[info.slot];
            if v.is_undef() {
                continue;
            }
            let visible = match info.vis {
                Visibility::Public => true,
                Visibility::Protected => match scope {
                    Some(s) => {
                        o.class.is_subclass_of(s) || s.is_subclass_of(&o.class) || s.instance_of_name(&info.decl_class.to_ascii_lowercase())
                    }
                    None => false,
                },
                Visibility::Private => scope.map(|s| same_class(s, &info.decl_class)).unwrap_or(false),
            };
            if !visible {
                continue;
            }
            if seen.contains(&&*info.name) {
                // shadowed private: keep the one accessible
                continue;
            }
            seen.push(&info.name);
            out.push((info.name.as_bytes().to_vec(), v.clone()));
        }
        drop(slots);
        if let Some(d) = &*o.dynamic.borrow() {
            for (k, v) in d.iter() {
                out.push((k.as_bytes(), v.clone()));
            }
        }
        out
    }

    /// all properties with mangled names
    pub fn object_prop_array(&self, o: &Obj) -> PArray {
        let mut out = PArray::new();
        let slots = o.slots.borrow();
        for info in o.class.slots.iter() {
            let v = &slots[info.slot];
            if v.is_undef() {
                continue;
            }
            out.set(Key::Str(Rc::new(mangle(info))), v.clone());
        }
        drop(slots);
        if let Some(d) = &*o.dynamic.borrow() {
            for (k, v) in d.iter() {
                out.set(k.clone(), v.clone());
            }
        }
        out
    }

    pub fn object_to_array(&mut self, o: &Obj) -> R<PArray> {
        if crate::builtins::spl::is_array_object(o) {
            if let Some(a) = crate::builtins::spl::array_object_storage(self, o) {
                return Ok(a);
            }
        }
        if crate::builtins::classes::is_closure(o) {
            let mut a = PArray::new();
            a.push(Value::Object(o.clone()));
            return Ok(a);
        }
        let mut out = PArray::new();
        for (k, v) in self.object_prop_array(o).iter() {
            let key = match k {
                Key::Str(s) => Key::from_pstr(s),
                k => k.clone(),
            };
            out.set(key, v.clone());
        }
        Ok(out)
    }
}

pub fn mangle(info: &PropInfo) -> Vec<u8> {
    match info.vis {
        Visibility::Public => info.name.as_bytes().to_vec(),
        Visibility::Protected => {
            let mut v = b"\0*\0".to_vec();
            v.extend_from_slice(info.name.as_bytes());
            v
        }
        Visibility::Private => {
            let mut v = vec![0u8];
            v.extend_from_slice(info.decl_class.as_bytes());
            v.push(0);
            v.extend_from_slice(info.name.as_bytes());
            v
        }
    }
}
