use super::*;
use crate::array::{Key, PArray};
use crate::ast::*;
use crate::imap::IndexMap;
use std::collections::HashMap;
use std::rc::Weak;

impl Interp {
    pub fn find_class(&self, name: &[u8]) -> Option<Rc<Class>> {
        let mut l = name.to_ascii_lowercase();
        if l.first() == Some(&b'\\') {
            l.remove(0);
        }
        self.classes.get(&l).cloned()
    }

    pub fn find_class_autoload(&mut self, name: &[u8]) -> Option<Rc<Class>> {
        if let Some(c) = self.find_class(name) {
            return Some(c);
        }
        if self.autoload(name).is_err() {
            return None;
        }
        self.find_class(name)
    }

    pub fn autoload(&mut self, name: &[u8]) -> R<()> {
        if self.autoloaders.is_empty() {
            return Ok(());
        }
        let mut n = name.to_vec();
        if n.first() == Some(&b'\\') {
            n.remove(0);
        }
        let l = n.to_ascii_lowercase();
        if self.autoload_in_progress.contains(&l) {
            return Ok(());
        }
        self.autoload_in_progress.insert(l.clone());
        let loaders = self.autoloaders.clone();
        let mut res = Ok(());
        for al in loaders {
            if let Err(e) = self.call_value(&al, vec![Value::vec(n.clone())]) {
                res = Err(e);
                break;
            }
            if self.classes.contains_key(&l) {
                break;
            }
        }
        self.autoload_in_progress.remove(&l);
        res
    }

    pub fn lookup_class(&mut self, name: &[u8]) -> R<Rc<Class>> {
        if let Some(c) = self.find_class(name) {
            return Ok(c);
        }
        self.autoload(name)?;
        if let Some(c) = self.find_class(name) {
            return Ok(c);
        }
        let n = String::from_utf8_lossy(name);
        let msg = format!("Class \"{}\" not found", n.trim_start_matches('\\'));
        Err(self.error(&msg))
    }

    pub fn resolve_class_ref(&mut self, f: &mut Frame, cref: &ClassRef, _autoload: bool) -> R<Rc<Class>> {
        match cref {
            ClassRef::Named(n) => {
                if let Some(c) = self.find_class(n.as_bytes()) {
                    return Ok(c);
                }
                self.lookup_class(n.as_bytes())
            }
            ClassRef::SelfRef => match &f.class {
                Some(c) => Ok(c.clone()),
                None => Err(self.error("Cannot use \"self\" when no class scope is active")),
            },
            ClassRef::Parent => match f.class.as_ref().and_then(|c| c.parent.clone()) {
                Some(p) => Ok(p),
                None => {
                    if f.class.is_none() {
                        Err(self.error("Cannot use \"parent\" when no class scope is active"))
                    } else {
                        Err(self.error("Cannot use \"parent\" when current class scope has no parent"))
                    }
                }
            },
            ClassRef::Static => match f.static_class.clone().or(f.class.clone()) {
                Some(c) => Ok(c),
                None => Err(self.error("Cannot use \"static\" when no class scope is active")),
            },
            ClassRef::Dynamic(e) => {
                let v = self.eval(f, e)?;
                match v {
                    Value::Object(o) => Ok(o.class.clone()),
                    Value::Str(s) => self.lookup_class(&s),
                    _ => Err(self.error("Cannot use value as class name")),
                }
            }
        }
    }

    // ---------------- class declaration ----------------
    pub fn declare_class(&mut self, d: &Rc<ClassDecl>) -> R<()> {
        let l = lc(&d.name);
        if self.classes.contains_key(&l) {
            if d.declared.get() {
                return Ok(());
            }
            let kind = match d.kind {
                ClassKind::Interface => "interface",
                ClassKind::Trait => "trait",
                ClassKind::Enum => "enum",
                _ => "class",
            };
            let msg = format!("Cannot declare {} {}, because the name is already in use", kind, d.name);
            self.cur_line = d.line;
            return Err(self.fatal(&msg));
        }
        let parent = match &d.parent {
            Some(p) => {
                let pc = match self.lookup_class(p.as_bytes()) {
                    Ok(c) => c,
                    Err(Flow::Throw(_)) => {
                        let msg = format!("Class \"{}\" not found", p);
                        self.cur_line = d.line;
                        return Err(self.error(&msg));
                    }
                    Err(e) => return Err(e),
                };
                if pc.is_final {
                    let msg = format!("Class {} cannot extend final class {}", d.name, pc.name);
                    self.cur_line = d.line;
                    return Err(self.fatal(&msg));
                }
                if pc.kind == ClassKind::Interface {
                    let msg = format!("Class {} cannot extend interface {}", d.name, pc.name);
                    self.cur_line = d.line;
                    return Err(self.fatal(&msg));
                }
                if pc.kind == ClassKind::Trait {
                    let msg = format!("Class {} cannot extend trait {}", d.name, pc.name);
                    self.cur_line = d.line;
                    return Err(self.fatal(&msg));
                }
                Some(pc)
            }
            None => None,
        };
        let mut interfaces: Vec<Rc<Class>> = Vec::new();
        let add_iface = |list: &mut Vec<Rc<Class>>, c: &Rc<Class>| {
            if !list.iter().any(|x| x.lname == c.lname) {
                list.push(c.clone());
            }
        };
        let mut direct = Vec::new();
        let mut iface_names: Vec<Name> = d.interfaces.clone();
        if d.kind == ClassKind::Enum {
            iface_names.push(Rc::from("UnitEnum"));
            if d.enum_type.is_some() {
                iface_names.push(Rc::from("BackedEnum"));
            }
        }
        // Stringable auto
        if d.methods.iter().any(|m| m.func.name.eq_ignore_ascii_case("__tostring")) && d.kind != ClassKind::Trait {
            if !iface_names.iter().any(|n| n.eq_ignore_ascii_case("stringable")) && !d.name.eq_ignore_ascii_case("stringable") {
                iface_names.push(Rc::from("Stringable"));
            }
        }
        for iname in &iface_names {
            let ic = match self.lookup_class(iname.as_bytes()) {
                Ok(c) => c,
                Err(Flow::Throw(_)) => {
                    let msg = format!("Interface \"{}\" not found", iname);
                    self.cur_line = d.line;
                    return Err(self.error(&msg));
                }
                Err(e) => return Err(e),
            };
            if ic.kind != ClassKind::Interface {
                let msg = format!("{} cannot implement {} - it is not an interface", d.name, ic.name);
                self.cur_line = d.line;
                return Err(self.fatal(&msg));
            }
            direct.push(ic.name.clone());
            for sub in ic.interfaces.iter() {
                add_iface(&mut interfaces, sub);
            }
            add_iface(&mut interfaces, &ic);
        }
        if let Some(p) = &parent {
            let mut all = p.interfaces.clone();
            for i in interfaces {
                if !all.iter().any(|x| x.lname == i.lname) {
                    all.push(i);
                }
            }
            interfaces = all;
        }
        let mut traits = Vec::new();
        for t in &d.traits {
            let tc = match self.lookup_class(t.as_bytes()) {
                Ok(c) => c,
                Err(Flow::Throw(_)) => {
                    let msg = format!("Trait \"{}\" not found", t);
                    self.cur_line = d.line;
                    return Err(self.error(&msg));
                }
                Err(e) => return Err(e),
            };
            if tc.kind != ClassKind::Trait {
                let msg = format!("{} cannot use {} - it is not a trait", d.name, tc.name);
                self.cur_line = d.line;
                return Err(self.fatal(&msg));
            }
            traits.push(tc);
        }
        self.class_id_counter += 1;
        let cid = self.class_id_counter;
        let name = d.name.clone();
        let lname: Name = Rc::from(String::from_utf8_lossy(&l).as_ref());
        let is_internal = !self.prelude_done;

        // ---- constants ----
        let mut consts: IndexMap<Name, Rc<ClassConst>> = IndexMap::new();
        if let Some(p) = &parent {
            for (k, v) in p.consts.borrow().iter() {
                consts.insert(k.clone(), v.clone());
            }
        }
        for i in &interfaces {
            for (k, v) in i.consts.borrow().iter() {
                if !consts.contains_key(k) {
                    consts.insert(k.clone(), v.clone());
                }
            }
        }
        for t in &traits {
            for (k, v) in t.consts.borrow().iter() {
                consts.insert(k.clone(), Rc::new(ClassConst {
                    name: v.name.clone(),
                    value: RefCell::new(v.value.borrow().clone()),
                    expr: v.expr.clone(),
                    vis: v.vis,
                    decl_class: name.clone(),
                    is_final: v.is_final,
                    is_case: false,
                }));
            }
        }
        for (i, c) in d.consts.iter().enumerate() {
            if let Some(existing) = consts.get(&c.name) {
                if existing.is_final && !existing.decl_class.eq_ignore_ascii_case(&name) {
                    let msg = format!("{}::{} cannot override final constant {}::{}", name, c.name, existing.decl_class, c.name);
                    self.cur_line = d.line;
                    return Err(self.fatal(&msg));
                }
            }
            consts.insert(
                c.name.clone(),
                Rc::new(ClassConst { name: c.name.clone(), value: RefCell::new(None), expr: Some((d.clone(), i)), vis: c.vis, decl_class: name.clone(), is_final: c.is_final, is_case: false }),
            );
        }
        let mut case_names = Vec::new();
        for c in d.cases.iter() {
            case_names.push(c.name.clone());
            consts.insert(c.name.clone(), Rc::new(ClassConst { name: c.name.clone(), value: RefCell::new(None), expr: None, vis: Visibility::Public, decl_class: name.clone(), is_final: true, is_case: true }));
        }

        // ---- properties ----
        let mut prop_infos: HashMap<Name, Rc<PropInfo>> = HashMap::new();
        let mut slots: Vec<Rc<PropInfo>> = Vec::new();
        let mut static_props: IndexMap<Name, Rc<StaticProp>> = IndexMap::new();
        if let Some(p) = &parent {
            for (k, v) in p.prop_infos.iter() {
                prop_infos.insert(k.clone(), v.clone());
            }
            slots = p.slots.clone();
            for (k, v) in p.static_props.iter() {
                static_props.insert(k.clone(), v.clone());
            }
        }
        let mut has_hooks = false;
        let mut add_prop = |pd: &PropDecl, src: Option<(Rc<ClassDecl>, usize)>, prop_infos: &mut HashMap<Name, Rc<PropInfo>>, slots: &mut Vec<Rc<PropInfo>>, static_props: &mut IndexMap<Name, Rc<StaticProp>>, is_readonly_class: bool| -> Option<String> {
            let hooks = if pd.hooks.is_empty() {
                None
            } else {
                has_hooks = true;
                let mut get = None;
                let mut set = None;
                for h in &pd.hooks {
                    if h.func.body.is_none() {
                        continue;
                    }
                    if &*h.kind == "get" {
                        get = Some(h.func.clone());
                    } else if &*h.kind == "set" {
                        set = Some(h.func.clone());
                    }
                }
                Some(Rc::new(PropHooks { get, set, class: name.clone() }))
            };
            let is_virtual = !pd.hooks.is_empty() && pd.default.is_none() && !hooks_use_backing(&pd.name, &pd.hooks);
            if pd.is_static {
                let info = Rc::new(PropInfo {
                    name: pd.name.clone(),
                    decl_class: name.clone(),
                    vis: pd.vis,
                    set_vis: pd.set_vis,
                    is_static: true,
                    readonly: pd.readonly,
                    ty: pd.ty.clone(),
                    slot: 0,
                    changed: false,
                    default_src: src.clone(),
                    hooks: None,
                    is_virtual: false,
                });
                static_props.insert(pd.name.clone(), Rc::new(StaticProp { val: Rc::new(RefCell::new(Value::Undef)), info, initialized: Cell::new(false) }));
                return None;
            }
            let existing = prop_infos.get(&pd.name).cloned();
            let (slot, changed) = match &existing {
                Some(e) if e.vis != Visibility::Private || e.decl_class.eq_ignore_ascii_case(&name) => (e.slot, false),
                Some(_) => (slots.len(), true),
                None => (slots.len(), false),
            };
            if let Some(e) = &existing {
                if e.vis != Visibility::Private && pd.vis > e.vis {
                    return Some(format!(
                        "Access level to {}::${} must be {} (as in class {}){}",
                        name,
                        pd.name,
                        calls::vis_name(e.vis),
                        e.decl_class,
                        if e.vis == Visibility::Protected { " or weaker" } else { "" }
                    ));
                }
            }
            let info = Rc::new(PropInfo {
                name: pd.name.clone(),
                decl_class: name.clone(),
                vis: pd.vis,
                set_vis: pd.set_vis.or(if pd.readonly { None } else { None }),
                is_static: false,
                readonly: pd.readonly || is_readonly_class,
                ty: pd.ty.clone(),
                slot,
                changed,
                default_src: src,
                hooks,
                is_virtual,
            });
            if slot == slots.len() {
                slots.push(info.clone());
            } else {
                slots[slot] = info.clone();
            }
            prop_infos.insert(pd.name.clone(), info);
            None
        };
        for (i, pd) in d.props.iter().enumerate() {
            if let Some(err) = add_prop(pd, Some((d.clone(), i)), &mut prop_infos, &mut slots, &mut static_props, d.is_readonly) {
                self.cur_line = d.line;
                return Err(self.fatal(&err));
            }
        }
        // promoted ctor params
        for m in &d.methods {
            if m.func.name.eq_ignore_ascii_case("__construct") {
                for p in &m.func.params {
                    if let Some((vis, ro, svis)) = p.promote {
                        let pd = PropDecl {
                            name: p.name.clone(),
                            default: None,
                            ty: p.ty.clone().or(None),
                            vis,
                            set_vis: svis,
                            is_static: false,
                            readonly: ro || d.is_readonly,
                            doc: None,
                            hooks: Vec::new(),
                            is_abstract: false,
                            is_final: false,
                            attrs: Vec::new(),
                            line: m.func.line,
                        };
                        // promoted props without type are untyped (null default)
                        let pd_ty_none = pd.ty.is_none();
                        add_prop(&pd, None, &mut prop_infos, &mut slots, &mut static_props, d.is_readonly);
                        if pd_ty_none {
                            // mark: promoted untyped default null
                        }
                    }
                }
            }
        }
        for t in &traits {
            if let Some(td) = &t.decl {
                for (i, pd) in td.props.iter().enumerate() {
                    if prop_infos.get(&pd.name).map(|e| e.decl_class.eq_ignore_ascii_case(&name)).unwrap_or(false) {
                        continue;
                    }
                    add_prop(pd, Some((td.clone(), i)), &mut prop_infos, &mut slots, &mut static_props, d.is_readonly);
                }
            }
        }
        drop(add_prop);

        // ---- methods ----
        let traits_c = traits.clone();
        let parent_c = parent.clone();
        let interfaces_c = interfaces.clone();
        let d2 = d.clone();
        let name2 = name.clone();
        let mut errors: Vec<String> = Vec::new();
        let cls = Rc::new_cyclic(|weak: &Weak<Class>| {
            let mut methods: HashMap<Name, Rc<Method>> = HashMap::new();
            let mut order: Vec<Name> = Vec::new();
            // own
            for md in &d2.methods {
                let ln: Name = Rc::from(md.func.name.to_ascii_lowercase().as_str());
                let proto = parent_c.as_ref().and_then(|p| p.methods.get(&ln)).map(|pm| pm.proto.clone().unwrap_or(pm.class.upgrade().map(|c| c.lname.clone()).unwrap_or(ln.clone())));
                if let Some(pm) = parent_c.as_ref().and_then(|p| p.methods.get(&ln)) {
                    if pm.is_final && pm.vis != Visibility::Private {
                        errors.push(format!("Cannot override final method {}::{}()", pm.decl_class_name, pm.name));
                    }
                    if pm.vis != Visibility::Private && md.vis > pm.vis {
                        errors.push(format!(
                            "Access level to {}::{}() must be {} (as in class {}){}",
                            name2,
                            md.func.name,
                            calls::vis_name(pm.vis),
                            pm.decl_class_name,
                            if pm.vis == Visibility::Protected { " or weaker" } else { "" }
                        ));
                    }
                    if pm.is_static != md.is_static && pm.vis != Visibility::Private {
                        if pm.is_static {
                            errors.push(format!("Cannot make static method {}::{}() non static in class {}", pm.decl_class_name, pm.name, name2));
                        } else {
                            errors.push(format!("Cannot make non static method {}::{}() static in class {}", pm.decl_class_name, pm.name, name2));
                        }
                    }
                }
                let m = Rc::new(Method {
                    name: md.func.name.clone(),
                    lname: ln.clone(),
                    class: weak.clone(),
                    decl_class_name: name2.clone(),
                    vis: md.vis,
                    is_static: md.is_static,
                    is_abstract: md.is_abstract || md.func.body.is_none(),
                    is_final: md.is_final,
                    imp: MethodImpl::User(md.func.clone()),
                    proto,
                    builtin_params: None,
                });
                if !methods.contains_key(&ln) {
                    order.push(ln.clone());
                }
                methods.insert(ln, m);
            }
            // traits
            let mut excluded: Vec<(String, String)> = Vec::new(); // (trait lname, method lname)
            for r in &d2.trait_rules {
                if let TraitRule::Insteadof { trait_name: _, method, instead_of } = r {
                    for io in instead_of {
                        excluded.push((io.to_ascii_lowercase(), method.to_ascii_lowercase()));
                    }
                }
            }
            for t in &traits_c {
                let mut tmeths: Vec<(&Name, &Rc<Method>)> = t.methods.iter().collect();
                tmeths.sort_by_key(|(k, _)| t.method_order.iter().position(|x| x == *k).unwrap_or(usize::MAX));
                for (ln, tm) in tmeths {
                    if excluded.iter().any(|(tn, mn)| *tn == *t.lname && mn == &**ln) {
                        continue;
                    }
                    // own methods take precedence
                    if let Some(existing) = methods.get(ln) {
                        if existing.decl_class_name.eq_ignore_ascii_case(&name2) && !existing.is_abstract {
                            if let MethodImpl::User(f) = &existing.imp {
                                if d2.methods.iter().any(|m| Rc::ptr_eq(&m.func, f)) {
                                    continue;
                                }
                            }
                        }
                    }
                    let mut vis = tm.vis;
                    for r in &d2.trait_rules {
                        if let TraitRule::Alias { trait_name, method, alias: None, vis: Some(v) } = r {
                            if method.eq_ignore_ascii_case(ln) && trait_name.as_ref().map(|tn| tn.eq_ignore_ascii_case(&t.name)).unwrap_or(true) {
                                vis = *v;
                            }
                        }
                    }
                    let m = Rc::new(Method {
                        name: tm.name.clone(),
                        lname: ln.clone(),
                        class: weak.clone(),
                        decl_class_name: name2.clone(),
                        vis,
                        is_static: tm.is_static,
                        is_abstract: tm.is_abstract,
                        is_final: tm.is_final,
                        imp: match &tm.imp {
                            MethodImpl::User(f) => MethodImpl::User(f.clone()),
                            MethodImpl::Builtin(b) => MethodImpl::Builtin(*b),
                        },
                        proto: None,
                        builtin_params: tm.builtin_params,
                    });
                    if let Some(existing) = methods.get(ln) {
                        if !existing.is_abstract && m.is_abstract {
                            continue;
                        }
                    }
                    if !methods.contains_key(ln) {
                        order.push(ln.clone());
                    }
                    methods.insert(ln.clone(), m);
                }
                // aliases
                for r in &d2.trait_rules {
                    if let TraitRule::Alias { trait_name, method, alias: Some(alias), vis } = r {
                        if let Some(tn) = trait_name {
                            if !tn.eq_ignore_ascii_case(&t.name) {
                                continue;
                            }
                        } else if !t.methods.contains_key(&*method.to_ascii_lowercase()) {
                            continue;
                        }
                        if let Some(tm) = t.methods.get(&*method.to_ascii_lowercase()) {
                            let aln: Name = Rc::from(alias.to_ascii_lowercase().as_str());
                            let m = Rc::new(Method {
                                name: alias.clone(),
                                lname: aln.clone(),
                                class: weak.clone(),
                                decl_class_name: name2.clone(),
                                vis: vis.unwrap_or(tm.vis),
                                is_static: tm.is_static,
                                is_abstract: tm.is_abstract,
                                is_final: tm.is_final,
                                imp: match &tm.imp {
                                    MethodImpl::User(f) => MethodImpl::User(f.clone()),
                                    MethodImpl::Builtin(b) => MethodImpl::Builtin(*b),
                                },
                                proto: None,
                                builtin_params: tm.builtin_params,
                            });
                            if !methods.contains_key(&aln) {
                                order.push(aln.clone());
                            }
                            methods.insert(aln, m);
                        }
                    }
                }
            }
            // inherited
            if let Some(p) = &parent_c {
                for ln in p.method_order.iter() {
                    if let Some(pm) = p.methods.get(ln) {
                        if !methods.contains_key(ln) {
                            methods.insert(ln.clone(), pm.clone());
                            order.push(ln.clone());
                        }
                    }
                }
            }
            // interface methods (abstract) for interfaces / abstract tracking
            for i in &interfaces_c {
                for ln in i.method_order.iter() {
                    if let Some(im) = i.methods.get(ln) {
                        if !methods.contains_key(ln) {
                            methods.insert(ln.clone(), im.clone());
                            order.push(ln.clone());
                        }
                    }
                }
            }
            let get = |n: &str| methods.get(n).cloned();
            let magic = Magic {
                get: get("__get"),
                set: get("__set"),
                isset: get("__isset"),
                unset: get("__unset"),
                call: get("__call"),
                callstatic: get("__callstatic"),
                tostring: get("__tostring"),
                invoke: get("__invoke"),
                construct: get("__construct"),
                destruct: get("__destruct"),
                clone: get("__clone"),
                debuginfo: get("__debuginfo"),
                serialize: get("__serialize"),
                unserialize: get("__unserialize"),
                sleep: get("__sleep"),
                wakeup: get("__wakeup"),
            };
            let allow_dynamic = d2.name.eq_ignore_ascii_case("stdclass")
                || d2.attrs.iter().any(|a| a.name.eq_ignore_ascii_case("AllowDynamicProperties"))
                || parent_c.as_ref().map(|p| p.allow_dynamic && !p.lname.eq_ignore_ascii_case("exception")).unwrap_or(false)
                || is_internal && !d2.name.eq_ignore_ascii_case("closure") && !d2.name.eq_ignore_ascii_case("generator");
            Class {
                name: name2.clone(),
                lname: lname.clone(),
                kind: d2.kind,
                parent: parent_c.clone(),
                interfaces: interfaces_c.clone(),
                direct_interfaces: direct.clone(),
                is_abstract: d2.is_abstract || d2.kind == ClassKind::Interface || d2.kind == ClassKind::Trait,
                is_final: d2.is_final || d2.kind == ClassKind::Enum,
                is_readonly: d2.is_readonly,
                internal: is_internal,
                consts: RefCell::new(consts),
                static_props,
                prop_infos,
                slots,
                defaults: RefCell::new(None),
                methods,
                method_order: order,
                magic,
                decl: Some(d2.clone()),
                enum_backing: d2.enum_type.as_ref().map(|t| match t {
                    TypeHint::Simple(n) => n.clone(),
                    _ => Rc::from("int"),
                }),
                enum_cases: RefCell::new(IndexMap::new()),
                case_names,
                traits: traits_c.clone(),
                allow_dynamic,
                id: cid,
                has_hooks,
            }
        });
        if let Some(e) = errors.into_iter().next() {
            self.cur_line = d.line;
            return Err(self.fatal(&e));
        }
        // abstract check
        if cls.kind == ClassKind::Class && !cls.is_abstract {
            let mut missing = Vec::new();
            for ln in cls.method_order.iter() {
                let m = &cls.methods[ln];
                if m.is_abstract {
                    missing.push(format!("{}::{}", m.decl_class_name, m.name));
                }
            }
            if !missing.is_empty() {
                let n = missing.len();
                let msg = format!(
                    "Class {} contains {} abstract method{} and must therefore be declared abstract or implement the remaining methods ({})",
                    cls.name,
                    n,
                    if n == 1 { "" } else { "s" },
                    missing.join(", ")
                );
                self.cur_line = d.line;
                return Err(self.fatal(&msg));
            }
        }
        if cls.kind == ClassKind::Enum {
            crate::builtins::classes::add_enum_methods(&cls);
        }
        d.declared.set(true);
        self.classes.insert(l, cls);
        Ok(())
    }

    /// evaluate a constant expression in class context
    pub fn eval_in_class(&mut self, cls: &Rc<Class>, e: &Expr) -> R<Value> {
        let mut f = Frame::new(0, Rc::new(Vec::new()), cls.decl.as_ref().map(|d| d.file.clone()).unwrap_or_else(|| self.cur_file.clone()));
        f.class = Some(cls.clone());
        f.static_class = Some(cls.clone());
        self.eval(&mut f, e)
    }

    pub fn class_defaults(&mut self, cls: &Rc<Class>) -> R<Rc<Vec<Value>>> {
        if let Some(d) = &*cls.defaults.borrow() {
            return Ok(d.clone());
        }
        let mut vals = Vec::with_capacity(cls.slots.len());
        for info in cls.slots.iter() {
            let v = match &info.default_src {
                Some((decl, i)) => match &decl.props[*i].default {
                    Some(e) => {
                        let owner = self.find_class(info.decl_class.as_bytes()).unwrap_or(cls.clone());
                        let saved = self.cur_line;
                        let r = self.eval_in_class(&owner, e);
                        self.cur_line = saved;
                        r?
                    }
                    None => {
                        if info.ty.is_some() || info.is_virtual {
                            Value::Undef
                        } else {
                            Value::Null
                        }
                    }
                },
                None => {
                    if info.ty.is_some() {
                        Value::Undef
                    } else {
                        Value::Undef
                    }
                }
            };
            vals.push(v);
        }
        let rc = Rc::new(vals);
        *cls.defaults.borrow_mut() = Some(rc.clone());
        Ok(rc)
    }

    /// create object without calling constructor
    pub fn instantiate_raw(&mut self, cls: &Rc<Class>) -> R<Obj> {
        let defaults = self.class_defaults(cls)?;
        let o = Object::new(cls.clone(), (*defaults).clone());
        if cls.instance_of_name("throwable") {
            self.init_exception_location(&o);
        }
        crate::builtins::classes::init_internal(self, &o);
        Ok(o)
    }

    pub fn new_object(&mut self, f: &mut Frame, cls: &Rc<Class>, args: &[Arg], line: u32) -> R<Value> {
        if cls.is_abstract || cls.kind != ClassKind::Class {
            let what = match cls.kind {
                ClassKind::Interface => "interface",
                ClassKind::Trait => "trait",
                ClassKind::Enum => "enum",
                _ => "abstract class",
            };
            let msg = format!("Cannot instantiate {} {}", what, cls.name);
            return Err(self.error(&msg));
        }
        let o = self.instantiate_raw(cls)?;
        if let Some(ctor) = cls.magic.construct.clone() {
            if ctor.vis != Visibility::Public && !self.can_access_method(&ctor, f.class.as_ref()) {
                let msg = format!("Call to {} {}::__construct() from {}", calls::vis_name(ctor.vis), cls.name, calls::scope_desc(f.class.as_ref()));
                return Err(self.error(&msg));
            }
            self.invoke_method(f, &ctor, Some(o.clone()), cls, args, line)?;
        } else {
            // still evaluate args
            for a in args {
                self.eval(f, &a.value)?;
            }
        }
        Ok(Value::Object(o))
    }

    pub fn instantiate(&mut self, cls: &Rc<Class>, args: Vec<Value>) -> R<Obj> {
        if cls.is_abstract || cls.kind != ClassKind::Class {
            let msg = format!("Cannot instantiate abstract class {}", cls.name);
            return Err(self.error(&msg));
        }
        let o = self.instantiate_raw(cls)?;
        if let Some(ctor) = cls.magic.construct.clone() {
            self.call_method_obj(&o, &ctor, args)?;
        }
        Ok(o)
    }

    pub fn clone_object(&mut self, o: &Obj) -> R<Obj> {
        if o.class.kind == ClassKind::Enum {
            let msg = format!("Trying to clone an uncloneable object of class {}", o.class.name);
            return Err(self.error(&msg));
        }
        if gen::is_generator_obj(o) {
            return Err(self.error("Trying to clone an uncloneable object of class Generator"));
        }
        if let Some(c) = &o.class.magic.clone {
            if c.vis != Visibility::Public {
                let scope = self.current_scope();
                if !self.can_access_method(c, scope.as_ref()) {
                    let msg = format!("Call to {} {}::__clone() from {}", calls::vis_name(c.vis), o.class.name, calls::scope_desc(scope.as_ref()));
                    return Err(self.error(&msg));
                }
            }
        }
        let slots: Vec<Value> = o.slots.borrow().iter().map(|v| clone_slot(v)).collect();
        let n = Object::new(o.class.clone(), slots);
        *n.dynamic.borrow_mut() = o.dynamic.borrow().as_ref().map(|d| {
            let mut c = d.clone();
            for (_, v) in c.iter_mut() {
                let nv = clone_slot(v);
                *v = nv;
            }
            c
        });
        crate::builtins::classes::clone_internal(self, o, &n);
        if let Some(c) = o.class.magic.clone.clone() {
            n.flags.set(n.flags.get() | OBJ_CLONING);
            let r = self.call_method_obj(&n, &c, Vec::new());
            n.flags.set(n.flags.get() & !OBJ_CLONING);
            r?;
        }
        Ok(n)
    }

    pub fn current_scope(&self) -> Option<Rc<Class>> {
        for ci in self.call_stack.iter().rev() {
            if !ci.frame.is_null() {
                let fr = unsafe { &*ci.frame };
                return fr.class.clone();
            }
        }
        None
    }

    // ---------------- static props / constants ----------------
    pub fn find_static_prop(&mut self, cls: &Rc<Class>, name: &[u8]) -> Option<Rc<StaticProp>> {
        let n = String::from_utf8_lossy(name);
        let sp = cls.static_props.get(&*n).cloned()?;
        if !sp.initialized.get() {
            sp.initialized.set(true);
            let v = match &sp.info.default_src {
                Some((decl, i)) => match &decl.props[*i].default {
                    Some(e) => {
                        let owner = self.find_class(sp.info.decl_class.as_bytes()).unwrap_or(cls.clone());
                        self.eval_in_class(&owner, e).unwrap_or(Value::Null)
                    }
                    None => {
                        if sp.info.ty.is_some() {
                            Value::Undef
                        } else {
                            Value::Null
                        }
                    }
                },
                None => Value::Null,
            };
            *sp.val.borrow_mut() = v;
        }
        Some(sp)
    }

    pub fn static_prop_ref(&mut self, f: &mut Frame, cref: &ClassRef, name: &MemberName) -> R<PRef> {
        let cls = self.resolve_class_ref(f, cref, true)?;
        let n = self.member_name(f, name)?;
        match self.find_static_prop(&cls, &n) {
            Some(sp) => {
                if sp.info.vis != Visibility::Public {
                    let ok = match &f.class {
                        Some(s) => {
                            if sp.info.vis == Visibility::Private {
                                s.name.eq_ignore_ascii_case(&sp.info.decl_class)
                            } else {
                                s.is_subclass_of(&cls) || cls.is_subclass_of(s) || s.instance_of_name(&sp.info.decl_class.to_ascii_lowercase())
                            }
                        }
                        None => false,
                    };
                    if !ok {
                        let msg = format!("Cannot access {} property {}::${}", calls::vis_name(sp.info.vis), cls.name, String::from_utf8_lossy(&n));
                        return Err(self.error(&msg));
                    }
                }
                if sp.val.borrow().is_undef() {
                    // uninitialized typed static: allowed for write; reading checked by caller
                }
                Ok(sp.val.clone())
            }
            None => {
                let msg = format!("Access to undeclared static property {}::${}", cls.name, String::from_utf8_lossy(&n));
                Err(self.error(&msg))
            }
        }
    }

    pub fn eval_class_const(&mut self, f: &mut Frame, cref: &ClassRef, name: &MemberName) -> R<Value> {
        let n = match name {
            MemberName::Ident(n) => n.clone(),
            MemberName::Dynamic(e) => {
                let v = self.eval(f, e)?;
                Rc::from(self.to_string_lossy(&v)?.as_str())
            }
        };
        if n.eq_ignore_ascii_case("class") {
            match cref {
                ClassRef::Named(cn) => return Ok(Value::str(cn)),
                ClassRef::Dynamic(e) => {
                    let v = self.eval(f, e)?;
                    return match v {
                        Value::Object(o) => Ok(Value::str(&o.class.name)),
                        other => {
                            let msg = format!("Cannot use \"::class\" on {}", other.type_name());
                            Err(self.type_error(&msg))
                        }
                    };
                }
                _ => {
                    let c = self.resolve_class_ref(f, cref, true)?;
                    return Ok(Value::str(&c.name));
                }
            }
        }
        let cls = self.resolve_class_ref(f, cref, true)?;
        self.class_const(&cls, &n, f.class.clone().as_ref())
    }

    pub fn class_const(&mut self, cls: &Rc<Class>, n: &str, scope: Option<&Rc<Class>>) -> R<Value> {
        let c = cls.consts.borrow().get(n).cloned();
        match c {
            Some(c) => {
                if c.vis != Visibility::Public {
                    let ok = match scope {
                        Some(s) => {
                            if c.vis == Visibility::Private {
                                s.name.eq_ignore_ascii_case(&c.decl_class)
                            } else {
                                s.is_subclass_of(cls) || cls.is_subclass_of(s)
                            }
                        }
                        None => false,
                    };
                    if !ok {
                        let msg = format!("Cannot access {} constant {}::{}", calls::vis_name(c.vis), cls.name, n);
                        return Err(self.error(&msg));
                    }
                }
                if c.is_case {
                    let owner = self.find_class(c.decl_class.as_bytes()).unwrap_or(cls.clone());
                    return Ok(Value::Object(crate::builtins::classes::enum_case(self, &owner, n)?));
                }
                if let Some(v) = &*c.value.borrow() {
                    return Ok(v.clone());
                }
                let (decl, i) = c.expr.clone().unwrap();
                let owner = self.find_class(c.decl_class.as_bytes()).unwrap_or(cls.clone());
                let saved = self.cur_line;
                let v = self.eval_in_class(&owner, &decl.consts[i].value)?;
                self.cur_line = saved;
                *c.value.borrow_mut() = Some(v.clone());
                Ok(v)
            }
            None => {
                let msg = format!("Undefined constant {}::{}", cls.name, n);
                Err(self.error(&msg))
            }
        }
    }

    // ---------------- exceptions ----------------
    pub fn init_exception_location(&mut self, o: &Obj) {
        let (file, line) = (self.cur_file.clone(), self.cur_line);
        let trace = self.build_trace(0);
        self.set_prop_raw(o, "file", Value::str(&file));
        self.set_prop_raw(o, "line", Value::Int(line as i64));
        self.set_prop_raw(o, "trace", Value::arr(trace));
    }

    pub fn set_exception_location(&mut self, o: &Obj, file: &str, line: u32) {
        self.set_prop_raw(o, "file", Value::str(file));
        self.set_prop_raw(o, "line", Value::Int(line as i64));
    }

    pub fn init_exception(&mut self, o: &Obj, msg: Option<Value>, code: Option<Value>, prev: Option<Value>) {
        if let Some(m) = msg {
            self.set_prop_raw(o, "message", m);
        }
        if let Some(c) = code {
            self.set_prop_raw(o, "code", c);
        }
        if let Some(p) = prev {
            self.set_prop_raw(o, "previous", p);
        }
    }

    /// set a declared property ignoring visibility
    pub fn set_prop_raw(&mut self, o: &Obj, name: &str, v: Value) {
        if let Some(info) = o.class.prop_infos.get(name) {
            // find the base-most declaration for private props (Exception/Error)
            let mut slots = o.slots.borrow_mut();
            slots[info.slot] = v;
            return;
        }
        let mut d = o.dynamic.borrow_mut();
        d.get_or_insert_with(PArray::new).set(Key::Str(Rc::new(name.as_bytes().to_vec())), v);
    }

    pub fn get_prop_raw(&self, o: &Obj, name: &str) -> Value {
        if let Some(info) = o.class.prop_infos.get(name) {
            let slots = o.slots.borrow();
            return slots[info.slot].deref();
        }
        if let Some(d) = &*o.dynamic.borrow() {
            if let Some(v) = d.get(&Key::Str(Rc::new(name.as_bytes().to_vec()))) {
                return v.deref();
            }
        }
        Value::Null
    }

    /// build debug_backtrace-style array; skip = number of top frames to skip
    pub fn build_trace(&mut self, skip: usize) -> PArray {
        let mut out = PArray::new();
        let n = self.call_stack.len();
        if n <= skip {
            return out;
        }
        for ci in self.call_stack[..n - skip].iter().rev() {
            let mut fr = PArray::new();
            if !ci.internal && !ci.file.is_empty() && &*ci.file != "[internal]" {
                fr.set(Key::Str(Rc::new(b"file".to_vec())), Value::str(&ci.file));
                fr.set(Key::Str(Rc::new(b"line".to_vec())), Value::Int(ci.line as i64));
            }
            fr.set(Key::Str(Rc::new(b"function".to_vec())), Value::str(&ci.func));
            if let Some(c) = &ci.class {
                fr.set(Key::Str(Rc::new(b"class".to_vec())), Value::str(c));
                fr.set(Key::Str(Rc::new(b"type".to_vec())), Value::str(ci.call_type));
            }
            let mut args = PArray::new();
            if !ci.frame.is_null() {
                let frame = unsafe { &*ci.frame };
                if let Some(d) = &frame.func {
                    for (i, p) in d.params.iter().enumerate() {
                        if p.variadic {
                            if let Some(Value::Array(a)) = frame.slots.get(p.slot as usize) {
                                for (_, v) in a.iter() {
                                    args.push(v.deref());
                                }
                            }
                            break;
                        }
                        if i < frame.num_args {
                            if let Some(v) = frame.slots.get(p.slot as usize) {
                                args.push(v.deref());
                            }
                        }
                    }
                    for v in &frame.extra_args {
                        args.push(v.clone());
                    }
                }
            } else if !ci.bargs.is_null() {
                let ba = unsafe { &*ci.bargs };
                for v in ba.iter() {
                    if v.is_undef() {
                        continue;
                    }
                    args.push(v.deref());
                }
            }
            fr.set(Key::Str(Rc::new(b"args".to_vec())), Value::arr(args));
            out.push(Value::arr(fr));
        }
        // fix file/line: PHP reports call-site location; entries already store call site
        out
    }
}

fn clone_slot(v: &Value) -> Value {
    match v {
        Value::Ref(r) => {
            if Rc::strong_count(r) == 1 {
                r.borrow().clone()
            } else {
                Value::Ref(r.clone())
            }
        }
        v => v.clone(),
    }
}

fn hooks_use_backing(name: &str, hooks: &[PropHook]) -> bool {
    // a property is backed if any hook references $this->name or is a short set
    for h in hooks {
        if h.func.body.is_none() {
            return true;
        }
        if &*h.kind == "set" && h.func.is_arrow {
            return true;
        }
        if body_refs_prop(h.func.body.as_ref().unwrap(), name) {
            return true;
        }
    }
    false
}

fn body_refs_prop(stmts: &[Stmt], name: &str) -> bool {
    // conservative textual check via debug format
    let s = format!("{:?}", stmts);
    s.contains(&format!("Prop(Expr {{ kind: This, line: ")) && s.contains(&format!("Ident(\"{}\")", name))
}
