#[derive(Clone, Copy, PartialEq, Eq)]
pub enum FiberStatus {
    Init,
    Running,
    Suspended,
    Terminated,
}

pub struct FiberState {
    pub coro: Option<Box<Coro>>,
    pub status: FiberStatus,
    pub callable: Value,
    pub transfer: Value,
    pub throw_in: Option<Obj>,
    pub error: Option<Flow>,
    pub retval: Value,
    pub saved_stack: Vec<CallInfo>,
    pub saved_gens: Vec<*mut GenState>,
    pub args: Vec<Value>,
    pub obj: Option<std::rc::Weak<Object>>,
}

pub struct FiberBox(pub Box<FiberState>);

pub fn fiber_ptr(o: &Object) -> *mut FiberState {
    let b = o.internal.borrow();
    match &*b {
        Internal::Any(a) => match a.downcast_ref::<FiberBox>() {
            Some(g) => &*g.0 as *const FiberState as *mut FiberState,
            None => std::ptr::null_mut(),
        },
        _ => std::ptr::null_mut(),
    }
}

pub fn fiber_resume_raw(it: &mut Interp, fp: *mut FiberState) -> R<Value> {
    let fs = unsafe { &mut *fp };
    if fs.coro.is_none() {
        let ip: *mut Interp = it;
        let fpp = fp;
        fs.coro = Some(Coro::new(Box::new(move || unsafe {
            let it = &mut *ip;
            let fs = &mut *fpp;
            let cb = fs.callable.clone();
            let args = std::mem::take(&mut fs.args);
            let r = it.call_value(&cb, args);
            let fs = &mut *fpp;
            match r {
                Ok(v) => fs.retval = v,
                Err(e) => fs.error = Some(e),
            }
            fs.status = FiberStatus::Terminated;
            fs.transfer = Value::Null;
        })));
    }
    fs.status = FiberStatus::Running;
    let base = it.call_stack.len();
    let gbase = it.gen_stack.len();
    let saved = std::mem::take(&mut fs.saved_stack);
    it.call_stack.extend(saved);
    let sg = std::mem::take(&mut fs.saved_gens);
    it.gen_stack.extend(sg);
    let saved_file = it.cur_file.clone();
    let saved_line = it.cur_line;
    let saved_depth = it.depth;
    it.fibers.push(fp);
    {
        let c: *mut Coro = &mut **fs.coro.as_mut().unwrap();
        unsafe { (*c).resume() };
    }
    it.fibers.pop();
    let fs = unsafe { &mut *fp };
    // stash fiber's call stack portion
    if fs.status != FiberStatus::Terminated {
        fs.saved_stack = it.call_stack.split_off(base);
        fs.saved_gens = it.gen_stack.split_off(gbase);
    } else {
        it.call_stack.truncate(base);
        it.gen_stack.truncate(gbase);
        fs.coro = None;
    }
    it.cur_file = saved_file;
    it.cur_line = saved_line;
    it.depth = saved_depth;
    if let Some(e) = fs.error.take() {
        return Err(e);
    }
    if fs.status == FiberStatus::Terminated {
        return Ok(Value::Null);
    }
    Ok(std::mem::take(&mut fs.transfer))
}

pub fn fiber_suspend(it: &mut Interp, v: Value) -> R<Value> {
    let fp = match it.fibers.last() {
        Some(f) => *f,
        None => return Err(it.throw_err("FiberError", "Cannot suspend outside of fiber")),
    };
    let fs = unsafe { &mut *fp };
    fs.transfer = v;
    fs.status = FiberStatus::Suspended;
    let line = it.cur_line;
    let file = it.cur_file.clone();
    let depth = it.depth;
    let c: *mut Coro = &mut **fs.coro.as_mut().unwrap();
    unsafe { (*c).suspend() };
    it.cur_line = line;
    it.cur_file = file;
    it.depth = depth;
    let fs = unsafe { &mut *fp };
    fs.status = FiberStatus::Running;
    if let Some(ex) = fs.throw_in.take() {
        return Err(Flow::Throw(ex));
    }
    Ok(std::mem::take(&mut fs.transfer))
}
