                g.key = Value::Int(g.auto_key);
                g.auto_key += 1;
            }
        }
        g.value = val;
        g.sent = Value::Null;
        self.suspend_gen(gp)?;
        let g = unsafe { &mut *gp };
        if g.destroy {
            return Err(Flow::GenDestroy);
        }
        if let Some(ex) = g.throw_in.take() {
            return Err(Flow::Throw(ex));
        }
        Ok(std::mem::take(&mut g.sent))
    }

    fn suspend_gen(&mut self, gp: *mut GenState) -> R<()> {
        let g = unsafe { &mut *gp };
        g.status = GenStatus::Suspended;
        let line = self.cur_line;
        let file = self.cur_file.clone();
        let depth = self.depth;
        // save call stack portion above generator's entry
        let c: *mut Coro = &mut **g.coro.as_mut().unwrap();
        unsafe { (*c).suspend() };
        self.cur_line = line;
        self.cur_file = file;
        self.depth = depth;
        let g = unsafe { &mut *gp };
        g.status = GenStatus::Running;
        Ok(())
    }

    pub fn do_yield_from(&mut self, src: Value) -> R<Value> {
        match src {
            Value::Array(a) => {
                for (k, v) in a.iter() {
                    let gp = *self.gen_stack.last().unwrap();
                    let g = unsafe { &mut *gp };
                    g.key = k.to_value();
                    g.value = v.deref();
                    self.suspend_gen(gp)?;
                    let g = unsafe { &mut *gp };
                    if g.destroy {
                        return Err(Flow::GenDestroy);
                    }
                    if let Some(ex) = g.throw_in.take() {
                        return Err(Flow::Throw(ex));
                    }
                }
                Ok(Value::Null)
            }
            Value::Object(o) if is_generator_obj(&o) => {
                gen_rewind_noerr(self, &o)?;
                loop {
                    if !gen_valid(self, &o)? {
                        break;
                    }
                    let k = gen_key(self, &o)?;
                    let v = gen_current(self, &o)?;
                    let gp = *self.gen_stack.last().unwrap();
                    let g = unsafe { &mut *gp };
                    g.key = k;
                    g.value = v;
                    g.sent = Value::Null;
                    self.suspend_gen(gp)?;
                    let g = unsafe { &mut *gp };
                    if g.destroy {
                        return Err(Flow::GenDestroy);
                    }
                    if let Some(ex) = g.throw_in.take() {
                        gen_throw(self, &o, ex)?;
                        continue;
                    }
                    let sent = std::mem::take(&mut g.sent);
                    gen_send(self, &o, sent)?;
                }
                let ip = gs_ptr(&o);
                Ok(unsafe { (*ip).retval.clone() })
            }
            Value::Object(o) if o.class.instance_of_name("traversable") => {
                let mut items = Vec::new();
                // iterate lazily
                let it_obj = o.clone();
                let mut err = None;
                self.iterate_object(&it_obj, &mut |it, k, v| {
                    let gp = *it.gen_stack.last().unwrap();
                    let g = unsafe { &mut *gp };
                    g.key = k;
                    g.value = v;
                    if let Err(e) = it.suspend_gen(gp) {
                        err = Some(e);
                        return Ok(false);
                    }
                    let g = unsafe { &mut *gp };
                    if g.destroy {
                        err = Some(Flow::GenDestroy);
                        return Ok(false);
                    }
                    if let Some(ex) = g.throw_in.take() {
                        err = Some(Flow::Throw(ex));
                        return Ok(false);
                    }
                    Ok(true)
                })?;
                items.clear();
                if let Some(e) = err {
                    return Err(e);
                }
                Ok(Value::Null)
            }
            _ => Err(self.error("Can use \"yield from\" only with arrays and Traversables")),
        }
    }
}

fn ensure_started(it: &mut Interp, o: &Obj) -> R<()> {
    let gp = gs_ptr(o);
    let g = unsafe { &mut *gp };
    if g.status == GenStatus::NotStarted {
        g.started_once = true;
        resume(it, o)?;
    }
    Ok(())
}

pub fn gen_rewind(it: &mut Interp, o: &Obj) -> R<()> {
    let gp = gs_ptr(o);
    let g = unsafe { &mut *gp };
    if g.advanced {
        return Err(it.throw_err("Exception", "Cannot rewind a generator that was already run"));
    }
    ensure_started(it, o)
}

fn gen_rewind_noerr(it: &mut Interp, o: &Obj) -> R<()> {
    ensure_started(it, o)
}

pub fn gen_valid(it: &mut Interp, o: &Obj) -> R<bool> {
    ensure_started(it, o)?;
    let gp = gs_ptr(o);
    Ok(unsafe { (*gp).status != GenStatus::Done })
}

pub fn gen_current(it: &mut Interp, o: &Obj) -> R<Value> {
    ensure_started(it, o)?;
    let gp = gs_ptr(o);
    let g = unsafe { &*gp };
    if g.status == GenStatus::Done {
        return Ok(Value::Null);
    }
    Ok(g.value.clone())
}

pub fn gen_key(it: &mut Interp, o: &Obj) -> R<Value> {
    ensure_started(it, o)?;
    let gp = gs_ptr(o);
    let g = unsafe { &*gp };
    if g.status == GenStatus::Done {
        return Ok(Value::Null);
    }
    Ok(g.key.clone())
}

pub fn gen_next(it: &mut Interp, o: &Obj) -> R<()> {
    let gp = gs_ptr(o);
    let g = unsafe { &mut *gp };
    if g.status == GenStatus::NotStarted {
        ensure_started(it, o)?;
    }
    let g = unsafe { &mut *gp };
    if g.status == GenStatus::Done {
        return Ok(());
    }
    g.advanced = true;
    g.sent = Value::Null;
    resume(it, o)
}

pub fn gen_send(it: &mut Interp, o: &Obj, v: Value) -> R<Value> {
    let gp = gs_ptr(o);
    let g = unsafe { &mut *gp };
    if g.status == GenStatus::NotStarted {
        ensure_started(it, o)?;
    }
    let g = unsafe { &mut *gp };
    if g.status == GenStatus::Done {
        return Ok(Value::Null);
    }
    g.advanced = true;
    g.sent = v;
    resume(it, o)?;
    let g = unsafe { &*gp };
    if g.status == GenStatus::Done {
        return Ok(Value::Null);
    }
    Ok(g.value.clone())
}

pub fn gen_throw(it: &mut Interp, o: &Obj, ex: Obj) -> R<Value> {
    let gp = gs_ptr(o);
    let g = unsafe { &mut *gp };
    if g.status == GenStatus::NotStarted {
        // throw before start: generator is closed and exception propagates
        g.status = GenStatus::Done;
        g.frame = None;
        return Err(Flow::Throw(ex));
    }
    if g.status == GenStatus::Done {
        return Err(Flow::Throw(ex));
    }
    g.advanced = true;
    g.throw_in = Some(ex);
    resume(it, o)?;
    let g = unsafe { &*gp };
    if g.status == GenStatus::Done {
        return Ok(Value::Null);
    }
    Ok(g.value.clone())
}

pub fn gen_get_return(it: &mut Interp, o: &Obj) -> R<Value> {
    let gp = gs_ptr(o);
    let g = unsafe { &*gp };
    if g.status == GenStatus::Done && g.returned {
        return Ok(g.retval.clone());
    }
    let msg = if g.status == GenStatus::Done {
        "Cannot get return value of a generator that hasn't returned"
    } else {
        "Cannot get return value of a generator that hasn't returned"
    };
    Err(it.throw_err("Exception", msg))
}

pub fn destroy_generator(it: &mut Interp, o: &Obj) -> R<()> {
    let gp = gs_ptr(o);
    if gp.is_null() {
        return Ok(());
    }
    let g = unsafe { &mut *gp };
    if g.status == GenStatus::Suspended && g.coro.is_some() {
        g.destroy = true;
        let r = resume(it, o);
        let g = unsafe { &mut *gp };
        g.coro = None;
        g.status = GenStatus::Done;
        return r;
    }
    Ok(())
}

// ---------------- Fibers ----------------
#[derive(Clone, Copy, PartialEq, Eq)]
pub enum FiberStatus {
    Init,
    Running,
    Suspended,
    Terminated,
}

pub struct FiberState {
    pub coro: Option<Box<Coro>>,
    pub status: FiberStatus,
    pub callable: Value,
    pub transfer: Value,
    pub throw_in: Option<Obj>,
    pub error: Option<Flow>,
    pub retval: Value,
    pub saved_stack: Vec<CallInfo>,
    pub saved_gens: Vec<*mut GenState>,
    pub args: Vec<Value>,
    pub obj: Option<std::rc::Weak<Object>>,
}

pub struct FiberBox(pub Box<FiberState>);

pub fn fiber_ptr(o: &Object) -> *mut FiberState {
    let b = o.internal.borrow();
    match &*b {
        Internal::Any(a) => match a.downcast_ref::<FiberBox>() {
            Some(g) => &*g.0 as *const FiberState as *mut FiberState,
            None => std::ptr::null_mut(),
        },
        _ => std::ptr::null_mut(),
    }
}

pub fn fiber_resume_raw(it: &mut Interp, fp: *mut FiberState) -> R<Value> {
    let fs = unsafe { &mut *fp };
    if fs.coro.is_none() {
        let ip: *mut Interp = it;
        let fpp = fp;
        fs.coro = Some(Coro::new(Box::new(move || unsafe {
            let it = &mut *ip;
            let fs = &mut *fpp;
            let cb = fs.callable.clone();
            let args = std::mem::take(&mut fs.args);
            let r = it.call_value(&cb, args);
            let fs = &mut *fpp;
            match r {
                Ok(v) => fs.retval = v,
                Err(e) => fs.error = Some(e),
            }
            fs.status = FiberStatus::Terminated;
            fs.transfer = Value::Null;
        })));
    }
    fs.status = FiberStatus::Running;
    let base = it.call_stack.len();
    let gbase = it.gen_stack.len();
    let saved = std::mem::take(&mut fs.saved_stack);
    it.call_stack.extend(saved);
    let sg = std::mem::take(&mut fs.saved_gens);
    it.gen_stack.extend(sg);
    let saved_file = it.cur_file.clone();
    let saved_line = it.cur_line;
    let saved_depth = it.depth;
    it.fibers.push(fp);
    {
        let c: *mut Coro = &mut **fs.coro.as_mut().unwrap();
        unsafe { (*c).resume() };
    }
    it.fibers.pop();
    let fs = unsafe { &mut *fp };
    // stash fiber's call stack portion
    if fs.status != FiberStatus::Terminated {
        fs.saved_stack = it.call_stack.split_off(base);
        fs.saved_gens = it.gen_stack.split_off(gbase);
    } else {
        it.call_stack.truncate(base);
        it.gen_stack.truncate(gbase);
        fs.coro = None;
    }
    it.cur_file = saved_file;
    it.cur_line = saved_line;
    it.depth = saved_depth;
    if let Some(e) = fs.error.take() {
        return Err(e);
    }
    if fs.status == FiberStatus::Terminated {
        return Ok(Value::Null);
    }
    Ok(std::mem::take(&mut fs.transfer))
}

pub fn fiber_suspend(it: &mut Interp, v: Value) -> R<Value> {
    let fp = match it.fibers.last() {
        Some(f) => *f,
        None => return Err(it.throw_err("FiberError", "Cannot suspend outside of fiber")),
    };
    let fs = unsafe { &mut *fp };
    fs.transfer = v;
    fs.status = FiberStatus::Suspended;
    let line = it.cur_line;
    let file = it.cur_file.clone();
    let depth = it.depth;
    let c: *mut Coro = &mut **fs.coro.as_mut().unwrap();
    unsafe { (*c).suspend() };
    it.cur_line = line;
    it.cur_file = file;
    it.depth = depth;
    let fs = unsafe { &mut *fp };
    fs.status = FiberStatus::Running;
    if let Some(ex) = fs.throw_in.take() {
        return Err(Flow::Throw(ex));
    }
    Ok(std::mem::take(&mut fs.transfer))
}
