fn real_main(args: Vec<String>) -> i32 {
    let mut i = 1;
    let mut code: Option<String> = None;
    let mut file: Option<String> = None;
    let mut lint = false;
    let mut ini: Vec<(String, String)> = Vec::new();
    let mut script_args: Vec<String> = Vec::new();
    while i < args.len() {
        let a = &args[i];
        if file.is_some() || code.is_some() {
            if a == "--" && script_args.is_empty() {
                i += 1;
                continue;
            }
            script_args.push(a.clone());
            i += 1;
            continue;
        }
        match a.as_str() {
            "-r" => {
                i += 1;
                code = args.get(i).cloned();
            }
            "-f" => {
                i += 1;
                file = args.get(i).cloned();
            }
            "-n" | "-e" | "-H" | "-q" => {}
            "-c" => {
                i += 1;
            }
            "-l" => lint = true,
            "-d" => {
                i += 1;
                if let Some(d) = args.get(i) {
                    let (k, v) = match d.split_once('=') {
                        Some((k, v)) => (k.to_string(), v.to_string()),
                        None => (d.clone(), "1".to_string()),
                    };
                    ini.push((k, v));
                }
            }
            "-v" | "--version" => {
                println!("PHP 8.6.0-dev (cli) (built: Jun 12 2026 00:41:04) (NTS)\nCopyright (c) The PHP Group\nZend Engine v4.6.0-dev, Copyright (c) Zend Technologies\n    with Zend OPcache v8.6.0-dev, Copyright (c), by Zend Technologies");
                return 0;
            }
            "-h" | "--help" => {
                usage();
                return 0;
            }
            "-m" => {
                println!("[PHP Modules]\nCore\ndate\nhash\njson\nlexbor\npcre\nrandom\nReflection\nSPL\nstandard\nuri\nZend OPcache\n\n[Zend Modules]\nZend OPcache\n");
                return 0;
            }
            "--" => {
                i += 1;
                while i < args.len() {
                    script_args.push(args[i].clone());
                    i += 1;
                }
                break;
            }
            _ => {
                if let Some(d) = a.strip_prefix("-d") {
                    let (k, v) = match d.split_once('=') {
                        Some((k, v)) => (k.to_string(), v.to_string()),
                        None => (d.to_string(), "1".to_string()),
                    };
                    ini.push((k, v));
                } else if a.starts_with('-') && a.len() > 1 {
                    // unknown option: ignore
                } else {
                    file = Some(a.clone());
                }
            }
        }
        i += 1;
    }

    let (src, fname, php_mode, display_name): (Vec<u8>, String, bool, String) = if let Some(c) = &code {
        (c.as_bytes().to_vec(), "Command line code".to_string(), true, "Standard input code".to_string())
    } else if let Some(f) = &file {
        match std::fs::read(f) {
            Ok(s) => {
                let real = std::fs::canonicalize(f).map(|p| p.to_string_lossy().to_string()).unwrap_or(f.clone());
                (s, real, false, f.clone())
            }
            Err(_) => {
                println!("Could not open input file: {}", f);
                return 1;
            }
        }
    } else {
        use std::io::Read;
        let mut s = Vec::new();
        let _ = std::io::stdin().read_to_end(&mut s);
        (s, "Standard input code".to_string(), false, "-".to_string())
    };

    // strip shebang
    let src = if !php_mode && src.starts_with(b"#!") {
        match src.iter().position(|&c| c == b'\n') {
            Some(p) => src[p + 1..].to_vec(),
            None => Vec::new(),
        }
    } else {
        src
    };
    let shebang_offset = 0;
    let _ = shebang_offset;

    let prog = match compile_source(&src, &fname, php_mode) {
        Ok(p) => p,
        Err((msg, line)) => {
            let shown = if lint { display_name.clone() } else { fname.clone() };
            print!("\nParse error: {} in {} on line {}\n", msg, shown, line);
            if lint {
                println!("Errors parsing {}", display_name);
            }
            return 255;
        }
    };
    if lint {
        println!("No syntax errors detected in {}", display_name);
        return 0;
    }

    let mut it = Interp::new();
    for (k, v) in ini {
        it.ini.insert(k.clone(), v.clone());
        if k == "precision" {
            it.precision = v.parse().unwrap_or(14);
        }
        if k == "serialize_precision" {
            it.serialize_precision = v.parse().unwrap_or(-1);
        }
        if k == "error_reporting" {
            it.error_reporting = v.parse().unwrap_or(32767);
        }
    }
    // prelude
    match compile_source(PRELUDE.as_bytes(), "[internal]", false) {
        Ok(p) => {
            let p = Rc::new(p);
            if it.run_prelude(&p).is_err() {
                eprintln!("prelude failed");
            }
        }
        Err((m, l)) => {
            eprintln!("prelude parse error: {} line {}", m, l);
            return 1;
        }
    }
    it.prelude_done = true;
    let mut argv = vec![if code.is_some() { "Standard input code".to_string() } else { file.clone().unwrap_or("Standard input code".to_string()) }];
    if code.is_some() {
        argv[0] = "Standard input code".to_string();
    }
    argv.extend(script_args);
    it.argv = argv;
    let r = it.run_main(Rc::new(prog), fname);
    it.flush();
    r
}
