pub struct ClosureData {
    pub decl: Option<Rc<FuncDecl>>,
    pub builtin: Option<&'static BuiltinDef>,
    pub method: Option<(Rc<Method>, Rc<Class>)>,
    pub this: Option<Obj>,
    pub scope: Option<Rc<Class>>,
    pub called_scope: Option<Rc<Class>>,
    pub bound: Vec<(u32, Value)>,
    pub statics: RefCell<HashMap<usize, PRef>>,
}

pub fn is_closure(o: &Object) -> bool {
    &*o.class.lname == "closure"
}

pub fn closure_decl(o: &Obj) -> Option<Rc<FuncDecl>> {
    o.with_internal::<ClosureData, _>(|c| {
        if let Some(d) = &c.decl {
            return Some(d.clone());
        }
        if let Some((m, _)) = &c.method {
            return m.user().cloned();
        }
        None
    })
    .flatten()
}

pub fn closure_builtin(o: &Obj) -> Option<&'static BuiltinDef> {
    o.with_internal::<ClosureData, _>(|c| c.builtin).flatten()
}

pub fn closure_static(o: &Obj, key: usize) -> Option<PRef> {
    o.with_internal::<ClosureData, _>(|c| c.statics.borrow().get(&key).cloned()).flatten()
}
pub fn closure_static_set(o: &Obj, key: usize, r: PRef) {
    o.with_internal::<ClosureData, _>(|c| {
        c.statics.borrow_mut().insert(key, r);
    });
}

pub fn new_closure(it: &mut Interp, data: ClosureData) -> Obj {
