cd /workspace/src/builtins && cat > classes.rs <<'EOF'
use super::*;
use crate::array::{Key, PArray};
use crate::ast::*;
use crate::interp::calls::CallCtx;
use crate::interp::gen;
use crate::object::*;
use std::cell::RefCell;
use std::collections::HashMap;

pub struct ClosureData {
    pub decl: Option<Rc<FuncDecl>>,
    pub builtin: Option<&'static BuiltinDef>,
    pub method: Option<(Rc<Method>, Rc<Class>)>,
    pub this: Option<Obj>,
    pub scope: Option<Rc<Class>>,
    pub called_scope: Option<Rc<Class>>,
    pub bound: Vec<(u32, Value)>,
    pub statics: RefCell<HashMap<usize, PRef>>,
}

pub fn is_closure(o: &Object) -> bool {
    &*o.class.lname == "closure"
}

pub fn closure_decl(o: &Obj) -> Option<Rc<FuncDecl>> {
    o.with_internal::<ClosureData, _>(|c| {
        if let Some(d) = &c.decl {
            return Some(d.clone());
        }
        if let Some((m, _)) = &c.method {
            return m.user().cloned();
        }
        None
    })
    .flatten()
}

pub fn closure_builtin(o: &Obj) -> Option<&'static BuiltinDef> {
    o.with_internal::<ClosureData, _>(|c| c.builtin).flatten()
}

pub fn closure_static(o: &Obj, key: usize) -> Option<PRef> {
    o.with_internal::<ClosureData, _>(|c| c.statics.borrow().get(&key).cloned()).flatten()
}
pub fn closure_static_set(o: &Obj, key: usize, r: PRef) {
    o.with_internal::<ClosureData, _>(|c| {
        c.statics.borrow_mut().insert(key, r);
    });
}

pub fn new_closure(it: &mut Interp, data: ClosureData) -> Obj {
    let cls = it.classes.get(&b"closure"[..]).cloned().unwrap();
    let o = Object::new(cls, Vec::new());
    o.set_internal(data);
    o
}

impl Interp {
    pub fn make_closure(&mut self, f: &mut Frame, decl: &Rc<FuncDecl>, uses: &[(VarRef, VarRef, bool)], is_static: bool) -> R<Value> {
        let mut bound = Vec::with_capacity(uses.len());
        for (outer, inner, by_ref) in uses {
            if *by_ref {
                let i = f.idx(outer);
                if i >= f.slots.len() {
                    f.sync();
                }
                let r = crate::interp::lval::wrap_ref(&mut f.slots[i]);
                bound.push((inner.slot, Value::Ref(r)));
            } else {
                let i = f.idx(outer);
                let v = match f.slots.get(i) {
                    Some(Value::Undef) | None => {
                        self.warn(&format!("Undefined variable ${}", outer.name))?;
                        Value::Null
                    }
                    Some(v) => v.deref(),
                };
                bound.push((inner.slot, v));
            }
        }
        let this = if is_static { None } else { f.this.clone() };
        let data = ClosureData {
            decl: Some(decl.clone()),
            builtin: None,
            method: None,
            this,
            scope: f.class.clone(),
            called_scope: f.static_class.clone().or(f.class.clone()),
            bound,
            statics: RefCell::new(HashMap::new()),
        };
        Ok(Value::Object(new_closure(self, data)))
    }

    pub fn make_arrow_fn(&mut self, f: &mut Frame, decl: &Rc<FuncDecl>, caps: &[(u32, u32)], is_static: bool) -> R<Value> {
        let mut bound = Vec::with_capacity(caps.len());
        for (outer, inner) in caps {
            let i = match &f.remap {
                None => *outer as usize,
                Some(m) => m[*outer as usize] as usize,
            };
            if let Some(v) = f.slots.get(i) {
                if !v.is_undef() {
                    let v = v.deref();
                    if !v.is_undef() {
                        bound.push((*inner, v));
                    }
                }
            }
        }
        let this = if is_static { None } else { f.this.clone() };
        let data = ClosureData {
            decl: Some(decl.clone()),
            builtin: None,
            method: None,
            this,
            scope: f.class.clone(),
            called_scope: f.static_class.clone().or(f.class.clone()),
            bound,
            statics: RefCell::new(HashMap::new()),
        };
        Ok(Value::Object(new_closure(self, data)))
    }

    /// first-class callable syntax
    pub fn eval_callable_ref(&mut self, f: &mut Frame, inner: &Expr) -> R<Value> {
        match &inner.kind {
            ExprKind::Call(fname, _) => {
                let c = self.resolve_func(fname)?;
                let data = match c {
                    Callable::User(d) => ClosureData { decl: Some(d), builtin: None, method: None, this: None, scope: None, called_scope: None, bound: vec![], statics: RefCell::new(HashMap::new()) },
                    Callable::Builtin(b) => ClosureData { decl: None, builtin: Some(b), method: None, this: None, scope: None, called_scope: None, bound: vec![], statics: RefCell::new(HashMap::new()) },
                };
                Ok(Value::Object(new_closure(self, data)))
            }
            ExprKind::MethodCall(base, name, _, _) => {
                let b = self.eval(f, base)?;
                let n = self.member_name(f, name)?;
                match b {
                    Value::Object(o) => self.closure_from_method(&o, &String::from_utf8_lossy(&n), f.class.clone()),
                    other => {
                        let msg = format!("Call to a member function {}() on {}", String::from_utf8_lossy(&n), other.type_name());
                        Err(self.error(&msg))
                    }
                }
            }
            ExprKind::StaticCall(cref, name, _) => {
                let cls = self.resolve_class_ref(f, cref, true)?;
                let n = self.member_name(f, name)?;
                let ln = String::from_utf8_lossy(&n.to_ascii_lowercase()).to_string();
                match cls.find_method(&ln).cloned() {
                    Some(m) => {
                        let this = if !m.is_static { f.this.clone() } else { None };
                        let sc = if matches!(cref, ClassRef::Static | ClassRef::SelfRef | ClassRef::Parent) { f.static_class.clone().unwrap_or(cls.clone()) } else { cls.clone() };
                        let data = ClosureData { decl: m.user().cloned(), builtin: None, method: Some((m.clone(), sc.clone())), this, scope: Some(m.scope_class()), called_scope: Some(sc), bound: vec![], statics: RefCell::new(HashMap::new()) };
                        Ok(Value::Object(new_closure(self, data)))
                    }
                    None => {
                        let msg = format!("Call to undefined method {}::{}()", cls.name, String::from_utf8_lossy(&n));
                        Err(self.error(&msg))
                    }
                }
            }
            ExprKind::CallExpr(callee, _) => {
                let v = self.eval(f, callee)?;
                self.closure_from_callable(&v)
            }
            _ => Err(self.error("Cannot create closure")),
        }
    }

    pub fn closure_from_method(&mut self, o: &Obj, name: &str, _scope: Option<Rc<Class>>) -> R<Value> {
        let ln = name.to_ascii_lowercase();
        if is_closure(o) && ln == "__invoke" {
            return Ok(Value::Object(o.clone()));
        }
        match o.class.find_method(&ln).cloned() {
            Some(m) => {
                let data = ClosureData {
                    decl: m.user().cloned(),
                    builtin: None,
                    method: Some((m.clone(), o.class.clone())),
                    this: if m.is_static { None } else { Some(o.clone()) },
                    scope: Some(m.scope_class()),
                    called_scope: Some(o.class.clone()),
                    bound: vec![],
                    statics: RefCell::new(HashMap::new()),
                };
                Ok(Value::Object(new_closure(self, data)))
            }
            None => {
                if let Some(call) = o.class.magic.call.clone() {
                    // closure calling __call with name
                    let data = ClosureData {
                        decl: None,
                        builtin: None,
                        method: Some((call, o.class.clone())),
                        this: Some(o.clone()),
                        scope: Some(o.class.clone()),
                        called_scope: Some(o.class.clone()),
                        bound: vec![(u32::MAX, Value::str(name))],
                        statics: RefCell::new(HashMap::new()),
                    };
                    return Ok(Value::Object(new_closure(self, data)));
                }
                let msg = format!("Call to undefined method {}::{}()", o.class.name, name);
                Err(self.error(&msg))
            }
        }
    }

    pub fn closure_from_callable(&mut self, v: &Value) -> R<Value> {
        match v {
            Value::Object(o) if is_closure(o) => Ok(v.clone()),
            Value::Object(o) => {
                if o.class.magic.invoke.is_some() {
                    return self.closure_from_method(o, "__invoke", None);
                }
                Err(self.type_error("Failed to create closure from callable: no array or string given"))
            }
            Value::Str(s) => {
                let st = String::from_utf8_lossy(s).to_string();
                if let Some(p) = st.find("::") {
                    let cls = self.lookup_class(st[..p].as_bytes())?;
                    let ln = st[p + 2..].to_ascii_lowercase();
                    if let Some(m) = cls.find_method(&ln).cloned() {
                        let data = ClosureData { decl: m.user().cloned(), builtin: None, method: Some((m.clone(), cls.clone())), this: None, scope: Some(m.scope_class()), called_scope: Some(cls.clone()), bound: vec![], statics: RefCell::new(HashMap::new()) };
                        return Ok(Value::Object(new_closure(self, data)));
                    }
                }
                match self.functions.get(&crate::interp::lc(st.trim_start_matches('\\'))).cloned() {
                    Some(Callable::User(d)) => Ok(Value::Object(new_closure(self, ClosureData { decl: Some(d), builtin: None, method: None, this: None, scope: None, called_scope: None, bound: vec![], statics: RefCell::new(HashMap::new()) }))),
                    Some(Callable::Builtin(b)) => Ok(Value::Object(new_closure(self, ClosureData { decl: None, builtin: Some(b), method: None, this: None, scope: None, called_scope: None, bound: vec![], statics: RefCell::new(HashMap::new()) }))),
                    None => {
                        let msg = format!("Failed to create closure from callable: function \"{}\" not found or invalid function name", st);
                        Err(self.type_error(&msg))
                    }
                }
            }
            Value::Array(a) if a.len() == 2 => {
                let t = a.get_int(0).cloned().unwrap_or(Value::Null).deref();
                let m = a.get_int(1).cloned().unwrap_or(Value::Null).deref();
                let mn = String::from_utf8_lossy(&m.to_bytes_simple()).to_string();
                match t {
                    Value::Object(o) => self.closure_from_method(&o, &mn, None),
                    Value::Str(cn) => {
                        let cls = self.lookup_class(&cn)?;
                        match cls.find_method(&mn.to_ascii_lowercase()).cloned() {
                            Some(m) => {
                                let data = ClosureData { decl: m.user().cloned(), builtin: None, method: Some((m.clone(), cls.clone())), this: None, scope: Some(m.scope_class()), called_scope: Some(cls.clone()), bound: vec![], statics: RefCell::new(HashMap::new()) };
                                Ok(Value::Object(new_closure(self, data)))
                            }
                            None => {
                                let msg = format!("Failed to create closure from callable: class {} does not have a method \"{}\"", cls.name, mn);
                                Err(self.type_error(&msg))
                            }
                        }
                    }
                    _ => Err(self.type_error("Failed to create closure from callable")),
                }
            }
            _ => Err(self.type_error("Failed to create closure from callable: no array or string given")),
        }
    }
}

pub fn call_closure(it: &mut Interp, o: &Obj, args: Vec<Value>, named: Vec<(Name, Value)>, line: u32) -> R<Value> {
    let info = o.with_internal::<ClosureData, _>(|c| (c.decl.clone(), c.builtin, c.method.clone(), c.this.clone(), c.scope.clone(), c.called_scope.clone(), c.bound.clone()));
    let (decl, builtin, method, this, scope, called, bound) = match info {
        Some(i) => i,
        None => return Err(it.error("Closure object is not initialized")),
    };
    if let Some(b) = builtin {
        let mut av = args;
        for (i, a) in av.iter_mut().enumerate() {
            if b.by_ref(i) && !matches!(a, Value::Ref(_)) {
                let v = std::mem::take(a);
                *a = Value::Ref(Rc::new(RefCell::new(v)));
            }
        }
        return it.call_builtin(b, av, named, line);
    }
    if let Some((m, cls)) = &method {
        if let Some((u32::MAX, nv)) = bound.first().cloned() {
            // __call trampoline
            let arr = Value::arr(PArray::from_values(args));
            return it.call_method_obj(this.as_ref().unwrap(), m, vec![nv, arr]);
        }
        match &m.imp {
            MethodImpl::User(d) => {
                let ctx = CallCtx {
                    this: if m.is_static { None } else { this },
                    class: Some(m.scope_class()),
                    static_class: Some(cls.clone()),
                    closure: None,
                    disp_class: Some(m.decl_class_name.clone()),
                    call_type: if m.is_static { "::" } else { "->" },
                    bound_vars: None,
                };
                return it.call_user(d, args, named, ctx, line);
            }
            MethodImpl::Builtin(bf) => {
                return it.call_builtin_method(m, *bf, this.as_ref(), args, cls, line);
            }
        }
    }
    let decl = decl.unwrap();
    let disp_class = scope.as_ref().map(|c| c.name.clone());
    let ctx = CallCtx {
        this,
        class: scope,
        static_class: called,
        closure: Some(o.clone()),
        disp_class,
        call_type: if o.with_internal::<ClosureData, _>(|c| c.this.is_some()).unwrap_or(false) { "->" } else { "::" },
        bound_vars: Some(bound),
    };
    let ctx = if ctx.disp_class.is_none() { CallCtx { call_type: "", ..ctx } } else { ctx };
    it.call_user(&decl, args, named, ctx, line)
}

// ---------------- enums ----------------
pub fn add_enum_methods(cls: &Rc<Class>) {
    // safety: called right after construction before sharing
    let p = Rc::as_ptr(cls) as *mut Class;
    let weak = Rc::downgrade(cls);
    let mk = |name: &str, f: BuiltinMethod| {
        Rc::new(Method {
            name: Rc::from(name),
            lname: Rc::from(name.to_ascii_lowercase().as_str()),
            class: weak.clone(),
            decl_class_name: cls.name.clone(),
            vis: Visibility::Public,
            is_static: true,
            is_abstract: false,
            is_final: false,
            imp: MethodImpl::Builtin(f),
            proto: None,
            builtin_params: None,
        })
    };
    unsafe {
        let c = &mut *p;
        c.methods.insert(Rc::from("cases"), mk("cases", enum_cases));
        c.method_order.retain(|n| &**n != "cases");
        c.method_order.insert(0, Rc::from("cases"));
        if c.enum_backing.is_some() {
            c.methods.insert(Rc::from("from"), mk("from", enum_from));
            c.methods.insert(Rc::from("tryfrom"), mk("tryFrom", enum_tryfrom));
            c.method_order.retain(|n| &**n != "from" && &**n != "tryfrom");
            c.method_order.insert(1, Rc::from("from"));
            c.method_order.insert(2, Rc::from("tryfrom"));
        }
    }
}

pub fn enum_case(it: &mut Interp, cls: &Rc<Class>, name: &str) -> R<Obj> {
    if let Some(o) = cls.enum_cases.borrow().get(name) {
        return Ok(o.clone());
    }
    let decl = cls.decl.clone().unwrap();
    let case = decl.cases.iter().find(|c| &*c.name == name).unwrap();
    let o = Object::new(cls.clone(), vec![Value::Undef; cls.slots.len()]);
    o.flags.set(o.flags.get() | OBJ_NO_DTOR);
    // name/value props as dynamic-like declared
    let mut d = PArray::new();
    d.set(Key::Str(Rc::new(b"name".to_vec())), Value::str(name));
    if let Some(ve) = &case.value {
        let v = it.eval_in_class(cls, ve)?;
        d.set(Key::Str(Rc::new(b"value".to_vec())), v);
    }
    *o.dynamic.borrow_mut() = Some(d);
    cls.enum_cases.borrow_mut().insert(Rc::from(name), o.clone());
    Ok(o)
}

fn enum_cases(it: &mut Interp, _this: Option<&Obj>, _args: &mut Vec<Value>, cls: &Rc<Class>) -> R<Value> {
    let mut out = PArray::new();
    let names = cls.case_names.clone();
    for n in names {
        out.push(Value::Object(enum_case(it, cls, &n)?));
    }
    Ok(Value::arr(out))
}

fn enum_lookup(it: &mut Interp, args: &mut Vec<Value>, cls: &Rc<Class>, try_: bool) -> R<Value> {
    let v = args.first().cloned().unwrap_or(Value::Null).deref();
    let is_int = cls.enum_backing.as_deref() == Some("int");
    let v = if is_int {
        match &v {
            Value::Int(_) => v,
            Value::Str(s) => match str_numeric(s) {
                Some(Num::Int(i)) => Value::Int(i),
                _ => {
                    let msg = format!("{}::{}(): Argument #1 ($value) must be of type int, string given", cls.name, if try_ { "tryFrom" } else { "from" });
                    return Err(it.type_error(&msg));
                }
            },
            Value::Float(f) if f.fract() == 0.0 => Value::Int(*f as i64),
            _ => {
                let msg = format!("{}::{}(): Argument #1 ($value) must be of type int, {} given", cls.name, if try_ { "tryFrom" } else { "from" }, v.type_name());
                return Err(it.type_error(&msg));
            }
        }
    } else {
        match &v {
            Value::Str(_) => v,
            Value::Int(_) | Value::Float(_) => Value::Str(it.to_str(&v)?),
            _ => {
                let msg = format!("{}::{}(): Argument #1 ($value) must be of type string, {} given", cls.name, if try_ { "tryFrom" } else { "from" }, v.type_name());
                return Err(it.type_error(&msg));
            }
        }
    };
    let names = cls.case_names.clone();
    for n in names {
        let o = enum_case(it, cls, &n)?;
        let cv = it.get_prop_raw(&o, "value");
        if crate::interp::ops::strict_equals(&cv, &v) {
            return Ok(Value::Object(o));
        }
    }
    if try_ {
        return Ok(Value::Null);
    }
    let shown = match &v {
        Value::Str(s) => {
            let mut d = Vec::new();
            super::output::export_str(&mut d, s);
            String::from_utf8_lossy(&d).to_string()
        }
        other => other.to_string_lossy(),
    };
    let msg = format!("{} is not a valid backing value for enum {}", shown, cls.name);
    Err(it.value_error(&msg))
}

fn enum_from(it: &mut Interp, _this: Option<&Obj>, args: &mut Vec<Value>, cls: &Rc<Class>) -> R<Value> {
    enum_lookup(it, args, cls, false)
}
fn enum_tryfrom(it: &mut Interp, _this: Option<&Obj>, args: &mut Vec<Value>, cls: &Rc<Class>) -> R<Value> {
    enum_lookup(it, args, cls, true)
}

pub fn init_internal(_it: &mut Interp, _o: &Obj) {}

pub fn clone_internal(_it: &mut Interp, src: &Obj, dst: &Obj) {
    if is_closure(src) {
        let d = src.with_internal::<ClosureData, _>(|c| ClosureData {
            decl: c.decl.clone(),
            builtin: c.builtin,
            method: c.method.clone(),
            this: c.this.clone(),
            scope: c.scope.clone(),
            called_scope: c.called_scope.clone(),
            bound: c.bound.clone(),
            statics: RefCell::new(c.statics.borrow().clone()),
        });
        if let Some(d) = d {
            dst.set_internal(d);
        }
    }
    super::spl::clone_internal(src, dst);
}

// ---------------- builtin helper functions used by the prelude ----------------
fn f_closure_bind(it: &mut Interp, a: &mut Args) -> R<Value> {
    let c = a.obj(it, 0)?;
    let new_this = a.get(1);
    let scope_arg = if a.has(2) { Some(a.get(2)) } else { None };
    let d = c.with_internal::<ClosureData, _>(|d| (d.decl.clone(), d.builtin, d.method.clone(), d.this.clone(), d.scope.clone(), d.called_scope.clone(), d.bound.clone(), d.statics.borrow().clone()));
    let (decl, builtin, method, _this, scope, _called, bound, statics) = match d {
        Some(d) => d,
        None => return Ok(Value::Null),
    };
    let new_scope = match scope_arg {
        None => scope.clone(),
        Some(Value::Object(o)) => Some(o.class.clone()),
        Some(Value::Str(s)) if s.as_slice() == b"static" => scope.clone(),
        Some(Value::Null) => None,
        Some(v) => {
            let s = it.to_str(&v)?;
            Some(it.lookup_class(&s)?)
        }
    };
    let nt = match new_this {
        Value::Object(o) => {
            if decl.as_ref().map(|d| d.is_static).unwrap_or(false) {
                it.warn("Cannot bind an instance to a static closure")?;
                return Ok(Value::Null);
            }
            Some(o)
        }
        _ => None,
    };
    let called = match &nt {
        Some(o) => Some(o.class.clone()),
        None => new_scope.clone(),
    };
    let data = ClosureData { decl, builtin, method, this: nt, scope: new_scope, called_scope: called, bound, statics: RefCell::new(statics) };
    Ok(Value::Object(new_closure(it, data)))
}

fn f_closure_call(it: &mut Interp, a: &mut Args) -> R<Value> {
    let c = a.obj(it, 0)?;
    let nt = a.obj(it, 1)?;
    let rest: Vec<Value> = a.v[2..].iter().map(|v| v.deref()).collect();
    let d = c.with_internal::<ClosureData, _>(|d| (d.decl.clone(), d.bound.clone(), d.statics.borrow().clone()));
    let (decl, bound, statics) = match d {
        Some(d) => d,
        None => return Ok(Value::Null),
    };
    let data = ClosureData { decl, builtin: None, method: None, this: Some(nt.clone()), scope: Some(nt.class.clone()), called_scope: Some(nt.class.clone()), bound, statics: RefCell::new(statics) };
    let nc = new_closure(it, data);
    let line = it.cur_line;
    call_closure(it, &nc, rest, Vec::new(), line)
}

fn f_closure_from_callable(it: &mut Interp, a: &mut Args) -> R<Value> {
    let v = a.get(0);
    it.closure_from_callable(&v)
}

fn f_closure_invoke(it: &mut Interp, a: &mut Args) -> R<Value> {
    let c = a.obj(it, 0)?;
    let rest: Vec<Value> = a.v[1..].to_vec();
    let line = it.cur_line;
    call_closure(it, &c, rest, Vec::new(), line)
}

fn exc_frame_str(it: &mut Interp, fr: &Value, out: &mut Vec<u8>) -> R<()> {
    let fr = match fr {
        Value::Array(a) => a.clone(),
        _ => return Ok(()),
    };
    let g = |k: &str| fr.get(&Key::Str(Rc::new(k.as_bytes().to_vec()))).map(|v| v.deref());
    match g("file") {
        Some(Value::Str(f)) => {
            out.extend_from_slice(&f);
            out.push(b'(');
            let l = g("line").map(|v| v.to_int()).unwrap_or(0);
            out.extend_from_slice(l.to_string().as_bytes());
            out.extend_from_slice(b"): ");
        }
        _ => out.extend_from_slice(b"[internal function]: "),
    }
    if let Some(c) = g("class") {
        out.extend_from_slice(&c.to_bytes_simple());
        out.extend_from_slice(&g("type").map(|v| v.to_bytes_simple()).unwrap_or_default());
    }
    out.extend_from_slice(&g("function").map(|v| v.to_bytes_simple()).unwrap_or_default());
    out.push(b'(');
    if let Some(Value::Array(args)) = g("args") {
        let mut first = true;
        for (_, v) in args.iter() {
            if !first {
                out.extend_from_slice(b", ");
            }
            first = false;
            match v.deref() {
                Value::Null | Value::Undef => out.extend_from_slice(b"NULL"),
                Value::Bool(b) => out.extend_from_slice(if b { b"true" } else { b"false" }),
                Value::Int(i) => out.extend_from_slice(i.to_string().as_bytes()),
                Value::Float(f) => out.extend_from_slice(fmt_float_prec(f, 17).as_bytes()),
                Value::Str(s) => {
                    out.push(b'\'');
                    if s.len() > 15 {
                        out.extend_from_slice(&s[..15]);
                        out.extend_from_slice(b"...");
                    } else {
                        out.extend_from_slice(&s);
                    }
                    out.push(b'\'');
                }
                Value::Array(_) => out.extend_from_slice(b"Array"),
                Value::Object(o) => {
                    out.extend_from_slice(b"Object(");
                    out.extend_from_slice(o.class.name.as_bytes());
                    out.push(b')');
                }
                Value::Ref(_) => {}
            }
        }
    }
    out.push(b')');
    let _ = it;
    Ok(())
}

pub fn trace_string(it: &mut Interp, trace: &Value) -> R<Vec<u8>> {
    let mut out = Vec::new();
    let mut n = 0;
    if let Value::Array(a) = trace {
        for (_, fr) in a.iter() {
            out.push(b'#');
            out.extend_from_slice(n.to_string().as_bytes());
            out.push(b' ');
            exc_frame_str(it, &fr.deref(), &mut out)?;
            out.push(b'\n');
            n += 1;
        }
    }
    out.push(b'#');
    out.extend_from_slice(n.to_string().as_bytes());
    out.extend_from_slice(b" {main}");
    Ok(out)
}

fn f_exc_trace_string(it: &mut Interp, a: &mut Args) -> R<Value> {
    let o = a.obj(it, 0)?;
    let t = it.get_prop_raw(&o, "trace");
    Ok(Value::vec(trace_string(it, &t)?))
}

pub fn exception_to_string(it: &mut Interp, o: &Obj) -> R<Vec<u8>> {
    let mut s: Vec<u8> = Vec::new();
    let mut cur = Some(o.clone());
    let mut guard = 0;
    while let Some(e) = cur {
        guard += 1;
        if guard > 100 {
            break;
        }
        if !e.class.instance_of_name("throwable") {
            break;
        }
        let prev_str = std::mem::take(&mut s);
        let msg = it.get_prop_raw(&e, "message");
        let mut msg = it.to_str(&msg)?.to_vec();
        let file = it.get_prop_raw(&e, "file").to_bytes_simple();
        let line = it.get_prop_raw(&e, "line").to_int();
        let trace = match e.class.find_method("gettraceasstring").cloned() {
            Some(m) => it.call_method_obj(&e, &m, vec![])?.to_bytes_simple(),
            None => b"#0 {main}".to_vec(),
        };
        let ln = &*e.class.lname;
        if (ln == "typeerror" || ln == "argumentcounterror") && msg.windows(12).any(|w| w == b", called in ") {
            msg.extend_from_slice(b" and defined");
        }
        s.extend_from_slice(e.class.name.as_bytes());
        if !msg.is_empty() {
            s.extend_from_slice(b": ");
            s.extend_from_slice(&msg);
        }
        s.extend_from_slice(b" in ");
        s.extend_from_slice(&file);
        s.push(b':');
        s.extend_from_slice(line.to_string().as_bytes());
        s.extend_from_slice(b"\nStack trace:\n");
        s.extend_from_slice(&trace);
        if !prev_str.is_empty() {
            s.extend_from_slice(b"\n\nNext ");
            s.extend_from_slice(&prev_str);
        }
        cur = match it.get_prop_raw(&e, "previous") {
            Value::Object(p) => Some(p),
            _ => None,
        };
    }
    it.set_prop_raw(o, "string", Value::vec(s.clone()));
    Ok(s)
}

fn f_exc_to_string(it: &mut Interp, a: &mut Args) -> R<Value> {
    let o = a.obj(it, 0)?;
    Ok(Value::vec(exception_to_string(it, &o)?))
}

fn f_exc_construct(it: &mut Interp, a: &mut Args) -> R<Value> {
    let o = a.obj(it, 0)?;
    let cname = o.class.name.to_string();
    if a.has(1) {
        let m = a.get(1);
        match m {
            Value::Str(_) => it.set_prop_raw(&o, "message", m),
            Value::Null => {}
            Value::Int(_) | Value::Float(_) | Value::Bool(_) => {
                let s = it.to_str(&m)?;
                it.set_prop_raw(&o, "message", Value::Str(s));
            }
            other => {
                let msg = format!("{}::__construct(): Argument #1 ($message) must be of type string, {} given", cname, other.type_name_ex());
                return Err(it.type_error(&msg));
            }
        }
    }
    if a.has(2) {
        let c = a.get(2);
        match c {
            Value::Int(_) => it.set_prop_raw(&o, "code", c),
            Value::Null => {}
            Value::Bool(b) => it.set_prop_raw(&o, "code", Value::Int(b as i64)),
            Value::Float(f) => it.set_prop_raw(&o, "code", Value::Int(f as i64)),
            Value::Str(ref s) if str_numeric(s).is_some() => it.set_prop_raw(&o, "code", Value::Int(c.to_int())),
            other => {
                let msg = format!("{}::__construct(): Argument #2 ($code) must be of type int, {} given", cname, other.type_name_ex());
                return Err(it.type_error(&msg));
            }
        }
    }
    if a.has(3) {
        let p = a.get(3);
        match &p {
            Value::Null => {}
            Value::Object(po) if po.class.instance_of_name("throwable") => it.set_prop_raw(&o, "previous", p.clone()),
            other => {
                let msg = format!("{}::__construct(): Argument #3 ($previous) must be of type ?Throwable, {} given", cname, other.type_name_ex());
                return Err(it.type_error(&msg));
            }
        }
    }
    Ok(Value::Null)
}

fn f_errorexc_construct(it: &mut Interp, a: &mut Args) -> R<Value> {
    let o = a.obj(it, 0)?;
    if a.has(1) {
        let m = a.get(1);
