use super::*;
use crate::array::{Key, PArray};
use crate::ast::{ClassKind, Visibility};
use crate::object::*;

pub fn export_str(out: &mut Vec<u8>, s: &[u8]) {
    out.push(b'\'');
    let mut i = 0;
    while i < s.len() {
        let c = s[i];
        match c {
            b'\'' => out.extend_from_slice(b"\\'"),
            b'\\' => out.extend_from_slice(b"\\\\"),
            0 => out.extend_from_slice(b"' . \"\\0\" . '"),
            _ => out.push(c),
        }
        i += 1;
    }
    out.push(b'\'');
}

fn spaces(out: &mut Vec<u8>, n: usize) {
    for _ in 0..n {
        out.push(b' ');
    }
}

pub struct PropEntry {
    pub name: Vec<u8>,
    pub vis: Visibility,
    pub class: Name,
    pub val: Value,
    pub uninit_type: Option<String>,
}

/// properties for dumping, in order
pub fn dump_props(it: &mut Interp, o: &Obj, use_debuginfo: bool) -> R<(Vec<PropEntry>, bool)> {
    if use_debuginfo {
        if let Some(m) = o.class.magic.debuginfo.clone() {
