            match v {
                Value::Array(a) => {
                    let mut out = Vec::new();
                    for (k, v) in a.iter() {
                        out.push(PropEntry { name: k.as_bytes(), vis: Visibility::Public, class: Rc::from(""), val: v.clone(), uninit_type: None });
                    }
                    return Ok((out, true));
                }
                Value::Null => return Ok((Vec::new(), true)),
                _ => {
                    return Err(it.fatal("__debuginfo() must return an array"));
                }
            }
        }
    }
    let mut out = Vec::new();
    if is_closure_obj(o) {
        return Ok((closure_debug(it, o), true));
    }
    let slots = o.slots.borrow();
    for info in o.class.slots.iter() {
        if info.is_virtual {
            continue;
        }
        let v = &slots[info.slot];
        if v.is_undef() {
            if let Some(t) = &info.ty {
                out.push(PropEntry { name: info.name.as_bytes().to_vec(), vis: info.vis, class: info.decl_class.clone(), val: Value::Undef, uninit_type: Some(crate::interp::calls::type_to_string(t)) });
            }
            continue;
        }
        out.push(PropEntry { name: info.name.as_bytes().to_vec(), vis: info.vis, class: info.decl_class.clone(), val: v.clone(), uninit_type: None });
    }
    drop(slots);
    if let Some(d) = &*o.dynamic.borrow() {
        for (k, v) in d.iter() {
            out.push(PropEntry { name: k.as_bytes(), vis: Visibility::Public, class: Rc::from(""), val: v.clone(), uninit_type: None });
        }
    }
    Ok((out, false))
}

fn is_closure_obj(o: &Obj) -> bool {
    &*o.class.lname == "closure"
}

fn closure_debug(_it: &mut Interp, o: &Obj) -> Vec<PropEntry> {
    let mut out = Vec::new();
    let info = o.with_internal::<super::classes::ClosureData, _>(|c| (c.decl.clone(), c.this.clone(), c.bound.clone(), c.builtin.map(|b| b.name), c.method.clone()));
    if let Some((decl, this, bound, bname, method)) = info {
        let mk = |n: &str, v: Value| PropEntry { name: n.as_bytes().to_vec(), vis: Visibility::Public, class: Rc::from(""), val: v, uninit_type: None };
        if let Some(b) = bname {
            out.push(mk("function", Value::str(b)));
            return out;
        }
        if let Some((m, _)) = &method {
            out.push(mk("function", Value::str(&format!("{}::{}", m.decl_class_name, m.name))));
            if let Some(t) = this {
                out.push(mk("this", Value::Object(t)));
            }
            return out;
        }
        if let Some(d) = decl {
            out.push(mk("name", Value::str(&d.name)));
            out.push(mk("file", Value::str(&d.file)));
            out.push(mk("line", Value::Int(d.line as i64)));
            if !bound.is_empty() {
                let mut st = PArray::new();
                for (slot, v) in &bound {
                    let n = d.slot_names.get(*slot as usize).cloned().unwrap_or(Rc::from("?"));
                    st.set(Key::Str(Rc::new(n.as_bytes().to_vec())), v.clone());
                }
                out.push(mk("static", Value::arr(st)));
            }
            if let Some(t) = this {
                out.push(mk("this", Value::Object(t)));
            }
            if !d.params.is_empty() {
                let mut ps = PArray::new();
                for p in &d.params {
                    let mut n = String::new();
                    if p.by_ref {
                        n.push('&');
                    }
                    n.push('$');
                    n.push_str(&p.name);
                    ps.set(Key::Str(Rc::new(n.into_bytes())), Value::str(if p.default.is_some() || p.variadic { "<optional>" } else { "<required>" }));
                }
                out.push(mk("parameter", Value::arr(ps)));
            }
        }
    }
    out
}

pub struct Dumper {
    pub out: Vec<u8>,
    obj_stack: Vec<u32>,
    arr_stack: Vec<usize>,
}

impl Dumper {
    pub fn new() -> Dumper {
        Dumper { out: Vec::new(), obj_stack: Vec::new(), arr_stack: Vec::new() }
    }

    pub fn var_dump(&mut self, it: &mut Interp, v: &Value, ind: usize, is_ref: bool) -> R<()> {
        spaces(&mut self.out, ind);
        if is_ref {
            self.out.push(b'&');
        }
        match v {
            Value::Undef | Value::Null => self.out.extend_from_slice(b"NULL\n"),
            Value::Bool(b) => self.out.extend_from_slice(if *b { b"bool(true)\n" } else { b"bool(false)\n" }),
            Value::Int(i) => {
                self.out.extend_from_slice(format!("int({})\n", i).as_bytes());
            }
            Value::Float(f) => {
                let s = fmt_float_prec(*f, it.serialize_precision);
                self.out.extend_from_slice(format!("float({})\n", s).as_bytes());
            }
            Value::Str(s) => {
                self.out.extend_from_slice(format!("string({}) \"", s.len()).as_bytes());
                self.out.extend_from_slice(s);
                self.out.extend_from_slice(b"\"\n");
            }
            Value::Array(a) => {
                let id = Rc::as_ptr(a) as usize;
                if self.arr_stack.contains(&id) {
                    self.out.extend_from_slice(b"*RECURSION*\n");
                    return Ok(());
                }
                self.out.extend_from_slice(format!("array({}) {{\n", a.len()).as_bytes());
                self.arr_stack.push(id);
                for (k, val) in a.iter() {
                    spaces(&mut self.out, ind + 2);
                    match k {
                        Key::Int(i) => self.out.extend_from_slice(format!("[{}]=>\n", i).as_bytes()),
                        Key::Str(s) => {
                            self.out.extend_from_slice(b"[\"");
                            self.out.extend_from_slice(s);
                            self.out.extend_from_slice(b"\"]=>\n");
                        }
                    }
                    self.dump_elem(it, val, ind + 2)?;
                }
                self.arr_stack.pop();
                spaces(&mut self.out, ind);
                self.out.extend_from_slice(b"}\n");
            }
            Value::Object(o) => {
                if o.class.kind == ClassKind::Enum {
                    let n = it.get_prop_raw(o, "name");
                    self.out.extend_from_slice(format!("enum({}::{})\n", o.class.name, n.to_string_lossy()).as_bytes());
                    return Ok(());
                }
                if self.obj_stack.contains(&o.id) {
                    self.out.extend_from_slice(b"*RECURSION*\n");
                    return Ok(());
                }
                let (props, dbg) = dump_props(it, o, true)?;
                let cnt = props.iter().filter(|p| p.uninit_type.is_none()).count();
                self.out.extend_from_slice(format!("object({})#{} ({}) {{\n", display_class_name(&o.class.name), o.id, cnt).as_bytes());
                self.obj_stack.push(o.id);
                for p in props {
                    spaces(&mut self.out, ind + 2);
                    self.out.extend_from_slice(b"[");
                    if dbg {
                        match Key::from_str_bytes(&p.name) {
                            Key::Int(i) if !is_closure_obj(o) => self.out.extend_from_slice(i.to_string().as_bytes()),
                            _ => {
                                self.out.push(b'"');
                                self.out.extend_from_slice(&p.name);
                                self.out.push(b'"');
                            }
                        }
                    } else {
                        self.out.push(b'"');
                        self.out.extend_from_slice(&p.name);
                        self.out.push(b'"');
                        match p.vis {
                            Visibility::Public => {}
                            Visibility::Protected => self.out.extend_from_slice(b":protected"),
                            Visibility::Private => {
                                self.out.extend_from_slice(b":\"");
                                self.out.extend_from_slice(p.class.as_bytes());
                                self.out.extend_from_slice(b"\":private");
                            }
                        }
                    }
                    self.out.extend_from_slice(b"]=>\n");
                    if let Some(t) = &p.uninit_type {
                        spaces(&mut self.out, ind + 2);
                        self.out.extend_from_slice(format!("uninitialized({})\n", t).as_bytes());
                        continue;
                    }
                    self.dump_elem(it, &p.val, ind + 2)?;
                }
                self.obj_stack.pop();
                spaces(&mut self.out, ind);
                self.out.extend_from_slice(b"}\n");
            }
            Value::Ref(r) => {
                let inner = r.borrow().clone();
                self.var_dump(it, &inner, 0, false)?;
            }
        }
        Ok(())
    }

    fn dump_elem(&mut self, it: &mut Interp, val: &Value, ind: usize) -> R<()> {
        match val {
            Value::Ref(r) => {
                let is_ref = Rc::strong_count(r) > 1;
                let id = Rc::as_ptr(r) as usize;
                if self.arr_stack.contains(&id) {
                    spaces(&mut self.out, ind);
                    self.out.extend_from_slice(b"*RECURSION*\n");
                    return Ok(());
                }
                let inner = r.borrow().clone();
                if let Value::Array(_) = inner {
                    self.arr_stack.push(id);
                    let res = self.var_dump(it, &inner, ind, is_ref);
                    self.arr_stack.pop();
                    return res;
                }
                self.var_dump(it, &inner, ind, is_ref)
            }
            v => self.var_dump(it, v, ind, false),
        }
    }

    pub fn print_r(&mut self, it: &mut Interp, v: &Value, ind: usize) -> R<()> {
        match v {
            Value::Array(a) => {
                let id = Rc::as_ptr(a) as usize;
                self.out.extend_from_slice(b"Array\n");
                if self.arr_stack.contains(&id) {
                    self.out.extend_from_slice(b" *RECURSION*");
                    return Ok(());
                }
                self.arr_stack.push(id);
                spaces(&mut self.out, ind);
                self.out.extend_from_slice(b"(\n");
                for (k, val) in a.iter() {
                    spaces(&mut self.out, ind + 4);
                    self.out.push(b'[');
                    self.out.extend_from_slice(&k.as_bytes());
                    self.out.extend_from_slice(b"] => ");
                    self.print_r_elem(it, val, ind + 8)?;
                    self.out.push(b'\n');
                }
                spaces(&mut self.out, ind);
                self.out.extend_from_slice(b")\n");
                self.arr_stack.pop();
            }
            Value::Object(o) => {
                self.out.extend_from_slice(display_class_name(&o.class.name).as_bytes());
                if o.class.kind == ClassKind::Enum {
                    self.out.extend_from_slice(b" Enum");
                    if let Some(b) = &o.class.enum_backing {
                        self.out.push(b':');
                        self.out.extend_from_slice(b.as_bytes());
                    }
                    self.out.push(b'\n');
                } else {
                    self.out.extend_from_slice(b" Object\n");
                }
                if self.obj_stack.contains(&o.id) {
                    self.out.extend_from_slice(b" *RECURSION*");
                    return Ok(());
                }
                self.obj_stack.push(o.id);
                let (props, dbg) = dump_props(it, o, true)?;
                spaces(&mut self.out, ind);
                self.out.extend_from_slice(b"(\n");
                for p in props {
                    if p.uninit_type.is_some() {
                        continue;
                    }
                    spaces(&mut self.out, ind + 4);
                    self.out.push(b'[');
                    self.out.extend_from_slice(&p.name);
                    if !dbg {
                        match p.vis {
                            Visibility::Public => {}
                            Visibility::Protected => self.out.extend_from_slice(b":protected"),
                            Visibility::Private => {
                                self.out.push(b':');
                                self.out.extend_from_slice(p.class.as_bytes());
                                self.out.extend_from_slice(b":private");
                            }
                        }
                    }
                    self.out.extend_from_slice(b"] => ");
                    self.print_r_elem(it, &p.val, ind + 8)?;
                    self.out.push(b'\n');
                }
                spaces(&mut self.out, ind);
                self.out.extend_from_slice(b")\n");
                self.obj_stack.pop();
            }
            Value::Ref(r) => {
                let inner = r.borrow().clone();
                self.print_r(it, &inner, ind)?;
            }
            other => {
                let s = it.to_str(other)?;
                self.out.extend_from_slice(&s);
            }
        }
        Ok(())
    }

    fn print_r_elem(&mut self, it: &mut Interp, val: &Value, ind: usize) -> R<()> {
        match val {
            Value::Ref(r) => {
                let id = Rc::as_ptr(r) as usize;
                let inner = r.borrow().clone();
                if let Value::Array(_) = inner {
                    if self.arr_stack.contains(&id) {
                        self.out.extend_from_slice(b"Array\n *RECURSION*");
                        return Ok(());
                    }
                    self.arr_stack.push(id);
                    let r = self.print_r(it, &inner, ind);
                    self.arr_stack.pop();
                    return r;
                }
                self.print_r(it, &inner, ind)
            }
            v => self.print_r(it, v, ind),
        }
    }

    pub fn var_export(&mut self, it: &mut Interp, v: &Value, level: usize) -> R<()> {
        match v {
            Value::Undef | Value::Null => self.out.extend_from_slice(b"NULL"),
            Value::Bool(b) => self.out.extend_from_slice(if *b { b"true" } else { b"false" }),
            Value::Int(i) => self.out.extend_from_slice(i.to_string().as_bytes()),
            Value::Float(f) => {
                let s = fmt_float_prec(*f, it.serialize_precision);
                self.out.extend_from_slice(s.as_bytes());
                if f.is_finite() && !s.contains('.') && !s.contains('E') && !s.contains('N') && !s.contains('I') {
                    self.out.extend_from_slice(b".0");
                }
            }
            Value::Str(s) => export_str(&mut self.out, s),
            Value::Array(a) => {
                let id = Rc::as_ptr(a) as usize;
                if self.arr_stack.contains(&id) {
                    it.warn("var_export does not handle circular references")?;
                    self.out.extend_from_slice(b"NULL");
                    return Ok(());
                }
                if level > 1 {
                    self.out.push(b'\n');
                    spaces(&mut self.out, level - 1);
                }
                self.out.extend_from_slice(b"array (\n");
                self.arr_stack.push(id);
                for (k, val) in a.iter() {
                    spaces(&mut self.out, level + 1);
                    match k {
                        Key::Int(i) => self.out.extend_from_slice(i.to_string().as_bytes()),
                        Key::Str(s) => export_str(&mut self.out, s),
                    }
                    self.out.extend_from_slice(b" => ");
                    let vv = val.deref();
                    self.var_export(it, &vv, level + 2)?;
                    self.out.extend_from_slice(b",\n");
                }
                self.arr_stack.pop();
                if level > 1 {
                    spaces(&mut self.out, level - 1);
                }
                self.out.push(b')');
            }
            Value::Object(o) => {
                if self.obj_stack.contains(&o.id) {
                    it.warn("var_export does not handle circular references")?;
                    self.out.extend_from_slice(b"NULL");
                    return Ok(());
                }
                if level > 1 {
                    self.out.push(b'\n');
                    spaces(&mut self.out, level - 1);
                }
                if o.class.kind == ClassKind::Enum {
                    let n = it.get_prop_raw(o, "name");
                    self.out.extend_from_slice(format!("\\{}::{}", o.class.name, n.to_string_lossy()).as_bytes());
                    return Ok(());
                }
                let is_std = &*o.class.lname == "stdclass";
                if is_std {
                    self.out.extend_from_slice(b"(object) array(\n");
                } else {
                    self.out.extend_from_slice(format!("\\{}::__set_state(array(\n", o.class.name).as_bytes());
                }
                self.obj_stack.push(o.id);
                let (props, _) = dump_props(it, o, false)?;
                for p in props {
                    if p.uninit_type.is_some() {
                        continue;
                    }
                    spaces(&mut self.out, level + 2);
                    match Key::from_str_bytes(&p.name) {
                        Key::Int(i) => self.out.extend_from_slice(i.to_string().as_bytes()),
                        Key::Str(s) => export_str(&mut self.out, &s),
                    }
                    self.out.extend_from_slice(b" => ");
                    let vv = p.val.deref();
                    self.var_export(it, &vv, level + 2)?;
                    self.out.extend_from_slice(b",\n");
                }
                self.obj_stack.pop();
                if level > 1 {
                    spaces(&mut self.out, level - 1);
                }
                if is_std {
                    self.out.push(b')');
                } else {
                    self.out.extend_from_slice(b"))");
                }
            }
            Value::Ref(r) => {
                let inner = r.borrow().clone();
                self.var_export(it, &inner, level)?;
            }
        }
        Ok(())
    }
}

pub fn display_class_name(n: &str) -> String {
    match n.find('\0') {
        Some(p) => {
            let _ = p;
            n.split('\0').next().unwrap().to_string() + &n[p..]
        }
        None => n.to_string(),
    }
}

fn f_var_dump(it: &mut Interp, a: &mut Args) -> R<Value> {
    for i in 0..a.len() {
        let v = a.get(i);
        let mut d = Dumper::new();
        d.var_dump(it, &v, 0, false)?;
        it.echo(&d.out);
    }
    Ok(Value::Null)
}

fn f_print_r(it: &mut Interp, a: &mut Args) -> R<Value> {
    let v = a.get(0);
    let ret = a.bool_or(it, 1, false)?;
    let mut d = Dumper::new();
    d.print_r(it, &v, 0)?;
    if ret {
        return Ok(Value::vec(d.out));
    }
    it.echo(&d.out);
    Ok(Value::Bool(true))
}

fn f_var_export(it: &mut Interp, a: &mut Args) -> R<Value> {
    let v = a.get(0);
    let ret = a.bool_or(it, 1, false)?;
    let mut d = Dumper::new();
    d.var_export(it, &v, 1)?;
    if ret {
        return Ok(Value::vec(d.out));
    }
    it.echo(&d.out);
    Ok(Value::Null)
}

fn f_debug_zval_dump(it: &mut Interp, a: &mut Args) -> R<Value> {
    f_var_dump(it, a)
}

// output buffering
fn f_ob_start(it: &mut Interp, a: &mut Args) -> R<Value> {
    let cb = if a.has(0) && !a.get(0).is_null() { Some(a.get(0)) } else { None };
    it.ob.push(crate::interp::ObBuf { buf: Vec::new(), callback: cb });
    Ok(Value::Bool(true))
}
fn apply_ob_cb(it: &mut Interp, b: &crate::interp::ObBuf, data: Vec<u8>, mode: i64) -> R<Vec<u8>> {
    match &b.callback {
        Some(cb) => {
            let cb = cb.clone();
            let r = it.call_value(&cb, vec![Value::vec(data.clone()), Value::Int(mode)])?;
            match r {
                Value::Bool(false) => Ok(data),
                other => Ok(other.to_bytes_simple()),
            }
        }
        None => Ok(data),
    }
}
fn f_ob_get_clean(it: &mut Interp, _a: &mut Args) -> R<Value> {
    match it.ob.pop() {
        Some(b) => Ok(Value::vec(b.buf)),
        None => Ok(Value::Bool(false)),
    }
}
fn f_ob_get_contents(it: &mut Interp, _a: &mut Args) -> R<Value> {
    match it.ob.last() {
        Some(b) => Ok(Value::bytes(&b.buf)),
        None => Ok(Value::Bool(false)),
    }
}
fn f_ob_end_clean(it: &mut Interp, _a: &mut Args) -> R<Value> {
    match it.ob.pop() {
        Some(_) => Ok(Value::Bool(true)),
        None => {
            it.notice("ob_end_clean(): Failed to delete buffer. No buffer to delete")?;
            Ok(Value::Bool(false))
        }
    }
}
fn f_ob_end_flush(it: &mut Interp, _a: &mut Args) -> R<Value> {
    match it.ob.pop() {
        Some(b) => {
            let data = std::mem::take(&mut { b.buf.clone() });
            let out = apply_ob_cb(it, &b, data, 8)?;
            it.echo(&out);
            Ok(Value::Bool(true))
        }
        None => {
            it.notice("ob_end_flush(): Failed to delete and flush buffer. No buffer to delete or flush")?;
            Ok(Value::Bool(false))
        }
    }
}
fn f_ob_get_flush(it: &mut Interp, _a: &mut Args) -> R<Value> {
    match it.ob.pop() {
        Some(b) => {
            let data = b.buf.clone();
            let out = apply_ob_cb(it, &b, data.clone(), 8)?;
            it.echo(&out);
            Ok(Value::vec(data))
        }
        None => Ok(Value::Bool(false)),
    }
}
fn f_ob_flush(it: &mut Interp, _a: &mut Args) -> R<Value> {
    let n = it.ob.len();
    if n == 0 {
        return Ok(Value::Bool(false));
    }
    let data = std::mem::take(&mut it.ob[n - 1].buf);
    let cb = it.ob[n - 1].callback.clone();
    let tmp = crate::interp::ObBuf { buf: Vec::new(), callback: cb };
    let out = apply_ob_cb(it, &tmp, data, 2)?;
    if n >= 2 {
        it.ob[n - 2].buf.extend_from_slice(&out);
    } else {
        it.out.extend_from_slice(&out);
    }
    Ok(Value::Bool(true))
}
fn f_ob_clean(it: &mut Interp, _a: &mut Args) -> R<Value> {
    match it.ob.last_mut() {
        Some(b) => {
            b.buf.clear();
            Ok(Value::Bool(true))
        }
        None => Ok(Value::Bool(false)),
    }
}
fn f_ob_get_level(it: &mut Interp, _a: &mut Args) -> R<Value> {
    Ok(Value::Int(it.ob.len() as i64))
}
fn f_ob_get_length(it: &mut Interp, _a: &mut Args) -> R<Value> {
    match it.ob.last() {
        Some(b) => Ok(Value::Int(b.buf.len() as i64)),
        None => Ok(Value::Bool(false)),
    }
}
fn f_flush(it: &mut Interp, _a: &mut Args) -> R<Value> {
    if it.ob.is_empty() {
        it.flush();
    }
    Ok(Value::Null)
}
fn f_ob_implicit_flush(_it: &mut Interp, _a: &mut Args) -> R<Value> {
    Ok(Value::Null)
}
fn f_ob_list_handlers(it: &mut Interp, _a: &mut Args) -> R<Value> {
    let mut out = PArray::new();
    for b in &it.ob {
        out.push(Value::str(if b.callback.is_some() { "Closure::__invoke" } else { "default output handler" }));
    }
    Ok(Value::arr(out))
}
fn f_ob_get_status(it: &mut Interp, _a: &mut Args) -> R<Value> {
    let mut out = PArray::new();
    if let Some(b) = it.ob.last() {
        out.set(Key::Str(pstr("name")), Value::str("default output handler"));
        out.set(Key::Str(pstr("level")), Value::Int(it.ob.len() as i64 - 1));
        out.set(Key::Str(pstr("buffer_used")), Value::Int(b.buf.len() as i64));
    }
    Ok(Value::arr(out))
}

pub fn register(it: &mut Interp) {
    reg(it, "var_dump", "value,...values", f_var_dump);
    reg(it, "print_r", "value,return?", f_print_r);
    reg(it, "var_export", "value,return?", f_var_export);
    reg(it, "debug_zval_dump", "value,...values", f_debug_zval_dump);
    reg(it, "ob_start", "callback?,chunk_size?,flags?", f_ob_start);
    reg(it, "ob_get_clean", "", f_ob_get_clean);
    reg(it, "ob_get_contents", "", f_ob_get_contents);
    reg(it, "ob_end_clean", "", f_ob_end_clean);
    reg(it, "ob_end_flush", "", f_ob_end_flush);
    reg(it, "ob_get_flush", "", f_ob_get_flush);
    reg(it, "ob_flush", "", f_ob_flush);
