        return None;
    }
    if n.len() == 1 {
        return h[from..].iter().position(|&c| c == n[0]).map(|p| p + from);
    }
    let first = n[0];
    let last_start = h.len() - n.len();
    let mut i = from;
    while i <= last_start {
        match h[i..=last_start].iter().position(|&c| c == first) {
