            }
        }
    }
    Ok(Value::vec(out))
}
fn f_explode(it: &mut Interp, a: &mut Args) -> R<Value> {
    let sep = a.str(it, 0)?;
    let s = a.str(it, 1)?;
    let limit = a.int_or(it, 2, i64::MAX)?;
    if sep.is_empty() {
        return Err(a.value_err(it, 0, "cannot be empty"));
    }
    let mut parts: Vec<&[u8]> = Vec::new();
    let mut i = 0;
    while let Some(p) = find_bytes(&s, &sep, i) {
        parts.push(&s[i..p]);
        i = p + sep.len();
    }
    parts.push(&s[i..]);
    let mut out = PArray::new();
    if limit > 0 {
        if parts.len() as i64 > limit {
            let l = limit as usize;
            for p in &parts[..l - 1] {
                out.push(Value::bytes(p));
            }
            // rest joined
            let start: usize = parts[..l - 1].iter().map(|p| p.len() + sep.len()).sum();
            out.push(Value::bytes(&s[start..]));
        } else {
            for p in parts {
                out.push(Value::bytes(p));
            }
        }
    } else if limit < 0 {
        let keep = parts.len() as i64 + limit;
        for p in parts.iter().take(keep.max(0) as usize) {
            out.push(Value::bytes(p));
        }
    } else {
        // limit 0 == 1
        out.push(Value::Str(s.clone()));
    }
    Ok(Value::arr(out))
}

// ---------------- sprintf ----------------
pub fn php_sprintf(it: &mut Interp, fname: &str, fmt: &[u8], args: &[Value]) -> R<Vec<u8>> {
    let mut out = Vec::with_capacity(fmt.len() + 16);
    let mut i = 0;
    let mut argi = 0usize;
    while i < fmt.len() {
        let c = fmt[i];
        if c != b'%' {
            out.push(c);
            i += 1;
            continue;
        }
        i += 1;
        if i >= fmt.len() {
            return Err(it.value_error("Missing format specifier at end of string"));
        }
        if fmt[i] == b'%' {
            out.push(b'%');
            i += 1;
            continue;
        }
        // argnum
        let mut argnum: Option<usize> = None;
        let save = i;
        let mut n = 0usize;
        let mut has = false;
        while i < fmt.len() && fmt[i].is_ascii_digit() {
            n = n * 10 + (fmt[i] - b'0') as usize;
            i += 1;
            has = true;
        }
        if has && i < fmt.len() && fmt[i] == b'$' {
            if n == 0 {
                return Err(it.value_error("Argument number specifier must be greater than zero and less than 2147483647"));
            }
            argnum = Some(n - 1);
            i += 1;
        } else {
            i = save;
        }
        // flags
        let mut left = false;
        let mut plus = false;
        let mut pad = b' ';
        loop {
            if i >= fmt.len() {
                break;
            }
            match fmt[i] {
                b'-' => {
                    left = true;
                    i += 1;
                }
                b'+' => {
                    plus = true;
                    i += 1;
                }
                b'0' => {
                    pad = b'0';
                    i += 1;
                }
                b' ' => {
                    pad = b' ';
                    i += 1;
                }
                b'\'' => {
                    if i + 1 < fmt.len() {
                        pad = fmt[i + 1];
                        i += 2;
                    } else {
                        i += 1;
                    }
                }
                _ => break,
            }
        }
        let mut width = 0usize;
        while i < fmt.len() && fmt[i].is_ascii_digit() {
            width = width * 10 + (fmt[i] - b'0') as usize;
            i += 1;
        }
        let mut prec: Option<usize> = None;
        if i < fmt.len() && fmt[i] == b'.' {
            i += 1;
            let mut p = 0;
            while i < fmt.len() && fmt[i].is_ascii_digit() {
                p = p * 10 + (fmt[i] - b'0') as usize;
                i += 1;
            }
            prec = Some(p);
        }
        // length modifiers (ignored)
        while i < fmt.len() && (fmt[i] == b'l' || fmt[i] == b'h') && i + 1 < fmt.len() && b"bcdeEfFgGosuxX".contains(&fmt[i + 1]) {
            i += 1;
        }
        if i >= fmt.len() {
            return Err(it.value_error("Missing format specifier at end of string"));
        }
        let spec = fmt[i];
        i += 1;
        let ai = match argnum {
            Some(n) => n,
            None => {
                let x = argi;
                argi += 1;
                x
            }
        };
        if !b"bcdeEfFgGhHosuxX".contains(&spec) {
            let msg = format!("Unknown format specifier \"{}\"", spec as char);
            return Err(it.value_error(&msg));
        }
        if ai >= args.len() {
            let msg = if argnum.is_some() {
                format!("{} arguments are required, {} given", ai + 2, args.len() + 1)
            } else {
                format!("{} arguments are required, {} given", ai + 2, args.len() + 1)
            };
            let _ = fname;
            return Err(it.throw_err("ArgumentCountError", &msg));
        }
        let arg = args[ai].deref();
        let mut s: Vec<u8>;
        let mut is_num = false;
        let mut neg = false;
        match spec {
            b's' => {
                let st = it.to_str(&arg)?;
                s = st.to_vec();
                if let Some(p) = prec {
                    s.truncate(p);
                }
            }
            b'd' => {
                let v = arg_int(&arg);
                is_num = true;
                neg = v < 0;
                s = v.unsigned_abs().to_string().into_bytes();
                if neg {
                    s.insert(0, b'-');
                } else if plus {
                    s.insert(0, b'+');
                }
            }
            b'u' => {
                let v = arg_int(&arg) as u64;
                s = v.to_string().into_bytes();
            }
            b'c' => {
                s = vec![arg_int(&arg) as u8];
                out.extend_from_slice(&s);
                continue;
            }
            b'x' => s = format!("{:x}", arg_int(&arg) as u64).into_bytes(),
            b'X' => s = format!("{:X}", arg_int(&arg) as u64).into_bytes(),
            b'o' => s = format!("{:o}", arg_int(&arg) as u64).into_bytes(),
            b'b' => s = format!("{:b}", arg_int(&arg) as u64).into_bytes(),
            b'f' | b'F' | b'e' | b'E' | b'g' | b'G' | b'h' | b'H' => {
                let f = arg.to_float();
                is_num = true;
                let p = prec.unwrap_or(6);
                neg = f < 0.0 || (f == 0.0 && f.is_sign_negative() && false);
                let body = if f.is_nan() {
                    "NaN".to_string()
                } else if f.is_infinite() {
                    if f > 0.0 { "Inf".to_string() } else { "-Inf".to_string() }
                } else {
                    match spec {
                        b'f' | b'F' => format!("{:.*}", p, f),
                        b'e' | b'E' => {
                            let r = format!("{:.*e}", p, f);
                            let (m, e) = r.split_once('e').unwrap();
                            let ei: i32 = e.parse().unwrap();
                            let ch = if spec == b'e' { 'e' } else { 'E' };
                            format!("{}{}{}{}", m, ch, if ei < 0 { "-" } else { "+" }, ei.abs())
                        }
                        _ => {
                            let pp = if p == 0 { 1 } else { p };
                            let ch = if spec == b'g' || spec == b'h' { b'e' } else { b'E' };
                            if f == 0.0 {
                                "0".to_string()
                            } else {
                                let r = format!("{:.*e}", pp - 1, f.abs());
                                let (m, e) = r.split_once('e').unwrap();
                                let ei: i32 = e.parse().unwrap();
                                let mut digits: Vec<u8> = m.bytes().filter(|c| *c != b'.').collect();
                                while digits.len() > 1 && *digits.last().unwrap() == b'0' {
                                    digits.pop();
                                }
                                let decpt = ei + 1;
                                let mut o = String::new();
                                if f < 0.0 {
                                    o.push('-');
                                }
                                if decpt < -3 || decpt > pp as i32 {
                                    o.push(digits[0] as char);
                                    o.push('.');
                                    if digits.len() > 1 {
                                        for &c in &digits[1..] {
                                            o.push(c as char);
                                        }
                                    } else {
                                        o.push('0');
                                    }
                                    o.push(ch as char);
                                    o.push(if decpt - 1 < 0 { '-' } else { '+' });
                                    o.push_str(&(decpt - 1).abs().to_string());
                                } else if decpt <= 0 {
                                    o.push_str("0.");
                                    for _ in 0..(-decpt) {
                                        o.push('0');
                                    }
                                    for &c in &digits {
                                        o.push(c as char);
                                    }
                                } else {
                                    let dp = decpt as usize;
                                    for (k, &c) in digits.iter().enumerate() {
                                        if k == dp {
                                            o.push('.');
                                        }
                                        o.push(c as char);
                                    }
                                    for _ in digits.len()..dp {
                                        o.push('0');
                                    }
                                }
                                o
                            }
                        }
                    }
                };
                s = body.into_bytes();
                if plus && !neg && f >= 0.0 {
                    s.insert(0, b'+');
                }
            }
            _ => unreachable!(),
        }
        // padding
        if s.len() < width {
            let padn = width - s.len();
            if left {
                if pad == b'0' && is_num {
                    // PHP: left-justify with zeros pads right with zeros? uses spaces? keep zeros
                    let mut v = s.clone();
                    for _ in 0..padn {
                        v.push(b'0');
                    }
                    s = v;
                } else {
                    for _ in 0..padn {
                        s.push(pad);
                    }
                }
            } else if pad == b'0' && is_num && (s.first() == Some(&b'-') || s.first() == Some(&b'+')) {
                let sign = s.remove(0);
                let mut v = vec![sign];
                for _ in 0..padn {
                    v.push(b'0');
                }
                v.extend_from_slice(&s);
                s = v;
            } else {
                let mut v = vec![pad; padn];
                v.extend_from_slice(&s);
                s = v;
            }
        }
        out.extend_from_slice(&s);
    }
    Ok(out)
}

fn arg_int(v: &Value) -> i64 {
    match v {
        Value::Float(f) => float_to_int(*f),
        _ => v.to_int(),
    }
}

fn f_sprintf(it: &mut Interp, a: &mut Args) -> R<Value> {
    let fmt = a.str(it, 0)?;
    let args: Vec<Value> = a.v[1..].to_vec();
    Ok(Value::vec(php_sprintf(it, "sprintf", &fmt, &args)?))
}
