pub fn php_round(value: f64, places: i64, mode: i64) -> f64 {
    if !value.is_finite() || value == 0.0 {
        return value;
    }
    let places = places.clamp(-308, 308) as i32;
    let exponent = 10f64.powi(places.abs());
    let scaled = if places > 0 { value * exponent } else { value / exponent };
    if !scaled.is_finite() {
        return value;
    }
    let (mut tmp, edge_tmp) = if value >= 0.0 {
        let t = scaled.floor();
        (t, t + 0.5)
    } else {
        let t = scaled.ceil();
        (t, t - 0.5)
    };
    if tmp.abs() >= 1e15 {
        return value;
    }
    let edge = if places > 0 { edge_tmp / exponent } else { edge_tmp * exponent };
    let pos = value >= 0.0;
    let beyond = if pos { value > edge } else { value < edge };
    let at = value == edge;
    let away = |t: f64| if pos { t + 1.0 } else { t - 1.0 };
    match mode {
        1 => {
            // HALF_UP
            if beyond || at {
                tmp = away(tmp);
            }
        }
        2 => {
            // HALF_DOWN
            if beyond {
                tmp = away(tmp);
            }
        }
        3 => {
            // HALF_EVEN
            if beyond || (at && (tmp % 2.0) != 0.0) {
                tmp = away(tmp);
            }
        }
        4 => {
            // HALF_ODD
            if beyond || (at && (tmp % 2.0) == 0.0) {
                tmp = away(tmp);
            }
        }
        5 => {
            // TOWARD_ZERO
        }
        6 => {
            // AWAY_FROM_ZERO
            let exact = if places > 0 { tmp / exponent } else { tmp * exponent };
            if exact != value {
                tmp = away(tmp);
            }
        }
        7 => {
            // CEILING
            let exact = if places > 0 { tmp / exponent } else { tmp * exponent };
            if exact != value && pos {
                tmp += 1.0;
            }
        }
        8 => {
            // FLOOR
            let exact = if places > 0 { tmp / exponent } else { tmp * exponent };
            if exact != value && !pos {
                tmp -= 1.0;
            }
        }
        _ => {
            if beyond || at {
                tmp = away(tmp);
            }
        }
    }
    let r = if places > 0 { tmp / exponent } else { tmp * exponent };
    if !r.is_finite() {
        return value;
    }
    r
}

pub fn number_format(f: f64, dec: i64, dp: &[u8], ts: &[u8]) -> Vec<u8> {
    let dec = dec.max(0) as usize;
    let r = php_round(f, dec as i64, 1);
    let mut s = format!("{:.*}", dec, r.abs());
    let neg = r < 0.0 && s.bytes().any(|c| c != b'0' && c != b'.');
    let (ip, fp) = match s.find('.') {
        Some(p) => {
            let fp = s[p + 1..].to_string();
            s.truncate(p);
            (s, Some(fp))
        }
        None => (s, None),
    };
    let mut out = Vec::new();
    if neg {
        out.push(b'-');
    }
    let ib = ip.as_bytes();
    for (i, c) in ib.iter().enumerate() {
        if i > 0 && (ib.len() - i) % 3 == 0 {
            out.extend_from_slice(ts);
        }
        out.push(*c);
    }
    if let Some(fp) = fp {
        if dec > 0 {
            out.extend_from_slice(dp);
            out.extend_from_slice(fp.as_bytes());
        }
    }
    out
}

fn f_number_format(it: &mut Interp, a: &mut Args) -> R<Value> {
    let f = a.float(it, 0)?;
    let dec = a.int_or(it, 1, 0)?;
    let dp = a.str_or(it, 2, b".")?;
    let ts = a.str_or(it, 3, b",")?;
    Ok(Value::vec(number_format(f, dec, &dp, &ts)))
}

fn f_nl2br(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let xhtml = a.bool_or(it, 1, true)?;
    let br: &[u8] = if xhtml { b"<br />" } else { b"<br>" };
    let mut out = Vec::new();
    let mut i = 0;
    while i < s.len() {
        let c = s[i];
        if c == b'\r' || c == b'\n' {
            out.extend_from_slice(br);
            out.push(c);
            if i + 1 < s.len() && ((c == b'\r' && s[i + 1] == b'\n') || (c == b'\n' && s[i + 1] == b'\r')) {
                out.push(s[i + 1]);
                i += 1;
            }
        } else {
            out.push(c);
        }
        i += 1;
    }
    Ok(Value::vec(out))
}

fn html_escape(s: &[u8], flags: i64, double: bool, all: bool) -> Vec<u8> {
    let mut out = Vec::with_capacity(s.len());
    let mut i = 0;
    while i < s.len() {
        let c = s[i];
        match c {
            b'&' => {
                if !double {
                    // check existing entity
                    if let Some(end) = s[i..].iter().take(12).position(|&x| x == b';') {
                        let ent = &s[i + 1..i + end];
                        let valid = !ent.is_empty() && (ent.iter().all(|c| c.is_ascii_alphanumeric()) || (ent[0] == b'#' && ent.len() > 1 && (ent[1..].iter().all(|c| c.is_ascii_digit()) || ((ent[1] == b'x' || ent[1] == b'X') && ent.len() > 2 && ent[2..].iter().all(|c| c.is_ascii_hexdigit())))));
                        if valid {
                            out.push(b'&');
                            i += 1;
                            continue;
                        }
                    }
                }
                out.extend_from_slice(b"&amp;");
            }
            b'<' => out.extend_from_slice(b"&lt;"),
            b'>' => out.extend_from_slice(b"&gt;"),
            b'"' if flags & 2 != 0 => out.extend_from_slice(b"&quot;"),
            b'\'' if flags & 1 != 0 => {
                if flags & (16 | 32) != 0 {
                    out.extend_from_slice(b"&apos;");
                } else {
                    out.extend_from_slice(b"&#039;");
                }
            }
            _ => {
                if all && c >= 0x80 {
                    // decode utf-8 and map common entities
                    let (cp, len) = crate::builtins::json::utf8_decode_at(s, i);
                    if let Some(name) = entity_name(cp) {
                        out.push(b'&');
                        out.extend_from_slice(name.as_bytes());
                        out.push(b';');
                        i += len;
                        continue;
                    }
                    out.extend_from_slice(&s[i..i + len]);
                    i += len;
                    continue;
                }
                out.push(c)
            }
        }
        i += 1;
    }
    out
}

fn entity_name(cp: u32) -> Option<&'static str> {
    Some(match cp {
        0xA0 => "nbsp",
        0xA9 => "copy",
        0xAE => "reg",
        0xE9 => "eacute",
        0xE8 => "egrave",
        0xE0 => "agrave",
        0xE1 => "aacute",
        0xE7 => "ccedil",
        0xF1 => "ntilde",
        0xF6 => "ouml",
        0xFC => "uuml",
        0xE4 => "auml",
        0xDF => "szlig",
        0xC9 => "Eacute",
        0x20AC => "euro",
        0xA3 => "pound",
        0xA5 => "yen",
        0xB0 => "deg",
        0x2014 => "mdash",
        0x2013 => "ndash",
        0x2026 => "hellip",
        0xAB => "laquo",
        0xBB => "raquo",
        0x201C => "ldquo",
        0x201D => "rdquo",
        0x2018 => "lsquo",
        0x2019 => "rsquo",
        0xD7 => "times",
        0xF7 => "divide",
        _ => return None,
    })
}

fn f_htmlspecialchars(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let flags = a.int_or(it, 1, 3 | 8 | 48)?;
    let double = a.bool_or(it, 3, true)?;
    Ok(Value::vec(html_escape(&s, flags, double, false)))
}
fn f_htmlentities(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let flags = a.int_or(it, 1, 3 | 8 | 48)?;
    let double = a.bool_or(it, 3, true)?;
    Ok(Value::vec(html_escape(&s, flags, double, true)))
}
fn html_decode(s: &[u8], flags: i64, all: bool) -> Vec<u8> {
    let mut out = Vec::with_capacity(s.len());
    let mut i = 0;
    while i < s.len() {
        if s[i] == b'&' {
            if let Some(end) = s[i..].iter().take(12).position(|&x| x == b';') {
                let ent = &s[i + 1..i + end];
                let rep: Option<Vec<u8>> = match ent {
                    b"amp" => Some(b"&".to_vec()),
                    b"lt" => Some(b"<".to_vec()),
                    b"gt" => Some(b">".to_vec()),
                    b"quot" if flags & 2 != 0 => Some(b"\"".to_vec()),
                    b"#039" | b"#39" | b"#x27" if flags & 1 != 0 => Some(b"'".to_vec()),
                    b"apos" if flags & 1 != 0 && flags & (16 | 32) != 0 => Some(b"'".to_vec()),
                    _ => {
                        if ent.len() > 1 && ent[0] == b'#' && all {
                            let n = if ent[1] == b'x' || ent[1] == b'X' { u32::from_str_radix(&String::from_utf8_lossy(&ent[2..]), 16).ok() } else { String::from_utf8_lossy(&ent[1..]).parse::<u32>().ok() };
                            n.map(|cp| {
                                let mut v = Vec::new();
                                crate::lexer::encode_utf8(cp, &mut v);
                                v
                            })
                        } else if all {
                            let name = String::from_utf8_lossy(ent).to_string();
                            (0x20u32..0x2200).find(|cp| entity_name(*cp) == Some(name.as_str())).map(|cp| {
                                let mut v = Vec::new();
                                crate::lexer::encode_utf8(cp, &mut v);
                                v
                            })
                        } else {
                            None
                        }
                    }
                };
                if let Some(r) = rep {
                    out.extend_from_slice(&r);
                    i += end + 1;
                    continue;
                }
            }
        }
        out.push(s[i]);
        i += 1;
    }
    out
}
fn f_htmlspecialchars_decode(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let flags = a.int_or(it, 1, 3 | 8 | 48)?;
    Ok(Value::vec(html_decode(&s, flags, false)))
}
fn f_html_entity_decode(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let flags = a.int_or(it, 1, 3 | 8 | 48)?;
    Ok(Value::vec(html_decode(&s, flags, true)))
}
fn f_addslashes(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let mut out = Vec::with_capacity(s.len());
    for &c in s.iter() {
        match c {
            b'\'' | b'"' | b'\\' => {
                out.push(b'\\');
                out.push(c);
            }
            0 => out.extend_from_slice(b"\\0"),
            _ => out.push(c),
        }
    }
    Ok(Value::vec(out))
}
fn f_stripslashes(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let mut out = Vec::with_capacity(s.len());
    let mut i = 0;
    while i < s.len() {
        if s[i] == b'\\' {
            if i + 1 < s.len() {
                if s[i + 1] == b'0' {
                    out.push(0);
                } else {
                    out.push(s[i + 1]);
                }
                i += 2;
            } else {
                i += 1;
            }
        } else {
            out.push(s[i]);
            i += 1;
        }
    }
    Ok(Value::vec(out))
}
fn f_addcslashes(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let m = a.str(it, 1)?;
    let mask = char_mask(&m);
    let mut out = Vec::new();
    for &c in s.iter() {
        if mask[c as usize] {
            out.push(b'\\');
            match c {
                b'\n' => out.push(b'n'),
                b'\t' => out.push(b't'),
                b'\r' => out.push(b'r'),
                0x07 => out.push(b'a'),
                0x0b => out.push(b'v'),
                0x08 => out.push(b'b'),
                0x0c => out.push(b'f'),
                c if c < 32 || c > 126 => out.extend_from_slice(format!("{:03o}", c).as_bytes()),
                c => out.push(c),
            }
        } else {
            out.push(c);
        }
    }
    Ok(Value::vec(out))
}
fn f_stripcslashes(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let mut out = Vec::new();
    let mut i = 0;
    while i < s.len() {
        if s[i] == b'\\' && i + 1 < s.len() {
            i += 1;
            match s[i] {
                b'n' => out.push(b'\n'),
                b't' => out.push(b'\t'),
                b'r' => out.push(b'\r'),
                b'a' => out.push(7),
                b'v' => out.push(11),
                b'b' => out.push(8),
                b'f' => out.push(12),
                b'x' => {
                    let mut v = 0u32;
                    let mut n = 0;
                    while n < 2 && i + 1 < s.len() && s[i + 1].is_ascii_hexdigit() {
                        i += 1;
                        v = v * 16 + (s[i] as char).to_digit(16).unwrap();
                        n += 1;
                    }
                    out.push(v as u8);
                }
                c if (b'0'..=b'7').contains(&c) => {
                    let mut v = (c - b'0') as u32;
                    let mut n = 1;
                    while n < 3 && i + 1 < s.len() && (b'0'..=b'7').contains(&s[i + 1]) {
                        i += 1;
                        v = v * 8 + (s[i] - b'0') as u32;
                        n += 1;
                    }
                    out.push(v as u8);
                }
                c => out.push(c),
            }
            i += 1;
        } else {
            out.push(s[i]);
            i += 1;
        }
    }
    Ok(Value::vec(out))
}
fn f_quotemeta(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let mut out = Vec::new();
