fn f_str_word_count(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let fmt = a.int_or(it, 1, 0)?;
    let extra = a.str_or(it, 2, b"")?;
    let mask = char_mask(&extra);
    let is_w = |c: u8| c.is_ascii_alphabetic() || mask[c as usize] || c == b'\'' || c == b'-';
    let mut words: Vec<(usize, &[u8])> = Vec::new();
    let mut i = 0;
    let n = s.len();
    while i < n {
        // word start: letter (or extra) ; '-' and '\'' allowed inside
        while i < n && !(s[i].is_ascii_alphabetic() || mask[s[i] as usize] || s[i] == b'\'') {
            i += 1;
        }
        let st = i;
        while i < n && is_w(s[i]) {
            i += 1;
        }
        let mut en = i;
        if en > st && s[en - 1] == b'-' && !mask[b'-' as usize] {
            en -= 1;
        }
        if en > st {
            words.push((st, &s[st..en]));
        }
    }
    match fmt {
        0 => Ok(Value::Int(words.len() as i64)),
        1 => Ok(Value::arr(PArray::from_values(words.iter().map(|(_, w)| Value::bytes(w)).collect()))),
        2 => {
            let mut out = PArray::new();
            for (p, w) in words {
                out.set(Key::Int(p as i64), Value::bytes(w));
            }
            Ok(Value::arr(out))
        }
        _ => Err(a.value_err(it, 1, "must be a valid format value")),
    }
}
fn f_count_chars(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let mode = a.int_or(it, 1, 0)?;
    let mut counts = [0i64; 256];
    for &c in s.iter() {
        counts[c as usize] += 1;
    }
    match mode {
        0 | 1 | 2 => {
            let mut out = PArray::new();
            for (i, &c) in counts.iter().enumerate() {
                if mode == 0 || (mode == 1 && c > 0) || (mode == 2 && c == 0) {
                    out.set(Key::Int(i as i64), Value::Int(c));
                }
            }
            Ok(Value::arr(out))
        }
        3 | 4 => {
            let mut out = Vec::new();
            for (i, &c) in counts.iter().enumerate() {
                if (mode == 3 && c > 0) || (mode == 4 && c == 0) {
                    out.push(i as u8);
                }
            }
            Ok(Value::vec(out))
        }
        _ => Err(a.value_err(it, 1, "must be between 0 and 4 (inclusive)")),
    }
}
fn f_strtr(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    if a.len() == 2 {
        let pairs = match a.get(1) {
            Value::Array(p) => p,
            other => {
                let msg = format!("strtr(): Argument #2 ($from) must be of type array, {} given", other.type_name());
                return Err(it.type_error(&msg));
            }
        };
        let mut reps: Vec<(Vec<u8>, Vec<u8>)> = Vec::new();
        for (k, v) in pairs.iter() {
            let kb = k.as_bytes();
            if kb.is_empty() {
                continue;
            }
            let vb = it.to_str(&v.deref())?.to_vec();
            reps.push((kb, vb));
        }
        if reps.is_empty() {
            return Ok(Value::Str(s));
        }
        let maxlen = reps.iter().map(|r| r.0.len()).max().unwrap();
        let minlen = reps.iter().map(|r| r.0.len()).min().unwrap();
        let map: std::collections::HashMap<Vec<u8>, Vec<u8>> = reps.into_iter().collect();
        let mut out = Vec::new();
        let mut i = 0;
        while i < s.len() {
            let mut found = false;
            let mut l = maxlen.min(s.len() - i);
            while l >= minlen && l > 0 {
                if let Some(r) = map.get(&s[i..i + l]) {
                    out.extend_from_slice(r);
                    i += l;
                    found = true;
                    break;
                }
                l -= 1;
            }
            if !found {
                out.push(s[i]);
                i += 1;
            }
        }
        return Ok(Value::vec(out));
    }
    let from = a.str(it, 1)?;
    let to = a.str(it, 2)?;
    let n = from.len().min(to.len());
    let mut map: [u8; 256] = [0; 256];
    for (i, m) in map.iter_mut().enumerate() {
        *m = i as u8;
    }
    for i in 0..n {
        map[from[i] as usize] = to[i];
    }
    Ok(Value::vec(s.iter().map(|&c| map[c as usize]).collect()))
}
