}

pub fn strnatcmp(a: &[u8], b: &[u8], ci: bool) -> i32 {
    let (mut i, mut j) = (0usize, 0usize);
    let (la, lb) = (a.len(), b.len());
    if la == 0 || lb == 0 {
        return if la == lb { 0 } else if la == 0 { -1 } else { 1 };
    }
    loop {
        // skip leading spaces
        while i < la && a[i].is_ascii_whitespace() {
            i += 1;
        }
        while j < lb && b[j].is_ascii_whitespace() {
            j += 1;
        }
        if i >= la || j >= lb {
            break;
        }
        let ca = a[i];
        let cb = b[j];
        if ca.is_ascii_digit() && cb.is_ascii_digit() {
            let fractional = ca == b'0' || cb == b'0';
            if fractional {
                // compare left-aligned
                loop {
                    let da = i < la && a[i].is_ascii_digit();
                    let db = j < lb && b[j].is_ascii_digit();
                    if !da && !db {
                        break;
                    }
                    if !da {
                        return -1;
                    }
                    if !db {
                        return 1;
                    }
                    if a[i] < b[j] {
                        return -1;
                    }
                    if a[i] > b[j] {
                        return 1;
                    }
                    i += 1;
                    j += 1;
                }
                continue;
            } else {
                // right-aligned: longest run wins
                let mut bias = 0;
                loop {
                    let da = i < la && a[i].is_ascii_digit();
                    let db = j < lb && b[j].is_ascii_digit();
                    if !da && !db {
                        if bias != 0 {
                            return bias;
                        }
                        break;
                    }
                    if !da {
                        return -1;
                    }
                    if !db {
                        return 1;
                    }
                    if bias == 0 {
                        if a[i] < b[j] {
                            bias = -1;
                        } else if a[i] > b[j] {
                            bias = 1;
                        }
                    }
                    i += 1;
                    j += 1;
                }
                continue;
            }
        }
        let (xa, xb) = if ci { (ca.to_ascii_lowercase(), cb.to_ascii_lowercase()) } else { (ca, cb) };
        if xa < xb {
            return -1;
        }
        if xa > xb {
            return 1;
        }
        i += 1;
        j += 1;
    }
    let ra = la - i.min(la);
    let rb = lb - j.min(lb);
    if ra == rb {
        0
    } else if ra < rb {
        -1
    } else {
        1
    }
}
fn f_strnatcmp(it: &mut Interp, a: &mut Args) -> R<Value> {
