fn f_substr_compare(it: &mut Interp, a: &mut Args) -> R<Value> {
    let h = a.str(it, 0)?;
    let n = a.str(it, 1)?;
    let off = a.int(it, 2)?;
    let len = a.opt_int(it, 3)?;
    let ci = a.bool_or(it, 4, false)?;
    let hl = h.len() as i64;
    let st = if off < 0 { (hl + off).max(0) } else { off };
    if st > hl {
        return Err(a.value_err(it, 2, "must be contained in argument #1 ($main_str)"));
    }
    let sub = &h[st as usize..];
    let (x, y): (Vec<u8>, Vec<u8>) = match len {
        Some(l) => {
            let l = l as usize;
            (sub[..l.min(sub.len())].to_vec(), n[..l.min(n.len())].to_vec())
        }
        None => (sub.to_vec(), n.to_vec()),
    };
    let (x, y) = if ci { (bytes_lower(&x), bytes_lower(&y)) } else { (x, y) };
    Ok(Value::Int(crate::interp::ops::byte_cmp(&x, &y) as i64))
}
fn f_strip_tags(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let allowed: Vec<Vec<u8>> = match a.get(1) {
        Value::Str(al) => {
            let mut v = Vec::new();
            let mut i = 0;
            while let Some(p) = find_bytes(&al, b"<", i) {
                if let Some(e) = find_bytes(&al, b">", p) {
                    v.push(bytes_lower(&al[p + 1..e]));
                    i = e;
                } else {
                    break;
                }
            }
            v
        }
        Value::Array(arr) => arr.values().map(|x| bytes_lower(&x.to_bytes_simple())).collect(),
        _ => Vec::new(),
    };
    let mut out = Vec::new();
    let mut i = 0;
    while i < s.len() {
        if s[i] == b'<' {
            // find end
            let mut j = i + 1;
            let mut q = 0u8;
            while j < s.len() {
                let c = s[j];
                if q != 0 {
                    if c == q {
                        q = 0;
                    }
                } else if c == b'"' || c == b'\'' {
                    q = c;
                } else if c == b'>' {
                    break;
                }
                j += 1;
            }
            let tag = &s[i + 1..j.min(s.len())];
            let name: Vec<u8> = tag.iter().skip_while(|&&c| c == b'/').take_while(|&&c| c.is_ascii_alphanumeric()).map(|c| c.to_ascii_lowercase()).collect();
            if !name.is_empty() && allowed.contains(&name) {
                out.extend_from_slice(&s[i..(j + 1).min(s.len())]);
            }
            i = j + 1;
        } else {
            out.push(s[i]);
            i += 1;
        }
    }
    Ok(Value::vec(out))
}
fn f_strspn(it: &mut Interp, a: &mut Args) -> R<Value> {
    span_common(it, a, true)
}
fn f_strcspn(it: &mut Interp, a: &mut Args) -> R<Value> {
