        out.push(if cp < 256 { cp as u8 } else { b'?' });
        i += l;
    }
    Ok(Value::vec(out))
}
fn f_sscanf(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let fmt = a.str(it, 1)?;
    let mut results: Vec<Value> = Vec::new();
    let mut si = 0;
    let mut fi = 0;
    let mut failed = false;
    while fi < fmt.len() {
        let fc = fmt[fi];
        if fc == b'%' && fi + 1 < fmt.len() {
            fi += 1;
            if fmt[fi] == b'%' {
                if si < s.len() && s[si] == b'%' {
                    si += 1;
                    fi += 1;
                    continue;
                }
                break;
            }
            let mut width = 0usize;
            while fi < fmt.len() && fmt[fi].is_ascii_digit() {
                width = width * 10 + (fmt[fi] - b'0') as usize;
                fi += 1;
            }
            let conv = fmt[fi];
            fi += 1;
            if failed {
                results.push(Value::Null);
                continue;
            }
            if conv != b'c' {
                while si < s.len() && s[si].is_ascii_whitespace() {
                    si += 1;
                }
            }
            let maxw = if width == 0 { usize::MAX } else { width };
            match conv {
                b'd' | b'i' | b'u' => {
                    let st = si;
                    if si < s.len() && (s[si] == b'-' || s[si] == b'+') {
                        si += 1;
                    }
                    while si < s.len() && s[si].is_ascii_digit() && si - st < maxw {
                        si += 1;
                    }
                    if si == st || (si == st + 1 && !s[st].is_ascii_digit()) {
                        failed = true;
                        results.push(Value::Null);
                        si = st;
                    } else {
                        results.push(Value::Int(String::from_utf8_lossy(&s[st..si]).parse().unwrap_or(0)));
                    }
                }
                b'f' | b'e' | b'g' => {
                    let st = si;
                    while si < s.len() && (s[si].is_ascii_digit() || s[si] == b'.' || s[si] == b'-' || s[si] == b'+' || s[si] == b'e' || s[si] == b'E') && si - st < maxw {
                        si += 1;
                    }
                    if si == st {
                        failed = true;
                        results.push(Value::Null);
                    } else {
                        results.push(Value::Float(String::from_utf8_lossy(&s[st..si]).parse().unwrap_or(0.0)));
                    }
                }
                b'x' | b'X' => {
                    let st = si;
                    while si < s.len() && s[si].is_ascii_hexdigit() && si - st < maxw {
                        si += 1;
                    }
                    if si == st {
                        failed = true;
                        results.push(Value::Null);
                    } else {
                        results.push(Value::Int(i64::from_str_radix(&String::from_utf8_lossy(&s[st..si]), 16).unwrap_or(0)));
                    }
                }
                b's' => {
                    let st = si;
                    while si < s.len() && !s[si].is_ascii_whitespace() && si - st < maxw {
                        si += 1;
                    }
                    if si == st {
                        failed = true;
                        results.push(Value::Null);
                    } else {
                        results.push(Value::bytes(&s[st..si]));
                    }
                }
                b'c' => {
                    let w = if width == 0 { 1 } else { width };
                    if si + w <= s.len() {
                        results.push(Value::bytes(&s[si..si + w]));
                        si += w;
                    } else {
                        failed = true;
                        results.push(Value::Null);
                    }
                }
                _ => {
                    results.push(Value::Null);
                }
            }
        } else if fc.is_ascii_whitespace() {
            while si < s.len() && s[si].is_ascii_whitespace() {
                si += 1;
            }
            fi += 1;
        } else {
            if !failed {
                if si < s.len() && s[si] == fc {
                    si += 1;
                } else {
                    failed = true;
                }
            }
            fi += 1;
        }
    }
    if a.len() > 2 {
        for (i, v) in results.iter().enumerate() {
            a.set_ref(2 + i, v.clone());
        }
        return Ok(Value::Int(results.iter().filter(|v| !v.is_null()).count() as i64));
    }
    if si == 0 && s.is_empty() {
        return Ok(Value::Int(-1));
    }
    Ok(Value::arr(PArray::from_values(results)))
}
