    Ok(Value::arr(parse_csv_line(&s, sep.first().copied().unwrap_or(b','), enc.first().copied().unwrap_or(b'"'), esc.first().copied())))
}
pub fn parse_csv_line(s: &[u8], sep: u8, enc: u8, esc: Option<u8>) -> PArray {
    let mut out = PArray::new();
    let mut i = 0;
    let n = s.len();
    let s = if n > 0 && s[n - 1] == b'\n' { &s[..if n > 1 && s[n - 2] == b'\r' { n - 2 } else { n - 1 }] } else { s };
    let n = s.len();
    if n == 0 {
        out.push(Value::Null);
        return out;
    }
    loop {
        let mut field = Vec::new();
        // skip leading whitespace? PHP keeps it except before enclosure
        let mut j = i;
        while j < n && (s[j] == b' ' || s[j] == b'\t') {
            j += 1;
        }
        if j < n && s[j] == enc {
            i = j + 1;
            loop {
                if i >= n {
                    break;
                }
                let c = s[i];
                if Some(c) == esc && esc != Some(enc) && i + 1 < n {
                    field.push(c);
                    field.push(s[i + 1]);
                    i += 2;
                    continue;
                }
                if c == enc {
                    if i + 1 < n && s[i + 1] == enc {
                        field.push(enc);
                        i += 2;
                        continue;
                    }
                    i += 1;
                    break;
                }
                field.push(c);
                i += 1;
            }
            while i < n && s[i] != sep {
                field.push(s[i]);
                i += 1;
            }
        } else {
            while i < n && s[i] != sep {
                field.push(s[i]);
                i += 1;
            }
        }
        out.push(Value::vec(field));
        if i >= n {
            break;
        }
        i += 1;
        if i >= n {
            out.push(Value::str(""));
            break;
        }
    }
    out
}

