/// parse a trim character list with ranges a..z
pub fn char_mask(m: &[u8]) -> [bool; 256] {
    let mut mask = [false; 256];
    let mut i = 0;
    while i < m.len() {
        if i + 3 < m.len() && m[i + 1] == b'.' && m[i + 2] == b'.' && m[i + 3] >= m[i] {
            for c in m[i]..=m[i + 3] {
                mask[c as usize] = true;
            }
            i += 4;
        } else {
            mask[m[i] as usize] = true;
            i += 1;
        }
    }
    mask
}

fn do_trim(it: &mut Interp, a: &Args, left: bool, right: bool) -> R<Value> {
    let s = a.str(it, 0)?;
    let mask = if a.has(1) { char_mask(&a.str(it, 1)?) } else { char_mask(b" \t\n\r\0\x0b") };
    let mut st = 0;
    let mut en = s.len();
    if left {
        while st < en && mask[s[st] as usize] {
            st += 1;
        }
    }
    if right {
        while en > st && mask[s[en - 1] as usize] {
            en -= 1;
        }
    }
    if st == 0 && en == s.len() {
        return Ok(Value::Str(s));
    }
    Ok(Value::bytes(&s[st..en]))
}
