    let len = a.int(it, 1)?;
    let pad = a.str_or(it, 2, b" ")?;
    let ty = a.int_or(it, 3, 1)?;
    if pad.is_empty() {
        return Err(a.value_err(it, 2, "must be a non-empty string"));
    }
    if ty < 0 || ty > 2 {
        return Err(a.value_err(it, 3, "must be STR_PAD_LEFT, STR_PAD_RIGHT, or STR_PAD_BOTH"));
    }
    if len <= s.len() as i64 {
        return Ok(Value::Str(s));
    }
    let total = len as usize - s.len();
    let (l, r) = match ty {
        0 => (total, 0),
        2 => (total / 2, total - total / 2),
        _ => (0, total),
    };
    let mut out = Vec::with_capacity(len as usize);
    for i in 0..l {
        out.push(pad[i % pad.len()]);
    }
    out.extend_from_slice(&s);
    for i in 0..r {
        out.push(pad[i % pad.len()]);
    }
    Ok(Value::vec(out))
}
fn f_str_split(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let n = a.int_or(it, 1, 1)?;
    if n < 1 {
        return Err(a.value_err(it, 1, "must be greater than 0"));
    }
    let mut out = PArray::new();
    if s.is_empty() {
        out.push(Value::str(""));
        return Ok(Value::arr(out));
    }
    for c in s.chunks(n as usize) {
        out.push(Value::bytes(c));
    }
    Ok(Value::arr(out))
}
fn f_strrev(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let mut v = s.to_vec();
    v.reverse();
    Ok(Value::vec(v))
}

pub fn find_bytes(h: &[u8], n: &[u8], from: usize) -> Option<usize> {
    if n.is_empty() {
        return if from <= h.len() { Some(from) } else { None };
    }
    if n.len() > h.len() || from > h.len() - n.len() {
        return None;
    }
    if n.len() == 1 {
        return h[from..].iter().position(|&c| c == n[0]).map(|p| p + from);
    }
    let first = n[0];
    let last_start = h.len() - n.len();
    let mut i = from;
    while i <= last_start {
        match h[i..=last_start].iter().position(|&c| c == first) {
            None => return None,
            Some(p) => {
                i += p;
                if &h[i..i + n.len()] == n {
                    return Some(i);
                }
                i += 1;
            }
        }
    }
    None
}
fn rfind_bytes(h: &[u8], n: &[u8], upto: usize) -> Option<usize> {
    // last occurrence starting at or before `upto`
    if n.len() > h.len() {
        return None;
    }
    let mut i = upto.min(h.len() - n.len());
    loop {
        if &h[i..i + n.len()] == n {
            return Some(i);
        }
        if i == 0 {
            return None;
        }
        i -= 1;
    }
}

fn str_replace_impl(subject: &[u8], search: &[u8], replace: &[u8], ci: bool, count: &mut i64) -> Vec<u8> {
    if search.is_empty() {
        return subject.to_vec();
    }
    let (hay, needle) = if ci { (bytes_lower(subject), bytes_lower(search)) } else { (Vec::new(), Vec::new()) };
    let (h, n): (&[u8], &[u8]) = if ci { (&hay, &needle) } else { (subject, search) };
    let mut out = Vec::with_capacity(subject.len());
    let mut i = 0;
    while let Some(p) = find_bytes(h, n, i) {
        out.extend_from_slice(&subject[i..p]);
        out.extend_from_slice(replace);
        i = p + n.len();
        *count += 1;
    }
    out.extend_from_slice(&subject[i..]);
    out
}

fn do_str_replace(it: &mut Interp, a: &mut Args, ci: bool) -> R<Value> {
    let search = a.get(0);
    let replace = a.get(1);
    let subject = a.get(2);
    let mut count = 0i64;
    let mut repl_one = |it: &mut Interp, s: &[u8], count: &mut i64| -> R<Vec<u8>> {
        match &search {
            Value::Array(sa) => {
                let mut cur = s.to_vec();
                let ra: Option<Vec<Value>> = match &replace {
                    Value::Array(r) => Some(r.values().cloned().collect()),
                    _ => None,
                };
                let rs = match &replace {
                    Value::Array(_) => None,
                    v => Some(it.to_str(v)?),
                };
                for (i, (_, sv)) in sa.iter().enumerate() {
                    let ss = it.to_str(&sv.deref())?;
                    let rep: Vec<u8> = match (&ra, &rs) {
                        (Some(r), _) => match r.get(i) {
                            Some(v) => it.to_str(&v.deref())?.to_vec(),
                            None => Vec::new(),
                        },
                        (None, Some(r)) => r.to_vec(),
                        _ => Vec::new(),
                    };
                    cur = str_replace_impl(&cur, &ss, &rep, ci, count);
                }
                Ok(cur)
            }
            sv => {
                let ss = it.to_str(sv)?;
                let rs = match &replace {
                    Value::Array(_) => {
                        return Err(it.type_error("str_replace(): Argument #2 ($replace) must be of type string when argument #1 ($search) is a string"));
                    }
                    v => it.to_str(v)?,
                };
                Ok(str_replace_impl(s, &ss, &rs, ci, count))
            }
        }
    };
    let result = match &subject {
        Value::Array(arr) => {
            let mut out = PArray::new();
            for (k, v) in arr.iter() {
                let v = v.deref();
                match v {
                    Value::Array(_) | Value::Object(_) => out.set(k.clone(), v),
                    _ => {
                        let s = it.to_str(&v)?;
                        let r = repl_one(it, &s, &mut count)?;
                        out.set(k.clone(), Value::vec(r));
                    }
                }
            }
            Value::arr(out)
        }
        v => {
            let s = it.to_str(v)?;
            Value::vec(repl_one(it, &s, &mut count)?)
        }
    };
    if a.len() > 3 {
        a.set_ref(3, Value::Int(count));
    }
    Ok(result)
}
fn f_str_replace(it: &mut Interp, a: &mut Args) -> R<Value> {
    do_str_replace(it, a, false)
}
fn f_str_ireplace(it: &mut Interp, a: &mut Args) -> R<Value> {
    do_str_replace(it, a, true)
}

fn f_substr(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let start = a.int(it, 1)?;
    let len = a.opt_int(it, 2)?;
    let n = s.len() as i64;
    let mut st = if start < 0 { (n + start).max(0) } else { start.min(n) };
    if st > n {
        st = n;
    }
    let en = match len {
        None => n,
        Some(l) if l < 0 => (n + l).max(st),
        Some(l) => (st + l).min(n),
    };
    if en <= st {
        return Ok(Value::str(""));
    }
    Ok(Value::bytes(&s[st as usize..en as usize]))
}
fn f_substr_count(it: &mut Interp, a: &mut Args) -> R<Value> {
    let h = a.str(it, 0)?;
    let n = a.str(it, 1)?;
    if n.is_empty() {
        return Err(a.value_err(it, 1, "cannot be empty"));
    }
    let off = a.int_or(it, 2, 0)?;
    let len = a.opt_int(it, 3)?;
    let hl = h.len() as i64;
    let st = if off < 0 { hl + off } else { off };
    if st < 0 || st > hl {
        return Err(a.value_err(it, 2, "must be contained in argument #1 ($haystack)"));
    }
    let en = match len {
        Some(l) => {
            let e = if l < 0 { hl + l } else { st + l };
            if e > hl || e < st {
                return Err(a.value_err(it, 3, "must be contained in argument #1 ($haystack)"));
            }
            e
        }
        None => hl,
    };
    let sub = &h[st as usize..en as usize];
    let mut c = 0;
    let mut i = 0;
    while let Some(p) = find_bytes(sub, &n, i) {
        c += 1;
        i = p + n.len();
    }
    Ok(Value::Int(c))
}
fn f_substr_replace(it: &mut Interp, a: &mut Args) -> R<Value> {
    let subj = a.get(0);
    let one = |it: &mut Interp, s: &[u8], rep: &[u8], start: i64, len: Option<i64>| -> Vec<u8> {
        let _ = it;
        let n = s.len() as i64;
        let st = if start < 0 { (n + start).max(0) } else { start.min(n) };
        let en = match len {
            None => n,
            Some(l) if l < 0 => (n + l).max(st),
            Some(l) => (st + l).min(n),
        };
        let mut out = s[..st as usize].to_vec();
        out.extend_from_slice(rep);
        if en > st {
            out.extend_from_slice(&s[en as usize..]);
        } else {
            out.extend_from_slice(&s[st as usize..]);
        }
        out
    };
    let rep_v = a.get(1);
    let start_v = a.get(2);
    let len_v = if a.has(3) { a.get(3) } else { Value::Null };
    let pick = |v: &Value, i: usize| -> Option<Value> {
        match v {
            Value::Array(arr) => arr.values().nth(i).map(|x| x.deref()),
            x => Some(x.clone()),
        }
    };
    match &subj {
        Value::Array(arr) => {
            let mut out = PArray::new();
            for (i, (k, v)) in arr.iter().enumerate() {
                let s = it.to_str(&v.deref())?;
                let r = match pick(&rep_v, i) {
                    Some(x) => it.to_str(&x)?.to_vec(),
                    None => Vec::new(),
                };
                let st = pick(&start_v, i).map(|x| x.to_int()).unwrap_or(0);
                let ln = match pick(&len_v, i) {
                    Some(Value::Null) | None => None,
                    Some(x) => Some(x.to_int()),
                };
                out.set(k.clone(), Value::vec(one(it, &s, &r, st, ln)));
            }
            Ok(Value::arr(out))
        }
        _ => {
            let s = a.str(it, 0)?;
            let r = match &rep_v {
                Value::Array(arr) => match arr.values().next() {
                    Some(x) => it.to_str(&x.deref())?.to_vec(),
                    None => Vec::new(),
                },
                x => it.to_str(x)?.to_vec(),
            };
            let st = start_v.to_int();
            let ln = if len_v.is_null() { None } else { Some(len_v.to_int()) };
            Ok(Value::vec(one(it, &s, &r, st, ln)))
        }
    }
}

fn pos_common(it: &mut Interp, a: &Args, ci: bool, rev: bool) -> R<Value> {
    let h = a.str(it, 0)?;
    let n = a.str(it, 1)?;
    let off = a.int_or(it, 2, 0)?;
    let hl = h.len() as i64;
    if off > hl || off < -hl {
        return Err(a.value_err(it, 2, "must be contained in argument #1 ($haystack)"));
    }
    let (h, n) = if ci { (Rc::new(bytes_lower(&h)), Rc::new(bytes_lower(&n))) } else { (h, n) };
    if !rev {
        let st = if off < 0 { hl + off } else { off } as usize;
        return Ok(match find_bytes(&h, &n, st) {
            Some(p) => Value::Int(p as i64),
            None => Value::Bool(false),
        });
    }
    // strrpos
    if n.len() > h.len() {
        return Ok(Value::Bool(false));
    }
    let r = if off >= 0 {
        let st = off as usize;
        let mut res = None;
        let mut i = st;
        while let Some(p) = find_bytes(&h, &n, i) {
            res = Some(p);
            i = p + 1;
        }
        res
    } else {
        let max_start = (hl + off) as i64;
        let upto = if -off as usize <= n.len() { (hl - n.len() as i64).max(0) as usize } else { max_start as usize };
        if max_start < 0 {
            None
        } else {
            rfind_bytes(&h, &n, upto)
        }
    };
    Ok(match r {
        Some(p) => Value::Int(p as i64),
        None => Value::Bool(false),
    })
}
fn f_strpos(it: &mut Interp, a: &mut Args) -> R<Value> {
    pos_common(it, a, false, false)
}
fn f_stripos(it: &mut Interp, a: &mut Args) -> R<Value> {
    pos_common(it, a, true, false)
}
fn f_strrpos(it: &mut Interp, a: &mut Args) -> R<Value> {
    pos_common(it, a, false, true)
}
fn f_strripos(it: &mut Interp, a: &mut Args) -> R<Value> {
    pos_common(it, a, true, true)
}
fn strstr_common(it: &mut Interp, a: &Args, ci: bool) -> R<Value> {
    let h = a.str(it, 0)?;
    let n = a.str(it, 1)?;
    let before = a.bool_or(it, 2, false)?;
    let p = if ci { find_bytes(&bytes_lower(&h), &bytes_lower(&n), 0) } else { find_bytes(&h, &n, 0) };
    Ok(match p {
        Some(p) => {
            if before {
                Value::bytes(&h[..p])
            } else {
                Value::bytes(&h[p..])
            }
        }
        None => Value::Bool(false),
    })
}
fn f_strstr(it: &mut Interp, a: &mut Args) -> R<Value> {
    strstr_common(it, a, false)
}
fn f_stristr(it: &mut Interp, a: &mut Args) -> R<Value> {
    strstr_common(it, a, true)
}
fn f_strrchr(it: &mut Interp, a: &mut Args) -> R<Value> {
    let h = a.str(it, 0)?;
    let n = a.str(it, 1)?;
    let c = match n.first() {
        Some(c) => *c,
        None => return Ok(Value::Bool(false)),
    };
    let before = a.bool_or(it, 2, false)?;
    Ok(match h.iter().rposition(|&x| x == c) {
        Some(p) => {
            if before {
                Value::bytes(&h[..p])
            } else {
                Value::bytes(&h[p..])
            }
        }
        None => Value::Bool(false),
    })
}
fn f_str_contains(it: &mut Interp, a: &mut Args) -> R<Value> {
    let h = a.str(it, 0)?;
    let n = a.str(it, 1)?;
    Ok(Value::Bool(find_bytes(&h, &n, 0).is_some()))
}
fn f_str_starts_with(it: &mut Interp, a: &mut Args) -> R<Value> {
    let h = a.str(it, 0)?;
    let n = a.str(it, 1)?;
    Ok(Value::Bool(h.starts_with(&n)))
}
fn f_str_ends_with(it: &mut Interp, a: &mut Args) -> R<Value> {
    let h = a.str(it, 0)?;
    let n = a.str(it, 1)?;
    Ok(Value::Bool(h.ends_with(&n)))
}
fn f_implode(it: &mut Interp, a: &mut Args) -> R<Value> {
    let (sep, arr) = match (a.get(0), a.get(1)) {
        (Value::Array(arr), Value::Null) if a.len() == 1 => (Rc::new(Vec::new()), arr),
        (Value::Array(arr), s) if a.len() == 2 => {
            let s = it.to_str(&s)?;
            (s, arr)
        }
        (s, Value::Array(arr)) => {
            let s = it.to_str(&s)?;
            (s, arr)
        }
        (_, other) => {
            if a.len() == 1 {
                return Err(it.type_error("implode(): Argument #1 ($array) must be of type array, string given"));
            }
            let msg = format!("implode(): Argument #2 ($array) must be of type ?array, {} given", other.type_name());
            return Err(it.type_error(&msg));
        }
    };
    let mut out = Vec::new();
    let mut first = true;
    for (_, v) in arr.iter() {
        if !first {
            out.extend_from_slice(&sep);
        }
        first = false;
        match v {
            Value::Str(s) => out.extend_from_slice(s),
            Value::Int(i) => out.extend_from_slice(i.to_string().as_bytes()),
            other => {
                let s = it.to_str(&other.deref())?;
                out.extend_from_slice(&s);
            }
        }
    }
    Ok(Value::vec(out))
}
fn f_explode(it: &mut Interp, a: &mut Args) -> R<Value> {
    let sep = a.str(it, 0)?;
    let s = a.str(it, 1)?;
    let limit = a.int_or(it, 2, i64::MAX)?;
    if sep.is_empty() {
        return Err(a.value_err(it, 0, "cannot be empty"));
    }
    let mut parts: Vec<&[u8]> = Vec::new();
    let mut i = 0;
    while let Some(p) = find_bytes(&s, &sep, i) {
        parts.push(&s[i..p]);
        i = p + sep.len();
    }
    parts.push(&s[i..]);
    let mut out = PArray::new();
    if limit > 0 {
        if parts.len() as i64 > limit {
            let l = limit as usize;
            for p in &parts[..l - 1] {
                out.push(Value::bytes(p));
            }
            // rest joined
            let start: usize = parts[..l - 1].iter().map(|p| p.len() + sep.len()).sum();
            out.push(Value::bytes(&s[start..]));
        } else {
            for p in parts {
                out.push(Value::bytes(p));
            }
        }
    } else if limit < 0 {
        let keep = parts.len() as i64 + limit;
        for p in parts.iter().take(keep.max(0) as usize) {
            out.push(Value::bytes(p));
        }
    } else {
        // limit 0 == 1
        out.push(Value::Str(s.clone()));
    }
    Ok(Value::arr(out))
}

// ---------------- sprintf ----------------
pub fn php_sprintf(it: &mut Interp, fname: &str, fmt: &[u8], args: &[Value]) -> R<Vec<u8>> {
    let mut out = Vec::with_capacity(fmt.len() + 16);
    let mut i = 0;
    let mut argi = 0usize;
    while i < fmt.len() {
        let c = fmt[i];
        if c != b'%' {
            out.push(c);
            i += 1;
            continue;
        }
        i += 1;
        if i >= fmt.len() {
            return Err(it.value_error("Missing format specifier at end of string"));
        }
        if fmt[i] == b'%' {
            out.push(b'%');
            i += 1;
            continue;
        }
        // argnum
        let mut argnum: Option<usize> = None;
        let save = i;
        let mut n = 0usize;
        let mut has = false;
        while i < fmt.len() && fmt[i].is_ascii_digit() {
            n = n * 10 + (fmt[i] - b'0') as usize;
            i += 1;
            has = true;
        }
        if has && i < fmt.len() && fmt[i] == b'$' {
            if n == 0 {
                return Err(it.value_error("Argument number specifier must be greater than zero and less than 2147483647"));
            }
            argnum = Some(n - 1);
            i += 1;
        } else {
            i = save;
        }
        // flags
        let mut left = false;
        let mut plus = false;
        let mut pad = b' ';
        loop {
            if i >= fmt.len() {
                break;
            }
            match fmt[i] {
                b'-' => {
                    left = true;
                    i += 1;
                }
                b'+' => {
                    plus = true;
                    i += 1;
                }
                b'0' => {
                    pad = b'0';
                    i += 1;
                }
                b' ' => {
                    pad = b' ';
                    i += 1;
                }
                b'\'' => {
                    if i + 1 < fmt.len() {
                        pad = fmt[i + 1];
                        i += 2;
                    } else {
                        i += 1;
                    }
                }
                _ => break,
            }
        }
        let mut width = 0usize;
        while i < fmt.len() && fmt[i].is_ascii_digit() {
            width = width * 10 + (fmt[i] - b'0') as usize;
            i += 1;
        }
        let mut prec: Option<usize> = None;
        if i < fmt.len() && fmt[i] == b'.' {
            i += 1;
            let mut p = 0;
            while i < fmt.len() && fmt[i].is_ascii_digit() {
                p = p * 10 + (fmt[i] - b'0') as usize;
                i += 1;
            }
            prec = Some(p);
        }
        // length modifiers (ignored)
        while i < fmt.len() && (fmt[i] == b'l' || fmt[i] == b'h') && i + 1 < fmt.len() && b"bcdeEfFgGosuxX".contains(&fmt[i + 1]) {
            i += 1;
        }
        if i >= fmt.len() {
            return Err(it.value_error("Missing format specifier at end of string"));
        }
        let spec = fmt[i];
        i += 1;
        let ai = match argnum {
            Some(n) => n,
            None => {
                let x = argi;
                argi += 1;
                x
            }
        };
        if !b"bcdeEfFgGhHosuxX".contains(&spec) {
            let msg = format!("Unknown format specifier \"{}\"", spec as char);
            return Err(it.value_error(&msg));
        }
        if ai >= args.len() {
            let msg = if argnum.is_some() {
                format!("{} arguments are required, {} given", ai + 2, args.len() + 1)
            } else {
                format!("{} arguments are required, {} given", ai + 2, args.len() + 1)
            };
            let _ = fname;
            return Err(it.throw_err("ArgumentCountError", &msg));
        }
        let arg = args[ai].deref();
        let mut s: Vec<u8>;
        let mut is_num = false;
        let mut neg = false;
        match spec {
            b's' => {
                let st = it.to_str(&arg)?;
                s = st.to_vec();
                if let Some(p) = prec {
                    s.truncate(p);
                }
            }
            b'd' => {
                let v = arg_int(&arg);
                is_num = true;
                neg = v < 0;
                s = v.unsigned_abs().to_string().into_bytes();
                if neg {
                    s.insert(0, b'-');
                } else if plus {
                    s.insert(0, b'+');
                }
            }
            b'u' => {
                let v = arg_int(&arg) as u64;
                s = v.to_string().into_bytes();
            }
            b'c' => {
                s = vec![arg_int(&arg) as u8];
                out.extend_from_slice(&s);
                continue;
            }
            b'x' => s = format!("{:x}", arg_int(&arg) as u64).into_bytes(),
            b'X' => s = format!("{:X}", arg_int(&arg) as u64).into_bytes(),
            b'o' => s = format!("{:o}", arg_int(&arg) as u64).into_bytes(),
            b'b' => s = format!("{:b}", arg_int(&arg) as u64).into_bytes(),
            b'f' | b'F' | b'e' | b'E' | b'g' | b'G' | b'h' | b'H' => {
                let f = arg.to_float();
                is_num = true;
                let p = prec.unwrap_or(6);
                neg = f < 0.0 || (f == 0.0 && f.is_sign_negative() && false);
                let body = if f.is_nan() {
                    "NaN".to_string()
                } else if f.is_infinite() {
                    if f > 0.0 { "Inf".to_string() } else { "-Inf".to_string() }
                } else {
                    match spec {
                        b'f' | b'F' => format!("{:.*}", p, f),
                        b'e' | b'E' => {
                            let r = format!("{:.*e}", p, f);
                            let (m, e) = r.split_once('e').unwrap();
                            let ei: i32 = e.parse().unwrap();
                            let ch = if spec == b'e' { 'e' } else { 'E' };
                            format!("{}{}{}{}", m, ch, if ei < 0 { "-" } else { "+" }, ei.abs())
                        }
                        _ => {
                            let pp = if p == 0 { 1 } else { p };
                            let ch = if spec == b'g' || spec == b'h' { b'e' } else { b'E' };
                            if f == 0.0 {
                                "0".to_string()
                            } else {
                                let r = format!("{:.*e}", pp - 1, f.abs());
                                let (m, e) = r.split_once('e').unwrap();
                                let ei: i32 = e.parse().unwrap();
                                let mut digits: Vec<u8> = m.bytes().filter(|c| *c != b'.').collect();
                                while digits.len() > 1 && *digits.last().unwrap() == b'0' {
                                    digits.pop();
                                }
                                let decpt = ei + 1;
                                let mut o = String::new();
                                if f < 0.0 {
                                    o.push('-');
                                }
                                if decpt < -3 || decpt > pp as i32 {
                                    o.push(digits[0] as char);
                                    o.push('.');
                                    if digits.len() > 1 {
                                        for &c in &digits[1..] {
                                            o.push(c as char);
                                        }
                                    } else {
                                        o.push('0');
                                    }
                                    o.push(ch as char);
                                    o.push(if decpt - 1 < 0 { '-' } else { '+' });
                                    o.push_str(&(decpt - 1).abs().to_string());
                                } else if decpt <= 0 {
                                    o.push_str("0.");
                                    for _ in 0..(-decpt) {
                                        o.push('0');
                                    }
                                    for &c in &digits {
                                        o.push(c as char);
                                    }
                                } else {
                                    let dp = decpt as usize;
                                    for (k, &c) in digits.iter().enumerate() {
                                        if k == dp {
                                            o.push('.');
                                        }
                                        o.push(c as char);
                                    }
                                    for _ in digits.len()..dp {
                                        o.push('0');
                                    }
                                }
                                o
                            }
                        }
                    }
                };
                s = body.into_bytes();
                if plus && !neg && f >= 0.0 {
                    s.insert(0, b'+');
                }
            }
            _ => unreachable!(),
        }
        // padding
        if s.len() < width {
            let padn = width - s.len();
            if left {
                if pad == b'0' && is_num {
                    // PHP: left-justify with zeros pads right with zeros? uses spaces? keep zeros
                    let mut v = s.clone();
                    for _ in 0..padn {
                        v.push(b'0');
                    }
                    s = v;
                } else {
                    for _ in 0..padn {
                        s.push(pad);
                    }
                }
            } else if pad == b'0' && is_num && (s.first() == Some(&b'-') || s.first() == Some(&b'+')) {
                let sign = s.remove(0);
                let mut v = vec![sign];
                for _ in 0..padn {
                    v.push(b'0');
                }
                v.extend_from_slice(&s);
                s = v;
            } else {
                let mut v = vec![pad; padn];
                v.extend_from_slice(&s);
                s = v;
            }
        }
        out.extend_from_slice(&s);
    }
    Ok(out)
}

