pub fn php_round(value: f64, places: i64, mode: i64) -> f64 {
    if !value.is_finite() || value == 0.0 {
        return value;
    }
    let places = places.clamp(-308, 308) as i32;
    let exponent = 10f64.powi(places.abs());
    let scaled = if places > 0 { value * exponent } else { value / exponent };
    if !scaled.is_finite() {
        return value;
    }
    let (mut tmp, edge_tmp) = if value >= 0.0 {
        let t = scaled.floor();
        (t, t + 0.5)
    } else {
        let t = scaled.ceil();
        (t, t - 0.5)
    };
    if tmp.abs() >= 1e15 {
        return value;
    }
    let edge = if places > 0 { edge_tmp / exponent } else { edge_tmp * exponent };
    let pos = value >= 0.0;
    let beyond = if pos { value > edge } else { value < edge };
    let at = value == edge;
    let away = |t: f64| if pos { t + 1.0 } else { t - 1.0 };
    match mode {
        1 => {
            // HALF_UP
            if beyond || at {
                tmp = away(tmp);
            }
        }
        2 => {
            // HALF_DOWN
            if beyond {
                tmp = away(tmp);
            }
        }
        3 => {
            // HALF_EVEN
            if beyond || (at && (tmp % 2.0) != 0.0) {
                tmp = away(tmp);
            }
        }
        4 => {
            // HALF_ODD
            if beyond || (at && (tmp % 2.0) == 0.0) {
                tmp = away(tmp);
            }
        }
        5 => {
            // TOWARD_ZERO
        }
        6 => {
            // AWAY_FROM_ZERO
            let exact = if places > 0 { tmp / exponent } else { tmp * exponent };
            if exact != value {
                tmp = away(tmp);
            }
        }
        7 => {
            // CEILING
            let exact = if places > 0 { tmp / exponent } else { tmp * exponent };
            if exact != value && pos {
                tmp += 1.0;
            }
        }
        8 => {
            // FLOOR
            let exact = if places > 0 { tmp / exponent } else { tmp * exponent };
            if exact != value && !pos {
                tmp -= 1.0;
            }
        }
        _ => {
            if beyond || at {
                tmp = away(tmp);
            }
        }
    }
    let r = if places > 0 { tmp / exponent } else { tmp * exponent };
    if !r.is_finite() {
        return value;
    }
    r
}

pub fn number_format(f: f64, dec: i64, dp: &[u8], ts: &[u8]) -> Vec<u8> {
    let dec = dec.max(0) as usize;
    let r = php_round(f, dec as i64, 1);
    let mut s = format!("{:.*}", dec, r.abs());
    let neg = r < 0.0 && s.bytes().any(|c| c != b'0' && c != b'.');
    let (ip, fp) = match s.find('.') {
        Some(p) => {
            let fp = s[p + 1..].to_string();
            s.truncate(p);
            (s, Some(fp))
        }
        None => (s, None),
    };
    let mut out = Vec::new();
    if neg {
        out.push(b'-');
    }
    let ib = ip.as_bytes();
    for (i, c) in ib.iter().enumerate() {
        if i > 0 && (ib.len() - i) % 3 == 0 {
            out.extend_from_slice(ts);
        }
        out.push(*c);
    }
    if let Some(fp) = fp {
        if dec > 0 {
            out.extend_from_slice(dp);
            out.extend_from_slice(fp.as_bytes());
        }
    }
    out
}

fn f_number_format(it: &mut Interp, a: &mut Args) -> R<Value> {
    let f = a.float(it, 0)?;
    let dec = a.int_or(it, 1, 0)?;
    let dp = a.str_or(it, 2, b".")?;
    let ts = a.str_or(it, 3, b",")?;
    Ok(Value::vec(number_format(f, dec, &dp, &ts)))
}

fn f_nl2br(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let xhtml = a.bool_or(it, 1, true)?;
    let br: &[u8] = if xhtml { b"<br />" } else { b"<br>" };
    let mut out = Vec::new();
    let mut i = 0;
    while i < s.len() {
        let c = s[i];
        if c == b'\r' || c == b'\n' {
            out.extend_from_slice(br);
            out.push(c);
            if i + 1 < s.len() && ((c == b'\r' && s[i + 1] == b'\n') || (c == b'\n' && s[i + 1] == b'\r')) {
                out.push(s[i + 1]);
                i += 1;
            }
        } else {
            out.push(c);
        }
        i += 1;
    }
    Ok(Value::vec(out))
}

fn html_escape(s: &[u8], flags: i64, double: bool, all: bool) -> Vec<u8> {
    let mut out = Vec::with_capacity(s.len());
    let mut i = 0;
    while i < s.len() {
        let c = s[i];
        match c {
            b'&' => {
                if !double {
                    // check existing entity
                    if let Some(end) = s[i..].iter().take(12).position(|&x| x == b';') {
                        let ent = &s[i + 1..i + end];
                        let valid = !ent.is_empty() && (ent.iter().all(|c| c.is_ascii_alphanumeric()) || (ent[0] == b'#' && ent.len() > 1 && (ent[1..].iter().all(|c| c.is_ascii_digit()) || ((ent[1] == b'x' || ent[1] == b'X') && ent.len() > 2 && ent[2..].iter().all(|c| c.is_ascii_hexdigit())))));
                        if valid {
                            out.push(b'&');
                            i += 1;
                            continue;
                        }
                    }
                }
                out.extend_from_slice(b"&amp;");
            }
            b'<' => out.extend_from_slice(b"&lt;"),
            b'>' => out.extend_from_slice(b"&gt;"),
            b'"' if flags & 2 != 0 => out.extend_from_slice(b"&quot;"),
            b'\'' if flags & 1 != 0 => {
                if flags & (16 | 32) != 0 {
                    out.extend_from_slice(b"&apos;");
                } else {
                    out.extend_from_slice(b"&#039;");
                }
            }
            _ => {
                if all && c >= 0x80 {
                    // decode utf-8 and map common entities
                    let (cp, len) = crate::builtins::json::utf8_decode_at(s, i);
                    if let Some(name) = entity_name(cp) {
                        out.push(b'&');
                        out.extend_from_slice(name.as_bytes());
                        out.push(b';');
                        i += len;
                        continue;
                    }
                    out.extend_from_slice(&s[i..i + len]);
                    i += len;
                    continue;
                }
                out.push(c)
            }
        }
        i += 1;
    }
    out
}

fn entity_name(cp: u32) -> Option<&'static str> {
    Some(match cp {
        0xA0 => "nbsp",
        0xA9 => "copy",
        0xAE => "reg",
        0xE9 => "eacute",
        0xE8 => "egrave",
        0xE0 => "agrave",
        0xE1 => "aacute",
        0xE7 => "ccedil",
        0xF1 => "ntilde",
        0xF6 => "ouml",
        0xFC => "uuml",
        0xE4 => "auml",
        0xDF => "szlig",
        0xC9 => "Eacute",
        0x20AC => "euro",
        0xA3 => "pound",
        0xA5 => "yen",
        0xB0 => "deg",
        0x2014 => "mdash",
        0x2013 => "ndash",
        0x2026 => "hellip",
        0xAB => "laquo",
        0xBB => "raquo",
        0x201C => "ldquo",
        0x201D => "rdquo",
        0x2018 => "lsquo",
        0x2019 => "rsquo",
        0xD7 => "times",
        0xF7 => "divide",
        _ => return None,
    })
}

