fn html_decode(s: &[u8], flags: i64, all: bool) -> Vec<u8> {
    let mut out = Vec::with_capacity(s.len());
    let mut i = 0;
    while i < s.len() {
        if s[i] == b'&' {
            if let Some(end) = s[i..].iter().take(12).position(|&x| x == b';') {
                let ent = &s[i + 1..i + end];
                let rep: Option<Vec<u8>> = match ent {
                    b"amp" => Some(b"&".to_vec()),
                    b"lt" => Some(b"<".to_vec()),
                    b"gt" => Some(b">".to_vec()),
                    b"quot" if flags & 2 != 0 => Some(b"\"".to_vec()),
                    b"#039" | b"#39" | b"#x27" if flags & 1 != 0 => Some(b"'".to_vec()),
                    b"apos" if flags & 1 != 0 && flags & (16 | 32) != 0 => Some(b"'".to_vec()),
                    _ => {
                        if ent.len() > 1 && ent[0] == b'#' && all {
                            let n = if ent[1] == b'x' || ent[1] == b'X' { u32::from_str_radix(&String::from_utf8_lossy(&ent[2..]), 16).ok() } else { String::from_utf8_lossy(&ent[1..]).parse::<u32>().ok() };
                            n.map(|cp| {
                                let mut v = Vec::new();
                                crate::lexer::encode_utf8(cp, &mut v);
                                v
                            })
                        } else if all {
                            let name = String::from_utf8_lossy(ent).to_string();
                            (0x20u32..0x2200).find(|cp| entity_name(*cp) == Some(name.as_str())).map(|cp| {
                                let mut v = Vec::new();
                                crate::lexer::encode_utf8(cp, &mut v);
                                v
                            })
                        } else {
                            None
                        }
                    }
                };
                if let Some(r) = rep {
                    out.extend_from_slice(&r);
                    i += end + 1;
                    continue;
                }
            }
        }
        out.push(s[i]);
        i += 1;
    }
    out
}
fn f_htmlspecialchars_decode(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let flags = a.int_or(it, 1, 3 | 8 | 48)?;
    Ok(Value::vec(html_decode(&s, flags, false)))
}
