}
fn f_addslashes(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let mut out = Vec::with_capacity(s.len());
    for &c in s.iter() {
        match c {
            b'\'' | b'"' | b'\\' => {
                out.push(b'\\');
                out.push(c);
            }
            0 => out.extend_from_slice(b"\\0"),
            _ => out.push(c),
        }
    }
    Ok(Value::vec(out))
}
fn f_stripslashes(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let mut out = Vec::with_capacity(s.len());
    let mut i = 0;
    while i < s.len() {
        if s[i] == b'\\' {
            if i + 1 < s.len() {
                if s[i + 1] == b'0' {
                    out.push(0);
                } else {
                    out.push(s[i + 1]);
                }
                i += 2;
            } else {
                i += 1;
            }
        } else {
            out.push(s[i]);
            i += 1;
        }
    }
    Ok(Value::vec(out))
}
fn f_addcslashes(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let m = a.str(it, 1)?;
    let mask = char_mask(&m);
    let mut out = Vec::new();
    for &c in s.iter() {
        if mask[c as usize] {
            out.push(b'\\');
            match c {
                b'\n' => out.push(b'n'),
                b'\t' => out.push(b't'),
                b'\r' => out.push(b'r'),
                0x07 => out.push(b'a'),
                0x0b => out.push(b'v'),
                0x08 => out.push(b'b'),
                0x0c => out.push(b'f'),
                c if c < 32 || c > 126 => out.extend_from_slice(format!("{:03o}", c).as_bytes()),
                c => out.push(c),
            }
        } else {
            out.push(c);
        }
    }
    Ok(Value::vec(out))
}
fn f_stripcslashes(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let mut out = Vec::new();
    let mut i = 0;
    while i < s.len() {
        if s[i] == b'\\' && i + 1 < s.len() {
            i += 1;
            match s[i] {
                b'n' => out.push(b'\n'),
                b't' => out.push(b'\t'),
                b'r' => out.push(b'\r'),
                b'a' => out.push(7),
                b'v' => out.push(11),
                b'b' => out.push(8),
                b'f' => out.push(12),
                b'x' => {
                    let mut v = 0u32;
                    let mut n = 0;
                    while n < 2 && i + 1 < s.len() && s[i + 1].is_ascii_hexdigit() {
                        i += 1;
                        v = v * 16 + (s[i] as char).to_digit(16).unwrap();
                        n += 1;
                    }
                    out.push(v as u8);
                }
                c if (b'0'..=b'7').contains(&c) => {
                    let mut v = (c - b'0') as u32;
                    let mut n = 1;
                    while n < 3 && i + 1 < s.len() && (b'0'..=b'7').contains(&s[i + 1]) {
                        i += 1;
                        v = v * 8 + (s[i] - b'0') as u32;
                        n += 1;
                    }
                    out.push(v as u8);
                }
                c => out.push(c),
            }
            i += 1;
        } else {
            out.push(s[i]);
            i += 1;
        }
    }
    Ok(Value::vec(out))
}
fn f_quotemeta(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let mut out = Vec::new();
    for &c in s.iter() {
        if b".\\+*?[^]$()".contains(&c) {
            out.push(b'\\');
        }
        out.push(c);
    }
    Ok(Value::vec(out))
}
