fn f_wordwrap(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let width = a.int_or(it, 1, 75)?;
    let brk = a.str_or(it, 2, b"\n")?;
    let cut = a.bool_or(it, 3, false)?;
    if brk.is_empty() {
        return Err(a.value_err(it, 2, "cannot be empty"));
    }
    if width == 0 && cut {
        return Err(a.value_err(it, 1, "cannot be 0 when argument #4 ($cut_long_words) is true"));
    }
    let w = width.max(0) as usize;
    // port of php wordwrap general algorithm
    let text = &s[..];
    let bl = brk.len();
    let mut out: Vec<u8> = Vec::new();
    let mut current = 0usize;
    let mut laststart = 0usize;
    let mut lastspace = 0usize;
    let n = text.len();
    while current < n {
        let c = text[current];
        if c == brk[0] && current + bl < n && &text[current..current + bl] == &brk[..] {
            out.extend_from_slice(&text[laststart..current + bl]);
            current += bl - 1;
            laststart = current + 1;
            lastspace = laststart;
        } else if c == b' ' {
            if current - laststart >= w {
                out.extend_from_slice(&text[laststart..current]);
                out.extend_from_slice(&brk);
                laststart = current + 1;
            }
            lastspace = current;
        } else if current - laststart >= w && cut && laststart >= lastspace {
            out.extend_from_slice(&text[laststart..current]);
            out.extend_from_slice(&brk);
            laststart = current;
            lastspace = current;
        } else if current - laststart >= w && laststart < lastspace {
            out.extend_from_slice(&text[laststart..lastspace]);
            out.extend_from_slice(&brk);
            laststart = lastspace + 1;
            lastspace = laststart;
        }
        current += 1;
    }
    if laststart != current {
        out.extend_from_slice(&text[laststart..current]);
    }
    Ok(Value::vec(out))
}
fn f_chunk_split(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let n = a.int_or(it, 1, 76)?;
    let end = a.str_or(it, 2, b"\r\n")?;
    if n < 1 {
        return Err(a.value_err(it, 1, "must be greater than 0"));
    }
    let mut out = Vec::new();
    for c in s.chunks(n as usize) {
        out.extend_from_slice(c);
        out.extend_from_slice(&end);
    }
    Ok(Value::vec(out))
}
fn similar(a: &[u8], b: &[u8]) -> usize {
    if a.is_empty() || b.is_empty() {
        return 0;
    }
    let mut max = 0;
    let mut pa = 0;
    let mut pb = 0;
    for i in 0..a.len() {
        for j in 0..b.len() {
            let mut k = 0;
            while i + k < a.len() && j + k < b.len() && a[i + k] == b[j + k] {
                k += 1;
            }
            if k > max {
                max = k;
                pa = i;
                pb = j;
            }
        }
    }
    if max == 0 {
        return 0;
    }
    max + similar(&a[..pa], &b[..pb]) + similar(&a[pa + max..], &b[pb + max..])
}
fn f_similar_text(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s1 = a.str(it, 0)?;
    let s2 = a.str(it, 1)?;
    let sim = similar(&s1, &s2);
    if a.len() > 2 {
        let pct = if s1.len() + s2.len() == 0 { 0.0 } else { sim as f64 * 2.0 * 100.0 / (s1.len() + s2.len()) as f64 };
        a.set_ref(2, Value::Float(pct));
    }
    Ok(Value::Int(sim as i64))
}
fn f_levenshtein(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s1 = a.str(it, 0)?;
    let s2 = a.str(it, 1)?;
    let ci = a.int_or(it, 2, 1)?;
    let cr = a.int_or(it, 3, 1)?;
    let cd = a.int_or(it, 4, 1)?;
    if s1.is_empty() {
        return Ok(Value::Int(s2.len() as i64 * ci));
    }
    if s2.is_empty() {
        return Ok(Value::Int(s1.len() as i64 * cd));
    }
    let mut p1: Vec<i64> = (0..=s2.len() as i64).map(|x| x * ci).collect();
    let mut p2 = vec![0i64; s2.len() + 1];
    for i in 0..s1.len() {
        p2[0] = p1[0] + cd;
        for j in 0..s2.len() {
            let mut c0 = p1[j] + if s1[i] == s2[j] { 0 } else { cr };
            let c1 = p1[j + 1] + cd;
            if c1 < c0 {
                c0 = c1;
            }
            let c2 = p2[j] + ci;
            if c2 < c0 {
                c0 = c2;
            }
            p2[j + 1] = c0;
        }
        std::mem::swap(&mut p1, &mut p2);
    }
    Ok(Value::Int(p1[s2.len()]))
}
fn f_soundex(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let code = |c: u8| -> u8 {
        match c.to_ascii_uppercase() {
            b'B' | b'F' | b'P' | b'V' => b'1',
            b'C' | b'G' | b'J' | b'K' | b'Q' | b'S' | b'X' | b'Z' => b'2',
            b'D' | b'T' => b'3',
            b'L' => b'4',
            b'M' | b'N' => b'5',
            b'R' => b'6',
            _ => 0,
        }
    };
    let mut out = Vec::new();
    let mut last = 0u8;
    for &c in s.iter() {
        if !c.is_ascii_alphabetic() {
            continue;
        }
        let cu = c.to_ascii_uppercase();
        if out.is_empty() {
            out.push(cu);
            last = code(cu);
        } else {
            let cd = code(cu);
            if cd != 0 && cd != last {
                out.push(cd);
            }
            if cu != b'H' && cu != b'W' {
                last = cd;
            }
        }
        if out.len() == 4 {
            break;
        }
    }
    if out.is_empty() {
        return Ok(Value::str(""));
    }
    while out.len() < 4 {
        out.push(b'0');
    }
    Ok(Value::vec(out))
}
