fn span_common(it: &mut Interp, a: &Args, accept: bool) -> R<Value> {
    let s = a.str(it, 0)?;
    let m = a.str(it, 1)?;
    let off = a.int_or(it, 2, 0)?;
    let len = a.opt_int(it, 3)?;
    let n = s.len() as i64;
    let st = if off < 0 { (n + off).max(0) } else { off.min(n) } as usize;
    let en = match len {
        None => n as usize,
        Some(l) if l < 0 => ((n + l).max(st as i64)) as usize,
        Some(l) => ((st as i64 + l).min(n)) as usize,
    };
    let mut c = 0;
    for &ch in &s[st..en.max(st)] {
        if m.contains(&ch) != accept {
            break;
        }
        c += 1;
    }
    Ok(Value::Int(c))
}
