fn f_strtok(it: &mut Interp, a: &mut Args) -> R<Value> {
    thread_local! {
        static TOK: std::cell::RefCell<(Vec<u8>, usize)> = const { std::cell::RefCell::new((Vec::new(), 0)) };
    }
    let (delims, reset) = if a.len() >= 2 {
        let s = a.str(it, 0)?;
        TOK.with(|t| *t.borrow_mut() = (s.to_vec(), 0));
        (a.str(it, 1)?, true)
    } else {
        (a.str(it, 0)?, false)
    };
    let _ = reset;
    TOK.with(|t| {
        let mut t = t.borrow_mut();
        let (s, pos) = &mut *t;
        let mut p = *pos;
        while p < s.len() && delims.contains(&s[p]) {
            p += 1;
        }
        if p >= s.len() {
            *pos = p;
            return Ok(Value::Bool(false));
        }
        let st = p;
        while p < s.len() && !delims.contains(&s[p]) {
            p += 1;
        }
        let tok = s[st..p].to_vec();
        *pos = if p < s.len() { p + 1 } else { p };
        Ok(Value::vec(tok))
    })
}
fn f_str_increment(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    if s.is_empty() {
        return Err(a.value_err(it, 0, "cannot be empty"));
    }
    if !s.iter().all(|c| c.is_ascii_alphanumeric()) {
        return Err(a.value_err(it, 0, "must be composed only of alphanumeric ASCII characters"));
    }
    Ok(Value::vec(crate::interp::lval::str_increment(&s)))
}
fn f_str_decrement(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    if s.is_empty() {
        return Err(a.value_err(it, 0, "cannot be empty"));
    }
    let mut v = s.to_vec();
    let mut i = v.len();
    loop {
        if i == 0 {
            break;
        }
        i -= 1;
        match v[i] {
            b'a' => v[i] = b'z',
            b'A' => v[i] = b'Z',
            b'0' => v[i] = b'9',
            c => {
                v[i] = c - 1;
                break;
            }
        }
    }
    if v.len() > 1 && (s[0] == b'a' || s[0] == b'A' || s[0] == b'1') && (v[0] == b'z' || v[0] == b'Z' || v[0] == b'0') && s[0] != v[0] {
        if s[0] == b'1' && v[0] == b'0' || s[0] == b'a' || s[0] == b'A' {
            v.remove(0);
        }
    }
    Ok(Value::vec(v))
}
