        match a.get(i) {
            Value::Array(x) => arrs.push(x),
            other => {
                let msg = format!("array_map(): Argument #{} must be of type array, {} given", i + 1, other.type_name());
                return Err(it.type_error(&msg));
            }
        }
    }
    let maxn = arrs.iter().map(|x| x.len()).max().unwrap_or(0);
    let vals: Vec<Vec<Value>> = arrs.iter().map(|x| x.values().map(|v| v.deref()).collect()).collect();
    let mut out = PArray::new();
    for i in 0..maxn {
        let args: Vec<Value> = vals.iter().map(|v| v.get(i).cloned().unwrap_or(Value::Null)).collect();
        if has_cb {
            out.push(it.call_value(&cb, args)?);
        } else {
            out.push(Value::arr(PArray::from_values(args)));
        }
    }
    Ok(Value::arr(out))
}
fn f_array_filter(it: &mut Interp, a: &mut Args) -> R<Value> {
    let arr = get_arr(it, a, 0)?;
    let cb = if a.has(1) && !a.get(1).is_null() { Some(a.callable(it, 1)?) } else { None };
    let mode = a.int_or(it, 2, 0)?;
    let mut out = PArray::new();
    for (k, v) in arr.iter() {
        let v = v.deref();
        let keep = match &cb {
            None => v.to_bool(),
            Some(cb) => {
                let args = match mode {
                    2 => vec![k.to_value()],
                    1 => vec![v.clone(), k.to_value()],
                    _ => vec![v.clone()],
                };
                it.call_value(cb, args)?.to_bool()
            }
        };
        if keep {
            out.set(k.clone(), v);
        }
    }
    Ok(Value::arr(out))
}
fn f_array_reduce(it: &mut Interp, a: &mut Args) -> R<Value> {
    let arr = get_arr(it, a, 0)?;
    let cb = a.callable(it, 1)?;
    let mut acc = a.get(2);
    for v in arr.values() {
        acc = it.call_value(&cb, vec![acc, v.deref()])?;
    }
    Ok(acc)
}
fn f_array_walk(it: &mut Interp, a: &mut Args) -> R<Value> {
    let cb = a.callable(it, 1)?;
    let extra = if a.has(2) { Some(a.get(2)) } else { None };
    let r = match a.r(0) {
        Some(r) => r,
        None => return Ok(Value::Bool(false)),
    };
    // object?
    let is_obj = matches!(&*r.borrow(), Value::Object(_));
    if is_obj {
        let o = r.borrow().clone();
        if let Value::Object(o) = o {
            let props = it.visible_props(&o, None);
            for (k, v) in props {
                let mut args = vec![v.deref(), Key::from_str_bytes(&k).to_value()];
                if let Some(e) = &extra {
                    args.push(e.clone());
                }
                it.call_value(&cb, args)?;
            }
        }
        return Ok(Value::Bool(true));
    }
    let keys: Vec<Key> = match &*r.borrow() {
        Value::Array(arr) => arr.keys().cloned().collect(),
        _ => return Ok(Value::Bool(false)),
    };
    for k in keys {
        let elem_ref = {
            let mut b = r.borrow_mut();
            match &mut *b {
                Value::Array(arr) => {
                    let m = Rc::make_mut(arr);
                    match m.get_mut(&k) {
                        Some(slot) => crate::interp::lval::wrap_ref(slot),
                        None => continue,
                    }
                }
                _ => break,
            }
        };
        let mut args = vec![Value::Ref(elem_ref), k.to_value()];
        if let Some(e) = &extra {
            args.push(e.clone());
        }
        it.call_value(&cb, args)?;
    }
    // unwrap refcount-1 refs
    if let Value::Array(arr) = &mut *r.borrow_mut() {
        let m = Rc::make_mut(arr);
        for (_, v) in m.iter_mut() {
            if let Value::Ref(rr) = v {
                if Rc::strong_count(rr) == 1 {
                    let inner = rr.borrow().clone();
                    *v = inner;
                }
            }
        }
    }
    Ok(Value::Bool(true))
}
fn walk_rec(it: &mut Interp, r: &PRef, cb: &Value, extra: &Option<Value>) -> R<()> {
    let keys: Vec<Key> = match &*r.borrow() {
        Value::Array(arr) => arr.keys().cloned().collect(),
        _ => return Ok(()),
    };
    for k in keys {
        let elem_ref = {
            let mut b = r.borrow_mut();
            match &mut *b {
                Value::Array(arr) => {
                    let m = Rc::make_mut(arr);
                    match m.get_mut(&k) {
                        Some(slot) => crate::interp::lval::wrap_ref(slot),
                        None => continue,
                    }
                }
                _ => break,
            }
        };
        let is_arr = matches!(&*elem_ref.borrow(), Value::Array(_));
        if is_arr {
            walk_rec(it, &elem_ref, cb, extra)?;
        } else {
            let mut args = vec![Value::Ref(elem_ref), k.to_value()];
            if let Some(e) = extra {
                args.push(e.clone());
            }
            it.call_value(cb, args)?;
        }
    }
    if let Value::Array(arr) = &mut *r.borrow_mut() {
        let m = Rc::make_mut(arr);
        for (_, v) in m.iter_mut() {
            if let Value::Ref(rr) = v {
                if Rc::strong_count(rr) == 1 {
                    let inner = rr.borrow().clone();
                    *v = inner;
                }
            }
        }
    }
    Ok(())
}
fn f_array_walk_recursive(it: &mut Interp, a: &mut Args) -> R<Value> {
    let cb = a.callable(it, 1)?;
    let extra = if a.has(2) { Some(a.get(2)) } else { None };
    if let Some(r) = a.r(0) {
        walk_rec(it, &r, &cb, &extra)?;
    }
    Ok(Value::Bool(true))
}
fn search(it: &mut Interp, a: &Args) -> R<Option<Key>> {
    let needle = a.get(0);
    let arr = get_arr(it, a, 1)?;
    let strict = a.bool_or(it, 2, false)?;
    for (k, v) in arr.iter() {
        let v = v.deref();
        let eq = if strict {
            crate::interp::ops::strict_equals(&v, &needle)
        } else {
            match (&v, &needle) {
                (Value::Int(x), Value::Int(y)) => x == y,
                (Value::Str(x), Value::Str(y)) if str_numeric(x).is_none() && str_numeric(y).is_none() => x == y,
                _ => it.loose_eq(&v, &needle)?,
            }
        };
        if eq {
            return Ok(Some(k.clone()));
        }
    }
    Ok(None)
}
fn f_in_array(it: &mut Interp, a: &mut Args) -> R<Value> {
    Ok(Value::Bool(search(it, a)?.is_some()))
}
fn f_array_search(it: &mut Interp, a: &mut Args) -> R<Value> {
    Ok(match search(it, a)? {
        Some(k) => k.to_value(),
        None => Value::Bool(false),
    })
}
fn f_array_key_exists(it: &mut Interp, a: &mut Args) -> R<Value> {
    let k = a.get(0);
    match a.get(1) {
        Value::Array(arr) => {
            let key = match &k {
                Value::Int(i) => Key::Int(*i),
                Value::Str(s) => Key::from_pstr(s),
                Value::Null => Key::Str(Rc::new(Vec::new())),
                Value::Bool(b) => Key::Int(*b as i64),
                Value::Float(f) => Key::Int(*f as i64),
                other => {
                    let msg = format!("Cannot access offset of type {} on array", crate::interp::ops::type_for_op(other));
                    return Err(it.type_error(&msg));
                }
            };
            Ok(Value::Bool(arr.contains_key(&key)))
        }
        other => {
            let msg = format!("array_key_exists(): Argument #2 ($array) must be of type array, {} given", other.type_name());
            Err(it.type_error(&msg))
        }
    }
}
fn f_array_key_first(it: &mut Interp, a: &mut Args) -> R<Value> {
    let arr = get_arr(it, a, 0)?;
    Ok(arr.first().map(|(k, _)| k.to_value()).unwrap_or(Value::Null))
