pub fn sort_cmp(it: &mut Interp, x: &Value, y: &Value, flags: i64) -> R<i32> {
    let base = flags & !8;
    let ci = flags & 8 != 0;
    match base {
        1 => {
            let (a, b) = (x.to_float(), y.to_float());
            Ok(crate::interp::ops::cmp_f(a, b))
        }
        2 | 5 => {
            let a = it.to_str(x)?;
            let b = it.to_str(y)?;
            if ci {
                Ok(crate::interp::ops::byte_cmp(&a.to_ascii_lowercase(), &b.to_ascii_lowercase()))
            } else {
                Ok(crate::interp::ops::byte_cmp(&a, &b))
            }
        }
        6 => {
            let a = it.to_str(x)?;
            let b = it.to_str(y)?;
            Ok(super::string::strnatcmp(&a, &b, ci))
        }
        _ => it.compare(x, y),
    }
}

pub fn key_cmp(it: &mut Interp, x: &Key, y: &Key, flags: i64) -> R<i32> {
    let base = flags & !8;
    if base == 0 {
        // regular key compare
        return Ok(match (x, y) {
            (Key::Int(a), Key::Int(b)) => crate::interp::ops::cmp_i(*a, *b),
            _ => it.compare(&x.to_value(), &y.to_value())?,
        });
    }
    sort_cmp(it, &x.to_value(), &y.to_value(), flags)
}

/// stable sort with fallible comparator
pub fn stable_sort<T: Clone>(it: &mut Interp, v: &mut Vec<T>, cmp: &mut dyn FnMut(&mut Interp, &T, &T) -> R<i32>) -> R<()> {
    let n = v.len();
    if n < 2 {
        return Ok(());
    }
    if n <= 16 {
        // insertion sort
        for i in 1..n {
            let mut j = i;
            while j > 0 {
                let c = cmp(it, &v[j - 1], &v[j])?;
                if c > 0 {
                    v.swap(j - 1, j);
                    j -= 1;
                } else {
                    break;
                }
            }
        }
        return Ok(());
    }
    let mut err: Option<Flow> = None;
    let itp: *mut Interp = it;
    v.sort_by(|a, b| {
        if err.is_some() {
            return Ordering::Equal;
        }
        let it = unsafe { &mut *itp };
        match cmp(it, a, b) {
            Ok(c) => c.cmp(&0),
            Err(e) => {
                err = Some(e);
                Ordering::Equal
            }
        }
    });
    match err {
        Some(e) => Err(e),
        None => Ok(()),
    }
}

fn user_cmp(it: &mut Interp, cb: &Value, x: &Value, y: &Value, fname: &str) -> R<i32> {
    let r = it.call_value(cb, vec![x.clone(), y.clone()])?;
    Ok(match r {
        Value::Bool(b) => {
            let msg = format!("{}(): Returning bool from comparison function is deprecated, return an integer less than, equal to, or greater than zero", fname);
            it.deprecated(&msg)?;
            if b {
                1
            } else {
                // PHP re-calls with swapped args when false
                let r2 = it.call_value(cb, vec![y.clone(), x.clone()])?;
                if r2.to_bool() {
                    -1
                } else {
                    0
                }
            }
        }
        Value::Int(i) => i.signum() as i32,
        Value::Float(f) => {
            if f < 0.0 {
                -1
            } else if f > 0.0 {
                1
            } else {
                0
            }
        }
        other => other.to_int().signum() as i32,
    })
}

fn do_sort(it: &mut Interp, a: &mut Args, by_key: bool, keep_keys: bool, reverse: bool, user: bool) -> R<Value> {
    let flags = if user { 0 } else { a.int_or(it, 1, 0)? };
    let cb = if user { Some(a.callable(it, 1)?) } else { None };
    let r = match a.r(0) {
        Some(r) => r,
        None => return Ok(Value::Bool(true)),
    };
    let arr = match &*r.borrow() {
        Value::Array(x) => x.clone(),
        other => {
            let msg = format!("{}(): Argument #1 ($array) must be of type array, {} given", a.def.name, other.type_name());
            drop(other);
            return Err(it.type_error(&msg));
        }
    };
    let mut pairs: Vec<(Key, Value)> = arr.iter().map(|(k, v)| (k.clone(), v.clone())).collect();
    drop(arr);
    let fname = a.def.name;
    stable_sort(it, &mut pairs, &mut |it, x, y| {
        let c = if by_key {
            match &cb {
                Some(cb) => user_cmp(it, cb, &x.0.to_value(), &y.0.to_value(), fname)?,
                None => key_cmp(it, &x.0, &y.0, flags)?,
            }
        } else {
            match &cb {
                Some(cb) => user_cmp(it, cb, &x.1.deref(), &y.1.deref(), fname)?,
                None => sort_cmp(it, &x.1.deref(), &y.1.deref(), flags)?,
            }
        };
        Ok(if reverse { -c } else { c })
    })?;
    let out = if keep_keys {
        PArray::from_pairs(pairs)
    } else {
        PArray::from_values(pairs.into_iter().map(|(_, v)| v).collect())
    };
    *r.borrow_mut() = Value::arr(out);
    Ok(Value::Bool(true))
}
fn f_sort(it: &mut Interp, a: &mut Args) -> R<Value> {
    do_sort(it, a, false, false, false, false)
}
fn f_rsort(it: &mut Interp, a: &mut Args) -> R<Value> {
    do_sort(it, a, false, false, true, false)
}
