fn natsort_common(it: &mut Interp, a: &mut Args, ci: bool) -> R<Value> {
    let r = match a.r(0) {
        Some(r) => r,
        None => return Ok(Value::Bool(true)),
    };
    let arr = match &*r.borrow() {
        Value::Array(x) => x.clone(),
        _ => return Ok(Value::Bool(false)),
    };
    let mut pairs: Vec<(Key, Value)> = arr.iter().map(|(k, v)| (k.clone(), v.clone())).collect();
    stable_sort(it, &mut pairs, &mut |it, x, y| {
        let a = it.to_str(&x.1.deref())?;
        let b = it.to_str(&y.1.deref())?;
        Ok(super::string::strnatcmp(&a, &b, ci))
    })?;
    *r.borrow_mut() = Value::arr(PArray::from_pairs(pairs));
    Ok(Value::Bool(true))
}
