    natsort_common(it, a, true)
}
fn f_array_multisort(it: &mut Interp, a: &mut Args) -> R<Value> {
    // collect arrays and their flags
    let mut cols: Vec<(PRef, i64, i64)> = Vec::new(); // (ref, order, flags)
    let mut i = 0;
    while i < a.len() {
        match a.get(i) {
            Value::Array(_) => {
                let r = a.r(i).unwrap_or_else(|| Rc::new(RefCell::new(a.get(i))));
                cols.push((r, 4, 0));
            }
            Value::Int(n) => {
                if let Some(last) = cols.last_mut() {
                    if n == 4 || n == 3 {
                        last.1 = n;
                    } else {
                        last.2 = n;
                    }
                }
            }
            _ => {}
        }
        i += 1;
    }
    if cols.is_empty() {
        return Ok(Value::Bool(false));
    }
    let data: Vec<Vec<(Key, Value)>> = cols.iter().map(|(r, _, _)| match &*r.borrow() {
        Value::Array(x) => x.iter().map(|(k, v)| (k.clone(), v.deref())).collect(),
        _ => vec![],
    }).collect();
    let n = data[0].len();
    if data.iter().any(|d| d.len() != n) {
        return Err(it.value_error("Array sizes are inconsistent"));
    }
    let mut idx: Vec<usize> = (0..n).collect();
    let specs: Vec<(i64, i64)> = cols.iter().map(|c| (c.1, c.2)).collect();
    stable_sort(it, &mut idx, &mut |it, &x, &y| {
        for (c, (ord, fl)) in specs.iter().enumerate() {
            let r = sort_cmp(it, &data[c][x].1, &data[c][y].1, *fl)?;
            if r != 0 {
                return Ok(if *ord == 3 { -r } else { r });
            }
        }
        Ok(0)
    })?;
    for (c, (r, _, _)) in cols.iter().enumerate() {
        let mut out = PArray::new();
        for &ix in &idx {
            let (k, v) = &data[c][ix];
            match k {
                Key::Int(_) => {
                    out.push(v.clone());
                }
                _ => out.set(k.clone(), v.clone()),
            }
        }
        *r.borrow_mut() = Value::arr(out);
    }
    Ok(Value::Bool(true))
}
fn f_array_unique(it: &mut Interp, a: &mut Args) -> R<Value> {
    let arr = get_arr(it, a, 0)?;
    let flags = a.int_or(it, 1, 2)?;
    let mut out = PArray::new();
    let mut seen: Vec<Value> = Vec::new();
    let mut seen_str: std::collections::HashSet<Vec<u8>> = std::collections::HashSet::new();
    for (k, v) in arr.iter() {
        let v = v.deref();
        if flags == 2 {
            let s = it.to_str(&v)?.to_vec();
            if seen_str.insert(s) {
                out.set(k.clone(), v);
            }
            continue;
        }
        let mut dup = false;
        for s in &seen {
            if sort_cmp(it, s, &v, flags)? == 0 {
                dup = true;
                break;
            }
        }
        if !dup {
            seen.push(v.clone());
            out.set(k.clone(), v);
        }
    }
    Ok(Value::arr(out))
}
fn f_array_reverse(it: &mut Interp, a: &mut Args) -> R<Value> {
    let arr = get_arr(it, a, 0)?;
    let pk = a.bool_or(it, 1, false)?;
    let mut out = PArray::new();
    let pairs: Vec<(Key, Value)> = arr.iter().map(|(k, v)| (k.clone(), v.deref())).collect();
    for (k, v) in pairs.into_iter().rev() {
        match k {
            Key::Int(_) if !pk => {
                out.push(v);
            }
            _ => out.set(k, v),
        }
    }
    Ok(Value::arr(out))
}
fn f_array_push(it: &mut Interp, a: &mut Args) -> R<Value> {
    let vals: Vec<Value> = a.v[1..].iter().map(|v| v.deref()).collect();
    let r = with_ref_arr(it, a, 0, |arr| {
        for v in vals {
            if !arr.push(v) {
                return Err(());
            }
        }
        Ok(arr.len())
    })?;
    match r {
        Ok(n) => Ok(Value::Int(n as i64)),
        Err(()) => Err(it.error("Cannot add element to the array as the next element is already occupied")),
    }
}
fn f_array_pop(it: &mut Interp, a: &mut Args) -> R<Value> {
    let r = with_ref_arr(it, a, 0, |arr| arr.pop().map(|(_, v)| v))?;
    Ok(r.map(|v| v.into_deref()).unwrap_or(Value::Null))
}
fn f_array_shift(it: &mut Interp, a: &mut Args) -> R<Value> {
    let r = with_ref_arr(it, a, 0, |arr| {
        if arr.is_empty() {
            return None;
        }
        let pairs = std::mem::take(arr).into_pairs();
        let mut it2 = pairs.into_iter();
        let (_, first) = it2.next().unwrap();
        let mut out = PArray::new();
        for (k, v) in it2 {
            match k {
                Key::Int(_) => {
                    out.push(v);
                }
                _ => out.set(k, v),
            }
        }
        *arr = out;
        Some(first)
    })?;
    Ok(r.map(|v| v.into_deref()).unwrap_or(Value::Null))
}
fn f_array_unshift(it: &mut Interp, a: &mut Args) -> R<Value> {
    let vals: Vec<Value> = a.v[1..].iter().map(|v| v.deref()).collect();
    let n = with_ref_arr(it, a, 0, |arr| {
        let pairs = std::mem::take(arr).into_pairs();
        let mut out = PArray::new();
        for v in vals {
            out.push(v);
        }
        for (k, v) in pairs {
            match k {
                Key::Int(_) => {
                    out.push(v);
                }
                _ => out.set(k, v),
            }
        }
        *arr = out;
        arr.len()
    })?;
    Ok(Value::Int(n as i64))
}
fn f_range(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.get(0);
    let e = a.get(1);
    let step_v = if a.has(2) { a.get(2) } else { Value::Int(1) };
    let mut out = PArray::new();
    // char ranges
    if let (Value::Str(x), Value::Str(y)) = (&s, &e) {
        if x.len() >= 1 && y.len() >= 1 && str_numeric(x).is_none() && str_numeric(y).is_none() {
            let (c1, c2) = (x[0] as i64, y[0] as i64);
            let step = step_v.to_int().abs().max(1);
            if c1 <= c2 {
                let mut c = c1;
                while c <= c2 {
                    out.push(Value::vec(vec![c as u8]));
                    c += step;
                }
            } else {
                let mut c = c1;
                while c >= c2 {
                    out.push(Value::vec(vec![c as u8]));
                    c -= step;
                }
            }
            return Ok(Value::arr(out));
        }
    }
    let to_num = |v: &Value| -> Num {
        match v {
            Value::Int(i) => Num::Int(*i),
            Value::Float(f) => Num::Float(*f),
            Value::Str(s) => str_numeric(s).unwrap_or(Num::Int(0)),
            other => Num::Int(other.to_int()),
        }
    };
    let ns = to_num(&s);
    let ne = to_num(&e);
    let nst = to_num(&step_v);
    let is_float = matches!(ns, Num::Float(_)) || matches!(ne, Num::Float(_)) || matches!(nst, Num::Float(f) if f.fract() != 0.0);
    if is_float {
        let (x, y) = (ns.as_f64(), ne.as_f64());
        let step = nst.as_f64().abs();
        if step == 0.0 {
            return Err(a.value_err(it, 2, "cannot be 0"));
        }
        let n = ((y - x).abs() / step + 1e-9).floor() as i64;
        for i in 0..=n {
            let v = if x <= y { x + i as f64 * step } else { x - i as f64 * step };
            out.push(Value::Float(v));
        }
        return Ok(Value::arr(out));
    }
    let (x, y) = (ns.as_f64() as i64, ne.as_f64() as i64);
    let step = match nst {
        Num::Int(i) => i.abs(),
        Num::Float(f) => f.abs() as i64,
    };
    if step == 0 {
        return Err(a.value_err(it, 2, "cannot be 0"));
    }
    if (x - y).unsigned_abs() / step as u64 > 100_000_000 {
        return Err(a.value_err(it, 2, "must not exceed the specified range"));
    }
    if x <= y {
        let mut c = x;
        while c <= y {
            out.push(Value::Int(c));
            c += step;
        }
    } else {
        let mut c = x;
        while c >= y {
            out.push(Value::Int(c));
            c -= step;
        }
    }
    Ok(Value::arr(out))
}
fn f_array_fill(it: &mut Interp, a: &mut Args) -> R<Value> {
    let st = a.int(it, 0)?;
    let n = a.int(it, 1)?;
    if n < 0 {
        return Err(a.value_err(it, 1, "must be greater than or equal to 0"));
    }
    let v = a.get(2);
    let mut out = PArray::new();
    for i in 0..n {
        out.set(Key::Int(st + i), v.clone());
    }
    Ok(Value::arr(out))
}
fn f_array_fill_keys(it: &mut Interp, a: &mut Args) -> R<Value> {
    let keys = get_arr(it, a, 0)?;
    let v = a.get(1);
    let mut out = PArray::new();
    for k in keys.values() {
        let key = match k.deref() {
            Value::Int(i) => Key::Int(i),
            other => Key::from_pstr(&it.to_str(&other)?),
        };
        out.set(key, v.clone());
    }
    Ok(Value::arr(out))
}
fn f_array_pad(it: &mut Interp, a: &mut Args) -> R<Value> {
    let arr = get_arr(it, a, 0)?;
    let n = a.int(it, 1)?;
    let v = a.get(2);
    let cur = arr.len() as i64;
    if n.abs() <= cur {
        return Ok(Value::Array(arr));
    }
    let padn = (n.abs() - cur) as usize;
    let mut out = PArray::new();
    let push_all = |out: &mut PArray| {
        for (k, x) in arr.iter() {
            match k {
                Key::Int(_) => {
                    out.push(x.deref());
                }
                _ => out.set(k.clone(), x.deref()),
            }
        }
    };
    if n > 0 {
        push_all(&mut out);
        for _ in 0..padn {
            out.push(v.clone());
        }
    } else {
        for _ in 0..padn {
            out.push(v.clone());
        }
        push_all(&mut out);
    }
    Ok(Value::arr(out))
}
fn f_array_chunk(it: &mut Interp, a: &mut Args) -> R<Value> {
    let arr = get_arr(it, a, 0)?;
    let size = a.int(it, 1)?;
    if size < 1 {
        return Err(a.value_err(it, 1, "must be greater than 0"));
    }
    let pk = a.bool_or(it, 2, false)?;
    let mut out = PArray::new();
    let mut cur = PArray::new();
    for (k, v) in arr.iter() {
        if pk {
            cur.set(k.clone(), v.deref());
        } else {
            cur.push(v.deref());
        }
        if cur.len() as i64 == size {
            out.push(Value::arr(std::mem::take(&mut cur)));
        }
    }
    if !cur.is_empty() {
        out.push(Value::arr(cur));
    }
    Ok(Value::arr(out))
}
fn col_get(it: &mut Interp, row: &Value, key: &Value) -> R<Option<Value>> {
    match row {
        Value::Array(r) => {
            let k = it.to_key(key)?;
            Ok(r.get(&k).map(|v| v.deref()))
        }
        Value::Object(o) => {
            let n = it.to_str(key)?;
            let o = o.clone();
            if it.prop_isset(&o, &n, None)? {
                Ok(Some(it.read_prop(&o, &n, None, true)?))
            } else {
                Ok(None)
            }
        }
        _ => Ok(None),
    }
}
fn f_array_column(it: &mut Interp, a: &mut Args) -> R<Value> {
    let arr = get_arr(it, a, 0)?;
    let col = a.get(1);
    let idx = if a.has(2) { a.get(2) } else { Value::Null };
    let mut out = PArray::new();
    for row in arr.values() {
        let row = row.deref();
        let v = if col.is_null() {
            Some(row.clone())
        } else {
            col_get(it, &row, &col)?
        };
        let v = match v {
            Some(v) => v,
            None => continue,
        };
        if !idx.is_null() {
            if let Some(k) = col_get(it, &row, &idx)? {
                let key = it.to_key(&k)?;
                out.set(key, v);
                continue;
            }
        }
        out.push(v);
    }
    Ok(Value::arr(out))
}

enum SetMode {
    Value,
    Key,
    Assoc,
}

fn set_op(it: &mut Interp, a: &mut Args, diff: bool, mode: SetMode, vcb: bool, kcb: bool) -> R<Value> {
    let mut nargs = a.len();
    let mut vcmp: Option<Value> = None;
    let mut kcmp: Option<Value> = None;
    if kcb {
        nargs -= 1;
        kcmp = Some(a.get(nargs));
    }
    if vcb {
        nargs -= 1;
        vcmp = Some(a.get(nargs));
    }
    let first = get_arr(it, a, 0)?;
    let mut others = Vec::new();
    for i in 1..nargs {
        others.push(get_arr(it, a, i)?);
    }
    let mut out = PArray::new();
    // fast path for value-based diff/intersect without callbacks: string compare
    let mut other_sets: Vec<std::collections::HashSet<Vec<u8>>> = Vec::new();
    let fast = matches!(mode, SetMode::Value) && vcmp.is_none();
    if fast {
        for o in &others {
            let mut s = std::collections::HashSet::new();
            for v in o.values() {
                s.insert(it.to_str(&v.deref())?.to_vec());
            }
            other_sets.push(s);
        }
    }
    for (k, v) in first.iter() {
        let v = v.deref();
        let mut in_all = true;
        let mut in_any = false;
        if fast {
            let sv = it.to_str(&v)?.to_vec();
            for s in &other_sets {
                if s.contains(&sv) {
                    in_any = true;
                } else {
                    in_all = false;
                }
            }
        } else {
            for o in &others {
                let mut found = false;
                match mode {
                    SetMode::Key => {
                        if let Some(kc) = &kcmp {
                            for ok in o.keys() {
                                if it.call_value(kc, vec![k.to_value(), ok.to_value()])?.to_int() == 0 {
                                    found = true;
                                    break;
                                }
                            }
                        } else {
                            found = o.contains_key(k);
                        }
                    }
                    SetMode::Assoc => {
                        let cands: Vec<(Key, Value)> = if let Some(kc) = &kcmp {
                            let mut c = Vec::new();
                            for (ok, ov) in o.iter() {
                                if it.call_value(kc, vec![k.to_value(), ok.to_value()])?.to_int() == 0 {
                                    c.push((ok.clone(), ov.deref()));
                                }
                            }
                            c
                        } else {
                            o.get(k).map(|ov| vec![(k.clone(), ov.deref())]).unwrap_or_default()
                        };
                        for (_, ov) in cands {
                            let eq = match &vcmp {
                                Some(vc) => it.call_value(vc, vec![v.clone(), ov.clone()])?.to_int() == 0,
                                None => it.to_str(&v)?.as_slice() == it.to_str(&ov)?.as_slice(),
                            };
                            if eq {
                                found = true;
                                break;
                            }
                        }
                    }
                    SetMode::Value => {
                        for ov in o.values() {
                            let ov = ov.deref();
                            let eq = match &vcmp {
                                Some(vc) => it.call_value(vc, vec![v.clone(), ov.clone()])?.to_int() == 0,
                                None => it.to_str(&v)?.as_slice() == it.to_str(&ov)?.as_slice(),
                            };
                            if eq {
                                found = true;
                                break;
                            }
                        }
                    }
                }
                if found {
                    in_any = true;
                } else {
                    in_all = false;
                }
            }
        }
        let keep = if diff { !in_any } else { in_all };
        if keep {
            out.set(k.clone(), v);
        }
    }
    Ok(Value::arr(out))
}
fn f_array_diff(it: &mut Interp, a: &mut Args) -> R<Value> {
    set_op(it, a, true, SetMode::Value, false, false)
}
