fn f_array_count_values(it: &mut Interp, a: &mut Args) -> R<Value> {
    let arr = get_arr(it, a, 0)?;
    let mut out = PArray::new();
    for v in arr.values() {
        match v.deref() {
            Value::Int(i) => {
                let e = out.entry_mut(Key::Int(i));
                *e = Value::Int(e.to_int() + 1);
            }
            Value::Str(s) => {
                let e = out.entry_mut(Key::from_pstr(&s));
                *e = Value::Int(e.to_int() + 1);
            }
            _ => {
                it.warn("array_count_values(): Can only count string and integer values, entry skipped")?;
            }
        }
    }
    Ok(Value::arr(out))
}
fn f_array_rand(it: &mut Interp, a: &mut Args) -> R<Value> {
    let arr = get_arr(it, a, 0)?;
    let n = a.int_or(it, 1, 1)?;
    let len = arr.len() as i64;
    if len == 0 {
        return Err(a.value_err(it, 0, "cannot be empty"));
    }
    if n < 1 || n > len {
        return Err(a.value_err(it, 1, "must be between 1 and the number of elements in argument #1 ($array)"));
    }
    let keys: Vec<Key> = arr.keys().cloned().collect();
    if n == 1 {
        let i = it.mt.range(0, len - 1) as usize;
        return Ok(keys[i].to_value());
    }
    // selection sampling preserving order
    let mut out = PArray::new();
    let mut need = n;
    let mut left = len;
    for k in keys.iter() {
        let r = it.mt.range(0, left - 1);
        if r < need {
            out.push(k.to_value());
            need -= 1;
        }
        left -= 1;
        if need == 0 {
            break;
        }
    }
    Ok(Value::arr(out))
}
fn f_shuffle(it: &mut Interp, a: &mut Args) -> R<Value> {
    let r = match a.r(0) {
        Some(r) => r,
        None => return Ok(Value::Bool(true)),
    };
    let mut vals: Vec<Value> = match &*r.borrow() {
        Value::Array(x) => x.values().cloned().collect(),
        _ => return Ok(Value::Bool(false)),
    };
    let n = vals.len();
    if n > 1 {
        for i in (1..n).rev() {
            let j = it.mt.range(0, i as i64) as usize;
            vals.swap(i, j);
        }
    }
    *r.borrow_mut() = Value::arr(PArray::from_values(vals));
    Ok(Value::Bool(true))
}
fn ptr_op(it: &mut Interp, a: &Args, op: u8) -> R<Value> {
    let r = match a.r(0) {
        Some(r) => r,
        None => {
            // by value (current/key)
            let v = a.get(0);
            return match v {
                Value::Array(arr) => Ok(match arr.next_valid(arr.iter_pos).and_then(|p| arr.entry_at(p)) {
                    Some((k, v)) => {
                        if op == b'k' {
                            k.to_value()
                        } else {
                            v.deref()
                        }
                    }
                    None => {
                        if op == b'k' {
                            Value::Null
                        } else {
                            Value::Bool(false)
                        }
                    }
                }),
                Value::Object(_) => Ok(Value::Bool(false)),
                other => {
                    let msg = format!("{}(): Argument #1 ($array) must be of type array, {} given", a.def.name, other.type_name());
                    Err(it.type_error(&msg))
                }
            };
        }
    };
    let mut b = r.borrow_mut();
    let arr = match &mut *b {
        Value::Array(arr) => arr,
        other => {
            let tn = other.type_name();
            drop(b);
            let msg = format!("{}(): Argument #1 ($array) must be of type array, {} given", a.def.name, tn);
            return Err(it.type_error(&msg));
        }
    };
    let res = |arr: &PArray, pos: Option<usize>, key: bool| -> Value {
        match pos.and_then(|p| arr.entry_at(p)) {
            Some((k, v)) => {
                if key {
                    k.to_value()
                } else {
                    v.deref()
                }
            }
            None => {
                if key {
                    Value::Null
                } else {
                    Value::Bool(false)
                }
            }
        }
    };
    match op {
        b'c' | b'k' => {
            let p = arr.next_valid(arr.iter_pos);
            Ok(res(arr, p, op == b'k'))
        }
        b'n' => {
            let m = Rc::make_mut(arr);
            let cur = m.next_valid(m.iter_pos);
            let np = match cur {
                Some(p) => p + 1,
                None => m.raw_len(),
            };
            m.iter_pos = np;
            let p = m.next_valid(np);
            Ok(res(m, p, false))
        }
        b'p' => {
            let m = Rc::make_mut(arr);
            let cur = m.next_valid(m.iter_pos);
            let p = match cur {
                Some(c) => m.prev_valid(c),
                None => None,
            };
            m.iter_pos = p.unwrap_or(m.raw_len());
            Ok(res(m, p, false))
        }
        b'r' => {
            let m = Rc::make_mut(arr);
            m.iter_pos = 0;
            let p = m.next_valid(0);
            Ok(res(m, p, false))
        }
        b'e' => {
            let m = Rc::make_mut(arr);
            let p = m.prev_valid(m.raw_len());
            m.iter_pos = p.unwrap_or(0);
            Ok(res(m, p, false))
        }
        _ => Ok(Value::Null),
    }
}
fn f_current(it: &mut Interp, a: &mut Args) -> R<Value> {
    ptr_op(it, a, b'c')
}
