    ptr_op(it, a, b'p')
}
fn f_reset(it: &mut Interp, a: &mut Args) -> R<Value> {
    ptr_op(it, a, b'r')
}
fn f_end(it: &mut Interp, a: &mut Args) -> R<Value> {
