}
fn f_array_is_list(it: &mut Interp, a: &mut Args) -> R<Value> {
    let arr = get_arr(it, a, 0)?;
    Ok(Value::Bool(arr.is_list()))
}
fn find_common(it: &mut Interp, a: &mut Args) -> R<Option<(Key, Value)>> {
    let arr = get_arr(it, a, 0)?;
    let cb = a.callable(it, 1)?;
    for (k, v) in arr.iter() {
        let v = v.deref();
        if it.call_value(&cb, vec![v.clone(), k.to_value()])?.to_bool() {
            return Ok(Some((k.clone(), v)));
        }
    }
    Ok(None)
}
fn f_array_find(it: &mut Interp, a: &mut Args) -> R<Value> {
    Ok(find_common(it, a)?.map(|(_, v)| v).unwrap_or(Value::Null))
}
fn f_array_find_key(it: &mut Interp, a: &mut Args) -> R<Value> {
    Ok(find_common(it, a)?.map(|(k, _)| k.to_value()).unwrap_or(Value::Null))
}
fn f_array_any(it: &mut Interp, a: &mut Args) -> R<Value> {
    Ok(Value::Bool(find_common(it, a)?.is_some()))
}
fn f_array_all(it: &mut Interp, a: &mut Args) -> R<Value> {
    let arr = get_arr(it, a, 0)?;
    let cb = a.callable(it, 1)?;
    for (k, v) in arr.iter() {
        if !it.call_value(&cb, vec![v.deref(), k.to_value()])?.to_bool() {
            return Ok(Value::Bool(false));
        }
    }
    Ok(Value::Bool(true))
}
fn f_array_change_key_case(it: &mut Interp, a: &mut Args) -> R<Value> {
    let arr = get_arr(it, a, 0)?;
    let upper = a.int_or(it, 1, 0)? == 1;
    let mut out = PArray::new();
    for (k, v) in arr.iter() {
        let nk = match k {
            Key::Str(s) => Key::Str(Rc::new(if upper { s.to_ascii_uppercase() } else { s.to_ascii_lowercase() })),
            k => k.clone(),
        };
        out.set(nk, v.deref());
    }
    Ok(Value::arr(out))
}
fn f_array_sum(it: &mut Interp, a: &mut Args) -> R<Value> {
    let arr = get_arr(it, a, 0)?;
    let mut acc = Value::Int(0);
    for v in arr.values() {
        let v = v.deref();
        let v = match &v {
            Value::Array(_) | Value::Object(_) => {
                it.warn(&format!("array_sum(): Addition is not supported on type {}", crate::interp::ops::type_for_op(&v)))?;
                continue;
            }
            Value::Str(s) if parse_numeric_prefix(s).is_none() => {
                it.warn(&format!("A non-numeric value encountered"))?;
                Value::Int(0)
            }
            Value::Str(s) => parse_numeric_prefix(s).unwrap().0.to_value(),
            _ => v,
        };
        acc = it.arith(crate::ast::BinOp::Add, &acc, &v)?;
    }
    Ok(acc)
}
fn f_array_product(it: &mut Interp, a: &mut Args) -> R<Value> {
    let arr = get_arr(it, a, 0)?;
    let mut acc = Value::Int(1);
    for v in arr.values() {
        let v = v.deref();
        let v = match &v {
            Value::Array(_) | Value::Object(_) => {
                it.warn(&format!("array_product(): Multiplication is not supported on type {}", crate::interp::ops::type_for_op(&v)))?;
                continue;
            }
            Value::Str(s) => parse_numeric_prefix(s).map(|n| n.0.to_value()).unwrap_or(Value::Int(0)),
            _ => v,
        };
        acc = it.arith(crate::ast::BinOp::Mul, &acc, &v)?;
    }
    Ok(acc)
}
fn f_iterator_to_array(it: &mut Interp, a: &mut Args) -> R<Value> {
    let v = a.get(0);
    let pk = a.bool_or(it, 1, true)?;
    match v {
        Value::Array(arr) => {
            if pk {
                return Ok(Value::Array(arr));
            }
            return Ok(Value::arr(PArray::from_values(arr.values().map(|v| v.deref()).collect())));
        }
        Value::Object(o) => {
            let mut out = PArray::new();
            let mut err = None;
            it.iterate_object(&o, &mut |it, k, v| {
                if pk {
                    match it.to_key(&k) {
                        Ok(key) => out.set(key, v),
                        Err(e) => {
                            err = Some(e);
                            return Ok(false);
                        }
                    }
                } else {
                    out.push(v);
                }
                Ok(true)
            })?;
            if let Some(e) = err {
                return Err(e);
            }
            Ok(Value::arr(out))
        }
        other => {
            let msg = format!("iterator_to_array(): Argument #1 ($iterator) must be of type Traversable|array, {} given", other.type_name());
            Err(it.type_error(&msg))
        }
    }
