use super::*;
use crate::array::{Key, PArray};
use std::cmp::Ordering;

fn arr_ref(a: &Args, i: usize) -> Option<PRef> {
    a.r(i)
}

/// operate mutably on by-ref array argument
fn with_ref_arr<T>(it: &mut Interp, a: &Args, i: usize, f: impl FnOnce(&mut PArray) -> T) -> R<T> {
    let r = match arr_ref(a, i) {
        Some(r) => r,
        None => return Err(it.error("argument must be passed by reference")),
    };
    let mut b = r.borrow_mut();
    match &mut *b {
        Value::Array(arr) => {
            let m = Rc::make_mut(arr);
            Ok(f(m))
        }
        other => {
            let tn = other.type_name();
            drop(b);
            let msg = format!("{}(): Argument #{} (${}) must be of type array, {} given", a.def.name, i + 1, a.def.param_name(i), tn);
            Err(it.type_error(&msg))
        }
    }
}

fn get_arr(it: &mut Interp, a: &Args, i: usize) -> R<Rc<PArray>> {
    a.arr(it, i)
}

fn f_count(it: &mut Interp, a: &mut Args) -> R<Value> {
    let v = a.get(0);
    let mode = a.int_or(it, 1, 0)?;
    match &v {
        Value::Array(arr) => {
            if mode == 1 {
                fn rc(a: &PArray) -> i64 {
                    let mut n = a.len() as i64;
                    for v in a.values() {
                        if let Value::Array(s) = v.deref() {
                            n += rc(&s);
                        }
                    }
                    n
                }
                return Ok(Value::Int(rc(arr)));
            }
            Ok(Value::Int(arr.len() as i64))
        }
        Value::Object(o) => {
            if o.class.instance_of_name("countable") {
                let o = o.clone();
                let r = it.call_method_name(&o, "count", vec![])?;
                return Ok(Value::Int(r.to_int()));
            }
            let msg = format!("count(): Argument #1 ($value) must be of type Countable|array, {} given", o.class.name);
            Err(it.type_error(&msg))
        }
        other => {
            let msg = format!("count(): Argument #1 ($value) must be of type Countable|array, {} given", other.type_name());
            Err(it.type_error(&msg))
        }
    }
}

fn f_array_keys(it: &mut Interp, a: &mut Args) -> R<Value> {
    let arr = get_arr(it, a, 0)?;
    let mut out = PArray::with_capacity(arr.len());
    if a.has(1) {
        let sv = a.get(1);
        let strict = a.bool_or(it, 2, false)?;
        for (k, v) in arr.iter() {
            let v = v.deref();
            let eq = if strict { crate::interp::ops::strict_equals(&v, &sv) } else { it.loose_eq(&v, &sv)? };
            if eq {
                out.push(k.to_value());
            }
        }
    } else {
        for k in arr.keys() {
            out.push(k.to_value());
        }
    }
    Ok(Value::arr(out))
}
fn f_array_values(it: &mut Interp, a: &mut Args) -> R<Value> {
    let arr = get_arr(it, a, 0)?;
    if arr.is_list() {
        return Ok(Value::Array(arr));
    }
