        for (k, v) in arr.iter() {
            out.set(k.clone(), v.deref());
        }
    }
    Ok(Value::arr(out))
}
fn replace_rec(dst: &mut PArray, src: &PArray) {
    for (k, v) in src.iter() {
        let v = v.deref();
        if let (Value::Array(sv), Some(Value::Array(dv))) = (&v, dst.get(k).map(|x| x.deref())) {
            let mut d = (*dv).clone();
            replace_rec(&mut d, sv);
            dst.set(k.clone(), Value::arr(d));
        } else {
            dst.set(k.clone(), v);
        }
    }
}
fn f_array_replace_recursive(it: &mut Interp, a: &mut Args) -> R<Value> {
    let mut out = (*get_arr(it, a, 0)?).clone();
