        let arr = get_arr(it, a, i)?;
        replace_rec(&mut out, &arr);
    }
    Ok(Value::arr(out))
}
fn f_array_combine(it: &mut Interp, a: &mut Args) -> R<Value> {
    let k = get_arr(it, a, 0)?;
    let v = get_arr(it, a, 1)?;
    if k.len() != v.len() {
        return Err(it.value_error("array_combine(): Argument #1 ($keys) and argument #2 ($values) must have the same number of elements"));
    }
    let mut out = PArray::new();
    for (kk, vv) in k.values().zip(v.values()) {
        let key = it.to_key(&kk.deref())?;
        out.set(key, vv.deref());
    }
    Ok(Value::arr(out))
}
fn f_array_flip(it: &mut Interp, a: &mut Args) -> R<Value> {
    let arr = get_arr(it, a, 0)?;
    let mut out = PArray::new();
    for (k, v) in arr.iter() {
        match v.deref() {
            Value::Int(i) => out.set(Key::Int(i), k.to_value()),
            Value::Str(s) => out.set(Key::from_pstr(&s), k.to_value()),
            _ => {
