            }
        }
    }
    Ok(Value::arr(out))
}
fn f_array_slice(it: &mut Interp, a: &mut Args) -> R<Value> {
    let arr = get_arr(it, a, 0)?;
    let off = a.int(it, 1)?;
    let len = a.opt_int(it, 2)?;
    let pk = a.bool_or(it, 3, false)?;
    let n = arr.len() as i64;
    let st = if off < 0 { (n + off).max(0) } else { off.min(n) };
    let en = match len {
        None => n,
        Some(l) if l < 0 => (n + l).max(st),
        Some(l) => (st + l).min(n),
    };
    let mut out = PArray::new();
    for (i, (k, v)) in arr.iter().enumerate() {
        let i = i as i64;
        if i < st {
            continue;
        }
        if i >= en {
            break;
        }
        match k {
            Key::Int(_) if !pk => {
                out.push(v.deref());
            }
            _ => out.set(k.clone(), v.deref()),
        }
    }
    Ok(Value::arr(out))
}
fn f_array_splice(it: &mut Interp, a: &mut Args) -> R<Value> {
    let off = a.int(it, 1)?;
    let len = a.opt_int(it, 2)?;
    let repl: Vec<Value> = if a.has(3) {
        match a.get(3) {
            Value::Array(r) => r.values().map(|v| v.deref()).collect(),
            Value::Null => vec![],
            other => vec![other],
        }
    } else {
        vec![]
    };
    let removed = with_ref_arr(it, a, 0, |arr| {
        let pairs = std::mem::take(arr).into_pairs();
        let n = pairs.len() as i64;
        let st = if off < 0 { (n + off).max(0) } else { off.min(n) } as usize;
        let en = match len {
            None => n as usize,
            Some(l) if l < 0 => ((n + l).max(st as i64)) as usize,
            Some(l) => ((st as i64 + l).min(n)) as usize,
        };
        let mut out = PArray::new();
        let mut removed = PArray::new();
        for (i, (k, v)) in pairs.into_iter().enumerate() {
            if i == st {
                for r in &repl {
                    out.push(r.clone());
                }
            }
            if i >= st && i < en {
                match k {
                    Key::Int(_) => {
                        removed.push(v);
                    }
                    _ => removed.set(k, v),
                }
                continue;
            }
            match k {
                Key::Int(_) => {
                    out.push(v);
                }
                _ => out.set(k, v),
            }
        }
        if st >= n as usize {
            for r in &repl {
                out.push(r.clone());
            }
        }
        *arr = out;
        removed
    })?;
    Ok(Value::arr(removed))
}
fn f_array_map(it: &mut Interp, a: &mut Args) -> R<Value> {
    let cb = a.get(0);
    let has_cb = !cb.is_null();
    if has_cb {
        a.callable(it, 0)?;
    }
    if a.len() == 2 {
        let arr = match a.get(1) {
            Value::Array(x) => x,
            other => {
                let msg = format!("array_map(): Argument #2 ($array) must be of type array, {} given", other.type_name());
                return Err(it.type_error(&msg));
            }
        };
        if !has_cb {
            return Ok(Value::Array(arr));
        }
        let mut out = PArray::with_capacity(arr.len());
        let strkeys = !arr.is_list();
        for (k, v) in arr.iter() {
            let r = it.call_value(&cb, vec![v.deref()])?;
            if strkeys {
                out.set(k.clone(), r);
            } else {
