}
fn f_array_filter(it: &mut Interp, a: &mut Args) -> R<Value> {
    let arr = get_arr(it, a, 0)?;
    let cb = if a.has(1) && !a.get(1).is_null() { Some(a.callable(it, 1)?) } else { None };
    let mode = a.int_or(it, 2, 0)?;
    let mut out = PArray::new();
    for (k, v) in arr.iter() {
        let v = v.deref();
        let keep = match &cb {
            None => v.to_bool(),
            Some(cb) => {
                let args = match mode {
                    2 => vec![k.to_value()],
                    1 => vec![v.clone(), k.to_value()],
                    _ => vec![v.clone()],
                };
                it.call_value(cb, args)?.to_bool()
