        } else {
            let mut args = vec![Value::Ref(elem_ref), k.to_value()];
            if let Some(e) = extra {
                args.push(e.clone());
            }
            it.call_value(cb, args)?;
        }
    }
    if let Value::Array(arr) = &mut *r.borrow_mut() {
        let m = Rc::make_mut(arr);
        for (_, v) in m.iter_mut() {
            if let Value::Ref(rr) = v {
                if Rc::strong_count(rr) == 1 {
                    let inner = rr.borrow().clone();
                    *v = inner;
                }
            }
        }
    }
    Ok(())
}
fn f_array_walk_recursive(it: &mut Interp, a: &mut Args) -> R<Value> {
    let cb = a.callable(it, 1)?;
    let extra = if a.has(2) { Some(a.get(2)) } else { None };
    if let Some(r) = a.r(0) {
        walk_rec(it, &r, &cb, &extra)?;
    }
    Ok(Value::Bool(true))
}
fn search(it: &mut Interp, a: &Args) -> R<Option<Key>> {
    let needle = a.get(0);
    let arr = get_arr(it, a, 1)?;
    let strict = a.bool_or(it, 2, false)?;
    for (k, v) in arr.iter() {
        let v = v.deref();
        let eq = if strict {
            crate::interp::ops::strict_equals(&v, &needle)
        } else {
            match (&v, &needle) {
                (Value::Int(x), Value::Int(y)) => x == y,
                (Value::Str(x), Value::Str(y)) if str_numeric(x).is_none() && str_numeric(y).is_none() => x == y,
                _ => it.loose_eq(&v, &needle)?,
            }
        };
        if eq {
            return Ok(Some(k.clone()));
        }
    }
    Ok(None)
}
fn f_in_array(it: &mut Interp, a: &mut Args) -> R<Value> {
    Ok(Value::Bool(search(it, a)?.is_some()))
}
fn f_array_search(it: &mut Interp, a: &mut Args) -> R<Value> {
    Ok(match search(it, a)? {
        Some(k) => k.to_value(),
        None => Value::Bool(false),
    })
}
fn f_array_key_exists(it: &mut Interp, a: &mut Args) -> R<Value> {
    let k = a.get(0);
    match a.get(1) {
        Value::Array(arr) => {
            let key = match &k {
                Value::Int(i) => Key::Int(*i),
                Value::Str(s) => Key::from_pstr(s),
                Value::Null => Key::Str(Rc::new(Vec::new())),
                Value::Bool(b) => Key::Int(*b as i64),
                Value::Float(f) => Key::Int(*f as i64),
                other => {
                    let msg = format!("Cannot access offset of type {} on array", crate::interp::ops::type_for_op(other));
                    return Err(it.type_error(&msg));
                }
            };
            Ok(Value::Bool(arr.contains_key(&key)))
        }
        other => {
            let msg = format!("array_key_exists(): Argument #2 ($array) must be of type array, {} given", other.type_name());
            Err(it.type_error(&msg))
        }
    }
}
fn f_array_key_first(it: &mut Interp, a: &mut Args) -> R<Value> {
