            let lb = if php { u & 1 } else { v & 1 };
            m ^ (mix >> 1) ^ ((lb as i32).wrapping_neg() as u32 & 0x9908_b0df)
        };
        for i in 0..(N - M) {
            s[i] = twist(s[i + M], s[i], s[i + 1]);
        }
        for i in (N - M)..(N - 1) {
            s[i] = twist(s[i + M - N], s[i], s[i + 1]);
        }
        s[N - 1] = twist(s[M - 1], s[N - 1], s[0]);
        self.left = N;
        self.next = 0;
    }
    pub fn ensure_seeded(&mut self) {
        if !self.seeded {
            let t = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|d| d.as_nanos() as u64).unwrap_or(0);
            let pid = std::process::id() as u64;
            self.seed((t ^ (pid << 16) ^ (t >> 32)) as u32);
        }
    }
    pub fn next_u32(&mut self) -> u32 {
