use super::*;

const N: usize = 624;
const M: usize = 397;

pub struct Mt {
    state: [u32; N],
    next: usize,
    left: usize,
    pub seeded: bool,
    pub php_mode: bool,
}

impl Mt {
    pub fn new() -> Mt {
        Mt { state: [0; N], next: 0, left: 0, seeded: false, php_mode: false }
    }
    pub fn seed(&mut self, s: u32) {
        self.state[0] = s;
        for i in 1..N {
            let p = self.state[i - 1];
            self.state[i] = 1812433253u32.wrapping_mul(p ^ (p >> 30)).wrapping_add(i as u32);
        }
        self.reload();
        self.seeded = true;
    }
    fn reload(&mut self) {
        let s = &mut self.state;
        let php = self.php_mode;
        let twist = |m: u32, u: u32, v: u32| -> u32 {
            let mix = (u & 0x8000_0000) | (v & 0x7fff_ffff);
            let lb = if php { u & 1 } else { v & 1 };
            m ^ (mix >> 1) ^ ((lb as i32).wrapping_neg() as u32 & 0x9908_b0df)
        };
        for i in 0..(N - M) {
            s[i] = twist(s[i + M], s[i], s[i + 1]);
        }
        for i in (N - M)..(N - 1) {
            s[i] = twist(s[i + M - N], s[i], s[i + 1]);
        }
        s[N - 1] = twist(s[M - 1], s[N - 1], s[0]);
        self.left = N;
        self.next = 0;
    }
    pub fn ensure_seeded(&mut self) {
        if !self.seeded {
            let t = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|d| d.as_nanos() as u64).unwrap_or(0);
            let pid = std::process::id() as u64;
            self.seed((t ^ (pid << 16) ^ (t >> 32)) as u32);
        }
    }
    pub fn next_u32(&mut self) -> u32 {
        self.ensure_seeded();
        if self.left == 0 {
            self.reload();
        }
        self.left -= 1;
        let mut s1 = self.state[self.next];
        self.next += 1;
        s1 ^= s1 >> 11;
        s1 ^= (s1 << 7) & 0x9d2c_5680;
        s1 ^= (s1 << 15) & 0xefc6_0000;
        s1 ^ (s1 >> 18)
    }
    pub fn range(&mut self, min: i64, max: i64) -> i64 {
        let umax = (max as u64).wrapping_sub(min as u64);
        if self.php_mode {
            // legacy scaling
            let n = (self.next_u32() >> 1) as f64;
            return min + ((max as f64 - min as f64 + 1.0) * (n / (2147483647.0 + 1.0))) as i64;
        }
        if umax > u32::MAX as u64 {
            let mut r = ((self.next_u32() as u64) << 32) | self.next_u32() as u64;
            if umax == u64::MAX {
                return (min as u64).wrapping_add(r) as i64;
            }
            let um = umax + 1;
            if um & (um - 1) != 0 {
                let limit = u64::MAX - (u64::MAX % um) - 1;
                while r > limit {
                    r = ((self.next_u32() as u64) << 32) | self.next_u32() as u64;
                }
            }
            return (min as u64).wrapping_add(r % um) as i64;
        }
        let umax = umax as u32;
        let mut r = self.next_u32();
        if umax == u32::MAX {
            return (min as u64).wrapping_add(r as u64) as i64;
        }
        let um = umax + 1;
        if um & (um - 1) != 0 {
            let limit = u32::MAX - (u32::MAX % um) - 1;
            while r > limit {
                r = self.next_u32();
            }
        }
        (min as u64).wrapping_add((r % um) as u64) as i64
    }
}

