fn canon_version(v: &[u8]) -> Vec<Vec<u8>> {
    // split into parts: numbers and alpha, separators . - + _
    let mut parts: Vec<Vec<u8>> = Vec::new();
    let mut cur = Vec::new();
    let mut last_kind = 0; // 1 digit 2 alpha
    for &c in v {
        let kind = if c.is_ascii_digit() { 1 } else if c.is_ascii_alphabetic() { 2 } else { 0 };
        if kind == 0 {
            if !cur.is_empty() {
                parts.push(std::mem::take(&mut cur));
            }
            last_kind = 0;
            continue;
        }
        if kind != last_kind && !cur.is_empty() {
            parts.push(std::mem::take(&mut cur));
        }
        cur.push(c);
        last_kind = kind;
    }
    if !cur.is_empty() {
        parts.push(cur);
    }
    parts
}
fn special_order(s: &[u8]) -> i32 {
    let l = s.to_ascii_lowercase();
    if l.starts_with(b"dev") {
        0
    } else if l.starts_with(b"alpha") || l == b"a" {
        1
    } else if l.starts_with(b"beta") || l == b"b" {
        2
    } else if l.starts_with(b"rc") || l == b"c" {
        3
    } else if l == b"#" {
        4
    } else if l.starts_with(b"pl") || l == b"p" {
        5
    } else {
        -6
    }
}
pub fn version_compare(a: &[u8], b: &[u8]) -> i32 {
    let pa = canon_version(a);
    let pb = canon_version(b);
    let n = pa.len().max(pb.len());
    for i in 0..n {
        let x = pa.get(i);
        let y = pb.get(i);
        let c = match (x, y) {
            (Some(x), Some(y)) => {
                let xd = x[0].is_ascii_digit();
                let yd = y[0].is_ascii_digit();
                if xd && yd {
                    let xi: i64 = String::from_utf8_lossy(x).parse().unwrap_or(0);
                    let yi: i64 = String::from_utf8_lossy(y).parse().unwrap_or(0);
                    xi.cmp(&yi) as i32
                } else if !xd && !yd {
                    special_order(x).cmp(&special_order(y)) as i32
                } else if xd {
                    // number vs special
                    let s = special_order(y);
                    if s >= 4 { -1 } else { 1 }
                } else {
                    let s = special_order(x);
                    if s >= 4 { 1 } else { -1 }
                }
            }
            (Some(x), None) => {
                if x[0].is_ascii_digit() {
                    1
                } else {
                    let s = special_order(x);
                    if s >= 4 { 1 } else { -1 }
                }
            }
            (None, Some(y)) => {
                if y[0].is_ascii_digit() {
                    -1
                } else {
                    let s = special_order(y);
                    if s >= 4 { -1 } else { 1 }
                }
            }
            (None, None) => 0,
        };
        if c != 0 {
            return c;
        }
    }
    0
}
fn f_version_compare(it: &mut Interp, a: &mut Args) -> R<Value> {
    let x = a.str(it, 0)?;
    let y = a.str(it, 1)?;
    let c = version_compare(&x, &y);
    if a.has(2) && !a.get(2).is_null() {
        let op = a.str(it, 2)?;
        let r = match &op[..] {
            b"<" | b"lt" => c < 0,
            b"<=" | b"le" => c <= 0,
            b">" | b"gt" => c > 0,
            b">=" | b"ge" => c >= 0,
            b"==" | b"eq" => c == 0,
            b"!=" | b"<>" | b"ne" => c != 0,
            _ => return Err(a.value_err(it, 2, "must be a valid comparison operator")),
        };
        return Ok(Value::Bool(r));
    }
    Ok(Value::Int(c as i64))
}
