        let mut arr = match a.get(1) {
            Value::Array(x) => (*x).clone(),
            _ => PArray::new(),
        };
        for l in &lines {
            let t: &[u8] = {
                let mut e = l.len();
                while e > 0 && l[e - 1].is_ascii_whitespace() {
                    e -= 1;
                }
                &l[..e]
            };
            arr.push(Value::bytes(t));
        }
        a.set_ref(1, Value::arr(arr));
    }
    if a.len() > 2 {
        a.set_ref(2, Value::Int(code as i64));
    }
    Ok(Value::bytes(lines.last().copied().unwrap_or(b"")))
}
fn f_system(it: &mut Interp, a: &mut Args) -> R<Value> {
    let c = a.str(it, 0)?;
    let (o, code) = run_shell(it, &c);
    it.echo(&o);
    if a.len() > 1 {
        a.set_ref(1, Value::Int(code as i64));
    }
    let last = o.split(|&c| c == b'\n').filter(|l| !l.is_empty()).last().unwrap_or(b"").to_vec();
    Ok(Value::vec(last))
}
