fn f_escapeshellarg(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let mut out = b"'".to_vec();
    for &c in s.iter() {
        if c == b'\'' {
            out.extend_from_slice(b"'\\''");
