pub fn base64_encode(s: &[u8]) -> Vec<u8> {
    const T: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = Vec::with_capacity((s.len() + 2) / 3 * 4);
    for c in s.chunks(3) {
        let b0 = c[0] as u32;
        let b1 = *c.get(1).unwrap_or(&0) as u32;
        let b2 = *c.get(2).unwrap_or(&0) as u32;
        let n = (b0 << 16) | (b1 << 8) | b2;
        out.push(T[(n >> 18) as usize & 63]);
        out.push(T[(n >> 12) as usize & 63]);
        out.push(if c.len() > 1 { T[(n >> 6) as usize & 63] } else { b'=' });
        out.push(if c.len() > 2 { T[n as usize & 63] } else { b'=' });
    }
    out
}
pub fn base64_decode(s: &[u8], strict: bool) -> Option<Vec<u8>> {
    let mut out = Vec::new();
    let mut buf = 0u32;
    let mut bits = 0;
    let mut pad = 0;
    for &c in s {
        let v = match c {
            b'A'..=b'Z' => c - b'A',
            b'a'..=b'z' => c - b'a' + 26,
            b'0'..=b'9' => c - b'0' + 52,
            b'+' | b'-' => 62,
            b'/' | b'_' => 63,
            b'=' => {
                pad += 1;
                continue;
            }
            _ => {
                if strict && !c.is_ascii_whitespace() {
                    return None;
                }
                continue;
            }
        };
        if pad > 0 && strict {
            return None;
        }
        buf = (buf << 6) | v as u32;
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            out.push((buf >> bits) as u8);
        }
    }
    if strict && bits >= 6 {
        return None;
    }
    Some(out)
}
fn f_base64_decode(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let strict = a.bool_or(it, 1, false)?;
    Ok(match base64_decode(&s, strict) {
        Some(v) => Value::vec(v),
        None => Value::Bool(false),
    })
}
fn f_bin2hex(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let mut out = String::with_capacity(s.len() * 2);
    for c in s.iter() {
        out.push_str(&format!("{:02x}", c));
    }
    Ok(Value::string(out))
}
fn f_hex2bin(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    if s.len() % 2 != 0 {
        it.warn("hex2bin(): Hexadecimal input string must have an even length")?;
        return Ok(Value::Bool(false));
    }
    let mut out = Vec::new();
    for c in s.chunks(2) {
        match u8::from_str_radix(&String::from_utf8_lossy(c), 16) {
            Ok(b) => out.push(b),
            Err(_) => {
                it.warn("hex2bin(): Input string must be hexadecimal string")?;
                return Ok(Value::Bool(false));
            }
        }
    }
    Ok(Value::vec(out))
}
pub fn urlencode(s: &[u8], raw: bool) -> Vec<u8> {
    let mut out = Vec::new();
    for &c in s {
        if c.is_ascii_alphanumeric() || c == b'-' || c == b'_' || c == b'.' || (raw && c == b'~') {
            out.push(c);
        } else if c == b' ' && !raw {
            out.push(b'+');
        } else {
            out.extend_from_slice(format!("%{:02X}", c).as_bytes());
        }
    }
    out
}
pub fn urldecode(s: &[u8], raw: bool) -> Vec<u8> {
    let mut out = Vec::new();
    let mut i = 0;
    while i < s.len() {
        let c = s[i];
        if c == b'+' && !raw {
            out.push(b' ');
        } else if c == b'%' && i + 2 < s.len() + 0 && i + 2 <= s.len() - 1 + 0 && s[i + 1].is_ascii_hexdigit() && s[i + 2].is_ascii_hexdigit() {
            out.push(u8::from_str_radix(&String::from_utf8_lossy(&s[i + 1..i + 3]), 16).unwrap());
            i += 3;
            continue;
        } else {
            out.push(c);
        }
        i += 1;
    }
    out
}
