fn build_query(it: &mut Interp, arr: &PArray, prefix: Option<&[u8]>, sep: &[u8], enc_type: i64, out: &mut Vec<Vec<u8>>, num_prefix: &[u8]) -> R<()> {
    for (k, v) in arr.iter() {
        let kb = match (k, prefix) {
            (Key::Int(i), None) => {
                let mut x = num_prefix.to_vec();
                x.extend_from_slice(i.to_string().as_bytes());
                x
            }
            (k, None) => k.as_bytes(),
            (k, Some(p)) => {
                let mut x = p.to_vec();
                x.extend_from_slice(b"%5B");
                x.extend_from_slice(&urlencode(&k.as_bytes(), enc_type == 2));
                x.extend_from_slice(b"%5D");
                x
            }
        };
        let key_enc = if prefix.is_none() { urlencode(&kb, enc_type == 2) } else { kb.clone() };
        match v.deref() {
            Value::Array(sub) => build_query(it, &sub, Some(&key_enc), sep, enc_type, out, num_prefix)?,
            Value::Object(o) => {
                let props = it.visible_props(&o, None);
                let sub = PArray::from_pairs(props.into_iter().map(|(k, v)| (Key::from_str_bytes(&k), v)).collect());
                build_query(it, &sub, Some(&key_enc), sep, enc_type, out, num_prefix)?;
            }
            Value::Null => {}
            Value::Bool(b) => {
                let mut x = key_enc;
                x.push(b'=');
                x.push(if b { b'1' } else { b'0' });
                out.push(x);
            }
            other => {
                let s = it.to_str(&other)?;
                let mut x = key_enc;
                x.push(b'=');
                x.extend_from_slice(&urlencode(&s, enc_type == 2));
                out.push(x);
            }
        }
    }
    let _ = sep;
    Ok(())
}
fn f_http_build_query(it: &mut Interp, a: &mut Args) -> R<Value> {
    let data = a.get(0);
    let arr = match &data {
        Value::Array(x) => (**x).clone(),
        Value::Object(o) => PArray::from_pairs(it.visible_props(o, None).into_iter().map(|(k, v)| (Key::from_str_bytes(&k), v)).collect()),
        _ => PArray::new(),
    };
    let np = a.str_or(it, 1, b"")?;
    let sep = match a.opt_str(it, 2)? {
        Some(s) => s.to_vec(),
        None => b"&".to_vec(),
    };
    let enc = a.int_or(it, 3, 1)?;
    let mut parts = Vec::new();
    build_query(it, &arr, None, &sep, enc, &mut parts, &np)?;
    Ok(Value::vec(parts.join(&sep[..])))
}
fn parse_str_into(arr: &mut PArray, s: &[u8]) {
    for pair in s.split(|&c| c == b'&') {
        if pair.is_empty() {
            continue;
        }
        let (k, v) = match pair.iter().position(|&c| c == b'=') {
            Some(p) => (&pair[..p], &pair[p + 1..]),
            None => (pair, &b""[..]),
        };
        let k = urldecode(k, false);
        let v = urldecode(v, false);
        // handle brackets
        let (base, rest) = match k.iter().position(|&c| c == b'[') {
            Some(p) if p > 0 => (k[..p].to_vec(), Some(k[p..].to_vec())),
            _ => (k.clone(), None),
        };
        let base: Vec<u8> = base.iter().map(|&c| if c == b' ' || c == b'.' { b'_' } else { c }).collect();
        match rest {
            None => arr.set(Key::from_str_bytes(&base), Value::vec(v)),
            Some(r) => {
                let mut keys: Vec<Option<Vec<u8>>> = Vec::new();
                let mut i = 0;
                while i < r.len() && r[i] == b'[' {
                    match r[i..].iter().position(|&c| c == b']') {
                        Some(e) => {
                            let kk = &r[i + 1..i + e];
                            keys.push(if kk.is_empty() { None } else { Some(kk.to_vec()) });
                            i += e + 1;
                        }
                        None => break,
                    }
                }
                fn insert(arr: &mut PArray, keys: &[Option<Vec<u8>>], v: Value) {
                    match keys.first() {
                        None => {}
                        Some(k) => {
                            if keys.len() == 1 {
                                match k {
                                    None => {
                                        arr.push(v);
                                    }
                                    Some(k) => arr.set(Key::from_str_bytes(k), v),
                                }
                                return;
                            }
                            let slot = match k {
                                None => {
                                    arr.push(Value::empty_array());
                                    let last = arr.last().map(|(k, _)| k.clone()).unwrap();
                                    arr.get_mut(&last).unwrap()
                                }
                                Some(k) => arr.entry_mut(Key::from_str_bytes(k)),
                            };
                            if !matches!(slot, Value::Array(_)) {
                                *slot = Value::empty_array();
                            }
                            if let Value::Array(sub) = slot {
                                insert(Rc::make_mut(sub), &keys[1..], v);
                            }
                        }
                    }
                }
                let slot = arr.entry_mut(Key::from_str_bytes(&base));
                if !matches!(slot, Value::Array(_)) {
                    *slot = Value::empty_array();
                }
                if let Value::Array(sub) = slot {
                    insert(Rc::make_mut(sub), &keys, Value::vec(v));
                }
            }
        }
    }
}
fn f_parse_str(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let mut arr = PArray::new();
    parse_str_into(&mut arr, &s);
    a.set_ref(1, Value::arr(arr));
    Ok(Value::Null)
}
fn f_parse_url(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let comp = a.int_or(it, 1, -1)?;
    let st = String::from_utf8_lossy(&s).to_string();
    let mut parts: Vec<(&str, Value)> = Vec::new();
    let mut rest = st.as_str();
    // scheme
    if let Some(p) = rest.find("://") {
        let sc = &rest[..p];
        if !sc.is_empty() && sc.chars().all(|c| c.is_ascii_alphanumeric() || c == '+' || c == '-' || c == '.') {
            parts.push(("scheme", Value::str(sc)));
            rest = &rest[p + 3..];
            // authority
            let end = rest.find(|c| c == '/' || c == '?' || c == '#').unwrap_or(rest.len());
            let auth = &rest[..end];
            rest = &rest[end..];
            let (userinfo, hostport) = match auth.rfind('@') {
                Some(p) => (Some(&auth[..p]), &auth[p + 1..]),
                None => (None, auth),
            };
            let (host, port) = if hostport.starts_with('[') {
                match hostport.find(']') {
                    Some(e) => (&hostport[..e + 1], hostport[e + 1..].strip_prefix(':')),
                    None => (hostport, None),
                }
            } else {
                match hostport.rfind(':') {
                    Some(p) => (&hostport[..p], Some(&hostport[p + 1..])),
                    None => (hostport, None),
                }
            };
            parts.push(("host", Value::str(host)));
            if let Some(pt) = port {
                if !pt.is_empty() {
                    match pt.parse::<i64>() {
                        Ok(n) if n <= 65535 => parts.push(("port", Value::Int(n))),
                        _ => return Ok(Value::Bool(false)),
                    }
                }
            }
            if let Some(ui) = userinfo {
                match ui.find(':') {
                    Some(p) => {
                        parts.push(("user", Value::str(&ui[..p])));
                        parts.push(("pass", Value::str(&ui[p + 1..])));
                    }
                    None => parts.push(("user", Value::str(ui))),
                }
            }
        }
    } else if rest.starts_with("//") {
        let r2 = &rest[2..];
        let end = r2.find(|c| c == '/' || c == '?' || c == '#').unwrap_or(r2.len());
        let hostport = &r2[..end];
        match hostport.rfind(':') {
            Some(p) => {
                parts.push(("host", Value::str(&hostport[..p])));
                if let Ok(n) = hostport[p + 1..].parse::<i64>() {
                    parts.push(("port", Value::Int(n)));
                }
            }
            None => parts.push(("host", Value::str(hostport))),
        }
        rest = &r2[end..];
    } else if let Some(p) = rest.find(':') {
        let sc = &rest[..p];
        let after = &rest[p + 1..];
        if !sc.is_empty() && sc.chars().all(|c| c.is_ascii_alphabetic()) && !after.chars().next().map(|c| c.is_ascii_digit()).unwrap_or(false) {
            parts.push(("scheme", Value::str(sc)));
            rest = after;
        }
    }
    let (before_frag, frag) = match rest.find('#') {
        Some(p) => (&rest[..p], Some(&rest[p + 1..])),
        None => (rest, None),
    };
    let (path, query) = match before_frag.find('?') {
        Some(p) => (&before_frag[..p], Some(&before_frag[p + 1..])),
        None => (before_frag, None),
    };
    if !path.is_empty() {
        parts.push(("path", Value::str(path)));
    }
    if let Some(q) = query {
        parts.push(("query", Value::str(q)));
    }
    if let Some(f) = frag {
        parts.push(("fragment", Value::str(f)));
    }
    let order = ["scheme", "host", "port", "user", "pass", "path", "query", "fragment"];
    if comp >= 0 {
        let name = match comp {
            0 => "scheme",
            1 => "host",
            2 => "port",
            3 => "user",
            4 => "pass",
            5 => "path",
            6 => "query",
            7 => "fragment",
            _ => return Err(a.value_err(it, 1, "must be a valid URL component identifier, ".to_string().as_str())),
        };
        return Ok(parts.iter().find(|(n, _)| *n == name).map(|(_, v)| v.clone()).unwrap_or(Value::Null));
    }
    let mut out = PArray::new();
    for o in order {
        if let Some((_, v)) = parts.iter().find(|(n, _)| *n == o) {
            out.set(Key::Str(pstr(o)), v.clone());
        }
    }
    Ok(Value::arr(out))
}
