fn f_gettype(_it: &mut Interp, a: &mut Args) -> R<Value> {
    let v = a.get(0);
    if let Value::Object(o) = &v {
        if super::file::is_resource_obj(o) {
            return Ok(Value::str(if super::file::is_closed_resource(o) { "resource (closed)" } else { "resource" }));
        }
    }
    Ok(Value::str(v.gettype()))
}
fn f_get_debug_type(_it: &mut Interp, a: &mut Args) -> R<Value> {
    let v = a.get(0);
    Ok(Value::str(&match &v {
        Value::Null | Value::Undef => "null".to_string(),
        Value::Object(o) => {
            if super::file::is_resource_obj(o) {
                "resource (stream)".to_string()
            } else if o.class.name.starts_with("class@anonymous") {
                "class@anonymous".to_string()
            } else {
                o.class.name.to_string()
            }
        }
        other => other.type_name().to_string(),
    }))
}
fn f_intval(it: &mut Interp, a: &mut Args) -> R<Value> {
    let v = a.get(0);
    let base = a.int_or(it, 1, 10)?;
    if base != 10 {
        if let Value::Str(s) = &v {
            let t: Vec<u8> = s.iter().copied().skip_while(|c| c.is_ascii_whitespace()).collect();
            let (neg, t) = match t.first() {
                Some(b'-') => (true, t[1..].to_vec()),
                Some(b'+') => (false, t[1..].to_vec()),
                _ => (false, t),
            };
            let (b, t) = if base == 0 {
                if t.len() >= 2 && t[0] == b'0' && (t[1] == b'x' || t[1] == b'X') {
                    (16, t[2..].to_vec())
                } else if t.len() >= 2 && t[0] == b'0' && (t[1] == b'b' || t[1] == b'B') {
                    (2, t[2..].to_vec())
                } else if t.len() >= 1 && t[0] == b'0' {
                    (8, t[1..].to_vec())
                } else {
                    (10, t)
                }
            } else if base == 16 && t.len() >= 2 && t[0] == b'0' && (t[1] == b'x' || t[1] == b'X') {
                (16, t[2..].to_vec())
            } else if base == 2 && t.len() >= 2 && t[0] == b'0' && (t[1] == b'b' || t[1] == b'B') {
                (2, t[2..].to_vec())
            } else if base == 8 && t.len() >= 2 && t[0] == b'0' && (t[1] == b'o' || t[1] == b'O') {
                (8, t[2..].to_vec())
            } else {
                (base as u32, t)
            };
            let mut r: i64 = 0;
            let mut sat = false;
            for &c in &t {
                match (c as char).to_digit(b) {
                    Some(d) => {
                        match r.checked_mul(b as i64).and_then(|x| x.checked_add(d as i64)) {
                            Some(x) => r = x,
                            None => {
                                sat = true;
                                break;
                            }
                        }
                    }
                    None => break,
                }
            }
            if sat {
                return Ok(Value::Int(if neg { i64::MIN } else { i64::MAX }));
            }
            return Ok(Value::Int(if neg { -r } else { r }));
        }
    }
    Ok(Value::Int(it.to_int_cast(&v)?))
}
