fn f_get_class_vars(it: &mut Interp, a: &mut Args) -> R<Value> {
    let n = a.str(it, 0)?;
    let cls = match it.find_class_autoload(&n) {
        Some(c) => c,
        None => return Ok(Value::Bool(false)),
    };
    let defaults = it.class_defaults(&cls)?;
    let scope = it.current_scope();
    let mut out = PArray::new();
    for info in cls.slots.iter() {
        let visible = match info.vis {
            Visibility::Public => true,
            Visibility::Protected => scope.as_ref().map(|s| s.is_subclass_of(&cls) || cls.is_subclass_of(s)).unwrap_or(false),
            Visibility::Private => scope.as_ref().map(|s| s.name.eq_ignore_ascii_case(&info.decl_class)).unwrap_or(false),
        };
        if !visible {
            continue;
        }
        let v = defaults[info.slot].clone();
        if v.is_undef() {
            continue;
        }
        out.set(Key::Str(Rc::new(info.name.as_bytes().to_vec())), v);
    }
    let names: Vec<Name> = cls.static_props.keys().cloned().collect();
    for n in names {
        if let Some(sp) = it.find_static_prop(&cls, n.as_bytes()) {
            if sp.info.vis == Visibility::Public {
                out.set(Key::Str(Rc::new(n.as_bytes().to_vec())), sp.val.borrow().clone());
            }
        }
    }
    Ok(Value::arr(out))
}
