    if ![E_USER_ERROR, E_USER_WARNING, E_USER_NOTICE, E_USER_DEPRECATED].contains(&lvl) {
        return Err(a.value_err(it, 1, "must be one of E_USER_ERROR, E_USER_WARNING, E_USER_NOTICE, or E_USER_DEPRECATED"));
    }
    let m = String::from_utf8_lossy(&msg).to_string();
    if lvl == E_USER_ERROR {
        it.deprecated("Passing E_USER_ERROR to trigger_error() is deprecated since 8.4, throw an exception or call exit with a string message instead")?;
        // handler?
        if let Some((h, mask)) = it.error_handlers.last().cloned() {
            if !h.is_null() && mask & lvl != 0 {
                it.raise(lvl, &m)?;
                return Ok(Value::Bool(true));
            }
        }
        let s = format!("\nFatal error: {} in {} on line {}\n", m, it.cur_file, it.cur_line);
        it.echo(s.as_bytes());
        return Err(Flow::Exit(255));
    }
    it.raise(lvl, &m)?;
    Ok(Value::Bool(true))
}
