    let limit = a.int_or(it, 1, 0)?;
    let t = it.build_trace(1);
    let mut out = PArray::new();
    for (i, (_, fr)) in t.iter().enumerate() {
        if limit > 0 && i as i64 >= limit {
            break;
        }
        let mut fr = match fr {
            Value::Array(x) => (**x).clone(),
            _ => continue,
        };
        if opts & 2 != 0 {
            fr.remove(&Key::Str(pstr("args")));
        }
        out.push(Value::arr(fr));
    }
    Ok(Value::arr(out))
}
