    let (o, code) = run_shell(it, &c);
    let mut lines: Vec<&[u8]> = o.split(|&c| c == b'\n').collect();
    if lines.last().map(|l| l.is_empty()).unwrap_or(false) {
        lines.pop();
    }
    if a.len() > 1 {
        let mut arr = match a.get(1) {
            Value::Array(x) => (*x).clone(),
            _ => PArray::new(),
        };
        for l in &lines {
            let t: &[u8] = {
                let mut e = l.len();
                while e > 0 && l[e - 1].is_ascii_whitespace() {
                    e -= 1;
                }
                &l[..e]
            };
            arr.push(Value::bytes(t));
        }
        a.set_ref(1, Value::arr(arr));
    }
    if a.len() > 2 {
        a.set_ref(2, Value::Int(code as i64));
    }
    Ok(Value::bytes(lines.last().copied().unwrap_or(b"")))
}
