    Ok(Value::Int(super::file::resource_id(&o)))
}
fn f_extension_loaded(it: &mut Interp, a: &mut Args) -> R<Value> {
    let e = a.str(it, 0)?;
    let l = e.to_ascii_lowercase();
    Ok(Value::Bool(matches!(&l[..], b"core" | b"date" | b"hash" | b"json" | b"lexbor" | b"pcre" | b"random" | b"reflection" | b"spl" | b"standard" | b"uri")))
}
fn f_get_loaded_extensions(_it: &mut Interp, _a: &mut Args) -> R<Value> {
    Ok(Value::arr(PArray::from_values(["Core", "date", "lexbor", "pcre", "hash", "json", "random", "Reflection", "SPL", "standard", "uri"].iter().map(|s| Value::str(s)).collect())))
}
fn f_hrtime(it: &mut Interp, a: &mut Args) -> R<Value> {
    let d = it.start_time.elapsed();
    let ns = d.as_nanos() as i64 + 1_000_000_000;
    if a.bool_or(it, 0, false)? {
        return Ok(Value::Int(ns));
    }
    Ok(Value::arr(PArray::from_values(vec![Value::Int(ns / 1_000_000_000), Value::Int(ns % 1_000_000_000)])))
}
fn f_get_included_files(it: &mut Interp, _a: &mut Args) -> R<Value> {
    let mut v: Vec<String> = vec![it.main_file.to_string()];
    for f in it.included.iter() {
        if *f != *it.main_file {
            v.push(f.clone());
        }
    }
    Ok(Value::arr(PArray::from_values(v.iter().map(|s| Value::str(s)).collect())))
}
fn f_get_defined_functions(it: &mut Interp, _a: &mut Args) -> R<Value> {
    let mut internal = PArray::new();
    let mut user = PArray::new();
    let mut names: Vec<(&Vec<u8>, &Callable)> = it.functions.iter().collect();
    names.sort_by(|a, b| a.0.cmp(b.0));
    for (k, c) in names {
        match c {
            Callable::Builtin(_) => {
                if !k.starts_with(b"__") {
                    internal.push(Value::bytes(k));
                }
            }
            Callable::User(_) => {
                user.push(Value::bytes(k));
            }
        }
    }
    let mut out = PArray::new();
    out.set(Key::Str(pstr("internal")), Value::arr(internal));
    out.set(Key::Str(pstr("user")), Value::arr(user));
    Ok(Value::arr(out))
}

pub fn metaphone(word: &[u8]) -> Vec<u8> {
    // simplified PHP metaphone
    let w: Vec<u8> = word.iter().filter(|c| c.is_ascii_alphabetic()).map(|c| c.to_ascii_uppercase()).collect();
    let mut out = Vec::new();
    if w.is_empty() {
        return out;
    }
    let is_vowel = |c: u8| matches!(c, b'A' | b'E' | b'I' | b'O' | b'U');
    let at = |i: isize| -> u8 {
        if i < 0 || i as usize >= w.len() {
            0
        } else {
            w[i as usize]
        }
    };
    let mut i: isize = 0;
    // initial exceptions
    match (at(0), at(1)) {
        (b'A', b'E') => {
            out.push(b'E');
            i = 2;
        }
        (b'G', b'N') | (b'K', b'N') | (b'P', b'N') | (b'W', b'R') => {
            out.push(at(1));
            i = 2;
        }
        (b'X', _) => {
            out.push(b'S');
            i = 1;
        }
        (b'W', b'H') => {
            out.push(b'W');
            i = 2;
        }
        _ => {}
    }
    while (i as usize) < w.len() {
        let c = at(i);
        if c == at(i - 1) && c != b'C' {
            i += 1;
            continue;
        }
        match c {
            b'A' | b'E' | b'I' | b'O' | b'U' => {
                if i == 0 {
                    out.push(c);
                }
            }
            b'B' => {
                if !(at(i - 1) == b'M' && i as usize == w.len() - 1) {
                    out.push(b'B');
                }
            }
            b'C' => {
                if at(i + 1) == b'I' && at(i + 2) == b'A' {
                    out.push(b'X');
                } else if at(i + 1) == b'H' {
                    if at(i - 1) == b'S' {
                        out.push(b'K');
                    } else {
                        out.push(b'X');
                    }
                    i += 1;
                } else if matches!(at(i + 1), b'I' | b'E' | b'Y') {
                    if at(i - 1) != b'S' {
                        out.push(b'S');
                    }
                } else {
                    out.push(b'K');
                }
            }
            b'D' => {
                if at(i + 1) == b'G' && matches!(at(i + 2), b'E' | b'Y' | b'I') {
                    out.push(b'J');
                    i += 1;
                } else {
                    out.push(b'T');
                }
            }
            b'G' => {
                if at(i + 1) == b'H' {
                    if !(i as usize + 2 < w.len() && !is_vowel(at(i + 2))) {
                        out.push(b'F');
                        i += 1;
                    }
                } else if at(i + 1) == b'N' {
                    if !(i as usize + 2 == w.len() || (at(i + 2) == b'E' && at(i + 3) == b'D' && i as usize + 4 == w.len())) {
                        out.push(b'K');
                    }
                } else if matches!(at(i + 1), b'I' | b'E' | b'Y') && at(i - 1) != b'G' {
                    out.push(b'J');
                } else {
                    out.push(b'K');
                }
            }
            b'H' => {
                if is_vowel(at(i + 1)) && !matches!(at(i - 1), b'C' | b'G' | b'P' | b'S' | b'T') {
                    out.push(b'H');
                }
            }
            b'K' => {
                if at(i - 1) != b'C' {
                    out.push(b'K');
                }
            }
            b'P' => {
                if at(i + 1) == b'H' {
                    out.push(b'F');
                    i += 1;
                } else {
                    out.push(b'P');
                }
            }
            b'Q' => out.push(b'K'),
            b'S' => {
                if at(i + 1) == b'H' {
                    out.push(b'X');
                    i += 1;
                } else if at(i + 1) == b'I' && matches!(at(i + 2), b'O' | b'A') {
                    out.push(b'X');
                } else {
                    out.push(b'S');
                }
            }
            b'T' => {
                if at(i + 1) == b'I' && matches!(at(i + 2), b'O' | b'A') {
                    out.push(b'X');
                } else if at(i + 1) == b'H' {
                    out.push(b'0');
                    i += 1;
                } else if !(at(i + 1) == b'C' && at(i + 2) == b'H') {
                    out.push(b'T');
                }
            }
            b'V' => out.push(b'F'),
            b'W' | b'Y' => {
                if is_vowel(at(i + 1)) {
                    out.push(c);
                }
            }
            b'X' => {
                out.push(b'K');
                out.push(b'S');
            }
            b'Z' => out.push(b'S'),
            b'F' | b'J' | b'L' | b'M' | b'N' | b'R' => out.push(c),
            _ => {}
        }
        i += 1;
    }
    out
}

