pub fn utf8_decode_at(s: &[u8], i: usize) -> (u32, usize) {
    let c = s[i];
    if c < 0x80 {
        return (c as u32, 1);
    }
    let (len, init) = if c & 0xE0 == 0xC0 {
        (2, (c & 0x1F) as u32)
    } else if c & 0xF0 == 0xE0 {
        (3, (c & 0x0F) as u32)
    } else if c & 0xF8 == 0xF0 {
        (4, (c & 0x07) as u32)
    } else {
        return (0xFFFD, 1);
    };
    if i + len > s.len() {
        return (0xFFFD, 1);
    }
    let mut cp = init;
    for k in 1..len {
        let b = s[i + k];
        if b & 0xC0 != 0x80 {
            return (0xFFFD, 1);
        }
        cp = (cp << 6) | (b & 0x3F) as u32;
    }
    (cp, len)
}

/// returns None if invalid utf-8 at position
fn utf8_valid_at(s: &[u8], i: usize) -> Option<(u32, usize)> {
    let c = s[i];
    if c < 0x80 {
        return Some((c as u32, 1));
    }
    let (len, init, min) = if c & 0xE0 == 0xC0 {
        (2, (c & 0x1F) as u32, 0x80)
    } else if c & 0xF0 == 0xE0 {
        (3, (c & 0x0F) as u32, 0x800)
    } else if c & 0xF8 == 0xF0 {
        (4, (c & 0x07) as u32, 0x10000)
    } else {
        return None;
    };
    if i + len > s.len() {
        return None;
    }
    let mut cp = init;
    for k in 1..len {
        let b = s[i + k];
        if b & 0xC0 != 0x80 {
            return None;
        }
        cp = (cp << 6) | (b & 0x3F) as u32;
    }
    if cp < min || cp > 0x10FFFF || (0xD800..=0xDFFF).contains(&cp) {
        return None;
    }
    Some((cp, len))
}

