pub fn utf8_decode_at(s: &[u8], i: usize) -> (u32, usize) {
    let c = s[i];
    if c < 0x80 {
        return (c as u32, 1);
    }
    let (len, init) = if c & 0xE0 == 0xC0 {
        (2, (c & 0x1F) as u32)
    } else if c & 0xF0 == 0xE0 {
        (3, (c & 0x0F) as u32)
    } else if c & 0xF8 == 0xF0 {
        (4, (c & 0x07) as u32)
    } else {
        return (0xFFFD, 1);
    };
    if i + len > s.len() {
        return (0xFFFD, 1);
    }
    let mut cp = init;
    for k in 1..len {
        let b = s[i + k];
        if b & 0xC0 != 0x80 {
            return (0xFFFD, 1);
        }
        cp = (cp << 6) | (b & 0x3F) as u32;
    }
    (cp, len)
}

/// returns None if invalid utf-8 at position
fn utf8_valid_at(s: &[u8], i: usize) -> Option<(u32, usize)> {
    let c = s[i];
    if c < 0x80 {
        return Some((c as u32, 1));
    }
    let (len, init, min) = if c & 0xE0 == 0xC0 {
        (2, (c & 0x1F) as u32, 0x80)
    } else if c & 0xF0 == 0xE0 {
        (3, (c & 0x0F) as u32, 0x800)
    } else if c & 0xF8 == 0xF0 {
        (4, (c & 0x07) as u32, 0x10000)
    } else {
        return None;
    };
    if i + len > s.len() {
        return None;
    }
    let mut cp = init;
    for k in 1..len {
        let b = s[i + k];
        if b & 0xC0 != 0x80 {
            return None;
        }
        cp = (cp << 6) | (b & 0x3F) as u32;
    }
    if cp < min || cp > 0x10FFFF || (0xD800..=0xDFFF).contains(&cp) {
        return None;
    }
    Some((cp, len))
}

pub struct JsonEnc {
    pub out: Vec<u8>,
    pub flags: i64,
    pub error: i64,
    depth: usize,
    max_depth: usize,
    stack: Vec<usize>,
}

impl JsonEnc {
    pub fn new(flags: i64, depth: usize) -> JsonEnc {
        JsonEnc { out: Vec::new(), flags, error: 0, depth: 0, max_depth: depth, stack: Vec::new() }
    }
    fn pretty(&self) -> bool {
        self.flags & JSON_PRETTY_PRINT != 0
    }
    fn nl_indent(&mut self) {
        if self.pretty() {
            self.out.push(b'\n');
            for _ in 0..self.depth {
                self.out.extend_from_slice(b"    ");
            }
        }
    }
    pub fn enc_str(&mut self, s: &[u8]) -> bool {
        if self.flags & JSON_NUMERIC_CHECK != 0 {
            if let Some(n) = str_numeric(s) {
                match n {
                    Num::Int(i) => self.out.extend_from_slice(i.to_string().as_bytes()),
                    Num::Float(f) => self.enc_float(f),
                }
                return true;
            }
        }
        let mut buf = Vec::with_capacity(s.len() + 2);
        buf.push(b'"');
        let mut i = 0;
        while i < s.len() {
            let c = s[i];
            if c >= 0x80 {
                match utf8_valid_at(s, i) {
                    Some((cp, len)) => {
                        if self.flags & JSON_UNESCAPED_UNICODE != 0 && !((cp == 0x2028 || cp == 0x2029) && self.flags & JSON_UNESCAPED_LINE_TERMINATORS == 0) {
                            buf.extend_from_slice(&s[i..i + len]);
                        } else if cp >= 0x10000 {
                            let v = cp - 0x10000;
                            let hi = 0xD800 + (v >> 10);
                            let lo = 0xDC00 + (v & 0x3FF);
                            buf.extend_from_slice(format!("\\u{:04x}\\u{:04x}", hi, lo).as_bytes());
                        } else {
                            buf.extend_from_slice(format!("\\u{:04x}", cp).as_bytes());
                        }
                        i += len;
                        continue;
                    }
                    None => {
                        if self.flags & JSON_INVALID_UTF8_IGNORE != 0 {
                            i += 1;
                            continue;
                        }
                        if self.flags & JSON_INVALID_UTF8_SUBSTITUTE != 0 {
                            if self.flags & JSON_UNESCAPED_UNICODE != 0 {
                                buf.extend_from_slice("\u{FFFD}".as_bytes());
                            } else {
                                buf.extend_from_slice(b"\\ufffd");
                            }
                            i += 1;
                            continue;
                        }
                        self.error = 5;
                        if self.flags & JSON_PARTIAL_OUTPUT_ON_ERROR != 0 {
                            self.out.extend_from_slice(b"null");
                        }
                        return false;
                    }
                }
            }
            match c {
                b'"' => {
                    if self.flags & JSON_HEX_QUOT != 0 {
                        buf.extend_from_slice(b"\\u0022")
                    } else {
                        buf.extend_from_slice(b"\\\"")
                    }
                }
                b'\\' => buf.extend_from_slice(b"\\\\"),
                b'/' => {
                    if self.flags & JSON_UNESCAPED_SLASHES != 0 {
                        buf.push(b'/')
                    } else {
                        buf.extend_from_slice(b"\\/")
                    }
                }
                8 => buf.extend_from_slice(b"\\b"),
                12 => buf.extend_from_slice(b"\\f"),
                b'\n' => buf.extend_from_slice(b"\\n"),
                b'\r' => buf.extend_from_slice(b"\\r"),
                b'\t' => buf.extend_from_slice(b"\\t"),
                b'<' if self.flags & JSON_HEX_TAG != 0 => buf.extend_from_slice(b"\\u003C"),
                b'>' if self.flags & JSON_HEX_TAG != 0 => buf.extend_from_slice(b"\\u003E"),
                b'&' if self.flags & JSON_HEX_AMP != 0 => buf.extend_from_slice(b"\\u0026"),
                b'\'' if self.flags & JSON_HEX_APOS != 0 => buf.extend_from_slice(b"\\u0027"),
                c if c < 0x20 => buf.extend_from_slice(format!("\\u{:04x}", c).as_bytes()),
                c => buf.push(c),
            }
            i += 1;
        }
        buf.push(b'"');
        self.out.extend_from_slice(&buf);
        true
    }
    fn enc_float(&mut self, f: f64) {
        if !f.is_finite() {
            self.error = 7;
            self.out.push(b'0');
            return;
        }
        let s = fmt_float_repr_e(f, b'e');
        self.out.extend_from_slice(s.as_bytes());
        if self.flags & JSON_PRESERVE_ZERO_FRACTION != 0 && !s.contains('.') && !s.contains('e') {
            self.out.extend_from_slice(b".0");
        }
    }
    pub fn encode(&mut self, it: &mut Interp, v: &Value) -> R<()> {
        match v {
            Value::Null | Value::Undef => self.out.extend_from_slice(b"null"),
            Value::Bool(b) => self.out.extend_from_slice(if *b { b"true" } else { b"false" }),
            Value::Int(i) => self.out.extend_from_slice(i.to_string().as_bytes()),
            Value::Float(f) => self.enc_float(*f),
            Value::Str(s) => {
                self.enc_str(s);
            }
            Value::Ref(r) => {
                let v = r.borrow().clone();
                self.encode(it, &v)?;
            }
            Value::Array(a) => {
                let id = Rc::as_ptr(a) as usize;
                if self.stack.contains(&id) {
                    self.error = 6;
                    self.out.extend_from_slice(b"null");
                    return Ok(());
                }
                let as_list = self.flags & JSON_FORCE_OBJECT == 0 && a.is_list();
                let pairs: Vec<(Key, Value)> = a.iter().map(|(k, v)| (k.clone(), v.clone())).collect();
                self.stack.push(id);
                self.enc_container(it, pairs, as_list)?;
                self.stack.pop();
            }
            Value::Object(o) => {
                if super::file::is_resource_obj(o) {
                    self.error = 8;
                    if self.flags & JSON_PARTIAL_OUTPUT_ON_ERROR != 0 {
                        self.out.extend_from_slice(b"null");
                    }
                    return Ok(());
                }
                if o.class.kind == ClassKind::Enum {
                    if o.class.enum_backing.is_none() {
                        self.error = 11;
                        self.out.push(b'0');
                        return Ok(());
                    }
                    let bv = it.get_prop_raw(o, "value");
                    return self.encode(it, &bv);
                }
                if self.stack.contains(&(o.id as usize | (1 << 60))) {
                    self.error = 6;
                    self.out.extend_from_slice(b"null");
                    return Ok(());
                }
                if o.class.instance_of_name("jsonserializable") {
                    let o2 = o.clone();
                    self.stack.push(o.id as usize | (1 << 60));
                    let r = it.call_method_name(&o2, "jsonSerialize", vec![])?;
                    let r = self.encode(it, &r);
                    self.stack.pop();
                    return r;
                }
                let props = it.visible_props(o, None);
                let pairs: Vec<(Key, Value)> = props.into_iter().map(|(k, v)| (Key::Str(Rc::new(k)), v)).collect();
                self.stack.push(o.id as usize | (1 << 60));
                self.enc_container(it, pairs, false)?;
                self.stack.pop();
            }
        }
        Ok(())
    }
    fn enc_container(&mut self, it: &mut Interp, pairs: Vec<(Key, Value)>, as_list: bool) -> R<()> {
        if self.depth >= self.max_depth {
            self.error = 1;
        }
        let (open, close) = if as_list { (b'[', b']') } else { (b'{', b'}') };
        self.out.push(open);
        if pairs.is_empty() {
            self.out.push(close);
            return Ok(());
        }
        self.depth += 1;
        let mut first = true;
        for (k, v) in pairs {
            if !first {
                self.out.push(b',');
            }
            first = false;
            self.nl_indent();
            if !as_list {
                let kb = k.as_bytes();
                self.enc_str_key(&kb);
                self.out.push(b':');
                if self.pretty() {
                    self.out.push(b' ');
                }
            }
            self.encode(it, &v)?;
        }
        self.depth -= 1;
        self.nl_indent();
        self.out.push(close);
        Ok(())
    }
    fn enc_str_key(&mut self, k: &[u8]) {
        let saved = self.flags;
        self.flags &= !JSON_NUMERIC_CHECK;
        self.enc_str(k);
        self.flags = saved;
    }
}

pub fn json_error_msg(code: i64) -> &'static str {
    match code {
        0 => "No error",
        1 => "Maximum stack depth exceeded",
        2 => "State mismatch (invalid or malformed JSON)",
        3 => "Control character error, possibly incorrectly encoded",
        4 => "Syntax error",
        5 => "Malformed UTF-8 characters, possibly incorrectly encoded",
        6 => "Recursion detected",
        7 => "Inf and NaN cannot be JSON encoded",
        8 => "Type is not supported",
        9 => "The decoded property name is invalid",
        10 => "Single unpaired UTF-16 surrogate in unicode escape",
        11 => "Non-backed enums have no default serialization",
        _ => "Unknown error",
    }
}

fn f_json_encode(it: &mut Interp, a: &mut Args) -> R<Value> {
    let v = a.get(0);
    let flags = a.int_or(it, 1, 0)?;
    let depth = a.int_or(it, 2, 512)?;
    let mut e = JsonEnc::new(flags, depth as usize);
    e.encode(it, &v)?;
    it.json_last_error = e.error;
    it.ini.insert("__json_loc".into(), String::new());
    if e.error != 0 {
        if flags & JSON_THROW_ON_ERROR != 0 {
            it.json_last_error = 0;
            let ex = it.create_exception("JsonException", json_error_msg(e.error), e.error)?;
            return Err(Flow::Throw(ex));
        }
        if flags & JSON_PARTIAL_OUTPUT_ON_ERROR != 0 {
            return Ok(Value::vec(e.out));
        }
        return Ok(Value::Bool(false));
    }
    Ok(Value::vec(e.out))
}

struct JsonDec<'a> {
    s: &'a [u8],
    pos: usize,
    assoc: bool,
    bigint_str: bool,
    max_depth: usize,
    depth: usize,
    err: i64,
    err_pos: usize,
}

impl<'a> JsonDec<'a> {
    fn ws(&mut self) {
        while self.pos < self.s.len() && matches!(self.s[self.pos], b' ' | b'\t' | b'\n' | b'\r') {
            self.pos += 1;
        }
    }
    fn fail(&mut self, code: i64, at: usize) -> Option<Value> {
        if self.err == 0 {
            self.err = code;
            self.err_pos = at;
        }
        None
    }
    fn value(&mut self, it: &mut Interp) -> Option<Value> {
        self.ws();
        let start = self.pos;
        if self.pos >= self.s.len() {
            return self.fail(4, start);
        }
        let c = self.s[self.pos];
        match c {
            b'{' => {
                self.depth += 1;
                if self.depth > self.max_depth {
                    return self.fail(1, start);
                }
                self.pos += 1;
                let mut arr = PArray::new();
                self.ws();
                if self.pos < self.s.len() && self.s[self.pos] == b'}' {
                    self.pos += 1;
                } else {
                    loop {
                        self.ws();
                        let ks = self.pos;
                        if self.pos >= self.s.len() || self.s[self.pos] != b'"' {
                            return self.fail(4, ks);
                        }
                        let k = self.string()?;
                        self.ws();
                        if self.pos >= self.s.len() || self.s[self.pos] != b':' {
                            let p = self.pos;
                            return self.fail(4, p);
                        }
                        self.pos += 1;
                        let v = self.value(it)?;
                        if !self.assoc && k.first() == Some(&0) {
                            return self.fail(9, ks);
                        }
                        if self.assoc {
                            arr.set(Key::from_str_bytes(&k), v);
                        } else {
                            arr.set(Key::Str(Rc::new(k)), v);
                        }
                        self.ws();
                        if self.pos < self.s.len() && self.s[self.pos] == b',' {
                            self.pos += 1;
                            continue;
                        }
                        if self.pos < self.s.len() && self.s[self.pos] == b'}' {
                            self.pos += 1;
                            break;
                        }
                        let p = self.pos;
                        return self.fail(4, p);
                    }
                }
                self.depth -= 1;
                if self.assoc {
                    Some(Value::arr(arr))
                } else {
                    let o = it.new_stdclass();
                    if !arr.is_empty() {
                        *o.dynamic.borrow_mut() = Some(arr);
                    }
                    Some(Value::Object(o))
                }
            }
            b'[' => {
                self.depth += 1;
                if self.depth > self.max_depth {
                    return self.fail(1, start);
                }
                self.pos += 1;
                let mut arr = PArray::new();
                self.ws();
                if self.pos < self.s.len() && self.s[self.pos] == b']' {
                    self.pos += 1;
                } else {
                    loop {
                        let v = self.value(it)?;
                        arr.push(v);
                        self.ws();
                        if self.pos < self.s.len() && self.s[self.pos] == b',' {
                            self.pos += 1;
                            continue;
                        }
                        if self.pos < self.s.len() && self.s[self.pos] == b']' {
                            self.pos += 1;
                            break;
                        }
                        let p = self.pos;
                        return self.fail(4, p);
                    }
                }
                self.depth -= 1;
                Some(Value::arr(arr))
            }
            b'"' => {
                let s = self.string()?;
                Some(Value::vec(s))
            }
            b't' if self.s[self.pos..].starts_with(b"true") => {
                self.pos += 4;
                Some(Value::Bool(true))
            }
            b'f' if self.s[self.pos..].starts_with(b"false") => {
                self.pos += 5;
                Some(Value::Bool(false))
            }
            b'n' if self.s[self.pos..].starts_with(b"null") => {
                self.pos += 4;
                Some(Value::Null)
            }
            b'-' | b'0'..=b'9' => self.number(),
            _ => self.fail(4, start),
        }
    }
    fn number(&mut self) -> Option<Value> {
        let st = self.pos;
        let s = self.s;
        let mut i = self.pos;
        if s[i] == b'-' {
            i += 1;
        }
        if i >= s.len() || !s[i].is_ascii_digit() {
            return self.fail(4, st);
        }
        if s[i] == b'0' {
            i += 1;
        } else {
            while i < s.len() && s[i].is_ascii_digit() {
                i += 1;
            }
        }
        let mut is_float = false;
        if i < s.len() && s[i] == b'.' {
            if i + 1 >= s.len() || !s[i + 1].is_ascii_digit() {
                self.pos = i;
                return self.fail(4, i);
            }
            is_float = true;
            i += 1;
            while i < s.len() && s[i].is_ascii_digit() {
                i += 1;
            }
        }
        if i < s.len() && (s[i] == b'e' || s[i] == b'E') {
            let mut j = i + 1;
            if j < s.len() && (s[j] == b'+' || s[j] == b'-') {
                j += 1;
            }
            if j < s.len() && s[j].is_ascii_digit() {
                is_float = true;
                while j < s.len() && s[j].is_ascii_digit() {
                    j += 1;
                }
                i = j;
            } else {
                return self.fail(4, i);
            }
        }
        self.pos = i;
        let txt = std::str::from_utf8(&s[st..i]).unwrap();
        if !is_float {
            if let Ok(v) = txt.parse::<i64>() {
                return Some(Value::Int(v));
            }
            if self.bigint_str {
                return Some(Value::str(txt));
            }
        }
        Some(Value::Float(txt.parse().unwrap_or(0.0)))
    }
    fn string(&mut self) -> Option<Vec<u8>> {
        let st = self.pos;
        self.pos += 1;
        let mut out = Vec::new();
        loop {
            if self.pos >= self.s.len() {
                self.fail(3, st);
                return None;
            }
            let c = self.s[self.pos];
            match c {
                b'"' => {
                    self.pos += 1;
                    return Some(out);
                }
                b'\\' => {
                    self.pos += 1;
                    if self.pos >= self.s.len() {
                        self.fail(4, st);
                        return None;
                    }
                    let e = self.s[self.pos];
                    self.pos += 1;
                    match e {
                        b'"' => out.push(b'"'),
                        b'\\' => out.push(b'\\'),
                        b'/' => out.push(b'/'),
                        b'b' => out.push(8),
                        b'f' => out.push(12),
                        b'n' => out.push(b'\n'),
                        b'r' => out.push(b'\r'),
                        b't' => out.push(b'\t'),
                        b'u' => {
                            let cp = self.hex4();
                            let cp = match cp {
                                Some(c) => c,
                                None => {
                                    self.fail(4, st);
                                    return None;
                                }
                            };
                            if (0xD800..0xDC00).contains(&cp) {
                                if self.s[self.pos..].starts_with(b"\\u") {
                                    self.pos += 2;
                                    let lo = self.hex4();
                                    match lo {
                                        Some(lo) if (0xDC00..0xE000).contains(&lo) => {
                                            let full = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                                            crate::lexer::encode_utf8(full, &mut out);
                                        }
                                        _ => {
                                            self.fail(10, st);
                                            return None;
                                        }
                                    }
                                } else {
                                    self.fail(10, st);
                                    return None;
                                }
                            } else if (0xDC00..0xE000).contains(&cp) {
                                self.fail(10, st);
                                return None;
                            } else {
                                crate::lexer::encode_utf8(cp, &mut out);
                            }
                        }
                        _ => {
                            self.fail(4, st);
                            return None;
                        }
                    }
                }
                c if c < 0x20 => {
                    self.fail(4, st);
                    return None;
                }
                c if c >= 0x80 => match utf8_valid_at(self.s, self.pos) {
                    Some((_, l)) => {
                        out.extend_from_slice(&self.s[self.pos..self.pos + l]);
                        self.pos += l;
                    }
                    None => {
                        self.fail(5, st);
                        return None;
                    }
                },
                c => {
                    out.push(c);
                    self.pos += 1;
                }
            }
        }
    }
    fn hex4(&mut self) -> Option<u32> {
        if self.pos + 4 > self.s.len() {
            return None;
        }
        let h = std::str::from_utf8(&self.s[self.pos..self.pos + 4]).ok()?;
        let v = u32::from_str_radix(h, 16).ok()?;
        self.pos += 4;
        Some(v)
    }
}

fn loc_of(s: &[u8], pos: usize) -> (usize, usize) {
    let mut line = 1;
    let mut col = 1;
    for &c in &s[..pos.min(s.len())] {
        if c == b'\n' {
            line += 1;
            col = 1;
        } else {
            col += 1;
        }
    }
    (line, col)
}

fn f_json_decode(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let assoc_v = if a.has(1) { a.get(1) } else { Value::Null };
    let depth = a.int_or(it, 2, 512)?;
    let flags = a.int_or(it, 3, 0)?;
    if depth <= 0 {
        return Err(a.value_err(it, 2, "must be greater than 0"));
    }
    let assoc = match assoc_v {
        Value::Null => flags & JSON_OBJECT_AS_ARRAY != 0,
        v => v.to_bool(),
    };
    let mut d = JsonDec { s: &s, pos: 0, assoc, bigint_str: flags & JSON_BIGINT_AS_STRING != 0, max_depth: depth as usize, depth: 0, err: 0, err_pos: 0 };
    let r = if s.is_empty() {
        d.err = 4;
        d.err_pos = usize::MAX;
        None
    } else {
        let v = d.value(it);
        match v {
            Some(v) => {
                d.ws();
                if d.pos < s.len() {
                    let p = d.pos;
                    d.fail(4, p);
                    None
                } else {
                    Some(v)
                }
            }
            None => None,
        }
    };
    match r {
        Some(v) => {
            it.json_last_error = 0;
            it.ini.insert("__json_loc".into(), String::new());
            Ok(v)
        }
        None => {
            let loc = if d.err_pos == usize::MAX { String::new() } else {
                let (l, c) = loc_of(&s, d.err_pos);
                format!(" near location {}:{}", l, c)
            };
            if flags & JSON_THROW_ON_ERROR != 0 {
                let msg = format!("{}{}", json_error_msg(d.err), loc);
                let ex = it.create_exception("JsonException", &msg, d.err)?;
                return Err(Flow::Throw(ex));
            }
            it.json_last_error = d.err;
            it.ini.insert("__json_loc".into(), loc);
            Ok(Value::Null)
        }
    }
}

fn f_json_last_error(it: &mut Interp, _a: &mut Args) -> R<Value> {
    Ok(Value::Int(it.json_last_error))
}
fn f_json_last_error_msg(it: &mut Interp, _a: &mut Args) -> R<Value> {
    let loc = it.ini.get("__json_loc").cloned().unwrap_or_default();
    Ok(Value::string(format!("{}{}", json_error_msg(it.json_last_error), loc)))
}
fn f_json_validate(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    if s.is_empty() {
        it.json_last_error = 4;
        return Ok(Value::Bool(false));
    }
    let mut d = JsonDec { s: &s, pos: 0, assoc: true, bigint_str: true, max_depth: 512, depth: 0, err: 0, err_pos: 0 };
    let ok = match d.value(it) {
        Some(_) => {
            d.ws();
            d.pos >= s.len()
        }
        None => false,
    };
    if ok {
        it.json_last_error = 0;
        it.ini.insert("__json_loc".into(), String::new());
    } else {
        if d.err == 0 {
            d.err = 4;
            d.err_pos = d.pos;
        }
        let (l, c) = loc_of(&s, d.err_pos);
        it.json_last_error = d.err;
        it.ini.insert("__json_loc".into(), format!(" near location {}:{}", l, c));
    }
    Ok(Value::Bool(ok))
}

pub fn register(it: &mut Interp) {
    reg(it, "json_encode", "value,flags?,depth?", f_json_encode);
    reg(it, "json_decode", "json,associative?,depth?,flags?", f_json_decode);
    reg(it, "json_last_error", "", f_json_last_error);
    reg(it, "json_last_error_msg", "", f_json_last_error_msg);
    reg(it, "json_validate", "json,depth?,flags?", f_json_validate);
    let c: &[(&str, i64)] = &[
        ("JSON_HEX_TAG", 1),
