        Value::Object(o) if is_resource_obj(&o) => {
            let fh = o.with_internal_ref::<ResBox, _>(|r| r.0.clone()).unwrap();
            if matches!(fh.borrow().stream, Stream::Closed) {
                return Err(it.type_error(&format!("{}(): supplied resource is not a valid stream resource", a.def.name)));
            }
            Ok(fh)
        }
        other => {
            let msg = format!("{}(): Argument #{} (${}) must be of type resource, {} given", a.def.name, i + 1, a.def.param_name(i), other.type_name());
            Err(it.type_error(&msg))
        }
    }
}

pub fn write_to(it: &mut Interp, h: &Value, data: &[u8]) -> R<i64> {
    let fh = match h {
        Value::Object(o) if is_resource_obj(o) => o.with_internal_ref::<ResBox, _>(|r| r.0.clone()).unwrap(),
        _ => return Ok(0),
    };
    write_handle(it, &fh, data)
}

fn write_handle(it: &mut Interp, fh: &Rc<RefCell<FileHandle>>, data: &[u8]) -> R<i64> {
    let mut f = fh.borrow_mut();
    match &mut f.stream {
        Stream::Stdout | Stream::Output => {
            drop(f);
            it.echo(data);
        }
        Stream::Stderr => {
            drop(f);
            it.flush();
            let _ = std::io::stderr().write_all(data);
        }
        Stream::File(file) => {
            let _ = file.write_all(data);
        }
        Stream::Memory(buf) => {
            let p = f.pos;
            let FileHandle { stream, pos, .. } = &mut *f;
            if let Stream::Memory(buf) = stream {
                if f_is_append(&buf) {}
                if p >= buf.len() {
                    buf.resize(p, 0);
                    buf.extend_from_slice(data);
                } else {
                    let end = (p + data.len()).min(buf.len());
                    buf.splice(p..end, data.iter().copied());
                }
                *pos = p + data.len();
            }
            let _ = buf;
        }
        _ => return Ok(0),
    }
    Ok(data.len() as i64)
}
fn f_is_append(_b: &[u8]) -> bool {
    false
}

fn fill_read(fh: &mut FileHandle, want: usize) {
    // ensure rbuf has at least `want` bytes or eof
    while fh.rbuf.len() < want && !fh.eof {
        let mut tmp = vec![0u8; 8192.max(want - fh.rbuf.len())];
        let n = match &mut fh.stream {
            Stream::Stdin => std::io::stdin().read(&mut tmp).unwrap_or(0),
            Stream::File(f) => f.read(&mut tmp).unwrap_or(0),
            Stream::Memory(buf) => {
                let p = fh.pos;
                let avail = buf.len().saturating_sub(p);
                let n = avail.min(tmp.len());
                tmp[..n].copy_from_slice(&buf[p..p + n]);
                fh.pos += n;
                n
            }
            _ => 0,
        };
        if n == 0 {
            fh.eof = true;
            break;
        }
        fh.rbuf.extend_from_slice(&tmp[..n]);
    }
}

fn read_line(fh: &mut FileHandle, max: Option<usize>) -> Option<Vec<u8>> {
    loop {
        if let Some(p) = fh.rbuf.iter().position(|&c| c == b'\n') {
            let take = match max {
                Some(m) if m < p + 1 => m,
                _ => p + 1,
            };
            let line: Vec<u8> = fh.rbuf.drain(..take).collect();
            return Some(line);
        }
        if let Some(m) = max {
            if fh.rbuf.len() >= m {
                let line: Vec<u8> = fh.rbuf.drain(..m).collect();
                return Some(line);
            }
        }
        if fh.eof {
            if fh.rbuf.is_empty() {
                return None;
            }
            return Some(std::mem::take(&mut fh.rbuf));
        }
        let want = fh.rbuf.len() + 1;
        fill_read(fh, want);
    }
}

fn f_fopen(it: &mut Interp, a: &mut Args) -> R<Value> {
    let path = a.str(it, 0)?;
    let mode = a.str(it, 1)?;
    let p = String::from_utf8_lossy(&path).to_string();
    let m = String::from_utf8_lossy(&mode).to_string();
    let stream = match p.as_str() {
        "php://stdin" => Stream::Stdin,
        "php://stdout" => Stream::Stdout,
        "php://stderr" => Stream::Stderr,
        "php://output" => Stream::Output,
        _ if p.starts_with("php://memory") || p.starts_with("php://temp") => Stream::Memory(Vec::new()),
        _ => {
            let mut o = std::fs::OpenOptions::new();
            let base = m.replace('b', "").replace('t', "");
            match base.as_str() {
                "r" => {
                    o.read(true);
                }
                "r+" => {
                    o.read(true).write(true);
                }
                "w" => {
                    o.write(true).create(true).truncate(true);
                }
                "w+" => {
                    o.read(true).write(true).create(true).truncate(true);
                }
                "a" => {
                    o.append(true).create(true);
                }
                "a+" => {
                    o.read(true).append(true).create(true);
                }
                "x" => {
                    o.write(true).create_new(true);
                }
                "x+" => {
                    o.read(true).write(true).create_new(true);
                }
                "c" => {
                    o.write(true).create(true);
                }
                "c+" => {
                    o.read(true).write(true).create(true);
                }
                _ => {
                    return Err(a.value_err(it, 1, "must be a valid mode"));
                }
            }
            match o.open(&p) {
                Ok(f) => Stream::File(f),
                Err(e) => {
                    let why = match e.kind() {
                        std::io::ErrorKind::NotFound => "No such file or directory",
                        std::io::ErrorKind::PermissionDenied => "Permission denied",
                        std::io::ErrorKind::AlreadyExists => "File exists",
                        _ => "Failed",
                    };
                    let msg = format!("fopen({}): Failed to open stream: {}", p, if std::path::Path::new(&p).is_dir() { "Is a directory" } else { why });
                    it.warn(&msg)?;
                    return Ok(Value::Bool(false));
                }
            }
        }
    };
    Ok(new_resource(it, stream, &m, &p, None))
}
fn f_fclose(it: &mut Interp, a: &mut Args) -> R<Value> {
    let fh = handle(it, a, 0)?;
    let mut f = fh.borrow_mut();
    if let Stream::File(file) = &mut f.stream {
        let _ = file.flush();
    }
    f.stream = Stream::Closed;
    Ok(Value::Bool(true))
}
fn f_fwrite(it: &mut Interp, a: &mut Args) -> R<Value> {
    let fh = handle(it, a, 0)?;
    let s = a.str(it, 1)?;
    let data = match a.opt_int(it, 2)? {
        Some(l) => &s[..(l.max(0) as usize).min(s.len())],
        None => &s[..],
    };
    if fh.borrow().mode.starts_with('r') && !fh.borrow().mode.contains('+') && !matches!(fh.borrow().stream, Stream::Stdout | Stream::Stderr | Stream::Output) {
        it.notice(&format!("fwrite(): Write of {} bytes failed with errno=9 Bad file descriptor", data.len()))?;
        return Ok(Value::Bool(false));
    }
    let n = write_handle(it, &fh, data)?;
    Ok(Value::Int(n))
}
fn f_fread(it: &mut Interp, a: &mut Args) -> R<Value> {
    let fh = handle(it, a, 0)?;
    let n = a.int(it, 1)?;
    if n <= 0 {
        return Err(a.value_err(it, 1, "must be greater than 0"));
    }
    let mut f = fh.borrow_mut();
    fill_read(&mut f, n as usize);
    let take = (n as usize).min(f.rbuf.len());
    let out: Vec<u8> = f.rbuf.drain(..take).collect();
    Ok(Value::vec(out))
}
fn f_fgets(it: &mut Interp, a: &mut Args) -> R<Value> {
    let fh = handle(it, a, 0)?;
    let max = a.opt_int(it, 1)?.map(|l| (l.max(1) - 1) as usize);
    if matches!(fh.borrow().stream, Stream::Stdin) {
        it.flush();
    }
    let mut f = fh.borrow_mut();
    Ok(match read_line(&mut f, max) {
        Some(l) => Value::vec(l),
        None => Value::Bool(false),
    })
}
fn f_fgetc(it: &mut Interp, a: &mut Args) -> R<Value> {
    let fh = handle(it, a, 0)?;
    let mut f = fh.borrow_mut();
    fill_read(&mut f, 1);
    if f.rbuf.is_empty() {
        return Ok(Value::Bool(false));
    }
    let c = f.rbuf.remove(0);
    Ok(Value::vec(vec![c]))
}
fn f_feof(it: &mut Interp, a: &mut Args) -> R<Value> {
    let fh = handle(it, a, 0)?;
    let mut f = fh.borrow_mut();
    if f.rbuf.is_empty() && !f.eof {
        if let Stream::Memory(buf) = &f.stream {
            return Ok(Value::Bool(f.pos >= buf.len() && f.eof));
        }
        if matches!(f.stream, Stream::File(_) | Stream::Stdin) {
            fill_read(&mut f, 1);
            if f.rbuf.is_empty() {
                return Ok(Value::Bool(true));
            }
        }
    }
    Ok(Value::Bool(f.rbuf.is_empty() && f.eof))
}
fn f_ftell(it: &mut Interp, a: &mut Args) -> R<Value> {
    let fh = handle(it, a, 0)?;
    let mut f = fh.borrow_mut();
    let buffered = f.rbuf.len();
    let p = match &mut f.stream {
        Stream::File(file) => file.stream_position().unwrap_or(0) as usize,
        Stream::Memory(_) => f.pos,
        _ => 0,
    };
    Ok(Value::Int((p - buffered.min(p)) as i64))
}
fn f_fseek(it: &mut Interp, a: &mut Args) -> R<Value> {
    let fh = handle(it, a, 0)?;
    let off = a.int(it, 1)?;
    let whence = a.int_or(it, 2, 0)?;
    let mut f = fh.borrow_mut();
    let buffered = f.rbuf.len() as i64;
    f.rbuf.clear();
    f.eof = false;
    let FileHandle { stream, pos, .. } = &mut *f;
    match stream {
        Stream::File(file) => {
            let r = match whence {
                1 => file.seek(SeekFrom::Current(off - buffered)),
                2 => file.seek(SeekFrom::End(off)),
                _ => file.seek(SeekFrom::Start(off.max(0) as u64)),
            };
            Ok(Value::Int(if r.is_ok() { 0 } else { -1 }))
        }
        Stream::Memory(buf) => {
            let np = match whence {
                1 => *pos as i64 - buffered + off,
                2 => buf.len() as i64 + off,
                _ => off,
            };
            if np < 0 {
                return Ok(Value::Int(-1));
            }
            *pos = np as usize;
            Ok(Value::Int(0))
        }
        _ => Ok(Value::Int(-1)),
    }
}
fn f_rewind(it: &mut Interp, a: &mut Args) -> R<Value> {
    let fh = handle(it, a, 0)?;
    let mut f = fh.borrow_mut();
    f.rbuf.clear();
    f.eof = false;
    f.pos = 0;
    if let Stream::File(file) = &mut f.stream {
        let _ = file.seek(SeekFrom::Start(0));
    }
    Ok(Value::Bool(true))
}
fn f_fflush(it: &mut Interp, a: &mut Args) -> R<Value> {
    let fh = handle(it, a, 0)?;
    let is_out = matches!(fh.borrow().stream, Stream::Stdout | Stream::Output);
    if is_out {
        it.flush();
    }
    if let Stream::File(file) = &mut fh.borrow_mut().stream {
        let _ = file.flush();
    }
    Ok(Value::Bool(true))
}
fn f_ftruncate(it: &mut Interp, a: &mut Args) -> R<Value> {
    let fh = handle(it, a, 0)?;
    let size = a.int(it, 1)?;
    let mut f = fh.borrow_mut();
    match &mut f.stream {
        Stream::File(file) => Ok(Value::Bool(file.set_len(size as u64).is_ok())),
        Stream::Memory(buf) => {
            buf.resize(size as usize, 0);
            Ok(Value::Bool(true))
        }
        _ => Ok(Value::Bool(false)),
    }
}
fn f_stream_get_contents(it: &mut Interp, a: &mut Args) -> R<Value> {
    let fh = handle(it, a, 0)?;
    let mut f = fh.borrow_mut();
    fill_read(&mut f, usize::MAX / 2);
    let out = std::mem::take(&mut f.rbuf);
    Ok(Value::vec(out))
}
fn f_fpassthru(it: &mut Interp, a: &mut Args) -> R<Value> {
    let fh = handle(it, a, 0)?;
    let out = {
        let mut f = fh.borrow_mut();
        fill_read(&mut f, usize::MAX / 2);
        std::mem::take(&mut f.rbuf)
    };
    it.echo(&out);
    Ok(Value::Int(out.len() as i64))
}
fn f_flock(_it: &mut Interp, _a: &mut Args) -> R<Value> {
    Ok(Value::Bool(true))
}
fn f_fgetcsv(it: &mut Interp, a: &mut Args) -> R<Value> {
    let fh = handle(it, a, 0)?;
    let sep = a.str_or(it, 2, b",")?;
    let enc = a.str_or(it, 3, b"\"")?;
    let mut f = fh.borrow_mut();
    let mut line = match read_line(&mut f, None) {
        Some(l) => l,
        None => return Ok(Value::Bool(false)),
    };
    // handle multi-line quoted fields
    loop {
        let quotes = line.iter().filter(|&&c| c == enc[0]).count();
        if quotes % 2 == 0 {
            break;
        }
        match read_line(&mut f, None) {
            Some(l) => line.extend_from_slice(&l),
            None => break,
        }
    }
    Ok(Value::arr(super::string::parse_csv_line(&line, sep[0], enc[0], Some(b'\\'))))
}
pub fn csv_line(it: &mut Interp, fields: &PArray, sep: u8, enc: u8, eol: &[u8]) -> R<Vec<u8>> {
    let mut out = Vec::new();
    let mut first = true;
    for v in fields.values() {
        if !first {
            out.push(sep);
        }
        first = false;
        let s = it.to_str(&v.deref())?;
        let needs = s.iter().any(|&c| c == sep || c == enc || c == b'\n' || c == b'\r' || c == b'\t' || c == b' ' || c == b'\\');
        if needs {
            out.push(enc);
            for &c in s.iter() {
                if c == enc {
                    out.push(enc);
                }
                out.push(c);
            }
            out.push(enc);
        } else {
            out.extend_from_slice(&s);
        }
    }
    out.extend_from_slice(eol);
    Ok(out)
}
fn f_fputcsv(it: &mut Interp, a: &mut Args) -> R<Value> {
    let fh = handle(it, a, 0)?;
    let fields = a.arr(it, 1)?;
    let sep = a.str_or(it, 2, b",")?;
    let enc = a.str_or(it, 3, b"\"")?;
    let eol = a.str_or(it, 5, b"\n")?;
    let line = csv_line(it, &fields, sep[0], enc[0], &eol)?;
    let n = write_handle(it, &fh, &line)?;
    Ok(Value::Int(n))
}
fn f_fstat(it: &mut Interp, a: &mut Args) -> R<Value> {
    let fh = handle(it, a, 0)?;
    let f = fh.borrow();
    let size = match &f.stream {
        Stream::File(file) => file.metadata().map(|m| m.len()).unwrap_or(0) as i64,
        Stream::Memory(b) => b.len() as i64,
        _ => 0,
    };
    let mut out = PArray::new();
    out.set(Key::Str(pstr("size")), Value::Int(size));
    Ok(Value::arr(out))
}
fn f_file_get_contents(it: &mut Interp, a: &mut Args) -> R<Value> {
    let p = a.str(it, 0)?;
    let ps = String::from_utf8_lossy(&p).to_string();
    if ps == "php://stdin" {
        let mut s = Vec::new();
        let _ = std::io::stdin().read_to_end(&mut s);
        return Ok(Value::vec(s));
    }
    match std::fs::read(&ps) {
        Ok(d) => {
            let off = a.int_or(it, 3, 0)?.max(0) as usize;
            let d = if off > 0 { d[off.min(d.len())..].to_vec() } else { d };
            let d = match a.opt_int(it, 4)? {
                Some(l) => d[..(l.max(0) as usize).min(d.len())].to_vec(),
                None => d,
            };
            Ok(Value::vec(d))
        }
        Err(e) => {
            let why = if std::path::Path::new(&ps).is_dir() {
                "Is a directory"
            } else {
                match e.kind() {
                    std::io::ErrorKind::NotFound => "No such file or directory",
                    std::io::ErrorKind::PermissionDenied => "Permission denied",
                    _ => "Failed",
                }
            };
            if why == "Is a directory" {
                it.notice(&format!("file_get_contents(): Read of 8192 bytes failed with errno=21 Is a directory"))?;
                return Ok(Value::str(""));
            }
            it.warn(&format!("file_get_contents({}): Failed to open stream: {}", ps, why))?;
            Ok(Value::Bool(false))
        }
    }
}
fn f_file_put_contents(it: &mut Interp, a: &mut Args) -> R<Value> {
    let p = a.str(it, 0)?;
    let ps = String::from_utf8_lossy(&p).to_string();
    let data = match a.get(1) {
        Value::Array(arr) => {
            let mut v = Vec::new();
            for x in arr.values() {
                v.extend_from_slice(&it.to_str(&x.deref())?);
            }
            v
        }
        Value::Object(o) if is_resource_obj(&o) => {
            let fh = o.with_internal_ref::<ResBox, _>(|r| r.0.clone()).unwrap();
            let mut f = fh.borrow_mut();
            fill_read(&mut f, usize::MAX / 2);
            std::mem::take(&mut f.rbuf)
        }
        v => it.to_str(&v)?.to_vec(),
    };
    let flags = a.int_or(it, 2, 0)?;
    if ps == "php://stdout" || ps == "php://output" {
        it.echo(&data);
        return Ok(Value::Int(data.len() as i64));
    }
    if ps == "php://stderr" {
        it.flush();
        let _ = std::io::stderr().write_all(&data);
        return Ok(Value::Int(data.len() as i64));
    }
    let r = if flags & 8 != 0 {
        std::fs::OpenOptions::new().append(true).create(true).open(&ps).and_then(|mut f| f.write_all(&data))
    } else {
        std::fs::write(&ps, &data)
    };
    match r {
        Ok(()) => Ok(Value::Int(data.len() as i64)),
        Err(e) => {
            let why = match e.kind() {
                std::io::ErrorKind::NotFound => "No such file or directory",
                std::io::ErrorKind::PermissionDenied => "Permission denied",
                _ => "Failed",
            };
            it.warn(&format!("file_put_contents({}): Failed to open stream: {}", ps, why))?;
            Ok(Value::Bool(false))
        }
    }
}
fn f_file(it: &mut Interp, a: &mut Args) -> R<Value> {
    let p = a.str(it, 0)?;
    let ps = String::from_utf8_lossy(&p).to_string();
    let flags = a.int_or(it, 1, 0)?;
    let data = match std::fs::read(&ps) {
        Ok(d) => d,
        Err(_) => {
            it.warn(&format!("file({}): Failed to open stream: No such file or directory", ps))?;
            return Ok(Value::Bool(false));
        }
    };
    let mut out = PArray::new();
    let mut st = 0;
    let n = data.len();
    let mut i = 0;
    while i <= n {
        if i == n || data[i] == b'\n' {
            if i == n && st == n {
                break;
            }
            let mut line = if i < n { &data[st..i + 1] } else { &data[st..i] };
            if flags & 2 != 0 {
                if line.last() == Some(&b'\n') {
                    line = &line[..line.len() - 1];
                    if line.last() == Some(&b'\r') {
                        line = &line[..line.len() - 1];
                    }
                }
            }
            if !(flags & 4 != 0 && line.is_empty()) {
                out.push(Value::bytes(line));
            }
            st = i + 1;
        }
        i += 1;
    }
    Ok(Value::arr(out))
}
fn path_arg(it: &mut Interp, a: &Args, i: usize) -> R<String> {
