fn f_mkdir(it: &mut Interp, a: &mut Args) -> R<Value> {
    let p = path_arg(it, a, 0)?;
    let rec = a.bool_or(it, 2, false)?;
    let r = if rec { std::fs::create_dir_all(&p) } else { std::fs::create_dir(&p) };
    match r {
        Ok(()) => Ok(Value::Bool(true)),
        Err(e) => {
