}
fn f_pathinfo(it: &mut Interp, a: &mut Args) -> R<Value> {
    let p = a.str(it, 0)?;
    let opt = a.int_or(it, 1, 15)?;
    let mut out = PArray::new();
    let dir = dirname(&p, 1);
    let has_dir = p.contains(&b'/');
    if opt & 1 != 0 && has_dir {
        out.set(Key::Str(pstr("dirname")), Value::vec(dir));
    } else if opt & 1 != 0 && !p.is_empty() {
        out.set(Key::Str(pstr("dirname")), Value::str("."));
    }
    let base = basename(&p, b"");
    if opt & 2 != 0 {
        out.set(Key::Str(pstr("basename")), Value::vec(base.clone()));
    }
    let dot = base.iter().rposition(|&c| c == b'.');
    if opt & 4 != 0 {
        if let Some(d) = dot {
            out.set(Key::Str(pstr("extension")), Value::bytes(&base[d + 1..]));
        }
    }
    if opt & 8 != 0 {
        let fname = match dot {
            Some(d) => &base[..d],
            None => &base[..],
        };
        out.set(Key::Str(pstr("filename")), Value::bytes(fname));
    }
    if opt != 15 {
        return Ok(out.values().next().cloned().unwrap_or(Value::str("")));
    }
    Ok(Value::arr(out))
}
fn f_tempnam(it: &mut Interp, a: &mut Args) -> R<Value> {
