    for i in 0..1000 {
        let t = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().subsec_nanos();
        let p = format!("{}/{}{:06x}{}", dir, pre, t % 0xffffff, i);
        if !std::path::Path::new(&p).exists() {
            let _ = std::fs::write(&p, b"");
