fn glob_match(pat: &[u8], s: &[u8]) -> bool {
    if pat.is_empty() {
        return s.is_empty();
    }
    match pat[0] {
        b'*' => (0..=s.len()).any(|i| glob_match(&pat[1..], &s[i..])),
        b'?' => !s.is_empty() && glob_match(&pat[1..], &s[1..]),
        b'[' => {
            if s.is_empty() {
                return false;
            }
            let end = match pat.iter().position(|&c| c == b']') {
                Some(e) => e,
                None => return false,
            };
            let set = &pat[1..end];
            let (neg, set) = if set.first() == Some(&b'!') || set.first() == Some(&b'^') { (true, &set[1..]) } else { (false, set) };
            let mut m = false;
            let mut i = 0;
            while i < set.len() {
                if i + 2 < set.len() && set[i + 1] == b'-' {
                    if s[0] >= set[i] && s[0] <= set[i + 2] {
                        m = true;
                    }
                    i += 3;
                } else {
                    if s[0] == set[i] {
                        m = true;
                    }
                    i += 1;
                }
            }
            m != neg && glob_match(&pat[end + 1..], &s[1..])
        }
        c => !s.is_empty() && s[0] == c && glob_match(&pat[1..], &s[1..]),
    }
}
