fn f_glob(it: &mut Interp, a: &mut Args) -> R<Value> {
    let pat = path_arg(it, a, 0)?;
    let (dir, fpat) = match pat.rfind('/') {
        Some(i) => (pat[..i].to_string(), pat[i + 1..].to_string()),
        None => (".".to_string(), pat.clone()),
    };
    let mut out = Vec::new();
    if let Ok(rd) = std::fs::read_dir(if dir.is_empty() { "/" } else { &dir }) {
        for e in rd.filter_map(|e| e.ok()) {
            let n = e.file_name().to_string_lossy().to_string();
            if n.starts_with('.') && !fpat.starts_with('.') {
                continue;
            }
            if glob_match(fpat.as_bytes(), n.as_bytes()) {
                if pat.contains('/') {
                    out.push(format!("{}/{}", dir, n));
                } else {
                    out.push(n);
                }
            }
        }
    }
    out.sort();
    Ok(Value::arr(PArray::from_values(out.iter().map(|s| Value::str(s)).collect())))
}
