use super::*;
use crate::array::{Key, PArray};
use crate::object::Object;
use std::io::{Read, Seek, SeekFrom, Write};

pub enum Stream {
    Stdin,
    Stdout,
    Stderr,
    Output,
    File(std::fs::File),
    Memory(Vec<u8>),
    Dir(Vec<String>),
    Closed,
}

pub struct FileHandle {
    pub id: i64,
    pub stream: Stream,
    pub pos: usize,
    pub eof: bool,
    pub rbuf: Vec<u8>,
    pub mode: String,
    pub path: String,
}

pub struct ResBox(pub Rc<RefCell<FileHandle>>);

use std::cell::RefCell;

pub fn is_resource_obj(o: &Object) -> bool {
    &*o.class.lname == "__resource"
}
pub fn is_closed_resource(o: &Object) -> bool {
    o.with_internal_ref::<ResBox, _>(|r| matches!(r.0.borrow().stream, Stream::Closed)).unwrap_or(true)
}
pub fn resource_id(o: &Object) -> i64 {
    o.with_internal_ref::<ResBox, _>(|r| r.0.borrow().id).unwrap_or(0)
}

impl Object {
    pub fn with_internal_ref<T: std::any::Any, R2>(&self, f: impl FnOnce(&T) -> R2) -> Option<R2> {
        let b = self.internal.borrow();
        match &*b {
            crate::object::Internal::Any(a) => a.downcast_ref::<T>().map(f),
            _ => None,
        }
    }
}

pub fn new_resource(it: &mut Interp, stream: Stream, mode: &str, path: &str, id: Option<i64>) -> Value {
    let cls = match it.classes.get(&b"__resource"[..]).cloned() {
        Some(c) => c,
        None => return Value::Bool(false),
    };
    let id = match id {
        Some(i) => i,
        None => {
            let i = it.next_resource;
            it.next_resource += 1;
            i
        }
    };
    let o = Object::new(cls, Vec::new());
    o.flags.set(o.flags.get() | crate::object::OBJ_NO_DTOR);
    let fh = Rc::new(RefCell::new(FileHandle { id, stream, pos: 0, eof: false, rbuf: Vec::new(), mode: mode.to_string(), path: path.to_string() }));
    it.resources.insert(id, fh.clone());
    o.set_internal(ResBox(fh));
    Value::Object(o)
}

pub fn init_std_streams(it: &mut Interp) {
    let a = new_resource(it, Stream::Stdin, "r", "php://stdin", Some(1));
    let b = new_resource(it, Stream::Stdout, "w", "php://stdout", Some(2));
    let c = new_resource(it, Stream::Stderr, "w", "php://stderr", Some(3));
    super::misc::def_const(it, "STDIN", a);
    super::misc::def_const(it, "STDOUT", b);
    super::misc::def_const(it, "STDERR", c);
}

fn handle(it: &mut Interp, a: &Args, i: usize) -> R<Rc<RefCell<FileHandle>>> {
    match a.get(i) {
        Value::Object(o) if is_resource_obj(&o) => {
            let fh = o.with_internal_ref::<ResBox, _>(|r| r.0.clone()).unwrap();
            if matches!(fh.borrow().stream, Stream::Closed) {
                return Err(it.type_error(&format!("{}(): supplied resource is not a valid stream resource", a.def.name)));
            }
            Ok(fh)
        }
        other => {
            let msg = format!("{}(): Argument #{} (${}) must be of type resource, {} given", a.def.name, i + 1, a.def.param_name(i), other.type_name());
            Err(it.type_error(&msg))
        }
    }
}

pub fn write_to(it: &mut Interp, h: &Value, data: &[u8]) -> R<i64> {
    let fh = match h {
        Value::Object(o) if is_resource_obj(o) => o.with_internal_ref::<ResBox, _>(|r| r.0.clone()).unwrap(),
        _ => return Ok(0),
    };
    write_handle(it, &fh, data)
}

fn write_handle(it: &mut Interp, fh: &Rc<RefCell<FileHandle>>, data: &[u8]) -> R<i64> {
    let mut f = fh.borrow_mut();
    match &mut f.stream {
        Stream::Stdout | Stream::Output => {
            drop(f);
            it.echo(data);
        }
        Stream::Stderr => {
            drop(f);
            it.flush();
            let _ = std::io::stderr().write_all(data);
        }
        Stream::File(file) => {
            let _ = file.write_all(data);
        }
        Stream::Memory(buf) => {
            let p = f.pos;
            let FileHandle { stream, pos, .. } = &mut *f;
            if let Stream::Memory(buf) = stream {
                if f_is_append(&buf) {}
                if p >= buf.len() {
                    buf.resize(p, 0);
                    buf.extend_from_slice(data);
                } else {
                    let end = (p + data.len()).min(buf.len());
                    buf.splice(p..end, data.iter().copied());
                }
                *pos = p + data.len();
            }
            let _ = buf;
        }
        _ => return Ok(0),
    }
    Ok(data.len() as i64)
}
fn f_is_append(_b: &[u8]) -> bool {
    false
}

fn fill_read(fh: &mut FileHandle, want: usize) {
    // ensure rbuf has at least `want` bytes or eof
    while fh.rbuf.len() < want && !fh.eof {
        let mut tmp = vec![0u8; 8192.max(want - fh.rbuf.len())];
        let n = match &mut fh.stream {
            Stream::Stdin => std::io::stdin().read(&mut tmp).unwrap_or(0),
            Stream::File(f) => f.read(&mut tmp).unwrap_or(0),
            Stream::Memory(buf) => {
                let p = fh.pos;
                let avail = buf.len().saturating_sub(p);
                let n = avail.min(tmp.len());
                tmp[..n].copy_from_slice(&buf[p..p + n]);
                fh.pos += n;
                n
            }
            _ => 0,
        };
        if n == 0 {
            fh.eof = true;
            break;
        }
        fh.rbuf.extend_from_slice(&tmp[..n]);
    }
}

fn read_line(fh: &mut FileHandle, max: Option<usize>) -> Option<Vec<u8>> {
    loop {
        if let Some(p) = fh.rbuf.iter().position(|&c| c == b'\n') {
            let take = match max {
                Some(m) if m < p + 1 => m,
                _ => p + 1,
            };
            let line: Vec<u8> = fh.rbuf.drain(..take).collect();
            return Some(line);
        }
        if let Some(m) = max {
            if fh.rbuf.len() >= m {
                let line: Vec<u8> = fh.rbuf.drain(..m).collect();
                return Some(line);
            }
        }
        if fh.eof {
            if fh.rbuf.is_empty() {
                return None;
            }
            return Some(std::mem::take(&mut fh.rbuf));
        }
        let want = fh.rbuf.len() + 1;
        fill_read(fh, want);
    }
}

fn f_fopen(it: &mut Interp, a: &mut Args) -> R<Value> {
    let path = a.str(it, 0)?;
    let mode = a.str(it, 1)?;
    let p = String::from_utf8_lossy(&path).to_string();
    let m = String::from_utf8_lossy(&mode).to_string();
    let stream = match p.as_str() {
        "php://stdin" => Stream::Stdin,
        "php://stdout" => Stream::Stdout,
        "php://stderr" => Stream::Stderr,
        "php://output" => Stream::Output,
        _ if p.starts_with("php://memory") || p.starts_with("php://temp") => Stream::Memory(Vec::new()),
        _ => {
            let mut o = std::fs::OpenOptions::new();
            let base = m.replace('b', "").replace('t', "");
            match base.as_str() {
                "r" => {
                    o.read(true);
                }
                "r+" => {
                    o.read(true).write(true);
                }
                "w" => {
                    o.write(true).create(true).truncate(true);
                }
                "w+" => {
                    o.read(true).write(true).create(true).truncate(true);
                }
                "a" => {
                    o.append(true).create(true);
                }
                "a+" => {
                    o.read(true).append(true).create(true);
                }
                "x" => {
                    o.write(true).create_new(true);
                }
                "x+" => {
                    o.read(true).write(true).create_new(true);
                }
                "c" => {
                    o.write(true).create(true);
                }
                "c+" => {
                    o.read(true).write(true).create(true);
                }
                _ => {
                    return Err(a.value_err(it, 1, "must be a valid mode"));
                }
            }
            match o.open(&p) {
                Ok(f) => Stream::File(f),
                Err(e) => {
                    let why = match e.kind() {
                        std::io::ErrorKind::NotFound => "No such file or directory",
                        std::io::ErrorKind::PermissionDenied => "Permission denied",
                        std::io::ErrorKind::AlreadyExists => "File exists",
                        _ => "Failed",
                    };
                    let msg = format!("fopen({}): Failed to open stream: {}", p, if std::path::Path::new(&p).is_dir() { "Is a directory" } else { why });
                    it.warn(&msg)?;
                    return Ok(Value::Bool(false));
                }
            }
        }
    };
    Ok(new_resource(it, stream, &m, &p, None))
}
fn f_fclose(it: &mut Interp, a: &mut Args) -> R<Value> {
    let fh = handle(it, a, 0)?;
    let mut f = fh.borrow_mut();
    if let Stream::File(file) = &mut f.stream {
        let _ = file.flush();
    }
    f.stream = Stream::Closed;
    Ok(Value::Bool(true))
}
fn f_fwrite(it: &mut Interp, a: &mut Args) -> R<Value> {
    let fh = handle(it, a, 0)?;
    let s = a.str(it, 1)?;
    let data = match a.opt_int(it, 2)? {
        Some(l) => &s[..(l.max(0) as usize).min(s.len())],
        None => &s[..],
    };
    if fh.borrow().mode.starts_with('r') && !fh.borrow().mode.contains('+') && !matches!(fh.borrow().stream, Stream::Stdout | Stream::Stderr | Stream::Output) {
        it.notice(&format!("fwrite(): Write of {} bytes failed with errno=9 Bad file descriptor", data.len()))?;
        return Ok(Value::Bool(false));
    }
    let n = write_handle(it, &fh, data)?;
    Ok(Value::Int(n))
}
fn f_fread(it: &mut Interp, a: &mut Args) -> R<Value> {
    let fh = handle(it, a, 0)?;
    let n = a.int(it, 1)?;
    if n <= 0 {
        return Err(a.value_err(it, 1, "must be greater than 0"));
    }
    let mut f = fh.borrow_mut();
    fill_read(&mut f, n as usize);
    let take = (n as usize).min(f.rbuf.len());
    let out: Vec<u8> = f.rbuf.drain(..take).collect();
    Ok(Value::vec(out))
}
fn f_fgets(it: &mut Interp, a: &mut Args) -> R<Value> {
    let fh = handle(it, a, 0)?;
    let max = a.opt_int(it, 1)?.map(|l| (l.max(1) - 1) as usize);
    if matches!(fh.borrow().stream, Stream::Stdin) {
        it.flush();
    }
    let mut f = fh.borrow_mut();
    Ok(match read_line(&mut f, max) {
        Some(l) => Value::vec(l),
        None => Value::Bool(false),
    })
}
fn f_fgetc(it: &mut Interp, a: &mut Args) -> R<Value> {
