fn f_fgetcsv(it: &mut Interp, a: &mut Args) -> R<Value> {
    let fh = handle(it, a, 0)?;
    let sep = a.str_or(it, 2, b",")?;
    let enc = a.str_or(it, 3, b"\"")?;
    let mut f = fh.borrow_mut();
    let mut line = match read_line(&mut f, None) {
        Some(l) => l,
        None => return Ok(Value::Bool(false)),
    };
    // handle multi-line quoted fields
    loop {
        let quotes = line.iter().filter(|&&c| c == enc[0]).count();
        if quotes % 2 == 0 {
            break;
        }
        match read_line(&mut f, None) {
            Some(l) => line.extend_from_slice(&l),
            None => break,
        }
    }
    Ok(Value::arr(super::string::parse_csv_line(&line, sep[0], enc[0], Some(b'\\'))))
}
pub fn csv_line(it: &mut Interp, fields: &PArray, sep: u8, enc: u8, eol: &[u8]) -> R<Vec<u8>> {
    let mut out = Vec::new();
    let mut first = true;
    for v in fields.values() {
        if !first {
            out.push(sep);
        }
        first = false;
        let s = it.to_str(&v.deref())?;
        let needs = s.iter().any(|&c| c == sep || c == enc || c == b'\n' || c == b'\r' || c == b'\t' || c == b' ' || c == b'\\');
        if needs {
            out.push(enc);
            for &c in s.iter() {
                if c == enc {
                    out.push(enc);
                }
                out.push(c);
            }
            out.push(enc);
        } else {
            out.extend_from_slice(&s);
        }
    }
    out.extend_from_slice(eol);
    Ok(out)
}
fn f_fputcsv(it: &mut Interp, a: &mut Args) -> R<Value> {
    let fh = handle(it, a, 0)?;
    let fields = a.arr(it, 1)?;
    let sep = a.str_or(it, 2, b",")?;
    let enc = a.str_or(it, 3, b"\"")?;
    let eol = a.str_or(it, 5, b"\n")?;
    let line = csv_line(it, &fields, sep[0], enc[0], &eol)?;
    let n = write_handle(it, &fh, &line)?;
    Ok(Value::Int(n))
}
