pub fn basename(p: &[u8], suffix: &[u8]) -> Vec<u8> {
    let mut end = p.len();
    while end > 0 && p[end - 1] == b'/' {
        end -= 1;
    }
    let s = &p[..end];
    let start = s.iter().rposition(|&c| c == b'/').map(|x| x + 1).unwrap_or(0);
    let mut b = s[start..].to_vec();
    if !suffix.is_empty() && b.len() > suffix.len() && b.ends_with(suffix) {
        b.truncate(b.len() - suffix.len());
    }
    b
}
pub fn dirname(p: &[u8], levels: usize) -> Vec<u8> {
    let mut cur = p.to_vec();
    for _ in 0..levels {
        let mut end = cur.len();
        while end > 1 && cur[end - 1] == b'/' {
            end -= 1;
        }
        let s = &cur[..end];
        match s.iter().rposition(|&c| c == b'/') {
            None => {
                cur = b".".to_vec();
            }
            Some(0) => {
                cur = b"/".to_vec();
            }
            Some(i) => {
                let mut e = i;
                while e > 1 && s[e - 1] == b'/' {
                    e -= 1;
                }
                cur = s[..e].to_vec();
            }
        }
    }
    cur
}
