        return Ok(Value::str(""));
    }
    Ok(Value::vec(dirname(&p, l as usize)))
}
fn f_pathinfo(it: &mut Interp, a: &mut Args) -> R<Value> {
    let p = a.str(it, 0)?;
    let opt = a.int_or(it, 1, 15)?;
    let mut out = PArray::new();
    let dir = dirname(&p, 1);
    let has_dir = p.contains(&b'/');
    if opt & 1 != 0 && has_dir {
        out.set(Key::Str(pstr("dirname")), Value::vec(dir));
    } else if opt & 1 != 0 && !p.is_empty() {
