            let mut i = 0;
            while i < set.len() {
                if i + 2 < set.len() && set[i + 1] == b'-' {
                    if s[0] >= set[i] && s[0] <= set[i + 2] {
                        m = true;
                    }
                    i += 3;
                } else {
                    if s[0] == set[i] {
                        m = true;
                    }
                    i += 1;
                }
            }
