pub fn sha512_generic(data: &[u8], init: [u64; 8], outlen: usize) -> Vec<u8> {
    let mut h = init;
    let mut msg = data.to_vec();
    let bitlen = (data.len() as u128).wrapping_mul(8);
    msg.push(0x80);
    while msg.len() % 128 != 112 {
        msg.push(0);
    }
    msg.extend_from_slice(&bitlen.to_be_bytes());
    for chunk in msg.chunks(128) {
        let mut w = [0u64; 80];
        for i in 0..16 {
            let mut b = [0u8; 8];
            b.copy_from_slice(&chunk[i * 8..i * 8 + 8]);
            w[i] = u64::from_be_bytes(b);
        }
        for i in 16..80 {
            let s0 = w[i - 15].rotate_right(1) ^ w[i - 15].rotate_right(8) ^ (w[i - 15] >> 7);
            let s1 = w[i - 2].rotate_right(19) ^ w[i - 2].rotate_right(61) ^ (w[i - 2] >> 6);
            w[i] = w[i - 16].wrapping_add(s0).wrapping_add(w[i - 7]).wrapping_add(s1);
        }
        let mut v = h;
        for i in 0..80 {
            let s1 = v[4].rotate_right(14) ^ v[4].rotate_right(18) ^ v[4].rotate_right(41);
            let ch = (v[4] & v[5]) ^ (!v[4] & v[6]);
            let t1 = v[7].wrapping_add(s1).wrapping_add(ch).wrapping_add(K512[i]).wrapping_add(w[i]);
            let s0 = v[0].rotate_right(28) ^ v[0].rotate_right(34) ^ v[0].rotate_right(39);
            let maj = (v[0] & v[1]) ^ (v[0] & v[2]) ^ (v[1] & v[2]);
            let t2 = s0.wrapping_add(maj);
            v[7] = v[6];
            v[6] = v[5];
            v[5] = v[4];
            v[4] = v[3].wrapping_add(t1);
            v[3] = v[2];
            v[2] = v[1];
            v[1] = v[0];
            v[0] = t1.wrapping_add(t2);
        }
        for i in 0..8 {
            h[i] = h[i].wrapping_add(v[i]);
        }
    }
    let mut out = Vec::new();
    for x in h.iter() {
        out.extend_from_slice(&x.to_be_bytes());
    }
    out.truncate(outlen);
    out
}
pub fn sha512(data: &[u8]) -> Vec<u8> {
    sha512_generic(data, [0x6a09e667f3bcc908, 0xbb67ae8584caa73b, 0x3c6ef372fe94f82b, 0xa54ff53a5f1d36f1, 0x510e527fade682d1, 0x9b05688c2b3e6c1f, 0x1f83d9abfb41bd6b, 0x5be0cd19137e2179], 64)
}
pub fn sha384(data: &[u8]) -> Vec<u8> {
    sha512_generic(data, [0xcbbb9d5dc1059ed8, 0x629a292a367cd507, 0x9159015a3070dd17, 0x152fecd8f70e5939, 0x67332667ffc00b31, 0x8eb44a8768581511, 0xdb0c2e0d64f98fa7, 0x47b5481dbefa4fa4], 48)
}

pub fn crc32_table(poly: u32) -> [u32; 256] {
    let mut t = [0u32; 256];
    for i in 0..256u32 {
        let mut c = i;
        for _ in 0..8 {
            c = if c & 1 != 0 { poly ^ (c >> 1) } else { c >> 1 };
        }
        t[i as usize] = c;
    }
    t
}
pub fn crc32b(data: &[u8]) -> u32 {
    thread_local! {
        static T: [u32; 256] = crc32_table(0xEDB88320);
    }
    T.with(|t| {
        let mut c = 0xFFFFFFFFu32;
        for &b in data {
            c = t[((c ^ b as u32) & 0xff) as usize] ^ (c >> 8);
        }
        c ^ 0xFFFFFFFF
    })
}
fn crc32c(data: &[u8]) -> u32 {
    let t = crc32_table(0x82F63B78);
    let mut c = 0xFFFFFFFFu32;
    for &b in data {
        c = t[((c ^ b as u32) & 0xff) as usize] ^ (c >> 8);
    }
    c ^ 0xFFFFFFFF
}
fn crc32_bzip(data: &[u8]) -> u32 {
    // "crc32" in php hash = bzip2 crc (MSB-first, poly 0x04C11DB7), output byte-swapped
    let mut t = [0u32; 256];
    for i in 0..256u32 {
        let mut c = i << 24;
        for _ in 0..8 {
            c = if c & 0x80000000 != 0 { (c << 1) ^ 0x04C11DB7 } else { c << 1 };
        }
        t[i as usize] = c;
    }
    let mut c = 0xFFFFFFFFu32;
    for &b in data {
        c = (c << 8) ^ t[(((c >> 24) ^ b as u32) & 0xff) as usize];
    }
    let r = c ^ 0xFFFFFFFF;
    r.swap_bytes()
}

pub fn hex(b: &[u8]) -> Vec<u8> {
    let mut s = Vec::with_capacity(b.len() * 2);
    for c in b {
        s.extend_from_slice(format!("{:02x}", c).as_bytes());
    }
    s
}

pub fn do_hash(algo: &str, data: &[u8]) -> Option<Vec<u8>> {
    Some(match algo {
        "md5" => md5(data).to_vec(),
        "sha1" => sha1(data).to_vec(),
        "sha256" => sha256(data),
        "sha224" => sha224(data),
        "sha512" => sha512(data),
        "sha384" => sha384(data),
        "sha512/256" => sha512_generic(data, [0x22312194FC2BF72C, 0x9F555FA3C84C64C2, 0x2393B86B6F53B151, 0x963877195940EABD, 0x96283EE2A88EFFE3, 0xBE5E1E2553863992, 0x2B0199FC2C85B8AA, 0x0EB72DDC81C52CA2], 32),
        "sha512/224" => sha512_generic(data, [0x8C3D37C819544DA2, 0x73E1996689DCD4D6, 0x1DFAB7AE32FF9C82, 0x679DD514582F9FCF, 0x0F6D2B697BD44DA8, 0x77E36F7304C48942, 0x3F9D85A86A1D36C8, 0x1112E6AD91D692A1], 28),
        "crc32b" => crc32b(data).to_be_bytes().to_vec(),
        "crc32c" => crc32c(data).to_be_bytes().to_vec(),
        "crc32" => crc32_bzip(data).to_be_bytes().to_vec(),
        "adler32" => {
            let mut a: u32 = 1;
            let mut b: u32 = 0;
            for &c in data {
                a = (a + c as u32) % 65521;
                b = (b + a) % 65521;
            }
            ((b << 16) | a).to_be_bytes().to_vec()
        }
        "fnv132" | "fnv1a32" => {
            let mut h: u32 = 0x811c9dc5;
            for &c in data {
                if algo == "fnv132" {
                    h = h.wrapping_mul(0x01000193);
                    h ^= c as u32;
                } else {
                    h ^= c as u32;
                    h = h.wrapping_mul(0x01000193);
                }
            }
            h.to_be_bytes().to_vec()
        }
        "fnv164" | "fnv1a64" => {
            let mut h: u64 = 0xcbf29ce484222325;
            for &c in data {
                if algo == "fnv164" {
                    h = h.wrapping_mul(0x100000001b3);
                    h ^= c as u64;
                } else {
                    h ^= c as u64;
                    h = h.wrapping_mul(0x100000001b3);
                }
            }
            h.to_be_bytes().to_vec()
        }
        "joaat" => {
            let mut h: u32 = 0;
            for &c in data {
                h = h.wrapping_add(c as u32);
                h = h.wrapping_add(h << 10);
                h ^= h >> 6;
            }
            h = h.wrapping_add(h << 3);
            h ^= h >> 11;
            h = h.wrapping_add(h << 15);
            h.to_be_bytes().to_vec()
        }
        _ => return None,
    })
}

fn block_size(algo: &str) -> usize {
    match algo {
        "sha512" | "sha384" | "sha512/256" | "sha512/224" => 128,
        _ => 64,
    }
}

pub fn hmac(algo: &str, key: &[u8], data: &[u8]) -> Option<Vec<u8>> {
    let bs = block_size(algo);
    let mut k = if key.len() > bs { do_hash(algo, key)? } else { key.to_vec() };
    k.resize(bs, 0);
    let mut ipad: Vec<u8> = k.iter().map(|b| b ^ 0x36).collect();
    let mut opad: Vec<u8> = k.iter().map(|b| b ^ 0x5c).collect();
    ipad.extend_from_slice(data);
    let inner = do_hash(algo, &ipad)?;
    opad.extend_from_slice(&inner);
    do_hash(algo, &opad)
}

fn f_md5(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let raw = a.bool_or(it, 1, false)?;
    let h = md5(&s);
    Ok(Value::vec(if raw { h.to_vec() } else { hex(&h) }))
}
fn f_sha1(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let raw = a.bool_or(it, 1, false)?;
    let h = sha1(&s);
    Ok(Value::vec(if raw { h.to_vec() } else { hex(&h) }))
}
fn f_crc32(it: &mut Interp, a: &mut Args) -> R<Value> {
