    Ok(Value::Int(crc32b(&s) as i64))
}
fn f_md5_file(it: &mut Interp, a: &mut Args) -> R<Value> {
    let p = a.str(it, 0)?;
    match std::fs::read(String::from_utf8_lossy(&p).as_ref()) {
        Ok(d) => Ok(Value::vec(hex(&md5(&d)))),
        Err(_) => Ok(Value::Bool(false)),
    }
}
fn f_sha1_file(it: &mut Interp, a: &mut Args) -> R<Value> {
    let p = a.str(it, 0)?;
    match std::fs::read(String::from_utf8_lossy(&p).as_ref()) {
