    }
}
fn f_hash(it: &mut Interp, a: &mut Args) -> R<Value> {
    let algo = a.str(it, 0)?;
    let al = String::from_utf8_lossy(&algo).to_ascii_lowercase();
    let s = a.str(it, 1)?;
    let raw = a.bool_or(it, 2, false)?;
    match do_hash(&al, &s) {
        Some(h) => Ok(Value::vec(if raw { h } else { hex(&h) })),
        None => Err(a.value_err(it, 0, "must be a valid hashing algorithm")),
    }
}
fn f_hash_file(it: &mut Interp, a: &mut Args) -> R<Value> {
    let algo = a.str(it, 0)?;
    let al = String::from_utf8_lossy(&algo).to_ascii_lowercase();
    let p = a.str(it, 1)?;
    let raw = a.bool_or(it, 2, false)?;
    let d = match std::fs::read(String::from_utf8_lossy(&p).as_ref()) {
        Ok(d) => d,
        Err(_) => return Ok(Value::Bool(false)),
    };
    match do_hash(&al, &d) {
        Some(h) => Ok(Value::vec(if raw { h } else { hex(&h) })),
        None => Err(a.value_err(it, 0, "must be a valid hashing algorithm")),
    }
}
fn f_hash_hmac(it: &mut Interp, a: &mut Args) -> R<Value> {
    let algo = a.str(it, 0)?;
    let al = String::from_utf8_lossy(&algo).to_ascii_lowercase();
    let s = a.str(it, 1)?;
    let k = a.str(it, 2)?;
    let raw = a.bool_or(it, 3, false)?;
    match hmac(&al, &k, &s) {
        Some(h) => Ok(Value::vec(if raw { h } else { hex(&h) })),
        None => Err(a.value_err(it, 0, "must be a valid cryptographic hashing algorithm")),
    }
}
fn f_hash_algos(_it: &mut Interp, _a: &mut Args) -> R<Value> {
    let l = ["md5", "sha1", "sha224", "sha256", "sha384", "sha512/224", "sha512/256", "sha512", "adler32", "crc32", "crc32b", "crc32c", "fnv132", "fnv1a32", "fnv164", "fnv1a64", "joaat"];
    Ok(Value::arr(PArray::from_values(l.iter().map(|s| Value::str(s)).collect())))
}
fn f_hash_equals(it: &mut Interp, a: &mut Args) -> R<Value> {
    let x = match a.get(0) {
        Value::Str(s) => s,
        other => {
            let msg = format!("hash_equals(): Argument #1 ($known_string) must be of type string, {} given", other.type_name());
            return Err(it.type_error(&msg));
        }
    };
    let y = match a.get(1) {
        Value::Str(s) => s,
        other => {
            let msg = format!("hash_equals(): Argument #2 ($user_string) must be of type string, {} given", other.type_name());
            return Err(it.type_error(&msg));
        }
    };
    Ok(Value::Bool(x == y))
}
fn f_password_hash(it: &mut Interp, a: &mut Args) -> R<Value> {
    let p = a.str(it, 0)?;
    let salt = super::rand::os_random_bytes(16);
    let h = hex(&sha256(&[&salt[..], &p[..]].concat()));
    let mut out = b"$2y$10$".to_vec();
    out.extend_from_slice(&super::misc::base64_encode(&salt)[..22]);
    out.extend_from_slice(&h[..31]);
    Ok(Value::vec(out))
}
fn f_password_verify(it: &mut Interp, a: &mut Args) -> R<Value> {
    let p = a.str(it, 0)?;
    let h = a.str(it, 1)?;
    if h.len() != 60 || !h.starts_with(b"$2y$10$") {
        return Ok(Value::Bool(false));
    }
    let salt_b64 = &h[7..29];
    let mut padded = salt_b64.to_vec();
    padded.extend_from_slice(b"==");
    let salt = super::misc::base64_decode(&padded, false).unwrap_or_default();
    let salt = &salt[..16.min(salt.len())];
    let hh = hex(&sha256(&[salt, &p[..]].concat()));
    Ok(Value::Bool(&hh[..31] == &h[29..]))
}
fn f_password_get_info(it: &mut Interp, a: &mut Args) -> R<Value> {
    let h = a.str(it, 0)?;
    let mut out = crate::array::PArray::new();
    let is_b = h.starts_with(b"$2y$");
    out.set(crate::array::Key::Str(pstr("algo")), if is_b { Value::str("2y") } else { Value::Null });
    out.set(crate::array::Key::Str(pstr("algoName")), Value::str(if is_b { "bcrypt" } else { "unknown" }));
    let mut opts = crate::array::PArray::new();
    if is_b {
        opts.set(crate::array::Key::Str(pstr("cost")), Value::Int(10));
    }
    out.set(crate::array::Key::Str(pstr("options")), Value::arr(opts));
    Ok(Value::arr(out))
}
fn f_password_needs_rehash(_it: &mut Interp, _a: &mut Args) -> R<Value> {
    Ok(Value::Bool(false))
}

pub fn register(it: &mut Interp) {
    reg(it, "md5", "string,binary?", f_md5);
    reg(it, "sha1", "string,binary?", f_sha1);
    reg(it, "crc32", "string", f_crc32);
    reg(it, "md5_file", "filename,binary?", f_md5_file);
    reg(it, "sha1_file", "filename,binary?", f_sha1_file);
    reg(it, "hash", "algo,data,binary?,options?", f_hash);
    reg(it, "hash_file", "algo,filename,binary?,options?", f_hash_file);
    reg(it, "hash_hmac", "algo,data,key,binary?", f_hash_hmac);
    reg(it, "hash_algos", "", f_hash_algos);
    reg(it, "hash_hmac_algos", "", f_hash_algos);
    reg(it, "hash_equals", "known_string,user_string", f_hash_equals);
    reg(it, "password_hash", "password,algo,options?", f_password_hash);
    reg(it, "password_verify", "password,hash", f_password_verify);
    reg(it, "password_get_info", "hash", f_password_get_info);
    reg(it, "password_needs_rehash", "hash,algo,options?", f_password_needs_rehash);
}
