        Some(h) => Ok(Value::vec(if raw { h } else { hex(&h) })),
        None => Err(a.value_err(it, 0, "must be a valid hashing algorithm")),
    }
}
fn f_hash_file(it: &mut Interp, a: &mut Args) -> R<Value> {
    let algo = a.str(it, 0)?;
    let al = String::from_utf8_lossy(&algo).to_ascii_lowercase();
    let p = a.str(it, 1)?;
    let raw = a.bool_or(it, 2, false)?;
    let d = match std::fs::read(String::from_utf8_lossy(&p).as_ref()) {
        Ok(d) => d,
        Err(_) => return Ok(Value::Bool(false)),
    };
    match do_hash(&al, &d) {
        Some(h) => Ok(Value::vec(if raw { h } else { hex(&h) })),
        None => Err(a.value_err(it, 0, "must be a valid hashing algorithm")),
    }
}
fn f_hash_hmac(it: &mut Interp, a: &mut Args) -> R<Value> {
    let algo = a.str(it, 0)?;
    let al = String::from_utf8_lossy(&algo).to_ascii_lowercase();
    let s = a.str(it, 1)?;
    let k = a.str(it, 2)?;
    let raw = a.bool_or(it, 3, false)?;
    match hmac(&al, &k, &s) {
        Some(h) => Ok(Value::vec(if raw { h } else { hex(&h) })),
        None => Err(a.value_err(it, 0, "must be a valid cryptographic hashing algorithm")),
    }
}
fn f_hash_algos(_it: &mut Interp, _a: &mut Args) -> R<Value> {
    let l = ["md5", "sha1", "sha224", "sha256", "sha384", "sha512/224", "sha512/256", "sha512", "adler32", "crc32", "crc32b", "crc32c", "fnv132", "fnv1a32", "fnv164", "fnv1a64", "joaat"];
