fn f_password_hash(it: &mut Interp, a: &mut Args) -> R<Value> {
    let p = a.str(it, 0)?;
    let salt = super::rand::os_random_bytes(16);
    let h = hex(&sha256(&[&salt[..], &p[..]].concat()));
    let mut out = b"$2y$10$".to_vec();
    out.extend_from_slice(&super::misc::base64_encode(&salt)[..22]);
    out.extend_from_slice(&h[..31]);
    Ok(Value::vec(out))
