fn f_password_verify(it: &mut Interp, a: &mut Args) -> R<Value> {
    let p = a.str(it, 0)?;
    let h = a.str(it, 1)?;
    if h.len() != 60 || !h.starts_with(b"$2y$10$") {
        return Ok(Value::Bool(false));
    }
    let salt_b64 = &h[7..29];
    let mut padded = salt_b64.to_vec();
    padded.extend_from_slice(b"==");
    let salt = super::misc::base64_decode(&padded, false).unwrap_or_default();
    let salt = &salt[..16.min(salt.len())];
    let hh = hex(&sha256(&[salt, &p[..]].concat()));
