// Backtracking regex engine with PCRE-like semantics.

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Prop {
    Letter,
    Upper,
    Lower,
    Number,
    Digit,
    Punct,
    Space,
    Symbol,
    Mark,
    Other,
    Any,
    Han,
    Latin,
    Greek,
    Cyrillic,
    Arabic,
    Hebrew,
}

#[derive(Clone, Debug)]
pub struct ClassSet {
    bits: [u64; 4],
    ranges: Vec<(u32, u32)>,
    props: Vec<(Prop, bool)>,
    neg: bool,
}

impl ClassSet {
    fn new() -> ClassSet {
        ClassSet { bits: [0; 4], ranges: Vec::new(), props: Vec::new(), neg: false }
    }
    fn add_byte(&mut self, b: u8) {
        self.bits[(b >> 6) as usize] |= 1u64 << (b & 63);
    }
    fn add_range(&mut self, lo: u32, hi: u32, utf8: bool) {
        let top = if utf8 { 127 } else { 255 };
        let mut c = lo;
        while c <= hi && c <= top {
            self.add_byte(c as u8);
            c += 1;
        }
        if hi > top {
            self.ranges.push((lo.max(top + 1), hi));
        }
    }
    #[inline]
    fn has_byte(&self, b: u8) -> bool {
        self.bits[(b >> 6) as usize] & (1u64 << (b & 63)) != 0
    }
    fn matches(&self, c: u32, utf8: bool) -> bool {
        let r = if c < 128 || (!utf8 && c < 256) {
            self.has_byte(c as u8) || (utf8 && self.props.iter().any(|(p, n)| prop_match(*p, c) != *n))
        } else {
            self.ranges.iter().any(|&(lo, hi)| c >= lo && c <= hi) || self.props.iter().any(|(p, n)| prop_match(*p, c) != *n)
        };
        r != self.neg
    }
}

fn prop_match(p: Prop, c: u32) -> bool {
    let ch = match char::from_u32(c) {
        Some(ch) => ch,
        None => return false,
    };
    match p {
        Prop::Letter => ch.is_alphabetic(),
        Prop::Upper => ch.is_uppercase(),
        Prop::Lower => ch.is_lowercase(),
        Prop::Number => ch.is_numeric(),
        Prop::Digit => ch.is_numeric() && (ch.is_ascii_digit() || ch.to_digit(10).is_some() || (c >= 0x660 && c <= 0x669) || (c >= 0x6F0 && c <= 0x6F9) || (c >= 0x966 && c <= 0x96F) || (c >= 0xFF10 && c <= 0xFF19)),
        Prop::Punct => {
            if c < 128 {
                ch.is_ascii_punctuation() && !"$+<=>^`|~".contains(ch)
            } else {
                matches!(c, 0xA1 | 0xA7 | 0xAB | 0xB6 | 0xB7 | 0xBB | 0xBF | 0x2010..=0x2027 | 0x2030..=0x205E | 0x3001..=0x3003 | 0x3008..=0x3011 | 0xFF01..=0xFF0F)
            }
        }
        Prop::Space => ch.is_whitespace(),
        Prop::Symbol => {
            if c < 128 {
                "$+<=>^`|~".contains(ch)
            } else {
                !ch.is_alphanumeric() && !ch.is_whitespace() && !ch.is_control() && !prop_match(Prop::Punct, c) && !prop_match(Prop::Mark, c)
            }
        }
        Prop::Mark => (0x300..=0x36F).contains(&c) || (0x1AB0..=0x1AFF).contains(&c) || (0x1DC0..=0x1DFF).contains(&c) || (0x20D0..=0x20FF).contains(&c) || (0xFE20..=0xFE2F).contains(&c),
        Prop::Other => ch.is_control(),
        Prop::Any => true,
        Prop::Han => (0x4E00..=0x9FFF).contains(&c) || (0x3400..=0x4DBF).contains(&c) || (0x20000..=0x2A6DF).contains(&c) || (0xF900..=0xFAFF).contains(&c),
        Prop::Latin => ch.is_ascii_alphabetic() || (0xC0..=0x24F).contains(&c) && c != 0xD7 && c != 0xF7 || (0x1E00..=0x1EFF).contains(&c),
        Prop::Greek => (0x370..=0x3FF).contains(&c) || (0x1F00..=0x1FFF).contains(&c),
        Prop::Cyrillic => (0x400..=0x52F).contains(&c),
        Prop::Arabic => (0x600..=0x6FF).contains(&c) || (0x750..=0x77F).contains(&c),
        Prop::Hebrew => (0x590..=0x5FF).contains(&c),
    }
}

#[derive(Clone, Debug)]
enum Node {
    Empty,
    Char(u32, bool), // char, caseless
    Any(bool),       // dotall
    Class(Box<ClassSet>),
    Bol(bool),       // multiline
    Eol(bool, bool), // multiline, dollar_endonly
    StartText,
    EndText,
    EndTextNL,
    WordB(bool),
    StartMatch, // \G
    Group(Box<Node>, Option<usize>),
    Concat(Vec<Node>),
    Alt(Vec<Node>),
    Repeat(Box<Node>, u32, Option<u32>, bool, bool), // node,min,max,greedy,possessive
    Backref(usize, bool),
    NamedBackref(String, bool),
    Look(Box<Node>, bool, bool), // ahead, neg
    Atomic(Box<Node>),
    Recurse(usize),
    Cond(Box<CondKind>, Box<Node>, Box<Node>),
    Keep,
    Fail,
}

#[derive(Clone, Debug)]
enum CondKind {
    Group(usize),
    Named(String),
    Look(Node),
}

#[derive(Clone, Debug)]
enum Inst {
    Byte(u8),
    ByteIC(u8),
    Bytes(Vec<u8>),
    Any(bool),
    Class(Box<ClassSet>),
    Split(usize, usize),
    Jmp(usize),
    Save(usize),
    Bol(bool),
    Eol(bool, bool),
    StartText,
    EndText,
    EndTextNL,
    WordB(bool),
    StartMatch,
    Backref(usize, bool),
    Look(Box<Prog>, bool, bool, Option<usize>),
    Atomic(Box<Prog>),
    SetMark(usize),
    IfProgress(usize, usize),
    Recurse(usize),
    CondGroup(usize, usize), // group, else-target
    CondLook(Box<Prog>, bool, bool, usize),
    Keep,
    Fail,
    Match,
}

#[derive(Clone, Debug)]
pub struct Prog {
    insts: Vec<Inst>,
}

pub struct Regex {
    prog: Prog,
    pub ncaps: usize,
    pub names: Vec<(String, usize)>,
    pub anchored: bool,
    pub utf8: bool,
    nmarks: usize,
    first_byte: Option<u8>,
    groups: Vec<Node>, // for recursion
    group_progs: Vec<Option<Prog>>,
    pub dollar_endonly: bool,
}

pub struct CompileError {
    pub msg: String,
    pub offset: usize,
}

struct Parser<'a> {
    p: &'a [u8],
    i: usize,
    caseless: bool,
    multiline: bool,
    dotall: bool,
    extended: bool,
    ungreedy: bool,
    dollar_endonly: bool,
    utf8: bool,
    no_auto_capture: bool,
    ncaps: usize,
    names: Vec<(String, usize)>,
    group_nodes: Vec<(usize, Node)>,
}

fn err<T>(msg: &str, offset: usize) -> Result<T, CompileError> {
    Err(CompileError { msg: msg.to_string(), offset })
}

impl<'a> Parser<'a> {
    fn peek(&self) -> Option<u8> {
        self.p.get(self.i).copied()
    }
    fn skip_ext(&mut self) {
        if !self.extended {
            return;
        }
        loop {
            match self.peek() {
                Some(c) if c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' || c == 0x0b || c == 0x0c => self.i += 1,
                Some(b'#') => {
                    while let Some(c) = self.peek() {
                        self.i += 1;
                        if c == b'\n' {
                            break;
                        }
                    }
                }
                _ => break,
            }
        }
    }
    fn parse_alt(&mut self) -> Result<Node, CompileError> {
        let mut alts = vec![self.parse_concat()?];
        while self.peek() == Some(b'|') {
            self.i += 1;
            alts.push(self.parse_concat()?);
        }
        if alts.len() == 1 {
            Ok(alts.pop().unwrap())
        } else {
            Ok(Node::Alt(alts))
        }
    }
    fn parse_concat(&mut self) -> Result<Node, CompileError> {
        let mut items = Vec::new();
        loop {
            self.skip_ext();
            match self.peek() {
                None | Some(b'|') | Some(b')') => break,
                _ => {}
            }
            let atom = self.parse_atom()?;
            let atom = match atom {
                Some(a) => a,
                None => continue,
            };
            let q = self.parse_quant(atom)?;
            items.push(q);
        }
        if items.len() == 1 {
            Ok(items.pop().unwrap())
        } else if items.is_empty() {
            Ok(Node::Empty)
        } else {
            Ok(Node::Concat(items))
        }
    }
    fn parse_quant(&mut self, atom: Node) -> Result<Node, CompileError> {
        let mut atom = atom;
        loop {
            self.skip_ext();
            let (min, max) = match self.peek() {
                Some(b'*') => {
                    self.i += 1;
                    (0, None)
                }
                Some(b'+') => {
                    self.i += 1;
                    (1, None)
                }
                Some(b'?') => {
                    self.i += 1;
                    (0, Some(1))
                }
                Some(b'{') => {
                    // {n}, {n,}, {n,m}
                    let save = self.i;
                    self.i += 1;
                    let mut n = String::new();
                    while let Some(c) = self.peek() {
                        if c.is_ascii_digit() {
                            n.push(c as char);
                            self.i += 1;
                        } else {
                            break;
                        }
                    }
                    let mut m: Option<String> = None;
                    if self.peek() == Some(b',') {
                        self.i += 1;
                        let mut ms = String::new();
                        while let Some(c) = self.peek() {
                            if c.is_ascii_digit() {
                                ms.push(c as char);
                                self.i += 1;
                            } else {
                                break;
                            }
                        }
                        m = Some(ms);
                    }
                    if self.peek() != Some(b'}') || (n.is_empty() && m.as_ref().map(|x| x.is_empty()).unwrap_or(true)) {
                        self.i = save;
                        return Ok(atom);
                    }
                    self.i += 1;
                    let lo: u32 = if n.is_empty() { 0 } else { n.parse().unwrap_or(0) };
                    let hi = match m {
                        None => Some(lo),
                        Some(ms) if ms.is_empty() => None,
                        Some(ms) => Some(ms.parse().unwrap_or(0)),
                    };
                    if let Some(h) = hi {
                        if h < lo {
                            return err("numbers out of order in {} quantifier", self.i - 1);
                        }
                    }
                    (lo, hi)
                }
                _ => return Ok(atom),
            };
            if matches!(atom, Node::Bol(_) | Node::Eol(..) | Node::WordB(_) | Node::StartText | Node::EndText) {
                // quantifier on assertion: allowed in PCRE (treated as optional)
            }
            let mut greedy = !self.ungreedy;
            let mut possessive = false;
            if self.peek() == Some(b'?') {
                self.i += 1;
                greedy = !greedy;
            } else if self.peek() == Some(b'+') {
                self.i += 1;
                possessive = true;
            }
            atom = Node::Repeat(Box::new(atom), min, max, greedy, possessive);
        }
    }
    fn lit(&self, c: u32) -> Node {
        Node::Char(c, self.caseless)
    }
    fn read_char_utf8(&mut self) -> u32 {
        let c = self.p[self.i];
        if self.utf8 && c >= 0x80 {
            let (cp, len) = crate::builtins::json::utf8_decode_at(self.p, self.i);
            self.i += len;
            cp
        } else {
            self.i += 1;
            c as u32
        }
    }
    fn parse_atom(&mut self) -> Result<Option<Node>, CompileError> {
        let c = self.peek().unwrap();
        match c {
            b'(' => {
                self.i += 1;
                self.parse_group().map(Some)
            }
            b'[' => {
                self.i += 1;
                let cs = self.parse_class()?;
                Ok(Some(Node::Class(Box::new(cs))))
            }
            b'.' => {
                self.i += 1;
                Ok(Some(Node::Any(self.dotall)))
            }
            b'^' => {
                self.i += 1;
                Ok(Some(Node::Bol(self.multiline)))
            }
            b'$' => {
                self.i += 1;
                Ok(Some(Node::Eol(self.multiline, self.dollar_endonly)))
            }
            b'\\' => {
                self.i += 1;
                self.parse_escape().map(Some)
            }
            b'*' | b'+' | b'?' => err("quantifier does not follow a repeatable item", self.i),
            b'{' => {
                // literal { unless valid quantifier
                self.i += 1;
                Ok(Some(self.lit(b'{' as u32)))
            }
            _ => {
                let cp = self.read_char_utf8();
                Ok(Some(self.lit(cp)))
            }
        }
    }
    fn parse_group(&mut self) -> Result<Node, CompileError> {
        let start = self.i;
        if self.peek() == Some(b'?') {
            self.i += 1;
            let c = self.peek();
            match c {
                Some(b':') => {
                    self.i += 1;
                    let n = self.parse_group_body()?;
                    return Ok(Node::Group(Box::new(n), None));
                }
                Some(b'=') | Some(b'!') => {
                    self.i += 1;
                    let n = self.parse_group_body()?;
                    return Ok(Node::Look(Box::new(n), true, c == Some(b'!')));
                }
                Some(b'>') => {
                    self.i += 1;
                    let n = self.parse_group_body()?;
                    return Ok(Node::Atomic(Box::new(n)));
                }
                Some(b'|') => {
                    // branch reset: approximate as non-capturing
                    self.i += 1;
                    let n = self.parse_group_body()?;
                    return Ok(Node::Group(Box::new(n), None));
                }
                Some(b'#') => {
                    while let Some(c) = self.peek() {
                        self.i += 1;
                        if c == b')' {
                            break;
                        }
                    }
                    return Ok(Node::Empty);
                }
                Some(b'<') if matches!(self.p.get(self.i + 1), Some(b'=') | Some(b'!')) => {
                    let neg = self.p[self.i + 1] == b'!';
                    self.i += 2;
                    let n = self.parse_group_body()?;
                    return Ok(Node::Look(Box::new(n), false, neg));
                }
                Some(b'P') | Some(b'<') | Some(b'\'') => {
                    if c == Some(b'P') {
                        self.i += 1;
                        if self.peek() == Some(b'=') {
                            // (?P=name)
                            self.i += 1;
                            let name = self.read_name(b')')?;
                            return Ok(Node::NamedBackref(name, self.caseless));
                        }
                        if self.peek() == Some(b'>') {
                            self.i += 1;
                            let name = self.read_name(b')')?;
                            let idx = self.names.iter().find(|(n, _)| *n == name).map(|x| x.1).unwrap_or(0);
                            return Ok(Node::Recurse(idx));
                        }
                    }
                    let close = if self.peek() == Some(b'\'') { b'\'' } else { b'>' };
                    self.i += 1;
                    let name = self.read_name(close)?;
                    self.ncaps += 1;
                    let idx = self.ncaps;
                    self.names.push((name, idx));
                    let n = self.parse_group_body()?;
                    self.group_nodes.push((idx, n.clone()));
                    return Ok(Node::Group(Box::new(n), Some(idx)));
                }
                Some(b'R') | Some(b'0'..=b'9') | Some(b'+') | Some(b'-') if c != Some(b'-') || matches!(self.p.get(self.i + 1), Some(b'0'..=b'9')) => {
                    let mut num = String::new();
                    if c == Some(b'R') {
                        self.i += 1;
                        num.push('0');
                    } else {
                        let sign = if c == Some(b'+') || c == Some(b'-') {
                            self.i += 1;
                            Some(c.unwrap())
                        } else {
                            None
                        };
                        while let Some(d) = self.peek() {
                            if d.is_ascii_digit() {
                                num.push(d as char);
                                self.i += 1;
                            } else {
                                break;
                            }
                        }
                        let n: usize = num.parse().unwrap_or(0);
                        let n = match sign {
                            Some(b'+') => self.ncaps + n,
                            Some(b'-') => self.ncaps + 1 - n,
                            _ => n,
                        };
                        num = n.to_string();
                    }
                    if self.peek() != Some(b')') {
                        return err("(?R (recursive pattern call) must be followed by )", self.i);
                    }
                    self.i += 1;
                    return Ok(Node::Recurse(num.parse().unwrap_or(0)));
                }
                Some(b'&') => {
                    self.i += 1;
                    let name = self.read_name(b')')?;
                    let idx = self.names.iter().find(|(n, _)| *n == name).map(|x| x.1).unwrap_or(0);
                    return Ok(Node::Recurse(idx));
                }
                Some(b'(') => {
                    // conditional
                    self.i += 1;
                    let cond = if self.peek().map(|c| c.is_ascii_digit()).unwrap_or(false) {
                        let mut num = String::new();
                        while let Some(d) = self.peek() {
                            if d.is_ascii_digit() {
                                num.push(d as char);
                                self.i += 1;
                            } else {
                                break;
                            }
                        }
                        if self.peek() != Some(b')') {
                            return err("malformed number or name after (?(", self.i);
                        }
                        self.i += 1;
                        CondKind::Group(num.parse().unwrap_or(0))
                    } else if self.peek() == Some(b'?') {
                        self.i += 1;
                        let ahead;
                        let neg;
                        match self.peek() {
                            Some(b'=') => {
                                ahead = true;
                                neg = false;
                                self.i += 1;
                            }
                            Some(b'!') => {
                                ahead = true;
                                neg = true;
                                self.i += 1;
                            }
                            Some(b'<') => {
                                ahead = false;
                                neg = self.p.get(self.i + 1) == Some(&b'!');
                                self.i += 2;
                            }
                            _ => return err("assertion expected after (?(", self.i),
                        }
                        let n = self.parse_group_body()?;
                        CondKind::Look(Node::Look(Box::new(n), ahead, neg))
                    } else {
                        let close = if self.peek() == Some(b'<') {
                            self.i += 1;
                            b'>'
                        } else if self.peek() == Some(b'\'') {
                            self.i += 1;
                            b'\''
                        } else {
                            b')'
                        };
                        let name = self.read_name(close)?;
                        if close != b')' {
                            if self.peek() != Some(b')') {
                                return err("malformed conditional", self.i);
                            }
                            self.i += 1;
                        }
                        CondKind::Named(name)
                    };
                    let body = self.parse_alt()?;
                    if self.peek() != Some(b')') {
                        return err("missing closing parenthesis", self.p.len());
                    }
                    self.i += 1;
                    let (yes, no) = match body {
                        Node::Alt(mut v) => {
                            if v.len() > 2 {
                                return err("conditional subpattern contains more than two branches", self.i);
                            }
                            let no = if v.len() == 2 { v.pop().unwrap() } else { Node::Empty };
                            (v.pop().unwrap(), no)
                        }
                        n => (n, Node::Empty),
                    };
                    return Ok(Node::Cond(Box::new(cond), Box::new(yes), Box::new(no)));
                }
                _ => {
                    // inline flags (?imsxU-imsx) or (?i:...)
                    let mut on = true;
                    let saved = (self.caseless, self.multiline, self.dotall, self.extended, self.ungreedy, self.no_auto_capture);
                    loop {
                        match self.peek() {
                            Some(b'i') => self.caseless = on,
                            Some(b'm') => self.multiline = on,
                            Some(b's') => self.dotall = on,
                            Some(b'x') => self.extended = on,
                            Some(b'U') => self.ungreedy = on,
                            Some(b'n') => self.no_auto_capture = on,
                            Some(b'J') => {}
                            Some(b'-') => on = false,
                            Some(b')') => {
                                self.i += 1;
                                // flags apply to rest of enclosing group
                                return Ok(Node::Empty);
                            }
                            Some(b':') => {
                                self.i += 1;
                                let n = self.parse_group_body()?;
                                self.caseless = saved.0;
                                self.multiline = saved.1;
                                self.dotall = saved.2;
                                self.extended = saved.3;
                                self.ungreedy = saved.4;
                                self.no_auto_capture = saved.5;
                                return Ok(Node::Group(Box::new(n), None));
                            }
                            _ => return err("unrecognized character after (? or (?-", self.i),
                        }
                        self.i += 1;
                    }
                }
            }
        }
        let _ = start;
        if self.no_auto_capture {
            let n = self.parse_group_body()?;
            return Ok(Node::Group(Box::new(n), None));
        }
        self.ncaps += 1;
        let idx = self.ncaps;
        let n = self.parse_group_body()?;
        self.group_nodes.push((idx, n.clone()));
        Ok(Node::Group(Box::new(n), Some(idx)))
    }
    fn parse_group_body(&mut self) -> Result<Node, CompileError> {
        let saved = (self.caseless, self.multiline, self.dotall, self.extended, self.ungreedy, self.no_auto_capture);
        let n = self.parse_alt()?;
        self.caseless = saved.0;
        self.multiline = saved.1;
        self.dotall = saved.2;
        self.extended = saved.3;
        self.ungreedy = saved.4;
        self.no_auto_capture = saved.5;
        if self.peek() != Some(b')') {
            return err("missing closing parenthesis", self.p.len());
        }
        self.i += 1;
        Ok(n)
    }
    fn read_name(&mut self, close: u8) -> Result<String, CompileError> {
        let st = self.i;
        while let Some(c) = self.peek() {
            if c == close {
                let name = String::from_utf8_lossy(&self.p[st..self.i]).to_string();
                self.i += 1;
                if name.is_empty() {
                    return err("subpattern name expected", self.i);
                }
                return Ok(name);
            }
            if !(c.is_ascii_alphanumeric() || c == b'_') {
                return err("syntax error in subpattern name (missing terminator?)", self.i);
            }
            self.i += 1;
        }
        err("syntax error in subpattern name (missing terminator?)", self.i)
    }
    fn class_escape(&mut self, c: u8, cs: &mut ClassSet) -> Option<u32> {
        // returns literal codepoint, or None if a class shorthand added
        match c {
            b'd' => {
                cs.add_range(b'0' as u32, b'9' as u32, self.utf8);
                None
            }
            b'D' => {
                let mut t = ClassSet::new();
                t.add_range(b'0' as u32, b'9' as u32, false);
                add_negated(cs, &t, self.utf8);
                None
            }
            b'w' => {
                add_word(cs, self.utf8);
                None
            }
            b'W' => {
                let mut t = ClassSet::new();
                add_word(&mut t, false);
                add_negated(cs, &t, self.utf8);
                None
            }
            b's' => {
                for b in [b' ', b'\t', b'\n', b'\r', 0x0b, 0x0c] {
                    cs.add_byte(b);
                }
                None
            }
            b'S' => {
                let mut t = ClassSet::new();
                for b in [b' ', b'\t', b'\n', b'\r', 0x0b, 0x0c] {
                    t.add_byte(b);
                }
                add_negated(cs, &t, self.utf8);
                None
            }
            b'h' => {
                cs.add_byte(b' ');
                cs.add_byte(b'\t');
                if self.utf8 {
                    cs.ranges.push((0xA0, 0xA0));
                } else {
                    cs.add_byte(0xA0);
                }
                None
            }
            b'v' => {
                for b in [b'\n', 0x0b, 0x0c, b'\r'] {
                    cs.add_byte(b);
                }
                None
            }
            b'n' => Some(b'\n' as u32),
            b't' => Some(b'\t' as u32),
            b'r' => Some(b'\r' as u32),
            b'f' => Some(0x0c),
            b'e' => Some(0x1b),
            b'a' => Some(0x07),
            b'b' => Some(0x08),
            _ => Some(c as u32),
        }
    }
    fn parse_hex_escape(&mut self) -> u32 {
        // after \x
        if self.peek() == Some(b'{') {
            self.i += 1;
            let st = self.i;
            while let Some(c) = self.peek() {
                if c == b'}' {
                    break;
                }
                self.i += 1;
            }
            let v = u32::from_str_radix(&String::from_utf8_lossy(&self.p[st..self.i]), 16).unwrap_or(0);
            self.i += 1;
            return v;
        }
        let mut v = 0;
        let mut n = 0;
        while n < 2 {
            match self.peek() {
                Some(c) if c.is_ascii_hexdigit() => {
                    v = v * 16 + (c as char).to_digit(16).unwrap();
                    self.i += 1;
                    n += 1;
                }
                _ => break,
            }
        }
        v
    }
    fn parse_prop(&mut self) -> Result<(Prop, bool), CompileError> {
        // after \p or \P
        let mut neg = false;
        let name = if self.peek() == Some(b'{') {
            self.i += 1;
            if self.peek() == Some(b'^') {
                neg = true;
                self.i += 1;
            }
            let st = self.i;
            while let Some(c) = self.peek() {
                if c == b'}' {
                    break;
                }
                self.i += 1;
            }
            let n = String::from_utf8_lossy(&self.p[st..self.i]).to_string();
            self.i += 1;
            n
        } else {
            let c = self.peek().unwrap_or(b'L');
            self.i += 1;
            (c as char).to_string()
        };
        let p = match name.as_str() {
            "L" | "L&" | "Lo" | "Lm" | "Lt" => Prop::Letter,
            "Lu" => Prop::Upper,
            "Ll" => Prop::Lower,
            "N" | "No" | "Nl" => Prop::Number,
            "Nd" => Prop::Digit,
            "P" | "Pc" | "Pd" | "Ps" | "Pe" | "Pi" | "Pf" | "Po" => Prop::Punct,
            "Z" | "Zs" | "Zl" | "Zp" | "Xsp" | "Xps" => Prop::Space,
            "S" | "Sm" | "Sc" | "Sk" | "So" => Prop::Symbol,
            "M" | "Mn" | "Mc" | "Me" => Prop::Mark,
            "C" | "Cc" | "Cf" | "Co" | "Cn" | "Cs" => Prop::Other,
            "Any" | "Xan" | "Xwd" => Prop::Any,
            "Han" => Prop::Han,
            "Latin" => Prop::Latin,
            "Greek" => Prop::Greek,
            "Cyrillic" => Prop::Cyrillic,
            "Arabic" => Prop::Arabic,
            "Hebrew" => Prop::Hebrew,
            _ => return err("unknown property name after \\P or \\p", self.i),
        };
        Ok((p, neg))
    }
    fn parse_escape(&mut self) -> Result<Node, CompileError> {
        let c = match self.peek() {
            Some(c) => c,
            None => return err("\\ at end of pattern", self.i),
        };
        self.i += 1;
        Ok(match c {
            b'd' | b'D' | b'w' | b'W' | b's' | b'S' | b'h' | b'v' => {
                let mut cs = ClassSet::new();
                self.class_escape(c, &mut cs);
                Node::Class(Box::new(cs))
            }
            b'H' | b'V' => {
                let mut t = ClassSet::new();
                self.class_escape(c.to_ascii_lowercase(), &mut t);
                let mut cs = ClassSet::new();
                add_negated(&mut cs, &t, self.utf8);
                Node::Class(Box::new(cs))
            }
            b'R' => {
                // newline sequence: \r\n | [\n\v\f\r]
                let mut cs = ClassSet::new();
                for b in [b'\n', 0x0b, 0x0c, b'\r'] {
                    cs.add_byte(b);
                }
                Node::Atomic(Box::new(Node::Alt(vec![Node::Concat(vec![Node::Char(b'\r' as u32, false), Node::Char(b'\n' as u32, false)]), Node::Class(Box::new(cs))])))
            }
            b'p' | b'P' => {
                let (p, mut neg) = self.parse_prop()?;
                if c == b'P' {
                    neg = !neg;
                }
                let mut cs = ClassSet::new();
                cs.props.push((p, false));
                cs.neg = neg;
                Node::Class(Box::new(cs))
            }
            b'X' => {
                // extended grapheme cluster approx: any char followed by marks
                let mut m = ClassSet::new();
                m.props.push((Prop::Mark, false));
                Node::Atomic(Box::new(Node::Concat(vec![Node::Any(true), Node::Repeat(Box::new(Node::Class(Box::new(m))), 0, None, true, false)])))
            }
            b'b' => Node::WordB(true),
            b'B' => Node::WordB(false),
            b'A' => Node::StartText,
            b'z' => Node::EndText,
            b'Z' => Node::EndTextNL,
            b'G' => Node::StartMatch,
            b'K' => Node::Keep,
            b'Q' => {
                let st = self.i;
                let mut en = self.p.len();
                let mut j = self.i;
                while j + 1 < self.p.len() {
                    if self.p[j] == b'\\' && self.p[j + 1] == b'E' {
                        en = j;
                        break;
                    }
                    j += 1;
                }
                let lit = self.p[st..en].to_vec();
                self.i = if en < self.p.len() { en + 2 } else { en };
                let mut v: Vec<Node> = Vec::new();
                let mut k = 0;
                while k < lit.len() {
                    if self.utf8 && lit[k] >= 0x80 {
                        let (cp, l) = crate::builtins::json::utf8_decode_at(&lit, k);
                        v.push(self.lit(cp));
                        k += l;
                    } else {
                        v.push(self.lit(lit[k] as u32));
                        k += 1;
                    }
                }
                Node::Concat(v)
            }
            b'E' => Node::Empty,
            b'x' => {
                let v = self.parse_hex_escape();
                self.lit(v)
            }
            b'o' if self.peek() == Some(b'{') => {
                self.i += 1;
                let st = self.i;
                while self.peek().map(|c| c != b'}').unwrap_or(false) {
                    self.i += 1;
                }
                let v = u32::from_str_radix(&String::from_utf8_lossy(&self.p[st..self.i]), 8).unwrap_or(0);
                self.i += 1;
                self.lit(v)
            }
            b'c' => {
                let ch = self.peek().unwrap_or(b'@');
                self.i += 1;
                self.lit((ch.to_ascii_uppercase() ^ 0x40) as u32)
            }
            b'0' => {
                let mut v = 0u32;
                let mut n = 0;
                while n < 2 {
                    match self.peek() {
                        Some(d) if (b'0'..=b'7').contains(&d) => {
                            v = v * 8 + (d - b'0') as u32;
                            self.i += 1;
                            n += 1;
                        }
                        _ => break,
                    }
                }
                self.lit(v)
            }
            b'1'..=b'9' => {
                let st = self.i - 1;
                let mut j = st;
                while j < self.p.len() && self.p[j].is_ascii_digit() {
                    j += 1;
                }
                let num: usize = String::from_utf8_lossy(&self.p[st..j]).parse().unwrap_or(0);
                if num < 10 || num <= self.ncaps {
                    self.i = j;
                    Node::Backref(num, self.caseless)
                } else {
                    // octal
                    let mut v = 0u32;
                    let mut n = 0;
                    self.i = st;
                    while n < 3 {
                        match self.peek() {
                            Some(d) if (b'0'..=b'7').contains(&d) => {
                                v = v * 8 + (d - b'0') as u32;
                                self.i += 1;
                                n += 1;
                            }
                            _ => break,
                        }
                    }
                    self.lit(v)
                }
            }
            b'g' => {
                // \g{n} \gn \g{-n} \g{name} \g<name> (recursion)
                if self.peek() == Some(b'<') || self.peek() == Some(b'\'') {
                    let close = if self.peek() == Some(b'<') { b'>' } else { b'\'' };
                    self.i += 1;
                    let name = self.read_name(close)?;
                    if let Ok(n) = name.parse::<usize>() {
                        return Ok(Node::Recurse(n));
                    }
                    let idx = self.names.iter().find(|(n, _)| *n == name).map(|x| x.1).unwrap_or(0);
                    return Ok(Node::Recurse(idx));
                }
                let braced = self.peek() == Some(b'{');
                if braced {
                    self.i += 1;
                }
                let st = self.i;
                while let Some(c) = self.peek() {
                    if (braced && c == b'}') || (!braced && !(c.is_ascii_digit() || c == b'-')) {
                        break;
                    }
                    self.i += 1;
                }
                let s = String::from_utf8_lossy(&self.p[st..self.i]).to_string();
                if braced {
                    self.i += 1;
                }
                if let Ok(n) = s.parse::<i64>() {
                    let idx = if n < 0 { (self.ncaps as i64 + 1 + n) as usize } else { n as usize };
                    Node::Backref(idx, self.caseless)
                } else {
                    Node::NamedBackref(s, self.caseless)
                }
            }
            b'k' => {
                let close = match self.peek() {
                    Some(b'<') => b'>',
                    Some(b'\'') => b'\'',
                    Some(b'{') => b'}',
                    _ => return err("\\k is not followed by a braced, angle-bracketed, or quoted name", self.i),
                };
                self.i += 1;
                let name = self.read_name(close)?;
                Node::NamedBackref(name, self.caseless)
            }
            b'n' => self.lit(b'\n' as u32),
            b't' => self.lit(b'\t' as u32),
            b'r' => self.lit(b'\r' as u32),
            b'f' => self.lit(0x0c),
            b'e' => self.lit(0x1b),
            b'a' => self.lit(0x07),
            c if c.is_ascii_alphanumeric() => {
                return err("unrecognized character follows \\", self.i - 1);
            }
            _ => {
                self.i -= 1;
                let cp = self.read_char_utf8();
                self.lit(cp)
            }
        })
    }
    fn parse_class(&mut self) -> Result<ClassSet, CompileError> {
        let mut cs = ClassSet::new();
        let start = self.i;
        if self.peek() == Some(b'^') {
            cs.neg = true;
            self.i += 1;
        }
        let mut first = true;
        loop {
            let c = match self.peek() {
                Some(c) => c,
                None => return err("missing terminating ] for character class", self.p.len()),
            };
            if c == b']' && !first {
                self.i += 1;
                break;
            }
            first = false;
            // posix class
            if c == b'[' && matches!(self.p.get(self.i + 1), Some(b':')) {
                if let Some(end) = self.p[self.i + 2..].windows(2).position(|w| w == b":]") {
                    let name = String::from_utf8_lossy(&self.p[self.i + 2..self.i + 2 + end]).to_string();
                    let (neg, name) = match name.strip_prefix('^') {
                        Some(n) => (true, n.to_string()),
                        None => (false, name),
                    };
                    let mut t = ClassSet::new();
                    let ok = posix_class(&name, &mut t);
                    if !ok {
                        return err("unknown POSIX class name", self.i);
                    }
                    if neg {
                        add_negated(&mut cs, &t, self.utf8);
                    } else {
                        for i in 0..4 {
                            cs.bits[i] |= t.bits[i];
                        }
                    }
                    self.i += 2 + end + 2;
                    continue;
                }
            }
            let lo: u32;
            if c == b'\\' {
                self.i += 1;
                let e = match self.peek() {
                    Some(e) => e,
                    None => return err("\\ at end of pattern", self.i),
                };
                self.i += 1;
                match e {
                    b'x' => lo = self.parse_hex_escape(),
                    b'p' | b'P' => {
                        let (p, mut neg) = self.parse_prop()?;
                        if e == b'P' {
                            neg = !neg;
                        }
                        cs.props.push((p, neg));
                        continue;
                    }
                    b'0'..=b'7' => {
                        let mut v = (e - b'0') as u32;
                        let mut n = 1;
                        while n < 3 {
                            match self.peek() {
                                Some(d) if (b'0'..=b'7').contains(&d) => {
                                    v = v * 8 + (d - b'0') as u32;
                                    self.i += 1;
                                    n += 1;
                                }
                                _ => break,
                            }
                        }
                        lo = v;
                    }
                    _ => match self.class_escape(e, &mut cs) {
                        Some(l) => lo = l,
                        None => continue,
                    },
                }
            } else {
                lo = self.read_char_utf8();
            }
            // range?
            if self.peek() == Some(b'-') && self.p.get(self.i + 1).map(|&x| x != b']').unwrap_or(false) {
                let save = self.i;
                self.i += 1;
                let hc = self.peek().unwrap();
                let hi: Option<u32> = if hc == b'\\' {
                    self.i += 1;
                    let e = self.peek().unwrap_or(0);
                    self.i += 1;
                    match e {
                        b'x' => Some(self.parse_hex_escape()),
                        b'd' | b'w' | b's' | b'D' | b'W' | b'S' => {
                            // not a range: treat '-' literally
                            self.i = save;
                            None
                        }
                        b'n' => Some(10),
                        b't' => Some(9),
                        b'r' => Some(13),
                        _ => Some(e as u32),
                    }
                } else if hc == b'[' && self.p.get(self.i + 1) == Some(&b':') {
                    self.i = save;
                    None
                } else {
                    Some(self.read_char_utf8())
                };
                if let Some(hi) = hi {
                    if hi < lo {
                        return err("range out of order in character class", self.i - 1);
                    }
                    self.add_class_range(&mut cs, lo, hi);
                    continue;
                }
            }
            self.add_class_range(&mut cs, lo, lo);
        }
        let _ = start;
        Ok(cs)
    }
    fn add_class_range(&self, cs: &mut ClassSet, lo: u32, hi: u32) {
        cs.add_range(lo, hi, self.utf8);
        if self.caseless {
            for c in lo..=hi.min(lo + 2000) {
                if c < 128 {
                    let b = c as u8;
                    if b.is_ascii_alphabetic() {
                        cs.add_byte(b.to_ascii_lowercase());
                        cs.add_byte(b.to_ascii_uppercase());
                    }
                } else if self.utf8 {
                    if let Some(ch) = char::from_u32(c) {
                        for l in ch.to_lowercase().chain(ch.to_uppercase()) {
                            let lc = l as u32;
                            if lc >= 128 {
                                cs.ranges.push((lc, lc));
                            } else {
                                cs.add_byte(lc as u8);
                            }
                        }
                    }
                }
            }
        }
    }
}

fn add_word(cs: &mut ClassSet, _utf8: bool) {
    for c in b'a'..=b'z' {
        cs.add_byte(c);
    }
    for c in b'A'..=b'Z' {
        cs.add_byte(c);
    }
    for c in b'0'..=b'9' {
        cs.add_byte(c);
    }
    cs.add_byte(b'_');
}

fn add_negated(cs: &mut ClassSet, t: &ClassSet, utf8: bool) {
    let top = if utf8 { 128 } else { 256 };
    for b in 0..top {
        if !t.has_byte(b as u8) {
            cs.add_byte(b as u8);
        }
    }
    if utf8 {
        cs.ranges.push((128, 0x10FFFF));
    }
}

fn posix_class(name: &str, t: &mut ClassSet) -> bool {
    let f: fn(u8) -> bool = match name {
        "alpha" => |c| c.is_ascii_alphabetic(),
        "digit" => |c| c.is_ascii_digit(),
        "alnum" => |c| c.is_ascii_alphanumeric(),
        "upper" => |c| c.is_ascii_uppercase(),
        "lower" => |c| c.is_ascii_lowercase(),
        "space" => |c| matches!(c, b' ' | b'\t' | b'\n' | b'\r' | 0x0b | 0x0c),
        "blank" => |c| c == b' ' || c == b'\t',
        "punct" => |c| c.is_ascii_punctuation(),
        "xdigit" => |c| c.is_ascii_hexdigit(),
        "word" => |c| c.is_ascii_alphanumeric() || c == b'_',
        "cntrl" => |c| c < 32 || c == 127,
        "print" => |c| (32..127).contains(&c),
        "graph" => |c| (33..127).contains(&c),
        "ascii" => |c| c < 128,
        _ => return false,
    };
    for b in 0..=255u8 {
        if f(b) {
            t.add_byte(b);
        }
    }
    true
}

// ---------------- compiler ----------------
struct Compiler {
    insts: Vec<Inst>,
    nmarks: usize,
    utf8: bool,
    names: Vec<(String, usize)>,
}

impl Compiler {
    fn emit(&mut self, i: Inst) -> usize {
        self.insts.push(i);
        self.insts.len() - 1
    }
    fn compile_sub(&mut self, n: &Node) -> Prog {
        let mut c = Compiler { insts: Vec::new(), nmarks: self.nmarks, utf8: self.utf8, names: self.names.clone() };
        c.compile(n);
        c.emit(Inst::Match);
        self.nmarks = c.nmarks;
        Prog { insts: c.insts }
    }
    fn compile(&mut self, n: &Node) {
        match n {
            Node::Empty => {}
            Node::Char(c, ic) => {
                let c = *c;
                if c < 128 || (!self.utf8 && c < 256) {
                    let b = c as u8;
                    if *ic && b.is_ascii_alphabetic() {
                        self.emit(Inst::ByteIC(b.to_ascii_lowercase()));
                    } else {
                        self.emit(Inst::Byte(b));
                    }
                } else if self.utf8 {
                    if *ic {
                        let mut cs = ClassSet::new();
                        if let Some(ch) = char::from_u32(c) {
                            for l in std::iter::once(ch).chain(ch.to_lowercase()).chain(ch.to_uppercase()) {
                                cs.ranges.push((l as u32, l as u32));
                            }
                        }
                        self.emit(Inst::Class(Box::new(cs)));
                    } else {
                        let mut v = Vec::new();
                        crate::lexer::encode_utf8(c, &mut v);
                        self.emit(Inst::Bytes(v));
                    }
                } else {
                    self.emit(Inst::Byte((c & 0xff) as u8));
                }
            }
            Node::Any(dotall) => {
                self.emit(Inst::Any(*dotall));
            }
            Node::Class(cs) => {
                self.emit(Inst::Class(cs.clone()));
            }
            Node::Bol(m) => {
                self.emit(Inst::Bol(*m));
            }
            Node::Eol(m, d) => {
                self.emit(Inst::Eol(*m, *d));
            }
            Node::StartText => {
                self.emit(Inst::StartText);
            }
            Node::EndText => {
                self.emit(Inst::EndText);
            }
            Node::EndTextNL => {
                self.emit(Inst::EndTextNL);
            }
            Node::WordB(b) => {
                self.emit(Inst::WordB(*b));
            }
            Node::StartMatch => {
                self.emit(Inst::StartMatch);
            }
            Node::Keep => {
                self.emit(Inst::Keep);
            }
            Node::Fail => {
                self.emit(Inst::Fail);
            }
            Node::Group(inner, cap) => match cap {
                Some(i) => {
                    self.emit(Inst::Save(i * 2));
                    self.compile(inner);
                    self.emit(Inst::Save(i * 2 + 1));
                }
                None => self.compile(inner),
            },
            Node::Concat(v) => {
                // merge consecutive literal bytes
                for x in v {
                    self.compile(x);
                }
            }
            Node::Alt(v) => {
                let mut jumps = Vec::new();
                for (i, x) in v.iter().enumerate() {
                    if i < v.len() - 1 {
                        let sp = self.emit(Inst::Split(0, 0));
                        self.compile(x);
                        jumps.push(self.emit(Inst::Jmp(0)));
                        let next = self.insts.len();
                        self.insts[sp] = Inst::Split(sp + 1, next);
                    } else {
                        self.compile(x);
                    }
                }
                let end = self.insts.len();
                for j in jumps {
                    self.insts[j] = Inst::Jmp(end);
                }
            }
            Node::Repeat(inner, min, max, greedy, possessive) => {
                if *possessive {
                    let sub = Node::Repeat(inner.clone(), *min, *max, *greedy, false);
                    let p = self.compile_sub(&sub);
                    self.emit(Inst::Atomic(Box::new(p)));
                    return;
                }
                let min = *min;
                for _ in 0..min {
                    self.compile(inner);
                }
                match max {
                    None => {
                        // star loop with progress check
                        let mark = self.nmarks;
                        self.nmarks += 1;
                        let l1 = self.emit(Inst::Split(0, 0));
                        self.emit(Inst::SetMark(mark));
                        self.compile(inner);
                        self.emit(Inst::IfProgress(mark, l1));
                        let l3 = self.insts.len();
                        self.insts[l1] = if *greedy { Inst::Split(l1 + 1, l3) } else { Inst::Split(l3, l1 + 1) };
                    }
                    Some(mx) => {
                        let opt = mx.saturating_sub(min);
                        let mut splits = Vec::new();
                        for _ in 0..opt {
                            let sp = self.emit(Inst::Split(0, 0));
                            splits.push(sp);
                            self.compile(inner);
                        }
                        let end = self.insts.len();
                        for sp in splits {
                            self.insts[sp] = if *greedy { Inst::Split(sp + 1, end) } else { Inst::Split(end, sp + 1) };
                        }
                    }
                }
            }
            Node::Backref(i, ic) => {
                self.emit(Inst::Backref(*i, *ic));
            }
            Node::NamedBackref(name, ic) => {
                let idx = self.names.iter().find(|(n, _)| n == name).map(|x| x.1).unwrap_or(0);
                self.emit(Inst::Backref(idx, *ic));
            }
            Node::Look(inner, ahead, neg) => {
                let len = if *ahead { None } else { fixed_len(inner) };
                let p = self.compile_sub(inner);
                self.emit(Inst::Look(Box::new(p), *ahead, *neg, len));
            }
            Node::Atomic(inner) => {
                let p = self.compile_sub(inner);
                self.emit(Inst::Atomic(Box::new(p)));
            }
            Node::Recurse(i) => {
                self.emit(Inst::Recurse(*i));
            }
            Node::Cond(kind, yes, no) => {
                match &**kind {
                    CondKind::Group(g) | CondKind::Named(_) if true => {
                        let g = match &**kind {
                            CondKind::Group(g) => *g,
                            CondKind::Named(n) => self.names.iter().find(|(x, _)| x == n).map(|x| x.1).unwrap_or(0),
                            _ => 0,
                        };
                        let c = self.emit(Inst::CondGroup(g, 0));
                        self.compile(yes);
                        let j = self.emit(Inst::Jmp(0));
                        let else_t = self.insts.len();
                        self.compile(no);
                        let end = self.insts.len();
                        self.insts[c] = Inst::CondGroup(g, else_t);
                        self.insts[j] = Inst::Jmp(end);
                    }
                    CondKind::Look(Node::Look(inner, ahead, neg)) => {
                        let p = self.compile_sub(inner);
                        let c = self.emit(Inst::CondLook(Box::new(p), *ahead, *neg, 0));
                        self.compile(yes);
                        let j = self.emit(Inst::Jmp(0));
                        let else_t = self.insts.len();
                        self.compile(no);
                        let end = self.insts.len();
                        if let Inst::CondLook(p, a, n, _) = std::mem::replace(&mut self.insts[c], Inst::Fail) {
                            self.insts[c] = Inst::CondLook(p, a, n, else_t);
                        }
                        self.insts[j] = Inst::Jmp(end);
                    }
                    _ => {}
                }
            }
        }
    }
}

fn fixed_len(n: &Node) -> Option<usize> {
    match n {
        Node::Empty | Node::Bol(_) | Node::Eol(..) | Node::WordB(_) | Node::StartText | Node::EndText | Node::EndTextNL | Node::Look(..) | Node::StartMatch => Some(0),
        Node::Char(c, _) => {
            if *c < 128 {
                Some(1)
            } else {
                None
            }
        }
        Node::Any(_) | Node::Class(_) => None,
        Node::Group(i, _) | Node::Atomic(i) => fixed_len(i),
        Node::Concat(v) => {
            let mut t = 0;
            for x in v {
                t += fixed_len(x)?;
            }
            Some(t)
        }
        Node::Alt(v) => {
            let f = fixed_len(&v[0])?;
            for x in &v[1..] {
                if fixed_len(x)? != f {
                    return None;
                }
            }
            Some(f)
        }
        Node::Repeat(i, mn, Some(mx), _, _) if mn == mx => Some(fixed_len(i)? * *mn as usize),
        _ => None,
    }
}

fn first_byte(n: &Node) -> Option<u8> {
    match n {
        Node::Char(c, false) if *c < 128 => Some(*c as u8),
        Node::Group(i, _) | Node::Atomic(i) => first_byte(i),
        Node::Concat(v) => {
            for x in v {
                match x {
                    Node::Empty => continue,
                    _ => return first_byte(x),
                }
            }
            None
        }
        Node::Repeat(i, mn, _, _, _) if *mn > 0 => first_byte(i),
        _ => None,
    }
}

pub struct Flags {
    pub caseless: bool,
    pub multiline: bool,
    pub dotall: bool,
    pub extended: bool,
    pub ungreedy: bool,
    pub anchored: bool,
    pub dollar_endonly: bool,
    pub utf8: bool,
    pub no_auto_capture: bool,
}

impl Regex {
    pub fn new(pat: &[u8], f: &Flags) -> Result<Regex, CompileError> {
        // pre-scan for named groups (forward references)
        let mut p = Parser {
            p: pat,
            i: 0,
            caseless: f.caseless,
            multiline: f.multiline,
            dotall: f.dotall,
            extended: f.extended,
            ungreedy: f.ungreedy,
            dollar_endonly: f.dollar_endonly,
            utf8: f.utf8,
            no_auto_capture: f.no_auto_capture,
            ncaps: 0,
            names: Vec::new(),
            group_nodes: Vec::new(),
        };
        let node = p.parse_alt()?;
        if p.i < pat.len() {
            return err("unmatched closing parenthesis", p.i);
        }
        if f.utf8 && std::str::from_utf8(pat).is_err() {
            return err("UTF-8 error: isolated byte with 0x80 bit set", 0);
        }
        let mut c = Compiler { insts: Vec::new(), nmarks: 0, utf8: f.utf8, names: p.names.clone() };
        c.emit(Inst::Save(0));
        c.compile(&node);
        c.emit(Inst::Save(1));
        c.emit(Inst::Match);
        let ncaps = p.ncaps;
        let mut groups: Vec<Node> = vec![Node::Empty; ncaps + 1];
        groups[0] = node.clone();
        for (i, n) in p.group_nodes.iter() {
            groups[*i] = n.clone();
        }
        // check backrefs
        let fb = first_byte(&node);
        let mut r = Regex {
            prog: Prog { insts: c.insts },
            ncaps,
            names: p.names,
            anchored: f.anchored,
            utf8: f.utf8,
            nmarks: c.nmarks,
            first_byte: fb,
            groups,
            group_progs: Vec::new(),
            dollar_endonly: f.dollar_endonly,
        };
        // compile recursion targets
        let mut gp = Vec::new();
        for (i, g) in r.groups.iter().enumerate() {
            let mut c2 = Compiler { insts: Vec::new(), nmarks: r.nmarks, utf8: f.utf8, names: r.names.clone() };
            if i > 0 {
                c2.emit(Inst::Save(i * 2));
            }
            c2.compile(g);
            if i > 0 {
                c2.emit(Inst::Save(i * 2 + 1));
            }
            c2.emit(Inst::Match);
            r.nmarks = c2.nmarks;
            gp.push(Some(Prog { insts: c2.insts }));
        }
        r.group_progs = gp;
        Ok(r)
    }

    /// try to match starting exactly at `start`; returns capture slots
    pub fn match_here(&self, s: &[u8], start: usize, search_start: usize, notempty: bool, steps: &mut usize) -> Result<Option<Vec<Option<usize>>>, ()> {
        let nslots = (self.ncaps + 1) * 2;
        let mut slots = vec![None; nslots];
        let mut marks = vec![usize::MAX; self.nmarks.max(1)];
        let mut vm = Vm { re: self, s, slots: &mut slots, marks: &mut marks, steps, search_start, depth: 0, keep: None };
        match vm.run(&self.prog, 0, start, notempty) {
            Err(()) => Err(()),
            Ok(Some(_)) => {
                if let Some(k) = vm.keep {
                    slots[0] = Some(k);
                }
                Ok(Some(slots))
            }
            Ok(None) => Ok(None),
        }
    }

    /// search from `from`; returns captures (byte offsets)
    pub fn search(&self, s: &[u8], from: usize, notempty_atstart: bool, steps: &mut usize) -> Result<Option<Vec<Option<usize>>>, ()> {
        let mut pos = from;
        loop {
            if pos > s.len() {
                return Ok(None);
            }
            if let Some(fb) = self.first_byte {
                if !self.anchored {
                    match s[pos..].iter().position(|&c| c == fb) {
                        Some(p) => pos += p,
                        None => return Ok(None),
                    }
                }
            }
            let ne = notempty_atstart && pos == from;
            match self.match_here(s, pos, from, ne, steps)? {
                Some(m) => return Ok(Some(m)),
                None => {}
            }
            if self.anchored {
                return Ok(None);
            }
            if pos >= s.len() {
                return Ok(None);
            }
            // advance one char
            pos += if self.utf8 { utf8_len(s[pos]) } else { 1 };
        }
    }
}

pub fn utf8_len(b: u8) -> usize {
    if b < 0x80 {
        1
    } else if b & 0xE0 == 0xC0 {
        2
    } else if b & 0xF0 == 0xE0 {
        3
    } else if b & 0xF8 == 0xF0 {
        4
    } else {
        1
    }
}

enum Bt {
    Branch(usize, usize),
    Slot(usize, Option<usize>),
    Mark(usize, usize),
}

struct Vm<'a> {
    re: &'a Regex,
    s: &'a [u8],
    slots: &'a mut Vec<Option<usize>>,
    marks: &'a mut Vec<usize>,
    steps: &'a mut usize,
    search_start: usize,
    depth: usize,
    keep: Option<usize>,
}

const STEP_LIMIT: usize = 100_000_000;

#[inline]
fn is_word(c: u8) -> bool {
    c.is_ascii_alphanumeric() || c == b'_'
}

impl<'a> Vm<'a> {
    fn decode(&self, pos: usize) -> (u32, usize) {
        let c = self.s[pos];
        if self.re.utf8 && c >= 0x80 {
            crate::builtins::json::utf8_decode_at(self.s, pos)
        } else {
            (c as u32, 1)
        }
    }

    /// run program; returns Some(end_pos) on match
    fn run(&mut self, prog: &Prog, pc0: usize, pos0: usize, notempty: bool) -> Result<Option<usize>, ()> {
        let mut stack: Vec<Bt> = Vec::new();
        let mut pc = pc0;
        let mut pos = pos0;
        let s = self.s;
        let n = s.len();
        let insts = &prog.insts;
        let start_pos = pos0;
        loop {
            *self.steps += 1;
            if *self.steps > STEP_LIMIT {
                return Err(());
            }
            let ok: bool = match &insts[pc] {
                Inst::Byte(b) => {
                    if pos < n && s[pos] == *b {
                        pos += 1;
                        pc += 1;
                        true
                    } else {
                        false
                    }
                }
                Inst::ByteIC(b) => {
                    if pos < n && s[pos].to_ascii_lowercase() == *b {
                        pos += 1;
                        pc += 1;
                        true
                    } else {
                        false
                    }
                }
                Inst::Bytes(v) => {
                    if pos + v.len() <= n && &s[pos..pos + v.len()] == &v[..] {
                        pos += v.len();
                        pc += 1;
                        true
                    } else {
                        false
                    }
                }
                Inst::Any(dotall) => {
                    if pos < n && (*dotall || s[pos] != b'\n') {
                        pos += if self.re.utf8 { utf8_len(s[pos]).min(n - pos) } else { 1 };
                        pc += 1;
                        true
                    } else {
                        false
                    }
                }
                Inst::Class(cs) => {
                    if pos < n {
                        let (c, l) = self.decode(pos);
                        if cs.matches(c, self.re.utf8) {
                            pos += l;
                            pc += 1;
                            true
                        } else {
                            false
                        }
                    } else {
                        false
                    }
                }
                Inst::Split(a, b) => {
                    stack.push(Bt::Branch(*b, pos));
                    pc = *a;
                    true
                }
                Inst::Jmp(t) => {
                    pc = *t;
                    true
                }
                Inst::Save(i) => {
                    let i = *i;
                    if i < self.slots.len() {
                        stack.push(Bt::Slot(i, self.slots[i]));
                        self.slots[i] = Some(pos);
                    }
                    pc += 1;
                    true
                }
                Inst::SetMark(k) => {
                    stack.push(Bt::Mark(*k, self.marks[*k]));
                    self.marks[*k] = pos;
                    pc += 1;
                    true
                }
                Inst::IfProgress(k, t) => {
                    if pos != self.marks[*k] {
                        pc = *t;
                    } else {
                        pc += 1;
                    }
                    true
                }
                Inst::Bol(m) => {
                    if pos == 0 || (*m && s[pos - 1] == b'\n') {
                        pc += 1;
                        true
                    } else {
                        false
                    }
                }
                Inst::Eol(m, d) => {
                    let ok = if *m {
                        pos == n || s[pos] == b'\n'
                    } else if *d {
                        pos == n
                    } else {
                        pos == n || (pos == n - 1 && s[pos] == b'\n')
                    };
                    if ok {
                        pc += 1;
                    }
                    ok
                }
                Inst::StartText => {
                    if pos == 0 {
                        pc += 1;
                        true
                    } else {
                        false
                    }
                }
                Inst::EndText => {
                    if pos == n {
                        pc += 1;
                        true
                    } else {
                        false
                    }
                }
                Inst::EndTextNL => {
                    if pos == n || (pos == n - 1 && s[pos] == b'\n') {
                        pc += 1;
                        true
                    } else {
                        false
                    }
                }
                Inst::StartMatch => {
                    if pos == self.search_start {
                        pc += 1;
                        true
                    } else {
                        false
                    }
                }
                Inst::WordB(want) => {
                    let a = pos > 0 && is_word(s[pos - 1]);
                    let b = pos < n && is_word(s[pos]);
                    if (a != b) == *want {
                        pc += 1;
                        true
                    } else {
                        false
                    }
                }
                Inst::Backref(g, ic) => {
                    let (st, en) = (self.slots.get(g * 2).copied().flatten(), self.slots.get(g * 2 + 1).copied().flatten());
                    match (st, en) {
                        (Some(a), Some(b)) if b >= a => {
                            let l = b - a;
                            if pos + l <= n && (if *ic { s[a..b].eq_ignore_ascii_case(&s[pos..pos + l]) } else { s[a..b] == s[pos..pos + l] }) {
                                pos += l;
                                pc += 1;
                                true
                            } else {
                                false
                            }
                        }
                        _ => false,
                    }
                }
                Inst::Look(sub, ahead, neg, len) => {
                    let found = if *ahead {
                        self.sub_match(sub, pos)?.is_some()
                    } else {
                        let mut f = false;
                        match len {
                            Some(l) => {
                                if pos >= *l {
                                    if let Some(e) = self.sub_match(sub, pos - l)? {
                                        f = e == pos;
                                    }
                                }
                            }
                            None => {
                                let mut st = pos as isize;
                                while st >= 0 {
                                    if let Some(e) = self.sub_match_end(sub, st as usize, pos)? {
                                        if e == pos {
                                            f = true;
                                            break;
                                        }
                                    }
                                    st -= 1;
                                }
                            }
                        }
                        f
                    };
                    if found != *neg {
                        pc += 1;
                        true
                    } else {
                        false
                    }
                }
                Inst::Atomic(sub) => match self.sub_match(sub, pos)? {
                    Some(e) => {
                        pos = e;
                        pc += 1;
                        true
                    }
                    None => false,
                },
                Inst::Recurse(g) => {
                    let g = *g;
                    if self.depth > 500 {
                        false
                    } else {
                        let prog = self.re.group_progs.get(g).cloned().flatten();
                        match prog {
                            Some(p) => {
                                // recursion: captures inside are restored afterwards (PCRE semantics)
                                let saved = self.slots.clone();
                                self.depth += 1;
                                let r = self.run(&p, 0, pos, false)?;
                                self.depth -= 1;
                                *self.slots = saved;
                                match r {
                                    Some(e) => {
                                        pos = e;
                                        pc += 1;
                                        true
                                    }
                                    None => false,
                                }
                            }
                            None => false,
                        }
                    }
                }
                Inst::CondGroup(g, else_t) => {
                    let set = self.slots.get(g * 2 + 1).copied().flatten().is_some();
                    if set {
                        pc += 1;
                    } else {
                        pc = *else_t;
                    }
                    true
                }
                Inst::CondLook(sub, ahead, neg, else_t) => {
                    let found = if *ahead {
                        self.sub_match(sub, pos)?.is_some()
                    } else {
                        let mut f = false;
                        let mut st = pos as isize;
                        while st >= 0 {
                            if let Some(e) = self.sub_match_end(sub, st as usize, pos)? {
                                if e == pos {
                                    f = true;
                                    break;
                                }
                            }
                            st -= 1;
                        }
                        f
                    };
                    if found != *neg {
                        pc += 1;
                    } else {
                        pc = *else_t;
                    }
                    true
                }
                Inst::Keep => {
                    self.keep = Some(pos);
                    pc += 1;
                    true
                }
                Inst::Fail => false,
                Inst::Match => {
                    if notempty && pos == start_pos && self.keep.is_none() {
                        false
                    } else {
                        return Ok(Some(pos));
                    }
                }
            };
            if !ok {
                // backtrack
                loop {
                    match stack.pop() {
                        None => return Ok(None),
                        Some(Bt::Branch(p, ps)) => {
                            pc = p;
                            pos = ps;
                            break;
                        }
                        Some(Bt::Slot(i, v)) => {
                            self.slots[i] = v;
                        }
                        Some(Bt::Mark(k, v)) => {
                            self.marks[k] = v;
                        }
                    }
                }
            }
        }
    }

    fn sub_match(&mut self, sub: &Prog, pos: usize) -> Result<Option<usize>, ()> {
        self.depth += 1;
        if self.depth > 1000 {
            self.depth -= 1;
            return Err(());
        }
        // captures set inside lookahead/atomic persist on success
        let saved = self.slots.clone();
        let r = self.run(sub, 0, pos, false);
        self.depth -= 1;
        match r {
            Ok(Some(e)) => Ok(Some(e)),
            Ok(None) => {
                *self.slots = saved;
                Ok(None)
            }
            Err(()) => Err(()),
        }
    }

    fn sub_match_end(&mut self, sub: &Prog, start: usize, must_end: usize) -> Result<Option<usize>, ()> {
        // like sub_match but only accept matches ending at must_end: emulate by restricting subject
        let saved_s = self.s;
        let limited = &saved_s[..must_end];
        let mut slots = self.slots.clone();
        let mut marks = self.marks.clone();
        let mut vm = Vm { re: self.re, s: limited, slots: &mut slots, marks: &mut marks, steps: self.steps, search_start: self.search_start, depth: self.depth + 1, keep: None };
        // need match that ends exactly at must_end: append EndText check by running then verifying
        let r = vm.run_until_end(sub, start, must_end)?;
        if r.is_some() {
            *self.slots = slots;
        }
        Ok(r)
    }

    fn run_until_end(&mut self, sub: &Prog, start: usize, end: usize) -> Result<Option<usize>, ()> {
        // emulate: try matches; backtracking VM returns first match; we need one ending at `end`.
        // Wrap: run program where Match requires pos==end.
        let mut stack: Vec<Bt> = Vec::new();
        let mut pc = 0;
        let mut pos = start;
        loop {
            // reuse run by checking result; simplified: run normally and accept only end
            let r = self.run(sub, pc, pos, false)?;
            let _ = &mut stack;
            return Ok(match r {
                Some(e) if e == end => Some(e),
                _ => None,
            });
            #[allow(unreachable_code)]
            {
                pc = 0;
                pos = 0;
            }
        }
    }
}

pub fn parse_pattern(full: &[u8]) -> Result<(Vec<u8>, Flags), String> {
    let mut i = 0;
    while i < full.len() && full[i].is_ascii_whitespace() {
        i += 1;
    }
    if i >= full.len() {
        return Err("Empty regular expression".to_string());
    }
    let d = full[i];
    if d.is_ascii_alphanumeric() || d == b'\\' || d == 0 {
        return Err("Delimiter must not be alphanumeric, backslash, or NUL byte".to_string());
    }
    let close = match d {
        b'(' => b')',
        b'[' => b']',
        b'{' => b'}',
        b'<' => b'>',
        c => c,
    };
    let start = i + 1;
    let mut j = start;
    let mut depth = 0;
    let mut end = None;
    while j < full.len() {
        let c = full[j];
        if c == b'\\' && j + 1 < full.len() {
            j += 2;
            continue;
        }
        if close != d {
            if c == d {
                depth += 1;
            } else if c == close {
                if depth == 0 {
                    end = Some(j);
                    break;
                }
                depth -= 1;
            }
        } else if c == close {
            end = Some(j);
            break;
        }
        j += 1;
    }
    let end = match end {
        Some(e) => e,
        None => {
            return Err(if close != d { format!("No ending matching delimiter '{}' found", close as char) } else { format!("No ending delimiter '{}' found", d as char) });
        }
    };
    let pat = full[start..end].to_vec();
    let mut f = Flags { caseless: false, multiline: false, dotall: false, extended: false, ungreedy: false, anchored: false, dollar_endonly: false, utf8: false, no_auto_capture: false };
    for &m in &full[end + 1..] {
        match m {
            b'i' => f.caseless = true,
            b'm' => f.multiline = true,
            b's' => f.dotall = true,
            b'x' => f.extended = true,
            b'U' => f.ungreedy = true,
            b'A' => f.anchored = true,
            b'D' => f.dollar_endonly = true,
            b'u' => f.utf8 = true,
            b'n' => f.no_auto_capture = true,
            b'S' | b'X' | b'J' => {}
            b'\n' | b'\r' | b' ' => {}
            b'e' => return Err("Unknown modifier 'e'".to_string()),
            c => {
                if c == 0 {
                    return Err("NUL is not a valid modifier".to_string());
                }
                return Err(format!("Unknown modifier '{}'", c as char));
            }
        }
    }
    Ok((pat, f))
}
