use super::*;
use crate::array::{Key, PArray};
use crate::regex::Regex;

pub const PREG_PATTERN_ORDER: i64 = 1;
pub const PREG_SET_ORDER: i64 = 2;
pub const PREG_OFFSET_CAPTURE: i64 = 256;
pub const PREG_UNMATCHED_AS_NULL: i64 = 512;
pub const PREG_SPLIT_NO_EMPTY: i64 = 1;
pub const PREG_SPLIT_DELIM_CAPTURE: i64 = 2;
pub const PREG_SPLIT_OFFSET_CAPTURE: i64 = 4;

pub fn get_regex(it: &mut Interp, fname: &str, pat: &[u8]) -> R<Option<Rc<Regex>>> {
    if let Some(r) = it.regex_cache.get(pat) {
        return Ok(Some(r.clone()));
    }
    let (p, flags) = match crate::regex::parse_pattern(pat) {
        Ok(x) => x,
        Err(msg) => {
            it.warn(&format!("{}(): {}", fname, msg))?;
            it.preg_last_error = 1;
            return Ok(None);
        }
    };
    match Regex::new(&p, &flags) {
        Ok(r) => {
            let r = Rc::new(r);
            if it.regex_cache.len() > 4096 {
                it.regex_cache.clear();
            }
            it.regex_cache.insert(pat.to_vec(), r.clone());
            Ok(Some(r))
        }
        Err(e) => {
            it.warn(&format!("{}(): Compilation failed: {} at offset {}", fname, e.msg, e.offset))?;
            it.preg_last_error = 1;
            Ok(None)
        }
    }
}

fn group_names(re: &Regex) -> Vec<Option<String>> {
    let mut v = vec![None; re.ncaps + 1];
    for (n, i) in &re.names {
        if *i < v.len() {
            v[*i] = Some(n.clone());
        }
    }
    v
}

fn cap_value(s: &[u8], caps: &[Option<usize>], i: usize, flags: i64) -> Value {
    let st = caps.get(i * 2).copied().flatten();
    let en = caps.get(i * 2 + 1).copied().flatten();
    let (v, off) = match (st, en) {
        (Some(a), Some(b)) if b >= a => (Value::bytes(&s[a..b]), a as i64),
        _ => (if flags & PREG_UNMATCHED_AS_NULL != 0 { Value::Null } else { Value::str("") }, -1),
    };
    if flags & PREG_OFFSET_CAPTURE != 0 {
        Value::arr(PArray::from_values(vec![v, Value::Int(off)]))
    } else {
        v
    }
}

fn build_match(re: &Regex, s: &[u8], caps: &[Option<usize>], flags: i64, trim: bool) -> PArray {
    let names = group_names(re);
    let mut count = re.ncaps + 1;
    if trim && flags & PREG_UNMATCHED_AS_NULL == 0 {
        while count > 1 && caps[(count - 1) * 2 + 1].is_none() {
            count -= 1;
        }
    }
    let mut out = PArray::new();
    for i in 0..count {
        let v = cap_value(s, caps, i, flags);
        if let Some(n) = &names[i] {
            out.set(Key::Str(Rc::new(n.as_bytes().to_vec())), v.clone());
        }
        out.set(Key::Int(i as i64), v);
    }
    out
}

fn check_utf8(it: &mut Interp, re: &Regex, s: &[u8]) -> bool {
    if re.utf8 && std::str::from_utf8(s).is_err() {
        it.preg_last_error = 4;
        return false;
    }
    true
}

fn f_preg_match(it: &mut Interp, a: &mut Args) -> R<Value> {
    let pat = a.str(it, 0)?;
    let s = a.str(it, 1)?;
    let flags = a.int_or(it, 3, 0)?;
    let mut off = a.int_or(it, 4, 0)?;
    let re = match get_regex(it, "preg_match", &pat)? {
        Some(r) => r,
        None => return Ok(Value::Bool(false)),
    };
    it.preg_last_error = 0;
    if !check_utf8(it, &re, &s) {
        return Ok(Value::Bool(false));
    }
    if off < 0 {
        off = (s.len() as i64 + off).max(0);
    }
    if off as usize > s.len() {
        it.preg_last_error = 1;
        a.set_ref(2, Value::empty_array());
        return Ok(Value::Bool(false));
    }
    let mut steps = 0;
    match re.search(&s, off as usize, false, &mut steps) {
        Err(()) => {
            it.preg_last_error = 2;
            a.set_ref(2, Value::empty_array());
            Ok(Value::Bool(false))
        }
        Ok(None) => {
            a.set_ref(2, Value::empty_array());
            Ok(Value::Int(0))
        }
        Ok(Some(caps)) => {
            if a.len() > 2 {
                a.set_ref(2, Value::arr(build_match(&re, &s, &caps, flags, true)));
            }
            Ok(Value::Int(1))
        }
    }
}

/// iterate all matches; callback gets caps
fn all_matches(re: &Regex, s: &[u8], start: usize, limit: Option<usize>, mut cb: impl FnMut(&[Option<usize>])) -> Result<usize, ()> {
    let mut pos = start;
    let mut count = 0;
    let mut steps = 0;
    let mut notempty = false;
    loop {
        if let Some(l) = limit {
            if count >= l {
                break;
            }
        }
        if pos > s.len() {
            break;
        }
        let m = re.search(s, pos, notempty, &mut steps)?;
        match m {
            None => {
                if notempty && pos < s.len() {
                    // retry from next char
                    let adv = if re.utf8 { crate::regex::utf8_len(s[pos]) } else { 1 };
                    pos += adv;
                    notempty = false;
                    // must find match starting at >= pos
                    continue;
                }
                break;
            }
            Some(caps) => {
                let (ms, me) = (caps[0].unwrap(), caps[1].unwrap());
                if notempty && ms == pos && me == pos {
                    // shouldn't happen
                    break;
                }
                count += 1;
                cb(&caps);
                if me == ms {
                    pos = me;
                    notempty = true;
                } else {
                    pos = me;
                    notempty = false;
                }
            }
        }
    }
    Ok(count)
}

fn f_preg_match_all(it: &mut Interp, a: &mut Args) -> R<Value> {
    let pat = a.str(it, 0)?;
    let s = a.str(it, 1)?;
    let mut flags = a.int_or(it, 3, 0)?;
    let off = a.int_or(it, 4, 0)?;
    let re = match get_regex(it, "preg_match_all", &pat)? {
        Some(r) => r,
        None => return Ok(Value::Bool(false)),
    };
    it.preg_last_error = 0;
    if !check_utf8(it, &re, &s) {
        return Ok(Value::Bool(false));
    }
    if flags & 3 == 0 {
        flags |= PREG_PATTERN_ORDER;
    }
    if flags & 3 == 3 {
        return Err(it.value_error("preg_match_all(): Argument #4 ($flags) must be a PREG_* constant"));
    }
    let off = if off < 0 { (s.len() as i64 + off).max(0) } else { off } as usize;
    let mut all: Vec<Vec<Option<usize>>> = Vec::new();
    let r = all_matches(&re, &s, off.min(s.len()), None, |c| all.push(c.to_vec()));
    let n = match r {
        Ok(n) => n,
        Err(()) => {
            it.preg_last_error = 2;
            a.set_ref(2, Value::empty_array());
            return Ok(Value::Bool(false));
        }
    };
    if a.len() > 2 {
        let names = group_names(&re);
        let result = if flags & PREG_SET_ORDER != 0 {
            let mut out = PArray::new();
            for caps in &all {
                out.push(Value::arr(build_match(&re, &s, caps, flags, flags & PREG_UNMATCHED_AS_NULL == 0)));
            }
            out
        } else {
            let mut out = PArray::new();
            for i in 0..=re.ncaps {
                let mut col = PArray::new();
                for caps in &all {
                    col.push(cap_value(&s, caps, i, flags));
                }
                if let Some(nm) = &names[i] {
                    out.set(Key::Str(Rc::new(nm.as_bytes().to_vec())), Value::arr(col.clone()));
                }
                out.set(Key::Int(i as i64), Value::arr(col));
            }
            out
        };
        a.set_ref(2, Value::arr(result));
    }
    Ok(Value::Int(n as i64))
}

fn expand_replacement(rep: &[u8], s: &[u8], caps: &[Option<usize>], ncaps: usize) -> Vec<u8> {
    let mut out = Vec::with_capacity(rep.len());
    let mut i = 0;
    let mut last: u8 = 0;
    while i < rep.len() {
        let c = rep[i];
        if c == b'\\' || c == b'$' {
            if last == b'\\' {
                // escaped
                let l = out.len();
                out[l - 1] = c;
                i += 1;
                last = 0;
                continue;
            }
            // backref?
            let mut j = i + 1;
            let mut braced = false;
            if c == b'$' && j < rep.len() && rep[j] == b'{' {
                braced = true;
                j += 1;
            }
            if j < rep.len() && rep[j].is_ascii_digit() {
                let mut n = (rep[j] - b'0') as usize;
                j += 1;
                if j < rep.len() && rep[j].is_ascii_digit() {
                    n = n * 10 + (rep[j] - b'0') as usize;
                    j += 1;
                }
                let ok = if braced {
                    if j < rep.len() && rep[j] == b'}' {
                        j += 1;
                        true
                    } else {
                        false
                    }
                } else {
                    true
                };
                if ok {
                    if n <= ncaps {
                        if let (Some(a), Some(b)) = (caps.get(n * 2).copied().flatten(), caps.get(n * 2 + 1).copied().flatten()) {
                            out.extend_from_slice(&s[a..b]);
                        }
                    }
                    i = j;
                    last = 0;
                    continue;
                }
            }
        }
        out.push(c);
        last = c;
        i += 1;
    }
    out
}

enum Repl<'a> {
    Str(&'a [u8]),
    Cb(&'a Value),
}

fn replace_one(it: &mut Interp, re: &Regex, s: &[u8], rep: Repl, limit: Option<usize>, count: &mut i64, cb_flags: i64) -> R<Option<Vec<u8>>> {
    if !check_utf8(it, re, s) {
        return Ok(None);
    }
    let mut all: Vec<Vec<Option<usize>>> = Vec::new();
    match all_matches(re, s, 0, limit, |c| all.push(c.to_vec())) {
        Ok(_) => {}
        Err(()) => {
            it.preg_last_error = 2;
            return Ok(None);
        }
    }
    if all.is_empty() {
        return Ok(Some(s.to_vec()));
    }
    let mut out = Vec::with_capacity(s.len());
    let mut last = 0;
    for caps in &all {
        let (ms, me) = (caps[0].unwrap(), caps[1].unwrap());
        out.extend_from_slice(&s[last..ms]);
        match &rep {
            Repl::Str(r) => out.extend_from_slice(&expand_replacement(r, s, caps, re.ncaps)),
            Repl::Cb(cb) => {
                let m = build_match(re, s, caps, cb_flags, cb_flags & PREG_UNMATCHED_AS_NULL == 0);
                let r = it.call_value(cb, vec![Value::arr(m)])?;
                let rs = it.to_str(&r)?;
                out.extend_from_slice(&rs);
            }
        }
        last = me;
        *count += 1;
    }
    out.extend_from_slice(&s[last..]);
    Ok(Some(out))
}

fn do_preg_replace(it: &mut Interp, a: &mut Args, fname: &str, is_cb: bool, filter: bool) -> R<Value> {
    let pat_v = a.get(0);
    let rep_v = a.get(1);
    let subj_v = a.get(2);
    let limit = a.int_or(it, 3, -1)?;
    let limit = if limit < 0 { None } else { Some(limit as usize) };
    let cb_flags = if is_cb { a.int_or(it, 5, 0)? } else { 0 };
    if is_cb {
        a.callable(it, 1)?;
    }
    let pats: Vec<PStr> = match &pat_v {
        Value::Array(arr) => {
            let mut v = Vec::new();
            for x in arr.values() {
                v.push(it.to_str(&x.deref())?);
            }
            v
        }
        x => vec![it.to_str(x)?],
    };
    let reps: Option<Vec<PStr>> = if is_cb {
        None
    } else {
        match &rep_v {
            Value::Array(arr) => {
                if !matches!(pat_v, Value::Array(_)) {
                    return Err(it.type_error(&format!("{}(): Argument #1 ($pattern) must be of type array when argument #2 ($replacement) is an array, string given", fname)));
                }
                let mut v = Vec::new();
                for x in arr.values() {
                    v.push(it.to_str(&x.deref())?);
                }
                Some(v)
            }
            x => {
                let s = it.to_str(x)?;
                Some(vec![s; pats.len()])
            }
        }
    };
    let mut total = 0i64;
    it.preg_last_error = 0;
    let mut process = |it: &mut Interp, subject: &[u8], total: &mut i64| -> R<Option<(Vec<u8>, i64)>> {
        let mut cur = subject.to_vec();
        let mut cnt = 0i64;
        for (pi, p) in pats.iter().enumerate() {
            let re = match get_regex(it, fname, p)? {
                Some(r) => r,
                None => return Ok(None),
            };
            let r = if is_cb {
                replace_one(it, &re, &cur, Repl::Cb(&rep_v), limit, &mut cnt, cb_flags)?
            } else {
                let empty: PStr = Rc::new(Vec::new());
                let rp = reps.as_ref().unwrap().get(pi).cloned().unwrap_or(empty);
                replace_one(it, &re, &cur, Repl::Str(&rp), limit, &mut cnt, 0)?
            };
            match r {
                Some(n) => cur = n,
                None => return Ok(None),
            }
        }
        *total += cnt;
        Ok(Some((cur, cnt)))
    };
    let result = match &subj_v {
        Value::Array(arr) => {
            let mut out = PArray::new();
            for (k, v) in arr.iter() {
                let sv = it.to_str(&v.deref())?;
                match process(it, &sv, &mut total)? {
                    Some((r, c)) => {
                        if !filter || c > 0 {
                            out.set(k.clone(), Value::vec(r));
                        }
                    }
                    None => {}
                }
            }
            Value::arr(out)
        }
        x => {
            let sv = it.to_str(x)?;
            match process(it, &sv, &mut total)? {
                Some((r, c)) => {
                    if filter && c == 0 {
                        Value::Null
                    } else {
                        Value::vec(r)
                    }
                }
                None => Value::Null,
            }
        }
    };
    if a.len() > 4 {
        a.set_ref(4, Value::Int(total));
    }
    Ok(result)
}

fn f_preg_replace(it: &mut Interp, a: &mut Args) -> R<Value> {
    do_preg_replace(it, a, "preg_replace", false, false)
}
fn f_preg_filter(it: &mut Interp, a: &mut Args) -> R<Value> {
    do_preg_replace(it, a, "preg_filter", false, true)
}
fn f_preg_replace_callback(it: &mut Interp, a: &mut Args) -> R<Value> {
    do_preg_replace(it, a, "preg_replace_callback", true, false)
}
fn f_preg_replace_callback_array(it: &mut Interp, a: &mut Args) -> R<Value> {
    let map = a.arr(it, 0)?;
    let mut subj = a.get(1);
    let limit = a.int_or(it, 2, -1)?;
    let flags = a.int_or(it, 4, 0)?;
    let mut total = 0;
    for (k, cb) in map.iter() {
        let pat = Value::bytes(&k.as_bytes());
        let def = a.def;
        let cnt_ref = Rc::new(RefCell::new(Value::Int(0)));
        let mut sub = Args { v: vec![pat, cb.deref(), subj.clone(), Value::Int(limit), Value::Ref(cnt_ref.clone()), Value::Int(flags)], def };
        subj = do_preg_replace(it, &mut sub, "preg_replace_callback_array", true, false)?;
        total += cnt_ref.borrow().to_int();
        if subj.is_null() {
            break;
        }
    }
    if a.len() > 3 {
        a.set_ref(3, Value::Int(total));
    }
    Ok(subj)
}
use std::cell::RefCell;

fn f_preg_split(it: &mut Interp, a: &mut Args) -> R<Value> {
    let pat = a.str(it, 0)?;
    let s = a.str(it, 1)?;
    let limit = a.int_or(it, 2, -1)?;
    let flags = a.int_or(it, 3, 0)?;
    let re = match get_regex(it, "preg_split", &pat)? {
        Some(r) => r,
        None => return Ok(Value::Bool(false)),
    };
    it.preg_last_error = 0;
    if !check_utf8(it, &re, &s) {
        return Ok(Value::Bool(false));
    }
    let no_empty = flags & PREG_SPLIT_NO_EMPTY != 0;
    let delim = flags & PREG_SPLIT_DELIM_CAPTURE != 0;
    let offc = flags & PREG_SPLIT_OFFSET_CAPTURE != 0;
    let limit = if limit == 0 { -1 } else { limit };
    let mut out = PArray::new();
    let push = |out: &mut PArray, piece: &[u8], off: usize| {
        if offc {
            out.push(Value::arr(PArray::from_values(vec![Value::bytes(piece), Value::Int(off as i64)])));
        } else {
            out.push(Value::bytes(piece));
        }
    };
    let mut last = 0usize;
    let mut pos = 0usize;
    let mut steps = 0;
    let mut notempty = false;
    loop {
        if limit > 0 && out.len() as i64 >= limit - 1 {
            break;
        }
        if pos > s.len() {
            break;
        }
        let m = match re.search(&s, pos, notempty, &mut steps) {
            Ok(m) => m,
            Err(()) => {
                it.preg_last_error = 2;
                return Ok(Value::Bool(false));
            }
        };
        let caps = match m {
            None => {
                if notempty && pos < s.len() {
                    pos += if re.utf8 { crate::regex::utf8_len(s[pos]) } else { 1 };
                    notempty = false;
                    continue;
                }
                break;
            }
            Some(c) => c,
        };
        let (ms, me) = (caps[0].unwrap(), caps[1].unwrap());
        if me == ms && ms == s.len() {
            break;
        }
        if !(me == ms && ms == last && false) {
            let piece = &s[last..ms];
            if !(no_empty && piece.is_empty()) {
                if !(me == ms && ms == 0) {
                    push(&mut out, piece, last);
                }
            }
            if delim {
                for g in 1..=re.ncaps {
                    if let (Some(a1), Some(b1)) = (caps[g * 2], caps[g * 2 + 1]) {
                        if !(no_empty && a1 == b1) {
                            push(&mut out, &s[a1..b1], a1);
                        }
                    }
                }
            }
            if !(me == ms && ms == 0) {
                last = me;
            }
        }
        if me == ms {
            pos = me;
            notempty = true;
        } else {
            pos = me;
            notempty = false;
        }
    }
    let piece = &s[last..];
    if !(no_empty && piece.is_empty()) {
        push(&mut out, piece, last);
    }
    Ok(Value::arr(out))
}

fn f_preg_quote(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let d = a.opt_str(it, 1)?;
    let dc = d.as_ref().and_then(|d| d.first().copied());
    let mut out = Vec::with_capacity(s.len());
    for &c in s.iter() {
        if c == 0 {
            out.extend_from_slice(b"\\000");
            continue;
        }
        if b".\\+*?[^]$(){}=!<>|:-#/".contains(&c) && (c != b'/' || dc == Some(b'/')) || Some(c) == dc {
            out.push(b'\\');
        }
        out.push(c);
    }
    Ok(Value::vec(out))
}

fn f_preg_grep(it: &mut Interp, a: &mut Args) -> R<Value> {
    let pat = a.str(it, 0)?;
    let arr = a.arr(it, 1)?;
    let flags = a.int_or(it, 2, 0)?;
    let re = match get_regex(it, "preg_grep", &pat)? {
        Some(r) => r,
        None => return Ok(Value::Bool(false)),
    };
    let mut out = PArray::new();
    for (k, v) in arr.iter() {
        let sv = it.to_str(&v.deref())?;
        let mut steps = 0;
        let m = re.search(&sv, 0, false, &mut steps).unwrap_or(None).is_some();
        if m != (flags & 1 != 0) {
            out.set(k.clone(), v.deref());
        }
    }
    Ok(Value::arr(out))
}

fn f_preg_last_error(it: &mut Interp, _a: &mut Args) -> R<Value> {
    Ok(Value::Int(it.preg_last_error))
}
fn f_preg_last_error_msg(it: &mut Interp, _a: &mut Args) -> R<Value> {
    Ok(Value::str(match it.preg_last_error {
        0 => "No error",
        1 => "Internal error",
        2 => "Backtrack limit exhausted",
        3 => "Recursion limit exhausted",
        4 => "Malformed UTF-8 characters, possibly incorrectly encoded",
        5 => "The offset did not correspond to the beginning of a valid UTF-8 code point",
        6 => "JIT stack limit exhausted",
        _ => "Unknown error",
    }))
}

pub fn register(it: &mut Interp) {
    reg(it, "preg_match", "pattern,subject,&matches?,flags?,offset?", f_preg_match);
    reg(it, "preg_match_all", "pattern,subject,&matches?,flags?,offset?", f_preg_match_all);
    reg(it, "preg_replace", "pattern,replacement,subject,limit?,&count?", f_preg_replace);
    reg(it, "preg_filter", "pattern,replacement,subject,limit?,&count?", f_preg_filter);
    reg(it, "preg_replace_callback", "pattern,callback,subject,limit?,&count?,flags?", f_preg_replace_callback);
    reg(it, "preg_replace_callback_array", "pattern,subject,limit?,&count?,flags?", f_preg_replace_callback_array);
    reg(it, "preg_split", "pattern,subject,limit?,flags?", f_preg_split);
    reg(it, "preg_quote", "str,delimiter?", f_preg_quote);
    reg(it, "preg_grep", "pattern,array,flags?", f_preg_grep);
    reg(it, "preg_last_error", "", f_preg_last_error);
    reg(it, "preg_last_error_msg", "", f_preg_last_error_msg);
    let c: &[(&str, i64)] = &[
        ("PREG_PATTERN_ORDER", 1),
        ("PREG_SET_ORDER", 2),
        ("PREG_OFFSET_CAPTURE", 256),
        ("PREG_UNMATCHED_AS_NULL", 512),
        ("PREG_SPLIT_NO_EMPTY", 1),
        ("PREG_SPLIT_DELIM_CAPTURE", 2),
        ("PREG_SPLIT_OFFSET_CAPTURE", 4),
        ("PREG_GREP_INVERT", 1),
        ("PREG_NO_ERROR", 0),
        ("PREG_INTERNAL_ERROR", 1),
        ("PREG_BACKTRACK_LIMIT_ERROR", 2),
        ("PREG_RECURSION_LIMIT_ERROR", 3),
        ("PREG_BAD_UTF8_ERROR", 4),
        ("PREG_BAD_UTF8_OFFSET_ERROR", 5),
        ("PREG_JIT_STACKLIMIT_ERROR", 6),
        ("PCRE_VERSION_MAJOR", 10),
        ("PCRE_VERSION_MINOR", 44),
        ("PCRE_JIT_SUPPORT", 1),
    ];
    for (n, v) in c {
        super::misc::def_const(it, n, Value::Int(*v));
    }
    super::misc::def_const(it, "PCRE_VERSION", Value::str("10.44 2024-06-07"));
}
