            b'd' => {
                let t = self.read_until(b';')?;
                let st = std::str::from_utf8(t).ok()?;
                Value::Float(match st {
                    "INF" => f64::INFINITY,
                    "-INF" => f64::NEG_INFINITY,
                    "NAN" => f64::NAN,
                    _ => st.parse().ok()?,
                })
            }
            b's' => {
                let v = self.read_strbody()?;
                self.expect(b';')?;
                Value::vec(v)
