                        let kb = k.as_bytes();
                        let name = match kb.iter().rposition(|&c| c == 0) {
                            Some(p) => kb[p + 1..].to_vec(),
                            None => kb.clone(),
                        };
                        let ns = String::from_utf8_lossy(&name).to_string();
                        // pick slot by mangled key
                        let mut set = false;
                        for info in cls.slots.iter() {
                            if *info.name == *ns {
                                let mk = crate::interp::props::mangle(info);
                                if mk == kb || info.vis == Visibility::Public && kb == name {
                                    o.slots.borrow_mut()[info.slot] = v.clone();
                                    set = true;
                                    break;
                                }
                            }
                        }
                        if !set {
                            if let Some(info) = cls.prop_infos.get(ns.as_str()) {
                                o.slots.borrow_mut()[info.slot] = v.clone();
                            } else {
                                o.dynamic.borrow_mut().get_or_insert_with(PArray::new).set(Key::Str(Rc::new(name)), v.clone());
                            }
                        }
                    }
                    if cls.magic.wakeup.is_some() {
                        self.wakeups.push(o.clone());
                    }
                }
                let _ = idx;
                return Some(Value::Object(o));
            }
            b'E' => {
                let body = self.read_strbody()?;
                self.expect(b';')?;
                let bs = String::from_utf8_lossy(&body).to_string();
                let (cn, case) = bs.split_once(':')?;
                let cls = it.find_class_autoload(cn.as_bytes())?;
                let o = super::classes::enum_case(it, &cls, case).ok()?;
                Value::Object(o)
            }
            b'r' | b'R' => {
                let n = self.read_int(b';')? as usize;
                let v = self.vars.get(n.checked_sub(1)?)?.clone();
                v
            }
            _ => return None,
        };
        self.vars.push(v.clone());
        Some(v)
    }
}

fn f_unserialize(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let mut allowed = None;
    if let Value::Array(opts) = a.get(1) {
        if let Some(ac) = opts.get(&Key::Str(pstr("allowed_classes"))) {
            match ac.deref() {
                Value::Bool(false) => allowed = Some(vec![]),
                Value::Array(list) => allowed = Some(list.values().map(|v| v.to_bytes_simple()).collect()),
                _ => {}
            }
        }
    }
    let mut u = Unser { s: &s, pos: 0, vars: Vec::new(), allowed, wakeups: Vec::new(), unser_calls: Vec::new() };
    let r = u.value(it);
    match r {
        Some(v) => {
            let calls = std::mem::take(&mut u.unser_calls);
            for (o, d) in calls {
                if let Some(m) = o.class.magic.unserialize.clone() {
                    it.call_method_obj(&o, &m, vec![d])?;
                }
            }
            let w = std::mem::take(&mut u.wakeups);
            for o in w {
                if let Some(m) = o.class.magic.wakeup.clone() {
                    it.call_method_obj(&o, &m, vec![])?;
                }
            }
            Ok(v)
        }
        None => {
            let off = u.pos.saturating_sub(1).min(s.len());
            it.notice(&format!("unserialize(): Error at offset {} of {} bytes", if s.is_empty() { 0 } else { off }, s.len()))?;
            Ok(Value::Bool(false))
        }
    }
}

pub fn register(it: &mut Interp) {
    reg(it, "serialize", "value", f_serialize);
    reg(it, "unserialize", "data,options?", f_unserialize);
}
