use super::*;
use crate::array::{Key, PArray};
use crate::ast::{ClassKind, Visibility};

struct Ser {
    out: Vec<u8>,
    objs: Vec<(u32, usize)>, // object id -> var number
    counter: usize,
}

fn ser_str(out: &mut Vec<u8>, s: &[u8]) {
    out.extend_from_slice(format!("s:{}:\"", s.len()).as_bytes());
    out.extend_from_slice(s);
    out.extend_from_slice(b"\";");
}

fn ser_key(out: &mut Vec<u8>, k: &Key) {
    match k {
        Key::Int(i) => out.extend_from_slice(format!("i:{};", i).as_bytes()),
        Key::Str(s) => ser_str(out, s),
    }
}

impl Ser {
    fn value(&mut self, it: &mut Interp, v: &Value) -> R<()> {
        self.counter += 1;
        match v {
            Value::Null | Value::Undef => self.out.extend_from_slice(b"N;"),
            Value::Bool(b) => self.out.extend_from_slice(if *b { b"b:1;" } else { b"b:0;" }),
            Value::Int(i) => self.out.extend_from_slice(format!("i:{};", i).as_bytes()),
            Value::Float(f) => {
                let s = if f.is_nan() { "NAN".to_string() } else if f.is_infinite() { if *f > 0.0 { "INF".into() } else { "-INF".into() } } else { fmt_float_prec(*f, it.serialize_precision) };
                self.out.extend_from_slice(format!("d:{};", s).as_bytes());
            }
            Value::Str(s) => ser_str(&mut self.out, s),
            Value::Ref(r) => {
                let v = r.borrow().clone();
                self.counter -= 1;
                self.value(it, &v)?;
            }
            Value::Array(a) => {
                self.out.extend_from_slice(format!("a:{}:{{", a.len()).as_bytes());
                for (k, v) in a.iter() {
                    ser_key(&mut self.out, k);
                    self.value(it, v)?;
                }
                self.out.push(b'}');
            }
            Value::Object(o) => {
                if let Some(&(_, n)) = self.objs.iter().find(|(id, _)| *id == o.id) {
                    self.out.extend_from_slice(format!("r:{};", n).as_bytes());
                    return Ok(());
                }
                self.objs.push((o.id, self.counter));
                let cname = o.class.name.clone();
                if o.class.kind == ClassKind::Enum {
                    let n = it.get_prop_raw(o, "name").to_string_lossy();
                    let s = format!("{}:{}", cname, n);
                    self.out.extend_from_slice(format!("E:{}:\"{}\";", s.len(), s).as_bytes());
                    return Ok(());
                }
                if super::classes::is_closure(o) || crate::interp::gen::is_generator_obj(o) {
                    let msg = format!("Serialization of '{}' is not allowed", cname);
                    return Err(it.throw_err("Exception", &msg));
                }
                if let Some(m) = o.class.magic.serialize.clone() {
                    let r = it.call_method_obj(o, &m, vec![])?;
                    let arr = match r {
                        Value::Array(a) => a,
                        _ => {
                            let msg = format!("{}::__serialize() must return an array", cname);
                            return Err(it.type_error(&msg));
                        }
                    };
                    self.out.extend_from_slice(format!("O:{}:\"{}\":{}:{{", cname.len(), cname, arr.len()).as_bytes());
                    for (k, v) in arr.iter() {
                        ser_key(&mut self.out, k);
                        self.value(it, v)?;
                    }
                    self.out.push(b'}');
                    return Ok(());
                }
                let props: Vec<(Vec<u8>, Value)> = if let Some(m) = o.class.magic.sleep.clone() {
                    let r = it.call_method_obj(o, &m, vec![])?;
                    let mut v = Vec::new();
                    if let Value::Array(names) = r {
                        let all = it.object_prop_array(o);
                        for n in names.values() {
                            let n = it.to_str(&n.deref())?;
                            // find mangled
                            let mut found = None;
                            for (k, val) in all.iter() {
                                let kb = k.as_bytes();
                                let base = match kb.iter().rposition(|&c| c == 0) {
                                    Some(p) => &kb[p + 1..],
                                    None => &kb[..],
                                };
                                if base == n.as_slice() {
                                    found = Some((kb.clone(), val.clone()));
                                    break;
                                }
                            }
                            match found {
                                Some(f) => v.push(f),
                                None => {
                                    it.warn(&format!("serialize(): \"{}\" returned as member variable from __sleep() but does not exist", String::from_utf8_lossy(&n)))?;
                                }
                            }
                        }
                    }
                    v
                } else {
                    it.object_prop_array(o).iter().map(|(k, v)| (k.as_bytes(), v.clone())).collect()
                };
                self.out.extend_from_slice(format!("O:{}:\"{}\":{}:{{", cname.len(), cname, props.len()).as_bytes());
                for (k, v) in props {
                    ser_str(&mut self.out, &k);
                    self.value(it, &v)?;
                }
                self.out.push(b'}');
            }
        }
        Ok(())
    }
}

pub fn serialize(it: &mut Interp, v: &Value) -> R<Vec<u8>> {
    let mut s = Ser { out: Vec::new(), objs: Vec::new(), counter: 0 };
    s.value(it, v)?;
    Ok(s.out)
}

fn f_serialize(it: &mut Interp, a: &mut Args) -> R<Value> {
    let v = a.get(0);
    Ok(Value::vec(serialize(it, &v)?))
}

struct Unser<'a> {
    s: &'a [u8],
    pos: usize,
    vars: Vec<Value>,
    allowed: Option<Vec<Vec<u8>>>,
    wakeups: Vec<Obj>,
    unser_calls: Vec<(Obj, Value)>,
}

impl<'a> Unser<'a> {
    fn expect(&mut self, c: u8) -> Option<()> {
        if self.s.get(self.pos) == Some(&c) {
            self.pos += 1;
            Some(())
        } else {
            None
        }
    }
    fn read_until(&mut self, c: u8) -> Option<&'a [u8]> {
        let st = self.pos;
        while self.pos < self.s.len() && self.s[self.pos] != c {
            self.pos += 1;
        }
        if self.pos >= self.s.len() {
            return None;
        }
        let r = &self.s[st..self.pos];
        self.pos += 1;
        Some(r)
    }
    fn read_int(&mut self, term: u8) -> Option<i64> {
        let t = self.read_until(term)?;
        std::str::from_utf8(t).ok()?.parse().ok()
    }
    fn read_strbody(&mut self) -> Option<Vec<u8>> {
        let n = self.read_int(b':')? as usize;
        self.expect(b'"')?;
        if self.pos + n > self.s.len() {
            return None;
        }
        let v = self.s[self.pos..self.pos + n].to_vec();
        self.pos += n;
        self.expect(b'"')?;
        Some(v)
    }
    fn value(&mut self, it: &mut Interp) -> Option<Value> {
        let t = *self.s.get(self.pos)?;
        self.pos += 1;
        if t == b'N' {
            self.expect(b';')?;
            self.vars.push(Value::Null);
            return Some(Value::Null);
        }
        self.expect(b':')?;
        let v = match t {
            b'b' => {
                let n = self.read_int(b';')?;
                if n != 0 && n != 1 {
                    return None;
                }
                Value::Bool(n == 1)
            }
            b'i' => Value::Int(self.read_int(b';')?),
            b'd' => {
                let t = self.read_until(b';')?;
                let st = std::str::from_utf8(t).ok()?;
                Value::Float(match st {
                    "INF" => f64::INFINITY,
                    "-INF" => f64::NEG_INFINITY,
                    "NAN" => f64::NAN,
                    _ => st.parse().ok()?,
                })
            }
            b's' => {
                let v = self.read_strbody()?;
                self.expect(b';')?;
                Value::vec(v)
            }
            b'S' => {
                let v = self.read_strbody()?;
                self.expect(b';')?;
                Value::vec(v)
            }
            b'a' => {
                let n = self.read_int(b':')?;
                self.expect(b'{')?;
                let idx = self.vars.len();
                self.vars.push(Value::Null);
                let mut arr = PArray::new();
                for _ in 0..n {
                    let k = match *self.s.get(self.pos)? {
                        b'i' => {
                            self.pos += 2;
                            Key::Int(self.read_int(b';')?)
                        }
                        b's' => {
                            self.pos += 2;
                            let s = self.read_strbody()?;
                            self.expect(b';')?;
                            Key::from_str_bytes(&s)
                        }
                        _ => return None,
                    };
                    let v = self.value(it)?;
                    arr.set(k, v);
                }
                self.expect(b'}')?;
                let v = Value::arr(arr);
                self.vars[idx] = v.clone();
                return Some(v);
            }
            b'O' | b'C' => {
                let cname = self.read_strbody()?;
                self.expect(b':')?;
                let n = self.read_int(b':')?;
                self.expect(b'{')?;
                let allowed = match &self.allowed {
                    None => true,
                    Some(list) => list.iter().any(|c| c.eq_ignore_ascii_case(&cname)),
                };
                let cls = if allowed { it.find_class_autoload(&cname) } else { None };
                let cls = match cls {
                    Some(c) => c,
                    None => {
                        let c = it.find_class(b"__PHP_Incomplete_Class").unwrap();
                        c
                    }
                };
                let o = it.instantiate_raw(&cls).ok()?;
                if cls.name.as_ref() == "__PHP_Incomplete_Class" {
                    let mut d = PArray::new();
                    d.set(Key::Str(pstr("__PHP_Incomplete_Class_Name")), Value::vec(cname.clone()));
                    *o.dynamic.borrow_mut() = Some(d);
                }
                let idx = self.vars.len();
                self.vars.push(Value::Object(o.clone()));
                let mut data = PArray::new();
                for _ in 0..n {
                    let k = match *self.s.get(self.pos)? {
                        b'i' => {
                            self.pos += 2;
                            Key::Int(self.read_int(b';')?)
                        }
                        b's' => {
                            self.pos += 2;
                            let s = self.read_strbody()?;
                            self.expect(b';')?;
                            Key::Str(Rc::new(s))
                        }
                        _ => return None,
                    };
                    let v = self.value(it)?;
                    data.set(k, v);
                }
                self.expect(b'}')?;
                if cls.magic.unserialize.is_some() {
                    self.unser_calls.push((o.clone(), Value::arr(data)));
                } else {
                    for (k, v) in data.iter() {
                        let kb = k.as_bytes();
                        let name = match kb.iter().rposition(|&c| c == 0) {
                            Some(p) => kb[p + 1..].to_vec(),
                            None => kb.clone(),
                        };
                        let ns = String::from_utf8_lossy(&name).to_string();
                        // pick slot by mangled key
                        let mut set = false;
                        for info in cls.slots.iter() {
                            if *info.name == *ns {
                                let mk = crate::interp::props::mangle(info);
                                if mk == kb || info.vis == Visibility::Public && kb == name {
                                    o.slots.borrow_mut()[info.slot] = v.clone();
                                    set = true;
                                    break;
                                }
                            }
                        }
                        if !set {
                            if let Some(info) = cls.prop_infos.get(ns.as_str()) {
                                o.slots.borrow_mut()[info.slot] = v.clone();
                            } else {
                                o.dynamic.borrow_mut().get_or_insert_with(PArray::new).set(Key::Str(Rc::new(name)), v.clone());
                            }
                        }
                    }
                    if cls.magic.wakeup.is_some() {
                        self.wakeups.push(o.clone());
                    }
                }
                let _ = idx;
                return Some(Value::Object(o));
            }
            b'E' => {
                let body = self.read_strbody()?;
                self.expect(b';')?;
                let bs = String::from_utf8_lossy(&body).to_string();
                let (cn, case) = bs.split_once(':')?;
                let cls = it.find_class_autoload(cn.as_bytes())?;
                let o = super::classes::enum_case(it, &cls, case).ok()?;
                Value::Object(o)
            }
            b'r' | b'R' => {
                let n = self.read_int(b';')? as usize;
                let v = self.vars.get(n.checked_sub(1)?)?.clone();
                v
            }
            _ => return None,
        };
        self.vars.push(v.clone());
        Some(v)
    }
}

fn f_unserialize(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let mut allowed = None;
    if let Value::Array(opts) = a.get(1) {
        if let Some(ac) = opts.get(&Key::Str(pstr("allowed_classes"))) {
            match ac.deref() {
                Value::Bool(false) => allowed = Some(vec![]),
                Value::Array(list) => allowed = Some(list.values().map(|v| v.to_bytes_simple()).collect()),
                _ => {}
            }
        }
    }
    let mut u = Unser { s: &s, pos: 0, vars: Vec::new(), allowed, wakeups: Vec::new(), unser_calls: Vec::new() };
    let r = u.value(it);
    match r {
        Some(v) => {
            let calls = std::mem::take(&mut u.unser_calls);
            for (o, d) in calls {
                if let Some(m) = o.class.magic.unserialize.clone() {
                    it.call_method_obj(&o, &m, vec![d])?;
                }
            }
            let w = std::mem::take(&mut u.wakeups);
            for o in w {
                if let Some(m) = o.class.magic.wakeup.clone() {
                    it.call_method_obj(&o, &m, vec![])?;
                }
            }
            Ok(v)
        }
        None => {
            let off = u.pos.saturating_sub(1).min(s.len());
            it.notice(&format!("unserialize(): Error at offset {} of {} bytes", if s.is_empty() { 0 } else { off }, s.len()))?;
            Ok(Value::Bool(false))
        }
    }
}

pub fn register(it: &mut Interp) {
    reg(it, "serialize", "value", f_serialize);
    reg(it, "unserialize", "data,options?", f_unserialize);
}
