pub fn find_zone(name: &str) -> Option<Zone> {
    let ln = name.to_ascii_lowercase();
    if ln == "utc" || ln == "z" || ln == "gmt" || ln == "universal" || ln == "zulu" || ln == "etc/utc" || ln == "etc/gmt" {
        let n = if ln == "utc" { "UTC".to_string() } else if ln == "z" { "Z".to_string() } else { name.to_string() };
        return Some(Zone { name: n, std: 0, dst: 0, sabbr: "UTC".into(), dabbr: "UTC".into(), rule: Rule::None, kind: 3 });
    }
    for (n, s, d, sa, da, r) in ZONES {
        if n.to_ascii_lowercase() == ln {
            return Some(Zone { name: n.to_string(), std: *s, dst: *d, sabbr: sa.to_string(), dabbr: da.to_string(), rule: *r, kind: 3 });
        }
    }
    // abbreviations
    let abbrs: &[(&str, i64, bool)] = &[("est", -18000, false), ("edt", -14400, true), ("cst", -21600, false), ("cdt", -18000, true), ("mst", -25200, false), ("mdt", -21600, true), ("pst", -28800, false), ("pdt", -25200, true), ("cet", 3600, false), ("cest", 7200, true), ("bst", 3600, true), ("eet", 7200, false), ("eest", 10800, true), ("jst", 32400, false)];
    for (a, off, dst) in abbrs {
        if *a == ln {
            return Some(Zone { name: a.to_ascii_uppercase(), std: *off, dst: *off, sabbr: a.to_ascii_uppercase(), dabbr: a.to_ascii_uppercase(), rule: Rule::None, kind: 2 + if *dst { 0 } else { 0 } });
        }
    }
    // offsets +hh:mm
    parse_offset(name).map(|off| Zone { name: fmt_offset(off, true), std: off, dst: off, sabbr: fmt_offset(off, true), dabbr: fmt_offset(off, true), rule: Rule::None, kind: 1 })
}

pub fn parse_offset(s: &str) -> Option<i64> {
    let b = s.as_bytes();
    if b.is_empty() || (b[0] != b'+' && b[0] != b'-') {
        return None;
    }
    let sign = if b[0] == b'-' { -1 } else { 1 };
    let rest: String = s[1..].chars().filter(|c| *c != ':').collect();
    if rest.is_empty() || !rest.chars().all(|c| c.is_ascii_digit()) {
        return None;
    }
    let (h, m) = match rest.len() {
        1 | 2 => (rest.parse::<i64>().ok()?, 0),
        3 => (rest[..1].parse::<i64>().ok()?, rest[1..].parse::<i64>().ok()?),
        4 => (rest[..2].parse::<i64>().ok()?, rest[2..].parse::<i64>().ok()?),
        _ => return None,
    };
    Some(sign * (h * 3600 + m * 60))
}

pub fn fmt_offset(off: i64, colon: bool) -> String {
    let sign = if off < 0 { '-' } else { '+' };
    let a = off.abs();
    if colon {
        format!("{}{:02}:{:02}", sign, a / 3600, (a % 3600) / 60)
    } else {
        format!("{}{:02}{:02}", sign, a / 3600, (a % 3600) / 60)
    }
}

fn nth_sunday(y: i64, m: i64, n: i64) -> i64 {
    // day number of nth Sunday (n>=1) ; n = -1 last
    if n > 0 {
        let first = days_from_civil(y, m, 1);
        let wd = weekday(first);
        let off = (7 - wd) % 7;
        first + off + (n - 1) * 7
    } else {
        let last = days_from_civil(y, m, days_in_month(y, m));
        let wd = weekday(last);
        last - wd
    }
}

impl Zone {
    pub fn utc() -> Zone {
        find_zone("UTC").unwrap()
    }
    /// is DST at utc timestamp
    fn is_dst(&self, ts: i64) -> bool {
        if self.rule == Rule::None || self.std == self.dst {
            return false;
        }
        let (y, _, _) = civil_from_days((ts + self.std).div_euclid(86400));
        match self.rule {
            Rule::Us => {
                let start = nth_sunday(y, 3, 2) * 86400 + 7200 - self.std;
                let end = nth_sunday(y, 11, 1) * 86400 + 7200 - self.dst;
                ts >= start && ts < end
            }
            Rule::Eu => {
                let start = nth_sunday(y, 3, -1) * 86400 + 3600;
                let end = nth_sunday(y, 10, -1) * 86400 + 3600;
                ts >= start && ts < end
            }
            Rule::Au => {
                let end = nth_sunday(y, 4, 1) * 86400 + 10800 - self.dst;
                let start = nth_sunday(y, 10, 1) * 86400 + 7200 - self.std;
                ts < end || ts >= start
            }
            Rule::Nz => {
                let end = nth_sunday(y, 4, 1) * 86400 + 10800 - self.dst;
                let start = nth_sunday(y, 9, -1) * 86400 + 7200 - self.std;
                ts < end || ts >= start
            }
            Rule::Eg => {
                if y < 2023 {
                    return false;
                }
                // last Friday of April 00:00 -> last Thursday of October 24:00
                let la = days_from_civil(y, 4, 30);
                let fri = la - (weekday(la) - 5).rem_euclid(7);
                let lo = days_from_civil(y, 10, 31);
                let thu = lo - (weekday(lo) - 4).rem_euclid(7);
                let start = fri * 86400 - self.std;
                let end = (thu + 1) * 86400 - self.dst;
                ts >= start && ts < end
            }
            Rule::None => false,
        }
    }
    pub fn offset_at(&self, ts: i64) -> (i64, bool, String) {
        if self.is_dst(ts) {
            (self.dst, true, self.dabbr.clone())
        } else {
            (self.std, false, self.sabbr.clone())
        }
    }
    /// convert local wall time (seconds since epoch as if UTC) to utc ts
    pub fn local_to_utc(&self, local: i64) -> i64 {
        let t1 = local - self.std;
        if self.is_dst(t1) {
            let t2 = local - self.dst;
            if self.is_dst(t2) {
                return t2;
            }
            // in gap: PHP moves forward
            return t1;
        }
        // could be ambiguous (overlap): prefer DST (first occurrence)
        let t2 = local - self.dst;
        if self.dst != self.std && self.is_dst(t2) {
            return t2;
        }
        t1
    }
}

pub struct Tm {
    pub y: i64,
    pub m: i64,
    pub d: i64,
    pub h: i64,
    pub i: i64,
    pub s: i64,
    pub wday: i64,
    pub yday: i64,
    pub off: i64,
    pub dst: bool,
    pub abbr: String,
}

pub fn to_tm(ts: i64, z: &Zone) -> Tm {
    let (off, dst, abbr) = z.offset_at(ts);
    let local = ts + off;
    let days = local.div_euclid(86400);
    let secs = local.rem_euclid(86400);
    let (y, m, d) = civil_from_days(days);
    Tm { y, m, d, h: secs / 3600, i: (secs % 3600) / 60, s: secs % 60, wday: weekday(days), yday: days - days_from_civil(y, 1, 1), off, dst, abbr }
}

fn iso_week(y: i64, yday: i64, wday: i64) -> (i64, i64) {
    let wd = if wday == 0 { 7 } else { wday };
    let w = (yday - wd + 10) / 7;
    if w < 1 {
        let py = y - 1;
        let pdays = if is_leap(py) { 366 } else { 365 };
        return iso_week(py, yday + pdays, wday);
    }
    let ydays = if is_leap(y) { 366 } else { 365 };
    if w == 53 && (ydays - yday) < (4 - (wd - 1)).max(0) + 0 && (yday - wd + 10) / 7 == 53 {
        // check if Dec 29-31 belongs to week 1 of next year
        let dec31_wd = (wd + (ydays - 1 - yday)) % 7;
        let dec31_wd = if dec31_wd == 0 { 7 } else { dec31_wd };
        if dec31_wd < 4 {
            return (y + 1, 1);
        }
    }
    if w == 53 {
        let dec31_wd = ((wd - 1) + (ydays - 1 - yday)) % 7 + 1;
        if dec31_wd < 4 {
            return (y + 1, 1);
        }
    }
    (y, w)
}

const DAYS: [&str; 7] = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
const MONTHS: [&str; 12] = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

pub fn format_date(fmt: &[u8], ts: i64, usec: i64, z: &Zone) -> Vec<u8> {
    let t = to_tm(ts, z);
    let mut out = String::new();
    let mut i = 0;
    while i < fmt.len() {
        let c = fmt[i] as char;
        match c {
            'd' => out.push_str(&format!("{:02}", t.d)),
            'D' => out.push_str(&DAYS[t.wday as usize][..3]),
            'j' => out.push_str(&t.d.to_string()),
            'l' => out.push_str(DAYS[t.wday as usize]),
            'N' => out.push_str(&(if t.wday == 0 { 7 } else { t.wday }).to_string()),
            'S' => out.push_str(match t.d {
                1 | 21 | 31 => "st",
                2 | 22 => "nd",
                3 | 23 => "rd",
                _ => "th",
            }),
            'w' => out.push_str(&t.wday.to_string()),
            'z' => out.push_str(&t.yday.to_string()),
            'W' => out.push_str(&format!("{:02}", iso_week(t.y, t.yday, t.wday).1)),
            'o' => out.push_str(&iso_week(t.y, t.yday, t.wday).0.to_string()),
            'F' => out.push_str(MONTHS[(t.m - 1) as usize]),
            'M' => out.push_str(&MONTHS[(t.m - 1) as usize][..3]),
            'm' => out.push_str(&format!("{:02}", t.m)),
            'n' => out.push_str(&t.m.to_string()),
            't' => out.push_str(&days_in_month(t.y, t.m).to_string()),
            'L' => out.push_str(if is_leap(t.y) { "1" } else { "0" }),
            'Y' => {
                if t.y < 0 {
                    out.push_str(&format!("-{:04}", -t.y));
                } else {
                    out.push_str(&format!("{:04}", t.y));
                }
            }
            'y' => out.push_str(&format!("{:02}", t.y.rem_euclid(100))),
            'X' | 'x' => {
                if c == 'X' || t.y >= 10000 || t.y < 0 {
                    out.push_str(&format!("{}{:04}", if t.y < 0 { "-" } else { "+" }, t.y.abs()));
                } else {
                    out.push_str(&format!("{:04}", t.y));
                }
            }
            'a' => out.push_str(if t.h < 12 { "am" } else { "pm" }),
            'A' => out.push_str(if t.h < 12 { "AM" } else { "PM" }),
            'B' => {
                let b = (((ts + 3600).rem_euclid(86400)) as f64 / 86.4) as i64 % 1000;
                out.push_str(&format!("{:03}", b));
            }
            'g' => out.push_str(&(if t.h % 12 == 0 { 12 } else { t.h % 12 }).to_string()),
            'G' => out.push_str(&t.h.to_string()),
            'h' => out.push_str(&format!("{:02}", if t.h % 12 == 0 { 12 } else { t.h % 12 })),
            'H' => out.push_str(&format!("{:02}", t.h)),
            'i' => out.push_str(&format!("{:02}", t.i)),
            's' => out.push_str(&format!("{:02}", t.s)),
            'u' => out.push_str(&format!("{:06}", usec)),
            'v' => out.push_str(&format!("{:03}", usec / 1000)),
            'e' => out.push_str(&z.name),
            'I' => out.push_str(if t.dst { "1" } else { "0" }),
            'O' => out.push_str(&fmt_offset(t.off, false)),
            'P' => out.push_str(&fmt_offset(t.off, true)),
            'p' => {
                if t.off == 0 {
                    out.push('Z');
                } else {
                    out.push_str(&fmt_offset(t.off, true));
                }
            }
            'T' => out.push_str(&t.abbr),
            'Z' => out.push_str(&t.off.to_string()),
            'c' => {
                let s = format_date(b"Y-m-d\\TH:i:sP", ts, usec, z);
                out.push_str(&String::from_utf8_lossy(&s));
            }
            'r' => {
                let s = format_date(b"D, d M Y H:i:s O", ts, usec, z);
                out.push_str(&String::from_utf8_lossy(&s));
            }
            'U' => out.push_str(&ts.to_string()),
            '\\' => {
                i += 1;
                if i < fmt.len() {
                    out.push(fmt[i] as char);
                }
            }
            _ => {
                // preserve raw bytes
                let mut b = out.into_bytes();
                b.push(fmt[i]);
                out = unsafe { String::from_utf8_unchecked(b) };
            }
        }
        i += 1;
    }
    out.into_bytes()
}

pub fn now_ts() -> (i64, i64) {
    let d = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap();
    (d.as_secs() as i64, d.subsec_micros() as i64)
}

pub fn default_zone(it: &Interp) -> Zone {
    find_zone(&it.timezone).unwrap_or_else(Zone::utc)
}

// ---------------- strtotime parser ----------------
pub struct DtState {
    pub y: i64,
    pub m: i64,
    pub d: i64,
    pub h: i64,
    pub i: i64,
    pub s: i64,
    pub us: i64,
    pub zone: Option<Zone>,
    pub have_time: bool,
    pub have_date: bool,
    pub rel: [i64; 7], // y m d h i s us
    pub weekday: Option<(i64, i64)>, // (weekday, behavior: 0 this/next, -1 last)
    pub special: Vec<String>,
    pub ts_set: Option<i64>,
}

fn month_from_name(w: &str) -> Option<i64> {
    let l = w.to_ascii_lowercase();
    let names = ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"];
    for (i, n) in names.iter().enumerate() {
        if l == *n || l == MONTHS[i].to_ascii_lowercase() || (l == "sept" && i == 8) {
            return Some(i as i64 + 1);
        }
    }
    None
}
fn day_from_name(w: &str) -> Option<i64> {
    let l = w.to_ascii_lowercase();
    for (i, n) in DAYS.iter().enumerate() {
        let nl = n.to_ascii_lowercase();
        if l == nl || l == nl[..3] || (l.len() >= 3 && nl.starts_with(&l) && l.len() <= nl.len()) {
            return Some(i as i64);
        }
    }
    None
}
fn unit_of(w: &str) -> Option<usize> {
    let l = w.to_ascii_lowercase();
    let l = l.trim_end_matches('s');
    Some(match l {
        "year" | "yr" => 0,
        "month" | "mon" => 1,
        "day" => 2,
        "week" | "wk" => 7,
        "fortnight" | "forthnight" => 8,
        "hour" | "hr" => 3,
        "minute" | "min" => 4,
        "second" | "sec" => 5,
        "microsecond" | "usec" | "µsec" | "µ" => 6,
        "millisecond" | "msec" | "m" => 9,
        "weekday" => 10,
        _ => return None,
    })
}

struct Tok {
    s: String,
    kind: u8, // n number, w word, p punct
}

fn tokenize(s: &str) -> Vec<Tok> {
    let mut out = Vec::new();
    let b: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < b.len() {
        let c = b[i];
        if c.is_whitespace() || c == ',' {
            i += 1;
            continue;
        }
        if c.is_ascii_digit() {
            let st = i;
            while i < b.len() && b[i].is_ascii_digit() {
                i += 1;
            }
            out.push(Tok { s: b[st..i].iter().collect(), kind: b'n' });
            continue;
        }
        if c.is_alphabetic() {
            let st = i;
            while i < b.len() && (b[i].is_alphabetic() || b[i] == '_' || (b[i] == '/' && i + 1 < b.len() && b[i + 1].is_alphabetic())) {
                i += 1;
            }
            out.push(Tok { s: b[st..i].iter().collect(), kind: b'w' });
            continue;
        }
        out.push(Tok { s: c.to_string(), kind: b'p' });
        i += 1;
    }
    out
}

pub fn parse_datetime(input: &str, st: &mut DtState) -> bool {
    let s = input.trim();
    if s.is_empty() {
        return true;
    }
    if let Some(rest) = s.strip_prefix('@') {
        let (num, frac) = match rest.split_once('.') {
            Some((a, b)) => (a, Some(b)),
            None => (rest, None),
        };
        if let Ok(v) = num.trim().parse::<i64>() {
            st.ts_set = Some(v);
            if let Some(f) = frac {
                let f6 = format!("{:0<6}", f);
                st.us = f6[..6].parse().unwrap_or(0);
            }
            st.zone = Some(Zone { name: "+00:00".into(), std: 0, dst: 0, sabbr: "+00:00".into(), dabbr: "+00:00".into(), rule: Rule::None, kind: 1 });
            return true;
        }
        return false;
    }
    let toks = tokenize(s);
    let n = toks.len();
    let mut i = 0;
    let num = |t: &Tok| -> Option<i64> {
        if t.kind == b'n' {
            t.s.parse().ok()
        } else {
            None
        }
    };
    let is_p = |i: usize, c: &str| -> bool { i < n && toks[i].kind == b'p' && toks[i].s == c };
    while i < n {
        let t = &toks[i];
        // ISO date YYYY-MM-DD
        if t.kind == b'n' && t.s.len() == 4 && is_p(i + 1, "-") && i + 2 < n && toks[i + 2].kind == b'n' && is_p(i + 3, "-") && i + 4 < n && toks[i + 4].kind == b'n' {
            st.y = num(t).unwrap();
            st.m = num(&toks[i + 2]).unwrap();
            st.d = num(&toks[i + 4]).unwrap();
            st.have_date = true;
            i += 5;
            if i < n && toks[i].kind == b'w' && (toks[i].s == "T" || toks[i].s == "t") {
                i += 1;
            }
            continue;
        }
        // YYYY-MM
        if t.kind == b'n' && t.s.len() == 4 && is_p(i + 1, "-") && i + 2 < n && toks[i + 2].kind == b'n' && !is_p(i + 3, "-") && !is_p(i + 3, ":") {
            st.y = num(t).unwrap();
            st.m = num(&toks[i + 2]).unwrap();
            st.d = 1;
            st.have_date = true;
            i += 3;
            continue;
        }
        // YYYY/MM/DD
        if t.kind == b'n' && t.s.len() == 4 && is_p(i + 1, "/") && i + 4 < n && is_p(i + 3, "/") {
            st.y = num(t).unwrap();
            st.m = num(&toks[i + 2]).unwrap_or(1);
            st.d = num(&toks[i + 4]).unwrap_or(1);
            st.have_date = true;
            i += 5;
            continue;
        }
        // MM/DD/YYYY or MM/DD
        if t.kind == b'n' && t.s.len() <= 2 && is_p(i + 1, "/") && i + 2 < n && toks[i + 2].kind == b'n' {
            st.m = num(t).unwrap();
            st.d = num(&toks[i + 2]).unwrap();
            if is_p(i + 3, "/") && i + 4 < n && toks[i + 4].kind == b'n' {
                let mut y = num(&toks[i + 4]).unwrap();
                if toks[i + 4].s.len() <= 2 {
                    y += if y < 70 { 2000 } else { 1900 };
                }
                st.y = y;
                i += 5;
            } else {
                i += 3;
            }
            st.have_date = true;
            continue;
        }
        // DD-MM-YYYY or DD.MM.YYYY
        if t.kind == b'n' && t.s.len() <= 2 && (is_p(i + 1, "-") || is_p(i + 1, ".")) && i + 4 < n && toks[i + 2].kind == b'n' && (is_p(i + 3, "-") || is_p(i + 3, ".")) && toks[i + 4].kind == b'n' && toks[i + 4].s.len() == 4 {
            st.d = num(t).unwrap();
            st.m = num(&toks[i + 2]).unwrap();
            st.y = num(&toks[i + 4]).unwrap();
            st.have_date = true;
            i += 5;
            continue;
        }
        // DD-Mon-YYYY
        if t.kind == b'n' && is_p(i + 1, "-") && i + 2 < n && toks[i + 2].kind == b'w' && month_from_name(&toks[i + 2].s).is_some() {
            st.d = num(t).unwrap();
            st.m = month_from_name(&toks[i + 2].s).unwrap();
            i += 3;
            if is_p(i, "-") && i + 1 < n && toks[i + 1].kind == b'n' {
                st.y = num(&toks[i + 1]).unwrap();
                i += 2;
            }
            st.have_date = true;
            continue;
        }
        // time HH:MM[:SS[.frac]] [am|pm]
        if t.kind == b'n' && is_p(i + 1, ":") && i + 2 < n && toks[i + 2].kind == b'n' {
            st.h = num(t).unwrap();
            st.i = num(&toks[i + 2]).unwrap();
            st.s = 0;
            i += 3;
            if is_p(i, ":") && i + 1 < n && toks[i + 1].kind == b'n' {
                st.s = num(&toks[i + 1]).unwrap();
                i += 2;
                if is_p(i, ".") && i + 1 < n && toks[i + 1].kind == b'n' {
                    let f = format!("{:0<6}", toks[i + 1].s);
                    st.us = f[..6].parse().unwrap_or(0);
                    i += 2;
                }
            }
            if i < n && toks[i].kind == b'w' {
                let w = toks[i].s.to_ascii_lowercase();
                if w == "am" || w == "pm" || w == "a" || w == "p" {
                    if w.starts_with('p') && st.h < 12 {
                        st.h += 12;
                    }
                    if w.starts_with('a') && st.h == 12 {
                        st.h = 0;
                    }
                    i += 1;
                    if is_p(i, ".") {
                        i += 1;
                    }
                }
            }
            st.have_time = true;
            continue;
        }
        // number followed by am/pm
        if t.kind == b'n' && i + 1 < n && toks[i + 1].kind == b'w' && matches!(toks[i + 1].s.to_ascii_lowercase().as_str(), "am" | "pm") {
            let mut h = num(t).unwrap();
            let pm = toks[i + 1].s.to_ascii_lowercase() == "pm";
            if pm && h < 12 {
                h += 12;
            }
            if !pm && h == 12 {
                h = 0;
            }
            st.h = h;
            st.i = 0;
            st.s = 0;
            st.have_time = true;
            i += 2;
            continue;
        }
        // relative: [+-]N unit
        if (t.kind == b'p' && (t.s == "+" || t.s == "-")) || (t.kind == b'n' && i + 1 < n && toks[i + 1].kind == b'w' && unit_of(&toks[i + 1].s).is_some()) {
            let (sign, j) = if t.kind == b'p' { (if t.s == "-" { -1 } else { 1 }, i + 1) } else { (1, i) };
            if j < n && toks[j].kind == b'n' && j + 1 < n && toks[j + 1].kind == b'w' {
                if let Some(u) = unit_of(&toks[j + 1].s) {
                    let mut v = sign * num(&toks[j]).unwrap();
                    let mut k = j + 2;
                    if k < n && toks[k].kind == b'w' && toks[k].s.eq_ignore_ascii_case("ago") {
                        v = -v;
                        k += 1;
                    }
                    add_rel(st, u, v);
                    i = k;
                    continue;
                }
            }
            if t.kind == b'p' && j < n && toks[j].kind == b'n' && (toks[j].s.len() == 4 || toks[j].s.len() == 2) && j + 1 >= n {
                // timezone offset
                let off = parse_offset(&format!("{}{}", t.s, toks[j].s));
                if let Some(o) = off {
                    st.zone = Some(Zone { name: fmt_offset(o, true), std: o, dst: o, sabbr: fmt_offset(o, true), dabbr: fmt_offset(o, true), rule: Rule::None, kind: 1 });
                    i = j + 1;
                    continue;
                }
            }
            if t.kind == b'p' && j < n && toks[j].kind == b'n' && is_p(j + 1, ":") && j + 2 < n {
                let off = parse_offset(&format!("{}{}:{}", t.s, toks[j].s, toks[j + 2].s));
                if let Some(o) = off {
                    st.zone = Some(Zone { name: fmt_offset(o, true), std: o, dst: o, sabbr: fmt_offset(o, true), dabbr: fmt_offset(o, true), rule: Rule::None, kind: 1 });
                    i = j + 3;
                    continue;
                }
            }
            if t.kind == b'p' {
                i += 1;
                continue;
            }
        }
        if t.kind == b'w' {
            let w = t.s.to_ascii_lowercase();
            match w.as_str() {
                "now" => {
                    i += 1;
                    continue;
                }
                "today" | "midnight" => {
                    st.special.push("today".into());
                    i += 1;
                    continue;
                }
                "noon" => {
                    st.special.push("today".into());
                    st.h = 12;
                    st.have_time = true;
                    i += 1;
                    continue;
                }
                "tomorrow" => {
                    st.special.push("today".into());
                    st.rel[2] += 1;
                    i += 1;
                    continue;
                }
                "yesterday" => {
                    st.special.push("today".into());
                    st.rel[2] -= 1;
                    i += 1;
                    continue;
                }
                "next" | "last" | "previous" | "this" => {
                    let amount = match w.as_str() {
                        "next" => 1,
                        "this" => 0,
                        _ => -1,
                    };
                    if i + 1 < n && toks[i + 1].kind == b'w' {
                        let w2 = toks[i + 1].s.to_ascii_lowercase();
                        if let Some(u) = unit_of(&w2) {
                            add_rel(st, u, amount);
                            i += 2;
                            continue;
                        }
                        if let Some(d) = day_from_name(&w2) {
                            st.weekday = Some((d, amount));
                            st.special.push("today".into());
                            i += 2;
                            continue;
                        }
                    }
                    i += 1;
                    continue;
                }
                "first" | "last_day" => {}
                "ago" => {
                    for r in st.rel.iter_mut() {
                        *r = -*r;
                    }
                    i += 1;
                    continue;
                }
                "t" => {
                    i += 1;
                    continue;
                }
                "z" | "utc" | "gmt" => {
                    st.zone = find_zone(&t.s);
                    i += 1;
                    continue;
                }
                _ => {}
            }
            // "first day of" / "last day of"
            if (w == "first" || w == "last") && i + 2 < n && toks[i + 1].s.eq_ignore_ascii_case("day") && toks[i + 2].s.eq_ignore_ascii_case("of") {
                st.special.push(if w == "first" { "first_day_of".into() } else { "last_day_of".into() });
                i += 3;
                continue;
            }
            if let Some(m) = month_from_name(&w) {
                st.m = m;
                st.have_date = true;
                i += 1;
                if i < n && toks[i].kind == b'n' {
                    let v = num(&toks[i]).unwrap();
                    if toks[i].s.len() == 4 {
                        st.y = v;
                        st.d = 1;
                        i += 1;
                    } else {
                        st.d = v;
                        i += 1;
                        if i < n && toks[i].kind == b'w' && matches!(toks[i].s.to_ascii_lowercase().as_str(), "st" | "nd" | "rd" | "th") {
                            i += 1;
                        }
                        if i < n && toks[i].kind == b'n' && toks[i].s.len() == 4 {
                            st.y = num(&toks[i]).unwrap();
                            i += 1;
                        }
                    }
                } else {
                    st.d = 1;
                }
                continue;
            }
            if let Some(d) = day_from_name(&w) {
                st.weekday = Some((d, 0));
                st.special.push("today".into());
                i += 1;
                continue;
            }
            if let Some(z) = find_zone(&t.s) {
                st.zone = Some(z);
                i += 1;
                continue;
            }
            return false;
        }
        // "15 January 2024"
        if t.kind == b'n' && i + 1 < n && toks[i + 1].kind == b'w' {
            let mut j = i + 1;
            if matches!(toks[j].s.to_ascii_lowercase().as_str(), "st" | "nd" | "rd" | "th") {
                j += 1;
            }
            if j < n && toks[j].kind == b'w' {
                if let Some(m) = month_from_name(&toks[j].s) {
                    st.d = num(t).unwrap();
                    st.m = m;
                    st.have_date = true;
                    i = j + 1;
                    if i < n && toks[i].kind == b'n' && toks[i].s.len() == 4 {
                        st.y = num(&toks[i]).unwrap();
                        i += 1;
                    }
                    continue;
                }
            }
        }
        // YYYYMMDD
        if t.kind == b'n' && t.s.len() == 8 {
            let v = &t.s;
            st.y = v[..4].parse().unwrap();
            st.m = v[4..6].parse().unwrap();
            st.d = v[6..8].parse().unwrap();
            st.have_date = true;
            i += 1;
            continue;
        }
        // lone 4-digit year
        if t.kind == b'n' && t.s.len() == 4 && st.have_date {
            st.y = num(t).unwrap();
            i += 1;
            continue;
        }
        return false;
    }
    true
}

fn add_rel(st: &mut DtState, u: usize, v: i64) {
    match u {
        7 => st.rel[2] += v * 7,
        8 => st.rel[2] += v * 14,
        9 => st.rel[6] += v * 1000,
        10 => st.rel[2] += v, // weekday approx
        _ => st.rel[u] += v,
    }
}

/// resolve state against base time; returns (ts, usec, zone)
pub fn resolve(st: &DtState, base_ts: i64, base_us: i64, base_zone: &Zone) -> (i64, i64, Zone) {
    let zone = st.zone.clone().unwrap_or_else(|| base_zone.clone());
    if let Some(t) = st.ts_set {
        let mut ts = t;
        ts += st.rel[5] + st.rel[4] * 60 + st.rel[3] * 3600 + st.rel[2] * 86400;
        return (ts, st.us, zone);
    }
    let bt = to_tm(base_ts, &zone);
    let mut y = bt.y;
    let mut m = bt.m;
    let mut d = bt.d;
    let mut h = bt.h;
    let mut mi = bt.i;
    let mut s = bt.s;
    let mut us = base_us;
    let today = st.special.iter().any(|x| x == "today");
    if st.have_date {
        y = st.y;
        m = st.m;
        d = st.d;
        if !st.have_time {
            h = 0;
            mi = 0;
            s = 0;
            us = 0;
        }
    }
    if today && !st.have_time {
        h = 0;
        mi = 0;
        s = 0;
        us = 0;
    }
    if st.have_time {
        h = st.h;
        mi = st.i;
        s = st.s;
        us = st.us;
    }
    // relative units
    y += st.rel[0];
    m += st.rel[1];
    // normalize month
    let mut mm = m - 1;
    y += mm.div_euclid(12);
    mm = mm.rem_euclid(12);
    m = mm + 1;
    if st.special.iter().any(|x| x == "first_day_of") {
        d = 1;
        if !st.have_time {
            h = 0;
            mi = 0;
            s = 0;
        }
    }
    if st.special.iter().any(|x| x == "last_day_of") {
        d = days_in_month(y, m);
        if !st.have_time {
            h = 0;
            mi = 0;
            s = 0;
        }
    }
    let mut days = days_from_civil(y, m, 1) + d - 1 + st.rel[2];
    if let Some((wd, behavior)) = st.weekday {
        let cur = weekday(days);
        let diff = (wd - cur).rem_euclid(7);
        if behavior == 1 {
            days += if diff == 0 { 7 } else { diff };
        } else if behavior == -1 {
            let back = (cur - wd).rem_euclid(7);
            days -= if back == 0 { 7 } else { back };
        } else {
            days += diff;
        }
    }
    let local = days * 86400 + h * 3600 + mi * 60 + s + st.rel[3] * 3600 + st.rel[4] * 60 + st.rel[5];
    let mut us_total = us + st.rel[6];
    let mut local = local;
    local += us_total.div_euclid(1_000_000);
    us_total = us_total.rem_euclid(1_000_000);
    let ts = zone.local_to_utc(local);
    (ts, us_total, zone)
}

pub fn new_state() -> DtState {
    DtState { y: 1970, m: 1, d: 1, h: 0, i: 0, s: 0, us: 0, zone: None, have_time: false, have_date: false, rel: [0; 7], weekday: None, special: Vec::new(), ts_set: None }
}

pub fn strtotime(it: &Interp, s: &str, base: i64) -> Option<(i64, i64, Zone)> {
    let mut st = new_state();
    if !parse_datetime(s, &mut st) {
        return None;
    }
    let z = default_zone(it);
    Some(resolve(&st, base, 0, &z))
}

// ---------------- builtins ----------------
fn f_time(_it: &mut Interp, _a: &mut Args) -> R<Value> {
    Ok(Value::Int(now_ts().0))
}
fn f_microtime(it: &mut Interp, a: &mut Args) -> R<Value> {
    let d = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap();
    if a.bool_or(it, 0, false)? {
        return Ok(Value::Float(d.as_secs_f64()));
    }
    Ok(Value::string(format!("{:.8} {}", d.subsec_micros() as f64 / 1e6, d.as_secs())))
}
fn f_date(it: &mut Interp, a: &mut Args) -> R<Value> {
    let f = a.str(it, 0)?;
    let ts = match a.opt_int(it, 1)? {
        Some(t) => t,
        None => now_ts().0,
    };
    let z = default_zone(it);
    Ok(Value::vec(format_date(&f, ts, 0, &z)))
}
fn f_gmdate(it: &mut Interp, a: &mut Args) -> R<Value> {
    let f = a.str(it, 0)?;
    let ts = match a.opt_int(it, 1)? {
        Some(t) => t,
        None => now_ts().0,
    };
    let mut z = Zone::utc();
    z.name = "UTC".into();
    let out = format_date(&f, ts, 0, &z);
    Ok(Value::vec(out))
}
fn f_idate(it: &mut Interp, a: &mut Args) -> R<Value> {
    let f = a.str(it, 0)?;
    let ts = a.opt_int(it, 1)?.unwrap_or(now_ts().0);
    let z = default_zone(it);
    let s = format_date(&f, ts, 0, &z);
    Ok(Value::Int(String::from_utf8_lossy(&s).parse().unwrap_or(0)))
}
fn mktime_impl(it: &mut Interp, a: &mut Args, gmt: bool) -> R<Value> {
    let z = if gmt { Zone::utc() } else { default_zone(it) };
    let (now, _) = now_ts();
    let t = to_tm(now, &z);
    let h = a.opt_int(it, 0)?.unwrap_or(t.h);
    let mi = a.opt_int(it, 1)?.unwrap_or(t.i);
    let s = a.opt_int(it, 2)?.unwrap_or(t.s);
    let mo = a.opt_int(it, 3)?.unwrap_or(t.m);
    let d = a.opt_int(it, 4)?.unwrap_or(t.d);
    let mut y = a.opt_int(it, 5)?.unwrap_or(t.y);
    if a.has(5) {
        if (0..70).contains(&y) {
            y += 2000;
        } else if (70..=100).contains(&y) {
            y += 1900;
        }
    }
    let mm = mo - 1;
    let yy = y + mm.div_euclid(12);
    let mm = mm.rem_euclid(12) + 1;
    let days = days_from_civil(yy, mm, 1) + d - 1;
    let local = days * 86400 + h * 3600 + mi * 60 + s;
    Ok(Value::Int(z.local_to_utc(local)))
}
fn f_mktime(it: &mut Interp, a: &mut Args) -> R<Value> {
    mktime_impl(it, a, false)
}
fn f_gmmktime(it: &mut Interp, a: &mut Args) -> R<Value> {
    mktime_impl(it, a, true)
}
fn f_checkdate(it: &mut Interp, a: &mut Args) -> R<Value> {
    let m = a.int(it, 0)?;
    let d = a.int(it, 1)?;
    let y = a.int(it, 2)?;
    Ok(Value::Bool(m >= 1 && m <= 12 && d >= 1 && y >= 1 && y <= 32767 && d <= days_in_month(y, m)))
}
fn f_strtotime(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let base = a.opt_int(it, 1)?.unwrap_or(now_ts().0);
    match strtotime(it, &String::from_utf8_lossy(&s), base) {
        Some((ts, _, _)) => Ok(Value::Int(ts)),
        None => Ok(Value::Bool(false)),
    }
}
fn f_date_default_timezone_set(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let n = String::from_utf8_lossy(&s).to_string();
    match find_zone(&n) {
        Some(z) if z.kind == 3 => {
            it.timezone = z.name.clone();
            Ok(Value::Bool(true))
        }
        _ => {
            it.notice(&format!("date_default_timezone_set(): Timezone ID '{}' is invalid", n))?;
            Ok(Value::Bool(false))
        }
    }
}
fn f_date_default_timezone_get(it: &mut Interp, _a: &mut Args) -> R<Value> {
    Ok(Value::str(&it.timezone))
}
fn tm_array(t: &Tm, ts: i64, assoc_names: bool) -> PArray {
    let mut out = PArray::new();
    if assoc_names {
        out.set(Key::Str(pstr("seconds")), Value::Int(t.s));
        out.set(Key::Str(pstr("minutes")), Value::Int(t.i));
        out.set(Key::Str(pstr("hours")), Value::Int(t.h));
        out.set(Key::Str(pstr("mday")), Value::Int(t.d));
        out.set(Key::Str(pstr("wday")), Value::Int(t.wday));
        out.set(Key::Str(pstr("mon")), Value::Int(t.m));
        out.set(Key::Str(pstr("year")), Value::Int(t.y));
        out.set(Key::Str(pstr("yday")), Value::Int(t.yday));
        out.set(Key::Str(pstr("weekday")), Value::str(DAYS[t.wday as usize]));
        out.set(Key::Str(pstr("month")), Value::str(MONTHS[(t.m - 1) as usize]));
        out.set(Key::Int(0), Value::Int(ts));
    }
    out
}
fn f_getdate(it: &mut Interp, a: &mut Args) -> R<Value> {
    let ts = a.opt_int(it, 0)?.unwrap_or(now_ts().0);
    let z = default_zone(it);
    let t = to_tm(ts, &z);
    Ok(Value::arr(tm_array(&t, ts, true)))
}
fn f_localtime(it: &mut Interp, a: &mut Args) -> R<Value> {
    let ts = a.opt_int(it, 0)?.unwrap_or(now_ts().0);
    let assoc = a.bool_or(it, 1, false)?;
    let z = default_zone(it);
    let t = to_tm(ts, &z);
    let vals = [t.s, t.i, t.h, t.d, t.m - 1, t.y - 1900, t.wday, t.yday, t.dst as i64];
    let names = ["tm_sec", "tm_min", "tm_hour", "tm_mday", "tm_mon", "tm_year", "tm_wday", "tm_yday", "tm_isdst"];
    let mut out = PArray::new();
    for (i, v) in vals.iter().enumerate() {
        if assoc {
            out.set(Key::Str(pstr(names[i])), Value::Int(*v));
        } else {
            out.push(Value::Int(*v));
        }
    }
    Ok(Value::arr(out))
}
fn f_date_parse(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let mut st = new_state();
    let ok = parse_datetime(&String::from_utf8_lossy(&s), &mut st);
    let mut out = PArray::new();
    let fv = |b: bool, v: i64| if b { Value::Int(v) } else { Value::Bool(false) };
    out.set(Key::Str(pstr("year")), fv(st.have_date, st.y));
    out.set(Key::Str(pstr("month")), fv(st.have_date, st.m));
    out.set(Key::Str(pstr("day")), fv(st.have_date, st.d));
    out.set(Key::Str(pstr("hour")), fv(st.have_time, st.h));
    out.set(Key::Str(pstr("minute")), fv(st.have_time, st.i));
    out.set(Key::Str(pstr("second")), fv(st.have_time, st.s));
    out.set(Key::Str(pstr("fraction")), if st.have_time { Value::Float(st.us as f64 / 1e6) } else { Value::Bool(false) });
    out.set(Key::Str(pstr("warning_count")), Value::Int(0));
    out.set(Key::Str(pstr("warnings")), Value::empty_array());
    out.set(Key::Str(pstr("error_count")), Value::Int(if ok { 0 } else { 1 }));
    out.set(Key::Str(pstr("errors")), Value::empty_array());
    out.set(Key::Str(pstr("is_localtime")), Value::Bool(st.zone.is_some()));
    Ok(Value::arr(out))
}

// helpers for prelude DateTime implementation
// __dt_parse(string, tzname|null, base_ts|null) -> [ts, us, tzname, tztype] | false
fn f_dt_parse(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let z = match a.opt_str(it, 1)? {
        Some(n) => find_zone(&String::from_utf8_lossy(&n)).unwrap_or_else(|| default_zone(it)),
        None => default_zone(it),
    };
    let (bts, bus) = match a.opt_int(it, 2)? {
        Some(t) => (t, a.int_or(it, 3, 0)?),
        None => now_ts(),
    };
    let mut st = new_state();
    if !parse_datetime(&String::from_utf8_lossy(&s), &mut st) {
        return Ok(Value::Bool(false));
    }
    let (ts, us, zone) = resolve(&st, bts, bus, &z);
    Ok(Value::arr(PArray::from_values(vec![Value::Int(ts), Value::Int(us), Value::str(&zone.name), Value::Int(zone.kind as i64)])))
}
fn f_dt_format(it: &mut Interp, a: &mut Args) -> R<Value> {
    let f = a.str(it, 0)?;
    let ts = a.int(it, 1)?;
    let us = a.int(it, 2)?;
    let zn = a.str(it, 3)?;
    let z = find_zone(&String::from_utf8_lossy(&zn)).unwrap_or_else(Zone::utc);
    Ok(Value::vec(format_date(&f, ts, us, &z)))
}
fn f_dt_valid_tz(it: &mut Interp, a: &mut Args) -> R<Value> {
    let zn = a.str(it, 0)?;
    Ok(match find_zone(&String::from_utf8_lossy(&zn)) {
        Some(z) => Value::arr(PArray::from_values(vec![Value::str(&z.name), Value::Int(z.kind as i64)])),
        None => Value::Bool(false),
    })
}
fn f_dt_tz_offset(it: &mut Interp, a: &mut Args) -> R<Value> {
    let zn = a.str(it, 0)?;
    let ts = a.int(it, 1)?;
    let z = find_zone(&String::from_utf8_lossy(&zn)).unwrap_or_else(Zone::utc);
    Ok(Value::Int(z.offset_at(ts).0))
}
// local components: __dt_parts(ts, tz) -> [y,m,d,h,i,s]
fn f_dt_parts(it: &mut Interp, a: &mut Args) -> R<Value> {
    let ts = a.int(it, 0)?;
    let zn = a.str(it, 1)?;
    let z = find_zone(&String::from_utf8_lossy(&zn)).unwrap_or_else(Zone::utc);
    let t = to_tm(ts, &z);
    Ok(Value::arr(PArray::from_values(vec![Value::Int(t.y), Value::Int(t.m), Value::Int(t.d), Value::Int(t.h), Value::Int(t.i), Value::Int(t.s), Value::Int(t.wday)])))
}
// __dt_make(y,m,d,h,i,s,tz) -> ts (with normalization)
fn f_dt_make(it: &mut Interp, a: &mut Args) -> R<Value> {
    let y = a.int(it, 0)?;
    let m = a.int(it, 1)?;
    let d = a.int(it, 2)?;
    let h = a.int(it, 3)?;
    let mi = a.int(it, 4)?;
    let s = a.int(it, 5)?;
    let zn = a.str(it, 6)?;
    let z = find_zone(&String::from_utf8_lossy(&zn)).unwrap_or_else(Zone::utc);
    let mm = m - 1;
    let yy = y + mm.div_euclid(12);
    let mm = mm.rem_euclid(12) + 1;
    let days = days_from_civil(yy, mm, 1) + d - 1;
    let local = days * 86400 + h * 3600 + mi * 60 + s;
    Ok(Value::Int(z.local_to_utc(local)))
}
fn f_dt_days_in_month(it: &mut Interp, a: &mut Args) -> R<Value> {
    let y = a.int(it, 0)?;
    let m = a.int(it, 1)?;
    Ok(Value::Int(days_in_month(y, m)))
}
fn f_dt_days(it: &mut Interp, a: &mut Args) -> R<Value> {
    let y = a.int(it, 0)?;
    let m = a.int(it, 1)?;
    let d = a.int(it, 2)?;
    Ok(Value::Int(days_from_civil(y, m, d)))
}
fn f_timezone_identifiers_list(_it: &mut Interp, _a: &mut Args) -> R<Value> {
    let mut v: Vec<&str> = ZONES.iter().map(|z| z.0).collect();
    v.sort();
    Ok(Value::arr(PArray::from_values(v.into_iter().map(Value::str).collect())))
}
fn f_strftime(it: &mut Interp, a: &mut Args) -> R<Value> {
    let f = a.str(it, 0)?;
    let ts = a.opt_int(it, 1)?.unwrap_or(now_ts().0);
    let z = default_zone(it);
    let mut out = Vec::new();
    let mut i = 0;
    while i < f.len() {
        if f[i] == b'%' && i + 1 < f.len() {
            let c = f[i + 1];
            let map: &[u8] = match c {
                b'Y' => b"Y",
                b'y' => b"y",
                b'm' => b"m",
                b'd' => b"d",
                b'e' => b"j",
                b'H' => b"H",
                b'I' => b"h",
                b'M' => b"i",
                b'S' => b"s",
                b'p' => b"A",
                b'A' => b"l",
                b'a' => b"D",
                b'B' => b"F",
                b'b' | b'h' => b"M",
                b'j' => b"z",
                b'Z' => b"T",
                b'z' => b"O",
                b'u' => b"N",
                b'w' => b"w",
                b'%' => b"\\%",
                b'D' => b"m/d/y",
                b'F' => b"Y-m-d",
                b'T' => b"H:i:s",
                b'R' => b"H:i",
                _ => b"",
            };
            if c == b'j' {
                let t = to_tm(ts, &z);
                out.extend_from_slice(format!("{:03}", t.yday + 1).as_bytes());
            } else if c == b'e' {
                let t = to_tm(ts, &z);
                out.extend_from_slice(format!("{:2}", t.d).as_bytes());
            } else {
                out.extend_from_slice(&format_date(map, ts, 0, &z));
            }
            i += 2;
        } else {
            out.push(f[i]);
            i += 1;
        }
    }
    it.deprecated("Function strftime() is deprecated since 8.1, use IntlDateFormatter::format() instead")?;
    Ok(Value::vec(out))
}

