    ("Asia/Tehran", 12600, 12600, "+0330", "+0330", Rule::None),
    ("Asia/Riyadh", 10800, 10800, "+03", "+03", Rule::None),
    ("Asia/Jerusalem", 7200, 10800, "IST", "IDT", Rule::Eu),
    ("Australia/Sydney", 36000, 39600, "AEST", "AEDT", Rule::Au),
    ("Australia/Melbourne", 36000, 39600, "AEST", "AEDT", Rule::Au),
    ("Australia/Hobart", 36000, 39600, "AEST", "AEDT", Rule::Au),
    ("Australia/Brisbane", 36000, 36000, "AEST", "AEST", Rule::None),
    ("Australia/Adelaide", 34200, 37800, "ACST", "ACDT", Rule::Au),
