pub fn find_zone(name: &str) -> Option<Zone> {
    let ln = name.to_ascii_lowercase();
    if ln == "utc" || ln == "z" || ln == "gmt" || ln == "universal" || ln == "zulu" || ln == "etc/utc" || ln == "etc/gmt" {
        let n = if ln == "utc" { "UTC".to_string() } else if ln == "z" { "Z".to_string() } else { name.to_string() };
        return Some(Zone { name: n, std: 0, dst: 0, sabbr: "UTC".into(), dabbr: "UTC".into(), rule: Rule::None, kind: 3 });
    }
    for (n, s, d, sa, da, r) in ZONES {
        if n.to_ascii_lowercase() == ln {
            return Some(Zone { name: n.to_string(), std: *s, dst: *d, sabbr: sa.to_string(), dabbr: da.to_string(), rule: *r, kind: 3 });
        }
    }
    // abbreviations
    let abbrs: &[(&str, i64, bool)] = &[("est", -18000, false), ("edt", -14400, true), ("cst", -21600, false), ("cdt", -18000, true), ("mst", -25200, false), ("mdt", -21600, true), ("pst", -28800, false), ("pdt", -25200, true), ("cet", 3600, false), ("cest", 7200, true), ("bst", 3600, true), ("eet", 7200, false), ("eest", 10800, true), ("jst", 32400, false)];
    for (a, off, dst) in abbrs {
        if *a == ln {
            return Some(Zone { name: a.to_ascii_uppercase(), std: *off, dst: *off, sabbr: a.to_ascii_uppercase(), dabbr: a.to_ascii_uppercase(), rule: Rule::None, kind: 2 + if *dst { 0 } else { 0 } });
        }
    }
    // offsets +hh:mm
    parse_offset(name).map(|off| Zone { name: fmt_offset(off, true), std: off, dst: off, sabbr: fmt_offset(off, true), dabbr: fmt_offset(off, true), rule: Rule::None, kind: 1 })
}

pub fn parse_offset(s: &str) -> Option<i64> {
    let b = s.as_bytes();
    if b.is_empty() || (b[0] != b'+' && b[0] != b'-') {
        return None;
    }
    let sign = if b[0] == b'-' { -1 } else { 1 };
    let rest: String = s[1..].chars().filter(|c| *c != ':').collect();
    if rest.is_empty() || !rest.chars().all(|c| c.is_ascii_digit()) {
        return None;
    }
    let (h, m) = match rest.len() {
        1 | 2 => (rest.parse::<i64>().ok()?, 0),
        3 => (rest[..1].parse::<i64>().ok()?, rest[1..].parse::<i64>().ok()?),
        4 => (rest[..2].parse::<i64>().ok()?, rest[2..].parse::<i64>().ok()?),
        _ => return None,
    };
    Some(sign * (h * 3600 + m * 60))
}

pub fn fmt_offset(off: i64, colon: bool) -> String {
    let sign = if off < 0 { '-' } else { '+' };
    let a = off.abs();
    if colon {
        format!("{}{:02}:{:02}", sign, a / 3600, (a % 3600) / 60)
    } else {
        format!("{}{:02}{:02}", sign, a / 3600, (a % 3600) / 60)
    }
}

fn nth_sunday(y: i64, m: i64, n: i64) -> i64 {
    // day number of nth Sunday (n>=1) ; n = -1 last
    if n > 0 {
        let first = days_from_civil(y, m, 1);
        let wd = weekday(first);
        let off = (7 - wd) % 7;
        first + off + (n - 1) * 7
    } else {
        let last = days_from_civil(y, m, days_in_month(y, m));
        let wd = weekday(last);
        last - wd
    }
}

impl Zone {
    pub fn utc() -> Zone {
        find_zone("UTC").unwrap()
    }
    /// is DST at utc timestamp
    fn is_dst(&self, ts: i64) -> bool {
        if self.rule == Rule::None || self.std == self.dst {
            return false;
        }
        let (y, _, _) = civil_from_days((ts + self.std).div_euclid(86400));
        match self.rule {
            Rule::Us => {
                let start = nth_sunday(y, 3, 2) * 86400 + 7200 - self.std;
                let end = nth_sunday(y, 11, 1) * 86400 + 7200 - self.dst;
                ts >= start && ts < end
            }
            Rule::Eu => {
                let start = nth_sunday(y, 3, -1) * 86400 + 3600;
                let end = nth_sunday(y, 10, -1) * 86400 + 3600;
                ts >= start && ts < end
            }
            Rule::Au => {
                let end = nth_sunday(y, 4, 1) * 86400 + 10800 - self.dst;
                let start = nth_sunday(y, 10, 1) * 86400 + 7200 - self.std;
                ts < end || ts >= start
            }
            Rule::Nz => {
                let end = nth_sunday(y, 4, 1) * 86400 + 10800 - self.dst;
                let start = nth_sunday(y, 9, -1) * 86400 + 7200 - self.std;
                ts < end || ts >= start
            }
            Rule::Eg => {
                if y < 2023 {
                    return false;
                }
                // last Friday of April 00:00 -> last Thursday of October 24:00
                let la = days_from_civil(y, 4, 30);
                let fri = la - (weekday(la) - 5).rem_euclid(7);
                let lo = days_from_civil(y, 10, 31);
                let thu = lo - (weekday(lo) - 4).rem_euclid(7);
                let start = fri * 86400 - self.std;
                let end = (thu + 1) * 86400 - self.dst;
                ts >= start && ts < end
            }
            Rule::None => false,
        }
    }
    pub fn offset_at(&self, ts: i64) -> (i64, bool, String) {
        if self.is_dst(ts) {
            (self.dst, true, self.dabbr.clone())
        } else {
            (self.std, false, self.sabbr.clone())
        }
    }
    /// convert local wall time (seconds since epoch as if UTC) to utc ts
    pub fn local_to_utc(&self, local: i64) -> i64 {
        let t1 = local - self.std;
        if self.is_dst(t1) {
            let t2 = local - self.dst;
            if self.is_dst(t2) {
                return t2;
            }
            // in gap: PHP moves forward
            return t1;
        }
        // could be ambiguous (overlap): prefer DST (first occurrence)
        let t2 = local - self.dst;
        if self.dst != self.std && self.is_dst(t2) {
            return t2;
        }
        t1
    }
}

pub struct Tm {
    pub y: i64,
    pub m: i64,
    pub d: i64,
    pub h: i64,
    pub i: i64,
    pub s: i64,
    pub wday: i64,
    pub yday: i64,
    pub off: i64,
    pub dst: bool,
    pub abbr: String,
}

pub fn to_tm(ts: i64, z: &Zone) -> Tm {
    let (off, dst, abbr) = z.offset_at(ts);
    let local = ts + off;
    let days = local.div_euclid(86400);
    let secs = local.rem_euclid(86400);
    let (y, m, d) = civil_from_days(days);
    Tm { y, m, d, h: secs / 3600, i: (secs % 3600) / 60, s: secs % 60, wday: weekday(days), yday: days - days_from_civil(y, 1, 1), off, dst, abbr }
}

fn iso_week(y: i64, yday: i64, wday: i64) -> (i64, i64) {
    let wd = if wday == 0 { 7 } else { wday };
    let w = (yday - wd + 10) / 7;
    if w < 1 {
        let py = y - 1;
        let pdays = if is_leap(py) { 366 } else { 365 };
        return iso_week(py, yday + pdays, wday);
    }
    let ydays = if is_leap(y) { 366 } else { 365 };
    if w == 53 && (ydays - yday) < (4 - (wd - 1)).max(0) + 0 && (yday - wd + 10) / 7 == 53 {
        // check if Dec 29-31 belongs to week 1 of next year
        let dec31_wd = (wd + (ydays - 1 - yday)) % 7;
        let dec31_wd = if dec31_wd == 0 { 7 } else { dec31_wd };
        if dec31_wd < 4 {
            return (y + 1, 1);
        }
    }
    if w == 53 {
        let dec31_wd = ((wd - 1) + (ydays - 1 - yday)) % 7 + 1;
        if dec31_wd < 4 {
            return (y + 1, 1);
        }
    }
    (y, w)
}

const DAYS: [&str; 7] = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
const MONTHS: [&str; 12] = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

pub fn format_date(fmt: &[u8], ts: i64, usec: i64, z: &Zone) -> Vec<u8> {
    let t = to_tm(ts, z);
    let mut out = String::new();
    let mut i = 0;
    while i < fmt.len() {
        let c = fmt[i] as char;
        match c {
            'd' => out.push_str(&format!("{:02}", t.d)),
            'D' => out.push_str(&DAYS[t.wday as usize][..3]),
            'j' => out.push_str(&t.d.to_string()),
            'l' => out.push_str(DAYS[t.wday as usize]),
            'N' => out.push_str(&(if t.wday == 0 { 7 } else { t.wday }).to_string()),
            'S' => out.push_str(match t.d {
                1 | 21 | 31 => "st",
                2 | 22 => "nd",
                3 | 23 => "rd",
                _ => "th",
            }),
            'w' => out.push_str(&t.wday.to_string()),
            'z' => out.push_str(&t.yday.to_string()),
            'W' => out.push_str(&format!("{:02}", iso_week(t.y, t.yday, t.wday).1)),
            'o' => out.push_str(&iso_week(t.y, t.yday, t.wday).0.to_string()),
            'F' => out.push_str(MONTHS[(t.m - 1) as usize]),
            'M' => out.push_str(&MONTHS[(t.m - 1) as usize][..3]),
            'm' => out.push_str(&format!("{:02}", t.m)),
            'n' => out.push_str(&t.m.to_string()),
            't' => out.push_str(&days_in_month(t.y, t.m).to_string()),
            'L' => out.push_str(if is_leap(t.y) { "1" } else { "0" }),
            'Y' => {
                if t.y < 0 {
                    out.push_str(&format!("-{:04}", -t.y));
                } else {
                    out.push_str(&format!("{:04}", t.y));
                }
            }
            'y' => out.push_str(&format!("{:02}", t.y.rem_euclid(100))),
            'X' | 'x' => {
                if c == 'X' || t.y >= 10000 || t.y < 0 {
                    out.push_str(&format!("{}{:04}", if t.y < 0 { "-" } else { "+" }, t.y.abs()));
                } else {
                    out.push_str(&format!("{:04}", t.y));
                }
            }
            'a' => out.push_str(if t.h < 12 { "am" } else { "pm" }),
            'A' => out.push_str(if t.h < 12 { "AM" } else { "PM" }),
            'B' => {
                let b = (((ts + 3600).rem_euclid(86400)) as f64 / 86.4) as i64 % 1000;
                out.push_str(&format!("{:03}", b));
            }
            'g' => out.push_str(&(if t.h % 12 == 0 { 12 } else { t.h % 12 }).to_string()),
            'G' => out.push_str(&t.h.to_string()),
            'h' => out.push_str(&format!("{:02}", if t.h % 12 == 0 { 12 } else { t.h % 12 })),
            'H' => out.push_str(&format!("{:02}", t.h)),
            'i' => out.push_str(&format!("{:02}", t.i)),
            's' => out.push_str(&format!("{:02}", t.s)),
            'u' => out.push_str(&format!("{:06}", usec)),
            'v' => out.push_str(&format!("{:03}", usec / 1000)),
            'e' => out.push_str(&z.name),
            'I' => out.push_str(if t.dst { "1" } else { "0" }),
            'O' => out.push_str(&fmt_offset(t.off, false)),
            'P' => out.push_str(&fmt_offset(t.off, true)),
            'p' => {
                if t.off == 0 {
                    out.push('Z');
                } else {
                    out.push_str(&fmt_offset(t.off, true));
                }
            }
            'T' => out.push_str(&t.abbr),
            'Z' => out.push_str(&t.off.to_string()),
            'c' => {
                let s = format_date(b"Y-m-d\\TH:i:sP", ts, usec, z);
                out.push_str(&String::from_utf8_lossy(&s));
            }
            'r' => {
                let s = format_date(b"D, d M Y H:i:s O", ts, usec, z);
                out.push_str(&String::from_utf8_lossy(&s));
            }
            'U' => out.push_str(&ts.to_string()),
            '\\' => {
                i += 1;
                if i < fmt.len() {
                    out.push(fmt[i] as char);
                }
            }
            _ => {
                // preserve raw bytes
                let mut b = out.into_bytes();
                b.push(fmt[i]);
                out = unsafe { String::from_utf8_unchecked(b) };
            }
        }
        i += 1;
    }
    out.into_bytes()
}

pub fn now_ts() -> (i64, i64) {
    let d = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap();
    (d.as_secs() as i64, d.subsec_micros() as i64)
}

pub fn default_zone(it: &Interp) -> Zone {
    find_zone(&it.timezone).unwrap_or_else(Zone::utc)
}

