fn month_from_name(w: &str) -> Option<i64> {
    let l = w.to_ascii_lowercase();
    let names = ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"];
    for (i, n) in names.iter().enumerate() {
        if l == *n || l == MONTHS[i].to_ascii_lowercase() || (l == "sept" && i == 8) {
            return Some(i as i64 + 1);
        }
    }
    None
}
fn day_from_name(w: &str) -> Option<i64> {
    let l = w.to_ascii_lowercase();
    for (i, n) in DAYS.iter().enumerate() {
        let nl = n.to_ascii_lowercase();
        if l == nl || l == nl[..3] || (l.len() >= 3 && nl.starts_with(&l) && l.len() <= nl.len()) {
            return Some(i as i64);
        }
    }
    None
}
fn unit_of(w: &str) -> Option<usize> {
    let l = w.to_ascii_lowercase();
    let l = l.trim_end_matches('s');
    Some(match l {
        "year" | "yr" => 0,
        "month" | "mon" => 1,
        "day" => 2,
        "week" | "wk" => 7,
        "fortnight" | "forthnight" => 8,
        "hour" | "hr" => 3,
        "minute" | "min" => 4,
        "second" | "sec" => 5,
        "microsecond" | "usec" | "µsec" | "µ" => 6,
        "millisecond" | "msec" | "m" => 9,
        "weekday" => 10,
        _ => return None,
    })
}

struct Tok {
    s: String,
    kind: u8, // n number, w word, p punct
}

fn tokenize(s: &str) -> Vec<Tok> {
    let mut out = Vec::new();
    let b: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < b.len() {
        let c = b[i];
        if c.is_whitespace() || c == ',' {
            i += 1;
            continue;
        }
        if c.is_ascii_digit() {
            let st = i;
            while i < b.len() && b[i].is_ascii_digit() {
                i += 1;
            }
            out.push(Tok { s: b[st..i].iter().collect(), kind: b'n' });
            continue;
        }
        if c.is_alphabetic() {
            let st = i;
            while i < b.len() && (b[i].is_alphabetic() || b[i] == '_' || (b[i] == '/' && i + 1 < b.len() && b[i + 1].is_alphabetic())) {
                i += 1;
            }
            out.push(Tok { s: b[st..i].iter().collect(), kind: b'w' });
            continue;
        }
        out.push(Tok { s: c.to_string(), kind: b'p' });
        i += 1;
    }
    out
}

pub fn parse_datetime(input: &str, st: &mut DtState) -> bool {
    let s = input.trim();
    if s.is_empty() {
        return true;
    }
    if let Some(rest) = s.strip_prefix('@') {
        let (num, frac) = match rest.split_once('.') {
            Some((a, b)) => (a, Some(b)),
            None => (rest, None),
        };
        if let Ok(v) = num.trim().parse::<i64>() {
            st.ts_set = Some(v);
            if let Some(f) = frac {
                let f6 = format!("{:0<6}", f);
                st.us = f6[..6].parse().unwrap_or(0);
            }
            st.zone = Some(Zone { name: "+00:00".into(), std: 0, dst: 0, sabbr: "+00:00".into(), dabbr: "+00:00".into(), rule: Rule::None, kind: 1 });
            return true;
        }
        return false;
    }
    let toks = tokenize(s);
    let n = toks.len();
    let mut i = 0;
    let num = |t: &Tok| -> Option<i64> {
        if t.kind == b'n' {
            t.s.parse().ok()
        } else {
            None
        }
    };
    let is_p = |i: usize, c: &str| -> bool { i < n && toks[i].kind == b'p' && toks[i].s == c };
    while i < n {
        let t = &toks[i];
        // ISO date YYYY-MM-DD
        if t.kind == b'n' && t.s.len() == 4 && is_p(i + 1, "-") && i + 2 < n && toks[i + 2].kind == b'n' && is_p(i + 3, "-") && i + 4 < n && toks[i + 4].kind == b'n' {
            st.y = num(t).unwrap();
            st.m = num(&toks[i + 2]).unwrap();
            st.d = num(&toks[i + 4]).unwrap();
            st.have_date = true;
            i += 5;
            if i < n && toks[i].kind == b'w' && (toks[i].s == "T" || toks[i].s == "t") {
                i += 1;
            }
            continue;
        }
        // YYYY-MM
        if t.kind == b'n' && t.s.len() == 4 && is_p(i + 1, "-") && i + 2 < n && toks[i + 2].kind == b'n' && !is_p(i + 3, "-") && !is_p(i + 3, ":") {
            st.y = num(t).unwrap();
            st.m = num(&toks[i + 2]).unwrap();
            st.d = 1;
            st.have_date = true;
            i += 3;
            continue;
        }
        // YYYY/MM/DD
        if t.kind == b'n' && t.s.len() == 4 && is_p(i + 1, "/") && i + 4 < n && is_p(i + 3, "/") {
            st.y = num(t).unwrap();
            st.m = num(&toks[i + 2]).unwrap_or(1);
            st.d = num(&toks[i + 4]).unwrap_or(1);
            st.have_date = true;
            i += 5;
            continue;
        }
        // MM/DD/YYYY or MM/DD
        if t.kind == b'n' && t.s.len() <= 2 && is_p(i + 1, "/") && i + 2 < n && toks[i + 2].kind == b'n' {
            st.m = num(t).unwrap();
            st.d = num(&toks[i + 2]).unwrap();
            if is_p(i + 3, "/") && i + 4 < n && toks[i + 4].kind == b'n' {
                let mut y = num(&toks[i + 4]).unwrap();
                if toks[i + 4].s.len() <= 2 {
                    y += if y < 70 { 2000 } else { 1900 };
                }
                st.y = y;
                i += 5;
            } else {
                i += 3;
            }
            st.have_date = true;
            continue;
        }
        // DD-MM-YYYY or DD.MM.YYYY
        if t.kind == b'n' && t.s.len() <= 2 && (is_p(i + 1, "-") || is_p(i + 1, ".")) && i + 4 < n && toks[i + 2].kind == b'n' && (is_p(i + 3, "-") || is_p(i + 3, ".")) && toks[i + 4].kind == b'n' && toks[i + 4].s.len() == 4 {
            st.d = num(t).unwrap();
            st.m = num(&toks[i + 2]).unwrap();
            st.y = num(&toks[i + 4]).unwrap();
            st.have_date = true;
            i += 5;
            continue;
        }
        // DD-Mon-YYYY
        if t.kind == b'n' && is_p(i + 1, "-") && i + 2 < n && toks[i + 2].kind == b'w' && month_from_name(&toks[i + 2].s).is_some() {
            st.d = num(t).unwrap();
            st.m = month_from_name(&toks[i + 2].s).unwrap();
            i += 3;
            if is_p(i, "-") && i + 1 < n && toks[i + 1].kind == b'n' {
                st.y = num(&toks[i + 1]).unwrap();
                i += 2;
            }
            st.have_date = true;
            continue;
        }
        // time HH:MM[:SS[.frac]] [am|pm]
        if t.kind == b'n' && is_p(i + 1, ":") && i + 2 < n && toks[i + 2].kind == b'n' {
            st.h = num(t).unwrap();
            st.i = num(&toks[i + 2]).unwrap();
            st.s = 0;
            i += 3;
            if is_p(i, ":") && i + 1 < n && toks[i + 1].kind == b'n' {
                st.s = num(&toks[i + 1]).unwrap();
                i += 2;
                if is_p(i, ".") && i + 1 < n && toks[i + 1].kind == b'n' {
                    let f = format!("{:0<6}", toks[i + 1].s);
                    st.us = f[..6].parse().unwrap_or(0);
                    i += 2;
                }
            }
            if i < n && toks[i].kind == b'w' {
                let w = toks[i].s.to_ascii_lowercase();
                if w == "am" || w == "pm" || w == "a" || w == "p" {
                    if w.starts_with('p') && st.h < 12 {
                        st.h += 12;
                    }
                    if w.starts_with('a') && st.h == 12 {
                        st.h = 0;
                    }
                    i += 1;
                    if is_p(i, ".") {
                        i += 1;
                    }
                }
            }
            st.have_time = true;
            continue;
        }
        // number followed by am/pm
        if t.kind == b'n' && i + 1 < n && toks[i + 1].kind == b'w' && matches!(toks[i + 1].s.to_ascii_lowercase().as_str(), "am" | "pm") {
            let mut h = num(t).unwrap();
            let pm = toks[i + 1].s.to_ascii_lowercase() == "pm";
            if pm && h < 12 {
                h += 12;
            }
            if !pm && h == 12 {
                h = 0;
            }
            st.h = h;
            st.i = 0;
            st.s = 0;
            st.have_time = true;
            i += 2;
            continue;
        }
        // relative: [+-]N unit
        if (t.kind == b'p' && (t.s == "+" || t.s == "-")) || (t.kind == b'n' && i + 1 < n && toks[i + 1].kind == b'w' && unit_of(&toks[i + 1].s).is_some()) {
            let (sign, j) = if t.kind == b'p' { (if t.s == "-" { -1 } else { 1 }, i + 1) } else { (1, i) };
            if j < n && toks[j].kind == b'n' && j + 1 < n && toks[j + 1].kind == b'w' {
                if let Some(u) = unit_of(&toks[j + 1].s) {
                    let mut v = sign * num(&toks[j]).unwrap();
                    let mut k = j + 2;
                    if k < n && toks[k].kind == b'w' && toks[k].s.eq_ignore_ascii_case("ago") {
                        v = -v;
                        k += 1;
                    }
                    add_rel(st, u, v);
                    i = k;
                    continue;
                }
            }
            if t.kind == b'p' && j < n && toks[j].kind == b'n' && (toks[j].s.len() == 4 || toks[j].s.len() == 2) && j + 1 >= n {
                // timezone offset
                let off = parse_offset(&format!("{}{}", t.s, toks[j].s));
                if let Some(o) = off {
                    st.zone = Some(Zone { name: fmt_offset(o, true), std: o, dst: o, sabbr: fmt_offset(o, true), dabbr: fmt_offset(o, true), rule: Rule::None, kind: 1 });
                    i = j + 1;
                    continue;
                }
            }
            if t.kind == b'p' && j < n && toks[j].kind == b'n' && is_p(j + 1, ":") && j + 2 < n {
                let off = parse_offset(&format!("{}{}:{}", t.s, toks[j].s, toks[j + 2].s));
                if let Some(o) = off {
                    st.zone = Some(Zone { name: fmt_offset(o, true), std: o, dst: o, sabbr: fmt_offset(o, true), dabbr: fmt_offset(o, true), rule: Rule::None, kind: 1 });
                    i = j + 3;
                    continue;
                }
            }
            if t.kind == b'p' {
                i += 1;
                continue;
            }
        }
        if t.kind == b'w' {
            let w = t.s.to_ascii_lowercase();
            match w.as_str() {
                "now" => {
                    i += 1;
                    continue;
                }
                "today" | "midnight" => {
                    st.special.push("today".into());
                    i += 1;
                    continue;
                }
                "noon" => {
                    st.special.push("today".into());
                    st.h = 12;
                    st.have_time = true;
                    i += 1;
                    continue;
                }
                "tomorrow" => {
                    st.special.push("today".into());
                    st.rel[2] += 1;
                    i += 1;
                    continue;
                }
                "yesterday" => {
                    st.special.push("today".into());
                    st.rel[2] -= 1;
                    i += 1;
                    continue;
                }
                "next" | "last" | "previous" | "this" => {
                    let amount = match w.as_str() {
                        "next" => 1,
                        "this" => 0,
                        _ => -1,
                    };
                    if i + 1 < n && toks[i + 1].kind == b'w' {
                        let w2 = toks[i + 1].s.to_ascii_lowercase();
                        if let Some(u) = unit_of(&w2) {
                            add_rel(st, u, amount);
                            i += 2;
                            continue;
                        }
                        if let Some(d) = day_from_name(&w2) {
                            st.weekday = Some((d, amount));
                            st.special.push("today".into());
                            i += 2;
                            continue;
                        }
                    }
                    i += 1;
                    continue;
                }
                "first" | "last_day" => {}
                "ago" => {
                    for r in st.rel.iter_mut() {
                        *r = -*r;
                    }
                    i += 1;
                    continue;
                }
                "t" => {
                    i += 1;
                    continue;
                }
                "z" | "utc" | "gmt" => {
                    st.zone = find_zone(&t.s);
                    i += 1;
                    continue;
                }
                _ => {}
            }
            // "first day of" / "last day of"
            if (w == "first" || w == "last") && i + 2 < n && toks[i + 1].s.eq_ignore_ascii_case("day") && toks[i + 2].s.eq_ignore_ascii_case("of") {
                st.special.push(if w == "first" { "first_day_of".into() } else { "last_day_of".into() });
                i += 3;
                continue;
            }
            if let Some(m) = month_from_name(&w) {
                st.m = m;
                st.have_date = true;
                i += 1;
                if i < n && toks[i].kind == b'n' {
                    let v = num(&toks[i]).unwrap();
                    if toks[i].s.len() == 4 {
                        st.y = v;
                        st.d = 1;
                        i += 1;
                    } else {
                        st.d = v;
                        i += 1;
                        if i < n && toks[i].kind == b'w' && matches!(toks[i].s.to_ascii_lowercase().as_str(), "st" | "nd" | "rd" | "th") {
                            i += 1;
                        }
                        if i < n && toks[i].kind == b'n' && toks[i].s.len() == 4 {
                            st.y = num(&toks[i]).unwrap();
                            i += 1;
                        }
                    }
                } else {
                    st.d = 1;
                }
                continue;
            }
            if let Some(d) = day_from_name(&w) {
                st.weekday = Some((d, 0));
                st.special.push("today".into());
                i += 1;
                continue;
            }
            if let Some(z) = find_zone(&t.s) {
                st.zone = Some(z);
                i += 1;
                continue;
            }
            return false;
        }
        // "15 January 2024"
        if t.kind == b'n' && i + 1 < n && toks[i + 1].kind == b'w' {
            let mut j = i + 1;
            if matches!(toks[j].s.to_ascii_lowercase().as_str(), "st" | "nd" | "rd" | "th") {
                j += 1;
            }
            if j < n && toks[j].kind == b'w' {
                if let Some(m) = month_from_name(&toks[j].s) {
                    st.d = num(t).unwrap();
                    st.m = m;
                    st.have_date = true;
                    i = j + 1;
                    if i < n && toks[i].kind == b'n' && toks[i].s.len() == 4 {
                        st.y = num(&toks[i]).unwrap();
                        i += 1;
                    }
                    continue;
                }
            }
        }
        // YYYYMMDD
        if t.kind == b'n' && t.s.len() == 8 {
            let v = &t.s;
            st.y = v[..4].parse().unwrap();
            st.m = v[4..6].parse().unwrap();
            st.d = v[6..8].parse().unwrap();
            st.have_date = true;
            i += 1;
            continue;
        }
        // lone 4-digit year
        if t.kind == b'n' && t.s.len() == 4 && st.have_date {
            st.y = num(t).unwrap();
            i += 1;
            continue;
        }
        return false;
    }
    true
}

fn add_rel(st: &mut DtState, u: usize, v: i64) {
    match u {
        7 => st.rel[2] += v * 7,
        8 => st.rel[2] += v * 14,
        9 => st.rel[6] += v * 1000,
        10 => st.rel[2] += v, // weekday approx
        _ => st.rel[u] += v,
    }
}

/// resolve state against base time; returns (ts, usec, zone)
pub fn resolve(st: &DtState, base_ts: i64, base_us: i64, base_zone: &Zone) -> (i64, i64, Zone) {
    let zone = st.zone.clone().unwrap_or_else(|| base_zone.clone());
    if let Some(t) = st.ts_set {
        let mut ts = t;
        ts += st.rel[5] + st.rel[4] * 60 + st.rel[3] * 3600 + st.rel[2] * 86400;
        return (ts, st.us, zone);
    }
    let bt = to_tm(base_ts, &zone);
    let mut y = bt.y;
    let mut m = bt.m;
    let mut d = bt.d;
    let mut h = bt.h;
    let mut mi = bt.i;
    let mut s = bt.s;
    let mut us = base_us;
    let today = st.special.iter().any(|x| x == "today");
    if st.have_date {
        y = st.y;
        m = st.m;
        d = st.d;
        if !st.have_time {
            h = 0;
            mi = 0;
            s = 0;
            us = 0;
        }
    }
    if today && !st.have_time {
        h = 0;
        mi = 0;
        s = 0;
        us = 0;
    }
    if st.have_time {
        h = st.h;
        mi = st.i;
        s = st.s;
        us = st.us;
    }
    // relative units
    y += st.rel[0];
    m += st.rel[1];
    // normalize month
    let mut mm = m - 1;
    y += mm.div_euclid(12);
    mm = mm.rem_euclid(12);
    m = mm + 1;
    if st.special.iter().any(|x| x == "first_day_of") {
        d = 1;
        if !st.have_time {
            h = 0;
            mi = 0;
            s = 0;
        }
    }
    if st.special.iter().any(|x| x == "last_day_of") {
        d = days_in_month(y, m);
        if !st.have_time {
            h = 0;
            mi = 0;
            s = 0;
        }
    }
    let mut days = days_from_civil(y, m, 1) + d - 1 + st.rel[2];
    if let Some((wd, behavior)) = st.weekday {
        let cur = weekday(days);
        let diff = (wd - cur).rem_euclid(7);
        if behavior == 1 {
            days += if diff == 0 { 7 } else { diff };
        } else if behavior == -1 {
            let back = (cur - wd).rem_euclid(7);
            days -= if back == 0 { 7 } else { back };
        } else {
            days += diff;
        }
    }
    let local = days * 86400 + h * 3600 + mi * 60 + s + st.rel[3] * 3600 + st.rel[4] * 60 + st.rel[5];
    let mut us_total = us + st.rel[6];
    let mut local = local;
    local += us_total.div_euclid(1_000_000);
    us_total = us_total.rem_euclid(1_000_000);
    let ts = zone.local_to_utc(local);
    (ts, us_total, zone)
}

pub fn new_state() -> DtState {
    DtState { y: 1970, m: 1, d: 1, h: 0, i: 0, s: 0, us: 0, zone: None, have_time: false, have_date: false, rel: [0; 7], weekday: None, special: Vec::new(), ts_set: None }
}

pub fn strtotime(it: &Interp, s: &str, base: i64) -> Option<(i64, i64, Zone)> {
    let mut st = new_state();
    if !parse_datetime(s, &mut st) {
        return None;
    }
    let z = default_zone(it);
    Some(resolve(&st, base, 0, &z))
}

// ---------------- builtins ----------------
fn f_time(_it: &mut Interp, _a: &mut Args) -> R<Value> {
    Ok(Value::Int(now_ts().0))
}
fn f_microtime(it: &mut Interp, a: &mut Args) -> R<Value> {
    let d = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap();
    if a.bool_or(it, 0, false)? {
        return Ok(Value::Float(d.as_secs_f64()));
    }
    Ok(Value::string(format!("{:.8} {}", d.subsec_micros() as f64 / 1e6, d.as_secs())))
}
fn f_date(it: &mut Interp, a: &mut Args) -> R<Value> {
    let f = a.str(it, 0)?;
    let ts = match a.opt_int(it, 1)? {
        Some(t) => t,
        None => now_ts().0,
    };
    let z = default_zone(it);
    Ok(Value::vec(format_date(&f, ts, 0, &z)))
}
fn f_gmdate(it: &mut Interp, a: &mut Args) -> R<Value> {
    let f = a.str(it, 0)?;
    let ts = match a.opt_int(it, 1)? {
        Some(t) => t,
        None => now_ts().0,
    };
    let mut z = Zone::utc();
    z.name = "UTC".into();
    let out = format_date(&f, ts, 0, &z);
    Ok(Value::vec(out))
}
fn f_idate(it: &mut Interp, a: &mut Args) -> R<Value> {
    let f = a.str(it, 0)?;
    let ts = a.opt_int(it, 1)?.unwrap_or(now_ts().0);
    let z = default_zone(it);
    let s = format_date(&f, ts, 0, &z);
    Ok(Value::Int(String::from_utf8_lossy(&s).parse().unwrap_or(0)))
}
fn mktime_impl(it: &mut Interp, a: &mut Args, gmt: bool) -> R<Value> {
    let z = if gmt { Zone::utc() } else { default_zone(it) };
    let (now, _) = now_ts();
    let t = to_tm(now, &z);
    let h = a.opt_int(it, 0)?.unwrap_or(t.h);
    let mi = a.opt_int(it, 1)?.unwrap_or(t.i);
    let s = a.opt_int(it, 2)?.unwrap_or(t.s);
    let mo = a.opt_int(it, 3)?.unwrap_or(t.m);
    let d = a.opt_int(it, 4)?.unwrap_or(t.d);
    let mut y = a.opt_int(it, 5)?.unwrap_or(t.y);
    if a.has(5) {
        if (0..70).contains(&y) {
            y += 2000;
        } else if (70..=100).contains(&y) {
            y += 1900;
        }
    }
    let mm = mo - 1;
    let yy = y + mm.div_euclid(12);
    let mm = mm.rem_euclid(12) + 1;
    let days = days_from_civil(yy, mm, 1) + d - 1;
    let local = days * 86400 + h * 3600 + mi * 60 + s;
    Ok(Value::Int(z.local_to_utc(local)))
}
fn f_mktime(it: &mut Interp, a: &mut Args) -> R<Value> {
    mktime_impl(it, a, false)
}
fn f_gmmktime(it: &mut Interp, a: &mut Args) -> R<Value> {
    mktime_impl(it, a, true)
}
fn f_checkdate(it: &mut Interp, a: &mut Args) -> R<Value> {
    let m = a.int(it, 0)?;
    let d = a.int(it, 1)?;
    let y = a.int(it, 2)?;
    Ok(Value::Bool(m >= 1 && m <= 12 && d >= 1 && y >= 1 && y <= 32767 && d <= days_in_month(y, m)))
}
fn f_strtotime(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let base = a.opt_int(it, 1)?.unwrap_or(now_ts().0);
    match strtotime(it, &String::from_utf8_lossy(&s), base) {
        Some((ts, _, _)) => Ok(Value::Int(ts)),
        None => Ok(Value::Bool(false)),
    }
}
fn f_date_default_timezone_set(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let n = String::from_utf8_lossy(&s).to_string();
    match find_zone(&n) {
        Some(z) if z.kind == 3 => {
            it.timezone = z.name.clone();
            Ok(Value::Bool(true))
        }
        _ => {
            it.notice(&format!("date_default_timezone_set(): Timezone ID '{}' is invalid", n))?;
            Ok(Value::Bool(false))
        }
    }
}
fn f_date_default_timezone_get(it: &mut Interp, _a: &mut Args) -> R<Value> {
    Ok(Value::str(&it.timezone))
}
fn tm_array(t: &Tm, ts: i64, assoc_names: bool) -> PArray {
    let mut out = PArray::new();
    if assoc_names {
        out.set(Key::Str(pstr("seconds")), Value::Int(t.s));
        out.set(Key::Str(pstr("minutes")), Value::Int(t.i));
        out.set(Key::Str(pstr("hours")), Value::Int(t.h));
        out.set(Key::Str(pstr("mday")), Value::Int(t.d));
        out.set(Key::Str(pstr("wday")), Value::Int(t.wday));
        out.set(Key::Str(pstr("mon")), Value::Int(t.m));
        out.set(Key::Str(pstr("year")), Value::Int(t.y));
        out.set(Key::Str(pstr("yday")), Value::Int(t.yday));
        out.set(Key::Str(pstr("weekday")), Value::str(DAYS[t.wday as usize]));
        out.set(Key::Str(pstr("month")), Value::str(MONTHS[(t.m - 1) as usize]));
        out.set(Key::Int(0), Value::Int(ts));
    }
    out
}
fn f_getdate(it: &mut Interp, a: &mut Args) -> R<Value> {
    let ts = a.opt_int(it, 0)?.unwrap_or(now_ts().0);
    let z = default_zone(it);
    let t = to_tm(ts, &z);
    Ok(Value::arr(tm_array(&t, ts, true)))
}
fn f_localtime(it: &mut Interp, a: &mut Args) -> R<Value> {
    let ts = a.opt_int(it, 0)?.unwrap_or(now_ts().0);
    let assoc = a.bool_or(it, 1, false)?;
    let z = default_zone(it);
    let t = to_tm(ts, &z);
    let vals = [t.s, t.i, t.h, t.d, t.m - 1, t.y - 1900, t.wday, t.yday, t.dst as i64];
    let names = ["tm_sec", "tm_min", "tm_hour", "tm_mday", "tm_mon", "tm_year", "tm_wday", "tm_yday", "tm_isdst"];
    let mut out = PArray::new();
    for (i, v) in vals.iter().enumerate() {
        if assoc {
            out.set(Key::Str(pstr(names[i])), Value::Int(*v));
        } else {
            out.push(Value::Int(*v));
        }
    }
    Ok(Value::arr(out))
}
fn f_date_parse(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let mut st = new_state();
    let ok = parse_datetime(&String::from_utf8_lossy(&s), &mut st);
    let mut out = PArray::new();
    let fv = |b: bool, v: i64| if b { Value::Int(v) } else { Value::Bool(false) };
    out.set(Key::Str(pstr("year")), fv(st.have_date, st.y));
    out.set(Key::Str(pstr("month")), fv(st.have_date, st.m));
    out.set(Key::Str(pstr("day")), fv(st.have_date, st.d));
    out.set(Key::Str(pstr("hour")), fv(st.have_time, st.h));
    out.set(Key::Str(pstr("minute")), fv(st.have_time, st.i));
    out.set(Key::Str(pstr("second")), fv(st.have_time, st.s));
    out.set(Key::Str(pstr("fraction")), if st.have_time { Value::Float(st.us as f64 / 1e6) } else { Value::Bool(false) });
    out.set(Key::Str(pstr("warning_count")), Value::Int(0));
    out.set(Key::Str(pstr("warnings")), Value::empty_array());
    out.set(Key::Str(pstr("error_count")), Value::Int(if ok { 0 } else { 1 }));
    out.set(Key::Str(pstr("errors")), Value::empty_array());
    out.set(Key::Str(pstr("is_localtime")), Value::Bool(st.zone.is_some()));
    Ok(Value::arr(out))
}

// helpers for prelude DateTime implementation
// __dt_parse(string, tzname|null, base_ts|null) -> [ts, us, tzname, tztype] | false
fn f_dt_parse(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let z = match a.opt_str(it, 1)? {
        Some(n) => find_zone(&String::from_utf8_lossy(&n)).unwrap_or_else(|| default_zone(it)),
        None => default_zone(it),
    };
    let (bts, bus) = match a.opt_int(it, 2)? {
        Some(t) => (t, a.int_or(it, 3, 0)?),
        None => now_ts(),
    };
    let mut st = new_state();
    if !parse_datetime(&String::from_utf8_lossy(&s), &mut st) {
        return Ok(Value::Bool(false));
    }
    let (ts, us, zone) = resolve(&st, bts, bus, &z);
    Ok(Value::arr(PArray::from_values(vec![Value::Int(ts), Value::Int(us), Value::str(&zone.name), Value::Int(zone.kind as i64)])))
}
fn f_dt_format(it: &mut Interp, a: &mut Args) -> R<Value> {
    let f = a.str(it, 0)?;
    let ts = a.int(it, 1)?;
    let us = a.int(it, 2)?;
    let zn = a.str(it, 3)?;
    let z = find_zone(&String::from_utf8_lossy(&zn)).unwrap_or_else(Zone::utc);
    Ok(Value::vec(format_date(&f, ts, us, &z)))
}
fn f_dt_valid_tz(it: &mut Interp, a: &mut Args) -> R<Value> {
    let zn = a.str(it, 0)?;
    Ok(match find_zone(&String::from_utf8_lossy(&zn)) {
        Some(z) => Value::arr(PArray::from_values(vec![Value::str(&z.name), Value::Int(z.kind as i64)])),
        None => Value::Bool(false),
    })
}
fn f_dt_tz_offset(it: &mut Interp, a: &mut Args) -> R<Value> {
    let zn = a.str(it, 0)?;
    let ts = a.int(it, 1)?;
    let z = find_zone(&String::from_utf8_lossy(&zn)).unwrap_or_else(Zone::utc);
    Ok(Value::Int(z.offset_at(ts).0))
}
// local components: __dt_parts(ts, tz) -> [y,m,d,h,i,s]
fn f_dt_parts(it: &mut Interp, a: &mut Args) -> R<Value> {
    let ts = a.int(it, 0)?;
    let zn = a.str(it, 1)?;
    let z = find_zone(&String::from_utf8_lossy(&zn)).unwrap_or_else(Zone::utc);
    let t = to_tm(ts, &z);
