fn f_dt_from_format(it: &mut Interp, a: &mut Args) -> R<Value> {
    let f = a.str(it, 0)?;
    let s = a.str(it, 1)?;
    let z = match a.opt_str(it, 2)? {
        Some(n) => find_zone(&String::from_utf8_lossy(&n)).unwrap_or_else(|| default_zone(it)),
        None => default_zone(it),
    };
    let (now, _) = now_ts();
    let t = to_tm(now, &z);
    let (mut y, mut m, mut d, mut h, mut mi, mut sec, mut us) = (t.y, t.m, t.d, t.h, t.i, t.s, 0i64);
    let mut have_time = false;
    let mut reset = false;
    let mut zone = z.clone();
    let mut ts_direct: Option<i64> = None;
    let mut pm: Option<bool> = None;
    let mut si = 0usize;
    let mut fi = 0usize;
