        let st = *si;
        let mut neg = false;
        if *si < s.len() && (s[*si] == b'-' || s[*si] == b'+') {
            neg = s[*si] == b'-';
            *si += 1;
        }
        let ds = *si;
        while *si < s.len() && s[*si].is_ascii_digit() && *si - ds < max {
            *si += 1;
        }
        if *si == ds {
            *si = st;
            return None;
        }
        let v: i64 = String::from_utf8_lossy(&s[ds..*si]).parse().ok()?;
        Some(if neg { -v } else { v })
    };
    while fi < f.len() {
        let c = f[fi];
        fi += 1;
        match c {
            b'd' | b'j' => {
                d = match rd(&s, &mut si, 2) {
                    Some(v) => v,
                    None => return Ok(Value::Bool(false)),
                }
            }
            b'm' | b'n' => {
                m = match rd(&s, &mut si, 2) {
                    Some(v) => v,
                    None => return Ok(Value::Bool(false)),
                }
            }
            b'Y' => {
                y = match rd(&s, &mut si, 4) {
                    Some(v) => v,
                    None => return Ok(Value::Bool(false)),
                }
            }
            b'y' => {
                let v = match rd(&s, &mut si, 2) {
                    Some(v) => v,
                    None => return Ok(Value::Bool(false)),
                };
                y = if v < 70 { 2000 + v } else { 1900 + v };
            }
            b'H' | b'G' | b'h' | b'g' => {
                h = match rd(&s, &mut si, 2) {
                    Some(v) => v,
                    None => return Ok(Value::Bool(false)),
                };
                have_time = true;
            }
            b'i' => {
                mi = match rd(&s, &mut si, 2) {
                    Some(v) => v,
                    None => return Ok(Value::Bool(false)),
                };
                have_time = true;
            }
            b's' => {
                sec = match rd(&s, &mut si, 2) {
                    Some(v) => v,
                    None => return Ok(Value::Bool(false)),
                };
                have_time = true;
            }
            b'u' | b'v' => {
                let st = si;
                while si < s.len() && s[si].is_ascii_digit() && si - st < 6 {
                    si += 1;
                }
                let fs = format!("{:0<6}", String::from_utf8_lossy(&s[st..si]));
                us = fs[..6].parse().unwrap_or(0);
            }
            b'A' | b'a' => {
                if si + 2 <= s.len() {
                    let w = s[si..si + 2].to_ascii_lowercase();
                    pm = Some(w == b"pm");
                    si += 2;
                }
            }
            b'D' | b'l' => {
                while si < s.len() && s[si].is_ascii_alphabetic() {
                    si += 1;
                }
            }
            b'M' | b'F' => {
                let st = si;
                while si < s.len() && s[si].is_ascii_alphabetic() {
                    si += 1;
                }
                m = match month_from_name(&String::from_utf8_lossy(&s[st..si])) {
                    Some(v) => v,
                    None => return Ok(Value::Bool(false)),
                };
            }
            b'U' => {
                ts_direct = rd(&s, &mut si, 20);
            }
            b'e' | b'T' | b'P' | b'O' | b'p' => {
                let st = si;
                while si < s.len() && !s[si].is_ascii_whitespace() {
                    si += 1;
                }
                if let Some(zz) = find_zone(&String::from_utf8_lossy(&s[st..si])) {
                    zone = zz;
                }
            }
            b'!' => {
                y = 1970;
                m = 1;
                d = 1;
                h = 0;
                mi = 0;
                sec = 0;
                us = 0;
                reset = true;
            }
            b'|' => {
                reset = true;
            }
            b'\\' => {
                if fi < f.len() {
                    if si < s.len() && s[si] == f[fi] {
                        si += 1;
                    }
                    fi += 1;
                }
            }
            b'*' => {
                while si < s.len() && !b" ,;:/.-()".contains(&s[si]) {
                    si += 1;
                }
            }
            b'?' => si += 1,
            _ => {
                if si < s.len() && s[si] == c {
                    si += 1;
                } else {
                    return Ok(Value::Bool(false));
                }
            }
        }
    }
    if si < s.len() {
        return Ok(Value::Bool(false));
    }
    if let Some(p) = pm {
        if p && h < 12 {
            h += 12;
        } else if !p && h == 12 {
            h = 0;
        }
    }
    if !have_time && !reset {
        // keep current time (PHP behavior)
    } else if reset && !have_time {
    }
    let ts = match ts_direct {
        Some(t) => t,
        None => {
            let mm = m - 1;
            let yy = y + mm.div_euclid(12);
            let mm = mm.rem_euclid(12) + 1;
            let days = days_from_civil(yy, mm, 1) + d - 1;
            zone.local_to_utc(days * 86400 + h * 3600 + mi * 60 + sec)
        }
    };
    Ok(Value::arr(PArray::from_values(vec![Value::Int(ts), Value::Int(us), Value::str(&zone.name), Value::Int(zone.kind as i64)])))
}

pub fn register2(it: &mut Interp) {
    reg(it, "__dt_from_format", "f,s,tz?", f_dt_from_format);
}
