// Minimal sampling profiler (debug aid). Enabled with PHPI_PROF=<outfile>.
use std::ffi::c_void;

#[repr(C)]
struct SigAction {
    sa_sigaction: usize,
    sa_mask: [u64; 16],
    sa_flags: i32,
    sa_restorer: usize,
}
#[repr(C)]
struct ItimerVal {
    it_interval: [i64; 2],
    it_value: [i64; 2],
}
extern "C" {
    fn sigaction(sig: i32, act: *const SigAction, old: *mut SigAction) -> i32;
    fn setitimer(which: i32, new: *const ItimerVal, old: *mut ItimerVal) -> i32;
}

const MAXS: usize = 2_000_000;
static mut SAMPLES: [usize; MAXS] = [0; MAXS];
static mut NS: usize = 0;

extern "C" fn handler(_sig: i32, _info: *mut c_void, uc: *mut c_void) {
    unsafe {
        // ucontext_t: uc_mcontext.gregs at offset 40; REG_RIP = 16, REG_RBP = 10
        let gregs = (uc as *mut u8).add(40) as *const usize;
        let rip = *gregs.add(16);
        let mut rbp = *gregs.add(10);
        let n = NS;
        if n + 12 >= MAXS {
            return;
        }
        SAMPLES[n] = rip;
        let mut k = 1;
        while k < 10 && rbp != 0 && rbp % 8 == 0 {
            let ret = *((rbp + 8) as *const usize);
            let next = *(rbp as *const usize);
            SAMPLES[n + k] = ret;
            k += 1;
            if next <= rbp || next - rbp > 1 << 24 {
                break;
            }
            rbp = next;
        }
        SAMPLES[n + k] = 0;
        NS = n + k + 1;
    }
}

pub fn start() {
    unsafe {
        let act = SigAction { sa_sigaction: handler as usize, sa_mask: [0; 16], sa_flags: 4 | 0x10000000, sa_restorer: 0 };
        sigaction(27, &act, std::ptr::null_mut());
        let tv = ItimerVal { it_interval: [0, 1000], it_value: [0, 1000] };
        setitimer(2, &tv, std::ptr::null_mut());
    }
}

pub fn finish(path: &str) {
    unsafe {
        let tv = ItimerVal { it_interval: [0, 0], it_value: [0, 0] };
        setitimer(2, &tv, std::ptr::null_mut());
        let maps = std::fs::read_to_string("/proc/self/maps").unwrap_or_default();
        let mut out = String::new();
        out.push_str(&maps);
        out.push_str("--SAMPLES--\n");
        let n = NS;
        let samples = std::ptr::addr_of!(SAMPLES) as *const usize;
        for i in 0..n {
            let v = *samples.add(i);
            if v == 0 {
                out.push('\n');
            } else {
                out.push_str(&format!("{:x} ", v));
            }
        }
        let _ = std::fs::write(path, out);
    }
}
