import sys, subprocess, bisect, collections
data = open(sys.argv[1]).read()
maps, samples = data.split("--SAMPLES--\n")
binpath = sys.argv[2]
base = None
for line in maps.splitlines():
    parts = line.split()
    if len(parts) >= 6 and parts[5].endswith('phpi') and parts[2] == '00000000':
        base = int(parts[0].split('-')[0], 16); break
syms = []
for line in subprocess.run(['nm', '-C', '--defined-only', binpath], capture_output=True, text=True).stdout.splitlines():
    p = line.split(' ', 2)
    if len(p) == 3 and p[1] in 'tTwW':
        syms.append((int(p[0], 16), p[2]))
syms.sort()
addrs = [a for a, _ in syms]
def sym(a):
    a -= base
    i = bisect.bisect_right(addrs, a) - 1
    return syms[i][1][:110] if i >= 0 else '?'
self_c = collections.Counter(); incl = collections.Counter(); total = 0
for st in samples.split('\n'):
    fr = st.split()
    if not fr: continue
    total += 1
    names = [sym(int(x, 16)) for x in fr]
    self_c[names[0]] += 1
    for n in set(names): incl[n] += 1
print("total", total)
print("== self")
for n, c in self_c.most_common(25): print(f"{100*c/total:5.1f}% {n}")
print("== inclusive")
for n, c in incl.most_common(25): print(f"{100*c/total:5.1f}% {n}")
