use super::*;
use crate::array::{Key, PArray};
use crate::ast::{Attribute, ClassKind, FuncDecl, Param, TypeHint, Visibility};
use crate::interp::calls::type_to_string;
use crate::object::MethodImpl;

fn rexc(it: &mut Interp, msg: &str) -> Flow {
    it.throw_err("ReflectionException", msg)
}

fn class_arg(it: &mut Interp, v: &Value) -> R<Rc<Class>> {
    match v {
        Value::Object(o) => Ok(o.class.clone()),
        Value::Str(s) => match it.find_class_autoload(s) {
            Some(c) => Ok(c),
            None => {
                let msg = format!("Class \"{}\" does not exist", String::from_utf8_lossy(s));
                Err(rexc(it, &msg))
            }
        },
        _ => Err(rexc(it, "Class \"\" does not exist")),
    }
}

fn s(x: &str) -> Value {
    Value::str(x)
}
fn names_arr(v: Vec<String>) -> Value {
    Value::arr(PArray::from_values(v.into_iter().map(|x| Value::str(&x)).collect()))
}

pub fn type_info(t: &Option<TypeHint>) -> Value {
    // [string repr, allowsNull, kind(named/union/intersection), [subtypes...], builtin]
    match t {
        None => Value::Null,
        Some(t) => {
            let mut a = PArray::new();
            let repr = type_to_string(t);
            a.set(Key::Str(pstr("str")), Value::str(&repr));
            let allows_null = match t {
                TypeHint::Nullable(_) => true,
                TypeHint::Simple(n) => &**n == "null" || &**n == "mixed",
                TypeHint::Union(v) => v.iter().any(|x| matches!(x, TypeHint::Simple(n) if &**n == "null")),
                _ => false,
            };
            a.set(Key::Str(pstr("null")), Value::Bool(allows_null));
            let (kind, subs): (&str, Vec<TypeHint>) = match t {
                TypeHint::Union(v) => {
                    if v.len() == 2 && v.iter().any(|x| matches!(x, TypeHint::Simple(n) if &**n == "null")) {
                        let other = v.iter().find(|x| !matches!(x, TypeHint::Simple(n) if &**n == "null")).unwrap().clone();
                        ("named", vec![other])
                    } else {
                        ("union", v.clone())
                    }
                }
                TypeHint::Intersection(v) => ("intersection", v.clone()),
                TypeHint::Nullable(i) => ("named", vec![(**i).clone()]),
                other => ("named", vec![other.clone()]),
            };
            a.set(Key::Str(pstr("kind")), s(kind));
            let mut sub = PArray::new();
            for st in subs.iter() {
                sub.push(type_info(&Some(st.clone())));
            }
            a.set(Key::Str(pstr("subs")), Value::arr(sub));
            let name = match (kind, subs.first()) {
                ("named", Some(TypeHint::Simple(n))) => n.to_string(),
                _ => repr.clone(),
            };
            let builtin = matches!(name.as_str(), "int" | "float" | "string" | "bool" | "array" | "callable" | "iterable" | "object" | "mixed" | "void" | "null" | "never" | "false" | "true" | "static");
            a.set(Key::Str(pstr("name")), Value::str(&name));
            a.set(Key::Str(pstr("builtin")), Value::Bool(builtin));
            Value::arr(a)
        }
    }
}

fn attrs_value(it: &mut Interp, attrs: &[Attribute], cls: Option<&Rc<Class>>) -> R<Value> {
    let mut out = PArray::new();
    for at in attrs {
        let mut args = PArray::new();
        for a in at.args.iter() {
            let v = match cls {
                Some(c) => it.eval_in_class(c, &a.value)?,
                None => {
                    let mut f = Frame::new(0, Rc::new(Vec::new()), it.cur_file.clone());
                    it.eval(&mut f, &a.value)?
                }
            };
            match &a.name {
                Some(n) => args.set(Key::Str(Rc::new(n.as_bytes().to_vec())), v),
                None => {
                    args.push(v);
                }
            }
        }
        let mut e = PArray::new();
        e.push(Value::str(&at.name));
        e.push(Value::arr(args));
        out.push(Value::arr(e));
    }
    Ok(Value::arr(out))
}

fn params_value(it: &mut Interp, d: &FuncDecl, cls: Option<&Rc<Class>>) -> R<Value> {
    let mut out = PArray::new();
    let nreq = required_count(&d.params);
    for (i, p) in d.params.iter().enumerate() {
        out.push(param_value(it, p, i, nreq, cls)?);
    }
    Ok(Value::arr(out))
}

fn required_count(ps: &[Param]) -> usize {
    let mut n = 0;
    for (i, p) in ps.iter().enumerate() {
        if p.default.is_none() && !p.variadic {
            n = i + 1;
        }
    }
    n
}

fn param_value(it: &mut Interp, p: &Param, i: usize, nreq: usize, cls: Option<&Rc<Class>>) -> R<Value> {
    let mut a = PArray::new();
    a.set(Key::Str(pstr("name")), Value::str(&p.name));
    a.set(Key::Str(pstr("pos")), Value::Int(i as i64));
    a.set(Key::Str(pstr("type")), type_info(&p.ty));
    let optional = i >= nreq;
    a.set(Key::Str(pstr("optional")), Value::Bool(optional));
    a.set(Key::Str(pstr("has_default")), Value::Bool(p.default.is_some()));
    let def = match &p.default {
        Some(e) => match cls {
            Some(c) => it.eval_in_class(c, e).unwrap_or(Value::Null),
            None => {
                let mut f = Frame::new(0, Rc::new(Vec::new()), it.cur_file.clone());
                it.eval(&mut f, e).unwrap_or(Value::Null)
            }
        },
        None => Value::Null,
    };
    a.set(Key::Str(pstr("default")), def);
    let implicit_null = matches!(&p.default, Some(crate::ast::Expr { kind: crate::ast::ExprKind::Lit(Value::Null), .. }));
    let allows_null = match &p.ty {
        None => true,
        Some(t) => matches!(t, TypeHint::Nullable(_)) || matches!(t, TypeHint::Simple(n) if &**n == "mixed" || &**n == "null") || matches!(t, TypeHint::Union(v) if v.iter().any(|x| matches!(x, TypeHint::Simple(n) if &**n == "null"))) || implicit_null,
    };
    a.set(Key::Str(pstr("allows_null")), Value::Bool(allows_null));
    a.set(Key::Str(pstr("variadic")), Value::Bool(p.variadic));
    a.set(Key::Str(pstr("by_ref")), Value::Bool(p.by_ref));
    a.set(Key::Str(pstr("promoted")), Value::Bool(p.promote.is_some()));
    a.set(Key::Str(pstr("attrs")), attrs_value(it, &p.attrs, cls)?);
    Ok(Value::arr(a))
}

fn vis_mods(v: Visibility) -> i64 {
    match v {
        Visibility::Public => 1,
        Visibility::Protected => 2,
        Visibility::Private => 4,
    }
}

fn method_info(it: &mut Interp, cls: &Rc<Class>, m: &Rc<Method>) -> R<Value> {
    let mut a = PArray::new();
    a.set(Key::Str(pstr("name")), Value::str(&m.name));
    a.set(Key::Str(pstr("class")), Value::str(&m.decl_class_name));
    a.set(Key::Str(pstr("vis")), Value::Int(vis_mods(m.vis)));
    a.set(Key::Str(pstr("static")), Value::Bool(m.is_static));
    a.set(Key::Str(pstr("abstract")), Value::Bool(m.is_abstract));
    a.set(Key::Str(pstr("final")), Value::Bool(m.is_final));
    let mut mods = vis_mods(m.vis);
    if m.is_static {
        mods |= 16;
    }
    if m.is_final {
        mods |= 32;
    }
    if m.is_abstract {
        mods |= 64;
    }
    a.set(Key::Str(pstr("mods")), Value::Int(mods));
    match &m.imp {
        MethodImpl::User(d) => {
            let sc = m.scope_class();
            a.set(Key::Str(pstr("params")), params_value(it, d, Some(&sc))?);
            a.set(Key::Str(pstr("ret")), type_info(&d.ret));
            a.set(Key::Str(pstr("doc")), d.doc.as_ref().map(|x| Value::str(x)).unwrap_or(Value::Bool(false)));
            a.set(Key::Str(pstr("attrs")), attrs_value(it, &d.attrs, Some(&sc))?);
            a.set(Key::Str(pstr("file")), Value::str(&d.file));
            a.set(Key::Str(pstr("start")), Value::Int(d.line as i64));
            a.set(Key::Str(pstr("end")), Value::Int(d.end_line as i64));
            a.set(Key::Str(pstr("internal")), Value::Bool(&*d.file == "[internal]"));
            a.set(Key::Str(pstr("generator")), Value::Bool(d.is_generator));
            a.set(Key::Str(pstr("byref")), Value::Bool(d.by_ref));
            a.set(Key::Str(pstr("variadic")), Value::Bool(d.params.iter().any(|p| p.variadic)));
        }
        MethodImpl::Builtin(_) => {
            a.set(Key::Str(pstr("params")), Value::empty_array());
            a.set(Key::Str(pstr("ret")), Value::Null);
            a.set(Key::Str(pstr("doc")), Value::Bool(false));
            a.set(Key::Str(pstr("attrs")), Value::empty_array());
            a.set(Key::Str(pstr("file")), Value::Bool(false));
            a.set(Key::Str(pstr("start")), Value::Bool(false));
            a.set(Key::Str(pstr("end")), Value::Bool(false));
            a.set(Key::Str(pstr("internal")), Value::Bool(true));
            a.set(Key::Str(pstr("generator")), Value::Bool(false));
            a.set(Key::Str(pstr("byref")), Value::Bool(false));
            a.set(Key::Str(pstr("variadic")), Value::Bool(false));
        }
    }
    let _ = cls;
    Ok(Value::arr(a))
}

fn func_info(it: &mut Interp, d: &Rc<FuncDecl>, cls: Option<&Rc<Class>>) -> R<Value> {
    let mut a = PArray::new();
    a.set(Key::Str(pstr("name")), Value::str(&d.name));
    a.set(Key::Str(pstr("params")), params_value(it, d, cls)?);
    a.set(Key::Str(pstr("ret")), type_info(&d.ret));
    a.set(Key::Str(pstr("doc")), d.doc.as_ref().map(|x| Value::str(x)).unwrap_or(Value::Bool(false)));
    a.set(Key::Str(pstr("attrs")), attrs_value(it, &d.attrs, cls)?);
    a.set(Key::Str(pstr("file")), Value::str(&d.file));
    a.set(Key::Str(pstr("start")), Value::Int(d.line as i64));
    a.set(Key::Str(pstr("end")), Value::Int(d.end_line as i64));
    a.set(Key::Str(pstr("internal")), Value::Bool(&*d.file == "[internal]"));
    a.set(Key::Str(pstr("generator")), Value::Bool(d.is_generator));
    a.set(Key::Str(pstr("byref")), Value::Bool(d.by_ref));
    a.set(Key::Str(pstr("variadic")), Value::Bool(d.params.iter().any(|p| p.variadic)));
    a.set(Key::Str(pstr("closure")), Value::Bool(d.is_closure));
    a.set(Key::Str(pstr("static")), Value::Bool(d.is_static));
    Ok(Value::arr(a))
}

fn builtin_func_info(b: &BuiltinDef) -> Value {
    let mut a = PArray::new();
    a.set(Key::Str(pstr("name")), s(b.name));
    let mut ps = PArray::new();
    for (i, p) in b.params.iter().enumerate() {
        let mut pa = PArray::new();
        pa.set(Key::Str(pstr("name")), s(p.name));
        pa.set(Key::Str(pstr("pos")), Value::Int(i as i64));
        pa.set(Key::Str(pstr("type")), Value::Null);
        pa.set(Key::Str(pstr("optional")), Value::Bool(p.optional || p.variadic));
        pa.set(Key::Str(pstr("has_default")), Value::Bool(p.optional));
        pa.set(Key::Str(pstr("default")), Value::Null);
        pa.set(Key::Str(pstr("allows_null")), Value::Bool(true));
        pa.set(Key::Str(pstr("variadic")), Value::Bool(p.variadic));
        pa.set(Key::Str(pstr("by_ref")), Value::Bool(p.by_ref));
        pa.set(Key::Str(pstr("promoted")), Value::Bool(false));
        pa.set(Key::Str(pstr("attrs")), Value::empty_array());
        ps.push(Value::arr(pa));
    }
    a.set(Key::Str(pstr("params")), Value::arr(ps));
    a.set(Key::Str(pstr("ret")), Value::Null);
    a.set(Key::Str(pstr("doc")), Value::Bool(false));
    a.set(Key::Str(pstr("attrs")), Value::empty_array());
    a.set(Key::Str(pstr("file")), Value::Bool(false));
    a.set(Key::Str(pstr("start")), Value::Bool(false));
    a.set(Key::Str(pstr("end")), Value::Bool(false));
    a.set(Key::Str(pstr("internal")), Value::Bool(true));
    a.set(Key::Str(pstr("generator")), Value::Bool(false));
    a.set(Key::Str(pstr("byref")), Value::Bool(false));
    a.set(Key::Str(pstr("variadic")), Value::Bool(b.variadic));
    a.set(Key::Str(pstr("closure")), Value::Bool(false));
    a.set(Key::Str(pstr("static")), Value::Bool(false));
    Value::arr(a)
}

// __rc(class, what, arg?)
fn f_rc(it: &mut Interp, a: &mut Args) -> R<Value> {
    let cls = class_arg(it, &a.get(0))?;
    let what = a.str(it, 1)?;
    let arg = a.get(2);
    let decl = cls.decl.clone();
    Ok(match &what[..] {
        b"name" => Value::str(&cls.name),
        b"kind" => s(match cls.kind {
            ClassKind::Class => "class",
            ClassKind::Interface => "interface",
            ClassKind::Trait => "trait",
            ClassKind::Enum => "enum",
        }),
        b"abstract" => Value::Bool(cls.is_abstract && cls.kind == ClassKind::Class || decl.as_ref().map(|d| d.is_abstract).unwrap_or(false)),
        b"final" => Value::Bool(cls.is_final),
        b"readonly" => Value::Bool(cls.is_readonly),
        b"internal" => Value::Bool(cls.internal),
        b"anon" => Value::Bool(decl.as_ref().map(|d| d.is_anon).unwrap_or(false)),
        b"parent" => match &cls.parent {
            Some(p) => Value::str(&p.name),
            None => Value::Bool(false),
        },
        b"interfaces" => names_arr(cls.interfaces.iter().map(|i| i.name.to_string()).collect()),
        b"traits" => names_arr(cls.traits.iter().map(|t| t.name.to_string()).collect()),
        b"file" => match &decl {
            Some(d) if !cls.internal => Value::str(&d.file),
            _ => Value::Bool(false),
        },
        b"start" => match &decl {
            Some(d) if !cls.internal => Value::Int(d.line as i64),
            _ => Value::Bool(false),
        },
        b"end" => match &decl {
            Some(d) if !cls.internal => Value::Int(d.end_line as i64),
            _ => Value::Bool(false),
        },
        b"doc" => match decl.as_ref().and_then(|d| d.doc.clone()) {
            Some(d) => Value::str(&d),
            None => Value::Bool(false),
        },
        b"consts" => {
            let mut out = PArray::new();
            let names: Vec<Name> = cls.consts.borrow().keys().cloned().collect();
            for n in names {
                let v = it.class_const(&cls, &n, Some(&cls))?;
                out.set(Key::Str(Rc::new(n.as_bytes().to_vec())), v);
            }
            Value::arr(out)
        }
        b"const_info" => {
            let n = it.to_str(&arg)?;
            let ns = String::from_utf8_lossy(&n).to_string();
            let c = cls.consts.borrow().get(ns.as_str()).cloned();
            match c {
                Some(c) => {
                    let mut out = PArray::new();
                    out.set(Key::Str(pstr("class")), Value::str(&c.decl_class));
                    out.set(Key::Str(pstr("vis")), Value::Int(vis_mods(c.vis)));
                    out.set(Key::Str(pstr("final")), Value::Bool(c.is_final));
                    out.set(Key::Str(pstr("case")), Value::Bool(c.is_case));
                    let v = it.class_const(&cls, &ns, Some(&cls))?;
                    out.set(Key::Str(pstr("value")), v);
                    let (doc, attrs) = match &c.expr {
                        Some((d, i)) => (d.consts[*i].doc.clone(), d.consts[*i].attrs.clone()),
                        None => (None, vec![]),
                    };
                    out.set(Key::Str(pstr("doc")), doc.map(|d| Value::str(&d)).unwrap_or(Value::Bool(false)));
                    out.set(Key::Str(pstr("attrs")), attrs_value(it, &attrs, Some(&cls))?);
                    Value::arr(out)
                }
                None => Value::Bool(false),
            }
        }
        b"methods" => names_arr(cls.method_order.iter().map(|n| cls.methods[n].name.to_string()).collect()),
        b"has_method" => {
            let n = it.to_str(&arg)?;
            Value::Bool(cls.methods.contains_key(String::from_utf8_lossy(&n.to_ascii_lowercase()).as_ref()))
        }
        b"method" => {
            let n = it.to_str(&arg)?;
            let ln = String::from_utf8_lossy(&n.to_ascii_lowercase()).to_string();
            match cls.methods.get(ln.as_str()).cloned() {
                Some(m) => method_info(it, &cls, &m)?,
                None => Value::Bool(false),
            }
        }
        b"props" => {
            // declared (non-static then static) in order
            let mut v: Vec<String> = Vec::new();
            for info in cls.slots.iter() {
                if crate::builtins::output::is_hidden_prop(info) {
                    continue;
                }
                if info.vis == Visibility::Private && !info.decl_class.eq_ignore_ascii_case(&cls.name) {
                    continue;
                }
                if !v.contains(&info.name.to_string()) {
                    v.push(info.name.to_string());
                }
            }
            for (n, sp) in cls.static_props.iter() {
                if sp.info.vis == Visibility::Private && !sp.info.decl_class.eq_ignore_ascii_case(&cls.name) {
                    continue;
                }
                v.push(n.to_string());
            }
            // own class props first (PHP order: declared in class then inherited)
            names_arr(v)
        }
        b"prop" => {
            let n = it.to_str(&arg)?;
            let ns = String::from_utf8_lossy(&n).to_string();
            let info = cls.prop_infos.get(ns.as_str()).cloned().or_else(|| cls.static_props.get(ns.as_str()).map(|sp| sp.info.clone()));
            match info {
                Some(info) => {
                    let mut out = PArray::new();
                    out.set(Key::Str(pstr("name")), Value::str(&info.name));
                    out.set(Key::Str(pstr("class")), Value::str(&info.decl_class));
                    out.set(Key::Str(pstr("vis")), Value::Int(vis_mods(info.vis)));
                    out.set(Key::Str(pstr("static")), Value::Bool(info.is_static));
                    out.set(Key::Str(pstr("readonly")), Value::Bool(info.readonly));
                    out.set(Key::Str(pstr("type")), type_info(&info.ty));
                    let (has_def, def, doc, attrs, promoted) = match &info.default_src {
                        Some((d, i)) => {
                            let pd = &d.props[*i];
                            let owner = it.find_class(info.decl_class.as_bytes()).unwrap_or(cls.clone());
                            let dv = match &pd.default {
                                Some(e) => it.eval_in_class(&owner, e)?,
                                None => Value::Null,
                            };
                            (pd.default.is_some() || pd.ty.is_none(), dv, pd.doc.clone(), pd.attrs.clone(), false)
                        }
                        None => (false, Value::Null, None, vec![], true),
                    };
                    out.set(Key::Str(pstr("has_default")), Value::Bool(has_def));
                    out.set(Key::Str(pstr("default")), def);
                    out.set(Key::Str(pstr("doc")), doc.map(|d| Value::str(&d)).unwrap_or(Value::Bool(false)));
                    out.set(Key::Str(pstr("attrs")), attrs_value(it, &attrs, Some(&cls))?);
                    out.set(Key::Str(pstr("promoted")), Value::Bool(promoted));
                    Value::arr(out)
                }
                None => Value::Bool(false),
            }
        }
        b"attrs" => {
            let attrs = decl.as_ref().map(|d| d.attrs.clone()).unwrap_or_default();
            attrs_value(it, &attrs, Some(&cls))?
        }
        b"instantiable" => {
            let ok = cls.kind == ClassKind::Class && !cls.is_abstract && cls.magic.construct.as_ref().map(|c| c.vis == Visibility::Public).unwrap_or(true);
            Value::Bool(ok)
        }
        b"cases" => names_arr(cls.case_names.iter().map(|n| n.to_string()).collect()),
        b"backing" => match &cls.enum_backing {
            Some(b) => Value::str(b),
            None => Value::Null,
        },
        b"static_props" => {
            let mut out = PArray::new();
            let names: Vec<Name> = cls.static_props.keys().cloned().collect();
            for n in names {
                if let Some(sp) = it.find_static_prop(&cls, n.as_bytes()) {
                    out.set(Key::Str(Rc::new(n.as_bytes().to_vec())), sp.val.borrow().clone());
                }
            }
            Value::arr(out)
        }
        b"get_static" => {
            let n = it.to_str(&arg)?;
            match it.find_static_prop(&cls, &n) {
                Some(sp) => sp.val.borrow().clone(),
                None => Value::Undef,
            }
        }
        b"set_static" => {
            let n = it.to_str(&arg)?;
            let v = a.get(3);
            match it.find_static_prop(&cls, &n) {
                Some(sp) => {
                    *sp.val.borrow_mut() = v;
                    Value::Bool(true)
                }
                None => Value::Bool(false),
            }
        }
        b"default_props" => {
            let d = it.class_defaults(&cls)?;
            let mut out = PArray::new();
            for info in cls.slots.iter() {
                let v = d[info.slot].clone();
                if v.is_undef() || crate::builtins::output::is_hidden_prop(info) {
                    continue;
                }
                out.set(Key::Str(Rc::new(info.name.as_bytes().to_vec())), v);
            }
            Value::arr(out)
        }
        b"new_noctor" => Value::Object(it.instantiate_raw(&cls)?),
        _ => Value::Null,
    })
}

fn f_rf(it: &mut Interp, a: &mut Args) -> R<Value> {
    let f = a.get(0);
    match &f {
        Value::Object(o) if super::classes::is_closure(o) => {
            let d = super::classes::closure_decl(o);
            match d {
                Some(d) => {
                    let scope = o.with_internal::<super::classes::ClosureData, _>(|c| c.scope.clone()).flatten();
                    let mut info = func_info(it, &d, scope.as_ref())?;
                    if let Value::Array(arr) = &mut info {
                        let m = Rc::make_mut(arr);
                        let this = o.with_internal::<super::classes::ClosureData, _>(|c| c.this.clone()).flatten();
                        m.set(Key::Str(pstr("this")), this.map(Value::Object).unwrap_or(Value::Null));
                        m.set(Key::Str(pstr("scope")), scope.map(|c| Value::str(&c.name)).unwrap_or(Value::Null));
                        let bound = o.with_internal::<super::classes::ClosureData, _>(|c| c.bound.clone()).unwrap_or_default();
                        let mut st = PArray::new();
                        for (slot, v) in bound {
                            if let Some(n) = d.slot_names.get(slot as usize) {
                                st.set(Key::Str(Rc::new(n.as_bytes().to_vec())), v.deref());
                            }
                        }
                        m.set(Key::Str(pstr("statics")), Value::arr(st));
                    }
                    Ok(info)
                }
                None => match super::classes::closure_builtin(o) {
                    Some(b) => Ok(builtin_func_info(b)),
                    None => Ok(Value::Bool(false)),
                },
            }
        }
        Value::Str(n) => {
            let mut l = n.to_ascii_lowercase();
            if l.first() == Some(&b'\\') {
                l.remove(0);
            }
            match it.functions.get(&l).cloned() {
                Some(Callable::User(d)) => func_info(it, &d, None),
                Some(Callable::Builtin(b)) => Ok(builtin_func_info(b)),
                None => {
                    let msg = format!("Function {}() does not exist", String::from_utf8_lossy(n));
                    Err(rexc(it, &msg))
                }
            }
        }
        _ => Err(rexc(it, "Function does not exist")),
    }
}

fn f_rm_invoke(it: &mut Interp, a: &mut Args) -> R<Value> {
    // __rm_invoke(class, method, obj|null, args array)
    let cls = class_arg(it, &a.get(0))?;
    let mn = a.str(it, 1)?;
    let obj = a.get(2);
    let args: Vec<Value> = match a.get(3) {
        Value::Array(x) => x.values().cloned().collect(),
        _ => vec![],
    };
    let ln = String::from_utf8_lossy(&mn.to_ascii_lowercase()).to_string();
    let m = match cls.methods.get(ln.as_str()).cloned() {
        Some(m) => m,
        None => return Err(rexc(it, "Method does not exist")),
    };
    match (m.is_static, obj) {
        (true, _) => it.call_static_method(&cls, &m, args, None),
        (false, Value::Object(o)) => {
            if !o.class.is_subclass_of(&cls) {
                return Err(rexc(it, "Given object is not an instance of the class this method was declared in"));
            }
            it.call_method_obj(&o, &m, args)
        }
        _ => {
            let msg = format!("Trying to invoke non static method {}::{}() without an object", m.decl_class_name, m.name);
            Err(rexc(it, &msg))
        }
    }
}

fn f_rm_closure(it: &mut Interp, a: &mut Args) -> R<Value> {
    let cls = class_arg(it, &a.get(0))?;
    let mn = a.str(it, 1)?;
    match a.get(2) {
        Value::Object(o) => it.closure_from_method(&o, &String::from_utf8_lossy(&mn), None),
        _ => {
            let ln = String::from_utf8_lossy(&mn.to_ascii_lowercase()).to_string();
            match cls.methods.get(ln.as_str()).cloned() {
                Some(m) => {
                    let data = super::classes::ClosureData {
                        decl: m.user().cloned(),
                        builtin: None,
                        method: Some((m.clone(), cls.clone())),
                        this: None,
                        scope: Some(m.scope_class()),
                        called_scope: Some(cls.clone()),
                        bound: vec![],
                        statics: std::cell::RefCell::new(std::collections::HashMap::new()),
                    };
                    Ok(Value::Object(super::classes::new_closure(it, data)))
                }
                None => Ok(Value::Null),
            }
        }
    }
}

fn f_rp_get(it: &mut Interp, a: &mut Args) -> R<Value> {
    // __rp_get(class, prop, obj)
    let cls = class_arg(it, &a.get(0))?;
    let n = a.str(it, 1)?;
    match a.get(2) {
        Value::Object(o) => {
            let scope = it.find_class(cls.prop_infos.get(String::from_utf8_lossy(&n).as_ref()).map(|i| i.decl_class.as_bytes()).unwrap_or(cls.name.as_bytes()));
            it.read_prop(&o, &n, scope.as_ref(), false)
        }
        _ => match it.find_static_prop(&cls, &n) {
            Some(sp) => Ok(sp.val.borrow().clone()),
            None => Ok(Value::Null),
        },
    }
}
fn f_rp_set(it: &mut Interp, a: &mut Args) -> R<Value> {
    let cls = class_arg(it, &a.get(0))?;
    let n = a.str(it, 1)?;
    let v = a.get(3);
    match a.get(2) {
        Value::Object(o) => {
            let scope = it.find_class(cls.prop_infos.get(String::from_utf8_lossy(&n).as_ref()).map(|i| i.decl_class.as_bytes()).unwrap_or(cls.name.as_bytes()));
            it.write_prop_scoped(&o, &n, v, scope.as_ref(), false)?;
        }
        _ => {
            if let Some(sp) = it.find_static_prop(&cls, &n) {
                *sp.val.borrow_mut() = v;
            }
        }
    }
    Ok(Value::Null)
}
fn f_rp_isinit(it: &mut Interp, a: &mut Args) -> R<Value> {
    let cls = class_arg(it, &a.get(0))?;
    let n = a.str(it, 1)?;
    match a.get(2) {
        Value::Object(o) => {
            let ns = String::from_utf8_lossy(&n).to_string();
            match cls.prop_infos.get(ns.as_str()) {
