                    continue;
                }
            };
            let key = match &item.key {
                Some(k) => {
                    let kv = self.eval(f, k)?;
                    self.to_key(&kv)?
                }
                None => {
                    let k = Key::Int(idx);
                    idx += 1;
                    k
                }
            };
            let sub_ref_needed = item.by_ref || matches!(&item.target.kind, ExprKind::List(sub, _) if Self::list_has_ref(sub));
            if sub_ref_needed {
                let er = {
                    let mut b = src.borrow_mut();
                    if matches!(&*b, Value::Null | Value::Undef) {
                        *b = Value::empty_array();
                    }
                    match &mut *b {
                        Value::Array(a) => {
                            let arr = Rc::make_mut(a);
                            wrap_ref(arr.entry_mut(key))
                        }
                        _ => Rc::new(RefCell::new(Value::Null)),
                    }
                };
                match &item.target.kind {
                    ExprKind::List(sub, _) => self.assign_list_ref(f, sub, er)?,
                    _ => self.bind_ref(f, &item.target, er)?,
                }
