                let elem = match &*src.borrow() {
                    Value::Array(a) => a.get(&key).map(|v| v.deref()),
                    _ => Some(Value::Null),
                };
                let elem = match elem {
                    Some(v) => v,
                    None => {
                        match &key {
                            Key::Int(i) => self.warn(&format!("Undefined array key {}", i))?,
