                        }
                        Value::Null
                    }
                };
                match &item.target.kind {
                    ExprKind::List(sub, _) => self.assign_list(f, sub, &elem)?,
                    _ => {
                        self.assign_value(f, &item.target, elem)?;
                    }
                }
            }
        }
