    if b.is_empty() {
        return Err(it.throw_err("Random\\BrokenRandomEngineError", "A random engine must return a non-empty string"));
    }
    let mut x = [0u8; 4];
    for (i, c) in b.iter().take(4).enumerate() {
        x[i] = *c;
    }
    Ok(u32::from_le_bytes(x))
}

fn engine_range(it: &mut Interp, e: &Obj, min: i64, max: i64) -> R<i64> {
    let umax = (max as u64).wrapping_sub(min as u64);
    if umax > u32::MAX as u64 {
        let lo = engine_u32(it, e)? as u64;
        let mut r = lo | ((engine_u32(it, e)? as u64) << 32);
        if umax == u64::MAX {
            return Ok((min as u64).wrapping_add(r) as i64);
        }
        let um = umax + 1;
        if um & (um - 1) != 0 {
            let limit = u64::MAX - (u64::MAX % um) - 1;
            while r > limit {
                let lo = engine_u32(it, e)? as u64;
                r = lo | ((engine_u32(it, e)? as u64) << 32);
            }
        }
        return Ok((min as u64).wrapping_add(r % um) as i64);
    }
    let umax = umax as u32;
    let mut r = engine_u32(it, e)?;
    if umax == u32::MAX {
        return Ok((min as u64).wrapping_add(r as u64) as i64);
    }
    let um = umax + 1;
    if um & (um - 1) != 0 {
        let limit = u32::MAX - (u32::MAX % um) - 1;
        while r > limit {
            r = engine_u32(it, e)?;
        }
    }
    Ok((min as u64).wrapping_add((r % um) as u64) as i64)
