fn f_mt_init(it: &mut Interp, a: &mut Args) -> R<Value> {
    let o = a.obj(it, 0)?;
    let mut m = Mt::new();
    m.php_mode = a.int_or(it, 2, 0)? == 1;
    let seed = match a.opt_int(it, 1)? {
        Some(s) => s as u32,
        None => {
            let b = os_random_bytes(4);
            u32::from_le_bytes([b[0], b[1], b[2], b[3]])
        }
    };
    m.seed(seed);
    o.set_internal(MtBox(m));
    Ok(Value::Null)
