fn f_rnd_bytes(it: &mut Interp, a: &mut Args) -> R<Value> {
    let e = a.obj(it, 0)?;
    let n = a.int(it, 1)?.max(0) as usize;
    let mut out = Vec::with_capacity(n);
    while out.len() < n {
        let v = engine_u32(it, &e)?;
        for b in v.to_le_bytes() {
