    let min = a.int(it, 1)?;
    let max = a.int(it, 2)?;
    Ok(Value::Int(engine_range(it, &e, min, max)?))
}
fn f_rnd_next(it: &mut Interp, a: &mut Args) -> R<Value> {
    let e = a.obj(it, 0)?;
    Ok(Value::Int((engine_u32(it, &e)? >> 1) as i64))
}
fn f_rnd_bytes(it: &mut Interp, a: &mut Args) -> R<Value> {
    let e = a.obj(it, 0)?;
    let n = a.int(it, 1)?.max(0) as usize;
    let mut out = Vec::with_capacity(n);
    while out.len() < n {
        let v = engine_u32(it, &e)?;
        for b in v.to_le_bytes() {
            if out.len() < n {
                out.push(b);
            }
        }
    }
    Ok(Value::vec(out))
}
fn f_rnd_float(it: &mut Interp, a: &mut Args) -> R<Value> {
    let e = a.obj(it, 0)?;
    let lo = engine_u32(it, &e)? as u64;
    let hi = engine_u32(it, &e)? as u64;
    let r = (lo | (hi << 32)) >> 11;
    Ok(Value::Float(r as f64 / (1u64 << 53) as f64))
}

pub fn register2(it: &mut Interp) {
    reg(it, "__mt_init", "o,seed?,mode?", f_mt_init);
    reg(it, "__mt_gen", "o", f_mt_gen);
    reg(it, "__rnd_range", "e,min,max", f_rnd_range);
    reg(it, "__rnd_next", "e", f_rnd_next);
    reg(it, "__rnd_bytes", "e,n", f_rnd_bytes);
    reg(it, "__rnd_float", "e", f_rnd_float);
}
