fn f_stream_get_line(it: &mut Interp, a: &mut Args) -> R<Value> {
    // emulate via fgets-like reading
    let h = a.get(0);
    let len = a.int(it, 1)?;
    let ending = a.str_or(it, 2, b"")?;
    let mut buf: Vec<u8> = Vec::new();
    loop {
        let mut sub = Args { v: vec![h.clone(), Value::Int(1)], def: a.def, strict: false };
        let c = super::file::read_bytes(it, &mut sub)?;
        match c {
            Some(b) if !b.is_empty() => {
                buf.extend_from_slice(&b);
                if !ending.is_empty() && buf.ends_with(&ending) {
                    buf.truncate(buf.len() - ending.len());
                    break;
                }
                if ending.is_empty() && buf.last() == Some(&b'\n') {
                    break;
                }
                if len > 0 && buf.len() as i64 >= len {
                    break;
                }
            }
            _ => {
                if buf.is_empty() {
                    return Ok(Value::Bool(false));
                }
                break;
            }
        }
    }
    Ok(Value::vec(buf))
}
fn f_hash_pbkdf2(it: &mut Interp, a: &mut Args) -> R<Value> {
    let algo = String::from_utf8_lossy(&a.str(it, 0)?).to_ascii_lowercase();
    let pw = a.str(it, 1)?;
    let salt = a.str(it, 2)?;
    let iters = a.int(it, 3)?.max(1);
    let len = a.int_or(it, 4, 0)?;
    let raw = a.bool_or(it, 5, false)?;
    let hlen = match super::hash::do_hash(&algo, b"") {
        Some(h) => h.len(),
        None => return Err(a.value_err(it, 0, "must be a valid cryptographic hashing algorithm")),
    };
    let want = if len <= 0 { hlen } else if raw { len as usize } else { (len as usize + 1) / 2 };
    let mut out = Vec::new();
    let mut block = 1u32;
    while out.len() < want {
        let mut s = salt.to_vec();
        s.extend_from_slice(&block.to_be_bytes());
        let mut u = super::hash::hmac(&algo, &pw, &s).unwrap();
        let mut t = u.clone();
        for _ in 1..iters {
            u = super::hash::hmac(&algo, &pw, &u).unwrap();
            for (x, y) in t.iter_mut().zip(u.iter()) {
                *x ^= y;
            }
        }
        out.extend_from_slice(&t);
        block += 1;
    }
    out.truncate(want);
    if raw {
        return Ok(Value::vec(out));
    }
    let mut h = super::hash::hex(&out);
    if len > 0 {
        h.truncate(len as usize);
    }
    Ok(Value::vec(h))
}

