use super::*;
use crate::array::{Key, PArray};

fn parse_count(f: &[u8], i: &mut usize) -> Option<i64> {
    // None => no count given; Some(-1) => '*'
    if *i < f.len() && f[*i] == b'*' {
        *i += 1;
        return Some(-1);
    }
    let st = *i;
    while *i < f.len() && f[*i].is_ascii_digit() {
        *i += 1;
    }
    if *i > st {
        Some(String::from_utf8_lossy(&f[st..*i]).parse().unwrap_or(1))
    } else {
        None
    }
}

fn f_pack(it: &mut Interp, a: &mut Args) -> R<Value> {
    let fmt = a.str(it, 0)?;
    let args: Vec<Value> = a.v[1..].iter().map(|v| v.deref()).collect();
    let mut ai = 0;
    let mut out: Vec<u8> = Vec::new();
    let mut i = 0;
    while i < fmt.len() {
        let c = fmt[i];
        i += 1;
        let cnt = parse_count(&fmt, &mut i);
        match c {
            b'a' | b'A' | b'Z' => {
                if ai >= args.len() {
                    return Err(it.value_error(&format!("Type {}: not enough arguments", c as char)));
                }
                let s = it.to_str(&args[ai])?;
                ai += 1;
                let n = match cnt {
                    None => 1,
                    Some(-1) => {
                        if c == b'Z' {
                            s.len() + 1
                        } else {
                            s.len()
                        }
                    }
                    Some(n) => n as usize,
                };
                let pad = if c == b'A' { b' ' } else { 0 };
                let mut take = s.len().min(n);
                if c == b'Z' && take == n && n > 0 {
                    take = n - 1;
                }
                out.extend_from_slice(&s[..take]);
                for _ in take..n {
                    out.push(pad);
                }
            }
            b'h' | b'H' => {
                if ai >= args.len() {
                    return Err(it.value_error(&format!("Type {}: not enough arguments", c as char)));
                }
                let s = it.to_str(&args[ai])?;
                ai += 1;
                let n = match cnt {
                    None => 1,
                    Some(-1) => s.len(),
                    Some(n) => (n as usize).min(s.len()),
                };
                let digits: Vec<u8> = s[..n].iter().map(|&d| (d as char).to_digit(16).unwrap_or(0) as u8).collect();
                for ch in digits.chunks(2) {
                    let (x, y) = (ch[0], *ch.get(1).unwrap_or(&0));
                    out.push(if c == b'H' { (x << 4) | y } else { (y << 4) | x });
                }
            }
            b'x' => {
                let n = match cnt {
                    None => 1,
                    Some(-1) => 0,
                    Some(n) => n as usize,
                };
                for _ in 0..n {
                    out.push(0);
                }
            }
            b'X' => {
                let n = match cnt {
                    None => 1,
                    Some(-1) => 0,
                    Some(n) => n as usize,
                };
                for _ in 0..n.min(out.len()) {
                    out.pop();
                }
            }
            b'@' => {
                let n = cnt.unwrap_or(1).max(0) as usize;
                out.resize(n, 0);
            }
            _ => {
                let n = match cnt {
                    None => 1,
                    Some(-1) => args.len() - ai,
                    Some(n) => n as usize,
                };
                for _ in 0..n {
                    if ai >= args.len() {
                        return Err(it.value_error(&format!("Type {}: too few arguments", c as char)));
                    }
                    let v = &args[ai];
                    ai += 1;
                    match c {
                        b'c' | b'C' => out.push(v.to_int() as u8),
                        b's' | b'S' | b'v' => out.extend_from_slice(&(v.to_int() as u16).to_le_bytes()),
                        b'n' => out.extend_from_slice(&(v.to_int() as u16).to_be_bytes()),
                        b'i' | b'I' | b'l' | b'L' | b'V' => out.extend_from_slice(&(v.to_int() as u32).to_le_bytes()),
                        b'N' => out.extend_from_slice(&(v.to_int() as u32).to_be_bytes()),
                        b'q' | b'Q' | b'P' => out.extend_from_slice(&(v.to_int() as u64).to_le_bytes()),
                        b'J' => out.extend_from_slice(&(v.to_int() as u64).to_be_bytes()),
                        b'f' | b'g' => out.extend_from_slice(&(v.to_float() as f32).to_le_bytes()),
                        b'G' => out.extend_from_slice(&(v.to_float() as f32).to_be_bytes()),
                        b'd' | b'e' => out.extend_from_slice(&v.to_float().to_le_bytes()),
                        b'E' => out.extend_from_slice(&v.to_float().to_be_bytes()),
                        _ => return Err(it.value_error(&format!("Type {}: unknown format code", c as char))),
                    }
                }
            }
        }
    }
    if ai < args.len() {
        it.warn(&format!("pack(): {} arguments unused", args.len() - ai))?;
    }
    Ok(Value::vec(out))
}

fn f_unpack(it: &mut Interp, a: &mut Args) -> R<Value> {
    let fmt = a.str(it, 0)?;
    let data = a.str(it, 1)?;
    let mut pos = a.int_or(it, 2, 0)?.max(0) as usize;
    let mut out = PArray::new();
    for part in fmt.split(|&c| c == b'/') {
        if part.is_empty() {
            continue;
        }
        let c = part[0];
        let mut i = 1;
        let cnt = parse_count(part, &mut i);
        let name = String::from_utf8_lossy(&part[i..]).to_string();
        let key = |idx: usize, total_many: bool| -> Key {
            if name.is_empty() {
                Key::Int(idx as i64 + 1)
            } else if total_many {
                Key::from_str_bytes(format!("{}{}", name, idx + 1).as_bytes())
            } else {
                Key::from_str_bytes(name.as_bytes())
            }
        };
        match c {
            b'a' | b'A' | b'Z' => {
                let n = match cnt {
                    None => 1,
                    Some(-1) => data.len().saturating_sub(pos),
                    Some(n) => n as usize,
                };
                if pos + n > data.len() {
                    it.warn(&format!("unpack(): Type {}: not enough input, need {}, have {}", c as char, n, data.len().saturating_sub(pos)))?;
                    return Ok(Value::Bool(false));
                }
                let mut s = data[pos..pos + n].to_vec();
                pos += n;
                match c {
                    b'A' => {
                        while s.last().map(|&x| x == b' ' || x == 0 || x == b'\t' || x == b'\r' || x == b'\n').unwrap_or(false) {
                            s.pop();
                        }
                    }
                    b'Z' => {
                        if let Some(p) = s.iter().position(|&x| x == 0) {
                            s.truncate(p);
                        }
                    }
                    _ => {}
                }
                out.set(key(0, false), Value::vec(s));
            }
            b'h' | b'H' => {
                let n = match cnt {
                    None => 1,
                    Some(-1) => (data.len() - pos) * 2,
                    Some(n) => n as usize,
                };
                let nbytes = (n + 1) / 2;
                if pos + nbytes > data.len() {
                    return Ok(Value::Bool(false));
                }
                let mut s = String::new();
                for k in 0..n {
                    let b = data[pos + k / 2];
                    let nib = if (k % 2 == 0) == (c == b'H') { b >> 4 } else { b & 15 };
                    s.push(std::char::from_digit(nib as u32, 16).unwrap());
                }
                pos += nbytes;
                out.set(key(0, false), Value::string(s));
            }
            b'x' => pos += cnt.unwrap_or(1).max(0) as usize,
            b'X' => pos = pos.saturating_sub(cnt.unwrap_or(1).max(0) as usize),
            b'@' => pos = cnt.unwrap_or(0).max(0) as usize,
            _ => {
                let size = match c {
                    b'c' | b'C' => 1,
                    b's' | b'S' | b'n' | b'v' => 2,
                    b'i' | b'I' | b'l' | b'L' | b'N' | b'V' | b'f' | b'g' | b'G' => 4,
                    b'q' | b'Q' | b'J' | b'P' | b'd' | b'e' | b'E' => 8,
                    _ => return Err(it.value_error(&format!("Type {}: unknown format code", c as char))),
                };
                let n = match cnt {
                    None => 1,
                    Some(-1) => (data.len().saturating_sub(pos)) / size,
                    Some(n) => n as usize,
                };
                let many = cnt.is_some();
                for k in 0..n {
                    if pos + size > data.len() {
                        it.warn(&format!("unpack(): Type {}: not enough input, need {}, have {}", c as char, size, data.len().saturating_sub(pos)))?;
                        return Ok(Value::Bool(false));
                    }
                    let b = &data[pos..pos + size];
                    pos += size;
                    let v = match c {
                        b'c' => Value::Int(b[0] as i8 as i64),
                        b'C' => Value::Int(b[0] as i64),
                        b's' => Value::Int(i16::from_le_bytes([b[0], b[1]]) as i64),
                        b'S' | b'v' => Value::Int(u16::from_le_bytes([b[0], b[1]]) as i64),
                        b'n' => Value::Int(u16::from_be_bytes([b[0], b[1]]) as i64),
                        b'i' | b'l' => Value::Int(i32::from_le_bytes([b[0], b[1], b[2], b[3]]) as i64),
                        b'I' | b'L' | b'V' => Value::Int(u32::from_le_bytes([b[0], b[1], b[2], b[3]]) as i64),
                        b'N' => Value::Int(u32::from_be_bytes([b[0], b[1], b[2], b[3]]) as i64),
                        b'q' | b'Q' | b'P' => Value::Int(i64::from_le_bytes([b[0], b[1], b[2], b[3], b[4], b[5], b[6], b[7]])),
                        b'J' => Value::Int(i64::from_be_bytes([b[0], b[1], b[2], b[3], b[4], b[5], b[6], b[7]])),
                        b'f' | b'g' => Value::Float(f32::from_le_bytes([b[0], b[1], b[2], b[3]]) as f64),
                        b'G' => Value::Float(f32::from_be_bytes([b[0], b[1], b[2], b[3]]) as f64),
                        b'd' | b'e' => Value::Float(f64::from_le_bytes([b[0], b[1], b[2], b[3], b[4], b[5], b[6], b[7]])),
                        _ => Value::Float(f64::from_be_bytes([b[0], b[1], b[2], b[3], b[4], b[5], b[6], b[7]])),
                    };
                    out.set(key(k, many && (n > 1 || cnt == Some(-1) || !name.is_empty() && cnt.is_some())), v);
                }
            }
        }
    }
    Ok(Value::arr(out))
}

fn f_ip2long(it: &mut Interp, a: &mut Args) -> R<Value> {
