fn f_quoted_printable_encode(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let mut out = Vec::new();
    let mut linelen = 0;
    let mut i = 0;
    while i < s.len() {
        let c = s[i];
        if c == b'\r' && i + 1 < s.len() && s[i + 1] == b'\n' {
            out.extend_from_slice(b"\r\n");
            i += 2;
            linelen = 0;
            continue;
        }
        let enc = c < 32 && c != b'\t' || c == b'=' || c >= 127 || ((c == b' ' || c == b'\t') && (i + 1 == s.len() || s[i + 1] == b'\r'));
        let piece: Vec<u8> = if enc { format!("={:02X}", c).into_bytes() } else { vec![c] };
        if linelen + piece.len() > 75 {
            out.extend_from_slice(b"=\r\n");
            linelen = 0;
        }
        linelen += piece.len();
        out.extend_from_slice(&piece);
        i += 1;
    }
    Ok(Value::vec(out))
}
fn f_quoted_printable_decode(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let mut out = Vec::new();
    let mut i = 0;
    while i < s.len() {
        if s[i] == b'=' {
            if i + 2 < s.len() + 1 && i + 2 <= s.len() - 1 + 1 && i + 2 < s.len() + 1 && i + 2 <= s.len() && i + 1 < s.len() && s[i + 1].is_ascii_hexdigit() && i + 2 < s.len() && s[i + 2].is_ascii_hexdigit() {
                out.push(u8::from_str_radix(&String::from_utf8_lossy(&s[i + 1..i + 3]), 16).unwrap());
                i += 3;
                continue;
            }
            // soft line break
            let mut j = i + 1;
            while j < s.len() && (s[j] == b' ' || s[j] == b'\t') {
                j += 1;
            }
            if j < s.len() && s[j] == b'\r' {
                j += 1;
            }
            if j < s.len() && s[j] == b'\n' {
                i = j + 1;
                continue;
            }
        }
        out.push(s[i]);
        i += 1;
    }
    Ok(Value::vec(out))
}
