fn f_parse_ini_string(it: &mut Interp, a: &mut Args) -> R<Value> {
    let s = a.str(it, 0)?;
    let sections = a.bool_or(it, 1, false)?;
    let mode = a.int_or(it, 2, 0)?;
    let mut out = PArray::new();
    let mut cur_section: Option<Vec<u8>> = None;
    let mut sec_arr = PArray::new();
    let conv = |v: &str, mode: i64| -> Value {
        let t = v.trim();
        if (t.starts_with('"') && t.ends_with('"') && t.len() >= 2) || (t.starts_with('\'') && t.ends_with('\'') && t.len() >= 2) {
            return Value::str(&t[1..t.len() - 1]);
        }
        if mode == 1 {
            return Value::str(t);
        }
        match t.to_ascii_lowercase().as_str() {
            "true" | "on" | "yes" => {
                if mode == 2 {
                    Value::Bool(true)
                } else {
                    Value::str("1")
                }
            }
            "false" | "off" | "no" | "none" => {
                if mode == 2 {
                    Value::Bool(false)
                } else {
                    Value::str("")
                }
            }
            "null" => {
                if mode == 2 {
                    Value::Null
                } else {
                    Value::str("")
                }
            }
            _ => {
                if mode == 2 {
                    if let Ok(i) = t.parse::<i64>() {
                        return Value::Int(i);
                    }
                    if let Ok(f) = t.parse::<f64>() {
                        return Value::Float(f);
                    }
                }
                Value::str(t)
            }
        }
    };
    let text = String::from_utf8_lossy(&s).to_string();
    for line in text.lines() {
        let l = line.trim();
        if l.is_empty() || l.starts_with(';') || l.starts_with('#') {
            continue;
        }
        if l.starts_with('[') && l.ends_with(']') {
            if sections {
                if let Some(sn) = cur_section.take() {
                    out.set(Key::from_str_bytes(&sn), Value::arr(std::mem::take(&mut sec_arr)));
                }
                cur_section = Some(l[1..l.len() - 1].as_bytes().to_vec());
            }
            continue;
        }
        if let Some((k, v)) = l.split_once('=') {
            let k = k.trim();
            let v = v.split(" ;").next().unwrap_or(v);
            let val = conv(v, mode);
            let target = if sections && cur_section.is_some() { &mut sec_arr } else { &mut out };
            if let Some(base) = k.strip_suffix("[]") {
                let e = target.entry_mut(Key::from_str_bytes(base.as_bytes()));
                if !matches!(e, Value::Array(_)) {
                    *e = Value::empty_array();
                }
                if let Value::Array(ar) = e {
                    Rc::make_mut(ar).push(val);
                }
            } else {
                target.set(Key::from_str_bytes(k.as_bytes()), val);
            }
        }
    }
    if let Some(sn) = cur_section.take() {
        out.set(Key::from_str_bytes(&sn), Value::arr(sec_arr));
    }
    Ok(Value::arr(out))
}
fn f_parse_ini_file(it: &mut Interp, a: &mut Args) -> R<Value> {
