s = s[:start] + r'''// range input kinds: 1 long, 2 double, 3 string, 4 array(single digit string)
fn range_input(it: &mut Interp, a: &Args, i: usize) -> R<(u8, i64, f64, Vec<u8>)> {
    let v = a.get(i);
    let name = if i == 0 { "start" } else { "end" };
    match v {
        Value::Int(n) => Ok((1, n, n as f64, vec![])),
        Value::Bool(b) => Ok((1, b as i64, b as i64 as f64, vec![])),
        Value::Null => {
            it.deprecated(&format!("range(): Passing null to parameter #{} (${}) of type string|int|float is deprecated", i + 1, name))?;
            Ok((1, 0, 0.0, vec![]))
        }
        Value::Float(f) => {
            if f.is_infinite() {
                return Err(a.value_err(it, i, "must be a finite number, INF provided"));
            }
            if f.is_nan() {
                return Err(a.value_err(it, i, "must be a finite number, NAN provided"));
            }
            Ok((2, 0, f, vec![]))
        }
        Value::Str(s) => {
            if s.is_empty() {
                it.warn(&format!("range(): Argument #{} (${}) must not be empty, casted to 0", i + 1, name))?;
                return Ok((1, 0, 0.0, vec![]));
            }
            match str_numeric(&s) {
                Some(Num::Float(f)) => {
                    if f.is_infinite() {
                        return Err(a.value_err(it, i, "must be a finite number, INF provided"));
                    }
                    Ok((2, 0, f, vec![]))
                }
                Some(Num::Int(n)) => Ok((if s.len() == 1 { 4 } else { 1 }, n, n as f64, s.to_vec())),
                None => {
                    if s.len() != 1 {
                        it.warn(&format!("range(): Argument #{} (${}) must be a single byte, subsequent bytes are ignored", i + 1, name))?;
                    }
                    Ok((3, 0, 0.0, s.to_vec()))
                }
            }
        }
        _ => Err(a.arg_err(it, i, "string|int|float")),
    }
}

fn f_range(it: &mut Interp, a: &mut Args) -> R<Value> {
    let mut is_step_double = false;
    let mut is_step_negative = false;
    let mut step_double = 1.0f64;
    let mut step: i64 = 1;
    if a.has(2) {
        match a.get(2) {
            Value::Float(f) => {
                step_double = f;
                if step_double < 0.0 {
                    is_step_negative = true;
                    step_double = -step_double;
                }
                step = float_to_int(step_double);
                if !(step_double.is_finite() && (step as f64) == step_double) {
                    is_step_double = true;
                }
            }
            _ => {
                let n = a.num(it, 2)?;
                match n {
                    Num::Float(f) => {
                        step_double = f.abs();
                        is_step_negative = f < 0.0;
                        step = float_to_int(step_double);
                        if (step as f64) != step_double {
                            is_step_double = true;
                        }
                    }
                    Num::Int(i) => {
                        step = i;
                        if step < 0 {
                            if step == i64::MIN {
                                return Err(a.value_err(it, 2, &format!("must be greater than {}", step)));
                            }
                            is_step_negative = true;
                            step = -step;
                        }
                        step_double = step as f64;
                    }
                }
            }
        }
        if step_double == 0.0 {
            return Err(a.value_err(it, 2, "cannot be 0"));
        }
    }
    let (mut st, sl, mut sd, sbytes) = range_input(it, a, 0)?;
    let (mut et, el, mut ed, ebytes) = range_input(it, a, 1)?;
    let mut out = PArray::new();
    let boundary = |it: &mut Interp, a: &Args| a.value_err(it, 2, "must not exceed the specified range");
    let neg_err = |it: &mut Interp, a: &Args| a.value_err(it, 2, "must be greater than 0 for increasing ranges");
    let (mut sl, mut el) = (sl, el);
    if st >= 3 || et >= 3 {
        let mut numeric = false;
        if st < 3 || et < 3 {
            if st < 3 {
                if et != 4 {
                    it.warn("range(): Argument #2 ($end) must be a single byte string if argument #1 ($start) is a single byte string, argument #2 ($end) converted to 0")?;
                }
                if et == 3 {
                    el = 0;
                    ed = 0.0;
                }
                et = 1;
            } else {
                if st != 4 {
                    it.warn("range(): Argument #1 ($start) must be a single byte string if argument #2 ($end) is a single byte string, argument #1 ($start) converted to 0")?;
                }
                if st == 3 {
                    sl = 0;
                    sd = 0.0;
                }
                st = 1;
            }
            numeric = true;
        } else if is_step_double {
            if st == 3 || et == 3 {
                it.warn("range(): Argument #3 ($step) must be of type int when generating an array of characters, inputs converted to 0")?;
            }
            if st == 3 {
                sl = 0;
                sd = 0.0;
            }
            if et == 3 {
                el = 0;
                ed = 0.0;
            }
            st = 1;
            et = 1;
            numeric = true;
        }
        if !numeric {
            let mut low = sbytes[0] as i64;
            let high = ebytes[0] as i64;
            if low > high {
                if low - high < step {
                    return Err(boundary(it, a));
                }
                while low >= high {
                    out.push(Value::vec(vec![low as u8]));
                    if low - step < 0 {
                        break;
                    }
                    low -= step;
                }
            } else if high > low {
                if is_step_negative {
                    return Err(neg_err(it, a));
                }
                if high - low < step {
                    return Err(boundary(it, a));
                }
                while low <= high {
                    out.push(Value::vec(vec![low as u8]));
                    if low + step > 255 {
                        break;
                    }
                    low += step;
                }
            } else {
                out.push(Value::vec(vec![low as u8]));
            }
            return Ok(Value::arr(out));
        }
    }
    if st == 4 {
        st = 1;
    }
    if et == 4 {
        et = 1;
    }
    if st == 2 || et == 2 || is_step_double {
        if st == 1 {
            sd = sl as f64;
        }
        if et == 1 {
            ed = el as f64;
        }
        if sd > ed {
            if sd - ed < step_double {
                return Err(boundary(it, a));
            }
            let size = ((sd - ed) / step_double + 1.0).round() as u64;
            if size >= (1 << 31) {
                return Err(it.value_error(&format!("The supplied range exceeds the maximum array size: start={:.1} end={:.1} step={:.1}", sd, ed, step_double)));
            }
            let mut i = 0u64;
            let mut el2 = sd;
            while i < size && el2 >= ed {
                out.push(Value::Float(el2));
                i += 1;
                el2 = sd - i as f64 * step_double;
            }
        } else if ed > sd {
            if is_step_negative {
                return Err(neg_err(it, a));
            }
            if ed - sd < step_double {
                return Err(boundary(it, a));
            }
            let size = ((ed - sd) / step_double + 1.0).round() as u64;
            if size >= (1 << 31) {
                return Err(it.value_error(&format!("The supplied range exceeds the maximum array size: start={:.1} end={:.1} step={:.1}", sd, ed, step_double)));
            }
            let mut i = 0u64;
            let mut el2 = sd;
            while i < size && el2 <= ed {
                out.push(Value::Float(el2));
                i += 1;
                el2 = sd + i as f64 * step_double;
            }
        } else {
            out.push(Value::Float(sd));
        }
        return Ok(Value::arr(out));
    }
    let ustep = step as u64;
    if sl > el {
        if (sl as u64).wrapping_sub(el as u64) < ustep {
            return Err(boundary(it, a));
        }
        let size = (sl as u64).wrapping_sub(el as u64) / ustep + 1;
        if size >= (1 << 31) {
            return Err(it.value_error(&format!("The supplied range exceeds the maximum array size: start={} end={} step={}", sl, el, step)));
        }
        it.check_alloc(size as usize * 16)?;
        for i in 0..size {
            out.push(Value::Int((sl as u64).wrapping_sub(i * ustep) as i64));
        }
    } else if el > sl {
        if is_step_negative {
            return Err(neg_err(it, a));
        }
        if (el as u64).wrapping_sub(sl as u64) < ustep {
            return Err(boundary(it, a));
        }
        let size = (el as u64).wrapping_sub(sl as u64) / ustep + 1;
        if size >= (1 << 31) {
            return Err(it.value_error(&format!("The supplied range exceeds the maximum array size: start={} end={} step={}", sl, el, step)));
        }
        it.check_alloc(size as usize * 16)?;
        for i in 0..size {
            out.push(Value::Int((sl as u64).wrapping_add(i * ustep) as i64));
        }
    } else {
        out.push(Value::Int(sl));
    }
    Ok(Value::arr(out))
}
